do local function f(R)
R(1,"The \"Chow\" Quest (123)aa",[[description="$Tpunk;!  Kill Kobold Vermin, 2 of em. NEW TEST AGAIN",objectives={"Kill Kobold Vermin, 2 of em."}]])
R(2,"Klaue von Scharfkralle",[[description="Der mächtige Hippogryph Scharfkralle wurde getötet und die Klaue der erschlagenen Bestie dient als Beweis für Euren Sieg. Senani Thunderheart im Splintertreeposten wird zum Beweis Eurer Tat sicher gern diese Trophäe sehen wollen.",objectives={"Bringt die Klaue von Scharfkralle zu Senani Thunderheart im Splintertreeposten in Ashenvale."}]])
R(5,"Jitters' knurrender Magen",[[description="Ich verstecke mich jetzt schon seit Wochen in dieser Geisterstadt, und die ganze Zeit habe ich nichts gegessen außer Maden und Unkraut! Ich brauche was Anständiges zum Essen, und ich werde mich nicht lumpen lassen.$B$BBringt mir ein Festessen, und ich bezahle Euch gut dafür.$B$BIch habe gehört, dass Küchenchef Grual aus der Taverne Zum roten Raben in Dunkelhain ganz ausgezeichnete schwärzliche Krebsküchlein macht...",objectives={"Sprecht mit Küchenchef Grual."}]])
R(6,"Kopfgeld auf Garrick Padfoot",[[description="Garrick Padfoot, ein Dieb und Halsabschneider, der schon seit Wochen unseren Bauern und Händlern das Leben schwer macht, ist bei einem Schuppen in der Nähe der Weinberge gesehen worden. Die Weinberge liegen im Osten der Abtei, auf der anderen Seite der Brücke. Bringt mir den Kopf des Schurken und verdient Euch das Kopfgeld, das auf ihn ausgesetzt ist!$B$BDoch seht Euch vor, $N. Garrick hat eine Bande von Rohlingen um sich versammelt, also werdet Ihr nicht leicht an ihn herankommen.",objectives={"Tötet Garrick Padfoot und bringt seinen Kopf zu Deputy Willem in der Nähe der Abtei von Nordhain."}]])
R(7,"Säuberung im Koboldlager",[[description="Eure erste Aufgabe ist eine Säuberung, $n. Ein Koboldklan hat sich in den Wäldern im Norden eingenistet. Begebt Euch dorthin und bekämpft das Koboldgezücht, das Ihr dort finden werdet. Dezimiert es, damit wir die Kobolde eines Tages gänzlich aus Nordhain vertreiben können.",objectives={"Tötet 10 von dem Koboldgezücht und kehrt dann zu Marshal McBride zurück."}]])
R(8,"Ein Schurkenhandel",[[description="Heda, Kamerad! Wollt Ihr nicht einem jungen Mann, der mehr als seinen Teil an hirnlosen Zombies und Spinnen umgelegt hat, einen Gefallen tun?$B$BIch hab hier einen Brief, der muss nach Brill... zu so einer Gastwirtin namens Renee Irgendwas. Ist eigentlich völlig egal, wie sie mit Nachnamen heißt.$B$BNa egal, jedenfalls ist es ein netter kleiner Ort, wo lauter Opfer der Seuche wohnen, die versuchen, sich irgendwie durchs Leben zu schlagen. Und es wäre ein toller Ort für Euch, an dem Ihr Euch ausruhen könnt, falls das mal nötig wird. Ihr solltet Euch den wirklich mal anseh'n - macht es, und ich bezahl Euch auch noch gut dafür.",objectives={"Liefert den unscheinbaren Brief bei Gastwirtin Renee in Tirisfal ab."}]])
R(9,"Tod auf den Feldern",[[description="Jetzt seht Euch nur an, was aus diesem Ort geworden ist! In dieser Gegend lebten einst ehrbare Bauersleute. Die verdammten Diebe haben sie alle vertrieben. Aber mich nicht! Jetzt sieht es allerdings so aus, als hätten einige Erntebehüter sich in den Feldern breit gemacht.$b$bWenn Ihr Euch dem gewachsen fühlt, dann geht hinaus und tötet dort draußen 20 von ihnen. Wenn Ihr fertig seid, kommt zurück und holt Euch Eure Bezahlung ab. Und wenn Ihr alle in meinem Feld erwischt habt, dann räumt auch in den angrenzenden Feldern auf.",objectives={"Bauer Saldean möchte, dass Ihr 20 Erntebehüter tötet."}]])
R(10,"Die Erlösung von Scrimshank",[[description="Oh, das ist einfach schrecklich! Ich habe meinen besten Gehilfen, Unterfeldmesser Scrimshank, in die Wüste südöstlich von hier geschickt. Das ist ein Gebiet, das wir die Klaffende Schlucht nennen. Nun ja, er wird vermisst und in seinem letzten Bericht sprach er davon, dass es dort, wo er war, noch mehr dieser komischen Viecher gäbe. Könnte es sein, dass sie sich jetzt in zwei großen Gebieten der Wüste eingenistet haben?$B$BBegebt Euch bitte für mich zur Klaffenden Schlucht und sucht nach Scrimshank! Das... oder findet wenigstens seine Feldmesserausrüstung. Ich fürchte, das ist alles, was von dem Armen übrig geblieben ist.",objectives={"Erforscht das Schicksal von Unterfeldmesser Scrimshank und bringt entweder ihn oder seine Feldmesserausrüstung nach Gadgetzan zum Leitenden Feldmesser Fizzledowser."}]])
R(11,"Kopfgeld auf die Flusspfotengnolle",[[description="Gnolle, brutale Wesen, die in dieser Gegend nichts zu suchen haben, sind entlang der Grenzen des Waldes von Elwynn gesehen worden. Ein großes Rudel, viel zu viele, als dass wir allein mit ihnen fertig werden könnten, hat sich in den Wäldern südlich von jenem Wachturm dort eingenistet. Eine weitere Gruppe hat sich im Gebiet nahe des Steinhügelsees im Osten eingenistet.$B$BDie Armee von Stormwind wird jeden belobigen, der dabei hilft, die Gnolle zu töten. Bringt mir ihre bemalten Gnoll-Armbinden als Beweis für Eure Tat.",objectives={"Bringt Deputy Rainer in der Kaserne 8 bemalte Gnoll-Armbinden."}]])
R(12,"Die Volksmiliz",[[description="Die Volksmiliz hat nur ein einziges Ziel: Westfall zu verteidigen und den Frieden in dieses Land zurückzubringen. Doch leider muss der Frieden nur allzu oft mit Blut bezahlt werden. $b$bEiner meiner Späher hat uns Kunde davon gebracht, dass eine Fallenstellerbande der Defias hier in der Nähe verheerende Schäden anrichtet. Mir liegen Berichte vor, dass einige Fallensteller der Defias in der Nähe des Jangoschachts im Nordwesten gesichtet wurden, ebenso bei Molsens Hof und bei Furlbrows Kürbishof. Wenn Ihr unseren Reihen beizutreten wünscht, dann erschlagt 15 Fallensteller der Defias und 15 Schmuggler der Defias und kehrt zu mir zurück.",objectives={"Gryan Stoutmantle möchte, dass Ihr 15 Fallensteller der Defias und 15 Schmuggler der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt."}]])
R(13,"Die Volksmiliz",[[description="Eine Bande heimtückischer Plünderer der Defias ist dabei gesehen worden, wie sie den Goldküstensteinbruch, Moonbrook und Alexstons Bauernhof ausplünderten. Die Volksmiliz kann ein solches Verhalten nicht hinnehmen. Macht Euch unverzüglich auf den Weg, $N, und zeigt, dass das Licht in Westfall zugegen ist.$b$bDer Goldküstensteinbruch befindet sich in der Nähe der Küste, westlich vom Turm. Im nächsten Schritt Eurer Ausbildung müsst Ihr 15 dieser üblen Plünderer der Defias und 15 Ausplünderer der Defias töten.",objectives={"Gryan Stoutmantle möchte, dass Ihr 15 Plünderer der Defias und 15 Ausplünderer der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt."}]])
R(14,"Die Volksmiliz",[[description="Einige Defias konnten wir bislang nicht erwischen. Mein bester Späher berichtet, dass diese Defias in der ganzen Gegend auf Raubzug gehen und schon bis Süd-Westfall gekommen sind. Wir glauben, dass sie sich in den Dolchhügeln versteckt halten und dort ihren nächsten Schachzug planen. Schaltet diese Verbrecher im Namen der Volksmiliz aus.",objectives={"Gryan Stoutmantle möchte, dass Ihr 15 Straßenräuber der Defias, 5 Pfadpirscher der Defias und 5 Knöchelhauer der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt."}]])
R(15,"Überprüfung der Echokammmine",[[description="Wie mir meine Späher mitteilen, ist das Koboldproblem größer als wir dachten, $N. Eine Gruppe Koboldtagelöhner hat ihr Lager in der Nähe der Echokammmine im Norden aufgeschlagen.$B$BBegebt Euch zu der Mine und entfernt die Kobolde. Wir wissen, dass sich mindestens 10 von ihnen dort aufhalten. Tötet sie, seht nach, ob dort noch mehr von ihnen sind, kommt dann zu mir zurück und erstattet Bericht.",objectives={"Tötet 10 Koboldtagelöhner und erstattet dann Marshal McBride Euren Bericht."}]])
R(16,"Etwas zu trinken für Gerard")
R(17,"Reagenzsuche in Uldaman",[[description="Ich habe von einer neu entdeckten Pflanze gehört, den magenta Funguskappen. Sie wachsen in Büscheln tief drinnen in der Uldaman-Grabungsstätte; vielleicht kann man sie auch anderswo finden, aber bisher ist das der einzige mir bekannte Ort, an dem sie gedeihen. Ich möchte ihren potenziellen Nutzen für die Alchimie erforschen und dafür brauche ich Euch.$B$BFindet die magenta Funguskappen-Büschel und bringt mir ein Dutzend Kappen. Aber seid gewarnt - die Pflanzen stoßen vielleicht Giftsporen aus, wenn man sie anstößt.$B$BWenn Ihr das für mich tut, dann braue ich Euch einen Schwung von meinem berühmten Regenerierungselixier!",objectives={"Bringt zwölf magenta Funguskappen nach Thelsamar zu Ghak Healtouch."}]])
R(18,"Bruderschaft der Diebe",[[description="Seit kurzem treibt sich eine neue Diebesbande in Nordhain herum. Sie nennen sich die \"Bruderschaft der Defias\" und sind auf der anderen Seite des Flusses im Osten gesehen worden.$B$BIch weiß nicht genau, was sie vorhaben, aber ich bin mir sicher, es ist nichts Gutes! Bringt mir die Kopftücher, die sie tragen, und ich werde Euch mit einer Waffe belohnen.",objectives={"Bringt 12 rote Sackleinenkopftücher zu Deputy Willem in der Nähe der Abtei von Nordhain."}]])
R(19,"Tharil'zun",[[description="Zwischen hier und Burg Steinwacht legen Kundschafter und Renegaten der Blackrock ständig Hinterhalte. Der Anführer der Kundschafter heißt Tharil'zun und diesen Orc wollen wir haben. Bringt mir den Kopf von Tharil'zun!",objectives={"Bringt den Kopf von Tharil'zun ins Rotkammgebirge zu Marshal Marris."}]])
R(20,"Bedrohung durch die Blackrock",[[description="Die Orcs des Blackrockklans haben die brennende Steppe verlassen und Burg Steinwacht im Norden besetzt. Von dort aus ziehen sie marodierend durch das Gebiet nördlich von Seenhain, so dass dessen Bewohner sich nicht mehr aus der Stadt wagen und dort eingesperrt sind wie Vieh in einem zu engen Pferch.$B$BHelft uns, diese Bedrohung von Seenhain zu nehmen! Tötet diese Orcs der Blackrock und bringt mir 10 ihrer kampferprobten Äxte zum Beweis.$B$BUnd obwohl die Blackrocks uns vor allem aus dem Norden bedrohen, haben wir auch gehört, dass sich noch weitere in der südöstlichen Ecke des Rotkammgebirges aufhalten. Wenn Ihr dort welche findet, solltet Ihr die auch jagen.",objectives={"Bringt 10 kampferprobte Äxte nach Seenhain zu Marshal Marris."}]])
R(21,"Scharmützel in der Echokammmine",[[description="Eure Untersuchungen beweisen, dass die Echokammmine gesäubert werden muss. Kehrt in die Mine zurück und helft dabei, sie von den Kobolden zu befreien.$B$BIhr dürft keine Zeit verlieren, $n. Je länger die Kobolde sich ungehindert in der Mine aufhalten können, umso festere Wurzeln fassen sie in Nordhain.",objectives={"Tötet 12 Koboldhilfsarbeiter und kehrt dann zu Marshal McBride in der Abtei von Nordhain zurück."}]])
R(22,"Pastete aus Geiferzahnleber",[[description="Die Zwiebeln sind geschält, der Knoblauch ist gehackt, der Rosmarin ist zerstoßen, die Kruste ist gebacken, das Dillkraut ist gewiegt und die Sauce steht auf dem Herd. Jetzt brauche ich für meine berühmte Fleischpastete nur noch 8 Geiferzahnlebern!",objectives={"Salma Saldean braucht 8 Geiferzahnlebern für ihre Pastete aus Geiferzahnleber."}]])
R(23,"Ursangus' Tatze",[[description="Die Tatze des mächtigen Bären Ursangus stellt die Trophäe für diesen Teil der Jagd in Ashenvale dar. Auf der Tatze befindet sich ein kleines Halbmond-Emblem; die Bedeutung dieses Emblems bleibt jedoch ein Geheimnis.$B$BDie Tatze soll zu Senani Thunderheart im Splintertreeposten gebracht werden, um zu beweisen, dass Ihr das mächtige Tier besiegt und diesen Teil der Jagd abgeschlossen habt.",objectives={"Bringt Ursangus' Tatze zu Senani Thunderheart im Splintertreeposten in Ashenvale."}]])
R(24,"Schattumbras Kopf",[[description="Der einstmals so flinke Schattumbra liegt jetzt regungslos vor Euch und der Sieg ist Euer. Der Kopf des erschlagenen Nachtsäblers ist eine passende Trophäe für diesen Kampf. Senani Thunderheart im Splintertreeposten wird eine solche Trophäe sehen wollen, um Euch den Erfolg in diesem Teil der Jagd in Ashenvale anzurechnen.",objectives={"Bringt Schattumbras Kopf zu Senani Thunderheart im Splintertreeposten in Ashenvale."}]])
R(25,"Stillstand am Steinkrallenpfad",[[description="Wenn Ihr Euch nützlich machen wollt, warum unternehmt Ihr dann nicht etwas wegen der Situation am Steinkrallenpfad?$B$BDer Güterverkehr zwischen Ashenvale und dem Steinkrallengebirge steht still, weil der See zum Leben erwacht ist und alles angreift, was ihm zu nahe kommt... und das bedeutet, jeden auf dem Pfad. Noch weitaus nützlicher als einfach nur die Wasserelementare zu unterjochen, wäre es, wenn jemand den Pavillon auf dem Mystralsee auskundschaften würde... der, von dem aus man einen guten Blick auf den dortigen Außenposten der Allianz hat.$B$BNa, wollt Ihr Euch nützlich machen?",objectives={"Erledigt 12 beschmutzte Wasserelementare am Mystralsee östlich vom Steinkrallenpfad und südwestlich vom Splintertreeposten.$B$BErkundet den Pavillon am Mystralsee, der den nahen Außenposten der Allianz überblickt.$B$BKehrt zu Mastok Wrilehiss im Splintertreeposten in Ashenvale zurück."}]])
R(26,"Eine wertvolle Lektion",[[description="$N, ich habe Euren Fortschritt mit großem Genuss verfolgt. Ihr entwickelt Euch definitiv zu einem wertvollen Beschützer der Natur.$B$BEs ist an der Zeit für Euch, mehr über einen der diversen Tieraspekte zu lernen, in die wir uns dank Cenarius' Segen verwandeln können... einen, der Euch die Beherrschung des Wassers ermöglicht. Dazu müsst Ihr zum Dorf Nighthaven in Moonglade reisen und mit Dendrite Starblaze vom Zirkel des Cenarius sprechen. Er wird Euch weiter anleiten.",objectives={"Sprecht mit Dendrite Starblaze im Dorf Nighthaven in Moonglade."}]])
R(27,"Eine wertvolle Lektion",[[description="$N, ich habe Euren Fortschritt mit großem Genuss verfolgt. Ihr entwickelt Euch definitiv zu einem wertvollen Beschützer der Natur.$B$BEs ist an der Zeit für Euch, mehr über einen der diversen Tieraspekte zu lernen, in die wir uns dank Cenarius' Segen verwandeln können... einen, der Euch die Beherrschung des Wassers ermöglicht. Dazu müsst Ihr zum Dorf Nighthaven in Moonglade reisen und mit Dendrite Starblaze vom Zirkel des Cenarius sprechen. Er wird Euch weiter anleiten.",objectives={"Sprecht mit Dendrite Starblaze im Dorf Nighthaven in Moonglade."}]])
R(28,"Prüfung des Sees",[[description="Als Eure erste Prüfung müsst Ihr in den Tiefen des Elune'ara Sees nach einem Schreinschmuckstück suchen. Es zerfällt schnell, daher solltet Ihr Euch mit größter Eile zum Schrein von Remulos begeben. Benutzt das Schmuckstück am Schrein und sprecht dann dort mit Tajarri; sie ist eine der vertrauenswürdigsten Aufseherinnen von Moonglade.$B$BIhr habt nur eine gewisse Zeitspanne für diese Aufgabe zur Verfügung, und Ihr könntet in Konkurrenz zu anderen Druiden stehen, die ebenfalls nach Schmuckstücken suchen. Geistiges wie körperliches Geschick wird für Euren Erfolg unabdingbar sein.$B$BViel Glück, $N.",objectives={"Sucht ein Schreinschmuckstück im Elune'ara See und bringt es zum Schrein von Remulos im Nordwesten von Moonglade. Wenn Ihr dort seid, benutzt das Schrein-Schmuckstück.$B$BIhr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen."}]])
R(29,"Prüfung des Sees",[[description="Als Eure erste Prüfung müsst Ihr in den Tiefen des Elune'ara Sees nach einem Schreinschmuckstück suchen. Es zerfällt schnell, daher solltet Ihr Euch mit größter Eile zum Schrein von Remulos begeben. Benutzt das Schmuckstück am Schrein und sprecht dann dort mit Tajarri; sie ist eine der vertrauenswürdigsten Aufseherinnen von Moonglade.$B$BIhr habt nur eine gewisse Zeitspanne für diese Aufgabe zur Verfügung, und Ihr könntet in Konkurrenz zu anderen Druiden stehen, die ebenfalls nach Schmuckstücken suchen. Geistiges wie körperliches Geschick wird für Euren Erfolg unabdingbar sein.$B$BViel Glück, $N.",objectives={"Sucht ein Schreinschmuckstück im Elune'ara See und bringt es zum Schrein von Remulos im Nordwesten von Moonglade. Wenn Ihr dort seid, benutzt das Schrein-Schmuckstück.$B$BIhr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen."}]])
R(30,"Prüfung des Seelöwen",[[description="Für die zweite Prüfung benötigt Ihr die zwei Hälften, aus denen der Anhänger des Seelöwen besteht. Die eine Hälfte bezieht ihre Kraft aus der Beweglichkeit des Seelöwen-Aspektes beim Gleiten durchs Wasser; die andere Hälfte bezieht ihre Kraft aus der unglaublichen Ausdauer des Seelöwen-Aspektes. Druiden bedienen sich dieser beiden Eigenschaften gleichermaßen, um den Aspekt ihrer Wassergestalt zu verkörpern.$B$BSprecht mit den Bewohnern von Moonglade, um herauszufinden, wo sich die Teile befinden könnten, und bringt beide hierher, um sie miteinander zu vereinen. Bringt den Anhänger zu Dendrite Starblaze, wenn Ihr ihn geschaffen habt.",objectives={"Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserausdauer. Sprecht mit den Einwohnern von Moonglade, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.$B$BFormt den Anhänger des Seelöwen aus den beiden Anhängerhälften. Ihr müsst in der unmittelbaren Nähe des Schreins von Remulos sein, um dies zu tun.$B$BBringt den zusammengefügten Anhänger zu Dendrite Starblaze nach Nighthaven in Moonglade."}]])
R(31,"Wassergestalt",[[description="Ihr habt die notwendigen Lektionen gemeistert, die alle jungen Druiden lernen, bevor sie einen Wasseraspekt annehmen können. Kehrt jetzt zu Eurem Lehrer Turak Runetotem nach Thunder Bluff zurück. Zeigt ihm Euren Anhänger und beweist ihm damit, dass Ihr bereit seid zu lernen, was er Euch lehren kann. Er wird Eure Ausbildung abschließen und Euch ermöglichen, eins mit dem Wasser zu werden.$B$BAuf Wiedersehen. Wir werden uns wieder sprechen.",objectives={"Kehrt nach Thunder Bluff zurück und zeigt Turak Runetotem den Anhänger des Seelöwen."}]])
R(32,"Aufstieg der Silithid",[[description="Hier ist Euer Bericht. Ihr solltet damit zu jemandem gehen, der ausreichend Kenntnis von solchen Dingen hat.$B$BIch kenne da einen Troll-Gelehrten mit Namen Zilzibin Drumlore. Er hat viel Zeit mit dem Studium der Lebensformen verbracht, die in der Ökologie von Azeroth einzigartig sind, und er ist noch dazu Historiker! Wenn Euch jemand helfen soll herauszufinden, was genau diese Bedrohung ausmacht, und wie sie zu stoppen ist, gebt ihm diesen Bericht. Hilfe können wir gar nicht genug haben.$B$BZil lebt in einem Haus auf der zweiten Ebene der Gasse in Orgrimmar.",objectives={"Bringt den Bericht nach Orgrimmar zu Zilzibin Drumlore."}]])
R(33,"Wölfe an der Grenze",[[description="Ich hasse diese grässlichen Waldwölfe! Aber Wolfsteaks esse ich für mein Leben gern. Bringt mir zähes Wolfsfleisch, dann gebe ich Euch etwas dafür, das Euch von Nutzen sein wird.$B$BZähes Wolfsfleisch bekommt Ihr, wenn Ihr die Waldwölfe und jungen Wölfe jagt, die in Nordhain durch das Land streifen.",objectives={"Bringt Eagan Peltskinner, den Ihr vor der Abtei von Nordshire findet, 8 Stücke zähes Wolfsfleisch."}]])
R(34,"Ein ungebetener Gast",[[description="Mein Garten ist schon wieder zertrampelt und verwüstet worden. Und ich weiß genau, was für ein Tier das getan hat. Das war dieser elende Eber, der, den Marshal Marris seit einer Weile immer \"Stopfwanst\" nennt.$b$bJetzt kann ich die Narzissen erst nächsten Herbst wieder anpflanzen. Hin! Alle hin, und das nur wegen diesem einen gefährlichen Eber. Bereitet dieser Plage ein Ende! Zeigt mir seinen Hauer und ich werde Euch nur zu gern belohnen. Die meiste Zeit scheint er damit zu verbringen, in den Feldern südwestlich von Seenhain nach Futter zu suchen, doch gelegentlich verirrt er sich auch hierher und in meinen Garten.",objectives={"Martie Jainrose aus Seenhain möchte, dass Ihr Stopfwanst tötet. Bringt ihr den Hauer des Ebers zum Beweis."}]])
R(35,"Weitere Sorgen",[[description="Falls Ihr befürchtet, dass die Gerüchte über das Auftauchen von Murlocs wahr sein könnten, dann tut das Folgende: Begebt Euch zur östlichen Elwynn-Brücke und sprecht mit Wache Thomas. Er ist seit einer Woche an der Brücke stationiert und wird deswegen wissen, wie es in der Gegend aussieht.$B$BBringt mir seinen Bericht.",objectives={"Marshal Dughan möchte, dass Ihr mit Wache Thomas sprecht."}]])
R(36,"Westfall-Eintopf",[[description="Ich hätte nie gedacht, dass jemals der Tag kommen würde, an dem ich den Hof verlasse. Aber in den Feldern wimmelt es nur so von Dieben und es ist hier für uns viel zu gefährlich geworden. Sobald Bauer Furlbrow den Wagen repariert hat, machen wir uns auf den Weg. $b $bKönntet Ihr mir vielleicht einen Gefallen tun? Ich schreibe Euch schnell mein Rezept für Westfall-Eintopf auf. Seid so nett und bringt es Salma Saldean; sie wohnt auf dem Hof dort hinten. Ihr findet den Hof der Saldeans gleich hinter der Gabelung der Straße.",objectives={"Verna Furlbrow möchte, dass Ihr ihr Rezept für Westfall-Eintopf bei Salma Saldean abliefert."}]])
R(37,"Suche nach den vermissten Wachen",[[description="Vor ein paar Tagen haben wir zwei Wachen, Rolf und Malakai, losgeschickt, damit sie entlang des Flusses Nachforschungen anstellen, aber bisher sind sie noch nicht zurückgekehrt. Damit ich meinen Bericht fertig schreiben kann, muss ich wissen, was den beiden Männern zugestoßen ist.$B$BSucht den Fluss in Richtung Norden ab und seht zu, dass Ihr die Wachen findet... oder ihre Überreste...",objectives={"Wache Thomas möchte, dass Ihr den Fluss in Richtung Norden nach Rolf und Malakai, den beiden vermissten Wachen, absucht."}]])
R(38,"Westfall-Eintopf",[[description="Wollt Ihr mir dabei helfen, Westfall-Eintopf zu kochen? Dann bringt mir die folgenden Zutaten: $b $b 3 Stücke sehniges Geierfleisch $b 3 Geiferzahnschnauzen $b 3 Murlocaugen $b 3 Okraschoten",objectives={"Salma Saldean möchte 3 Stücke sehniges Geierfleisch, 3 Geiferzahnschnauzen, 3 Murlocaugen und 3 Okraschoten."}]])
R(39,"Zustellung von Thomas' Bericht",[[description="Berichtet Marshal Dughan, dass Malakai und Rolf ums Leben gekommen sind, und teilt ihm auch mit, dass wir die Murlocs in Ost-Elwynn mit unserer derzeitigen Truppenstärke hier nicht unter Kontrolle halten können.$B$BIch weiß, dass wir nicht viele überzählige Männer haben, aber vielleicht findet Dughan ja doch jemanden.",objectives={"Erstattet Marshal Dughan in Goldhain Bericht."}]])
R(40,"Gefahr aus dem Wasser",[[description="Eine neue Gefahr bedroht den Wald von Elwynn, $N! Murlocs kommen die Bäche und Flüsse im östlichen Elwynn hinaufgeschwommen, vertreiben die Fische und greifen einfache Leute an!$B$BIch habe Marshal Dughan bereits gewarnt, aber der macht sich größere Sorgen wegen der Gnolle und der Banditen. Er ist nicht überzeugt davon, dass die Murlocs eine Gefahr darstellen.$B$BBitte sprecht mit Dughan, $N, und bringt ihn dazu, dass er Verstärkung in den Osten schickt!",objectives={"Remy \"Zweifach\" möchte, dass Ihr in Goldhain mit Marshal Dughan sprecht."}]])
R(45,"Rolfs Schicksal",[[description="Als Ihr die Gegend weiter absucht, findet Ihr die Abdrücke von Füßen mit Schwimmhäuten, die entlang dem Ufer des Steinhügelsees nach Osten führen. In der Ferne könnt Ihr im Osten gerade noch so ein Murlocdorf ausmachen.$B$BVielleicht fand Rolfs Leben dort sein Ende...",objectives={"Durchsucht das Murlocdorf nach Rolf - oder nach Anzeichen für seinen Tod."}]])
R(46,"Kopfgeld auf die Murlocs",[[description="Die Armee von Stormwind hat ein Kopfgeld auf die Murloclauerer und Murlocfutterwühler ausgesetzt, die sich in Elwynn herumtreiben. Erlegt sie und bringt mir ihre zerrissenen Murlocflossen, dann wird die Armee von Stormwind Euch ansehnlich belohnen$B$BDie Murlocs haben am Steinhügelsee nördlich von hier ein Dorf errichtet und ein weiteres ihrer Dörfer befindet sich im Süden, wo der Fluss sich teilt.",objectives={"Bringt 8 zerrissene Murlocflossen zu Wache Thomas, den ihr an der östlichen Elwynn-Brücke findet."}]])
R(47,"Tauschhandel mit Goldstaub",[[description="Manchmal haben die Kobolde in dieser Gegend Goldstaub dabei. Das Zeug könnte ich wirklich gut gebrauchen. Bringt mir etwas davon und ich mache Euch den besten Preis in der Stadt... den besten Preis in der Stadt!$B$BDie Kobolde halten sich in der Tiefenschachtmine im Süden und im Bereich der Jaspismine im Nordosten auf.",objectives={"Bringt 10 Einheiten Goldstaub nach Goldhain zu Remy \"Zweifach\". Goldstaub findet Ihr bei den Kobolden im Wald von Elwynn."}]])
R(48,"Goldbrauner Samt",[[description="Weit im Süden, wo die Lianen sich ranken,$bLiegt versteckt ein Brunnen, in dem fast versanken$bDie wertvollen Wasser, so rein und so helle - $bBringt mir Wasser von der Heiligen Quelle.",objectives={"Bringt Grimbooze Donnerbräu Wasser von der Heiligen Quelle."}]])
R(49,"Goldbrauner Samt",[[description="Lang schon vermiss ich die Lieb meines Lebens,$bGoldbraun und samtig, doch noch wart ich vergebens.$bBringt mir, dann vergeht jeder Zorn,$bJe einen Sack Gerste, Roggen und Korn.",objectives={"Grimbooze Donnerbräu möchte einen Sack Gerste, einen Sack Roggen und einen Sack Korn haben."}]])
R(50,"Goldbrauner Samt",[[description="Die Maische anrühren, das ist mein Wille,$bDoch fehlt mir dann auch noch eine Destille.$bFür diese brauch ich ein starkes Metall - $bBringt mir Echtsilber, das ist gut in dem Fall!",objectives={"Grimbooze Donnerbräu braucht Echtsilber."}]])
R(51,"Goldbrauner Samt",[[description="Noch ist er nicht fertig, doch schon frisch gebrannt,$bJetzt wird als Nächstes der Meiler bemannt,$bUm den Whisky zu filtern. Drum bringt mir den Ast$bEines Bergahorns - wenn Ihr könnt, ohne Rast!",objectives={"Bringt Grimbooze Donnerbräu den Ast eines Bergahorns."}]])
R(52,"Grenzschutz",[[description="Seid gegrüßt, $n. Je weiter wir uns von Goldhain entfernen, umso reizbarer sind die wilden Tiere. Und das Holzfällerlager des Osttals wird beinahe ständig von Wölfen und Bären angegriffen.$B$BWir könnten hier draußen wirklich Eure Hilfe gebrauchen.",objectives={"Tötet 8 Streuner und 5 junge Waldbären und kehrt dann zu Wache Thomas an der östlichen Elwynn-Brücke zurück."}]])
R(53,"Goldbrauner Samt",[[description="Das Getränk, das ich braue, das reine und klare,$bWird goldbraun und samtig im Laufe der Jahre.$bDoch ehe er fertig, der Whisky, der weiche,$bBraucht's noch ein Fass aus verkohlter Eiche.",objectives={"Bringt Grimbooze Donnerbräu ein verkohltes Eichenbündel."}]])
R(54,"Meldung in Goldhain",[[description="$N, Ihr habt bewiesen, dass Ihr als $C Euch um die Sicherheit von Nordhain sorgt. Nun erhaltet Ihr die Aufgabe, Euch auch dem Schutz des umliegenden Waldes von Elwynn zu widmen.$B$BWenn Ihr Euch dieser Aufgabe stellen wollt, dann nehmt diese Papiere, die bei Marshal Dughan in Goldhain abgeliefert werden müssen. Goldhain liegt an der südlichen Straße, hinter den Grenztoren.",objectives={"Liefert Marshal McBrides Unterlagen bei Marshal Dughan in Goldhain ab."}]])
R(55,"Morbent Fel",[[description="Morbent Fel hält sich in seinem Unterschlupf verborgen, dem Haus, das hoch oben auf dem Hügel im Osten über dem Friedhof von Rabenflucht thront. Doch seine Zeit in diesem Land neigt sich dem Ende entgegen...$B$BSetzt Morbents Bann gegen ihn ein. Das wird seine schützenden Zauber machtlos machen.$B$BErschlagt ihn. Erschlagt ihn und errettet uns von seiner Verderbtheit. Werdet zum Instrument meiner Rache und damit $gzum Helden:zur Heldin; des Dämmerwalds!",objectives={"Verwendet Morbents Bann gegen Morbent Fel, tötet Morbent Fel und bringt Morbents Bann anschließend zu Sven in dessen Lager zurück."}]])
R(56,"Die Nachtwache",[[description="Als Kommandantin der Nachtwache habe ich geschworen, die Bürger von Dunkelhain zu beschützen. Stormwind hat alle offiziell ernannten Wachen von ihren Posten hier abgezogen; damit sind wir uns selbst überlassen.$b$bWenn Ihr glaubt, der Aufgabe gewachsen zu sein, könnten wir Eure Hilfe wirklich gebrauchen! Helft der Nachtwache und wagt Euch in den Friedhof \"Stille Gärten\", der ein Stückchen südlich von Dunkelhain liegt. Tötet dort 8 Skelettkieger und 6 Skelettmagier. Der Bedrohung durch die Untoten muss ein Ende gemacht werden!",objectives={"Kommandantin Althea Ebonlocke aus Dunkelhain möchte, dass Ihr 8 Skelettkrieger und 6 Skelettmagier tötet."}]])
R(57,"Die Nachtwache",[[description="Ich habe berichtet bekommen, dass im Wald eine wahre Untotenplage ausgebrochen ist, $N. Wenn Ihr Euch der Aufgabe gewachsen fühlt, dann macht Euch auf den Weg zum Friedhof von Rabenflucht und erschlagt 15 dieser abscheulichen Skelettsatanskreaturen und 15 Skelettschrecken. Außerdem sollen im Friedhof \"Stille Gärten\", der sich ein Stückchen südlich von Dunkelhain befindet, Skelette gesehen worden sein. Die Untoten müssen aus dem Dämmerwald vertrieben werden!",objectives={"Kommandantin Althea Ebonlocke aus Dunkelhain möchte, dass Ihr 15 Skelettsatanskreaturen und 15 Skelettschrecken tötet."}]])
R(58,"Die Nachtwache",[[description="Die Lage in Rabenflucht ist noch immer sehr bedenklich. Die Sicherheit von Dunkelhain liegt in Euren Händen, $N. Ich habe einfach nicht genug Behüter, um die Sicherheit in der Stadt zu gewährleisten. Deswegen müsst Ihr Euch erneut nach Rabenflucht aufmachen und das östliche Mausoleum von den Seuchenverbreitern säubern, die sich dort breit gemacht haben. Tötet 20 von ihnen!",objectives={"Kommandantin Althea Ebonlocke aus Dunkelhain möchte, dass Ihr im östlichen Mausoleum von Rabenflucht 20 Seuchenverbreiter tötet."}]])
R(59,"Rüstung aus Tuch und aus Leder",[[description="Als Dank für Eure Gewitztheit und Euren Mut gebe ich Euch hier einen Gutschein, den Ihr gegen ein Rüstungsteil eintauschen könnt. Bringt den Gutschein ins Holzfällerlager des Osttals zu Sara Timberlain. Wenn Ihr ihr den Gutschein gebt, dann stellt sie die Rüstung für Euch her. Und wenn Ihr sie habt, tragt sie zur Verteidigung von Elwynn, $N.$B$BIhr findet das Holzfällerlager des Osttals im Osten jenseits von Wache Thomas' Posten.",objectives={"Gebt Sara Timberlain den Rüstungsgutschein der Armee von Stormwind."}]])
R(60,"Koboldkerzen",[[description="Guten Tag, $gwerter Herr:werte Dame;! Hättet Ihr einen Moment Zeit für mich?$B$BMein Bruder und ich führen in Stormwind eine Apotheke und ich bin hier, weil ich große Kerzen suche, ihres Wachses wegen. Könnt Ihr mir vielleicht helfen?$B$BGroße Kerzen könnt Ihr von Kobolden bekommen - und ich habe Gerüchte gehört, dass Kobolde sich in den Minen von Elwynn eingenistet haben: in der Tiefenschachtmine im Süden und in der Jaspismine im Osten. Ich schlage vor, dass Ihr Euch an einem dieser Orte auf die Suche nach Kerzen begebt.",objectives={"Bringt 8 große Kerzen nach Goldhain zu William Pestle."}]])
R(61,"Lieferung nach Stormwind",[[description="In Stormwind wartet mein Bruder Morgan auf die Lieferung der Kerzen. Ich habe selbst nicht die Zeit, um mich auf die Reise zu begeben, aber wenn Ihr ihm die Lieferung überbringen wollt, so wird er Euch gut bezahlen.$B$BIch habe die Kerzen schon fertig verpackt. Ihr findet Morgan in unserem Geschäft im Handelsdistrikt von Stormwind. Es heißt Pestles Apotheke.",objectives={"Bringt Williams Lieferung in den Handelsdistrikt von Stormwind zu Morgan Pestle."}]])
R(62,"Die Tiefenschachtmine",[[description="Die Mine in Nordhain ist nicht die einzige, mit der es Probleme gibt. Berichten zufolge ist auch die Tiefenschachtmine im Wald von Elwynn zu einem Tummelplatz für Kobolde geworden.$B$BErforscht die Mine, bestätigt diese Berichte und kehrt dann zu mir zurück. Die Mine liegt fast genau südlich von Goldhain, zwischen den Höfen der Stonefields und der Maclures.",objectives={"Erforscht die Tiefenschachtmine und kehrt dann nach Goldhain zu Marshal Dughan zurück."}]])
R(63,"Ruf des Wassers",[[description="An der Küste des Silberwalds befindet sich westlich des Grabmals ein Schrein, der von der Seuche besudelt ist. Die Geister dort sprechen nicht länger zu unserem Volk und es ist jetzt an Euch, die Manifestation dort zu besiegen und den Teich zu säubern.$B$BNehmt die Armschienen des Elementars und gebt sie zusammen mit den verbleibenden Tropfen von Brines Trank in die Kohlenpfanne. Das sollte ausreichen, um einen reinen Geist zu beschwören, mit dem Ihr kommunizieren könnt.$B$BBringt mir einen Beweis dafür, dass Ihr die Tat vollbracht habt, dann belohne ich Euch mit Eurem Totem.",objectives={"Besiegt die verderbte Wassermanifestation und legt die Armschienen der verderbten Manifestation und die verbleibenden Tropfen reinsten Wassers im Silberwald auf die Kohlenpfanne von Everfount."}]])
R(64,"Das vergessene Erbstück",[[description="Es war fürchterlich! Verna hat mich aufgeweckt, als sie draußen auf dem Feld so einen Radau gehört hat. Das ganze Feld war voller Rowdys! Wir sind in solcher Eile aufgebrochen und da hab ich vergessen, meine Taschenuhr einzupacken. Die Uhr hat mir Vernas Vater an unserem Hochzeitstag geschenkt und es wird mir fast schlecht, wenn ich dran denke, dass diese Diebe sie jetzt haben. Ich hab die Taschenuhr im Kleiderschrank in unserem Haus liegen lassen. Haltet nach dem Kürbisfeld im Westen Ausschau, dann kommt Ihr zu unserem Hof - Ihr könnt ihn gar nicht verfehlen. Wenn Ihr mir meine Uhr wiederbringen würdet, wäre ich Euch sehr dankbar.",objectives={"Bauer Furlbrow möchte, dass Ihr seine Taschenuhr holt. Sie befindet sich im Kleiderschrank des Bauernhauses auf der Kürbisfarm im Westen."}]])
R(65,"Die Bruderschaft der Defias",[[description="Die Bruderschaft der Defias nennt sich die Bande von Schuften, von der die braven Leute von Westfall aus dem Land vertrieben werden. Ihr müsst für mich diese Bande bespitzeln. Wir müssen erfahren, wer der Kopf der Gruppe ist und wo sie ihr Versteck hat. In Seenhain findet Ihr im Gasthaus einen Schurken namens Wiley, der mir noch einen Gefallen schuldet.$b$bBegebt Euch nach Seenhain im Rotkammgebirge, östlich von Elwynn, und findet heraus, was Ihr könnt.",objectives={"Gryan Stoutmantle möchte, dass Ihr in Seenhain mit Wiley sprecht."}]])
R(66,"Die Legende von Stalvan",[[description="Letzte Nacht verspürte ich in meinem Geist eine schreckliche Erschütterung. Ich wusste, dass sich meine Enkelin Alyssa in großer Gefahr befand. Ich befragte die Karten und aus ihnen starrte mich die Fratze des Todes höhnisch an.$b$bIch begab mich auf eine lange Reise durch eine dunkle Trance und schließlich gelang es mir, einen Hinweis auf dieses schreckliche Geheimnis zu erhaschen. Ein Name erschloss sich mir, der Name Stalvan.$b$bSucht den Amtmann im Rathaus auf und schaut, ob Ihr nicht mehr über diese Person herausfinden könnt. Ich fürchte um unser aller Leben.",objectives={"Sucht Amtmann Daltry im Rathaus von Dunkelhain auf."}]])
R(67,"Die Legende von Stalvan",[[description="Stalvan, hm? Lasst mich im Stadtverzeichnis nachsehen.$b$bStalvan... Stalvan... mal sehen. Ah, hier ist es! Ich habe hier einen Eintrag über einen gewissen Stalvan Mistmantle. Die letzte bekannte Adresse ist die Schule in Moonbrook. Liebe Güte, das nenne ich veraltet!$b$bWürdet Ihr mir einen Gefallen tun? Falls Ihr zufällig nach Moonbrook kommt, dann lasst es mich wissen, wenn Ihr an neue Informationen über diese Person geraten solltet. Ich habe meine Unterlagen gern auf dem neuesten Stand.",objectives={"Begebt Euch zur Schule in Moonbrook und bringt Amtmann Daltry alle neuen Informationen über Stalvan Mistmantle."}]])
R(68,"Die Legende von Stalvan",[[description="In der alten Schließkiste findet Ihr einen verstaubten, nie abgeschickten Brief.",objectives={"Bringt Amtmann Daltry den verstaubten, nie abgeschickten Brief."}]])
R(69,"Die Legende von Stalvan",[[description="Ach du liebes bisschen! Das ist mir beim ersten Mal ja glatt entgangen! Hier im Verzeichnis steht beim Eintrag für diesen Stalvan direkt unter der ersten Adresse noch eine weitere, die zum Teil durchgestrichen ist. Es scheint, als wäre er zum Gasthaus Zur Höhle des Löwen drüben in Goldhain unterwegs gewesen. Vielleicht solltet Ihr dort nachfragen, $N.",objectives={"Begebt Euch zum Gasthaus Zur Höhle des Löwen und fragt dort nach, ob jemand schon einmal den Namen Stalvan gehört hat."}]])
R(70,"Die Legende von Stalvan",[[description="Den Namen Stalvan hab ich schon mal gehört... Ach, jetzt fällt's mir wieder ein.$b$bVor vielen Jahren betrat an einem stürmischen Abend ein Bote dieses Haus, der Unterkunft für die Nacht suchte. Es war noch nicht ganz Mitternacht, da kam der Mann schreiend die Treppe heruntergerannt. Er war bleich wie der Tod vor Angst. Nur mit seinem Nachtgewand bekleidet verschwand er im Regen.$b$bIn der Eile vergaß er seine Briefe in der Truhe oben und kam nie zurück, um sie abzuholen. Es ist ein Brief dabei von diesem Stalvan, den Ihr erwähntet, adressiert an den Kanaldistrikt in Stormwind. Ihr dürft ihn gern haben.",objectives={"Holt Stalvans niemals zugestellten Brief aus der Truhe und liefert ihn im Kanaldistrikt von Stormwind ab."}]])
R(71,"Meldung an Thomas",[[description="Nun habt Ihr beide Medaillons. Bringt sie an die Brücke zu Wache Thomas, damit er erfährt, welches Schicksal seine beiden Kameraden erlitten haben.",objectives={"Bringt die Medaillons von Rolf und Malakai zu Wache Thomas an die östliche Elwynn-Brücke."}]])
R(72,"Die Legende von Stalvan",[[description="Mein Vater war der Verwalter des Besitzes, lange bevor ich es wurde. Nach dem Massaker war er derjenige, der das Blut aufwischen und aufräumen musste. Aber das tut nichts zur Sache.$b$bDie letzten Gelder aus dem Flintridge-Fonds sind versiegt und jetzt müssen die letzten Stücke aus dem Familienbesitz versteigert werden. Daran sind nur diese Steuereintreiber schuld. Aber wenn Ihr wirklich dringend mehr erfahren wollt, dann dürft Ihr diesen Kram hier gern durchsehen. Wer weiß, was Ihr findet.",objectives={"Durchsucht die verpackten Besitztümer nach Hinweisen."}]])
R(73,"<TXT> No Reward")
R(74,"Die Legende von Stalvan",[[description="In der Kiste findet Ihr verschiedene Dinge: muffige Erbstücke, ein Familienportrait, einige Jagdtrophäen und ein paar alte Bücher. Fast schon am Boden der Kiste findet Ihr unter einer Keramikvase eine zerrissene Tagebuchseite.",objectives={"Die zerrissene Tagebuchseite, die Ihr gefunden habt, gibt Euch den nächsten Hinweis."}]])
R(75,"Die Legende von Stalvan",[[description="Als ich hier eingezogen bin, stand oben schon eine Truhe mit Pergamenten darin. Kurz nach meinem Einzug habe ich sie mir einmal angesehen, aber bald darauf konnte ich nur noch verschwommen sehen und da hab ich's dann gelassen. $b$bTut einem alten, halb blinden Mann einen Gefallen und seht Euch selbst mal in der Kiste oben um, ob Ihr vielleicht etwas findet, das Euch bei Eurer Suche nach diesem Stalvan weiterhelfen kann. Ich bin mir ziemlich sicher, dass da eine verblasste Tagebuchseite dabei ist, die Euch interessieren müsste. Bringt sie mir und ich werde sehen, was ich tun kann, um Euch zu helfen.",objectives={"Marshal Haggard möchte, dass Ihr in der Kiste oben nach der verblassten Tagebuchseite sucht."}]])
R(76,"Die Jaspismine",[[description="Dank Euch wissen wir jetzt, dass Kobolde sich in der Tiefenschachtmine eingenistet haben. Jetzt brauchen wir noch einen Späher, der die weiter entfernte Jaspismine untersucht.$B$BErforscht die Jaspismine und bestätigt mir, ob sich dort tatsächlich Kobolde aufhalten. Die Mine erreicht Ihr, indem Ihr der Straße nach Osten folgt, bis Ihr zum Turm von Azora kommt. Wenn Ihr Euch am Turm nach Norden wendet, dann findet Ihr die Mine im Vorgebirge.",objectives={"Erforscht die Jaspismine und kehrt dann nach Goldhain zu Marshal Dughan zurück, um ihm Bericht zu erstatten."}]])
R(77,"Eine schwierige Situation",[[description="Ich besitze Originalverpackungsmaterial für die Welle, die Dran Droffers will. Ich werde Euch dabei helfen, die Welle für Maltons ungehobelten Vater zu verpacken... für einen Unkostenbeitrag in Höhe zweier weiterer Flaschen besagter Welle. Sie befinden sich in Kisten, die Ihr in dem verlassenen Stützpunkt der Horde in der Nähe von Skulk Rock findet.$B$BDas heißt, dass es eine anstrengende Aufgabe wird. Ihr werdet bei den Ruinen stinkende Brühschleimer und Brühschlammer vorfinden; angeblich werden sie von einer Art Oberbrühschlammer geführt. Beschafft trotzdem die Welle und kehrt hierher zu mir zurück, um sie zu verpacken.",objectives={"Holt 10 Flaschen Hinterland-Honigwelle aus den Kisten, die sich rund um den verlassenen Stützpunkt der Horde in Skulk Rock befinden."}]])
R(78,"Die Legende von Stalvan",[[description="Ich kenne jemanden, der Euch vielleicht helfen könnte. Damals, als ich noch die Wachen von Stormwind kommandierte, haben wir immer in der Taverne Zum roten Raben in Dunkelhain gesessen und etwas getrunken. Smitts, der Gastwirt dort, kannte sich mit den örtlichen Lehren ziemlich gut aus. Zeigt ihm diese Seite, mal sehen, was er dazu zu sagen hat.",objectives={"Bringt die verblasste Tagebuchseite zu Schankwart Smitts."}]])
R(79,"Die Legende von Stalvan",[[description="Ich habe die Geschichten um diesen Stalvan jahrelang verfolgt. Als vor ein paar Jahren diese Adligen, die hier zu Besuch waren, ermordet wurden, hab ich Haggard bei seinen Nachforschungen begleitet. Ich habe damals diese schlammverschmierten Seiten gefunden, aber es ist uns nie gelungen, die Handschrift mit diesem Verrückten in den Wäldern in Verbindung zu bringen. Eure Spur der Beweise zeigt aber, dass er schuldig ist. Bringt dies sofort zu Kommandant Ebonlocke und sagt ihr, was Ihr entdeckt habt!",objectives={"Bringt Kommandant Ebonlocke die schlammverschmierte Seite."}]])
R(80,"Die Legende von Stalvan",[[description="Ich beobachte diesen Widerling Stalvan jetzt schon eine ganze Weile. Aber wenn diese Seite tatsächlich von seiner Hand geschrieben wurde, dann beweist das seine Schuld ohne den letzten Zweifel.$b$bSo lange, wie Amtmann Daltry das Stadtverzeichnis jetzt schon verwaltet, ist er ein wahrer Experte darin geworden, Handschriften zu identifizieren. Zeigt ihm diese Seite und stellt fest, ob die Schrift dieselbe ist wie diejenige der Unterschrift im Verzeichnis.",objectives={"Zeigt Amtmann Daltry die blutbefleckte Tagebuchseite."}]])
R(81,"Wellenlieferung",[[description="Ich habe zusätzliche Vorsichtsmaßnahmen getroffen und nicht nur Drans verpackte Welle in dem Fass sicher untergebracht, sondern auch die zusätzlichen Wellenflaschen, die er klaut. Auch wenn ich nicht viel von Dran halte, so gibt es doch nichts Schlimmeres als ein durchgeschütteltes Wellenbouquet. Bitte, bitte, keine Ursache.$B$BBringt jetzt Euer Fass zu Dran Droffers in seinem Kramladen in Orgrimmar. Entbietet meine besten Grüße bitte auch Malton und lasst ihn wissen, dass uns sein Besuch eine große Ehre wäre, falls es ihn jemals nach einem feinen Getränk und noch feineren Trinkkumpanen gelüstet.",objectives={"Liefert das Fass nach Orgrimmar an Dran Droffers."}]])
R(82,"Erkundung des Giftigen Unterschlupfes",[[description="Tja, diese Berichte über die Käfer... wir wissen, dass sie die Teiche trocken legen, die sich dort befanden, wo sich der Giftige Unterschlupf befindet. Was wir NICHT wissen, ist, na ja, alles andere.$B$BWir müssen als Erstes herausfinden, wer unser Feind ist! Begebt Euch bitte in den Giftigen Unterschlupf und besorgt ein paar Stücke dieser Tierwesen. Holt fünf der dortigen Centipaar und bringt sie dem Alchimisten Pestlezugg zur Untersuchung. Wenn er sich damit beschäftigt, werden wir schon herausfinden, worum es sich handelt!",objectives={"Bringt fünf Centipaarinsektenteile vom Giftigen Unterschlupf nach Gadgetzan zum Alchimisten Pestlezugg."}]])
R(83,"Rote Leinenwaren",[[description="Die Mitglieder der Defias in Nordhain tragen Masken aus Sackleinen, die Masken der Defias in Elwynn dagegen sind aus gutem Leinen, aus dem ich Qualitätsleinenwaren herstellen kann.$B$BBringt mir rote Leinenkopftücher, dann stelle ich daraus etwas für Euch her.$B$BDie Mitglieder der Defias haben Lager, die sich über ganz Elwynn verteilen.",objectives={"Bringt 6 rote Leinenkopftücher ins Holzfällerlager des Osttals zu Sara Timberlain."}]])
R(84,"Zurück zu Billy",[[description="Hier, bitte schön. Und wenn Ihr Billy die Pastete gebt, dann sagt ihm, ich hoffe, er erstickt daran!",objectives={"Bringt die Schweinebauchpastete zu Billy Maclure in den Weinbergen der Maclures."}]])
R(85,"Die verlorene Halskette",[[description="Ich habe meine Halskette verloren und ich glaube, dieser Tunichtgut Billy Maclure hat sie genommen! Normalerweise treibt er sich immer wie eine kleine Ratte in den Weinbergen der Maclures östlich von hier herum. $B$BBringt mir meine Halskette zurück, wenn Ihr das Herz einer alten Witwe erfreuen wollt.",objectives={"Sprecht mit Billy Maclure."}]])
R(86,"Pastete für Billy",[[description="Wenn ich 'ne Pastete kriegen würde, dann könnte ich Euch vielleicht sagen, wer die Kette hat. Ach, und wisst Ihr was? Diese alte Dame Bernice auf dem anderen Hof da macht ganz tolle Schweinebauchpasteten. $B$BWenn Ihr ihr ein paar Brocken Eberfleisch von den Ebern bringt, die immer um unsere Höfe herumstromern, und ihr sagt, dass es für einen guten Zweck ist, dann backt sie Euch vielleicht eine Pastete.",objectives={"Bringt 4 Brocken Eberfleisch zu Tantchen Bernice Stonefield auf den Hof der Stonefields."}]])
R(87,"Goldzahn",[[description="Ich hab in der Nähe von der Tiefenschachtmine gespielt und da hab ich, glaub ich, die Kette von der alten Dame fallen ge... äääh, gesehen. Fragt mich nicht, wie die dahin gekommen ist, ich war's nicht!$B$BNa egal, jedenfalls hab ich diesen großen Kobold gesehen, der hatte einen Goldzahn und der hat die Kette aufgehoben und ist in die Mine gerannt. Wenn Ihr diesen Kobold findet, dann findet Ihr auch die Halskette, ehrlich! Ich schwör's!",objectives={"Bringt Berenices Halskette auf den Hof der Stonefields zu \"Tantchen\" Berenice Stonefield."}]])
R(88,"Prinzessin muss sterben!",[[description="Die Brackwells haben ein Schwein, eine Sau namens Prinzessin, die schon viele Preise gewonnen hat. Dass dieses Tier so riesig geworden ist, das kommt nur daher, dass es immer hier herübergeschlichen kommt und mein Gemüse frisst!$B$BUnd deswegen muss Prinzessin sterben, bevor sie wieder unsere Felder heimsucht! Bringt mir ihr Halsband zum Beweis, dass Ihr die Sau abgestochen habt, dann gebe ich Euch etwas, das Euch für Euren Aufwand entschädigt.$B$BIhr findet Prinzessin normalerweise bei Brackwells Kürbisbeet, noch hinter dem Hof der Maclures und von dort aus im Osten gesehen. Ich hoffe, Ihr erwischt die Sau, bevor sie wieder hungrig wird und hierher kommt!",objectives={"Tötet Prinzessin, nehmt ihr Halsband an Euch und bringt es zu Mutter Stonefield auf den Hof der Stonefields."}]])
R(89,"Die Immerruhbrücke",[[description="Während der letzten Invasion der Orcs waren wir gezwungen, unser Eisen einzuschmelzen, um Kugeln, Schwerter und Rüstungen herzustellen. Wir haben Stormwind benachrichtigt, dass wir eine neue Lieferung Materialien benötigen. Aber eine Bande von Rotkammgnollen hat die Karawane überfallen und sich dann in die Hügel hinter Seenhain zurückgezogen.$b$bJetzt gehen uns langsam die Vorräte aus, die wir brauchen, um die Brücke wieder aufzubauen. Wenn Ihr mir 5 Eisenspitzen und 5 Eisennieten bringt, $N, dann sollt Ihr dafür belohnt werden. $b$bUnd jetzt an die Arbeit!",objectives={"Bringt 5 Eisenspitzen und 5 Eisennieten nach Seenhain zu Großknecht Oslow."}]])
R(90,"Gewürzter Wolfskebab",[[description="Gewürzter Wolfskebab ist eine Spezialität des Hauses! Natürlich kann ich Euch welchen machen. Aber ich brauche erst die Zutaten dafür. Bringt mir 10 magere Wolfflanken sowie Würzkräuter aus Stormwind. Hier im Wald streifen so viele Wölfe herum, da werdet Ihr kein Problem haben, an die Wolfflanken zu kommen, da bin ich mir sicher. Und für die Kräuter sucht ihr am besten Felicia Gump in ihrem Blumenladen im Kanaldistrikt von Stormwind auf.",objectives={"Beschafft Euch 10 magere Wolfflanken und Würzkräuter aus Stormwind und kehrt dann zu Küchenchef Grual nach Dunkelhain zurück."}]])
R(91,"Das Gesetz des Solomon",[[description="Ein Feind Stormwinds hat sich im östlichen Vorläufer des Rotkammgebirges niedergelassen. Dieser verderbte Schurke bedient sich des Übernatürlichen, um unsere Stadt und ihre Einwohner in Angst und Schrecken zu versetzen. Er betreibt sein übles Geschäft unter dem Namen Morganth.$b$bMorganth kontrolliert jetzt den Schattenfellklan. Die Gnolle tun alles, was er ihnen befiehlt. Wie es das Gesetz von Seenhain vorsieht, steht auf die Unterstützung eines im Königreich gesuchten Verbrechers die Todesstrafe.$b$bDiese abscheulichen Gnolle verdienen den Tod!$b$bGebt 10 Schattenfellanhänger bei mir ab, dann erhaltet Ihr eine Belohnung.",objectives={"Bringt 10 Schattenfellanhänger ins Rathaus von Seenhain zu Büttel Conacher."}]])
R(92,"Rotkammgulasch",[[description="Ich würde liebend gern Rotkammgulasch für Euch kochen. Aber es gibt da ein kleines Problem. Erst kürzlich musste ich während des Orcaufstands eine ganze Brigade von Soldaten der Armee von Stormwind verpflegen. Jetzt ist meine Vorratskammer leer. Aber wenn Ihr mir die Zutaten besorgt, dann mache ich das gern für Euch.$b$bBringt mir einfach 5 Stücke zähes Kondorfleisch, 5 große Geiferzahnschnauzen und 5 Portionen knuspriges Spinnenfleisch.",objectives={"Küchenchefin Breanna aus Seenhain möchte 5 Stücke zähes Kondorfleisch, 5 große Geiferzahnschnauzen und 5 Portionen knuspriges Spinnenfleisch."}]])
R(93,"Schwärzliche Krebsküchlein",[[description="Ich verrate Euch ein kleines Geheimnis: Schwärzliche \"Krebs\"-Küchlein werden eigentlich aus Spinnenbeinen gemacht! Ich weiß, das ist irgendwie eklig, aber die Küchlein schmecken lecker, ein bisschen scharf und eignen sich ganz ausgezeichnet zum Knabbern. Wenn Ihr mir einige klebrige Spinnenbeine bringt, dann zaubere ich Euch ein paar.$B$BIch habe gehört, dass sich Giftweberspinnen ausgezeichnet dafür eignen - sie haben ihr Nest im Norden, zwischen dem Vorgebirge und dem Fluss.",objectives={"Beschafft 6 klebrige Spinnenbeine und bringt sie nach Dunkelhain zu Küchenchef Grual."}]])
R(94,"Ein wachsames Auge",[[description="Mein Widersacher Morganth ist ein böser Magier von großer Macht, der im Turm von Ilgalar im Rotkammgebirge lebt. Ich habe eine Methode entwickelt, mit der ich ihn ausspionieren kann: Mit dem Auge von Azora ist es mir möglich, ihn von weitem zu sehen.$B$BDoch um seine Gedanken zu erforschen... ja, dazu benötige ich noch weitere Hilfe.$B$BWenn Ihr gewillt seid, dies zu tun, dann bringt meine Glyphe von Azora zum Turm von Ilgalar. Legt sie auf die Löwenstatue in der Nähe des Turms.$B$BSobald dieses getan ist, wird die Macht von Azora mir Visionen von Morganths zukünftigen Plänen gewähren.",objectives={"Bringt die Glyphe von Azora zur Löwenstatue in der Nähe des Turms von Ilgalar im Rotkammgebirge."}]])
R(95,"Svens Rache",[[description="Früher arbeitete ich auf einem der Höfe im Südosten... bis einmal in meiner Abwesenheit Dunkle Reiter vom Gebirgspass der Totenwinde herunterkamen, meinen Hof überfielen und meine Familie abschlachteten.$B$BAls ich zurückkehrte, sah ich eine schattenhafte Gestalt, die sich bei meiner Scheune herumtrieb und dort etwas vergrub. Er floh, ehe ich ihn erreichen konnte, und ich hatte keine Zeit, mich mit ihm aufzuhalten, da ich den Dunklen Reitern dicht auf den Fersen war. Und so habe ich nie entdeckt, was die Gestalt dort versteckte.$B$BWenn Ihr herausfinden könntet, was jene schattenhafte Gestalt dort vergrub, dann wäre ich Euch dankbar. Das Versteck befindet sich hinter dem alten Baumstumpf in der Nähe meiner Scheune.",objectives={"Begebt Euch zu Svens Hof und findet heraus, was hinter dem alten Baumstumpf vergraben wurde."}]])
R(96,"Ruf des Wassers",[[description="Nehmt Splitter. Nehmt Splitter und gebt Leben.$B$BGebt Leben und versteht. Versteht, Wasser ist Leben... Verderbnis beendet Leben.$B$BIhr schützt und gebt Leben mit der Macht des Wassers.",objectives={"Bringt den Splitter des Wassers in das Brachland zu Islen Waterseer."}]])
R(97,"Die Legende von Stalvan",[[description="Kommandant Ebonlocke muss unverzüglich erfahren, dass die Handschriften identisch sind, $N! Ihr Verdacht hat sich also bestätigt.",objectives={"Berichtet Kommandant Ebonlocke die Neuigkeiten."}]])
R(98,"Die Legende von Stalvan",[[description="Stalvan Mistmantle hat ein Leben der Verworfenheit gelebt und unschuldige Opfer starben von seiner Hand. Zweifellos hat er noch zahllose andere Verbrechen begangen und nun wird Dunkelhain von diesem Wahnsinnigen bedroht. Das Licht allein weiß, welche schmutzigen Pläne er jetzt ausheckt. Deswegen brauche ich Eure Hilfe, $C. Begebt Euch zu seiner Hütte ein kleines Stück nördlich der Stadt und schaltet Stalvan ein für alle Mal aus.$b$bSobald die Tat vollbracht ist, begebt Euch zu Madame Eva und zeigt Ihr den Ring seiner Familie. Schließlich war es ihre Vorahnung, die zu dieser entsetzlichen Entdeckung führte. Doch jetzt kann ganz Dunkelhain dank ihr wieder ruhiger schlafen.",objectives={"Tötet Stalvan Mistmantle und zeigt Madame Eva den Ring seiner Familie."}]])
R(99,"Arugals Torheit",[[description="Je mehr ich über Arugals Magie erfahre, umso mehr wächst meine Verachtung für diesen jämmerlichen Narren. Bald werde ich meine Studien zu seiner so genannten 'Arznei' beendet haben.$b$bMein Wissen wird vollständig sein, sobald ich herausgefunden habe, welche Verzauberung die seltsamen Zustände in Pyrewood verursacht. Tagsüber scheinen die Arbeiter dort ganz gewöhnliche Menschen zu sein. Doch sobald die Sonne untergeht, verwandeln sich die Dorfbewohner in Moonrage-Worgs.$b$bIch muss Energie aus den verzauberten Fesseln ziehen, die Arugal auf sie gewirkt hat. Bringt mir 6 verzauberte Pyrewood-Fesseln, $N.",objectives={"Bringt Dalar Dawnweaver 6 Pyrewood-Fesseln zum Grabmal."}]])
R(100,"Ruf des Wassers",[[description="Noch während die Zauberformel, die Ihr gesprochen habt, verhallt, zuckt ein Meer von Lichtern um Euch herum auf. Das Zischen der Wassertropfen, die mit den Flammen in Berührung kommen, lässt nach und Eure überreizten Sinne spüren, wie die verderbten Geister in Eurer Nähe vernichtet werden.",objectives={"Sprecht mit der schwachen Wassermanifestation im Silberwald."}]])
R(101,"Das Totem des Gegenschlages",[[description="Nun, da übernatürliche Mächte den Wald durchziehen, besteht ganz zweifellos die Notwendigkeit, sich zu schützen, $N. Leise flüstern mir die Winde von einer großen Gefahr, die auf Euch lauert und der Ihr Euch in nicht allzu ferner Zukunft gegenübersehen werdet.$b$bAuch ein tapferer $C wie Ihr sollte sich schützen. Falls Ihr dies wünscht, so bringt mir 10 Ghulfangzähne, 10 Skelettfinger und 5 Phiolen Spinnengift. Dann stelle ich Euch ein Totem des Gegenschlages her und belege es mit einem Zauber, durch den es all denjenigen schadet, die gegen Euch Gewalt anwenden wollen.",objectives={"Bringt 10 Ghulfangzähne, 10 Skelettfinger und 5 Phiolen Spinnengift nach Dunkelhain zu Madame Eva."}]])
R(102,"Auf Patrouille durch Westfall",[[description="Stormwind hat uns im Stich gelassen. Der üble Gestank der Verderbtheit weht über die Ebenen von Westfall. Dies war und ist mein Heimatland und ich werde die Bürger, die sich zum Bleiben entschlossen haben, nicht verlassen. Wir, die wir früher Bauern waren, werden Widerstand leisten.$b$bEure Aufgabe, so Ihr sie denn annehmt, wird es sein, im Grasland von Westfall auf Patrouille zu gehen. Spürt die widerwärtigen Gnolle auf, die augenscheinlich mit den Dieben aus den Todesminen zusammenarbeiten, und tötet sie. Bringt mir 8 Gnolltatzen und ich werde Euren Mut zu belohnen wissen.",objectives={"Bringt 8 Gnolltatzen auf die Späherkuppe zu Captain Danuvin."}]])
R(103,"Bewahrer der Flamme",[[description="Die Nacht, in der die Familie des Leuchtturmwärters starb, war schrecklich. Hilflos musste ich mit ansehen, wie Old Murk-Eye den Angriff befehligte. Doch was geschehen ist, ist geschehen. Nun sorge ich mich vor allem um das Leben der Seeleute, die das große Meer besegeln und deren Schiffe den trügerischen Felsen vor der Küste gefährlich nahe kommen. Da hier niemand mehr lebt, der die Flamme bewacht, obliegt die Verantwortung nun mir.$b$bHelft mir dabei, die Fackel am Leuchten zu erhalten, und bringt mir 5 Fläschchen Öl von den Erntemonstern.",objectives={"Bringt 5 Fläschchen Öl zu Captain Grayson beim Leuchtturm von Westfall."}]])
R(104,"Bedrohung an der Küste",[[description="Als ich auf den Felsen mein Leben aushauchte, hatte ich keine Ahnung, was das Leben nach dem Tode für mich bereithalten würde. In jener Nacht war der Leuchtturm erloschen, weil Old Murk-Eye die Familie des Leuchtturmwärters vertrieben hatte. Die Familie kehrte zurück und zündete die Flamme wieder an, doch Old Murk-Eye brachte die willensschwächeren Murlocs dazu, den Leuchtturm noch einmal mit ihm zusammen anzugreifen. Beim zweiten Mal hatte die Familie nicht so viel Glück. Vor meinen Augen starben sie alle, ohne sich wehren zu können.$b$bTötet Old Murk-Eye, wenn Ihr ihn am Ufer seht, und bringt mir eine seiner Schuppen, dann werdet Ihr eine Belohnung erhalten.",objectives={"Bringt Captain Grayson am Leuchtturm von Westfall eine Schuppe von Old Murk-Eye."}]])
R(105,"Weh dir, Andorhal",[[description="Endlich ist die Zeit gekommen Andorhal anzugreifen und den Lich, der die Stadt kontrolliert, zu vertreiben.$B$BDer Lich - Araj der Zerstörer - herrscht von innerhalb der Ruinen der Stadt aus. Er wird von zahlreichen Angehörigen der Geißel bewacht, die über die Überreste des Stadtzentrums wachen, auch sein Gefolge an Leibwächtern ist ausgezeichnet. Ihr werdet einige Verbündete brauchen, um auch nur einen Hauch von einer Chance zu haben, sich ihm gegenüber stellen zu können.$B$BVernichtet Araj, $N, und bringt mir einen Splitter seines Phylakteriums als Beweis!",objectives={"Bringt den Splitter von Arajs Phylakterium zu Hochexekutor Derrington ins Bollwerk in den Westlichen Pestländern."}]])
R(106,"Junge Liebende",[[description="Oh, ein Fluch lastet auf mir! Mein Herz gehört Tommy Joe Stonefield, aber unsere Familien sind aufs Ärgste miteinander verfeindet. Daher kann ich mich nicht mit ihm treffen, obwohl ich mich doch so sehr danach sehne, sein geliebtes Gesicht zu sehen!$B$BBitte nehmt diesen Brief und gebt ihn Tommy Joe. Normalerweise hält er sich am Fluss im Westen des Hofs der Stonefields auf, das ist auch von hier aus genau westlich.",objectives={"Gebt Tommy Joe Stonefield Maybells Liebesbrief."}]])
R(107,"Nachricht an William",[[description="Ich möchte wetten, William Pestle hat einen Trank, der unsere beiden Liebenden zusammenbringen kann.$B$BHier, bringt William diese Nachricht. Er wohnt im Gasthaus Zur Höhle des Löwen in Goldhain.",objectives={"Bringt Oma Stonefields Nachricht zu William Pestle."}]])
R(108,"<TXT> Mystery Reward")
R(109,"Meldung bei Gryan Stoutmantle",[[description="Es scheint mir, $C, als hättet Ihr schon etliche Kämpfe überstanden. Falls Ihr das noch nicht getan habt, solltet Ihr Euch bei Gryan Stoutmantle melden. Er ist der Anführer der Volksmiliz, die es sich zur Aufgabe gemacht hat, das Ackerland von Westfall zu beschützen. Ich möchte wetten, er könnte Eure Hilfe gebrauchen. Normalerweise findet man ihn im Steinturm auf der Späherkuppe, ein kleines Stückchen von der Straße weg, mitten in Westfall.",objectives={"Sprecht mit Gryan Stoutmantle. Normalerweise findet man ihn im Steinturm auf der Späherkuppe, ein kleines Stückchen von der Straße weg, mitten in Westfall."}]])
R(110,"Insektenteil-Analyse",[[description="Ich werde einige Zeit brauchen, um Scrimshanks Feldmesserausrüstung durchzusehen... und seine persönlichen Angelegenheiten zu regeln. Mein Bauch sagt mir, dass dies nicht der letzte Verlust ist, den wir durch die Käfer hinnehmen müssen.$B$BGeht bitte zu Alchimist Pestlezugg, um zu sehen, ob er etwas mit den Insektenteilen anfangen konnte, die wir ihm geschickt haben. Wenn sie fertig sind, bringt sie mir.",objectives={"Begebt Euch nach Gadgetzan zu Alchimist Pestlezugg und erkundigt Euch nach der Analyse der Insektenteile."}]])
R(111,"Gespräch mit Oma",[[description="Bitte sprecht mit meiner Großmutter, $n. Wenn irgendjemand einen Weg weiß, wie ich mit Maybell zusammen sein kann, dann ist sie das.$B$BIhr findet sie in unserem Haus, östlich von hier.",objectives={"Sprecht mit Oma Stonefield."}]])
R(112,"Die Suche nach dem Tang",[[description="Ich könnte einen Unsichtbarkeitsschnaps für Maybell brauen, damit sie sich aus den Weinbergen der Maclures fortstehlen und Tommy Joe sehen kann. Aber um den Schnaps herzustellen, brauche ich etwas Kristalltang.$B$BDieser Tang wächst zwar normalerweise im Meer, aber manchmal wird er auch von den Murlocs gesammelt. Geht und schaut, ob die Murlocs am Kristallsee welchen haben. Der Kristallsee liegt ein kleines Stück östlich von Goldhain.",objectives={"Bringt 4 Kristalltangwedel nach Goldhain zu William Pestle."}]])
R(113,"Insektenteil-Analyse",[[description="Der Leitende Feldmesser Fizzledowser muss diesen Bericht sofort sehen. Eigentlich muss jeder, der lesen kann, diesen Bericht sehen. Wir stehen einer großen und ernsten Bedrohung gegenüber, die nicht nur Tanaris und Gadgetzan, sondern das ganze südliche Kalimdor betrifft, wenn wir nichts unternehmen. Möglicherweise ist sogar ganz Azeroth gefährdet. Dieses Ding macht nicht den Eindruck, als würde es das Interesse verlieren.$B$BLasst Fizzledowser ein Duplikat des Berichts anfertigen, den Ihr dann an Eure Verbündeten verteilen könnt. Jeder muss von dieser Bedrohung erfahren!",objectives={"Bringt den Bericht nach Gadgetzan zum Leitenden Feldmesser Fizzledowser. Lasst Euch von ihm eine Kopie des Berichts geben, wie Alchimist Pestlezugg gefordert hat."}]])
R(114,"Die Flucht",[[description="Bringt der jungen Maybell diesen Unsichtbarkeitsschnaps. Seine Wirkung sollte so lange anhalten, dass sie Tommy Joe besuchen kann.",objectives={"Bringt Maybell Maclure den Unsichtbarkeitsschnaps."}]])
R(115,"Schattenmagie",[[description="Von den Orcs des Blackrockklans wurden zur Unterstützung ihrer Angriffe auf das Rotkammgebirge Schattenzauberer rekrutiert, die von einer dunklen Macht erfüllte Vorrichtungen mit sich führten - Mitternachtskugeln. Diese Kugeln haben den Verteidigern vom Rotkammgebirge schwere Verluste zugefügt und es ist von äußerster Wichtigkeit, dass wir diese dämonbesudelten Gegenstände aus dem Konflikt entfernen.$B$BDurchsucht erschlagene Schattenzauberer der Blackrock nach Mitternachtskugeln und bringt sie mir. Ich werde die Kugeln dann vernichten lassen, denn ohne sie wäre die Welt ein wesentlich besserer Ort.",objectives={"Bringt 3 Mitternachtskugeln nach Seenhain zu Marshal Marris."}]])
R(116,"Trockene Zeiten",[[description="Mir werden hier gerade die Vorräte knapp, $N. Alle Flaschen sind fast leer, und die letzte Schnapslieferung hätte schon längst hier eintreffen sollen. Die Orcinvasion ist einfach die Hölle.$b$bVielleicht könnt Ihr Euch ja für mich an die Arbeit machen?$b$bIhr müsst für mich bei Grimbooze Donnerbräu in den Westfall-Hügeln ein Fässchen Donnerbräu Lagerbier besorgen, ebenso ein Fässlein Merlot aus Stormwind, eine Flasche Fusel aus Dunkelhain und einen Schlauch mit süßem Rum aus Goldhain. Bringt mir all diese Dinge, dann werde ich dafür sorgen, dass Ihr belohnt werdet.",objectives={"Barkeeper Daniels aus Seenhain braucht ein Fässchen Donnerbräu Lagerbier, ein Fässlein Merlot, eine Flasche Fusel und einen Schlauch mit süßem Rum."}]])
R(117,"Donnerbräu",[[description="Ihr müsst eilen, $gmein Freund:Madame;, sollt nicht ruhen, noch rasten, $bDenn für unser Lagerbier lohnt sich's zu hasten. $bEs schmeckt allen Männern, es schmeckt allen Frauen - $bDoch ich brauche noch Hopfen, um das Bier zu brauen.",objectives={"Bringt Grimbooze Donnerbräu 5 Hopfen, damit er sein besonderes Bier brauen kann."}]])
R(118,"Der Preis für Hufeisen",[[description="Ich habe so viel Eisen dafür verwenden müssen, die Wachen von Stormwind auszurüsten, dass ich nicht mehr genug Eisen übrig habe, um die Pferde im Stall zu beschlagen!$B$BBringt diese Nachricht zu Schmied Argus nach Goldhain. Darin erkläre ich ihm mein Problem und bitte ihn um eine Lieferung Hufeisen.",objectives={"Bringt Verners Nachricht zu Schmied Argus nach Goldhain."}]])
R(119,"Zurück zu Verner",[[description="Gut, er soll seine 50 Hufeisen haben.$B$BHier sind sie, schön in eine Kiste verpackt und bereit zum Abmarsch. Sagt Verner, dass es ein Vergnügen war, mit ihm Geschäfte zu machen, und sagt ihm, dass er unbedingt die Nachricht lesen soll, die ich ihm an die Kiste geheftet habe!",objectives={"Kehrt zu Verner Osgood ins Rotkammgebirge zurück. Gebt ihm die Kiste mit Hufeisen."}]])
R(120,"Botschaft nach Stormwind",[[description="Wir leben in schwierigen Zeiten, $C. Unsere Ortschaft ist einer ständigen Belagerung ausgesetzt. Wenn wir keine Verstärkung bekommen, ist unsere Niederlage so gut wie besiegelt. Die Botschaft, die ich Euch nun anvertrauen werde, ist von äußerster Wichtigkeit. Bringt diesen Bericht unverzüglich zu General Marcus Jonathan nach Stormwind. Sobald Ihr die Nachricht abgeliefert habt, kehrt umgehend zu mir zurück und überbringt mir alle Neuigkeiten, ganz gleich, ob gut oder schlecht. $b$bDoch nun eilt!",objectives={"Magistrat Solomon hat Euch einen Bericht übergeben, der bei General Marcus Jonathan in Stormwind abgeliefert werden muss. Der Richter möchte, dass Ihr zu ihm zurückkehrt, sobald Ihr die Nachricht zugestellt habt."}]])
R(121,"Botschaft nach Stormwind",[[description="Während ich auf Antwort vom König warte, möchte ich, dass Ihr diesen Brief zu Magistrat Solomon bringt. $b$bWeggetreten, $C!",objectives={"Bringt General Marcus Jonathans Antwortschreiben nach Seenhain zu Magistrat Solomon."}]])
R(122,"Bauchschuppen",[[description="Ich brauche einige Bauchschuppen von schwarzen Großdrachenwelpen, damit ich die Hufeisen bezahlen kann, die Argus mir aus Goldhain geschickt hat. Wenn Ihr mir 6 solcher Schuppen besorgt, dann kann ich mit einem Teil davon Argus bezahlen - und habe dann immer noch einen Rest übrig, aus dem ich etwas für Euch herstellen kann.$B$BSchwarze Großdrachenwelpen fliegen häufig über das Gebiet südlich von Seenhain, aber sie wandern auch gern herum. Haltet einfach die Augen offen und jagt sie, wenn Ihr sie seht.",objectives={"Sammelt 6 Welpenbauchschuppen von schwarzen Großdrachenwelpen ein und bringt sie ins Rotkammgebirge zu Verner Osgood."}]])
R(123,"Der Sammler",[[description="Bei der Notiz handelt es sich um eine Tabelle mit Daten und Zeiten, zu denen jemand, der in der Notiz nur als \"der Sammler\" bezeichnet wird, je eine Lieferung Gold aus den Minen des Waldes von Elwynn erhalten soll.$B$BAus dem Plan geht hervor, dass sich der Sammler anscheinend in der Nähe vom Brackwell-Kürbisbeet in Ost-Elwynn aufhält.$B$BDas klingt, als sei es wichtig. Ihr solltet Marshal Dughan in Goldhain davon berichten.",objectives={"Begebt Euch zu Marshal Dughan nach Goldhain und gebt ihm den Zeitplan des Sammlers."}]])
R(124,"Das Bellen der Gnolle",[[description="Als ob Orc-Angriffe nicht genug wären! Jetzt schleichen auch noch Gnoll-Schläger und Gnoll-Mystiker auf dem Hügelkamm nördlich von meinem Stall herum und fallen meine Pferde an, wenn diese sich auch nur etwas zu weit vom Stall entfernen...$B$BWenn Ihr diese Gnolle beseitigen könntet, wären meine Pferde und ich Euch sehr dankbar.",objectives={"Tötet 10 Schläger der Rotkammgnolle und 8 Mystiker der Rotkammgnolle und kehrt anschließend zu Verner Osgood zurück."}]])
R(125,"Die verlorenen Werkzeuge",[[description="Ich könnte hier wirklich etwas Hilfe gebrauchen, $n. Jetzt, wo die Stadt belagert wird, bekommen wir hier nur schwer Nachschub. Meine Werkzeuge sollten mit dem Karren von Goldhain aus angeliefert werden, aber die Brücke wurde in die Luft gejagt. Also legten wir die Werkzeuge in ein Boot, aber die Orcs beschossen es mit einem Katapult und trafen auch noch. Na, und bei meinem Pech ist mein Werkzeugkasten natürlich geradewegs bis auf den Grund des Sees gesunken.$b$bWenn Ihr mir meinen Werkzeugkasten wiederbeschafft, $n, dann soll es Euer Schaden nicht sein.",objectives={"Großknecht Oslow aus Seenhain möchte, dass Ihr seinen Werkzeugkasten vom Grunde des Immerruhsees heraufholt."}]])
R(126,"Geheul in den Hügeln",[[description="Die Gnolle sind immer noch da draußen, $n. Ich kann sie bellen hören, wenn sie in den Hügeln oberhalb von Seenhain jagen. Und das Geheul eines Gnolls ist lauter als das aller anderen - das von Jauler, ihrem Anführer.$B$BTötet Jauler und vertreibt sein Rudel in alle vier Winde! Bringt mir seine Tatze zum Beweis.$B$BAber seid vorsichtig! Dieser Gnoll ist nicht umsonst der Anführer seines Rudels. Er ist kein einfacher Köter...",objectives={"Bringt Jaulers Tatze nach Seenhain zu Verner Osgood."}]])
R(127,"Fischhandel",[[description="Der Immerruhsee ist für seinen gefleckten Sonnenfisch berühmt. Die Nachfrage nach diesen Fischen ist enorm hoch - und ich habe bald keine mehr vorrätig!$B$BBringt mir 10 Stück, dann werden wir uns schon handelseinig werden. Und wenn Ihr nicht selbst angeln möchtet oder könnt - na ja, vielleicht bekommt Ihr die Fische ja von den Murlocs!",objectives={"Bringt 10 gefleckte Sonnenfische nach Seenhain zu Dockmeister Baren."}]])
R(128,"Kopfgeld auf die Blackrocks",[[description="Der Blackrockklan muss vernichtet werden. Der Feind ist in unser Land eingedrungen. Diese Berge unterliegen der Oberhoheit des Königs von Stormwind. Aus bestimmten Quellen haben wir erfahren können, dass die Anführer jeder Einheit im Klan \"Helden\" genannt werden. Ihr findet sie in ihrem Lager im Norden, ein kleines Stück westlich von der Straße, die in die brennende Steppe führt.$b$bMagistrat Solomon möchte diese garstigen Bestien tot sehen. Erschlagt 15 Helden der Blackrock und kehrt zu mir zurück.",objectives={"Tötet 15 Helden der Blackrock, dann erhaltet Ihr von Wache Howe aus Seenhain eine Belohnung."}]])
R(129,"Ein geschenktes Mittagessen",[[description="Könntet Ihr mir einen Gefallen tun? Ich habe für Wache Parker ein Mittagessen gemacht, aber er ist gerade auf Patrouille unterwegs... Er ist groß und stark und noch dazu eine Wache von Stormwind, also kann er auf sich selbst aufpassen, aber ich bin nur eine kleine Stadtbewohnerin - für mich ist das da draußen viel zu gefährlich!$B$BWenn Ihr ihm also sein Mittagessen bringt und anschließend wieder herkommt, dann bekommt Ihr auch ein Mittagessen von mir - umsonst! Parker patrouilliert die Straße, die in den Dämmerwald führt.",objectives={"Bringt Parkers Mittagessen zu Wache Parker. Er ist auf der Straße nach Dunkelhain auf Patrouille."}]])
R(130,"Besuch im Kräuterladen",[[description="Könnt Ihr Darcy ein paar Blumen von mir bringen, wenn Ihr wieder zu ihr geht? Die Blumen bekommt Ihr im Kräuterladen von Seenhain, am westlichen Ende des Ortes.$B$BAber wenn Ihr die Blumen holt, dann sagt Martie, der Kräuterkundigen, nicht, für wen sie bestimmt sind oder wer Euch beauftragt hat, ja?",objectives={"Sprecht mit der Kräuterkundigen des Rotkammgebirges, Martie Jainrose."}]])
R(131,"Narzissen für eine Dame",[[description="Hier habt Ihr Euren Blumenstrauß. Ich habe Narzissen für Euch ausgesucht. Narzissen sind meine Lieblingsblumen.",objectives={"Gebt Darcy den Narzissenstrauß."}]])
R(132,"Die Bruderschaft der Defias",[[description="Was ich Euch jetzt erzähle, könnte mich das Leben kosten. Die Bande der Defias plant irgendwas Großes. Das Letzte, was ich gehört habe, war, dass sie mit unterschiedlichen Gnollen, Kobolden und sogar Goblins zusammenarbeiten.$b$bBringt Stoutmantle diese Nachricht. Darin steht alles, was ich zu dem Thema sagen kann.",objectives={"Bringt Wileys Nachricht nach Westfall zu Gryan Stoutmantle."}]])
R(133,"Ein Ghulbildnis",[[description="Ich wohne so weit weg von der Stadt und dem Schutz, den sie bietet, dass es ein Wunder ist, dass die Ghuls und die wandelnden Toten mich noch nicht aufgefressen haben! Tatsächlich hat erst gestern ein Rudel Knochenkauer gegen die Wände meines Hauses gehämmert.$B$BIch möchte ein Bildnis herstellen - eine Art \"Vogelscheuche\", nur für Ghuls. Dafür brauche ich ein paar Ghulrippen. Die bekommt Ihr von Fleischfressern, Knochenkauern, Hirnfressern, Verfaulten und Seuchenverbreitern.$B$BWenn Ihr mir die Rippen beschafft, bezahle ich Euch in barer Münze.",objectives={"Sammelt 7 Ghulrippen und bringt sie zu Calvinius in seiner Hütte."}]])
R(134,"Ogerdiebe",[[description="Vor ein paar Wochen wurde ich von einer Bande Ogern angegriffen, als ich draußen Kräuter sammelte, ziemlich weit von meinem Haus entfernt. Ich lief davon und musste eine Kiste mit wertvollen Werkzeugen und Kräutern zurücklassen.$B$BNachdem sie mich vertrieben hatten, stolzierten die Oger zurück zum Ogerhort im südlichen Dämmerwald. Ich bin mir sicher, dass meine Kiste irgendwo in der Nähe des Hügels sein muss.$B$BBitte, $n, beschafft mir diese Kiste wieder, denn sie fehlt mir sehr.",objectives={"Bringt Calvinius' Kiste zu Calvinius."}]])
R(135,"Die Bruderschaft der Defias",[[description="Ich möchte zu gern wissen, was Wiley meinte, als er die Steinmetze erwähnte. Vielleicht ist ihm da nur etwas rausgerutscht. Könnten die Defias irgendwas mit den Steinmetzen zu tun haben? Nur ein Mann weiß das mit Sicherheit: Mathias Shaw, Kopf von SI:7. Zeigt ihm Wileys Nachricht und stellt fest, ob er noch etwas zu diesem immer verzwickter werdenden Rätsel beitragen kann. Falls Ihr Probleme habt, Shaw zu finden, seht in der Kaserne in der Altstadt nach.",objectives={"Bringt Wileys Nachricht nach Stormwind zu Mathias Shaw."}]])
R(136,"Käpt'n Sanders Versteckter Schatz",[[description="Wenn Ihr das hier lesen tut, dann heißt das, dass der alte Käpt'n Sander in den Fluten begraben is'. Also tut mein Schatz jetz' Euch gehör'n, Ihr braucht bloß den Hinweisen folgen. $b$bErst müsst Ihr ma' meine Schließkiste finden. Wahrscheinlich is' die jetz' da an der Westküste von Westfall in der Nähe von dem Schiffswrack schon halb im Sand verschwunden. 's gibt da an der Küste massig Schiffswracks, aber bloß einen rostigen Anker. Wenn Ihr den Anker finden tut, dann habt Ihr auch meine Schließkiste gefunden. Da müsst ihr reingucken, denn da steht der nächste Hinweis drin.",objectives={"Findet Käpt'n Sanders Schließkiste und durchsucht sie, um den nächsten Hinweis zu erhalten."}]])
R(137,"<NYI> <TXT> Stormwind Commendation",[[description="If you earn a commendation from one of our Marshals, then bring it to me.  It will be good for one of our Lion Emblem gloves.",objectives={"General Marcus Jonathan in Stormwind will accept a commendation from Elwynn Forest.  Bringing him such a document will reward you with a choice of armor."}]])
R(138,"Käpt'n Sanders versteckter Schatz",[[description="Der Hinweis auf den Schatz lautet folgendermaßen: Gut gemacht, Kumpel! Jetz' müsst Ihr Euch imma nach Ost'n halten. Östlich von der Straße die Steilhänge hoch. Schaut Euch nach so 'nem ollen verfallenen Kamin nahe bei der Straße um. Dort findet Ihr'n altes Fass mit Eurem nächsten Hinweis drin.",objectives={"Findet das alte Fass in der Nähe des verfallenen Kamins und durchsucht es nach Eurem nächsten Hinweis."}]])
R(139,"Käpt'n Sanders Versteckter Schatz",[[description="Als Ihr das Fass durchsucht, findet Ihr ein weiteres Stück Pergament. Darauf steht: Also, von dem Fass dort müsst Ihr Euch nach Norden halten tun. Un' dann geht Ihr immer der Nase nach schnurstracks geradeaus, bis Ihr den leeren Henkelkrug sehen tut, der da irgendwo bei so 'ner einzeln stehenden Windmühle oben auf dem Steilhang über dem Meer liegt. Wenn Ihr Euch bei dem Henkelkrug umguckt, dann findet Ihr vielleicht sogar, was Ihr sucht.",objectives={"Durchsucht den leeren Henkelkrug neben der Windmühle nach dem nächsten Hinweis."}]])
R(140,"Käpt'n Sanders Versteckter Schatz",[[description="Und tatsächlich, ganz unten, fast am Boden des alten Henkelkruges findet sich der nächste Hinweis auf Sanders Schatz. An manchen Stellen ist die Tinte verwischt und das Papier riecht nach Whisky, aber zum Teil kann man den Text noch lesen: Jetz', wo Ihr mein'n alten Whiskykrug gefunden habt, habt Ihr den Schatz schon so gut wie in der Tasche. Von der Flasche aus müsst Ihr Euch einfach nach Westen halten und runter zum Strand geh'n. Und dann heißt es schwimmen! Schwimmt schnurstracks nach Westen, bis Ihr an der Insel seid, da wo meine Schatztruhe drauf is'!",objectives={"Findet Käpt'n Sanders Truhe und öffnet sie. Darin befindet sich Eure Belohnung."}]])
R(141,"Die Bruderschaft der Defias",[[description="Die Gilde der Steinmetze wurde von einem Mann namens Edwin van Cleef geführt. Van Cleef war dafür verantwortlich, dass Stormwind wieder aufgebaut wurde, nachdem die Orcs es im Ersten Krieg dem Boden gleichgemacht hatten. Anscheinend waren van Cleef und seine Leute nicht zufrieden damit, wie der König sie behandelte, nachdem der Wiederaufbau vollendet war. Das könnte den einen oder anderen Sachverhalt erklären.$b$bIch habe Eurem Meister in Westfall einen ausführlicheren Bericht geschrieben. Bringt ihn sofort zu ihm!",objectives={"Bringt Shaws Bericht nach Westfall zu Gryan Stoutmantle."}]])
R(142,"Die Bruderschaft der Defias",[[description="Wir müssen herausfinden, wo genau sich das Versteck der Defias befindet. $N, meine Späher berichten mir, dass ein Bote der Defias auf der Straße zwischen Moonbrook, dem Goldküstensteinbruch und dem Jangoschacht gesehen worden ist. Ich möchte, dass Ihr ihn fangt. Wenn er Widerstand leistet, tötet ihn und bringt mir alles, was er bei sich trägt.",objectives={"Spürt den Boten der Defias in Westfall auf und bringt die Nachricht, die er bei sich hat, zu Stoutmantle."}]])
R(143,"Botschaft nach Westfall",[[description="Irgendetwas stimmt mit der Armee von Stormwind nicht. Sie hätte längst mit einem größeren Aufgebot hier sein müssen. Doch Zeit ist ein Luxus, den wir nicht haben. Ich werde nicht dabeistehen und tatenlos zusehen, wie die Bewohner von Seenhain ihr Leben geben. Nein. Ich muss versuchen, von anderer Stelle her Hilfe zu gewinnen. Ich habe gehört, dass sich in Westfall eine Volksmiliz gebildet hat.$b$bBringt dieses Hilfegesuch ihrem Anführer, Gryan Stoutmantle. Vielleicht können Stoutmantles Männer uns hier unterstützen, bis der König Verstärkung schickt.",objectives={"Magistrat Solomon möchte, dass Ihr sein Hilfegesuch nach Westfall zu Gryan Stoutmantle bringt."}]])
R(144,"Botschaft nach Westfall",[[description="Es schmerzt mich, Magistrat Solomons Schreiben zu lesen. Offensichtlich hat er von dem Krieg, der hier in Westfall tobt, keine Ahnung. Sonst wäre er nicht so naiv, Hilfe von der Miliz zu erwarten. Wenn Stormwind nicht auch uns im Stich gelassen hätte, dann hätte es keinen Grund gegeben, die Miliz ins Leben zu rufen.$b$bBringt Eurem Herrn im Rotkammgebirge diese Antwort, $C. Und lasst ihn wissen, dass mir das Herz schwer wird, wenn ich an all die tapferen Leute denke, die ihr Leben verloren haben.",objectives={"Kehrt mit Gryan Stoutmantles Antwort zu Magistrat Solomon zurück."}]])
R(145,"Botschaft nach Dunkelhain",[[description="Ein weiteres Mal brauche ich Eure Hilfe. Ich habe an Lord Ebonlocke geschrieben und ihn gebeten, seine gut ausgebildete Nachtwache hierher zu schicken, damit diese bei der Verteidigung von Seenhain hilft. Es ist von ausnehmender Wichtigkeit, dass diese Nachricht ihn so bald wie möglich erreicht. Doch Ihr müsst äußerste Vorsicht walten lassen. Ebonlocke ist der Bürgermeister von Dunkelhain, und das liegt im Herzen des Dämmerwalds. Entfernt Euch nicht von der Straße.",objectives={"Magistrat Solomon möchte, dass Ihr einen Brief zu Lord Ebonlocke nach Dunkelhain bringt."}]])
R(146,"Botschaft nach Dunkelhain",[[description="Wenn mir Magistrat Solomon nicht persönlich bekannt wäre, würde ich sagen, der Mann hat den Verstand verloren. Die Nachtwache nach Seenhain schicken, weil Stormwind die Hilfe verweigert? Die Nachtwache wurde gegründet, weil Stormwind uns verließ, als diese elende Magie langsam das Land überzog. Wenn ich meine Nachtwache jetzt fortschicke, dann würde diese Stadt vom Bösen überrannt werden, noch ehe die Wachen den Waldrand erreicht hätten.$b$bBringt Eurem Meister in Seenhain dieses Antwortschreiben.",objectives={"Kehrt mit Lord Ebonlockes Antwortschreiben zu Magistrat Solomon zurück."}]])
R(147,"Menschenjagd",[[description="Wenn der \"Sammler\" Gold aus unseren Minen entnimmt, dann bestiehlt er das Königreich! Führt den Sammler seiner gerechten Strafe zu und bringt mir den Ring, der in dem Abholplan, den Ihr mir gegeben habt, erwähnt wurde.$B$BIm Abholplan steht, dass der Sammler sich am Brackwell-Kürbisbeet versteckt hält. Dort solltet Ihr nach ihm suchen.",objectives={"Findet den \"Sammler\" und tötet ihn, dann kehrt mit dem Ring des Sammlers zu Marshal Dughan zurück."}]])
R(148,"Lieferung aus Dunkelhain",[[description="Ach, was soll ich armer, alter Mann nur machen? Ich brauche einige Vorräte aus Dunkelhain, aber das Dorf ist so weit weg und ich bin so alt und schwach... ich würde die Reise niemals überstehen.$B$BKönnt Ihr nach Dunkelhain reisen und mir etwas Geisterhaarfaden mitbringen? Den bekommt Ihr im Haus von Madame Eva am Dorfplatz von Dunkelhain.",objectives={"Sprecht mit Madame Eva."}]])
R(149,"Geisterhaarfaden",[[description="Es gibt da einen armen, traurigen Geist, die blinde Mary, die in einem alten Bauernhaus in den Hügeln südlich von Dunkelhain spukt.$B$BHier, nehmt diesen spektralen Kamm und bittet die blinde Mary, sich die Haare zu kämmen. Bringt mir anschließend den Kamm zurück, dann entnehme ich ihm das Geisterhaar, das ich für den Faden brauche.$B$BUnd seht Euch vor, denn in der Nähe dieses Hauses lauern üble Dinge...",objectives={"Bringt der blinden Mary den spektralen Kamm."}]])
R(150,"Murlocwilderer",[[description="Die Murlocs werden zu einem Problem. Große Gruppen der Fischwesen werfen entlang der Ufer des Immerruhsees Anker und fischen, was das Zeug hält! Sie müssen verschwinden, ehe sie den ganzen See leer gefischt haben.$B$BGeht Murlocs jagen! Bringt mir 8 ihrer Flossen, dann habe ich vielleicht etwas für Euch...",objectives={"Bringt 8 Murlocflossen nach Seenhain zu Dockmeister Baren."}]])
R(151,"Die arme Graumähne",[[description="Die arme Graumähne! Das arme Pferd ist völlig entkräftet nach all der Arbeit, die wir ihm aufgebürdet haben. Ich habe es gefüttert, ehe wir den Hof verließen, aber wir haben natürlich nicht damit gerechnet, dass uns der Wagen kaputtgehen würde. Wenn Ihr der Stute ein paar Hände voll Hafer vom Feld bringen könntet, wäre ich Euch dankbar.$B$BIch wette, es lässt sich rund um die Höfe in Westfall etwas Hafer finden; Ihr müsst nur diesen entsetzlichen Maschinen aus dem Weg gehen, die hier alles übernommen haben. Es gibt einige Höfe südwestlich von hier.",objectives={"Verna Furlbrow in Westfall möchte, dass Ihr ihr 8 Hände voll Hafer bringt."}]])
R(152,"Ärger an der Küste",[[description="Die vielen Schiffswracks entlang der Küste sind Euch ja vermutlich schon aufgefallen. Das Große Meer ist überaus tückisch. Die Küste von Westfall muss freigehalten werden, damit die Seeleute sicher sind, wenn sie unsere Ufer erreichen. Aber die Murlocs sind ein Problem.$b$bTötet 7 Gezeitenjäger, 7 Krieger, 7 Orakel und 7 Küstenläufer, dann sorge ich dafür, dass Ihr belohnt werdet.",objectives={"Tötet 7 Gezeitenjäger, 7 Krieger, 7 Orakel sowie 7 Küstenläufer und kehrt dann zu Captain Grayson beim Leuchtturm von Westfall zurück."}]])
R(153,"Rote Lederkopftücher",[[description="Die Defias sind ständig in Bewegung. Ich überwache ihre Aktivitäten jetzt schon seit einiger Zeit. Und dabei habe ich festgestellt, dass viele Bandenmitglieder an den roten Lederkopftüchern zu erkennen sind, die sie tragen.$b$bBringt mir 15 dieser Kopftücher, dann werde ich dafür sorgen, dass Ihr belohnt werdet.",objectives={"Bringt 15 rote Lederkopftücher auf die Späherkuppe zu Späher Galiaan."}]])
R(154,"Rückkehr mit dem Kamm",[[description="NEIN!!!!!$B$BNehmt ihn weg, nehmt diesen Kamm weg!$B$BIch bin ein Monster und niemand wird mich jemals wieder für schön halten!",objectives={"Bringt den Geisterhaarkamm zu Madame Eva nach Dunkelhain."}]])
R(155,"Die Bruderschaft der Defias",[[description="Stoutmantle denkt also wirklich, ein $R wie Ihr könne mich beschützen? Tja, Ihr werdet wohl reichen müssen. Bringt am besten ein paar Freunde mit. $b$bIhr wisst ja, wie's läuft, oder? Ihr haltet mir den Rücken frei und ich bringe Euch zum Versteck der Defias. Aber Ihr solltet besser in meiner Nähe bleiben, denn die Bande der Defias will jetzt meinen Kopf. Wenn die mich mit Euch sehen, werden sie versuchen, mich umzubringen.$b$bSagt mir einfach Bescheid, wenn Ihr und irgendwelche Freunde, die Ihr noch zusammentrommeln könnt, bereit seid loszuziehen.",objectives={"Eskortiert den Verräter der Defias zum Geheimversteck der Defiasbruderschaft. Sobald der Verräter der Defias Euch gezeigt hat, wo sich van Cleef und seine Männer aufhalten, kehrt Ihr mit der Information zu Gryan Stoutmantle zurück."}]])
R(156,"Das Sammeln von Faulblüten",[[description="Wenn Ihr mir ein paar Faulblüten bringt, dann kann ich Euch einen Kessel Zombiesaft brauen.$B$BFaulblüten wachsen an seltsamen Orten. Vor allem, habe ich gehört, findet man sie in den Schädeln von Skelettschrecken und Skelettsatanskreaturen - nicht, dass ich selbst schon mal nah genug dran war, um nachzusehen!$B$BDer Friedhof von Rabenflucht und die stillen Gärten sind voll von diesen Skeletten. Wenn Ihr die auf Eurer Suche nach den Faulblüten auch noch dezimiert, dann schlagt Ihr zwei Fliegen mit einer Klappe, und ganz Dunkelhain wäre Euch dankbar.",objectives={"Sammelt 8 Faulblüten und bringt sie nach Dunkelhain zu Schankwart Smitts."}]])
R(157,"Abliefern des Fadens",[[description="Hier ist Euer Faden, $n. Man kann tausend Dinge damit machen, zum Beispiel böse Geister binden oder unbelebte Gegenstände mit Leben erfüllen.",objectives={"Bringt Calvinius den Geisterhaarfaden in seine Hütte nördlich des Friedhofs von Rabenflucht."}]])
R(158,"Zombiesaft",[[description="Ich brauche eine Flasche eines bestimmten Schnapses, und zwar Zombiesaft. Schankwart Smitts aus der Taverne Zum roten Raben in Dunkelhain sollte welchen haben.$B$BUnd bitte sputet Euch, $N. Die Nächte sind kalt und ich brauche den Schnaps, um meine Adern wieder mit Feuer zu erfüllen!",objectives={"Sprecht mit Schankwart Smitts."}]])
R(159,"Saftlieferung",[[description="Hier habt Ihr Euren Zombiesaft...$B$B... aber passt mir mit dem Zeug auf. Es ist stark genug, um die Toten zu erwecken!",objectives={"Bringt Calvinius den Zombiesaft in seine Hütte."}]])
R(160,"Ein Brief für den Bürgermeister",[[description="Bringt diese Nachricht zu Ello Ebonlocke, dem Bürgermeister von Dunkelhain.$B$BEr und ich sind alte Freunde, und wenn er den Zettel liest und herausfindet, was Ihr für mich getan habt... dann freut er sich bestimmt genauso sehr, wie ich das tue! Hahahaha!",objectives={"Bringt Calvinius' Brief zu Ello Ebonlocke, dem Bürgermeister von Dunkelhain."}]])
R(161,"Eine dunkle Bedrohung",[[description="Falls mein Verdacht sich bestätigt, ist dies eine Art Sprengpulver. Es muss von einem Sprengstoffexperten analysiert werden, damit wir genau wissen, mit was wir es hier zu tun haben. Ashlan Stonesmirk wurde dem Regiment zugeteilt, das Dun Modr und den Thandol-Übergang bewachen soll. Ihr müsst für mich eine schwierige und gefahrvolle Reise auf Euch nehmen, $N.$b$bReist durch das Algaz-Tor, folgt der Straße durch das Sumpfland und sucht Stonesmirk in Dun Modr auf. Folgt meinem Rat: Bleibt auf den Straßen und lasst Euch nicht zum Anhalten bewegen!",objectives={"Chefingenieur Hinderweir möchte, dass Ihr das sonderbar riechende Pulver nach Dun Modr zu Ashlan Stonesmirk, dem Sprengstoffexperten, bringt."}]])
R(162,"Aufstieg der Silithid",[[description="Ihr solltet mit diesem Bericht zu jemandem gehen, der ausreichend Kenntnis von solchen Dingen hat.$B$BIch kenne da diese Nachtelfen-Gelehrte namens Gracina Spiritmight. Sie hat viel Zeit mit dem Studium der Lebensformen verbracht, die in der Ökologie von Azeroth einzigartig sind, und sie ist noch dazu Historikerin! Wenn Euch jemand dabei helfen soll herauszufinden, was genau diese Bedrohung ausmacht, und noch viel wichtiger, wie sie zu stoppen ist, gebt ihr den Bericht. Wir werden die Hilfe brauchen.$B$BDas Letzte, was ich hörte, war, dass sie im Tempel des Mondes in Darnassus lebt.",objectives={"Bringt den Insektenanalysebericht nach Darnassus zu Gracina Spiritmight."}]])
R(163,"Rabenflucht",[[description="Irgendetwas stimmt nicht in Rabenflucht, $n. Calor schwört, dass jemand - oder etwas - in den Gebäuden dort umgeht. Zwei Nächte in Folge hat er jetzt schon gesehen, wie sich die Schatten bewegten, und in der Nacht vorher habe er Licht in einem der Fenster gesehen, sagte er.$b$bWenn Euch, wie Ihr sagt, die Sicherheit des Dämmerwalds am Herzen liegt, dann findet heraus, welches Monster in Rabenflucht umgeht.",objectives={"Findet heraus, was in Rabenflucht umgeht."}]])
R(164,"Lieferung an Sven",[[description="Kennt Ihr Sven? Das ist mal ein Mann, der das Werk des Lichtes vollbringt! Er und seine Anhänger haben ein Lager am nordwestlichen Rand des Dämmerwalds.$b$bLeider sind sie so wenige, dass noch nicht einmal ein einziger Mann abkömmlich ist, um Vorräte aus der Stadt zu holen. Würdet Ihr diese Vorräte bei ihm abliefern?",objectives={"Liefert die Vorräte an Sven."}]])
R(165,"Der Einsiedler",[[description="Es gab einmal einen alten Mann, der recht häufig in die Stadt kam, um Vorräte einzukaufen, aber ich habe ihn jetzt schon ziemlich lange nicht mehr gesehen. Er lebt draußen in einer Hütte, von der aus man den Friedhof von Rabenflucht überblicken kann, wenn ich mich recht erinnere. Vielleicht solltet Ihr einmal nachsehen gehen, ob dort alles in Ordnung ist.",objectives={"Schaut in der Nähe des Friedhofs von Rabenflucht nach dem alten Mann in der Hütte."}]])
R(166,"Die Bruderschaft der Defias",[[description="Jetzt gibt es für Euch nur noch eine Aufgabe zu erledigen. Edwin van Cleef muss getötet werden. Zwar stimmt es mich traurig, einen Menschen zum Tode zu verurteilen, doch es ist zum Besten des Volkes von Westfall, wenn van Cleef ein für alle Mal aus dem Verkehr gezogen wird. Bringt mir den Kopf des Schurken, sobald die Tat getan ist.",objectives={"Tötet Edwin van Cleef und bringt seinen Kopf zu Gryan Stoutmantle."}]])
R(167,"Oh Bruder...",[[description="Wir waren tief unten in einer großen Mine in Westfall, deren Eingang unter einer Scheune in Moonbrook versteckt lag. Keine Ahnung, wo dieses elende Diebesgesindel herkam. Egal, jedenfalls stürzte der Minentunnel über uns ein. Ich hab's nach draußen geschafft, aber die anderen ... na ja ... von den anderen hat seither niemand mehr etwas gehört.$b$bIhr seht aus, als könntet Ihr vielleicht etwas mehr Glück haben, wenn Ihr dort hineingeht. Wenn Ihr nach meinem Bruder suchen könntet, wäre ich Euch dankbar. Er trug immer sein Forscherliga-Abzeichen bei sich. Wenn Ihr ihn selbst nicht finden könnt, dann würde zumindest das Abzeichen mir etwas Seelenfrieden verschaffen.",objectives={"Bringt Großknecht Thistlenettles Forscherliga-Abzeichen nach Stormwind zu Wilder Thistlenettle."}]])
R(168,"Die Suche nach Andenken",[[description="Viele meiner Freunde starben an jenem schrecklichen Tag, als der Minentunnel einstürzte. Wenn Eure Abenteuer Euch in jenen Abschnitt der Mine in Moonbrook führen sollten, dann haltet doch bitte die Augen offen nach jedem Zeichen, anhand dessen man sie identifizieren könnte. Wenn Ihr zum Beispiel ihre Gewerkschaftsausweise finden solltet, so bringt sie mir, dann sehe ich zu, dass ihre Familien informiert werden und damit wenigstens eine Art Schlussstrich unter diesen schrecklichen Unfall ziehen können.",objectives={"Beschafft 4 Gewerkschaftsausweise und bringt sie nach Stormwind zu Wilder Thistlenettle."}]])
R(169,"GESUCHT: Gath'Ilzogg",[[description="Gesucht! Gath'llzogg, Rädelsführer hinter den Angriffen der Blackrock auf Burg Steinwacht und den Überfällen auf die Ortschaft Seenhain. $b$bGath'llzogg ist äußerst gefährlich. Berichten zufolge hat er sich in der kürzlich eroberten Burg eingenistet und plant dort die weiteren Verbrechen des Blackrockklans gegen die menschliche Bevölkerung. Die Orcplage muss um jeden Preis eingedämmt werden. Der tapferen Seele, die Magistrat Solomon den Kopf von Gath'llzogg übergeben kann, winkt eine großzügige Belohnung.",objectives={"Erledigt Gath'llzogg und bringt seinen Kopf zu Magistrat Solomon in Seenhain, um die Belohnung zu erhalten."}]])
R(170,"Eine neue Bedrohung",[[description="Ich hoffe, Ihr seid hier, um uns zu helfen, $C. Nach dem letzten Angriff der Troggs können wir alle Hilfe gebrauchen, die wir kriegen können.$b$bIch habe gehört, die kleinen Biester sind überall im ganzen Land aufgetaucht, und wie es scheint, ist das Coldridge-Tal keine Ausnahme. Sie sind kreuz und quer in den Hügeln im Südosten und in der Nähe des gefrorenen Sees gesehen worden.$b$bUnd das ist noch nicht alles. Vor ein paar Nächten haben sie unser Lager im Westen angegriffen und überrannt! $b$bWir haben hier zu wenig Leute, $gJungchen:Mädel;, und wir brauchen ein paar starke Arme, die dabei helfen, die Troggs zurückzutreiben.",objectives={"Balir Frosthammer möchte, dass Ihr 6 Troggs der Felsenkiefer und 6 bullige Troggs der Felsenkiefer tötet."}]])
R(171,"Tageseltern der Allianz",[[description="Ihr wart die ganze Zeit so gut zu mir, $n. Nie hätte ich erwartet, während der Kinderwoche so viel Spaß zu haben! Danke schön.$B$BIch wünschte, all die anderen Waisenkinder hätten das Glück, so tolle Dinge zu unternehmen, wie wir. Meint Ihr, wir können Craggle Schlingerkreisel wiederfinden und bekommen einen Schaumstoffschwertständer von ihm? Ich glaube, er schiebt noch immer seinen Karren an den Kanälen rund um den Handelsdistrikt herum. So könnten alle anderen im Waisenhaus ihren Spaß haben!$B$BDanach wird es Zeit für mich, nach Hause zu gehen.",objectives={"Kauft einen Schaumstoffschwertständer von Craggle Schlingerkreisel und bringt dann Euren Schützling in das Waisenhaus von Sturmwind zurück, indem Ihr die Pfeife des Menschenwaisenkindes an Waisenmatrone Nachtigall im Kathedralenviertel übergebt."}]])
R(172,"Die Kinderwoche",[[description="Ihr wollt uns tatsächlich hier im Waisenhaus zur Hand gehen? Seid gesegnet, Freund. Eure Unterstützung in der Kinderwoche ist für uns von unschätzbarem Wert.$B$BNehmt diese Pfeife. Sie kann sieben Tage lang verwendet werden - über die ganze Dauer der Kinderwoche hinweg. Durch Benutzung der Pfeife, könnt Ihr mit dem Waisenkind sprechen, auf das Ihr aufpasst. Verwendet sie erneut, um das Kind wieder zu entlassen.$B$BDas Kind ist schon ganz aufgeregt und freut sich darauf Euch kennenzulernen. Worauf wartet Ihr noch $n, benutzt die Pfeife und trefft Euren Schützling.",objectives={"Benutzt die Pfeife des orcischen Waisenkindes um während der Kinderwoche mit Eurem Schützling zu sprechen."}]])
R(173,"Worgs in den Wäldern",[[description="Es scheint, als würden dunkle Dinge unaufhaltsam in den Dämmerwald gezogen. Meister Carevin hat sich der Aufgabe verschrieben, das Böse und die Ketzerei zu vertreiben. Dank unserer Anstrengungen lebt das Volk von Dunkelhain in Sicherheit.$b$bIhr glaubt, Ihr seid würdig, Euch unserer Gruppe anzuschließen?$b$bEinst dachte ich wie Ihr. Die Selbstzufriedenheit der Wache hatte mich meiner Illusionen beraubt und so schloss ich mich Meister Carevin an. Wenn Ihr Euch beweisen möchtet, so kann dies nicht durch Worte geschehen.$b$bMesst Eure Fertigkeiten an den Schattenwirkern der Nachtheuler im Schattenhain und im verlassenen Obstgarten.",objectives={"Tötet für Calor aus Dunkelhain 6 Schattenwirker der Nachtheuler."}]])
R(174,"Der Blick zu den Sternen",[[description="Mein Freund Cog, der Gnom, hat mir versprochen, mir beim Bau eines Gerätes zu helfen, mit dem ich in die Sterne blicken kann. Jenseits der Magie existiert eine Wahrheit, mit deren Hilfe sich die seltsame Verwandlung des Waldes erklären lässt.$b$bBringt mir eine Bronzeröhre, die von einem geschickten Ingenieur hergestellt wurde. Wenn man nach Cogs Blaupause geht, ist das der erste Schritt.",objectives={"Viktori Prism'Antras aus Dunkelhain möchte, dass Ihr ihm eine Bronzeröhre bringt."}]])
R(175,"Der Blick zu den Sternen",[[description="Laut Cogs Blaupause brauche ich jetzt etwas, mit dem Licht reflektiert werden kann. Ich erinnere mich an eine Frau namens Mary, die hier in der Gegend eine gewisse Bekanntheit erlangte, weil sie immer einen Handspiegel bei sich trug. Vielleicht könnt Ihr diese Mary aufspüren und sie fragen, ob sie ihn uns für unser Vorhaben vielleicht leiht, weil wir ja eine reflektierende Oberfläche brauchen... Ich glaube, sie wohnte früher im südlichen Dämmerwald...",objectives={"Findet Mary und überredet sie, einen Gegenstand mit reflektierender Oberfläche zu Viktoris Projekt beizusteuern."}]])
R(176,"GESUCHT: \"Hogger\"",[[description="Gesucht: Hogger$B$BEin riesiger Gnoll, Hogger, streunt im südwestlichen Elwynn durch den Wald. Er hat bislang alle Versuche, ihn zu fangen, vereiteln können.$B$BDie Armee von Stormwind hat ein großzügiges Kopfgeld auf den Gnoll ausgesetzt. Kopfgeldjäger, die sich die Belohnung verdienen möchten, sollten einen Beweis für Hoggers Tod bei Marshal Dughan in Goldhain vorlegen.",objectives={"Erschlagt den Gnoll Hogger und bringt seine gewaltige Gnoll-Klaue zu Marshal Dughan."}]])
R(177,"Der Blick zu den Sternen",[[description="Der Handspiegel war eines meiner wertvollsten Besitztümer bis zu... dem Vorfall. Danach warf ich den Spiegel hinter der Scheune fort. Es gab da einen irrsinnigen Ghul, der sich früher dort hinten herumgetrieben hat. Vielleicht hat der ihn aufgehoben und mitgenommen. Gerüchten zufolge haust die teuflische Bestie im Friedhof \"Stille Gärten\".",objectives={"Nehmt dem irrsinnigen Ghul den Handspiegel der blinden Mary ab und gebt ihn Viktori in Dunkelhain."}]])
R(178,"Wiederbeschaffung für Theocritus",[[description="<Ihr hört eine körperlose Stimme:>$B$BIhr müsst nicht erschrecken. Ich bin Theocritus, Hochmagier des Turms von Azora im Wald von Elwynn. Der Anhänger, den Ihr in Händen haltet, ist ein Mittel zur Kommunikation zwischen den Schattenfellgnollen und Morganth, ihrem Meister.$B$BNach langen Monaten der Forschung glaube ich, dass nun auch ich durch diese Anhänger kommunizieren kann. Wenn Ihr diese Nachricht hören könnt, dann war mein Zauber erfolgreich.$B$BBringt mir diesen Anhänger und ich werde Euch für Eure Dienste belohnen.",objectives={"Bringt den verblassten Schattenfellanhänger zu Theocritus, dem Magier."}]])
R(179,"Zwergenausstatter",[[description="Was haben wir denn hier? Ihr seht aus, als könntet Ihr was brauchen, was Euch die Hände warm hält, hm?$b$bIch sag Euch, was da helfen würde: ein paar schöne, warme Handschuhe. Und weil ich so ein netter Kerl bin, geb ich Euch doch gern so ein Paar. Unter einer Bedingung, versteht sich.$b$bIhr müsst mir etwas Wolfsfleisch besorgen. Ist doch 'n guter Handel, oder? Ihr bringt mir etwas Wolfsfleisch und ich sorge dafür, dass Ihr Euch keine Frostbeulen an den Fingern holt. Na, was sagt Ihr?",objectives={"Sten Stoutarm hätte gern 8 Stücke zähes Wolfsfleisch."}]])
R(180,"GESUCHT: Lieutenant Fangor",[[description="Gesucht: Lieutenant Fangor$b$bBekannter Anführer des Gnollklans der Schattenfelle; arbeitet für Morganth, den Feind der Stadt und des Königreiches. Auf Geheiß von Magistrat Solomon wird der Tod dieses üblen Verräters an Stormwind gewünscht. Zeigt dem Magistraten seine Tatze zum Beweis, dass er tot ist.",objectives={"Tötet Lieutenant Fangor und kehrt mit seiner Tatze zu Magistrat Solomon nach Seenhain zurück."}]])
R(181,"Der Blick zu den Sternen",[[description="Jetzt brauchen wir nur noch einen weiteren Gegenstand, um das Gerät fertig zu stellen. Laut Cogs Blaupause wird eine Linse oder etwas in der Art benötigt. Die einzige Linse, von der ich weiß, dass sie groß genug wäre, wird sehr schwierig zu beschaffen sein.$b$bEs gibt da einen Oger namens Zzarc'Vul, der im Ogerhort im Süden des Dämmerwalds haust. Wenn Ihr könnt, bringt mir sein Monokel, dann werde ich das als unsere Linse verwenden.",objectives={"Findet Zzarc'Vul im südlichen Ogerhort des Dämmerwalds und bringt sein Monokel zu Viktori nach Dunkelhain."}]])
R(182,"Die Trollhöhle",[[description="Mein Bruder Senir und ich wurden in unterschiedliche Ecken von Dun Morogh entsandt, um dort die von den Trollen ausgehende Gefahr zu untersuchen. Der Senat hat mit den Troggs bereits alle Hände voll zu tun, deswegen kann er keinen weiteren Ärger gebrauchen.$b$bNach allem, was ich gesehen habe, ist die Position der Trolle hier im Coldridgetal nicht sonderlich gut - sie sind vor allem in der südlichen Höhle zu finden. Ich würde sagen, die Armee brauchen wir nicht. Einige starke Arme sollten mehr als ausreichend sein.$b$bMöchtet Ihr vielleicht mithelfen? Ich bin ermächtigt, Euch für Eure Dienste eine Entschädigung anzubieten.",objectives={"Grelin Whitebeard möchte, dass Ihr 14 Trollwelpen der Frostmane tötet."}]])
R(183,"Der Eberjäger",[[description="Es geht doch nichts über einen Tag auf der Eberjagd, wie?$b$bNa ja, hier im Coldridgetal gibt es so viele Eber, dass es fast schon keinen Spaß mehr macht. Man muss sie gar nicht mehr reizen. Sie sind schon aggressiv und angriffslustig, ohne dass man nachhilft. Um genau zu sein, streifen in letzter Zeit so viele Eber durch die Gegend, dass es gefährlich für mich geworden ist, auf die Jagd zu gehen.$b$bIch mach's kurz: Wenn Ihr mir dabei helfen könntet, einige der Eber zu töten, dann würde ich das zu schätzen wissen.",objectives={"Talin Keeneye möchte, dass Ihr 12 kleine Klippeneber tötet."}]])
R(184,"Furlbrows Urkunde",[[description="Dies ist eine Besitzurkunde für ein Stück Ackerland in Westfall. Es ist von einem gewissen Theodore Furlbrow und seiner Frau Verna unterzeichnet. Auf der Rückseite der Besitzurkunde stehen ein paar hastig hingekritzelte Worte:$B$B\"Wir haben Furlbrow etwas bearbeitet und ihm seine Besitzurkunde abgeluchst. Wäre vielleicht ganz nützlich, wenn Ihr Euch auch so eine fälschen wolltet.$B$BUm die Furlbrows müssen wir uns jedenfalls keine Sorgen machen. Zuletzt sah ich sie kurz hinter Westfall in einem Wagen mit gebrochener Achse.\"$B$BIhr denkt, die Furlbrows hätten ihre Besitzurkunde vielleicht gern zurück ...",objectives={"Bringt Furlbrows Besitzurkunde zu Bauer Furlbrow."}]])
R(185,"Beherrschen der Tigerjagd",[[description="Als ich noch ein kleines Mädchen war, brachte mein Vater mir die Kunst der Tigerjagd bei.$b$bIhr werdet feststellen, dass die jungen Katzen sich wesentlich leichter aufspüren und töten lassen. Deswegen fangen wir auch klein an. Man findet die jungen Tiger oftmals in der Nähe des Expeditionslagers.$b$bÜbt Euch im Fährtenlesen und seht zu, ob Ihr nicht einige der Wildtiere zur Strecke bringen könnt.",objectives={"Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 junge Schlingendorntiger tötet."}]])
R(186,"Beherrschen der Tigerjagd",[[description="Ihr macht Fortschritte, $C. Jetzt lasst uns sehen, wie Ihr Euch gegen die ausgewachsenen Katzen anstellt. Tötet diesmal 10 Schlingendorntiger.",objectives={"Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 Schlingendorntiger tötet."}]])
R(187,"Beherrschen der Tigerjagd",[[description="Jetzt werde ich den Einsatz erhöhen und Eure Fähigkeiten wirklich prüfen. Beweist mir, dass Ihr 10 alte Schlingendorntiger töten könnt. Wenn Ihr das schafft, dann seid Ihr bereit für Eure letzte Herausforderung, ehe ich Euch in Meister Nesingwarys Gegenwart $gzum Meisterjäger:zur Meisterjägerin; ernenne.$b$bNicht nur sind die alten Schlingendorntiger am schwierigsten zu finden, sie sind auch am schwierigsten zu besiegen.",objectives={"Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 alte Schlingendorntiger tötet."}]])
R(188,"Beherrschen der Tigerjagd",[[description="Hier ist die letzte Aufgabe, die ich Euch auferlegen werde. Wir sind schon seit Wochen einer schwer zu fassenden Tigerin auf der Spur. Wir nennen das Tier Sin'Dall. Vielleicht gelingt Euch ja, was noch kein $R vor Euch geschafft hat: Spürt Sin'Dall auf und bringt sie zur Strecke. Bringt mir ihre Tatze zum Beweis für Eure Leistung.$b$bAber die Tigerin aufzuspüren, wird nicht leicht sein.",objectives={"Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr Sin'Dall tötet und mit ihrer Tatze zurückkehrt."}]])
R(189,"Ohren der Bloodscalp",[[description="Verdammte Trolle! Sie haben im Dschungel schon etliche unserer Agenten getötet und ich habe bereits einige meiner besten Wachen in Scharmützeln mit ihnen verloren. Was das alles kostet! Wie soll ich das nur Baron Revilgaz erklären?$b$bEntschieden handeln... Denk nach, Kebok... Du bist auf den Posten, den du heute hast, nicht durch Rumsitzen gekommen... Ha, ich hab's! Ihr... $N, richtig? Ihr helft mir doch, oder? Es gibt auch Geld zu verdienen!$b$bFolgender Handel... Ihr bringt mir die Ohren von 15 Trollen der Bloodscalp und ich bezahle Euch gut dafür.",objectives={"Verschafft Euch 15 Ohren der Bloodscalp und bringt sie Kebok in Booty Bay."}]])
R(190,"Beherrschen der Pantherjagd",[[description="Wenn Ihr zusammen mit dieser Elitegruppe, die Hemet zusammengestellt hat, an der Jagd teilnehmen wollt, dann müsst Ihr erst beweisen, dass Ihr $gein fähiger Pantherjäger:eine fähige Pantherjägerin; seid. Aber wir fangen ganz einfach an, keine Sorge. Schauen wir mal, wie Ihr Euch beim Töten von 10 jungen Panthern anstellt.$b$bDie Tiere aufzuspüren ist nur die halbe Miete.",objectives={"Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr 10 junge Panther tötet."}]])
R(191,"Beherrschen der Pantherjagd",[[description="Jetzt seid Ihr bereit, Euch an einen Gegner zu wagen, der eine Nummer schwieriger ist. Wenn Ihr Euch wirklich als würdig erweisen wollt, mit solchen Leuten wie den Großwildjägern zu verkehren, dann müsst Ihr beweisen, dass Ihr 10 Panther töten könnt.$b$bDiese Bestien sind schon etwas zäher. Die lassen sich nicht so leicht erlegen wie die Jungtiere, mit denen Ihr Euch bis jetzt abgegeben habt.",objectives={"Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr 10 Panther tötet."}]])
R(192,"Beherrschen der Pantherjagd",[[description="Jetzt kommt der schwierige Teil. Ein echter Pantherjäger beweist seine Fähigkeiten damit, dass er Schattentatzenpanther erlegt, die tödlichsten Vertreter ihrer Art im ganzen Schlingendorntal. Beweist uns, dass Ihr 10 dieser Bestien zur Strecke bringen könnt.$b$bUnd wenn Ihr glaubt, die seien schwer aufzuspüren, dann wartet nur, bis Ihr versucht, eine von ihnen zu erlegen...",objectives={"Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr 10 Schattentatzenpanther tötet."}]])
R(193,"Beherrschen der Pantherjagd",[[description="Ihr habt schon fast bewiesen, dass Ihr die Kunst der Pantherjagd meisterlich versteht. Schon seit längerem pirscht ein Panther namens Bhag'thera durch den Dschungel. Bis jetzt ist er unserer Jagdgesellschaft immer ausgewichen. Seht zu, ob es Euch mit Euren Fähigkeiten gelingt, den großen Bhag'thera zu töten.$b$bBringt mir den Fangzahn von Bhag'thera, dann habt Ihr Euch meinen Respekt redlich verdient!",objectives={"Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr ihm den Fangzahn von Bhag'thera bringt."}]])
R(194,"Beherrschen der Raptorenjagd",[[description="Soso, Ihr glaubt also, Eure Jagdfertigkeiten sind erstklassig? Das lässt sich ganz leicht feststellen. Zieht hinaus in den Dschungel und tötet 10 Schlingendornraptoren. Dann werden wir ja sehen, wie gut Ihr als Großwildjäger wirklich seid.$b$bUnd nein, ich werde Euch nicht sagen, wo Ihr sie finden könnt! Die Viecher aufzuspüren ist Teil der Aufgabe.",objectives={"Hemet Nesingwary möchte, dass Ihr 10 Schlingendornraptoren tötet."}]])
R(195,"Beherrschen der Raptorenjagd",[[description="Jetzt machen wir die Herausforderung ein wenig schwieriger und schauen mal, ob Ihr dem gewachsen seid. Begebt Euch in den Dschungel und erlegt 10 dieser elenden Schmetterschwanzraptoren. Zeigt uns, was Ihr so drauf habt!",objectives={"Hemet Nesingwary möchte, dass Ihr 10 Schmetterschwanzraptoren tötet."}]])
R(196,"Beherrschen der Raptorenjagd",[[description="Mal sehen, wie Ihr mit der nächsten Herausforderung fertig werdet. Dort draußen treibt sich eine sehr scheue Art von Raptoren herum. Wir nennen sie Dschungelpirscher. Sie sind sehr viel schwieriger aufzuspüren und zu erlegen als die anderen Arten, an denen Ihr Euch bisher versucht habt. Tötet 10 Dschungelpirscher, dann verrate ich Euch, wie Ihr zu einem noch besseren Jagderlebnis kommt.",objectives={"Hemet Nesingwary möchte, dass Ihr 10 Dschungelpirscher tötet."}]])
R(197,"Beherrschen der Raptorenjagd",[[description="Da Ihr Euch im Dschungel als so tatkräftig erwiesen habt, lasst mich Euch von einem wilden Raptor erzählen, den sogar ich nicht erlegen konnte. Ajeck hier nennt diesen verschlagenen Raptor Tethis.$b$bWenn Ihr Euch als $gwahrer Meister:wahre Meisterin; erweisen wollt, dann erlegt Tethis und bringt mir seine Kralle. Es wäre eine Leistung, die bisher noch keinem anderen Großwildjäger gelungen ist.",objectives={"Hemet Nesingwary möchte, dass Ihr Tethis tötet, einen schwer fassbaren, gefährlichen Raptoren des Schlingendorntals."}]])
R(198,"Vorräte für den Gefreiten Thorsen",[[description="Hmm. Ja, es gibt tatsächlich etwas, das Ihr tun könntet. Lieutenant Doren und seine Leute oben im Norden warten auf ihre turnusmäßige Vorratslieferung von uns.$b$bDie Vorräte wurden noch nicht bei ihnen abgeliefert und jetzt, wo die Trolle ständig angreifen, brauche ich jemanden, der das erledigt. Dorens Lager liegt im Nordwesten der Straße, dort, wo man vom Dämmerwald aus ins Schlingendorntal kommt. Gebt die Vorräte dem Gefreiten Thorsen. Wenn er nicht im Lager ist, dann patrouilliert er südlich davon. Er wird sie in Empfang nehmen und verstauen.$b$bAber dass eines klar ist: Wenn Ihr versagt, dann müsst Ihr mir Ersatz leisten.",objectives={"Liefert die verschiedenen Goblin-Vorräte bei dem Gefreiten Thorsen ab."}]])
R(199,"Eine dunkle Bedrohung",[[description="Ihr nehmt eine Probe von dem sonderbar riechenden Pulver.",objectives={"Kehrt zu Chefingenieur Hinderweir zurück und zeigt ihm den Hinweis, den Ihr entdeckt habt."}]])
R(200,"Buchmacher Herod",[[description="Wenn Kurzen Thorsens Geheimnis kennt, dann haben wir einen Spion in unseren Reihen. Wir müssen herausfinden, wie das Geheimnis verraten werden konnte!$B$BThorsens Kontaktperson in Kurzens Lager war der Buchhalter Herod. Herod ist Kurzens Nachschuboffizier und weiß alles über den Betrieb in Kurzens Truppenlager. Wenn Ihr Herods Unterlagen oder Aufzeichnungen beschaffen könntet, dann finden wir vielleicht heraus, wie Thorsen entdeckt werden konnte.$B$BAls wir noch unter Kurzen dienten, war das Büro des Buchhalters im oberen Stock des einzigen zweistöckigen Gebäudes im Lager. Seine Aufzeichnungen sind vermutlich immer noch dort zu finden.",objectives={"Findet Buchhalter Herods Aufzeichnungen."}]])
R(201,"Untersuchung des Lagers",[[description="Ich habe Berichte gehört, nach denen eine Gruppe von Jägern ihr Lager flussaufwärts vom Bergbaucamp der Venture Company am Nazferitisee aufgeschlagen hat. Das wäre mir normalerweise völlig egal, aber ich habe gehört, dass Hemet Nesingwary einer der Jäger dort sein soll. Das ist zwar absolut unwahrscheinlich, aber... na ja, er hat sehr gute Beziehungen, wenn Ihr wisst, was ich meine, und man kann nie vorsichtig genug sein.$B$BWollt Ihr nicht hin und Euch das Lager einmal anschauen, $N, und sehen, was die vorhaben?",objectives={"Lokalisiert das Jägerlager und teilt dann Krazek in Booty Bay mit, wo es sich befindet."}]])
R(202,"Colonel Kurzen",[[description="Ihr habt Euren Wert wieder und wieder unter Beweis gestellt und Euer Einfallsreichtum scheint sich mit dem von Kurzen selbst messen zu können. Ihr könntet die Rettung für unseren Rebellentrupp sein... falls Ihr Euch gegen Kurzen stellen und siegen könnt!$B$BEr erteilt die Befehle an seine Männer von tief aus dem Vorratslager heraus. Ihr müsst Euch Zutritt zu dieser Höhle verschaffen, an seinen Verteidigern vorbei, und dann Kurzen und seinen Führungsoffizieren gegenübertreten.$B$BLebt wohl, $n. All meine Hoffnung, ebenso das Schicksal meiner Männer, ruht in Euren Händen.",objectives={"Tötet 6 von Kurzens Elitesoldaten, 4 von Kurzens Stabschefs und bringt Kurzens Kopf ins Rebellenlager zu Lieutenant Doren."}]])
R(203,"Die zweite Rebellion",[[description="Wir kämpfen einen aussichtslosen Kampf gegen Colonel Kurzen. Nicht nur, dass der Mann ein brillanter Taktiker ist, seine Männer sind uns auch noch zahlenmäßig mindestens 10 zu 1 überlegen! Um überleben zu können, müssen wir seine eigenen, auf Heimlichkeit basierenden Taktiken gegen ihn anwenden.$B$BBetretet sein Lager im Osten und tötet seine Leute. So viele Ihr könnt. Und verschwindet wieder, bevor seine Verstärkung Euch in die Zange nehmen kann.",objectives={"Tötet 15 von Kurzens Dschungelkämpfern.$B$BKehrt ins Rebellenlager zu Sergeant Yohwa zurück."}]])
R(204,"Schlechte Medizin",[[description="Um überhaupt eine Chance gegen Kurzen zu haben, müssen wir ihm die Möglichkeiten beschneiden, seine Truppen zu heilen. Er hat um sich eine große Anzahl an Medizinmännern versammelt, die seine Streitkräfte mit Dschungelarzneien heilen und unsere Kämpfer mit Giftfarnextrakt vergiften.$B$BWir brauchen dieses Arzneien, um unsere eigenen Leute zu heilen, und wir brauchen eine Probe dieser Extrakte, damit wir sie untersuchen und unser eigenen Arzneien herstellen können. Sucht in Kurzens Truppenlager nach beidem: Seine Medizinmänner haben die Arzneien und die Extrakte werden vermutlich irgendwo in den Vorratskästen im Lager verstaut sein.",objectives={"Bringt Sergeant Yohwa im Rebellenlager 7 Dschungelarzneien und 1 Giftfarnextrakt."}]])
R(205,"Troll-Hexerei",[[description="Während ich die Legenden studiere, die Ihr beschafft habt, sammelt bitte für mich die Gerätschaften der bösen Trollmagie. Begebt Euch in das Gebiet der Skullsplittertrolle, eines zweiten Stammes weit entfernt im Süden, und beschafft Euch dort Fetische der Skullsplitter von ihren Hexendoktoren und Mystikern.",objectives={"Bringt Bruder Nimetz 4 Fetische der Skullsplitter ins Rebellenlager."}]])
R(206,"Mai'Zoth",[[description="Kurzen mag vielleicht tot sein, doch das, was ihn zum Bösen trieb, ist noch am Leben! Mittels meiner Studien habe ich Folgendes entdeckt: Ein Ogermagier namens Mai'Zoth lebt in einem Ogerhort in den östlichen Bergen des Schlingendorntals. Gerüchten zufolge wendet er Magie an, mit deren Hilfe er in die Gedanken anderer eindringen und diese kontrollieren kann, und ich bin mir sicher, dass er es war, der Kurzen verderbt hat.$B$BBleibt Mai'Zoth am Leben, dann beeinflusst er vielleicht noch andere und vielleicht würde dann sogar ein zweiter Kurzen entstehen.$B$BTötet ihn und bringt mir sein Gedankenauge, das Artefakt, mit dem er andere Wesen verderbt.",objectives={"Bringt das Gedankenauge zu Bruder Nimetz ins Rebellenlager."}]])
R(207,"Das Geheimnis um Kurzen",[[description="Colonel Kurzen war einst ein großer, ein edler Mann - ich muss herausfinden, wie es zu seiner Entartung kommen konnte! Es ist möglich, dass er dem Einfluss von Trollmagie unterliegt. Um diesen Verdacht zu bestätigen, muss ich einige ihrer Legenden studieren.$B$BIn den Trollruinen des Schlingendorntals liegen 4 Schrifttafeln versteckt. Ich muss wissen, was auf diesen Tafeln geschrieben steht! Schreibt die Zeichen ab, die Ihr auf den Tafeln findet, und bringt mir die Abschriften.$B$BDie erste Schrifttafel befindet sich in den Ruinen von Bal'lal, die zweite im Finsteren Riff und die dritte und vierte Schrifttafel findet Ihr in den Ruinen von Zul'Kunda.",objectives={"Findet die 4 Schrifttafeln und bringt ihre Legenden zu Bruder Nimetz zurück."}]])
R(208,"Großwildjagd",[[description="$N, Ihr seid $gein Jäger, der:eine Jägerin, die; unserer Gesellschaft wahrlich würdig ist. Von den Schlachtfeldern von Lordaeron bis in den tiefsten Dschungel hinein habe ich selten jemanden gesehen, der so geschickt mit den Waffen umgegangen ist wie Ihr.$b$bIhr habt die furchterregende Sin'Dall, den schwer fassbaren Bag'thera und die tückische Tethis erlegt. Doch die wahre Trophäe ist der Kopf von König Bangalash. Dieser weiße Tiger ist der Grund, warum ich hier bin. Ich habe schon seit geraumer Zeit ein Auge auf ihn geworfen. Wenn Ihr König Bangalash tötet, dann steht ein für alle Mal fest, dass Euer jägerisches Können von niemandem übertroffen wird.",objectives={"Hemet Nesingwary möchte, dass Ihr ihm den Kopf von König Bangalash, dem großen weißen Tiger, bringt."}]])
R(209,"Hauer der Skullsplitter",[[description="Es ist teuer und anstrengend, genug Tiger zu töten, um damit den Bedarf an Tigerzähnen für den Export auf die Inseln in den südlichen Meeren decken zu können. Glücklicherweise haben wir eine gewisse Technik entwickelt, mit deren Hilfe wir aus einfachem hornähnlichen Material nicht nachweisbare Fälschungen herstellen können.$b$bErstaunlicherweise eignen sich die Hauer von Skullsplittertrollen dafür am besten.$b$bUnd bevor Ihr irgendwas sagt - was der Käufer nicht weiß, macht ihn nicht heiß, hab ich nicht Recht? Bringt mir so viele Hauer wie möglich, damit wir mit der monatlichen Lieferung anfangen können!",objectives={"Besorgt 18 Hauer der Skullsplitter und bringt sie zu Kebok."}]])
R(210,"Kochen mit Krazek",[[description="Meistens bin ich es, der hier im Lager kocht. Und das war auch immer ganz schön viel Arbeit, bis ich von einem Goblin-Händler in Booty Bay einen mechanischen Kochtopf gekauft habe. Der Topf ist einfach unglaublich. Er hat mir unzählige Stunden Arbeit erspart - bis er kaputtgegangen ist!$B$BKönnt Ihr den Topf dem Goblin zurückbringen, damit er ihn mir repariert? Der Händler heißt Krazek.",objectives={"Bringt Krazeks Spezialtopf zu Krazek, dem Goblin."}]])
R(211,"Weh dir, Andorhal",[[description="Endlich ist die Zeit gekommen, Andorhal anzugreifen und den Lich, der die Stadt kontrolliert, zu vertreiben.$B$BIhr habt vielleicht einen Beschwörungskristall in den von Euch markierten Wachtürmen bemerkt. Wir glauben, dass diese dem Lich die Kraft geben, die er zur Kontrolle der Stadt benötigt. Ihr müsst alle vier ausschalten. Wird einer davon zerstört, dürfte das zweifellos weitere Truppen des Lichs auf den Plan rufen. Wenn alle vier vernichtet wurden, dürfte der Lich selbst auftauchen, um das Herz der Stadt zu verteidigen.$B$BVernichtet den Lich, $n, und bringt mir einen Splitter seines Phylakteriums als Beweis!",objectives={"Bringt den Splitter von Arajs Phylakterium zu Kommandant Ashlam Valorfist auf der Chillwindspitze in den westlichen Pestländern."}]])
R(212,"Eine kalte Mahlzeit",[[description="Eines meiner berühmtesten Gerichte ist gekühlter Basilisk an Limonenvinaigrette. Das Problem ist nur: Das Fleisch lässt sich unmöglich frisch halten und ich muss das Gericht heute Abend anlässlich des Geburtstags eines Edelmannes servieren!$B$BWenn Ihr mir also schnell einen gekühlten Basiliskenschenkel von einem frisch getöteten Kaltaugenbasilisken bringen könnt, dann schulde ich Euch ein Festessen, das eines Königs würdig wäre!$B$BKaltaugenbasilisken streifen durch die Stranddünen im Nordwesten des Schlingendorntals, also habt Ihr eine lange Reise vor Euch. Und macht schnell!",objectives={"Tötet einen Kaltaugenbasilisken, beschafft Euch einen gekühlten Basiliskenschenkel und bringt ihn Angus Stern im Blauen Eremiten.$B$B<Um diese Aufgabe erfolgreich abschließen zu können, dürft Ihr Euren Geist nicht freigeben.>"}]])
R(213,"Feindliche Übernahme",[[description="Diesmal ist er zu weit gegangen! Schlimm genug, dass Gelriz dabei ist, die von den Handelsfürsten eingesetzten Moguln rauszudrängen, jetzt versucht er auch noch, den berüchtigtsten aller Piraten mit hineinzubringen!$b$bDas lässt Revilgaz sich nicht bieten und er hat mir aufgetragen, das Problem auf meine Weise zu lösen.$b$bWas meine Weise ist? Diebstahl, ganz einfach. Die Geologen der Venture Company zeigen ein auffälliges Interesse an den seltsamen blauen Kristallen, die sie bisweilen in den Minen finden. Bringt mir einige Proben dieser Steine von den Geologen; es ist mir völlig egal, was Ihr tun müsst, um an sie heranzukommen.",objectives={"Beschafft 8 gerommelte Kristalle und bringt sie nach Booty Bay zu Kebok."}]])
R(214,"Rote Seidenkopftücher",[[description="Es ist kein Geheimnis, dass das Markenzeichen der Defiasbande ihre roten Kopftücher sind. Aber wir haben herausgefunden, dass das Material, aus dem diese Kopftücher gemacht sind, den Rang des Bandenmitglieds bezeichnet.$b$bJetzt, wo wir das wissen, möchte ich, dass Ihr so viele hochrangige Mitglieder der Defias eliminiert, wie Ihr könnt. Die Bandenmitglieder mit der höchsten Position findet Ihr zweifellos in van Cleefs Geheimversteck. Wenn Ihr fertig seid, bringt mir 10 rote Seidenkopftücher zum Beweis, dass sie tot sind, dann werde ich Euch belohnen. Viel Glück, $n.",objectives={"Späherin Riell am Turm auf der Späherkuppe möchte, dass Ihr ihr 10 rote Seidenkopftücher bringt."}]])
R(215,"Geheimnisse im Dschungel",[[description="Danke, dass Ihr mich gerettet habt, $N. Ich weiß, wie es aussieht, aber lasst mich bitte erklären!$B$BIch hatte von Lieutenant Doren den Auftrag erhalten, mich wieder Kurzens Männern anzuschließen. Ich sollte sie ausspionieren und den Rebellen Informationen bringen, die sie bitter benötigen. Was Ihr hier miterlebt habt, war das, was ich für meine Chance hielt, Kurzens Truppenlager zu infiltrieren. Ich habe mich geirrt und ich muss Euch nochmals danken, dass Ihr mich gerettet habt.$B$BDiese Mission war streng geheim, Ihr dürft also niemandem davon erzählen. Aber wenn Ihr mit Doren sprecht, dann wird der Euch alles erklären.",objectives={"Sprecht im Rebellenlager mit Lieutenant Doren."}]])
R(216,"Hart auf hart",[[description="Die Distelfellfurbolgs bedrohen unsere Expansion! Das Lager der Distelfelle östlich von uns blockiert den Weg zwischen uns hier und dem Splintertreeposten. Dieser Weg würde das Dorf Astranaar umgehen; ohne ihn überlassen wir der Allianz eine zusätzliche Möglichkeit der Ausbreitung.$B$B$N, wir dürfen keine Lücke in unseren Expansionspfaden erlauben!$B$BBegebt Euch ins Distelfelllager und dünnt die Furbolgs etwas aus. Ihr werdet für diese Aufgabe entschädigt werden, aber noch viel wichtiger ist, dass Ihr Eure Pflicht der Horde gegenüber tun werdet.",objectives={"Schaltet 12 Rächer der Distelfelle und 12 Schamanen der Distelfelle aus. Man findet sie am häufigsten östlich vom Zoramstrand im Distelfelllager. Wenn das erledigt ist, kehrt zu Karang Amakkar in den Zoram'gar-Außenposten in Ashenvale zurück."}]])
R(217,"Verteidigung der Länder des Königs",[[description="$N, unsere Späher haben den Anführer des jüngsten Eindringens der Troggs ermitteln können. Es scheint, als folgten diese Bestien am Loch Modan einem Häuptling namens Grawmug. Grawmug wird jedoch aufs Schwerste bewacht. Zwei seiner Elitewachen, Knirscher und Muskelprotz, weichen nie von seiner Seite.$b$bWenn Ihr Euch dem gewachsen fühlt, $N, dann möchte ich, dass Ihr das Attentat auf Grawmug und seine beiden Schläger anführt. Wenn die Führungsriege der Troggs tot ist, dann haben wir vielleicht eine Chance, diese Bestien wieder unter die Erde zu treiben.",objectives={"Tötet den Anführer der Troggs, Grawmug, sowie seine beiden Wachen, Knirscher und Muskelprotz, und erstattet dann Captain Rugelfuss im südlichen Wachturm Bericht."}]])
R(218,"Das gestohlene Tagebuch",[[description="Mein Tagebuch! Sie haben es in die Höhle gebracht. Der, der es hatte, war ein großer Kerl mit seltsamen Zeichen auf der Haut und im Gesicht. Viel mehr konnte ich leider nicht sehen.$b$bIhr hattet ja mit den Trollen Erfolg, vielleicht könntet Ihr es mir wiederbeschaffen?",objectives={"Grelin Whitebeard möchte, dass Ihr Grik'nir den Kalten tötet und ihm sein Tagebuch wiederbeschafft."}]])
R(219,"Vermisst",[[description="Freunde der Allianz! Endlich!$b$bHelft... bitte... $b$bDas Letzte, an das ich mich erinnere, ist, dass diese abscheulichen Orcs unser Regiment überwältigten. Die meisten Männer wurden getötet; ich selbst erhielt einen Schlag an den Kopf und alles wurde schwarz. Jetzt werde ich in dieser Höhle gefangen gehalten. Bitte helft mir; ich bin schwer verletzt.$b$bIch brauche Hilfe auf dem Weg zurück in die Stadt... bitte... Ihr seid meine letzte Hoffnung...",objectives={"Beschützt Corporal Keeshan auf dem Rückweg ins Rotkammgebirge."}]])
R(220,"Ruf des Wassers",[[description="Islen hat noch eine weitere Aufgabe für Euch, ehe Ihr zur Belohnung Euer nächstes Totem erhaltet. Die Phiole mit Wasser, die ich Euch gegeben habe, wird für diese Aufgabe gebraucht, um was auch immer es sich dabei handeln mag.$B$BGeht nun und sucht sie auf. Wir werden uns eines Tages wieder begegnen.",objectives={"Bringt die Phiole mit reinstem Wasser in das Brachland zu Islen Waterseer."}]])
R(221,"Worgs in den Wäldern",[[description="Habt Ihr vielleicht schon festgestellt, dass einige größere Worgs zusammen mit den Schattenwirkern im Wald herumziehen? Nach allem, was wir wissen, machen diese Dunkelläufer den Großteil der Worg-Population aus.$b$bAuf meinen Wanderungen habe ich außerdem festgestellt, dass sie in den verlassenen Obsthain im Südwesten der Stadt eingefallen sind. Diese Worgs sind etwas zäher als die Letzten, denen Ihr begegnet seid.$b$bAlso seht Euch vor.",objectives={"Tötet für Calor aus Dunkelhain 12 Dunkelläufer der Nachtheuler."}]])
R(222,"Worgs in den Wäldern",[[description="Eure früheren Leistungen haben mich überzeugt, dass Ihr in der Lage seid, Euch mit den zähesten Worgs zu messen, die sich in den Wäldern eingenistet haben.$b$bVon all den Worgs, die plötzlich hier zu finden sind, haben sich die Faulreißer und die Besudelten als die gefährlichsten herausgestellt. Sie haben sich in der Nähe einiger Höhlen und in der Mine im Süden niedergelassen.$b$bNoch aus weiter Entfernung sieht man die Lichter ihrer Feuer...",objectives={"Tötet für Calor aus Dunkelhain einige Worgs, und zwar 8 Faulreißer der Nachtheuler und 8 besudelte Nachtheuler."}]])
R(223,"Worgs in den Wäldern",[[description="Hier, bitte schön, $n. Bringt Meister Carevin diese Nachricht.$b$b<Schnell zieht er ein Stück verblasstes Pergament hervor und reicht es Euch.>$b$bNoch ein paar mehr wie Ihr, dann sind wir bald mehr Kämpfer als die Nachtwache! Vielleicht können wir dann das Werk vollenden, an dem wir wenigen uns heute noch vergebens abmühen.",objectives={"Bringt Calors Notiz zu Jonathan Carevin."}]])
R(224,"Verteidigung der Länder des Königs",[[description="Wir müssen den Loch beschützen, $N! Jetzt, wo so viele der Soldaten des Königs tapfer auf weit entfernten Schlachtfeldern kämpfen, sind wir nahe davor, an der Heimatfront überwältigt zu werden. Aus jedem Spalt graben sich Troggs an die Oberfläche! Die Trogg-Plage stellt für Ironforge die größte Gefahr dar. Diese widerwärtigen Mutanten müssen vernichtet werden.$b$bIhr, $gtapferer Abenteurer:tapfere Abenteurerin;, müsst Euch für uns hinauswagen und der Bedrohung durch die Troggs ein Ende bereiten. Erschlagt 10 Stonesplitter-Troggs und 10 Stonesplitter-Späher und erstattet dann wieder Bericht.",objectives={"Gebirgsjäger Cobbleflint vom südlichen Wachturm möchte, dass Ihr 10 Stonesplitter-Troggs und 10 Stonesplitter-Späher tötet."}]])
R(225,"Das verwitterte Grab",[[description="Auf dem verwitterten Grabstein steht einfach:$b$bMORGAN LADIMORE$b$b<Als Ihr den Ort weiter untersucht, stellt Ihr fest, dass die Erde über dem Grab kürzlich umgegraben wurde und dass ein guter Teil der Erde entfernt worden zu sein scheint...>",objectives={"Sprecht in Dunkelhain mit Sirra Von'Indi."}]])
R(226,"Wölfe auf den Fersen",[[description="Sven und mir stehen jetzt gefährliche Tage ins Haus, wo doch der Totenbeschwörer im Osten sitzt und all das. Und weil wir hier draußen allein sind, müssen wir auch selbst jagen, wenn wir etwas essen wollen. Es kommt mir so vor, als würden jedes Mal, wenn ich mit etwas Fleisch zum Lager zurückgehe, verhungernde oder tollwütige Terrorwölfe aus dem Wald kommen, die auch etwas abhaben möchten. Ja, eines steht fest, das Leben hier draußen ist gefährlich!$B$BAber wenn Ihr einige der Wölfe für uns erledigen könntet, dann wäre das Leben für uns etwas leichter. Meist streunen sie nördlich und östlich von hier herum, in der Nähe des Flusses.",objectives={"Tötet 12 verhungernde Terrorwölfe und 8 tollwütige Terrorwölfe und kehrt dann zu Lars in Svens Lager an der westlichen Grenze des Dämmerwalds zurück."}]])
R(227,"Morgan Ladimore",[[description="<Er sucht in den Regalen und kommt mit einem ledergebundenen Buch zurück.>$b$bWenn Ihr mehr wissen wollt, dann fragt Althea. Sie ist diejenige, die in letzter Zeit von dem... Ärger... mit ihm am meisten mitbekommen hat.",objectives={"Sprecht in Dunkelhain mit Kommandantin Althea Ebonlocke."}]])
R(228,"Mor'Ladim",[[description="Meine Späher berichten mir, dass Mor'Ladim durch den ganzen Dämmerwald wandert und auf dem Friedhof einen seltsamen, gewundenen Weg einschlägt. Wir haben ihn hinter dem Haus auf dem Hügel begraben, wisst Ihr, wo das ist?$b$bEs gibt nichts, was ich tun könnte, um Euch zu helfen, aber ich wünsche Euch viel Glück.",objectives={"Tötet Mor'Ladim und bringt seinen Schädel nach Dunkelhain zu Kommandantin Althea Ebonlocke."}]])
R(229,"Die überlebende Tochter",[[description="Ich hätte Euch dies schon früher sagen sollen...$b$bWie soll ich sagen...$b$bMorgan dachte zwar, dass seine ganze Familie umgekommen sei, aber seine Tochter Sarah Ladimore lebt noch: Sie ist jetzt eine Behüterin. Die... Umstände... , unter denen ihr Vater zu Tode gekommen ist, haben sie immer sehr aufgewühlt. Vielleicht könntet Ihr zu ihr gehen und ihr mitteilen, was geschehen ist.",objectives={"Sprecht in Dunkelhain mit Behüterin Sarah Ladimore."}]])
R(230,"Svens Lager",[[description="Als Ihr durch den Haufen wühlt, findet Ihr ein kleines, schmutzbeflecktes Buch.$B$BDas Buch hat keinen Titel, aber... es enthält Informationen, die Sven bestimmt interessieren.",objectives={"Bringt das Buch von Svens Hof zu Sven."}]])
R(231,"Die Liebe einer Tochter",[[description="Hier, nehmt dies und legt es auf sein Grab. Vielleicht... vielleicht weiß er dann irgendwie, dass es mir gut geht und dass keiner von uns ihn für das verantwortlich macht, was geschehen ist.$b$b<Jetzt hat sie Tränen in den Augen, als sie einen Ring von der rechten Hand zieht und ihn Euch übergibt.>$b$bUnd... danke, $n.",objectives={"Bringt Sarah Ladimores Ring zu Morgan Ladimores Grab."}]])
R(232,"Kurierdienst für Apothekerin Zinge",[[description="Die Königliche Apothekenvereinigung benötigt Eure Hilfe. Hört gut zu und wir können beide von meinem Plan profitieren.$B$BApotheker Keever im nächsten Raum mag... begabt sein..., aber seine Forschungen könnten Früchte tragen, wenn sie von einem gewandten Forscher... oder einer gewandten Forscherin verfolgt würden. Zum Glück bin ich eine solche Forscherin. Bringt diese Bestellung zu Alessandro Luca, dem Eigentümer von Blaumond Dies-und-Das. Er wird Euch ein Testset geben. Wenn Ihr es habt, bringt es zu mir zurück und ich werde Euch Eure Aufgabe im Detail erläutern.",objectives={"Bringt die Bestellung nach Undercity zu Alessandro Luca."}]])
R(233,"Postbeförderung im Coldridgetal",[[description="Hm, ich nehme nicht an, dass Ihr mir einen Gefallen tun würdet, $gJungchen:Mädchen;? Heute kam ein Stapel Briefe durch den Pass, aber ich habe nicht die Zeit, sie weiterzuleiten.$b$bSie sind alle an Talin Keeneye adressiert. Ihr findet ihn ein Stück entlang der Straße im Westen. Er hat sein Lager am gefrorenen See aufgeschlagen.$b$bWas meint Ihr?",objectives={"Liefert den Stapel Briefe bei Talin Keeneye ab."}]])
R(234,"Postbeförderung im Coldridgetal",[[description="Wenn ich mich recht erinnere, hat Grelin sein Lager im Südosten, ein Stück die Straße hinunter. Ich bin sicher, er wartet schon sehnsüchtig auf seine Post.",objectives={"Liefert den Brief bei Grelin Whitebeard ab."}]])
R(235,"Die Jagd in Ashenvale",[[description="Achtung, junge Abenteurer! Die Wildnis von Ashenvale erwartet Euch!$B$BDie Horde hat eine starke Präsenz in den Ländern nördlich des Brachlandes aufgebaut. Unsere beiden Außenposten - der Splintertreeposten und der Zoramstrandposten - wollen der Horde zu Ruhm gereichen! Diejenigen, die sich beweisen möchten, sollten dort nach Anleitung suchen. Wichtiger Hinweis: Senani Thunderheart im Splintertreeposten, direkt nördlich des Brachlandes, sucht Abenteurer, die an einer großen Jagd in Ashenvale teilnehmen wollen!",objectives={"Sprecht mit Seneni Thunderheart im Splintertreeposten in Ashenvale."}]])
R(236,"Awaiting Word",[[description="A few weeks ago, I dispatched Watcher Callahan and a few others to the northern border of Duskwood to deal with the wolf infestation. I haven't heard word from him for quite some time. If he followed my instructions, he'll be camped out on the road north from Darkshire. $B$BIf it's on your way, please check up on him and inform him that I am awaiting a progress report from him.",objectives={"Speak with Watcher Callahan."}]])
R(237,"Verteidigung der Länder des Königs",[[description="Gebirgsjäger Cobbleflint hat nur Gutes über Euch zu berichten gehabt, $R. Daher werde ich Euch eine Mission von äußerster Wichtigkeit anvertrauen. Wir müssen den Druck auf die eindringenden Trogg-Streitkräfte aufrechterhalten, bis unsere Brüder, die Zwerge, von der Front der Allianz zurückkehren.$b$bBegebt Euch in die südlichen Hügel und tötet 10 Stonesplitter-Schädelhauer und 10 Stonesplitter-Seher. Eure Angriffe werden uns etwas Zeit verschaffen. Erstattet Bericht, sobald Ihr die Aufgabe erfüllt habt.",objectives={"Gebirgsjäger Gravelgaw im südlichen Wachturm möchte, dass Ihr 10 Stonesplitter-Schädelhauer und 10 Stonesplitter-Seher tötet und ihm anschließend Bericht erstattet."}]])
R(238,"Kurierdienst für Apothekerin Zinge",[[description="Das Set ist fertig, $n. Die Apothekerin Zinge wird es zweifellos so schnell wie möglich haben wollen. Bringt es ihr ohne Verzögerung und lasst sie wissen, dass ich die Kosten für das Set mit auf die Rechnung der Gesellschaft schreiben werde. Richtet ihr bitte außerdem meine wärmsten Grüße aus.$B$BAlso los, steht nicht einfach so rum. So ist nun mal das Leben eines einfachen Kuriers, stimmt's?",objectives={"Bringt das Feldprobenset nach Undercity zu Apothekerin Zinge."}]])
R(239,"Hilfe für die Weststromgarnison",[[description="Die Garnison an unserer westlichen Grenze berichtet von steigenden Aktivitäten der Gnolle und der Diebe. Sie bitten uns um die Entsendung weiterer Soldaten aus Stormwind... aber wir können einfach keine entbehren!$B$BWenn Ihr helfen könntet - wir könnten die Hilfe wirklich gebrauchen. Geht, sprecht mit Deputy Rainer in der Weststromgarnison und fragt ihn, was getan werden muss.$B$BDie Garnison liegt an der Straße im Westen. Wenn Ihr die Brücke über den kleinen Bach überquert habt, liegt sie auf der rechten Seite.",objectives={"Begebt Euch zur Weststromgarnison und sprecht mit Deputy Rainer."}]])
R(240,"Rückkehr zu Jitters",[[description="Und voilà - \"Krebs\"-Küchlein à la Grual!",objectives={"Kehrt mit den schwärzlichen Krebsküchlein zu Jitters zurück."}]])
R(241,"<TEST> HEY MISTER WILSON!",[[description="Description",objectives={"Log"}]])
R(242,"<UNUSED>",[[description="Throm-ka, $c. There is no time to waste. Orcs of the Dragonmaw clan have fortified themselves in the valley to the south of here. $b$bThey have denied the Warchief's mandate, leaving us only one course of action. We will eliminate them so that they will no longer dirty the name of the Horde.",objectives={"Kill 8 Dragonmaw Raiders, 3 Dragonmaw Bonewarders, and a Dragonmaw Battlemaster."}]])
R(243,"Auf ins Feld",[[description="Ihr werdet Euch in die Tanariswüste begeben und die Gewebebeschaffenheit der Basilisken, Skorpiden und Hyänen testen, die dort heimisch sind. Beschafft Gewebeproben und untersucht sie mit dem Testset; Ihr müsst davon ausgehen, dass eine Reihe der Proben unnütz sind. Ich benötige von jeder Kreaturenart acht akzeptable Proben.$B$BAußerdem verfügen die Goblins von Gadgetzan über eine Kraftquelle, die mit dieser Art von modifiziertem Set verwendet werden muss. Sprecht mit Chefingenieur Bilgewhizzle und erwerbt eine für das Set.$B$BKehrt erst zu mir zurück, wenn Ihr erfolgreich wart.",objectives={"Sprecht in Gadgetzan mit Chefingenieur Bilgewhizzle über eine Kraftquelle für das Testset."}]])
R(244,"Eindringende Gnolle",[[description="Seid gegrüßt, $C. Meine Aufgabe ist es, auf diesem Stück Straße zu patrouillieren. Obwohl die Straße im Augenblick sicher ist, habe ich nördlich und östlich von hier einige Lager von Gnollen gesehen.$B$BSeenhain muss erfahren, dass die Gnollstreitkräfte sich sammeln! Meldet Euch bei Deputy Feldon in Seenhain und berichtet ihm von den Gnollen. Wenn Ihr dies tut, dann wird Feldon Euch bestimmt den Sold eines Spähers zahlen.$B$BGewöhnlich inspiziert Feldon das Gebiet südlich der Brücke nach Seenhain.",objectives={"Erstattet Deputy Feldon Bericht."}]])
R(245,"Gefahr auf acht Beinen",[[description="Seid gegrüßt, $C. Vielleicht habt Ihr die Spinnen gesehen, die die Grenze im Westen überrannt haben? Mit den achtbeinigen Monstern werden wir nicht fertig und der Kommandant hat nicht genug Leute, um sie so weit weg von Dunkelhain einsetzen zu können.$b$bIch bitte Euch wirklich nur sehr ungern darum, aber Ihr seht aus, als könntet Ihr mit ihnen fertig werden. Ich kann Euch keine großen Schätze versprechen, aber ich kann Euch belohnen, wenn Ihr dabei helft, die dreckigen Biester auszurotten.$b$bAch, ein Ratschlag noch: Weicht ihrem Gift aus, wenn Ihr könnt.",objectives={"Erledigt 15 Zwerggiftweberspinnen und meldet Euch dann wieder bei Behüter Dodds im Dämmerwald."}]])
R(246,"Einschätzung der Gefahr",[[description="Wir können keinen der Männer hier entbehren, aber mit diesen Gnollen, von denen Ihr mir berichtet habt, muss etwas passieren.$B$BSpäht das südliche Rotkammgebirge nach Gnollen aus. Bedrängt sie, tötet so viele Ihr könnt und erstattet mir dann Bericht über ihre Anzahl. Gebt mir auch eine Einschätzung der Gefahr, die sie darstellen. Möglicherweise findet Ihr Lager dieser Gnolle entlang der südlichen Straße im Rotkammgebirge.$B$BTut dies für die Armee von Stormwind, $N, und Ihr erhaltet eine Belohnung.",objectives={"Tötet 10 Bastarde der Rotkammgnolle und 6 Wilderer der Rotkammgnolle und meldet Euch anschließend wieder bei Deputy Feldon in Seenhain."}]])
R(247,"Die Jagd ist abgeschlossen")
R(248,"Weitere Beobachtungen",[[description="Seit einer Weile schon beobachte ich den Turm von Ilgalar und ich habe herausgefunden, dass Morganth im Konflikt mit den Orcs von Burg Steinwacht liegt. Den Grund für ihren Streit kenne ich nicht, aber vielleicht könnt Ihr mir ja dabei helfen, diesem Rätsel auf die Spur zu kommen.$B$BNehmt eine weitere Glyphe von Azora und begebt Euch dann auf die Spitze des unversehrten Wachturms neben der Burg Steinwacht.$B$BFindet einen passenden Gegenstand, auf dem Ihr die Glyphe ablegen könnt. Eine Truhe oder ein Krug - irgendein Ort, an dem die Glyphe nicht auffällt - ist für meine Zwecke geeignet.",objectives={"Steigt in den unversehrten Wachturm neben der Burg Steinwacht hinauf.$B$BFindet einen passenden Behälter für die Glyphe von Azora und legt diese dort ab."}]])
R(249,"Morganth",[[description="Nach langen Beobachtungen habe ich jetzt Morganths Pläne durchschaut.$B$BEr sucht nach der Sense von Elune... und vielleicht hat er sie bereits gefunden! Wenn dem so ist, dann werden das Rotkammgebirge und das Königreich Stormwind schon bald seine dunkle Macht zu spüren bekommen.$B$BIch selbst bin leider nicht bereit, mich gegen Morganth zu stellen, doch ich fürchte, er muss genau jetzt aufgehalten werden. Daher müsst Ihr Euch Zutritt zum Turm von Ilgalar verschaffen und Morganth entgegentreten.$B$BBesiegt ihn und bringt mir seinen Schattenanhänger. Wenn Ihr dies vermögt, dann schuldet das Königreich Euch viel.",objectives={"Besiegt Morganth.$B$BBringt seinen Schattenanhänger zu Theocritus am Turm von Azora im Wald von Elwynn."}]])
R(250,"Eine dunkle Bedrohung",[[description="Den Sternen sei Dank, jemand sorgt sich um den Damm. Erst die Zerstörung des Thandol-Übergangs, dann die Plünderung von Dun Modr! Ich hege keinerlei Zweifel, dass der Damm das Ziel des nächsten Anschlags der Dunkeleisenzwerge sein wird. Der größte Teil meiner Sicherheitsleute wurde an die Front der Allianz versetzt, einschließlich meines besten Kontrolleurs.$b$bUnd deswegen brauche ich Euch, $N. Ich habe einige Pioniere der Dunkeleisenzwerge gesehen, die an der östlichen Rampe des Damms herumlungerten. Untersucht den Bereich und bringt einen Hinweis zurück.",objectives={"Untersucht den Bereich um die östliche Dammrampe und bringt Chefingenieur Hinderweir einen Hinweis, der Auskunft darüber geben könnte, was die Dunkeleisenzwerge vorhaben."}]])
R(251,"Übersetzung von Calvinius' Notiz",[[description="Bringt den Zettel, den Ihr mir gabt, zu Sirra Von'Indi. Er ist sehr gelehrt und kennt viele Sprachen und alte Künste - wenn überhaupt jemand diese Nachricht übersetzen kann, dann ist er das.",objectives={"Bringt den Brief an Ello zu Sirra Von'Indi."}]])
R(252,"Übersetzung für Ello",[[description="Oh je! Wenn das, was hier steht, wahr ist, dann hat Calvinius etwas... Unsägliches getan.$B$BBringt die übersetzte Notiz besser schnell zu Ello zurück.$B$BBeeilt Euch, denn ich fürchte, Unheil rollt bereits auf unsere Stadt zu...",objectives={"Bringt Lord Ello Ebonlocke den übersetzten Brief."}]])
R(253,"Braut des Einbalsamierers",[[description="Der Einbalsamierer... diesen Namen kennen wir aus einer Geschichte, die wir unseren Kindern erzählen. Er war ein freundlicher Alchimist, den der Tod seiner Frau Eliza in den Wahnsinn trieb. Er wollte sie wiederbeleben und so wandte er schwarze Magie an und pflanzte sein eigenes Herz in die Brust seiner toten Gattin ein.$B$BDies stellte Eliza wieder her, doch nun war sie verflucht... ein unstillbarer Hunger auf Menschenfleisch hatte sich ihrer bemächtigt und der Einbalsamierer musste sie in ihrem Grab liegen lassen.$B$BSeine Macht ruht in seinem Herzen. Findet das Grab seiner Frau, holt sein Herz und bringt es mir, solange es noch schlägt. Wenn Ihr dies tut, wird seine Macht gebrochen sein.",objectives={"Findet Elizas Grab. Beschafft das Herz des Einbalsamierers, das sie in sich trägt, und kehrt zu Ello Ebonlocke zurück."}]])
R(254,"Graben in der Erde")
R(255,"Söldner",[[description="Zwei Monate! Zwei Monate, nur um dann aus Ironforge zu hören zu bekommen, dass eine Handvoll Soldaten zu unserer Verteidigung abgestellt wird, und zwei weitere Monate, bis sie ankommen! Schlimm genug, dass unsere Stadt ohne Schutz ist, aber die Ausgrabung und der Damm - der Damm! - sind ebenfalls allen Angriffen schutzlos ausgesetzt.$b$bIch habe also keine Wahl, scheint mir. Ich brauche gedungene Kämpfer.$b$bWie steht es mit Euch? Ihr seht mir tüchtig aus, $C. Eine Gruppe Oger hat im Nordosten des Sees ihr Lager aufgeschlagen. Vielleicht könntet Ihr ein paar weitere Kämpfer rekrutieren und uns dabei helfen, die Bedrohung für unsere Stadt zu beseitigen?",objectives={"Magistrat Bluntnose aus Thelsamar hat Euch angeheuert, um 4 Oger der Mo'grosh, 4 Schläger der Mo'grosh und 4 Vollstrecker der Mo'grosh zu töten."}]])
R(256,"GESUCHT: Chok'sul",[[description="Auf Befehl des Magistrats von Thelsamar:$b$bDer Tod von Chok'sul, dem Oger und mutmasslichen Anführer und Kopf hinter den Angriffen auf die Stadt Thelsamar, den Stonewroughtdamm und die Ausgrabungsstätte, wird unter allen Umständen gewünscht. Es darf zu jedem Mittel gegriffen werden, das notwendig ist.$b$bEine Barentschädigung kommt zur Auszahlung, wenn der Magistrat einen Beweis für Chok'suls Tod erhält.$b$bZuletzt wurde Chok'sul am Ogerlager im nordöstlichen Teil von Loch Modan gesehen.",objectives={"Tötet Chok'sul und bringt Magistrat Bluntnose seinen Kopf."}]])
R(257,"Das Prahlen eines Jägers",[[description="Ihr glaubt wohl, Ihr könnt Euch mit Daryl dem Kühnen messen, hm? Das will ich auch nicht hoffen! Aber Ihr dürft es natürlich gern versuchen, wenn Ihr denn meint... Hier habt Ihr eine Herausforderung, der Ihr bestimmt nicht gewachsen seid. Also nehmt's nicht zu schwer, wenn Ihr damit nicht fertig werdet.$b$bEin Schwarm Bussarde nistet hier am Loch Modan. Warum versucht Ihr nicht, einige von denen zu erledigen? Ich sag Euch was. Wenn Ihr meine Herausforderung annehmt und es Euch in 15 Minuten gelingt, dann gebe ich Euch meinen Bogen oder mein Gewehr.$b$b<Er mustert Euch abschätzig.>$b$bScheint ja nicht, als ob Ihr viel zu verlieren hättet.",objectives={"Tötet 6 Bergbussarde und kehrt innerhalb von 15 Minuten zu Daryl dem Jüngling in die Weitschreiter-Lodge zurück."}]])
R(258,"Die Herausforderung eines Jägers",[[description="$nath, stimmt's? Ich seh schon, Ihr platzt fast vor Stolz, dass Ihr den ersten Test bestanden habt. Aber ich hab Euch ja auch schon gesagt, dass das keine große Tat war.$b$bIhr solltet Euch mal an der Eberjagd versuchen. Glaubt mir, das sind andere Eber als im Coldridgetal, also solltet Ihr Euch vorsehen. Diesmal gebe ich Euch nur 12 Minuten.$b$bSeid nicht zu traurig, wenn Ihr versagt. Ich würde Euch das Hemd geben, das ich am Leibe trage, wenn Ihr es schaffen würdet!$b$bHabe ich Euch schon mal erzählt, wie ich an meine berühmte Narbe gekommen bin? Nein? Also, das war vor zwei Jahren...",objectives={"Tötet 5 alte Bergeber und kehrt innerhalb von 12 Minuten zu Daryl dem Jüngling in die Weitschreiter-Lodge zurück."}]])
R(259,"<UNUSED>",[[description="Hello there, $n. I've heard much about your exploits, and must say I'm honored to meet you. I don't suppose you've heard the story of Ol' Kelt? Ah, well, Ol' Kelt--Kelt Thomasin, that is--was once considered one of the finest hunters in all the realm. There wasn't much he hadn't done, but then, one day, he became obsessed with an ancient story... a myth, really. Well, as the stories go, a huge threshadon lives in the waters of the lake. Hogwash, if you ask me. If you're interested, you might talk to Kelt.",objectives={"Talk to Kelt Thomasin."}]])
R(260,"<UNUSED>",[[description="Now, this will no doubt convince you that I am, as they say--and don't deny it, I know what they say--of an addled mind, obsessed with an impossible legend. An old dwarven legend, it is, of an enormous monster that lives in the depths of the Loch. I spent a good bit of my life trying to track it down, and I believe I got close, but alas, I fear old age has caught up to me. If you would like to try hunting down the monster of the Loch, bring me some treshadon teeth and claws.$B$B<He smiles mysteriously.>",objectives={"Collect 5 Threshadon Teeth and 5 Threshadon Claws, then bring them to Kelt Thomasin."}]])
R(261,"Auf dem Scharlachroten Pfad",[[description="Ich werde offen mit Euch sein. Wir sind im Krieg mit der Geißel. Sie ist ein Übel, das unser Volk verdirbt und unser Land infiziert. Sie muss aufgehalten werden, bevor sie uns übermannt und unsere Welt mit Schatten überzieht. Wir vom scharlachroten Kreuzzug haben geschworen, die Geißel mit Leib und Seele zu bekämpfen.$B$BWenn Ihr auf unserer Seite steht, dann nehmt Euren Mut zusammen und beweist Eure Zugehörigkeit - zerstört die untoten Verheerer von Desolace im südlich gelegenen Tal der Knochen.$B$BTut dies, und der Kreuzzug wird Euch mit offenen Armen aufnehmen.",objectives={"Vernichtet 30 untote Verheerer und kehrt dann zu Bruder Anton auf die Nijelspitze zurück."}]])
R(262,"Die Schattengestalt",[[description="Ich muss wissen, wen ich in der Nacht, in der meine Familie ermordet wurde, in den Schatten habe herumschleichen sehen.$B$BBitte, $n, Ihr habt euren Einfallsreichtum bereits bewiesen. Bitte findet diese schattenhafte Gestalt. Ich muss wissen, was sie für Geheimnisse kennt!$B$BIch habe keine Hinweise, die Ihr nicht bereits hättet, aber hier - nehmt das Buch, das Ihr auf meinem Hof gefunden habt. Vielleicht können einige Stadtbewohner das Buch mit seinem Besitzer in Verbindung bringen.",objectives={"Nehmt das Buch, das Ihr auf Svens Hof gefunden habt, und zeigt es den Einwohnern von Dunkelhain."}]])
R(263,"Verteidigung der Länder des Königs",[[description="Die Gebirgsjäger sagen mir, dass Ihr recht tapfer und fähig seid, $N. Ein $R wie Ihr wird hier draußen gebraucht. Wir bekommen das Trogg-Problem einfach nicht unter Kontrolle. Die Reserve wurde zur Front gerufen, und wir sind hier auf uns allein gestellt. Aber jetzt seid ja Ihr hier, ein erfahrener $C, also wollen wir doch mal sehen, was Ihr ausrichten könnt.$b$bZieht los und tötet 10 Schamanen der Splittersteintroggs und 10 Knochenknacker der Splittersteintroggs. Wir werden sehen, ob Ihr Eurem Ruf gerecht werdet, $gTrogg-Töter:Trogg-Töterin;.",objectives={"Gebirgsjäger Wallbang im südlichen Wachturm möchte, dass Ihr 10 Schamanen der Splittersteintroggs und 10 Knochenknacker der Splittersteintroggs tötet."}]])
R(264,"Bis dass der Tod uns scheidet",[[description="Dreckiger Abschaum! Lässt mich wegen seinem verdammten Kreuzzug hier sitzen. Nur, weil \"das Licht das Wichtigste ist, was wir gegen die Bedrohung durch die Untoten besitzen\".$B$BUnd was ist mit seinen Kindern?! Was ist mit MIR?! Nacht für Nacht hab ich hier gesessen und geduldig auf ihn gewartet ... hab immer den zweiten Platz hinter seiner verfluchten Pflicht eingenommen!$B$BTja, hier könnt Ihr sehen, was Euch \"Gerechtigkeit\" einbringt, $N! Er ist tot, und ich ertrage genau das, was er aufzuhalten versuchte!$B$BNehmt diesen Plunder und legt ihn auf seine Gruft in dem Grabmal. Ich will nichts mehr damit zu tun haben ... oder mit ihm!",objectives={"Legt Clarices Anhänger auf Yurivs Grab in Silberwald."}]])
R(265,"Die Schattensuche geht weiter",[[description="Hier habt Ihr Euer Buch zurück, $n, und viel Glück noch bei Eurer Suche. Vielleicht können Euch ja andere in der Stadt mehr Hinweise geben, wenn Ihr sie fragt.$B$BIch habe jedenfalls noch einen für Euch - obwohl der Autor dieses Buches in Dunkelhain fremd ist, wurde das Buch selbst hier gekauft.",objectives={"Überprüft, ob andere Einwohner Hinweise auf die schattenhafte Gestalt haben."}]])
R(266,"Nachforschungen im Gasthaus",[[description="Hier habt Ihr Euer Buch zurück, und noch viel Glück bei Euren Nachforschungen.$B$BVielleicht wollt Ihr Eure Suche auf das Gasthaus ausweiten. Wenn die Person, die Ihr sucht, einige Zeit hier in der Stadt verbracht hat, dann hat sie dort vielleicht jemand gesehen.",objectives={"Sucht im Gasthaus nach Hinweisen auf die schattenhafte Gestalt."}]])
R(267,"Die Bedrohung durch die Troggs",[[description="$C, Ihr seid Euch vielleicht nicht unbedingt der Bedrohung durch die Troggs bewusst, die ihren Schatten über das Land der Zwerge wirft. Nachdem die Reserve von Ironforge zur Front der Allianz gerufen wurde, bleibt uns nur ein Bruchteil der Verteidigungskräfte, die nötig wären, um dieses Land zu schützen. Meinem Regiment wurde aufgetragen, über das Tor hier zu wachen, und wir können unseren Posten aufgrund der Gefahr einer Invasion nicht verlassen.$b$bEs muss aber etwas Druck auf diese verdammten Troggs ausgeübt werden, die in den Hügeln lauern. Wenn Ihr Euch dem gewachsen fühlt, startet einen Angriff auf die Troggs. Bringt mir 8 Trogg-Steinzähne als Beweis.",objectives={"Bringt Captain Rugelfuss im südlichen Wachturm 8 Trogg-Steinzähne."}]])
R(268,"Rückkehr zu Sven",[[description="Das Buch, das Ihr gefunden habt, war nur zur Hälfte fertig geschrieben. Ich musste es auf Svens Hof zurücklassen, als ich hierher floh... $B$BHier. Nehmt mein vollständiges Tagebuch und bringt es zu Sven. Es beschreibt wesentlich genauer, was auf seinem Hof passierte.$B$BObwohl dieses Tagebuch in den letzten Wochen meine einzige Gesellschaft war, gebe ich es gern auf, wenn ich mir dadurch erspare, Sven und seiner Wut zu begegnen.",objectives={"Kehrt mit Jitters' vollständigem Tagebuch zu Sven zurück."}]])
R(269,"Auf der Suche nach Weisheit",[[description="Geht nach Stormwind und sprecht dort mit Bischof Farthing in der Kathedrale des Lichts. Gebt ihm Jitters' Tagebuch und sagt ihm, dass Ihr vorhabt, Euch Morbent Fel zu stellen.$B$BAuch wenn Stormwind Dunkelhain aufgegeben hat, ist Farthing doch eine gute Seele und sehr weise. Er könnte Euch bei Eurem Versuch, uns zu retten, behilflich sein.$B$BEure Mission ist gefahrvoll, aber beeilt Euch dennoch, $N. Mit jeder verstreichenden Stunde verfinstern sich die Schatten über dem Dämmerwald mehr und mehr.",objectives={"Gebt Bischof Farthing in Stormwind Jitters' vollständiges Tagebuch."}]])
R(270,"Die verlorene Flotte",[[description="Vor vielen Jahren sank die dritte Flotte von Kul'Tiras vor der Küste des Sumpflandes, einem Moorgebiet nördlich des Zwergenkönigreichs von Ironforge. Auf einem der Schiffe befand sich eine Ladung Lichtgeschmiedetes Eisen.$B$BDieses Metall ist wertvoll für uns, da Gegenstände, die daraus gefertigt werden, mit heiliger Wahrheit zuschlagen. Wenn Ihr Morbent Fel entgegentreten wollt, dann werdet Ihr eine solche Waffe brauchen.$B$BGeht zum Hafen von Menethil und sprecht mit meinem zwergischen Kollegen Glorin Steelbrow. Wenn dieses verlorene Metall überhaupt gefunden werden kann, dann weiß er, wo man danach suchen muss.",objectives={"Geht zum Hafen von Menethil im Sumpfland und sprecht mit Glorin Steelbrow."}]])
R(271,"Vyrins Rache",[[description="Ihr seid nicht zufällig daran interessiert, es unserem ach so kühnen Kühnen ein wenig heimzuzahlen? Es schmerzt mich, das zu sagen, aber Daryl hat ein gewisses Talent.$b$bVor einem Jahr war ein großer Bär das Ziel der Weitschreiter-Lodge, aber keiner der Jäger hatte Glück mit ihm. Also dachte sich Daryl, er könnte sich mal an ihm versuchen. Das einzige, was er nach seinem Versuch vorweisen konnte, war die hässliche Narbe über seinem Auge.$b$bErlegt den Bären und ich bin mir sicher, dass sogar Daryl mal sprachlos wäre.$b$bDer Bär, Old Sooty, hält sich irgendwo in der Nähe seines Baus in den Hügeln über Thelsamar auf.",objectives={"Tötet Old Sooty und zeigt Daryl dem Jüngling in der Weitschreiter-Lodge dann Euer Werk."}]])
R(272,"Prüfung des Seelöwen",[[description="Für die zweite Prüfung benötigt Ihr die zwei Hälften, aus denen der Anhänger des Seelöwen besteht. Die eine Hälfte bezieht ihre Kraft aus der Beweglichkeit des Seelöwen-Aspektes beim Gleiten durchs Wasser; die andere Hälfte bezieht ihre Kraft aus der unglaublichen Ausdauer des Seelöwen-Aspektes. Druiden bedienen sich dieser beiden Eigenschaften gleichermaßen, um den Aspekt ihrer Wassergestalt zu verkörpern.$B$BSprecht mit den Bewohnern von Moonglade, um herauszufinden, wo sich die Teile befinden könnten, und bringt beide hierher, um sie miteinander zu vereinen. Bringt den Anhänger zu Dendrite Starblaze, wenn Ihr ihn geschaffen habt.",objectives={"Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserausdauer. Sprecht mit den Einwohnern von Moonglade, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.$B$BFormt den Anhänger des Seelöwen aus den beiden Anhängerhälften. Ihr müsst in der unmittelbaren Nähe des Schreins von Remulos sein, um dies zu tun.$B$BBringt den zusammengefügten Anhänger zu Dendrite Starblaze nach Nighthaven in Moonglade."}]])
R(273,"Nachschub für die Ausgrabungsstätte",[[description="Es ist noch nicht zu spät, Ihr könnt gern losziehen und Huldar suchen. Er kann noch nicht sehr weit gekommen sein, denn so stark sie auch sein mögen, können Miran und Saean dennoch nicht allzu schnell laufen, wenn sie mit diesen Fässern vollgepackt sind.$b$bSie nehmen die übliche Route zur Ausgrabungsstätte, südwärts aus der Stadt raus und dann an der Krümmung des Lochs entlang.$b$bIhr solltet keine Probleme haben, sie zu finden, solange sie nicht bereits dort angekommen sind.",objectives={"Sprecht mit Huldar."}]])
R(274,"Eine dunkle Bedrohung",[[description="Dies ist kein gewöhnliches Sprengpulver. Seht diese winzigen Silberkristalle. Und der eindeutige Geruch! Es ist sonnenklar, dass es sich hier um Zephyriumpulver handelt. Zephyrium an sich ist harmlos. Aber wenn es nass wird, könnte es ganz Ironforge aus dem Berg sprengen.$b$bDie chemische Reaktion kann entschärft werden, indem man vier Komponenten mischt: Lauerergift, einen zerstoßenen Kristall der Mo'grosh, eine Krokiliskenträne und diese Entschärfungspaste. Jetzt geht und erklärt es Hinderweir, ehe es zu spät ist!",objectives={"Ashlan Stonesmirk möchte, dass Ihr zum Chefingenieur Hinderweir zurückkehrt und ihn von der neuen Entdeckung in Kenntnis setzt."}]])
R(275,"Schwärendes Land",[[description="Ich weiß nicht warum, aber irgendetwas schwärt im Sumpfland. Moorkrabbler haben sich dort ausgebreitet. Sie sind wie kranke, fiebrige Blasen auf dem Land, und um das Fieber zu besiegen, müssen sie erledigt und dem Sumpf wieder zugeführt werden.$B$BDie Moorkrabbler watscheln mitten in den Wasserwegen des Sumpflandes herum.",objectives={"Tötet 12 Moorkrabbler und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück."}]])
R(276,"Stapfende Pfoten",[[description="Die Moosfellgnolle lebten viele Jahre friedlich im Sumpfland, aber in letzter Zeit wächst ihre Anzahl. Ihre Füße trampeln die Büsche und Blumen des Moores platt, und ihre garstigen Äxte schlagen zu viel Holz für ihre Feuer.$B$BSie befinden sich nicht mehr im Gleichgewicht mit dem Land. Wenn das Sumpfland überleben soll, müssen die Gnolle dezimiert werden.$B$BTötet 15 Gnolle der Moosfelle und 10 Bastarde der Moosfelle. Jagt sie im Süden, nahe dem Zwergentor von Algaz. Wenn Ihr das getan habt, kehrt zu mir zurück.",objectives={"Tötet 15 Gnolle der Moosfelle sowie 10 Bastarde der Moosfelle und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück."}]])
R(277,"Feuer-Tabu",[[description="Die Moosfelle fällen die Bäume des Sumpflandes und verwenden das Fleisch der Bäume, um sich mit Feuer zu wärmen. Ich werde diesen Schmerz nicht länger ertragen!$B$BEntledigt die Moosfelle ihrer kunstlosen Feuersteine, der Werkzeuge, die sie zum Feuermachen verwenden. Die meisten Moosfelle tragen diese Feuersteine bei sich, ausgenommen die kleineren Gnolle der Moosfelle und Bastarde der Moosfelle.",objectives={"Bringt Rethiel dem Sumpfhüter 9 kunstlose Feuersteine."}]])
R(278,"Eine dunkle Bedrohung",[[description="Fangt gleich damit an, die Stoffe zum Entschärfen zusammenzusuchen, $N. Lauerergift kann von den im Loch Modan heimischen Spinnen gewonnen werden. Krokiliskentränen findet man ebenfalls hier im Loch. Ein Kristall der Mo'grosh hingegen dürfte sehr schwierig zu bekommen sein. Die Oger im Nordosten bauen sie ab, aber die Kristalle sind ein sehr seltener Rohstoff.$b$bWir müssen einen Angriff der Dunkeleisenzwerge abwehren können! Kommt zurück, wenn Ihr alle erforderlichen Dinge zusammenhabt, und ich werde die Mixtur vorbereiten.",objectives={"Chefingenieur Hinderweir möchte, dass Ihr Lauerergift, einen Kristall der Mo'grosh und eine Krokiliskenträne besorgt."}]])
R(279,"Klauen aus der Tiefe",[[description="Murlocs kriechen aus den tiefen Wassern und bauen ihre Dörfer entlang der Küste. Sie überfallen unsere Fischer und Händler und müssen aufgehalten werden.$B$BEiner dieser Murlocs, Gobbler, streift mit den anderen Murlocs der Blaukiemen umher und plündert die Händler entlang der Straße aus, wobei sie sich danach immer in die Sicherheit der nahegelegenen Hütten zurückziehen. Unsere Händler sind in Gefahr, und wir sind bereit, für ihre Sicherheit zu zahlen.$B$BGobbler strolcht in der kleinen Bucht nördlich von hier herum. Findet ihn, erschlagt seine Artgenossen und bringt mir seinen Kopf.",objectives={"Tötet 12 Murlocs der Blaukiemen.$B$BErschlagt Gobbler und nehmt Euch seinen Kopf.$B$BBringt Gobblers Kopf zu Karl Boran in den Hafen von Menethil"}]])
R(280,"Eine dunkle Bedrohung",[[description="Heute habe ich einige Aufrührer der Dunkeleisenzwerge gesehen, die mit einem Fässchen in Richtung Damm geschwommen sind. Es waren keine Gebirgsjäger zur Hand, um sie aufzuhalten! Ich fürchte, sie haben das Zephyrium am Fuße des Dammes deponiert, und es könnte jede Minute hochgehen! Lasst mich diese ganzen Zutaten zur Entschärfungsmixtur zusammenmischen. Na bitte!$b$bIhr müsst jetzt diese Mixtur mitnehmen und in das Fässchen einrühren, bevor es zu spät ist! Beeilt Euch!",objectives={"Chefingenieur Hinderweir will, dass Ihr zum Fuß des Dammes hinunterschwimmt, das Pulverfässchen ausfindig macht und die Entschärfungsmixtur hineinrührt, um eine Explosion zu verhindern."}]])
R(281,"Waren-Wiederbeschaffung",[[description="Vor nicht allzu langer Zeit wurde ein Handelsschiff, die Blind Princess, von Murlocs überfallen. Obwohl das Schiff unversehrt entkam, wurde ein Großteil seiner Fracht von den Kreaturen über Bord gezogen, darunter eine äußerst wertvolle Statuette von Terenas Menethil. Wir möchten, dass die Statuette geborgen wird.$B$BDurchsucht die Hütten der Murloc an der Küste nach Kisten, Fässern und anderen Spuren von verlorener Fracht. Findet die Menethil-Statuette und bringt sie mir wieder.",objectives={"Durchsucht die Kisten und Fässer in den Murloclagern an der Küste."}]])
R(282,"Senirs Beobachtungen",[[description="Ich hatte ursprünglich vor, meinen Lehrling mit meinem Bericht zu meinem Bruder Senir zu schicken, aber ich würde mich viel besser fühlen, wenn er in etwas... verlässlicheren Händen wäre. Natürlich nur, wenn es Euch nichts ausmacht?$b$bHmm... Ihr müsstet den Tunnel nehmen, um nach Kharanos zu gelangen.$b$bSprecht mit Gebirgsjäger Thalos, bevor Ihr durch den Tunnel geht. Er ist mittlerweile vollständig von den Troggs überrannt.$b$bFolgt der Straße zurück nach Anvilmar und geht dann weiter nach Osten zum Tunnel. Thalos ist ganz in seiner Nähe stationiert.",objectives={"Sprecht mit Gebirgsjäger Thalos."}]])
R(283,"Eine dunkle Bedrohung",[[description="Das Fässchen zischt ein wenig.",objectives={"Die Entschärfungsmixtur scheint gewirkt zu haben. Kehrt zu Chefingenieur Hinderweir zurück und berichtet ihm die guten Neuigkeiten."}]])
R(284,"Die Suche geht weiter",[[description="Ihr durchsucht gründlich diese Ansammlung von Murlochütten, findet aber keine Spur von der Menethil-Statuette.$B$BVielleicht gibt es in einer der beiden nahe gelegenen Hütten im Norden und Nordosten mehr Hinweise.",objectives={"Sucht nach der Menethil-Statuette."}]])
R(285,"Suche in weiteren Hütten",[[description="Dieses Grüppchen Murlochütten offenbart auch nach einer gründlichen Überprüfung nichts.$B$B... Aber Ihr seid Euch sicher, dass der nächste Anhaltspunkt, den Ihr findet, nützlich sein wird.$B$BEine der Hütten nördlich von hier muss die Menethil-Statuette enthalten!",objectives={"Sucht weiter in den Hütten der Murlocs nach der Menethil-Statuette."}]])
R(286,"Rückgabe der Statuette",[[description="Nachdem Ihr das Fass aus dem Dreck gezogen und geöffnet habt, findet Ihr eine in dünnes Stroh eingepackte, silbrige Figur. Sie stellt einen jungen, langhaarigen Paladin mit erhobenem Hammer dar.$B$BDies kann nur die Menethil-Statuette sein! Ihr müsst sie nun zu Karl Boran in den Hafen von Menethil zurückbringen.",objectives={"Bringt Karl Boran die Menethil-Statuette."}]])
R(287,"Höhle der Frostmane",[[description="Ich bin mit meinem Bericht etwas im Rückstand und könnte Eure Hilfe brauchen, $n. Ich habe gerade herausgefunden, wo sich die Trolle verschanzt haben, aber ich habe so viele Trolle gesehen, dass ich mich nicht getraut habe, hineinzugehen.$b$bWas ich von Euch möchte, ist Folgendes: Geht runter zur Höhle, schaut Euch ein wenig darin um, tötet ein paar Trolle und kommt dann wieder hierher zurück.$b$bNehmt die Straße nach Norden, raus aus Kharanos. Sobald Ihr an der Brücke ankommt, folgt dem zugefrorenen Fluss westwärts, bis Ihr den Iceflowsee erreicht. Am linken Ufer werdet Ihr Brewnall vorfinden. Die Höhle liegt südwestlich des Dorfes.",objectives={"Erforscht die Höhle der Frostmane und tötet 5 Kopfjäger der Frostmane für Senir Whitebeard in Kharanos."}]])
R(288,"Die Dritte Flotte",[[description="Ich war einst erster Maat auf der HERRIN DER MEERE, einem Linienschiff der dritten Flotte von Kul Tiras, der verlorenen Flotte. Verloren deshalb, weil die Flotte auf ihrer letzten Reise von roten Großdrachen angegriffen wurde. Großdrachen, die von Orcs beherrscht wurden!$B$BWir hatten keine Chance gegen das Drachenfeuer... und unsere Flotte ging just vor dieser Küste hier brennend unter. Ich bin der einzige Überlebende von diesen armen Schiffen.$B$B... Oh, mir brummt der Schädel! Ich werde einen frischen Drink brauchen, wenn ich mit diesem Kater klarkommen und meine Geschichte fortsetzen soll.",objectives={"Spendiert dem Ersten Maat Fitzsimmons einen Krug Met."}]])
R(289,"Die verfluchte Crew",[[description="<Gestärkt setzt Fitzsimmons seine Geschichte fort...>$B$BIch bin der einzige Überlebende der unglückseligen Dritten Flotte von Kul Tiras, die vor der Küste im Norden vernichtet wurde. Aber obwohl ich das einzige Mitglied der Flotte bin, das noch atmet, bin ich nicht der einzige, der noch herumläuft! Denn auf einem unserer Schiffe war ein großer und schrecklicher Schatz versteckt, und dessen unheimliche Macht hält die Seelen meiner Brüder in den verrottenden Wracks gefangen.$B$BWenn Ihr allerdings einige meiner Brüder befreien könnt, könnt Ihr vielleicht auch den Fluch brechen, der auf ihnen lastet.",objectives={"Vernichtet 13 verfluchte Seeleute, 5 verfluchte Matrosen und den ersten Maat Snellig. Bringt Snelligs Schnupftabakdose zum ersten Maat Fitzsimmons im Hafen von Menethil."}]])
R(290,"Brechen des Fluchs",[[description="Um den Fluch zu brechen und alle meine Brüder zu befreien, müsst Ihr das... Ding... das auf meinem Schiff verstaut ist, bergen und reinigen! Ich weiß nicht, was es war, aber ich weiß, dass es sicher in der Geldkassette des Schiffs verwahrt wurde, zu dem nur Kapitän Halyndor den Schlüssel hatte.$B$BMein alter Kapitän erscheint mir immer noch in meinen Träumen. Ich bin mir sicher, dass er auf meinem untergegangenen Schiff, der INTREPID, herumläuft. Besorgt Euch den Schlüssel von ihm und öffnet damit die Geldkassette der INTREPID.$B$BAnschließend, wenn Ihr das verfluchte Ding habt, bringt es zu Glorin Steelbrow, dem Priester, hier in der Stadt.",objectives={"Besorgt den Geldkassettenschlüssel der INTREPID von Kapitän Halyndor.$B$BVerwendet den Schlüssel, um die Geldkassette der INTREPID zu öffnen."}]])
R(291,"Die Berichte",[[description="Wunderbar! Überbringt Senator Barin Redstone meinen Bericht. Er ist ein missmutiger Geselle, also stört Euch nicht an seinem wenig sonnigen Gemüt. Er ist in Ironforge, in der Halle, in der König Magni Hof hält.$b$bIhr kennt den Weg nach Ironforge nicht? Nehmt die Straße aus Kharanos heraus nach Norden, überquert die Brücke und folgt dann der Straße nach Osten den Berghang hinauf. Einige große Banner flankieren diese Straße.$b$bAch ja, und könntet Ihr es vielleicht vermeiden, zu erwähnen, dass Ihr mir geholfen habt? Ich kann die ja nicht glauben lassen, ich würde hier draußen nicht hart arbeiten, nicht wahr?",objectives={"Überbringt Senator Barin Redstone in Ironforge Senirs Bericht."}]])
R(292,"Das Auge von Paleth",[[description="In der offenen Truhe erblickt Ihr eine geschwärzte Kugel, die in einem gruseligen Licht pulsiert. Dies ist der Schatz, von dem Fitzsimmons gesprochen hat: ein verfluchtes Auge von Paleth.$B$BBringt das verfluchte Auge von Paleth zum Zwergen-Priester Glorin Steelbrow im Hafen von Menethil. Fragt ihn, wie man den Fluch des Auges brechen kann.",objectives={"Bringt Glorin Steelbrow das verfluchte Auge von Paleth."}]])
R(293,"Die Reinigung des Auges",[[description="Ich kann den Fluch nicht von dem Auge von Paleth nehmen. Die Augen wurden von Menschen-Priestern hergestellt, daher werdet Ihr nach Stormwind gehen müssen, um jemanden zu finden, der Euch helfen kann. Sprecht mit Erzbischof Benedictus. Er steht der Kathedrale des Lichts in Stormwind vor. Er kann helfen.$B$BDas hoffe ich jedenfalls, um euretwillen.",objectives={"Bringt Erzbischof Benedictus das verfluchte Auge von Paleth. Ihr findet Benedictus in der Kathedrale des Lichts, in der Stadt Stormwind."}]])
R(294,"Ormers Rache",[[description="Die Lage ist ernst, soviel ist sicher. Als wir diese Knochen freigelegt haben, hat das die Raptoren angelockt. Diese dreckigen Bestien haben meine Brüder getötet und mich, Merrin und den armen Ausgrabungsleiter hier festgesetzt.$b$bHelft mit, das Sumpfland von diesen Raptoren zu säubern, $N. Scheckige Raptoren und Scheckige Kreischer befinden sich direkt westlich der Klippe hier. Tötet jeweils 10, wenn Ihr könnt.$b$bDas wäre ein guter Anfang für die Rache, die ich mir für sie ausgedacht habe.",objectives={"Ormer Ironbraid von der Whelgars Ausgrabungsstätte möchte, dass Ihr 10 scheckige Kreischer und 10 scheckige Raptoren tötet."}]])
R(295,"Ormers Rache",[[description="Es ist an der Zeit, diese abscheulichen Raptoren ihren Blutdurst bereuen zu lassen. Gleich da unten gibt es Dutzende von scheckigen Sensenklauen- und Scharfzahnraptoren. Lasst diese scheußlichen Kreaturen bezahlen, indem Ihr 10 von jeder Sorte erschlagt.",objectives={"Ormer Ironbraid möchte, dass Ihr 10 scheckige Sensenklauen- und 10 scheckige Scharfzahnraptoren tötet und dann zu ihm zu Whelgars Ausgrabungsstätte zurückkommt."}]])
R(296,"Ormers Rache",[[description="Während Ihr da unten wart, ist mir aufgefallen, dass eines der Biester aus der Menge herausstach. Es war größer und bedrohlicher. Ich könnte wetten, das ist derjenige, der die anderen hierher geführt hat und für die Störung der Ausgrabungsstätte verantwortlich ist.$b$bIch erbitte eine letzte Aufgabe von Euch, $n. Sorgt dafür, dass Sarlatan seine gerechte Strafe erhält. Und wenn man die Schwere seiner Verbrechen bedenkt, bedeutet Gerechtigkeit in diesem Falle den Tod! Bringt mir eine seiner Krallen als Beweis, dass er tot ist.",objectives={"Ormer Ironbraid von der Whelgars Ausgrabungsstätte möchte, dass Ihr Sarlatan tötet und mit einer seiner Krallen zu ihm zurückkehrt, sobald Ihr die Aufgabe erledigt habt."}]])
R(297,"Götzen sammeln",[[description="Vor einer Weile, kurz bevor die Troggs in der Stätte auftauchten, hatten wir eine große Anzahl seltsame, verzierte Götzen gefunden. Leider hatten wir keine Gelegenheit, sie zu untersuchen, denn kurz nach ihrer Entdeckung haben uns die Troggs aus den Ruinen verjagt. Und diese Götzen haben eine seltsame Wirkung auf die Troggs. Sie verfallen dadurch in Raserei!$B$BBringt mir 8 Götzen - ich möchte sie studieren, und ich will sie nicht mehr in den Händen der Troggs sehen. Ihr könnt die Götzen bei den Troggs finden, die die Stätte heimsuchen.",objectives={"Bringt Magmar Fellhew 8 verzierte Steingötzen."}]])
R(298,"Bericht über den Fortschritt der Ausgrabungen",[[description="Ich muss einen Fortschrittsbericht nach Thelsamar schicken - einen Fortschrittsbericht und eine Neufassung meiner Anfrage nach mehr Sprengpulver! Hier ist der Bericht. Bringt ihn Jern Hornhelm. Er ist unser örtlicher Kontaktmann in Thelsamar.$B$BKeine schwierige Aufgabe, aber sie muss erledigt werden.",objectives={"Bringt Ironbands Fortschrittsbericht zu Jern Hornhelm in Thelsamar."}]])
R(299,"Enthüllung der Vergangenheit",[[description="Kurz vor der Invasion habe ich eine große Schrifttafel gefunden, die man den Goazstein nennt. Der übersetzte Text reißt an 4 Stellen ab. Der Text spricht von einem \"göttlichen Plan\" und einer \"schicksalhaften Prophezeiung\".$b$bIch fürchte, uns läuft die Zeit davon. Ich bin zu alt, um hinunterzugehen und diesen Bestien zu trotzen. Aber Ihr seid stark.$b$bDurchkämmt die Ausgrabungsstätte und sucht die 4 fehlenden Tafelfragmente: Ados, Modr, Golm und Neru. Sucht sie in alten Artefakten oder dort, wo das Erdreich locker ist. Bringt sie mir, auf dass ich damit beginnen kann, ihre Geheimnisse zu enträtseln!",objectives={"Ausgrabungsleiter Whelgar wünscht, dass Ihr die Ausgrabungsstätte nach den 4 fehlenden Tafel-Fragmenten durchkämmt, Ados, Modr, Golm und Neru."}]])
R(301,"Meldung in Ironforge",[[description="Wir werden eine Bewilligung brauchen, um Ironband mehr Sprengpulver zu beschaffen. Ihr müsst seinen Bericht zum Hauptquartier der Forscherliga in Ironforge bringen.$B$BHier ist der Bericht. Gebt ihn Ausgrabungsleiter Stormpike und vergesst nicht, Euch zu ducken, nachdem Ihr ihn abgeliefert habt. Stormpike ist ein Hitzkopf, und es wird ihn nicht erfreuen, wenn er von Ironbands langsamem Vorankommen an der Ausgrabungsstätte hört.$B$BIhr findet Stormpike in der Versammlungshalle der Forscher.",objectives={"Bringt Ironbands Fortschrittsbericht zu Ausgrabungsleiter Stormpike."}]])
R(302,"Pulver für Ironband",[[description="Wenn Ironband immer noch Sprengpulver braucht, dann, bei Magni, soll er es haben! Ich habe die Bewilligung bereits mit einem Boten nach Thelsamar zu Jern Hornhelm vorausgeschickt. Er wird das Pulver und andere Vorräte zum Transport zu Ironband bereitstellen.$B$BAch, und noch was: Ich will, dass Ihr persönlich dafür Sorge tragt, dass diese Pulverlieferung ihren Bestimmungsort erreicht. Die letzte kam nicht an, also haltet Euren Verstand wach und Eure Augen offen.",objectives={"Sprecht in Thelsamar mit Jern Hornhelm."}]])
R(303,"Der Dunkeleisenkrieg",[[description="Der Krieg tobt daheim ebenso wie in der Fremde. Während mächtige Zwergenkrieger im Namen der Allianz in weit abgelegenen Gegenden ihr Leben lassen, fallen unsere eigenen Gebiete den bösen Taten der Dunkeleisenzwerge zum Opfer. Sie haben den Thandol-Übergang verwüstet. Dun Modr fiel kurz darauf.$b$bIhr müsst Kräfte sammeln und die Front zurückdrängen. Wenn Ihr 15 Dunkeleisenzwerge, 5 Tunnelgräber der Dunkeleisenzwerge, 5 Saboteure der Dunkeleisenzwerge und 5 Demolierer der Dunkeleisenzwerge töten könnt, dann kommen die Reserven vielleicht rechtzeitig, um den Vormarsch zu beenden.$b$bUnd jetzt beeilt Euch!",objectives={"Motley Garmason in Dun Modr möchte, dass Ihr 15 Dunkeleisenzwerge, 5 Tunnelgräber der Dunkeleisenzwerge, 5 Saboteure der Dunkeleisenzwerge und 5 Demolierer der Dunkeleisenzwerge tötet."}]])
R(304,"Eine grausige Aufgabe",[[description="Viele meiner Soldaten fielen in der Schlacht von Dun Modr. Mein eigener Bruder kam um, als die Westbrücke über dem Thandol-Übergang zerstört wurde. Jawohl, die Dunkeleisenzwerge sind eine teuflische Brut. Soweit Roggo das in Erfahrung bringen konnte, ist der Anführer dieses Verbrecherpacks im Sumpfland ein Hexenmeister namens Balgaras der Niederträchtige. Er ist allerdings ein ziemlicher Feigling. Er kommandiert seine Soldaten herum, bleibt aber selbst im Hintergrund, jegliche Gefahr meidend.$b$bWenn Ihr diesen rückgratlosen Abschaum finden könnt, erschlagt ihn und bringt mir sein Ohr. Ich werde Euch dafür entlohnen, $C.",objectives={"Tötet Balgaras den Niederträchtigen und bringt Longbraid dem Grimmigen vor Dun Modr sein Ohr."}]])
R(305,"Auf der Suche nach dem Ausgrabungstrupp",[[description="Wie schön, Ihr müsst der Späher sein, den Longbraid zu schicken versprach. Ihr könnt Euch nicht vorstellen, wie besorgt ich war.$b$bMeine Frau, Merrin, hat mir im letzten Monat jede Woche Briefe geschickt. Sie gehört zum Whelgar-Ausgrabungstrupp. Aber es sind fast zwei Wochen seit unserem letzten Briefwechsel vergangen. Irgendetwas ist bestimmt schief gelaufen!$b$bLongbraid versprach, dass er einen Späher schicken würde, der sich dort mal umsieht, wenn wir nicht bald etwas vom Trupp hören. Ich nehme mal an, dieser Späher seid Ihr, $N. Findet Merrin in der Ausgrabungsstätte im Osten!",objectives={"Tarrel Rockweaver möchte, dass Ihr zur Ausgrabungsstätte reist und dort Kontakt mit Merrin Rockweaver aufnehmt."}]])
R(306,"Auf der Suche nach dem Ausgrabungstrupp",[[description="Es war grauenhaft! Wir hatten einige seltene Artefakte enthüllt und fingen an, welche von diesen großen Knochen zu finden.$b$bBevor wir wussten, wie uns geschah, überrannten diese scheckigen Raptoren die Ausgrabungsstätte. Viele ließen ihr Leben.$b$bOrmer hier rettete - ganz tapfer - den Ausgrabungsleiter und mich. Er verteidigte uns, während wir Schutz suchten. Jetzt sind wir gefangen. Und unsere harte Arbeit liegt in Trümmern.$b$bHier, nehmt diese Nachricht mit zurück zu meinem süßen Tarrel. Sie wird ihm die Situation klarmachen.",objectives={"Kehrt mit Merrins Nachricht zu Tarrel Rockweaver zurück."}]])
R(307,"Schmutzige Pfoten",[[description="Die Silberbachmine im Osten hat sich schon vor langer Zeit erschöpft. Sie wurde vom Bund der Bergarbeiter in ein Lagerhaus umgewandelt, aber jetzt sind dort Kobolde eingezogen und befingern mit ihren schmutzigen Pfoten gute zwergische Werkzeuge!$B$BWir werden dieses Ungeziefer noch früh genug ausmerzen, aber der Bund wünscht, dass jemand ihre Gerätschaften aus der Mine schafft, bevor wir Krieger da reinstürmen und was kaputtmachen. Das wird ein harter Abstieg – Ihr solltet vielleicht Unterstützung mitnehmen.$B$BDie Ausstattung wird in Kisten des Bergarbeiterbunds über die Mine verteilt aufbewahrt. Viel Glück.",objectives={"Geht zur Silberbachmine und sucht 4 Sätze Bergarbeiter-Ausstattung zusammen.$B$BKehrt dann zu Gebirgsjäger Stormpike zurück."}]])
R(308,"Jarvens Ablenkung")
R(309,"Beschützen der Fracht",[[description="Bereit zum Aufbruch, $N?$b$bAls Erstes müssen wir dieses Pulver zu Ironband bringen. Für mich allein wäre es zu viel zu tragen und diese Gegend kann gefährlich werden - und wer weiß, was diese Dunkeleisenzwerge noch für mich bereithalten?$b$bIch werde mich viel besser fühlen, wenn Ihr mitkommt.",objectives={"Stellt sicher, dass sowohl Miran als auch seine Warenlieferung sicher an der Ausgrabungsstätte ankommen und setzt dann Ausgrabungsleiter Ironband davon in Kenntnis."}]])
R(310,"Bittere Rivalen",[[description="Ich muss zugeben, diese Donnerbräus stellen ein paar gute Getränke her. Aber sie müssen noch lernen, dass ihres nicht das einzige ordentliche Gebräu ist! Vielleicht könnt Ihr mir helfen, ihnen diese Lehre zu erteilen...$B$BHier, nehmt dieses Fass mit Gerstenbräu. Schleicht Euch in den Keller der Brauerei Donnerbräu in Kharanos und vertauscht es mit einem ihrer Fässer Donnerbier. Dann werden wir ja sehen, ob ihre Kundschaft mein Gebräu lieber mag als ihres!$B$BAch ja, und falls die Fässer bewacht sein sollten, müsstet Ihr eventuell den Wächter irgendwie ablenken...",objectives={"Vertauscht im Keller der Brauerei Donnerbräu in Kharanos ein Fass Donnerbier mit einem Fass Gerstenbräu."}]])
R(311,"Rückkehr zu Marleth",[[description="Nachdem Ihr ein Fass von Marleths Gerstenbräu im Keller der Brauerei Donnerbräu abgestellt habt, schnappt Ihr Euch zum Beweis ein Fass Donnerbier...",objectives={"Bringt Marleth Gerstenbräu in Brewnall das Fass mit Donnerbier."}]])
R(312,"Tundra MacGranns gestohlene Vorräte",[[description="Ich hatte einen Monatsvorrat Trockenfleisch gesalzen und für die kalte Jahreszeit weggeschlossen. Weggeschlossen deshalb, damit die Bären nicht rankommen! Aber während ich unterwegs auf der Jagd war, hat sich diese Bestie, Eisbart der Alte, mit meinem Fleisch-Spind davongemacht. Er wird allerdings nicht durch das Thorium kommen. Ich wiederum werde verhungern, wenn ich mein Fleisch nicht wiederbekomme.$b$bIhr seht verstohlener aus als ich. Vielleicht könnt Ihr meinen Vorrat wiederbeschaffen? Ich würde es mit meinem steifen Bein niemals schnell genug in die Höhle hinein und wieder heraus schaffen.",objectives={"Holt Tundra MacGranns Trockenfleisch aus dem gestohlenen Fleisch-Spind in der Höhle von Eisbart dem Alten."}]])
R(313,"Der altgediente Bau",[[description="Nicht jeder ist dazu geschaffen, eine Belagerungsmaschine zu fahren. Dazu braucht man eine eiserne Hand und Nerven aus Stahl... zum Glück besitze ich beides! Wie steht's mit Euch? Wie groß ist euer Talent? Wollt Ihr es mir nicht zeigen?$B$BWie auch immer... ich versuche gerade, meine Maschine, Trollplow, etwas gemütlicher zu machen. Wie wäre es, wenn Ihr mir einen Haufen Wendigomähnen aus dem altgedienten Bau westlich von Kharanos besorgt? Diese Mähnen könnten einen tollen Teppich für das Innendeck abgeben!",objectives={"Sammelt 8 Wendigomähnen und bringt sie Pilot Stonegear."}]])
R(314,"Die Herde beschützen",[[description="Wir haben mitten in der Nacht die Schreie gehört. Heute morgen fehlten der Herde dann tatsächlich zwei Widder. Diese heimtückische Bestie, Vagash genannt, hat sich über unsere Existenzgrundlage hergemacht. Da der Großteil von König Magnis Armee irgendwo in weit entfernten Landen an der Seite der Allianz kämpft, ist niemand mehr da, der Vagash in Schach halten könnte.$b$bVielleicht seid Ihr tapfer genug, die Bestie aufzuspüren und zu erschlagen. Bringt mir einen Fangzahn der Bestie, und ich werde Euch belohnen. Vagash lauert direkt oberhalb der Ranch hier, aber seid gewarnt, die Bestie ist tödlich.",objectives={"Rudra Amberstill möchte, dass Ihr Vagash erschlagt und einen seiner Fangzähne zu ihr auf die Widder-Ranch bringt."}]])
R(315,"Das Perfekte Starkbier",[[description="Ich bin von einem Vorhaben besessen, dem Vorhaben, das perfekte Starkbier herzustellen. Ich weiß, dass ich es schaffen kann - das Brauen liegt mir im Blut. Ich muss nur das richtige Rezept finden...$B$BWeit oben in den Bergen im Osten bauen die Trolle der Frostmane eine Pflanze an, Schimmerkraut genannt. Sie verwenden sie in ihren seltsamen Stammesritualen. Wir Zwerge haben bisher keine wirkliche Verwendung dafür gefunden, aber sie hat einen einzigartigen Geschmack... und ich möchte damit in meinen Gebräuen herumexperimentieren.$B$BBesorgt mir etwas Schimmerkraut von den Sehern der Frostmane oder klaut es aus den Schimmerkrautkörben der Trolle.",objectives={"Bringt Rejold Gerstenbräu in Brewnall 6 Schimmerkräuter."}]])
R(316,"<UNUSED>")
R(317,"Vorräte für Jetsteam",[[description="Ich bereite mich gerade darauf vor, eine Mission für die Belagerungsbrigade in Angriff zu nehmen. Sie wird ziemlich lange dauern, und ich muss Jetsteam mit Vorräten für einen ganzen Monat beladen. Könntet Ihr also nicht, während Steelgrill an meinem Panzer arbeitet, ein wenig für mich auf die Jagd gehen?$B$BIch werde ein paar Pelze als Bettzeug und etwas Eberfleisch zum Essen brauchen. Ihr könnt das Fleisch von Ebern und die Pelze von Bären erbeuten... Ihr findet beide in den Schneefeldern südlich des altgedienten Baus.",objectives={"Sammelt 4 Brocken Eberfleisch und 2 dicke Bärenfelle und liefert sie bei Pilot Bellowfiz in Steelgrills Depot ab."}]])
R(318,"Immerschimmer",[[description="Rejold Gerstenbräu experimentiert mit seinen Gebräuen. Ein paar davon schmecken gut, einige schlecht, und einige... nun, einige hauen selbst den stärksten Zwerg um.$B$BEr lebt in Brewnall, westlich von Kharanos, und ich will Immerschimmer, eines seiner Getränke. Es wird mich warmhalten, während ich in der Kälte unterwegs bin.$B$BAußerdem brennt das gesegnete Zeug so heiß, dass ich es in Jetsteams Brennofen kippen kann, um einen Energieschub zu erzeugen! Diese nette Taktik hat mich schon aus mehr als einer haarigen Situation gerettet.",objectives={"Besorgt von Rejold Gerstenbräu in Brewnall ein Fässlein Immerschimmer."}]])
R(319,"Ein Gefallen für etwas Immerschimmer",[[description="Ich habe ein Fässlein mit Immerschimmer zur Hand, aber... könnt Ihr mir einen Gefallen tun? Brewnall könnte ein wenig Hilfe gebrauchen gegen die wilden Tiere, die die nahegelegenen Schneefelder durchstreifen. Manchmal kommen sie sehr nah.$B$BWir haben keine Angst vor diesen Bären und Katzen und Ebern - kein Zwerg, der etwas auf sich hält, hätte das - aber wenn Ihr Euch für uns um diese Tiere kümmern könntet, hätten wir mehr Zeit für unser Handwerk und unsere Braukunst.",objectives={"Tötet 6 Eisklauenbären, 8 alte Klippeneber sowie 8 Schneeleoparden und kehrt dann zu Rejold Gerstenbräu nach Brewnall zurück."}]])
R(320,"Rückkehr zu Bellowfiz",[[description="Hier habt Ihr Euer Fässlein mit Immerschimmer, $n. Und wie gesagt, vielen Dank für die Jagd kürzlich.",objectives={"Gebt Pilot Bellowfiz in Steelgrills Depot das Fässlein mit Immerschimmer."}]])
R(321,"Lichtgeschmiedetes Eisen",[[description="Diese Schiffswracks hier vor der Küste sind die verlorene dritte Flotte von Kul'Tiras, die während des letzten großen Krieges von roten Drachen verbrannt und versenkt wurde.$B$BDie Flotte stammte aus Lordaeron, bis auf ein Schiff, einen elfischen Zerstörer: die Flying Osprey. Es transportierte eine Ladung Lichtgeschmiedetes Eisen und schloss sich der dritten Flotte aus Sicherheitsgründen an. Welche Ironie, dass es von denselben Drachen versenkt wurde... $B$BGenug Geschichte. Die Flying Osprey liegt südlich vom Hafen von Menethil auf Grund. Wenn Ihr das Lichtgeschmiedetes Eisen darin finden könnt, bringt es zu mir.",objectives={"Durchsucht das Wrack der FLYING OSPREY im Sumpfland."}]])
R(322,"Gesegnete Waffe",[[description="Im Zwergendistrikt von Stormwind gibt es einen zwergischen Waffenschmied, der Lichtgeschmiedetes Eisen verarbeiten kann. Er heißt Grimand Elmore.$B$BIch habe das von Euch gefundene Eisen in eine Kiste gepackt. Bringt sie zu Grimand und erzählt ihm Eure Geschichte. Ich bin mir sicher, er wird jemandem, der auf einem Kreuzzug wie dem Euren ist, gefällig sein und Euch eine Waffe schmieden - eine Waffe, vor der sich sogar Morbent Fel fürchten wird.",objectives={"Bringt Grimand Elmore in Stormwind die Kiste mit Lichtschmiedeblöcken."}]])
R(323,"Bewährungsprobe",[[description="Morbent Fel ist ein Totenbeschwörer und ein Verbündeter der dunklen Reiter. Ich würde Euch ja erlauben, Euch der Macht von Morbent Fel entgegenzustellen, aber ich werde Euch erst gegen diese widerwärtige Satanskreatur kämpfen lassen, wenn ich Eure wahre Stärke kenne.$B$BIhr habt mir Eure Tapferkeit bereits bewiesen, aber wenn Ihr dem Totenbeschwörer wirklich trotzen wollt, dann beweist Euer Geschick zuerst an seinen Dienern.",objectives={"Vernichtet 15 Skeletträuber, 3 Skelettheiler sowie 3 Skelettwärter und kehrt danach zu Sven zurück."}]])
R(324,"Die verlorenen Blöcke",[[description="Nachdem Ihr den einzelnen Lichtschmiedeblock aus der voll gelaufenen Kiste genommen habt, ist Euch klar, dass die Murlocs wohl den Rest gestohlen haben. Jagt die Murlocräuber in der Nähe des Wracks der Flying Osprey, um an das verloren gegangene Lichtgeschmiedetes Eisen zu kommen.",objectives={"Sammelt 5 Lichtschmiedeblöcke und kehrt dann zu Glorin Steelbrow im Sumpfland zurück."}]])
R(325,"Bewaffnet und bereit",[[description="Hier ist die Waffe gegen die Satanskreatur, von der Ihr spracht. Ihr seid bestens vorbereitet, $N. Viel Glück, und ich freue mich schon darauf, von Eurer Ruhmestat zu hören!",objectives={"Bringt Morbents Bann zu Sven im Dämmerwald."}]])
R(328,"Der versteckte Schlüssel",[[description="In den Berichten wird kein Wort über den Gefreiten Thorsen verloren, jedoch im Einband eines von Herods Geschäftsbüchern findet sich ein kleiner Messingschlüssel.$B$BUnd nach genauerem Studium seiner Notizen finden sich in den verschiedenen Dokumenten einige Verweise auf eine \"sichere Geldkassette\". Die Geldkassette befindet sich irgendwo innerhalb des Vorratslagers - des Höhlenkomplexes weiter hinten in Kurzens Truppenlager.$B$BWenn diese sichere Geldkassette gefunden wird und der kleine Messingschlüssel ihn öffnen kann, dann kann das Geheimnis um Thorsens Entdeckung vielleicht offenbart werden.",objectives={"Verwendet den kleinen Messingschlüssel, um Buchhalter Herods Geldkassette zu öffnen."}]])
R(329,"Der entlarvte Spion",[[description="Unter den Wertgegenständen in der Geldkassette befindet sich eine schlammverschmierte, gekritzelte Notiz. Wenn sie auch kaum lesbar ist, so scheint es, als wäre es eine Abhandlung über den Gefreiten Thorsen. Sie beschreibt ausführlich seine Patrouillenrouten, mit wem er so spricht und wie er seine Zeit bei den Rebellen verbringt. Sie ist nur mit einem einzelnen Buchstaben unterschrieben: -M.$B$BDennoch muss, wer auch immer diese Notiz verfasst hat, stets in Thorsens Nähe gewesen sein. Wer auch immer diese Notiz verfasst hat, ist der Verräter im Rebellen-Lager.",objectives={"Bringt die schlammverschmierte Notiz zu Lieutenant Doren im Rebellen-Lager."}]])
R(330,"Patrouillen-Pläne",[[description="Die Notiz, die Ihr mir gegeben habt, ist mit einem \"-M\" unterzeichnet... Ich weiß nicht, was das heißen könnte.$B$BAber... die Notiz sagt auch aus, dass diese Person letzte Woche die gleichen Patrouillenrouten wie Thorsen hatte. Also muss, wer auch immer mit Thorsen letzte Woche auf Patrouille war, der Verräter sein!$B$BGeht zu Corporal Sethman. Er kümmert sich um die Patrouillenpläne und wird Euch sagen können, wer mit Thorsen unterwegs war.",objectives={"Sprecht mit Corporal Sethman."}]])
R(331,"Meldung bei Doren",[[description="Wollte Lieutenant Doren, dass Ihr Euch mit diesen Patrouillen-Informationen wieder bei ihm meldet?",objectives={"Sprecht mit Lieutenant Doren."}]])
R(332,"Weinladen-Werbung",[[description="Wenn Ihr Euch mit irgendwem über Weine unterhaltet, werdet Ihr erfahren, dass wir Gallinas die besten Weine in ganz Stormwind verkaufen. Wir sind auch nicht weit weg, immer noch innerhalb des Handelsdistrikts entlang der herrlichen Kanäle der Stadt.$B$BHier, nehmt dieses Flugblatt. Bringt es meiner Schwester Suzetta in unseren Laden, und Ihr erhaltet eine Gratis-Flasche unseres berühmten Pinot Noir. Ihr werdet es nicht bereuen!",objectives={"Geht zum Weingut Gallina und gebt Suzetta Gallina den Wein-Gutschein, um eine kostenlose Flasche Wein zu erhalten."}]])
R(333,"Harlan braucht Nachschub",[[description="Wir hatten hier in der letzten Zeit viel Betrieb. Es scheint so, als wollte wirklich jeder Rüstungen und robuste Kleidung kaufen. Als würden alle eine kalte, harte Jahreszeit erwarten... $B$BAber das sind alles Zukunftssorgen. Meine heutige Sorge ist eher, dass mir die gestrickten Kleidungsstücke ausgehen. Ich brauche eine weitere Fuhre von unserem Lieferanten.$B$BWenn Ihr diesen Auftrag zu Rema Schneider in die Schneiderei und Anpasserei am Kanal bringen könntet, währe ich Euch sehr dankbar.",objectives={"Geht zur Schneiderei und Anpasserei am Kanal und bringt Rema Schneider Harlan Bagleys Kleidungs-Auftrag."}]])
R(334,"Eine Lieferung für Thurman",[[description="Mein Sohn Thurman ist Lehrling beim Konfektionsgeschäft Larson im Magierviertel. Er hatte es heute etwas eilig und vergaß seine Schere und Nadeln. Ich weiß, ein großer $C wie Ihr hat bestimmt wichtige Aufgaben zu erledigen, aber ohne sein Handwerkszeug kann er seine Lehrarbeiten nicht erledigen!$B$BBitte, $N. Könnt Ihr meinem Sohn sein Nähkästchen vorbeibringen? Das Konfektionsgeschäft Larson ist einer von zwei Kleiderläden im Magierviertel - es ist das, das etwas weiter drin liegt, ganz in der Nähe des Magierturms.",objectives={"Geht zum Konfektionsgeschäft Larson im Magierviertel von Stormwind und gebt Thurman Schneider sein Nähkästchen."}]])
R(335,"Ein nobles Bräu",[[description="Lord Wishock sorgt im Oberhaus ganz schön für Unruhe. Er wurde auf unseren kleinen \"Betrieb\" hier unten aufmerksam gemacht und propagiert jetzt eine genaue Untersuchung. Ich habe einen Plan, um Wishock... zu beschäftigen... aber ich benötige Eure Hilfe. $b$bEs gibt eine Blume, die in Stalvans Garten in den Außenbezirken von Dunkelhain wächst. Diese kleine weiße Blume ist als Tilloaträne bekannt. Ich werde außerdem eine Bisamwurzel brauchen, die man nur am Fuße des Wasserfalls tief unter dem Stonewroughtdamm im Sumpfland findet.",objectives={"Zardeth Blackclaw möchte, dass Ihr ihm eine Tilloaträne aus Dunkelhain und eine Bisamwurzel aus dem Sumpfland bringt."}]])
R(336,"Ein nobles Bräu",[[description="Lord Wishock hat, wie alle Menschen, seine Schwächen. Bei seiner handelt es sich um eine Vorliebe für alkoholische Getränke. Seine Scheinheiligkeit ist verblüffend. Dieser spießige Trottel verbringt seine Tage damit zu versuchen, unsere kleine \"Taverne\" schließen zu lassen, während er seine Nächte im Obergeschoss zubringt und dabei Rechnungen anschreiben lässt, die er niemals bezahlt. Na, mal sehen, wie Wishock dieses besondere Gebräu schmeckt, das ich für ihn vorbereitet habe: Blackclaw-Starkbier. Es haut ziemlich rein, $N.$b$bBringt es ihm und seht, wie es ihm schmeckt. Höchstwahrscheinlich treibt sich der alte Trottel in der Halle der Bittsteller herum.",objectives={"Bringt Lord Wishock in der Halle der Bittsteller das Blackclaw-Starkbier."}]])
R(337,"Ein altes Geschichtsbuch",[[description="Obwohl der Einband dieses Buches von Kratzern überzogen und von Schmutz verkrustet ist, kann man auf dem Buchrücken noch immer die Worte \"Die Geschichte von Stormwind\" lesen. Wenn man das Buch aufmacht, kann man das Siegel der Bibliothek von Stormwind erkennen, das deutlich auf der ersten Seite prangt.$B$BEs sieht so aus, als hätte jemand dieses Buch ausgeliehen, aber nie zurückgegeben.",objectives={"Bringt das Buch: \"Die Geschichte von Stormwind\" in die Bibliothek von Stormwind zurück."}]])
R(338,"Die Grünen Hügel des Schlingendorntals",[[description="Meister Nesingwary wird furchtbar wütend sein, wenn er das herausfindet!$b$bEr vertraute mir das Manuskript für seinen Roman, \"Die Grünen Hügel des Schlingendorntals\", zum Korrekturlesen an. Es lief auch alles glatt, aber dann wehte ein großer Windstoß durch das Lager und hat die Seiten überall verteilt.$b$bIch konnte die meisten Seiten wieder zusammensuchen, aber viele sind noch über den halben Dschungel verstreut. Sammelt die Seiten, mit denen man die vier Kapitel vervollständigen kann.$b$bIch werde Euch helfen, sie zu ordnen. Bringt mir die Kapitel zurück, wenn Ihr alle vier beisammen habt.",objectives={"Sammelt die fehlenden Seiten des Manuskripts von \"Die Grünen Hügel des Schlingendorntals”. Wenn alle vier Kapitel vollständig sind, bringt sie zu Barnil zurück."}]])
R(339,"Kapitel I",[[description="Kapitel I war ziemlich fesselnd! Meister Nesingwary baut den Hintergrund der Geschichte auf und erwähnt seine Jagdgefährten, mich eingeschlossen! $b$bAber das tut gerade nichts zur Sache. Lasst mich mal sehen, welche Seiten noch fehlen. So wie es aussieht sind die Seiten 1, 4, 6 und 8 immer noch irgendwo da draußen im Dschungel!",objectives={"Bringt Barnil Stonepot die Seiten 1, 4, 6 und 8 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals”, um Kapitel I zu vervollständigen."}]])
R(340,"Kapitel II",[[description="Kapitel II war voll gestopft mit aufregenden Geschichten von der Panther- und Tigerjagd. Ich könnte mir dafür in den Hintern treten, dass ich die Seiten habe davonfliegen lassen. $b$b Es sieht aus, als hätte ich alle Seiten wiedergefunden, bis auf die Seiten 10, 11, 14 und 16.",objectives={"Bringt Barnil Stonepot die Seiten 10, 11, 14 und 16 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals\", um Kapitel II zu vervollständigen."}]])
R(341,"Kapitel III",[[description="Kapitel III gefiel mir am besten. Es erzählt von Sire Erlgadins und Lady Rouacks erstem Blattschuss mit einem Zwergen-Gewehr. Und am Ende von Kapitel III, Mann, solche eine Spannung! $b$bWenn ich das richtig sehe, brauchen wir noch die Seiten 18, 20, 21 und 24, um das Kapitel fertig zu stellen. Diese Seiten sind irgendwo da draußen...",objectives={"Bringt Barnil Stonepot die Seiten 18, 20, 21 und 24 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals”, um Kapitel III zu vervollständigen."}]])
R(342,"Kapitel IV",[[description="Ah, Kapitel IV; Das große Finale! Und was für ein Ende es war! $b$bUns fehlen nur drei Seiten aus diesem Kapitel. Wir brauchen die Seiten 25, 26 und 27, um Kapitel IV wieder zusammenzusetzen.",objectives={"Bringt Barnil Stonepot die Seiten 25, 26 und 27 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals\", um Kapitel IV zu vervollständigen."}]])
R(343,"Reden über Kraft",[[description="Ich werde eine Rede über die Kraft des Geistes halten, und ich würde dazu gern einige Auszüge aus einem bestimmten Buch über Metallurgie zitieren - \"Belastbarkeit von Eisen\". Eine Abschrift dieses Buches dürfte sich in der königlichen Bibliothek der Burg Stormwind finden. Könnt Ihr es für mich holen? Wenn dem so ist, dann mögen die Segnungen des Lichts mit Euch sein!$B$BDie königliche Bibliothek ist sehr groß, aber der oberste Bibliothekar, Milton Sheaf, kennt jedes Regal, als wäre es sein eigenes Kind. Sprecht mit ihm, und er wird Euch das Buch holen.",objectives={"Geht in die königliche Bibliothek der Feste von Stormwind und sprecht mit Milton Sheaf. Er kann das Buch über Metallurgie für Euch finden, das Bruder Kristoff für seine Rede benötigt."}]])
R(344,"Bruder Paxton",[[description="Belastbarkeit von Eisen? Ja, ich kenne das Buch. Ziemlich gut, vor einigen Jahrzehnten von dem Zwergenminenarbeiter Margulf Blaggon geschrieben. Er verbrachte den Großteil seines Lebens tief in den Bergen von Khaz Modan, Erze schürfend. Kluger Kerl!$B$BAber wo war ich doch gleich? Ach ja, die \"Belastbarkeit von Eisen\"! Ich fürchte, das Buch wurde in die Abtei von Nordhain verlegt. Der Verwalter der Bibliothek der Abtei, Bruder Paxton, wollte eine Kopie des Buches für seine eigenen Regale anfertigen.$B$BDas war allerdings vor Monaten. Ich frage mich, warum er so lange dafür braucht...",objectives={"Sprecht mit Bruder Paxton in der Abtei von Nordhain."}]])
R(345,"Tinten-Zutaten",[[description="Ich will meine Abschrift von \"Belastbarkeit von Eisen\" schon länger fertig stellen, aber... $B$BNun, ich stelle für die Bücher, die ich abschreibe, meine Tinte selbst her, versteht Ihr? Es handelt sich um mein eigenes Rezept. Sie verläuft nicht, sie schmiert nicht und sie trocknet sehr schnell. Dummerweise trocknet sie ein wenig zu schnell! Meine letzte Portion ist ausgetrocknet, bevor ich die Abschrift beenden konnte, und ich hatte bisher keine Gelegenheit, mehr Tinte herzustellen!$B$BUm mehr herzustellen, benötige ich Rethbaneisenerz aus dem Rotkammgebirge. Großknecht Oslow in Seenhain ist mein üblicher Lieferant.",objectives={"Sprecht mit Großknecht Oslow in Seenhain und fragt ihn nach Rethbaneisenerz."}]])
R(346,"Rückkehr zu Kristoff",[[description="Nachdem ich jetzt mit der Abschrift fertig bin, könnt Ihr das Original von \"Belastbarkeit von Eisen\" haben. Ich danke Euch für Eure Geduld, und wenn Ihr Milton seht, bitte sagt ihm, die lange Verzögerung täte mir Leid.",objectives={"Kehrt zu Bruder Kristoff auf den Kathedralenplatz zurück. Gebt ihm das Buch: \"Belastbarkeit von Eisen\"."}]])
R(347,"Rethbanerz",[[description="Rethbanerz wurde nach dem Mann benannt, der es als Erster entdeckt hat, Bart Rethban. Wenn es geschmolzen wird, ist es nicht so stark wie Eisen, aber sein Erz hat eine dunkle, glatte Farbe, die einige Schreiber in ihren Farbtinten verwenden. Man kann es in den Rethbanhöhlen nördlich von hier finden.$B$BWir haben normalerweise etwas davon auf Lager, aber wir sind zu sehr damit beschäftigt, uns auf Orcangriffe vorzubereiten, als dass wir welches sammeln könnten. Und nur so nebenbei... In den Rethbanhöhlen leben jetzt Rotkammgnolle und deren Zwangsarbeiter bauen das Erz selbst ab.$B$BWenn Ihr also welches benötigt, müsst Ihr es Euch selbst besorgen.",objectives={"Sammelt 5 Fuhren Rethbanerz und bringt sie Bruder Paxton in der Bibliothek von Nordhain."}]])
R(348,"Schlingendornfieber",[[description="Krank... so... furchtbar k-k-krank... $b$b... habe mich mit Schlingendornfieber angesteckt... tödliches V-v-virus... $b$b... einziges Heilmittel... wäre... wäre es... das Herz von M-m-m-mokk dem Wilden zu essen... schwer zu fassendes, weißes Wildtier... $b$b... Hexendoktor Unbagwa... Einziger, der es b-b-beschwören kann...$b$b... sucht Unbagwa... versteckte Höhle am südlichen Kap...$b$b... schnell... sterbe... sterbe...",objectives={"Sucht Hexendoktor Unbagwa und lasst ihn Mokk den Wilden beschwören. Bringt das Herz von Mokk zu Fin Fizracket."}]])
R(349,"Schlingendornfieber",[[description="Hallo, $N!$B$BSprich mit meinem Freund Hexendoktor Unbagwa.",objectives={"Sprecht mit Hexendoktor Unbagwa."}]])
R(350,"Auf einen alten Freund verlassen",[[description="Marzon würde ein Mitglied der Defias kontaktieren und er hat Verbindungen zu Lescovar... $B$BDa van Cleef und Thredd tot sind, wäre es schwierig, einen Richtspruch gegen Lescovar zu erwirken, denn Eure Beweise sind wertlos ohne deren Zeugnis. Und dabei wird noch nicht einmal die Tatsache berücksichtigt, dass Lescovar ja ein Adliger ist und viele Beziehungen hat. Das stellt ihn gewissermaßen über das Gesetz.$B$BWir werden weitere Hilfe benötigen. Ich tu das nur äußerst ungern, aber ich kenne jemanden, der uns helfen wird. Ihr findet Trias im Handelsdistrikt der Stadt.",objectives={"Sprecht mit Elling Trias in Stormwind."}]])
R(351,"Findet OOX-17/TN!",[[description="Ihr habt ein merkwürdiges Gerät aus Metall entdeckt, das die Form eines Eis hat. Als Ihr einen der Knöpfe berührt, erwacht das Ei zu Leben und verwandelt sich in eine Art Gnom-Roboter-Apparat! Aus dem Inneren des Roboteis erklingt eine rasselnde Stimme.$B$B\"Mein Name ist Oglethorpe und mein Leitroboter ist verloren gegangen! Ich würde Euch belohnen, wenn Ihr ihn aufspürt! Bringt dem Roboter bitte diesen Signalgeber. Hervorragend, jetzt habe ich die Koordinaten für Euch berechnet! Er ist in der Nähe der Klaffenden Schlucht in Tanaris abgestürzt!\"",objectives={"Bringt das Notsignal zum Leitroboter von Oglethorpe."}]])
R(352,"<UNUSED>",[[description="Great Mammoda. Enormous, she was, with claws and teeth like swords. Now, I was caught off my guard, but I don't think being ready would have helped my cause much. One swipe and poof! Darkness. They say I'm lucky to walk now...$b$bWell, not much enjoyment to be had in hearing that old story now, is there? Anyways, $n, if you'd like to try yourself against her, the Lady of the Loch,"]])
R(353,"Stormpikes Lieferung",[[description="Die Stormpikes sind ein geachteter Zwergenklan und bekannt für ihren feinen und kritischen Geschmack. Daher ist es nicht verwunderlich, dass Gringer Stormpike, ein Gebirgsjäger aus Ironforge, mich beauftragte, ihm eine Waffe zu schmieden.$B$BDie Waffe ist fertig, aber... Gebirgsjäger Stormpike ist weit weg, am fernen Loch Modan. Wenn Ihr ohnehin vorhabt, nordwärts zu reisen, könntet Ihr ihm dieses Päckchen überbringen?$B$BMeine letzte Nachricht von Gebirgsjäger Stormpike besagte, dass er im nördlichen Wachturm des Loch Modan stationiert ist.",objectives={"Bringt das Päckchen für Stormpike zu Gebirgsjäger Stormpike am Loch Modan."}]])
R(354,"Todesfälle in der Familie",[[description="Die Familie Agamand war die wohlhabendste in Tirisfal. Ich habe früher in ihrer Mühle gearbeitet... vor der Seuche.$B$BAls die Geißel das erste Mal auftauchte, befestigten die Agamands ihre Heimstatt und überredeten ihre Angestellten zu bleiben und bei der Verteidigung zu helfen. Wir waren Narren, aber wir waren loyale Narren.$B$BDie Agamands haben uns in ihrem Stolz zum Untod verdammt. Und heute sind sie Diener der Geißel!$B$BDient den Verlassenen, indem Ihr die Agamands besiegt, die der Seuche zum Opfer fielen. Dient mir, indem Ihr mir ihre Überreste bringt.",objectives={"Bringt Coleman Farthing in Brill Gregors Überreste, Nissas Überreste und Thurmans Überreste."}]])
R(355,"Gespräch mit Sevren",[[description="Ihr habt mir die Überreste der Agamands gegeben und meinen Rachedurst gestillt. Aber Agamands Mühlen sind eine Bedrohung für alle Verlassenen, nicht nur für mich.$B$BIch habe mit Magistrat Sevren über Eure Heldentaten gegen die Agamands geredet, und er wünscht, mit Euch zu sprechen.",objectives={"Sprecht mit Magistrat Sevren in Brill."}]])
R(356,"Patrouille zur Rückendeckung",[[description="Die Verteidiger auf dem Bollwerk, die Tirisfal vor den Pestländern schützen, sind immer wachsam. Aber manchmal schafft es die Geißel, an ihnen vorbeizuschlüpfen.$B$BUnser Erfolg am Bollwerk hängt an einer Ein-Fronten-Schlacht - wir können keinen Angriff von hinten zulassen, und noch weniger können wir zulassen, dass die Versorgungslinie unserer Verteidiger unterbrochen wird.$B$BUnterstützt das Bollwerk. Patrouilliert ostwärts und erschlagt alle Untoten, die Ihr findet. Seid auf Balnirs Bauernhof im Osten besonders gründlich. Es hat sich zu einem Zufluchtsort für eindringende Untote entwickelt.",objectives={"Tötet 8 blutende Schrecken und 8 wandernde Geister und meldet Euch dann wieder bei Linnea in ihrem Lager."}]])
R(357,"Die Identität des Lichs",[[description="Es gibt einen Lich, der auf einer Insel im Blendwassersee im Norden haust. Obwohl er ein Verlassener mit freiem Willen ist, glaubt er, dass alle anderen Untoten Sklaven der Geißel sind, und hetzt seine Diener auf jeden, der sich ihm nähert.$B$BAber da er ein Verlassener ist, wird die Königin ihn haben wollen. Und wenn er in der Totenbeschwörung bewandert ist, dann wäre sein Wissen... recht nützlich für uns.$B$BUm etwas über seine Identität und sein Können herauszufinden, muss ich mir sein Zauberbuch ansehen. Stehlt Euch in sein Lager, verschafft es Euch und kehrt dann zu mir zurück.",objectives={"Bringt das Zauberbuch des Lichs zu Bethor Iceshard in Undercity."}]])
R(358,"Grabräuber",[[description="Die Massengräber südwestlich von Garrens Schlupfwinkel weiter im Norden wurden geschaffen, um der... eindrucksvollen... Anzahl Todesfälle gerecht zu werden, die Tirisfal erlitt, als die Seuche zum ersten Mal über uns kam. $B$BDen Toten in diesen Gräbern blieb der Untod bisher erspart, aber die Geißel schickt jetzt Moderfellgnolle, um die Leichen einzusammeln, um sie zur Verstärkung ihrer Armeen einzusetzen. Das können wir nicht zulassen!$B$BIhr habt zweierlei Aufgaben: Erschlagt die Moderfelle am Massengrab und in Garrens Schlupfwinkel und nehmt Euch von ihnen das Einbalsamierungssekret, das ihnen Leben verleiht.",objectives={"Tötet Grabräuber der Moderfelle und Bastarde der Moderfelle. $B$BBringt Magistrat Sevren in Brill 8 Einbalsamierungssekrete."}]])
R(359,"Verlassenen-Pflichten",[[description="Ich brauche einen aktuellen Bericht von unserem Außenposten der Todeswache im Osten.$B$BIch muss wissen, ob mehr Streitkräfte der Geißel am Bollwerk vorbei und nach Tirisfal herein geschlichen sind. Unsere Wachsamkeit an der Grenze zu den Pestländern muss aufrechterhalten werden - wir können die Geißel hier nicht stärker Fuß fassen lassen!$B$BReist südwärts die Straße entlang und biegt an der Gabelung nach Osten zum Außenposten ab. Sprecht mit Todeswache Linnea. Sie hat die Informationen, die ich benötige.",objectives={"Sprecht mit Todeswache Linnea."}]])
R(360,"Rückkehr zum Magistrat",[[description="Kehrt jetzt zu Magistrat Sevren mit den Informationen zurück, die ich euch gegeben habe. Er wird sie so schnell wie möglich haben wollen, also sputet Euch.$B$BUnd solltet Ihr unterwegs welche von der Geißel sehen, schaltet sie aus - wir können sie nicht unbehelligt durch unser Land spazieren lassen.",objectives={"Kehrt zu Magistrat Sevren nach Brill zurück."}]])
R(361,"Ein nie zugestellter Brief",[[description="Dies ist ein Brief, der von Thurman, dem ältesten Sohn von Gregor Agamand, geschrieben wurde. Er ist an Yvette Farthing adressiert, aber er scheint nicht bei ihr angekommen zu sein...",objectives={"Findet Yvette Farthing und bringt Ihr den Brief von Thurman Agamand."}]])
R(362,"Die Spuk-Mühle",[[description="Devlin Agamand war der jüngere von zwei Söhnen der Familie Agamand und im Leben hätten sie unterschiedlicher nicht sein können. Thurman war groß und sanft, während sein jüngerer Bruder schwach und scharfzüngig war.$B$BAls Agamands Mühlen der Seuche anheim fielen, war ich nicht überrascht zu hören, dass Devlin ihr schnell erlag. Sein verrücktes Gebrabbel kann man heute noch nahe der Straße hören, die zu Agamands Mühlen führt.$B$BIch sammle die Überreste der Agamands und ich möchte den armen Devlin. Findet ihn, vernichtet ihn und bringt mir seine Knochen.",objectives={"Erschlagt Devlin Agamand und bringt Devlins Überreste zu Coleman Farthing nach Brill."}]])
R(363,"Unsanftes Erwachen",[[description="Wurde auch Zeit, dass Ihr aufwacht. Wir wollten Euch gerade mit den anderen ins Feuer werfen, aber es sieht so aus, als hättet Ihr es geschafft.$b$bIch bin Mordo, der Verwalter der Deathknell-Gruft. Und Ihr seid kein Sklave des Lichkönigs mehr.$b$bSprecht mit Schattenpriester Sarvis in der Kapelle am Fuße des Hügels, er wird Euch mehr über das erzählen, was Ihr wissen müsst.",objectives={"Sprecht mit Schattenpriester Sarvis."}]])
R(364,"Die Hirnlosen",[[description="Wir Verlassenen liegen im Krieg mit der Geißel, der Armee des Lichkönigs: durch Nekromantie erweckte Armeen von Untoten, grausige Bestien des Nordens und gepeinigte Schreckgespenster.$b$bDer nördliche Teil des Dorfes wurde von den Hirnlosen überrannt, und diese müssen vernichtet werden. Vernichtet sie, zeigt ihnen keine Gnade, auch wenn sie unsere früheren Brüder und Schwestern gewesen sein mögen. Die Gefallenen sind nichts als Sklaven des Lichkönigs.",objectives={"Schattenpriester Sarvis will, dass Ihr 8 hirnlose Zombies und 8 elende Zombies tötet."}]])
R(365,"Felder des Kummers",[[description="Was haben wir denn hier? Ihr seht wie ein Neuling aus, $C. Wenn Ihr darauf hofft, Euch der Dunklen Fürstin zu beweisen, dann müsst Ihr die Gebräuche der Verlassenen erlernen.$b$bIm Westen werdet Ihr einen Hof vorfinden. Menschen suchen das Land heim wie Schimmel eine verrottende Leiche. Und um es noch schlimmer zu machen, patrouilliert ganz in der Nähe der Scharlachrote Kreuzzug von seinem Turm aus. Erteilt diesem Abschaum eine Lektion und stehlt 10 ihrer kostbaren Kürbisse.$b$bSobald Ihr 10 beisammen habt, bringt sie zu Apotheker Johaan nach Brill.",objectives={"Stehlt 10 Kürbisse vom Gehöft im Westen, direkt nördlich von Deathknell und bringt sie zu Apotheker Johann nach Brill."}]])
R(366,"Rückgabe des Buches",[[description="Vor langer Zeit waren Gunther und ich, wie auch der jetzt der Geißel dienende Totenbeschörer Thule Rabenklaue, Freunde und Schüler beim Kirin Tor, einer Magiergesellschaft in Dalaran.$B$BGunther und ich fielen beide der Seuche anheim, aber ich dachte, er wäre entweder tot geblieben oder für die Armee des Lichkönigs erweckt worden. Es tut gut zu wissen, dass er frei ist.$B$BWir müssen ihn für uns gewinnen. Ich habe einen Zauber auf dieses Buch gelegt, der ihm, sobald er ihn sieht, zeigen wird, dass ich ebenfalls frei vom Einfluss des Lichkönigs bin. Ich hoffe, dass er sich uns anschließt, wenn er das erfährt.",objectives={"Bringt Gunthers Zauberbuch zu ihm auf die \"Gunthers Zufluchtsort\" genannte Insel zurück."}]])
R(367,"Eine neue Seuche",[[description="Lady Sylvanas hat sich an die königliche Apothekervereinigung gewandt. Die dunkle Fürstin glaubt, dass unser Wissen, gepaart mit der neuentdeckten Magie, der Schlüssel zu Arthas' Untergang sein wird. Sie hat uns aufgefordert, eine neue Seuche zusammenzubrauen, eine Seuche, tödlicher als jedes Leiden in ganz Azeroth. Diese neue Krankheit wird Arthas' Armee der Geißel ins Verderben stürzen.$b$bMeine Studien zeigen, dass das Blut von Bestien der Schlüssel sein könnte. Bringt mir 5 Phiolen Schattenhundblut, damit ich meine Theorie ausprobieren kann.",objectives={"Apotheker Johaan in der Stadt Brill möchte, dass Ihr 5 Phiolen Schattenhundblut sammelt."}]])
R(368,"Eine neue Seuche",[[description="Während Ihr unterwegs wart und Proben für mich gesammelt habt, haben meine Experimente ergeben, dass noch weitere Reagenzien benötigt werden, wenn sich diese Krankheit ordentlich ausbreiten soll. Ein paar unglückliche Opfer zu vergiften, ist eine Kleinigkeit. Eine ganze Welt erkranken zu lassen, erweist sich als etwas komplizierter.$b$bIch werde 5 Finsterflossenschuppen von den Murlocs in der Umgebung brauchen. Ihr findet die Kreaturen entlang der Küste im Norden oder Westen von hier.",objectives={"Apotheker Johaan in der Stadt Brill benötigt 5 Finsterflossenschuppen von den Murlocs in Tirisfal."}]])
R(369,"Eine neue Seuche",[[description="Während Ihr sammeln wart, habe ich einen alten Text in einem meiner Bücher entdeckt, der darauf hindeutet, dass eine uralte Seuche Tausende unschuldiger Opfer ausgelöscht hat. Man fand später heraus, dass der tödliche Erreger im Gift der Nachtweberspinnen erhalten blieb.$b$bBringt mir etwas Gift eines heimtückischen Nachtwebers, um dieses Experiment abzuschließen. Ich möchte sehen, ob das ansteckende Element des Giftes mit meinem neuen Gebräu harmoniert. Gerüchten zufolge leben die Spinnen im östlichen Tirisfal.",objectives={"Apotheker Johaan in der Stadt Brill möchte, dass Ihr ihm 4 Proben vom Gift eines heimtückischen Nachtwebers bringt."}]])
R(370,"Im Krieg mit dem Scharlachroten Kreuzzug",[[description="Die strategischen Dokumente von Exekutor Arren enthalten alle Angaben, die wir brauchen, um die menschliche Plage aus den Ländern zu tilgen. Nach diesen Informationen hat der Scharlachrote Kreuzzug Captain Perrine mit einer Brigade dem verfallenen Turm südwestlich von Brill zugeteilt.$b$bTötet Perrine, sowie 3 Zeloten und 3 Missionare und erstattet mir dann Meldung.",objectives={"Exekutor Zygand in Brill möchte, dass Ihr Captain Perrine, 3 Scharlachrote Zeloten und 3 Scharlachrote Missionare tötet."}]])
R(371,"Krieg mit dem Scharlachroten Kreuzzug",[[description="Wir befinden uns noch immer im Krieg, und der Scharlachrote Kreuzzug gewinnt an Stärke. Der Bericht, den mir Exekutor Arren schickte, zeigt auf, dass die Scharlachroten Kreuzzügler ihre Überfälle von dem verfallenen Turm im südöstlichen Tirisfal, nahe Balnirs Bauernhof, unter dem Kommando von Captain Vachon ausgeführt haben.$b$bTötet Vachon, zusammen mit 5 Scharlachroten Ordensmitgliedern. Das sollte sich als vernichtender Schlag für den Kreuzzug erweisen!",objectives={"Exekutor Zygand in Brill hat Euch damit beauftragt, Captain Vachon und 5 Scharlachrote Ordensmitglieder zu erschlagen."}]])
R(372,"Krieg mit dem Scharlachroten Kreuzzug",[[description="Scharlachrote Kreuzzügler haben vom verfallenen Turm im nördlichen Tirisfal, hinter Faols Ruheplatz, Überfälle ausgeführt. Nach den Informationen, die wir haben, führt ein unbarmherziger Kommandant mit Namen Captain Melrache diese bösartige Truppe an.$b$bIch vertraue Euch eine besondere und gefahrvolle Mission an. Erschlagt Melrache und seine beiden Leibwachen im Namen der dunklen Fürstin.",objectives={"Exekutor Zygand in der Stadt Brill möchte, dass Ihr Captain Melrache und seine beiden Leibwachen ermordet."}]])
R(373,"Der nie verschickte Brief",[[description="Als Ihr Edwin van Cleef durchsucht, findet Ihr unter anderem einen nie verschickten Brief. Er ist adressiert an \"Baros Alexston, Stadtarchitekt von Stormwind, Rathaus, Kathedralenplatz\".$B$BEr scheint erst vor kurzem geschrieben und versiegelt worden zu sein.",objectives={"Bringt den Brief nach Stormwind zum Stadtarchitekten Baros Alexston."}]])
R(374,"Beweise des Ablebens",[[description="Exekutor Zygand sagt mir, dass Ihr Scharlachrote Kreuzzügler töten wart. In Tirisfal wimmelt es nur so von denen.$b$bVarimathras, Offizier der Dunklen Fürstin, kümmert sich persönlich darum, dass der Abschaum Azeroths, die Menschen, völlig ausgelöscht wird. Hier in Tirisfal stehen wir einer besonders lästigen Menschenbrut gegenüber: dem Scharlachroten Kreuzzug.$b$bBegebt Euch hinaus und führt eine Offensive gegen den Scharlachroten Kreuzzug, $C. Bringt mir 10 Scharlachrote Insignienringe zum Beweis Eurer Loyalität Varimathras und der Dunklen Fürstin gegenüber.",objectives={"Bringt Todeswache Burgess in Brill 10 Scharlachrote Insignienringe."}]])
R(375,"Die Kälte des Todes",[[description="Es ist jetzt so kalt. Die Seuche des Untodes kriecht durch meine Adern wie eine eisige Schlange. Ich werde bald den Hirnlosen Zustand erreichen. Doch auch ein besiegeltes Schicksal wird mich nicht davon abhalten, unserer Dunklen Fürstin zu dienen. Als der Ruf ertönte, nähte ich Leichensäcke für die gefallenen Soldaten von Sylvanas' mächtiger Armee.$b$bJetzt zittern meine Hände vor lauter Kälte. Wenn Ihr mir fünf Nachtsaugerpelze und etwas groben Faden bringen würdet, könnte ich mir eine Decke nähen. Helft mir, $n, auf dass ich der Sache weiter dienen kann.",objectives={"Bringt Gretchen Dedmar in Brill fünf Nachtsaugerpelze und etwas groben Faden."}]])
R(376,"Die Verdammten",[[description="Meine Pflichten umfassen, die verwundeten Krieger zu versorgen, Rüstung und Kleidung zu schneidern und Schattenpriester Sarvis in jeder erdenklichen Weise zu unterstützen.$b$bEs sieht so aus, als würdet Ihr ebenfalls in seine Dienste aufgenommen... wahrscheinlich um die Hirnlosen zu jagen, wie ich ihn kenne. Tja, wenn Ihr dabei in einem Stück bleiben wollt - und ich bezweifle nicht, dass Ihr das wollt -, dann kann ich Euch vielleicht helfen. Mir gehen die Tatzen und Flügel aus, und wenn Ihr mir einige davon bringt, besorge ich Euch eine Rüstung. Ihr werdet im Norden eine Menge Wölfe und Fledermäuse finden.",objectives={"Novize Elreth benötigt 6 Aasfressertatzen und 6 Nachtsaugerflügel."}]])
R(377,"Verbrechen und Strafe",[[description="Als wäre die Vernachlässigung der Einwohner des Dämmerwalds nicht schlimm genug, nein, die jüngste Entscheidung des Oberhauses, Dextren Ward in Stormwind ins Gefängnis zu werfen, anstatt den Schurken - wie durch Lord Ebonlockes Urteil gefordert - zu enthaupten, ist ein Schlag ins Gesicht für den Rat von Dunkelhain.$b$bWard wurde dabei erwischt, wie er Leichen aus dem Friedhof an Morbent Fel verkaufte, ein Verbrechen, auf das der Tod steht. Und dennoch fordert Stormwind seine Gefangensetzung.$b$bErmordet Ward im Verlies von Stormwind - bringt mir seine Hand - und ich werde Euch belohnen.",objectives={"Ratsherr Millstipe von Dunkelhain will, dass Ihr ihm die Hand von Dextren Ward bringt."}]])
R(378,"Tief empfundener Zorn",[[description="Ihr habt Eure Loyalität zu König Magni bewiesen, $C. Und Euer Hass auf den Dunkeleisenabschaum ist genau so groß wie mein eigener.$b$bEs gibt da eine Aufgabe, die ich selbst beenden möchte, aber ich bin durch meine Ehre verpflichtet, bei Longbraid zu bleiben. Jedoch hat Roggo Informationen gesammelt, die belegen, dass Kam Deepfury einer der Verschwörer beim Angriff auf den Thandol-Übergang war. Durch Deepfurys Pläne verlor Longbraid seine Sippe.$b$bDeepfury wird aus politischen Gründen im Verlies von Stormwind festgehalten. Ich will ihn tot sehen, $N. Für Longbraid! Bringt mir seinen Kopf!",objectives={"Motley Garmason in Dun Modr verlangt Kam Deepfurys Kopf."}]])
R(379,"Durstlöscher",[[description="Ihr möchtet eine Kraftquelle. Da kann ich Euch helfen. Wisst Ihr, was ich möchte? Ich möchte etwas zu Trinken! Bringt mir fünf Wasserbeutel eines Wüstenläufers und ich werde Euch die 4711-FTZ geben.$B$BUnd jetzt... ratet einmal, wo Ihr solche Wasserbeutel finden könnt! Warum geht Ihr nicht zu einem der Wüstenläufernomaden östlich von hier und bittet ihn um einen? Lasst mich wissen, ob das klappt.",objectives={"Bringt Chefingenieur Bilgewhizzle in Gadgetzan 5 Wasserbeutel eines Wüstenläufers."}]])
R(380,"Nachtweber",[[description="Eine unserer größten Schwierigkeiten besteht darin, die Rohstoffe zu besorgen, die wir zum Überleben brauchen. Gold war schon zu Hochzeiten der Macht der Allianz selten.$b$bEs gibt eine Goldmine im Nordwesten, die von Spinnen überrannt wurde. Wir brauchen das Gold dieser Mine, aber wir können es ja schlecht holen, während die Spinnen darin herumkrabbeln. Ich habe nicht viel Personal übrig für diese Aufgabe, also müssen wir sie Schritt für Schritt lösen.$B$BBegebt Euch dorthin und schaut mal, was Ihr für uns ausrichten könnt, $n.",objectives={"Exekutor Arren will, dass Ihr 10 junge Nachtweber und 8 Nachtweber tötet."}]])
R(381,"Der Scharlachrote Kreuzzug",[[description="Ihr werdet erfreut sein zu hören, dass wir anscheinend Fortschritte in der Mine machen. Der Dank dafür gebührt zu einem nicht unerheblichen Maß Euren Bemühungen. Nun können wir uns anderen Belangen zuwenden.$b$bMeine Späher haben berichtet, dass eine Abteilung des Scharlachroten Kreuzzugs südöstlich von hier ein Lager errichtet. Der Scharlachrote Kreuzzug ist eine verabscheuungswürdige Organisation, die uns jagt, und sie wird nicht ruhen, ehe nicht alle Untoten - ganz gleich, ob Teil der Geißel des Lichkönigs oder nicht - vernichtet sind. Wir müssen ihnen zuvorkommen!$b$bSeid vorsichtig, denn der unheilige Eifer dieser Leute macht sie zu gefährlichen Gegnern.",objectives={"Bringt Exekutor Arren insgesamt 12 Scharlachrote Armbinden von Scharlachroten Konvertiten und Scharlachroten Initianden."}]])
R(382,"Der Rote Bote",[[description="Berichte meiner Vorgesetzten in Brill weisen darauf hin, dass ein Agent des Scharlachroten Kreuzzugs vom Scharlachroten Kloster hierher nach Deathknell entsendet wurde. Nach diesen Berichten führt dieser Bote wichtige Informationen mit sich. Ich kann nicht mit Einzelheiten dienen, aber was auch immer es ist, wir müssen es haben!$b$bIhr seid die qualifizierteste Person, die ich darauf ansetzen kann, $n. Findet diesen Boten und bringt mir alle Informationen, die er bei sich trägt.",objectives={"Tötet Meven Korgal, den Boten, im Lager der Kreuzzügler und kehrt danach mit allen Informationen, die Ihr findet, zu Exekutor Arren zurück."}]])
R(383,"Entscheidende Informationen",[[description="Das muss zu meinem Vorgesetzten, Exekutor Zygand, nach Brill gebracht werden. Mit diesen Informationen können wir dem Scharlachroten Kreuzzug einen entscheidenden Schlag versetzen. Eure Dienste waren hier in Deathknell nützlich, aber ich benötige jemanden, der dies zu Zygand bringt, und ich denke, er wird angemessenere Arbeiten für Euch finden. $b$bNehmt die Straße nach Norden, hinaus aus Deathknell. Kurz nachdem Ihr nach Tirisfal hineinkommt, trefft Ihr auf eine Kreuzung. Nehmt die Abzweigung nach Osten und behaltet diese Richtung dann bei. Ihr werdet unterwegs am Coldhearth-Anwesen vorbeikommen.",objectives={"Bringt die Dokumente des Scharlachroten Kreuzzugs zu Exekutor Zygand nach Brill."}]])
R(384,"Eberrippchen in Biersauce",[[description="Meine Tavernengäste mögen nichts so sehr wie meine Eberrippchen in Biersauce. Das einzige Problem dabei ist, dass der ortsansässige Fallensteller, der mich bisher mit den Zutaten versorgt hat, in die Armee des Königs eingetreten ist, um im Krieg an der Allianzfront zu helfen. $b$bVielleicht könnt Ihr mir helfen? Wenn Ihr mir sechs Klippeneberrippchen bringt und ein Rhapsody-Malzbier von der Taverne hier besorgt, bekommt Ihr das Familienrezept für meine berühmten Eberrippchen in Biersauce, und nicht zu vergessen natürlich eine Kostprobe! Das Geheimnis liegt im Malz!",objectives={"Ragnar Donnerbräu in Kharanos benötigt 6 Klippeneberrippchen und einen Krug Rhapsody-Malzbier."}]])
R(385,"Krokiliskenjagd",[[description="So manchen Jäger zieht es an den Loch Modan, um unsere berühmten Kroks zu erlegen. Irgendein Händler sucht immer Krokiliskenhäute für seine Kleidungsstücke oder Rüstungen und es gibt auch einige Leute, denen ihr Fleisch mundet.$b$bWir handeln ein wenig damit, aber nicht wirklich viel, denn die Krokilisken sind wild und haben sich auf den Inseln im Loch verschanzt. Aber ich will Euch nicht davon abbringen, denn es ist ein unvergessliches Erlebnis, mit den Kiefern der Bestien zu ringen.$b$bAch ja, das eine Mal damals...",objectives={"Besorgt 5 Stücke Krokiliskenfleisch und 6 Krokiliskenhäute für Marek Ironheart in der Weitschreiter-Lodge."}]])
R(386,"Verbrechen lohnt sich nicht",[[description="Targorr der Schreckliche diente als oberster Exekutor unter Gath'llzogg. Er ging grausam vor, selbst nach den Standards der dreckigen Orcs. Menschen, die tapfer gekämpft hatten, um das Königreich zu verteidigen, wurden nur zu seiner Belustigung gefoltert. Heute wird er im Verlies von Stormwind gefangen gehalten und wurde zum Tode verurteilt. Dennoch stimmt irgendetwas nicht. Einer dieser bürokratischen Adeligen hat seine Exekution ausgesetzt. Ich bin mir sicher, hier wird eine Schandtat geplant.$b$bMacht Targorr dem Schrecklichen ein Ende, $N. Reist zum Verlies und enthauptet ihn, bevor man uns überlistet.",objectives={"Bringt Wache Berton in Seenhain den Kopf von Targorr dem Schrecklichen."}]])
R(387,"Niederschlagung des Aufstandes",[[description="Der Aufstand muss niedergeschlagen werden! Ich brauche Eure Hilfe. Wenn jemand mitbekommt, dass das Gefängnis überrannt wurde, verliere ich meinen Job! Solch übles Spiel habe ich noch nie erlebt. Aber was jetzt zählt ist, die Gefangenen zur Sicherheit Stormwinds niederzuringen.$b$bDie Strafe für Auflehnung lautet Tod. Tötet einige dieser Abweichler! Das sollte die Angelegenheit wieder unter Kontrolle bringen.",objectives={"Aufseher Thelwater aus Stormwind will, dass Ihr im Verlies 10 gefangene Defias, 8 eingekerkerte Defias und 8 Aufrührer der Defias tötet."}]])
R(388,"Die Farbe von Blut",[[description="Verbitterung fließt wie ein kalter Fluss durch meine Adern. Mein Enkel, Mac, war so ein guter Junge. Gerade mal 14 Jahre alt. Als die Armee an die Front geschickt wurde, griff Mac zu den Waffen, um die Stadt zu verteidigen. Er war eine Wache im Verlies, wo diese elenden Defias eingesperrt sind. Mac wies ein paar der Gefangenen dafür zurecht, dass sie ihre Wolldecken zerrissen, um Schals daraus zu machen, die ein Symbol ihrer Bande darstellen. Dafür wurde Mac hinterhältig erstochen.$b$bIch will Rache. Bringt mir 10 ihrer kostbaren Wollkopftücher. Sie haben die Farbe von Blut.",objectives={"Nikova Raskol von Stormwind will, dass Ihr 10 rote Wollkopftücher für sie sammelt."}]])
R(389,"Bazil Thredd",[[description="Van Cleef und ich waren beide Mitglieder der Steinmetzgilde. Unser Hauptprojekt war der Wiederaufbau Stormwinds nach dem Krieg.$B$BAls wir unsere Aufgabe erfüllt hatten, wurden wir betrogen. Die Adligen verweigerten uns die Bezahlung für unsere Arbeit. Einigen der älteren Steinmetze wurden Posten in der Regierung angeboten, aber van Cleef lehnte aus Loyalität zu den übrigen Steinmetzen ab. Er führte eine Revolte an und verließ, Rache schwörend, die Stadt.$b$bSein Helfer, Bazil Thredd, könnte vielleicht mehr über van Cleefs Pläne wissen. Er wird im Verlies gefangen gehalten.",objectives={"Sprecht mit Aufseher Thelwater im Verlies."}]])
R(390,"<UNUSED>")
R(391,"Aufstand im Verlies",[[description="Lasst uns eine Sache klarstellen, $n: Ich traue Euch nicht. Aber wie die Sache im Moment aussieht, werdet Ihr ohnehin keinen Unterschied machen.$B$BAlso wird das folgendermaßen ablaufen: Geht da runter und redet mit Thredd. Wenn Ihr wirklich auf unserer Seite seid, dann eliminiert ihn und bringt mir seinen Kopf, wenn Ihr fertig seid. Und falls sich herausstellt, dass Ihr auf seiner Seite seid und nicht herauskommt... werdet Ihr zusammen mit dem Rest dieser Würmer sterben, wenn wir Euch finden.",objectives={"Tötet Bazil Thredd und bringt seinen Kopf mit zurück zu Aufseher Thelwater im Verlies."}]])
R(392,"Der seltsame Besucher",[[description="In den ersten Jahren von Thredds Gefangenschaft bekam er niemals Besuch. Ich ging davon aus, dass er für die Bruderschaft keinen Nutzen mehr hatte und sie ihn daher fallen ließ.$B$BAber vor einigen Monaten hat sich das alles geändert; er bekam regelmäßig Besuch ... einmal, manchmal sogar zweimal pro Woche. Es war ein seltsamer Mann, so ein ruhiger Typ. Ich hatte da so meinen Verdacht, aber alle seine Papiere waren in Ordnung.$B$BLaut seinen Dokumenten war sein Name Maelik; hier habt Ihr seine Beschreibung. Ich glaube nicht, dass er noch einmal kommen wird, um Thredd zu besuchen.",objectives={"Bringt die versiegelte Beschreibung von Thredds Besucher nach Stormwind zu Baros Alexston."}]])
R(393,"Schatten der Vergangenheit",[[description="Ich habe wirklich keine Ahnung, $n. Aber es gibt da jemand anderen, der Euch vielleicht helfen kann, und wie es der Zufall so will, schuldet dieser Jemand mir einen Gefallen, weil... egal, das brauchen wir jetzt nicht zu vertiefen. Ihr könnt Meister Mathias Shaw vom SI:7 in der Kaserne in der Altstadt finden. Shaw hat seine Finger in den meisten zwielichtigen oder heimlichen Geschäften der Stadt.$B$BWenn also jemand etwas weiß, dann er.",objectives={"Bringt die versiegelte Beschreibung von Thredds Besucher nach Stormwind zu Meister Mathias Shaw."}]])
R(394,"Der Kopf des Ganzen",[[description="Sucht Shaw in der Altstadt. Teilt ihm mit, dass Ihr Euch um die Bedrohung durch Lescovar gekümmert habt, und berichtet ihm von Eurer Beteiligung an den Plänen des Lords gegen die Stadt. Ich bin sicher, er wird stolz sein, einen weiteren Helden unter den Bürgern Stormwinds zu haben.$B$BEr wird Euch ganz bestimmt zu einem Treffen mit dem Prinzen oder einem anderen Adligen schicken. Lasst Euch das nicht zu Kopfe steigen, $N. Die Adligen können noch so sehr glauben, dass sie die Stadt beherrschen, aber einige Dinge bleiben für die im Dunklen.",objectives={"Sprecht mit Mathias Shaw in Stormwind."}]])
R(395,"Das Ende der Bruderschaft",[[description="Ach, das hätte ich fast vergessen. Alexston kam vorbei, als Ihr unterwegs wart, und wünschte mit Euch zu sprechen. Zweifellos möchte er den Adligen über die Ränkespiele der Defiasbruderschaft berichten.$B$BEin kleiner Rat, $n: Sollte Euch jemand fragen, würde ich zwar alle Details offen legen, aber dabei nicht erwähnen, dass es Eure Hand war, die Lescovar erschlug. Vertraut mir. Ich... kenne mich aus... mit solchen Dingen.$B$BUnd was Trias angeht, nun, sprecht mit niemandem über ihn... niemals... wenn Ihr es vermeiden könnt.",objectives={"Sprecht mit Baros Alexston in Stormwind."}]])
R(396,"Eine Audienz beim König",[[description="Ich habe einen Bericht an den König vorbereitet. Und Ihr sollt sein Überbringer sein, zusammen mit einer Auflistung Eurer Ergebnisse. Macht Euch keine Sorgen, er wird Euch zweifellos für die Erfüllung Eurer Pflicht gegenüber den Leuten von Stormwind loben.$B$BEure Audienz findet in Kürze statt, also solltet Ihr Euch besser beeilen, denn es ist schon ein Stück Weges bis zur Burg Stormwind.",objectives={"Liefert Baros Alexstons Bericht über die Bruderschaft der Defias bei König Varian Wrynn in der Burg Stormwind ab."}]])
R(397,"Ihr habt uns gut gedient",[[description="Wie ich höre, hat Lord Wishock sein Getränk genossen. $b$bIhr habt uns gut gedient, $N. Die Hexenmeister von Stormwind werden nun, dank Euch, ohne Störung ihrem Tagewerk nachgehen können. Ich habe ein besonderes Geschenk vorbereitet, um Euch für Eure Mühen zu entlohnen. Sprecht mit meinem Diener, Zggi, um Eure Belohnung zu erhalten.",objectives={"Sprecht mit Zggi, dem Diener von Zardeth von den Blackclaw, um Eure Belohnung zu erhalten."}]])
R(398,"GESUCHT: Madenauge",[[description="Gesucht: Madenauge!$b$bDie selbst für einen Gnoll außerordentlich niederträchtige Kreatur wurde für ihre Verbrechen an den Verlassenen zum Tode verurteilt. Dieser verabscheuungswürdige Verbrecher hat Leichen für die Armee des Lichkönigs gestohlen. Madenauge wurde zuletzt gesehen, als er die Gegend nahe Garrens Schlupfwinkel nördlich von Brill plünderte.$b$bDie Stadt Brill bietet hiermit eine Belohnung für die fähige Seele, die die Exekution durchführt. Zeigt Exekutor Zygand die Tatze des Verbrechers, wenn die Tat getan ist.$b$bGnade ist etwas für die Schwachen.",objectives={"Tötet Madenauge und kehrt dann mit seiner Tatze zu Exekutor Zygand nach Brill zurück, um eine Belohnung zu erhalten."}]])
R(399,"Ein bescheidener Anfang",[[description="Es kommt mir so vor, als wäre es ewig her, dass ich als Junge in Westfall auf dem Hof gearbeitet habe. Man sagt ja, man kann niemals in der Zeit zurückgehen, und es stimmt wohl. In meinem Fall trifft das sogar gleich doppelt zu, denn das Heim meiner Familie wurde niedergebrannt und von Dieben besetzt.$b$bIch habe mit meinem Vater über den Verbleib einiger meiner Habseligkeiten gesprochen, darunter mein erster Kompass. Er konnte sie nicht retten. Allerdings meint er auch, dass sie auf dem Hof versteckt sein müssten.$b$bIhr findet den Alexstons Bauernhof westlich der Späherkuppe. Könntet Ihr vielleicht dorthin gehen und mir meinen Kompass wiederbringen?",objectives={"Begebt Euch zu Baros Alexstons Haus in Westfall und sucht nach seinem Kompass. Übergebt ihm diesen dann am Kathedralenplatz von Stormwind."}]])
R(400,"Werkzeuge für Steelgrill",[[description="Beldin Steelgrill ist der Besitzer der örtlichen Maschinenschlosserei, und er ist der beste Monteur von Belagerungsmaschinen, den es gibt! Allerdings geht er nicht sehr gnädig mit seinen Werkzeugen um. Ich schwöre Euch, er macht bald mehr Bogenlichtschraubenschlüssel kaputt, als wir ihm liefern können!$B$BWir haben gerade seine letzte Werkzeugbestellung fertig. Wenn Ihr sie ihm anliefert, wird er sich sicherlich erkenntlich zeigen.$B$BSein Geschäft, Steelgrills Depot, liegt etwas nordöstlich von Kharanos. Und nebenbei, es handelt sich dort um einen örtlichen Treffpunkt für die Veteranen unter den Piloten der Belagerungsmaschinen, also hört Euch ruhig ein wenig um, während Ihr dort seid.",objectives={"Liefert Beldin Steelgrill seine Werkzeuge."}]])
R(401,"Wartet, bis Sirra fertig ist",[[description="Ich bin fast mit der Übersetzung dieser Notiz fertig. Wenn Ihr in ein paar Minuten wiederkommt, dürfte ich fertig sein.",objectives={"Wartet einen Moment und sprecht dann erneut mit Sirra Von'Indi."}]])
R(403,"Das bewachte Fass mit Donnerbier")
R(404,"Eine eitrige Aufgabe",[[description="Teile der Geißel sind nach und nach in Tirisfal eingedrungen und suchen die Gegend westlich von Brill heim, nahe der alten Brücke.$B$BGeht dorthin und schlagt die Faulenden Toten und Verheerten Kadaver zurück, die Ihr dort vorfindet. Zerstreut ihre Knochen und bringt uns ihre eitrigen Klauen, dann werden die Todeswachen Euch entlohnen.",objectives={"Bringt Todeswache Dillinger in Brill 7 eitrige Klauen."}]])
R(405,"Der abtrünnige Lich",[[description="Bethor Iceshard, ein hochrangiger und mächtiger Magier aus Undercity im Süden, befiehlt mir, ihm einen Agenten zu schicken, der seinen Wert gegen die Geißel bereits bewiesen hat. Ihr, $N, werdet dieser Agent sein.$B$BZeigt Bethor diese Befehle. Er wird Euch daraufhin über Eure Mission aufklären. Ich kenne keine Details, aber es hat etwas damit zu tun, einen eigenwilligen Lich zu rekrutieren. Und es wird gefährlich sein.$B$BAlso macht Euch bereit, $C. Ihr dürft nicht scheitern.$B$BIhr dürftet Bethor im Magieviertel von Undercity finden.",objectives={"Zeigt Bethor Iceshard in Undercity Sevrens Befehle."}]])
R(406,"<UNUSED>")
R(407,"Felder des Kummers",[[description="Harmlose Kürbisse, oder? Zumindest sehen sie so aus. Wenn wir Arthas' Vormarsch im Norden und die menschliche Plage im Süden stoppen wollen, müssen wir alle Möglichkeiten unseres untoten Daseins nutzen.$b$bMit etwas Einfallsreichtum wird sogar aus einem einfachen Kürbis ein Agent für unsere Dunkle Fürstin. Dieser Kürbis wird sich, wenn nach meiner jüngsten Formel behandelt, als eine besondere Leckerei erweisen.$b$bEs wurde schon wieder ein Scharlachroter Zelot gefangen genommen, der derzeit im Keller der Taverne Zur Galgenschlinge gefangen gehalten wird. Bringt dem Trottel diesen Kürbis.",objectives={"Bringt den getränkten Kürbis zum gefangenen Scharlachroten Zeloten, der im Keller der Taverne Zur Galgenschlinge gefangen gehalten wird."}]])
R(408,"Die Familiengruft",[[description="Die Gegend um Agamands Mühlen hat sich zu einem Außenposten der Geißel entwickelt. Am stärksten sind sie in der Gruft der Familie Agamand, wo ihr örtlicher militärischer Anführer, ein Skelett namens Captain Dargol, sein Hauptquartier hat. Er hat die Vorfahren der Agamands durch Nekromantie wiedererweckt und hat vor, sie gegen uns einzusetzen.$B$BDies darf nicht geschehen, und Ihr müsst es verhindern. Reist zur Gruft der Familie Agamand und besiegt die erweckten Vorfahren der Agamands.$B$BUnd bringt mir den Schädel von Captain Dargol.",objectives={"Tötet 8 Klagende Vorfahren und 8 Faulende Vorfahren.$B$BTötet Captain Dargol und bringt seinen Schädel zu Magistrat Sevren nach Brill."}]])
R(409,"Treuebeweis",[[description="Ihr behauptet, Ihr wärt nicht dem Willen des Lichkönigs unterworfen, und die Verzauberung, die Bethor auf mein Buch legte, untermauert dies. Aber bevor ich Euch glaube, muss ich den Beweis haben, dass Ihr der Geißel feindlich gegenübersteht.$B$BEs gibt einen alten, blutigen Altar kurz vor der Südküste dieser Insel. Er wird von einer mächtigen Dienerin der Geißel, Lillith Nefara, verwendet.$B$BNehmt eine Kerze des Heranlockens aus dieser Kiste hier. Entzündet sie auf dem Altar, und Lillith wird erwachen. Vernichtet Lillith, und ich werde Euch glauben, dass Ihr ein Gegner des Lichkönigs seid.",objectives={"Beschafft Euch eine Kerze des Heranlockens.$B$BBeschwört Lillith Nefara und tötet sie.$B$BKehrt zu Gunther auf seiner Insel zurück."}]])
R(410,"Der Schlummernde Schatten")
R(411,"Die Rückkehr des abtrünnigen Lichs",[[description="Bringt meinem alten Kameraden Bethor diesen Netheredelstein. Er wird uns ermöglichen, miteinander zu kommunizieren... und ich habe ihm eine Menge zu erzählen.",objectives={"Bringt den Netheredelstein zu Bethor Iceshard nach Undercity."}]])
R(412,"Operation Rekombobulationsgerät",[[description="Nach genauerer Analyse der Situation in Gnomeregan sieht es so aus, als hätten wir nicht nur dabei versagt, die Troggs auszulöschen, sondern als hätten wir dabei auch noch einen Großteil des Volkes der Gnome in schreckliche, hirnlose, bösartige Lepragnome verwandelt.$b$bOzzie und ich haben vor, den schrecklichen Lepraeffekt mit unserer jüngsten Erfindung wieder rückgängig zu machen: der Rekombobulator. Die Maschine ist beinahe fertig, aber wir brauchen dringend einige Restabilisationszahnräder und gyromechanische Getriebeteile. Besorgt uns ein paar davon bei den Lepragnomen drüben in Gnomeregan.",objectives={"Bringt Razzle Sprysprocket in Kharanos 8 Restabilisationszahnräder und 8 gyromechanische Getriebeteile."}]])
R(413,"Schimmerstarkbier",[[description="Ich möchte, dass mein Bruder Wellart mein neues Schimmerstarkbier ausprobiert. Er ist Gebirgsjäger und im südlichen Wachturm stationiert, einem von zwei Türmen an der Grenze zum Loch Modan.$B$BEr mag vielleicht kein Bierbrauer sein wie der Rest von uns Gerstenbräus, aber er trinkt gern mal einen, und ich bin mir sicher, er wird dies hier mögen.$B$BKönnt Ihr ihm dieses Fass Schimmerstarkbier für mich bringen?",objectives={"Bringt das Fass mit Schimmerstarkbier zu Gebirgsjäger Gerstenbräu."}]])
R(414,"Starkbier für Kadrell",[[description="Ich habe inzwischen mehr von diesem Schimmerstarkbier getrunken, das mein Bruder gebraut hat - das ist großartiges Zeug! Ein Gebirgsjägerkumpel von mir muss das mal probieren. Er heißt Kadrell und patrouilliert normalerweise entlang der Straße durch Thelsamar beim Loch Modan.$B$BUm nach Thelsamar zu gelangen, müsst Ihr südostwärts durch den Tunnel gehen und dann nach Nordosten abbiegen, wenn der Pfad auf eine Straße trifft. Dieser Straße folgt Ihr direkt bis nach Thelsamar.$B$BGebt Gebirgsjäger Kadrell dieses Fässlein Schimmerstarkbier und schaut mal, was er davon hält!",objectives={"Bringt das Fässlein mit Schimmerstarkbier zu Gebirgsjäger Kadrell."}]])
R(415,"Rejolds neues Gebräu",[[description="Rejold Gerstenbräu aus Brewnall hat nach Euch gefragt.$B$BEr möchte mit Euch über ein neues Getränk reden, das er gebraut hat... er sagte etwas davon, dass Ihr ihm vielleicht dabei helfen könntet. Vielleicht wollt Ihr also wieder nach Brewnall zurückkehren, um herauszufinden, worum es geht.$B$BEs könnte etwas Freibier für Euch drin sein...",objectives={"Sprecht mit Rejold Gerstenbräu."}]])
R(416,"Rattenfang",[[description="Wir haben im Westen ein Problem mit einer echten Plage. Kobolde der Tunnelratten sind ins Vorgebirge eingedrungen, haben dort ihre Baue eingerichtet und verdrecken unser Land mit ihrem Abfall!$B$BWir wollen, dass sie ausgelöscht werden. Jagt sie, bringt mir ihre Ohren und kassiert das Kopfgeld.$B$BIhr findet die Kobolde der Tunnelratten und ihre Baue westlich von Thelsamar überall über den Berghang verteilt.",objectives={"Bringt Gebirgsjäger Kadrell in Thelsamar 12 Tunnelrattenohren."}]])
R(417,"Pilotenrache",[[description="Hildelve schrieb in sein Tagebuch, dass er von Marterklaue, einem \"gewaltigen Eisklauenbären\", angegriffen wurde. Er hat die Bestie verjagt, aber nicht, ohne vorher übel zugerichtet zu werden.$B$BWenn man sich den Zustand von Hildelves Leiche so ansieht, muss Marterklaue später wiedergekommen sein und ihn getötet haben.$B$BJedenfalls schrieb Hildelve in sein Tagebuch einen letzten Wunsch:$B$BRache an Marterklaue.",objectives={"Tötet Marterklaue.$B$BBringt Pilot Hammerfoot die räudige Klaue des Bären und Hildelves Tagebuch."}]])
R(418,"Thelsamar-Blutwurst",[[description="Es gibt hier in Thelsamar immer genug Mäuler zu stopfen, mit all den Kindern, die ein und aus gehen, und den Arbeitern von den Ausgrabungsstätten, die nach einem arbeitsreichen Tag hereinkommen. Wir sind berühmt für unsere Blutwurst, Ihr habt sie nicht zufällig schon einmal probiert?$b$bNein? Nun, hierzulande muss man für seine Mahlzeiten arbeiten, und glaubt nur nicht, dass Ihr eine Ausnahme seid, nur weil Ihr ein toller $C seid.$b$bIch brauche Bärenfleisch, Ebergedärme für die Pelle und Spinnensekret als Würzmittel. Bringt mir das alles und überlasst dann Vidra das Kochen!",objectives={"Bringt Vidra Hearthstove in Thelsamar 3 Stück Bärenfleisch, 3 Portionen Ebergedärme und 3 Portionen Spinnensekret."}]])
R(419,"Der vermisste Pilot",[[description="Mein Freund Mori Hildelve, ebenfalls ein Pilot der Belagerungsmaschinen, hat sich in den Hügeln verirrt. Wir haben nach einem seltenen Erz gesucht, das man für hochwertiges Sprengpulver benötigt, und während unserer Suche hat er seine Maschine einen steilen Hügel hinaufgefahren und sie dabei kaputt gemacht!$B$BImmer noch überzeugt davon, dass es in diesen Bergen Erz gibt, hat er mich beauftragt, unsere Maschinen zu bewachen, während er zu Fuß weitersuchen wollte.$B$BDas ist jetzt mehrere Tage her, und ich habe in den Hügeln des Nachts das Knurren von Raubtieren gehört. Mori ist ein zäher Bursche, aber ich mache mir Sorgen.$B$BBitte, $N. Sucht ihn.",objectives={"Findet Pilot Hildelve."}]])
R(420,"Senirs Beobachtungen",[[description="Die Troggs im Tunnel sind extrem feindselig und scheinen nicht zu zögern, durch den Tunnel reisende Leute anzugreifen. Ihr seid aber offenbar hart genug im Nehmen, also solltet ihr wahrscheinlich sicher sein.$b$bEine Wegbeschreibung? Wenn Ihr mit Senir sprechen wollt, findet Ihr ihn in Kharanos.$b$bArbeitet Euch durch den Tunnel und folgt einfach weiter der Straße, wenn Ihr auf der anderen Seite herauskommt, denn sie führt direkt nach Kharanos.",objectives={"Überbringt Senir Whitebeard in Kharanos Grelins Bericht."}]])
R(421,"Wertbeweis",[[description="Lady Sylvanas hat Varimathras damit beauftragt, die Gebiete der Menschen und Zwerge im Süden zu erobern.$b$bAber dieser Idiot Arugal - ein Scharlatan aus Dalaran und heutzutage eine verfluchte Kreatur der Burg Shadowfang - hat auf verantwortungslose Weise mit seiner Magie den strategischen Stützpunkt des Silberwaldes verheert.$b$bIch brauche einen geschickten Kämpfer, der dabei hilft, die Suppe auszulöffeln, die Arugal uns eingebrockt hat. Beweist Euch mir, indem Ihr 5 Moonrage-Weißskalps tötet. Man findet die elenden Bestien oft nur ein kleines Stück abseits der Straße, am Fuße des Hügels dort unten.",objectives={"Dalar Dawnweaver auf dem Grabmal will, dass Ihr 5 Moonrage-Weißskalps tötet."}]])
R(422,"Arugals Torheit",[[description="Wie Arugal in die Kirin Tor aufgenommen wurde, ist mir schleierhaft. Seine Zauberkunst schien so billig wie schlecht nachgemachter Schmuck.$b$bAm wichtigsten ist es erst einmal, herauszufinden, welche Art von Magie Arugal genau verwendet hat, damit ich sie gegen ihn verwenden und den Silberwald für die Dunkle Fürstin einnehmen kann.$b$bArugal hielt sich zuerst auf der Weizenfarm etwas nördlich der Brücke auf. Einer der Todespirscher berichtete, dass er einige Zauberbücher gesehen hätte, sie aber nicht beschaffen konnte. Beschafft mir den Zauber namens 'Arznei des Arugal' aus diesen Büchern.",objectives={"Beschafft Dalar Dawnweaver auf dem Grabmal die Arznei des Arugal."}]])
R(423,"Arugals Torheit",[[description="Bei der Untersuchung von Arugals Arbeit haben sich meine schlimmsten Befürchtungen bestätigt. Der alte Taugenichts war nicht einmal qualifiziert genug, um die Nachttöpfe in Dalaran zu leeren, davon, die Kirin Tor in ihrer schwersten Stunde zu repräsentieren, ganz zu schweigen. Narren!$b$bArugal benutzte verzauberte Gegenstände, um seine schwache Magie zu verstärken. Ich muss diese Gegenstände selbst untersuchen. Zieht los und erschlagt so lange Moonrage-Nimmersatts und Moonrage-Dunkelseelen, bis Ihr genug ihrer verzauberten Fesseln für meine Nachforschungen gesammelt habt. Man hat diese üblen Kreaturen im Norden und Osten gesehen.",objectives={"Bringt Dalar Dawnweaver am Grabmal 6 Nimmersattfesseln und 3 Dunkelseelenfesseln."}]])
R(424,"Arugals Torheit",[[description="Ich werde tatsächlich länger brauchen, als ich gedacht hätte, die dunklen Geheimnisse hinter den Verzauberungen, die Arugal verwendete, zu entdecken.$b$bIn der Zwischenzeit müsst Ihr Euch um ein kleines Problem kümmern, das unsere Dunkelpirscher entdeckt haben. Es sieht so aus, als hätte Arugal seiner Magie erlaubt, sich bis zur Tiefenfelsmine in den Hügeln im Südosten auszubreiten.$b$bDiese Mine wäre eine ziemlich nützliche Ressource für Varimathras' Vormarsch.$b$bIch will, dass Ihr Grimson den Blassen, den besudelten Großknecht der Mine, enthauptet. Mit seinem Tod sollte die Mine uns gehören.",objectives={"Tötet Grimson den Blassen und bringt seinen Kopf zu Dalar Dawnweaver auf das Grabmal."}]])
R(425,"Ivar der Verfaulte",[[description="Mein Bruder Quinn und ich wurden beauftragt, den Silberwald auszukundschaften und Hochexekutor Hadrec Bericht zu erstatten. Aber wir kamen nicht weit - als wir über diese Farm gingen, wurden wir von einem Ghul namens Ivar der Verfaulte angegriffen.$B$BWir entkamen Ivar, aber er verletzte Quinn schwer. Dank des Trankes, den Ihr ihm gegeben habt, heilt er, aber Ivar könnte wiederkommen, bevor Quinn sich erholt hat.$B$BTötet Ivar, damit Quinn genug Zeit hat, sich zu regenerieren. Ivar hält sich üblicherweise in dem Schuppen da drüben auf und wartet darauf, dass meine Wachsamkeit nachlässt.",objectives={"Tötet Ivar den Verfaulten und bringt Ivars Kopf zu Rane Yorick auf dem Ivar-Feld."}]])
R(426,"Die überrannte Mühle",[[description="Die Geißel versucht, bei Agamands Mühlen einen Stützpunkt zu errichten. Wenn ihnen das gelingt, können sie weitere Angriffe innerhalb von Tirisfal unternehmen.$B$BEs wurden klare Befehle erteilt. Die Diener der Geißel in den Mühlen müssen vernichtet werden.$B$BGeht zu den Mühlen. Sammelt schartige Rippen von klappernden Skelettsoldaten und Trümmerschädelsoldaten sowie geschwärzte Schädel von dunklen Skelettmagiern.$B$BUm zu den Mühlen zu gelangen, folgt der Straße westwärts. Nachdem Ihr die Brücke überquert habt, nehmt die erste Abzweigung nach Norden und folgt diesem Weg. Wenn Ihr die Windmühlen seht, beginnt die Schlacht.",objectives={"Sammelt 5 schartige Rippen sowie 3 geschwärzte Schädel und kehrt dann zu Todeswache Dillinger nach Brill zurück."}]])
R(427,"Im Krieg mit dem Scharlachroten Kreuzzug",[[description="Die Dokumente, die Exekutor Arren uns zur Verfügung stellte, verschaffen uns genau die Atempause, die wir in unserem Kampf gegen den Scharlachroten Kreuzzug benötigen. Wir kennen jetzt dessen genaue Aufenthaltsorte überall in Tirisfal.$b$bAber leider haben die Todeswachen noch ganz andere Sorgen. Die Armee des Lichkönigs wächst jede Nacht an. Wir benötigen jemanden, der wie Ihr gern \"Initiative\" zeigt, um den Scharlachroten Kreuzzug ins Grab zu bringen.$b$bBeweist mir, dass Ihr der Dunklen Fürstin dienen könnt, indem Ihr nach Westen zum Turm hinter Sollidens Bauernhof reist und dort 10 Scharlachrote Krieger erschlagt.",objectives={"Exekutor Zygand von Brill verlangt, dass Ihr 10 Scharlachrote Krieger tötet."}]])
R(428,"Die verlorenen Todespirscher",[[description="Vor einigen Wochen wurden zwei unserer Todespirscher, Rane und Quinn Yorick, auf eine Aufklärungsmission durch den nördlichen Silberwald geschickt. Wir haben nichts mehr von ihnen gehört.$B$BSie könnten der Geißel zum Opfer gefallen sein, doch wenn dem so ist, will ich es bestätigt wissen. Findet diese Todespirscher.$B$BIhre erste Aufgabe war es, die Bauernhöfe im nördlichen Silberwald auszukundschaften. Ihr solltet dort mit Eurer Suche beginnen.",objectives={"Findet die Todespirscher Quinn und Rane Yorick."}]])
R(429,"Wilde Herzen",[[description="Mein Bruder Quinn wurde von dem Ghul Ivar dem Verfaulten schwer verletzt, und ich glaube nicht, dass er ohne magische Hilfe wieder vollständig genesen wird. Auch wenn ich kein Apotheker bin, so weiß ich doch, dass unsere Apotheker Heiltränke aus verfärbten Worgherzen herstellen können.$B$BSammelt einige solcher Herzen und bringt sie zu Apotheker Renferrel am Grabmal im Süden. Kommt dann mit dem Trank hierher zurück.$B$BZwischen hier und Maldens Obsthain im Osten werdet Ihr jede Menge Worgs vorfinden.",objectives={"Sammelt 6 verfärbte Worgherzen und bringt sie zu Apotheker Renferrel auf dem Grabmal."}]])
R(430,"Rückkehr zu Quinn",[[description="Hier habt Ihr den Trank, mit dem Ihr Quinn Yoricks Erholung beschleunigen könnt.$B$BWenn Ihr mich jetzt entschuldigen mögt, ich habe wirklich wichtige Dinge zu erledigen...",objectives={"Bringt Quinn Yorick auf dem Ivar-Feld, nördlich des Grabmals, Quinns Trank."}]])
R(431,"Kerze des Heranlockens")
R(432,"Diese verfluchten Troggs!",[[description="Diese vom Licht verfluchten Troggs verwandeln meinen Arbeitsplatz in eine Ruine. Schaut Euch das an, da geht schon wieder ein Pulverfass hoch.$b$bOh, ich wünschte ich könnte da runtergehen und allen einzeln ihre dürren Hälse umdrehen! Ich will sie alle töten!$b$bDas kann nicht gut für meine Gesundheit sein, all dieser Stress und diese Wut... Was haben sie mir gelassen? Nichts!$b$bIch würde sie persönlich umbringen, aber ich ziele nicht mehr so gut wie früher. Geht in den Steinbruch und tötet einige dieser dreckigen Mistviecher! Ich werde Euch bezahlen! Hauptsache, Ihr verletzt sie, tötet sie!",objectives={"Tötet für Großknecht Stonebrow im Gol'Bolar Steinbruch 6 Schädelhauer der Felsenkiefer."}]])
R(433,"Im Dienste des Volkes",[[description="Als Mitglied des Senats und der Forscherliga habe ich mir vorgenommen, mich um den Teil der Trogg-Plage zu kümmern, die unser Land heimsucht.$b$bSie haben den Gol'Bolar Steinbruch wirklich ziemlich verwüstet, und das ohne erkennbaren Grund. Als wir tiefer in die Erde hineingruben, strömten sie heraus, zerstörten unsere Ausrüstung und verjagten die Minenarbeiter. Wir können nicht viel mehr tun, als das ganze Pack auszulöschen, alles wieder aufzubauen und dann wieder an die Arbeit zu gehen.$b$bWenn Ihr mir mit den Troggs helft, werde ich Euch gern für Eure Zeit, die Ihr dafür opfert, entschädigen.",objectives={"Tötet für Senator Mehr Stonehallow im Gol'Bolar Steinbruch 10 Knochenknacker der Felsenkiefer."}]])
R(434,"Der Angriff!",[[description="Nachdem ich dem Spionagebot die Verkleidung angelegt habe, begibt er sich hinein, um mit Lescovar zu sprechen. Die Wachen sollten ihn ohne Probleme durchlassen.$B$BWährend Ihr Material für mich gesammelt habt, habe ich Marzon darüber informiert, dass es für ihn und Lescovar an der Zeit sei, sich wieder zu treffen. Ich habe sogar einige falsche Informationen verlautbaren lassen.$B$BLescovar wird seine Wachen wegschicken und hier draußen im Garten auf Marzon warten. Tretet in Aktion, wenn Ihr etwas über die Defias hört. Ihr müsst sie beide eliminieren. Kapiert?$B$BWenn Ihr das erledigt habt, sprecht Ihr mit Trias.",objectives={"Bleibt im Garten, bis Lord Gregor Lescovar und Marzon die Stille Klinge ihr Gespräch beendet haben. Schaltet sie danach beide aus, bevor Ihr nach Stormwind zu Elling Trias zurückkehrt."}]])
R(435,"Eskorte für Erland",[[description="Die Wölfe da draußen wollen nicht abhauen, und jedesmal, wenn ich einen Schritt aus der Tür mache, schauen sie mich böse an. Sie müssen unglaublich hungrig sein, wenn sie mich für essenswert halten.$B$BIch muss mich bei meiner Kampfgefährtin, Todespirscherin Rane Yorick, melden. Und um zu Rane zu kommen, brauche ich Hilfe gegen diese Wölfe.$B$BBitte begleitet mich! Ach ja, da draußen sind eine Menge Wölfe, wir hätten also eine bessere Chance, wenn Ihr Freunde dabei hättet, die ebenfalls helfen können...",objectives={"Begleitet Erland durch die Wölfe hindurch zu Rane Yorick."}]])
R(436,"Ironbands Ausgrabungsstätte",[[description="Ausgrabungsleiter Ironband leitet die Ausgrabung einiger alter Ruinen östlich des Sees. Er hat zuletzt wenig Fortschritte gemacht, besonders, wenn man all den Nachschub bedenkt, den wir ihm geschickt haben.$B$BIronband ist ein bodenständiger, ehrlicher Zwerg, der gern Resultate sieht, und daher mache ich mir Sorgen, dass da irgendwelche Kräfte gegen ihn arbeiten.$B$BGeht zu Ironbands Ausgrabungsstätte und sprecht mit Magmar Fellhew. Er kümmert sich um die Einzelheiten an der Stätte und wird wissen, warum es so langsam voran geht.$B$BUm zur Ausgrabungsstätte zu gelangen, müsst Ihr um die Südspitze des Sees herum und dann nach Osten gehen.",objectives={"Sprecht mit Forscher Fellhew."}]])
R(437,"Das Todesfeld",[[description="Unsere ursprünglichen Spähberichte über den Silberwald zeigen, dass die Moderfelle auf einer alten Farm im Norden, nahe dem Todesfeld, einen Stützpunkt haben. Wir haben kleine Angriffe auf sie gestartet, aber jedesmal werden sie von der Banshee Nachtseele unterstützt, die ihre Magie einsetzt, um unsere Truppen in die Flucht zu schlagen.$B$BWir wollen Nachtseele vernichtet sehen.$B$BGeht ins Todesfeld und greift die Moderfelle an. Falls Ihr Nachtseele nicht seht, tötet so lange Moderfellgnolle, bis sie auftaucht, und besiegt sie dann.$B$BIhre Essenz wird zu Staub zerfallen. Bringt mir diesen Staub als Beweis.",objectives={"Tötet Gnolle der Moderfelle auf dem Todesfeld.$B$BSobald Nachtseele auftaucht, tötet sie ebenfalls.$B$BBringt Nachtseeles Essenz zu Hochexekutor Hadrec auf das Grabmal."}]])
R(438,"Die verfallene Fähre",[[description="$n, wir haben ein neues Nest der Geißel entdeckt: Die verfallene Fähre. Die Fähre liegt östlich des Grabmals und wird von Moderfellgnollen und anderen Untoten schwer bewacht.$B$BEs muss einen Grund dafür geben, warum die Geißel dieses Gebiet besetzt hat. Geht zur verfallenen Fähre und findet heraus, warum die Geißel sich dort aufhält.",objectives={"Geht zur verfallenen Fähre.$B$BSucht nach dem Grund, warum die Geißel dort ist."}]])
R(439,"Auf den Spuren der Moderfelle",[[description="Aus den Leichen ragt eine nicht eingewickelte Hand heraus. Es handelt sich um die Hand einer Frau, von der Seuche pockennarbig, aber relativ frisch. $B$BAn der Hand befindet sich ein Ring. Als Ihr den Ring entfernt und untersucht, entdeckt Ihr eine Gravur:$B$B\"Für Deliah\".",objectives={"Bringt Deliahs Ring zu Hochexekutor Hadrec auf das Grabmal."}]])
R(440,"Der gravierte Ring",[[description="Wenn Ihr den Ehemann oder Geliebten finden wollt, der Deliah ihren Ring gab... dann sprecht mit Magistrat Sevren in Brill. Er sollte alle Dokumente über die jüngsten Todesfälle haben und wird mit etwas Glück herausfinden können, wer Deliah ist.$B$BAber ich würde meine Hoffnungen nicht zu hoch stecken. Wer auch immer ihr den Ring gab, ist wahrscheinlich tot. Oder, wenn er untot ist, kümmert Deliah ihn wahrscheinlich nicht mehr.",objectives={"Bringt Deliahs Ring zu Magistrat Sevren nach Brill."}]])
R(441,"Raleigh und Undercity",[[description="Deliah hatte einen Ehemann, Raleigh, der nun in Undercity sein Zuhause hat. Wenn die Deliah, die in Brill wohnte, die ist, der dieser Ring gehörte, dann wird es Raleigh wissen.$B$BRaleigh ist im Handwerksviertel von Undercity.",objectives={"Bringt Deliahs Ring zu Raleigh."}]])
R(442,"Sturm auf die Insel Fenris",[[description="Es ist an der Zeit, den Standort der Geißel im Silberwald zu stürmen: die Insel Fenris.$B$BIhr müsst Euch noch einmal auf diese Insel begeben und Thule Rabenklaue vernichten. Ich will seinen Kopf!$B$BDiese Mission ist so gefahrvoll, wie sie entscheidend ist, $n. Ihr dürft nicht scheitern.",objectives={"Bringt Hochexekutor Hadrec auf dem Grabmal Thules Kopf."}]])
R(443,"Moderfellsekret",[[description="Bevor wir einen Angriff auf die Insel Fenris starten können, müssen wir erst herausfinden, wer hinter den Moderfellgnollen steht. Unsere Apotheker glauben, ihr Ursprung liegt in der seltsamen Flüssigkeit, die durch ihre Körper fließt.$B$BGeht zur Insel Fenris, östlich der verfallenen Fähre, und sammelt Moderfellsekret von den Gnollen dort. Bringt es zu Apotheker Renferrel, draußen vor dem Grabmal.",objectives={"Bringt 8 Flaschen Moderfellsekret zu Apotheker Renferrel auf das Grabmal."}]])
R(444,"Die Ursprünge der Moderfelle",[[description="Ich habe das Sekret, das Ihr mir gebracht habt, in seine Grundbestandteile aufgelöst. Meine Ergebnisse sind nicht sehr aufschlussreich, aber ich konnte ermitteln, dass Hexenmeister- und Totenbeschwörermagie zur Herstellung des Sekrets verwendet wurden.$B$BWährend ich weiter das Sekret untersuche, möchte ich, dass Ihr eine Probe davon zu Bethor Iceshard nach Undercity bringt. Bethor ist kein Apotheker, aber sein Wissen von der Magie könnte uns helfen, das Geheimnis um die Moderfelle zu lüften.$B$BGeht. Ihr dürftet Bethor im Magieviertel von Undercity finden.",objectives={"Bringt die Sekretprobe zu Bethor Iceshard nach Undercity."}]])
R(445,"Lieferung in den Silberwald",[[description="Zeit ist ein Luxus, den sich diejenigen, die für Lady Sylvanas arbeiten, nicht leisten können. Aber das wisst Ihr inzwischen sicher selbst.$b$bAls Mitglied der königlichen Apothekervereinigung ist es meine Pflicht, mein Wissen mit meinen Kollegen zu teilen, auf dass unsere gemeinsamen Bemühungen der dunklen Fürstin eines Tages die neue Seuche bescheren werden, die sie so ersehnt.$b$bBringt diese Erkenntnisse zu Apotheker Renferrel, der beim Grabmal im Silberwald stationiert ist. Folgt der Straße von Brill aus nach Süden. Geht dann nach Undercity südwestwärts.",objectives={"Bringt Apotheker Johaans Erkenntnisse zu Apotheker Renferrel im Silberwald."}]])
R(446,"Thule Rabenklaue",[[description="Dieses Sekret wurde von einem alten Kollegen von mir hergestellt: Thule Rabenklaue. Vor dem großen Krieg war er ein junger, aufstrebender Magier, aber als der Lichkönig immer mächtiger wurde, verriet er seine Brüder und verbündete sich mit der Geißel.$B$BIch hätte nicht gedacht, dass er noch lebt, geschweige denn, dass er die Moderfelle bei ihren Vorstößen gegen uns anführt.$B$BIch kenne viele seiner Zauber und kann dabei helfen, einen Trank zu brauen, der ihnen entgegenwirkt. Nehmt diese Spruchrolle mit zurück zu Apotheker Renferrel. Auf ihr stehen die Beschwörungsformeln, die man für den Trank braucht.",objectives={"Bringt Bethors Spruchrolle zu Apotheker Renferrel auf das Silberwald-Grabmal."}]])
R(447,"Rezept für den Tod",[[description="Arthas hat Truppen von schier endloser Zahl. Doch mit einer neuen Seuche könnten wir sowohl die Armee der Geißel als auch das menschliche Ungeziefer ein für alle Mal auslöschen.$b$bMeine Studien haben bewiesen, dass Spinnenblut, vermischt mit einem aus dem Herzen eines ergrauten Bären gewonnenen Toxin, zu einem tödlichen Elixier wird. Sammelt Proben von den Spinnen im Huschdunkel im Nordwesten und von den Bären, die im Silberwald umherstreifen. Bringt diese Reagenzien zu Meisterapotheker Faranell von der königlichen Apothekervereinigung in Undercity.",objectives={"Sammelt 6 Herzen von ergrauten Bären und 6 Proben Huschendes Blut und bringt diese zu Meisterapotheker Faranell nach Undercity."}]])
R(448,"Meldung bei Hadrec",[[description="Bevor Ihr einen Angriff auf die Insel Fenris unternehmt, meldet Euch bei Hochexekutor Hadrec. Er könnte zusätzliche Informationen oder Ausrüstung haben, die Ihr brauchen werdet.",objectives={"Meldet Euch bei Hochexekutor Hadrec auf dem Grabmal."}]])
R(449,"Der Bericht der Todespirscher",[[description="Auch wenn Quinns Wunden heilen, möchte ich doch unseren Bericht so schnell wie möglich zu Hochexekutor Hadrec bringen. Er enthält Informationen, die für die Besetzung des Silberwaldes durch die Verlassenen von höchster Wichtigkeit sind.",objectives={"Bringt den Todespirscherbericht zu Hochexekutor Hadrec auf das Grabmal."}]])
R(450,"Rezept für den Tod",[[description="Ihr könnt der königlichen Apothekervereinigung noch weiter zu Diensten sein, $N.$b$bAls Arugal seine elenden Zauber über den Wald gelegt hat, verfluchte er eines unserer viel versprechendsten Mitglieder, Apotheker Berard. Als hirnloser Diener von Arugal ist Berard jetzt für uns nutzlos. Aber seine Erkenntnisse könnten sich als wertvoll erweisen. Er untersuchte eine längst vergessene Seuche, die vor Ewigkeiten einmal alles Leben im Lordameresee getötet hat.$b$bBergt Berards Tagebuch aus seinem Studierzimmer im Gasthaus von Pyrewood und bringt es zu Apotheker Renferrel.",objectives={"Bergt Apotheker Berards Tagebuch aus Pyrewood und bringt es zu Apotheker Renferrel auf das Grabmal."}]])
R(451,"Rezept für den Tod",[[description="Laut Berards Tagebuch könnte sich das Moos von Seeschleichern und Seekrabblern bei unserer Suche nach einer neuen Seuche als nützlich erweisen. Diese Bestien leben auf den Inseln im Lordameresee im Osten.$b$bEr erwähnt außerdem einen sehr seltenen verhärteten Tumor, den er bei einem Finsterflossenmurloc entdeckte. Anscheinend war der Tumor so selten, dass Berard nur einen einzigen auftreiben konnte.$b$bSammelt Proben von diesem Moos sowie von dem seltenen verhärteten Tumor und bringt beides zu Meisterapotheker Faranell nach Undercity.",objectives={"Bringt 6 Proben Seeschleicher-Moos, 6 Proben Seekrabbler-Moos und einen verhärteten Tumor zu Meisterapotheker Faranell nach Undercity."}]])
R(452,"Der Pyrewood-Überfall",[[description="Ihr kommt gerade rechtzeitig, $N!$b$bDer Rat von Pyrewood wird jeden Moment zurückkehren. Arugal muss sich in der Burg um andere Dinge kümmern. Er benutzt den Rat als reine Schachfiguren, um die hirnlosen Diener von Pyrewood unter seiner Kontrolle zu halten. Aber ich glaube, dass die Söhne von Arugal sich ohne die Führung durch den Rat von Pyrewood gegen ihren Meister stellen werden.$b$bIch werde nicht allein mit ihnen allen fertig. Ihr müsst mir helfen. Gemeinsam können wir den Rat für Lady Sylvanas zerschlagen.",objectives={"Helft Todespirscher Faerleia, den Rat von Pyrewood zu töten."}]])
R(453,"Auf der Suche nach der Schattengestalt",[[description="Viel Glück, $n. Ich hoffe, Ihr könnt den Kerl finden, und dass er dann noch am Leben ist.$B$BWenn er die Sicherheit von Dunkelhain hinter sich gelassen hat, könnte er leicht Wildtieren zum Opfer gefallen sein.",objectives={"Findet die Schattengestalt. Eure Hinweise:$B$BEr stammt nicht aus Dunkelhain.$B$BEr ist eine nervöse, hektische Person.$B$BEr verließ Dunkelhain und ging nach Westen."}]])
R(454,"Nach dem Hinterhalt",[[description="Wir hatten vor dieser... Geschichte die Pulverfässer in mehreren Fuhren transportiert. Jetzt müssen wir die Arbeit aufteilen. Miran nimmt die Fässer, und ich passe auf die anderen auf.$b$bIch fühle mich nicht wohl dabei, Miran den Rest der Fracht ganz allein transportieren zu lassen. Vielleicht könntet Ihr ihn auf seiner nächsten Tour begleiten, wenn er fertig zur Abreise ist?",objectives={"Sprecht mit Miran."}]])
R(455,"Der Algaz-Spießrutenlauf",[[description="Orcs vom Dragonmawklan haben im Sumpfland eine Zufluchtstätte. Und jetzt haben sie sich nach Dun Algaz ausgebreitet. Wir können nicht zulassen, dass sie ihren Einfluss auf dieses Gebiet behalten, sonst wird der Loch Modan vom Hafen von Menethil, unserer Hafenfestung im Sumpfland, abgeschnitten.$B$BBrecht durch Dun Algaz in das dahinterliegende Sumpfland durch und tötet dabei ein paar Orcs. Meldet Euch bei Valstag Ironjaw im Hafen von Menethil.$B$BNach Menethil kommt Ihr, indem Ihr Dun Algaz durchquert, anschließend nordwärts der Straße folgt und Euch dann an der Biegung westwärts haltet.$B$BWir verlassen uns auf Euch, $N. Ihr dürft nicht scheitern.",objectives={"Durchquert Dun Algaz.$B$BTötet 8 Späher der Dragonmaw und 6 Grunzer der Dragonmaw.$B$BMeldet Euch bei Valstag Ironjaw im Hafen von Menethil."}]])
R(456,"Das Gleichgewicht der Natur",[[description="Seid gegrüßt, $N. Ich bin Konservator Ilthalaine. Meine Aufgabe in Shadowglen ist es, für den Erhalt des Gleichgewichts der Natur zu sorgen.$b$bDie Frühjahrsniederschläge waren dieses Jahr besonders heftig, was dafür sorgte, dass einige Tiere des Waldes gediehen, während andere darunter litten.$b$bUnglücklicherweise sind die Bestände an Nachtsäblern und Distelebern zu stark angewachsen. Shadowglen kann nur eine gewisse Menge Futter für diese Tiere erzeugen. Zieht los, $C, und dünnt die Eber- und die Säblerpopulation etwas aus, auf dass die Harmonie der Natur erhalten bleibt.",objectives={"Tötet 7 junge Nachtsäbler sowie 4 junge Disteleber und kehrt dann zu Konservator Ilthalaine zurück."}]])
R(457,"Das Gleichgewicht der Natur",[[description="Die Jungbestände einiger Kreaturen hier im Shadowglen auszudünnen, war ein guter Anfang, $N, aber es gibt immer noch etwas zu tun.$b$bDie Ressourcen des Waldes werden sich zu schnell erschöpfen, wenn sich niemand um das Problem kümmert. Mutter Naturs Wildtiere zu töten, ist ein notwendiges Übel zum Besten von allen, die sich das Land teilen. Begebt Euch in den Wald und erschlagt im Namen des Gleichgewichts räudige Nachtsäbler und Disteleber.",objectives={"Konservator Ilthalaine verlangt von Euch, 7 räudige Nachtsäbler und 7 Disteleber zu töten."}]])
R(458,"Die Beschützerin des Waldlandes",[[description="Was ein Glück, dass Ihr hier seid, $C. Vom Wispern der Waldgeister wurden mir seltsame Neuigkeiten zugetragen.$b$bDie geheimnisvolle Beschützerin des Waldlandes, Tarindrella, ist nach Shadowglen zurückgekehrt. Jahrelang war die Gegenwart der Dryade in den Wäldern Kalimdors nicht zu spüren. Sicherlich stimmt irgendetwas nicht, wenn sie jetzt wieder in diese Gegend zurückgekommen ist.$b$bSucht Tarindrella und findet heraus, was sie in unseren Hain führt. Eine der Schildwachen berichtete, sie südwestlich von Aldrassil gesehen zu haben.",objectives={"Sucht die Dryade, die als Tarindrella bekannt ist."}]])
R(459,"Die Beschützerin des Waldlandes",[[description="Etwas Böses braut sich im Wald von Teldrassil zusammen. Schaut Euch die Hügel an, in denen die friedlichen Furbolgs früher hausten. Sie haben ihre Heime verlassen und sammeln sich unter dem Banner des Knarzklauenstamms.$b$bNur die Verderbtheit des bösartigen Teufelsmooses könnte eine solche Wandlung geschehen lassen. Die Grells und Grellkin suchen die Gegend heim und bedrohen die Einwohner von Shadowglen. $b$bSpürt diese Grells und Grellkins auf, $N, und überzeugt Euch, ob sie wirklich unter dem Einfluss des bösartigen Teufelsmooses stehen.",objectives={"Sammelt 8 Stücke Teufelsmoos und bringt sie zu Tarindrella."}]])
R(460,"In Stücken begraben",[[description="Ihr seht nicht aus wie ein Moderfell. Gut. Ich hatte die Hoffnung schon aufgegeben...$B$BMein Name ist Alaric und ich war einst Thules oberster Diener und Leibwächter. Er nutzte seine Magie, um mich vor der Pest des Untodes zu \"schützen\", ein schöner Schutz... denn sein Zauber bürdete mir ein Unleben auf, dem ich nicht entrinnen kann. Und nachdem er diese verfluchten  der Moderfellgnolle erschaffen hatte, hat Thule mich geköpft... und meinen Kopf den Gnollen zum Spielen gegeben!$B$BBitte, bringt mich zu meinem Körper. Ich glaube, die Gnolle haben ihn hier in der Burg Fenris, nahe den Stallungen, in einem namenlosen Grab verscharrt.",objectives={"Bringt Alarics Kopf zu seinem Grab."}]])
R(461,"Die versteckte Nische",[[description="Ich kenne eine versteckte Nische in der Burg, die einen Gegenstand enthält, der für Thule und seine alten Kollegen sehr wichtig ist. Außerdem enthält sie noch etwas, das Ihr nützlich finden könntet. Bringt mich dorthin!$B$BDie Nische ist im Südwestturm der Burg, hinter einem staubigen Regal.$B$BNehmt meinen Körper mit, aber lasst die Stiefel hier. Die haben mir sowieso nie richtig gepasst.",objectives={"Bringt Alaric zur versteckten Nische."}]])
R(462,"<UNUSED>",[[description="Other than you, we sent two scouts through Algaz.  Only one returned.  Here's what he discovered:$B$BThe Dragonmaws sent one of their Lieutenants, Maruk Wyrmscale, to organize a crew of orcs in Algaz and cut off the land route to Menethil Harbor!$B$BWe have to stop this, now.  Take out Maruk, and then report to Valstag Ironjaw in Menethil Harbor.$B$BMaruk is headquartered in a small cave, across a pond between the second and third tunnels of Algaz.  Menethil is through Algaz, then west along the road.",objectives={"Kill Maruk Wyrmscale$B$BReport to Valstag Ironjaw in Menethil Harbor."}]])
R(463,"Der Sumpfhüter",[[description="Ihr habt vom Sumpfhüter gehört? Ihr sucht doch nicht etwa nach ihm, oder? Nun, ich behaupte ja, Ihr seid verrückt, wenn dem so ist, aber wer bin ich, dass ich $geinen Narren:eine Närrin; davon abhalte, in den Tod zu gehen?$B$BFalls Ihr ihn sucht - hmmm, ich habe gehört, er sei in den Marschen, ostwärts von dort, wo die Straße nach Dun Modr abzweigt. Er lungert dort bei den Kroks und Schlimmerem herum!$B$BAch, und lasst Euer Geld besser hier. Ihr werdet es dort, wo Ihr hingeht, nicht brauchen... und Ihr wollt doch sicher nicht, dass der alte Grünling sich an Eurem Gold einen Zahn ausbricht, wenn er Euch mittendurch beißt.",objectives={"Findet den Sumpfhüter."}]])
R(464,"Kriegsflaggen",[[description="Der orcische Dragonmawklan war am Ende des zweiten Krieges so gut wie vernichtet, nachdem sie die Kontrolle über ihre Schoßtierchen, die roten Drachen, verloren hatten. Die Drachen waren nicht sehr freundlich zu ihren früheren Herren und machten gnadenlos Jagd auf die Dragonmaw. Die wenigen, die überlebten, flohen aus Grim Batol in die Berge östlich von Whelgars Ausgrabungsstätte.$B$BJetzt haben sie an Stärke gewonnen und besitzen ein Lager nordöstlich von Menethil.$B$BWir wollen, dass Ihr dieses Lager angreift. Sammelt und bringt mir ihre Kriegsflaggen als Beweis.",objectives={"Bringt Captain Stoutfist 8 Kriegsflaggen der Dragonmaw."}]])
R(465,"Nek'roshs Schachzug",[[description="Während Ihr die Dragonmaw bekämpft habt, haben wir mehr über deren Pläne herausgefunden.$B$BNek'rosh hat Katapulte gebaut und beabsichtigt, Menethil zu belagern! Und dank der Kämpfe in Dun Algaz sind wir effektiv von Verstärkungen abgeschnitten!$B$BIhr müsst diese Katapulte zerstören. Sie befinden sich im Lager der Dragonmaw.$B$BHier, nehmt diesen Zunder. Kämpft Euch zu den Katapulten durch und lasst sie mit dem Zunder in Flammen aufgehen.$B$BUnd nachdem Ihr das getan habt, findet und tötet Nek'rosh. Wir müssen dieser Dragonmawbestie den Kopf abschlagen.",objectives={"Zerstört die Katapulte der Dragonmaw."}]])
R(466,"Auf der Suche nach Pyrophor",[[description="Ich habe gehört, im Sumpfland wurde in einer Höhle nordwestlich vom Algaz-Tor ein seltenes Erz namens Pyrophor gefunden. Pyrophor ist instabil und schwer anzuwenden, ohne sich dabei selbst in die Luft zu sprengen, aber ich bin mir sicher, wenn man es auf die richtige Art und Weise verhüttet, könnte man daraus Kanonenkugeln mit einer ziemlichen Durchschlagskraft herstellen.$B$BBesorgt mir Pyrophorerz und ich finde jemanden, der mutig genug ist, damit zu experimentieren.$B$BOh, und um dieses Erz aus einer Ader zu schürfen, müsst Ihr Euch mit Bergbau auskennen. Wenn dem nicht so ist, dann... nehmt einen Freund mit in diese Höhle, der es tut!",objectives={"Bringt 6 Ladungen Pyrophorerz zu Pilot Stonegear nach Dun Morogh."}]])
R(467,"Stonegears Suche",[[description="Pilot Stonegear liebt seine Belagerungsmaschine, wie jeder Pilot es auch sollte! Und er ist immer begierig, neue Wege zu finden, die Feuerkraft seines Panzers zu vergrößern!$B$BEr hat Gerüchte über ein seltenes Erz gehört und sucht jetzt nach jemandem, der es für ihn auftreibt. Wenn es Euch also in den Fingern juckt, dann sucht Stonegear in Steelgrills Depot in Dun Morogh auf und schaut mal, was er will.",objectives={"Sprecht mit Pilot Stonegear."}]])
R(468,"Meldung bei Gebirgsjäger Rockgar",[[description="Gebirgsjäger Rockgar sucht nach Freiwilligen für eine Mission durch Dun Algaz und in das Sumpfland hinein. $B$BWenn Ihr also Lust habt, Euch Eure Stiefel in dieser sumpfigen Gegend im Norden schmutzig zu machen, dann sprecht mit Rockgar in Dun Algaz. Dun Algaz liegt weiter die Straße entlang im Norden, hinter dem Wachturm.",objectives={"Sprecht mit Gebirgsjäger Rockgar."}]])
R(469,"Tägliche Lieferung",[[description="Seid gegrüßt!$b$bIhr seid nicht zufällig in Richtung Menethil unterwegs? Falls nicht, würde ich Euch empfehlen, dort Halt zu machen, denn es ist ein guter Ort, um Waren zu kaufen oder etwas trinken zu gehen und sich auszuruhen.$b$bTja, wenn Ihr also zufälligerweise in diese Richtung unterwegs seid, dann habt Ihr doch sicher nichts dagegen, dieses Bündel Krokiliskenhäute zu James Halloran, dem Gerber, zu bringen?$b$bIch würde es ja selbst tun, aber meine Frau ist in letzter Zeit ziemlich launisch, und ich würde es gern so lange wie möglich aufschieben, ihr zu begegnen.",objectives={"Liefert das Bündel Krokiliskenhäute bei dem Gerber James Halloran im Hafen von Menethil ab."}]])
R(470,"Stochern im Brühschlamm",[[description="Bei meinem wöchentlichen Besuch an Ironbeards Grabmal wurde ich von grässlichen, triefenden Brühschlammern angegriffen! Natürlich geriet ich in Panik.$b$bIch habe meine Tasche nach einem geworfen, aber das zeigte keinerlei Wirkung! Der Brühschlammer saugte sie einfach auf... Glücklicherweise gab mir das genug Zeit wegzulaufen.$b$bDie schlechte Nachricht ist, dass ich dringend den Inhalt meiner Tasche benötige!$b$bIch weiß nicht, nach welchem Brühschlammer ich meine Tasche geworfen habe; sie sehen alle gleich aus! Ironbeards Grabmal liegt nordöstlich von hier, in der Nähe von Dun Modr. Ich danke Euch wirklich sehr!",objectives={"Einer der Brühschlammer bei Ironbeards Grabmal hat Sidas Tasche. Bergt sie und bringt sie ihr zurück in den Hafen von Menethil."}]])
R(471,"Lehrlingspflichten",[[description="Ich habe meinen Lehrling in die Marschen geschickt, um einige unserer berühmten riesigen Sumpflandkrokilisken zu häuten. Als er nicht zurückkam, bin ich losgezogen, um ihn zu suchen... Sagen wir einfach, es war kein schöner Anblick.$b$bDie Schwester sagt, er könnte durchkommen, aber derweil brauche ich immer noch meine Häute!$b$bUnd wenn Ihr noch ein paar von den Monstern töten wollt, hätte ich nichts dagegen, nach allem, was sie getan haben. Ihr findet die Kroks, wenn Ihr die Küste entlang nach Norden geht, hinter den Hütten der Murlocs.",objectives={"Sammelt 6 riesige Krokiliskenhäute und bringt sie zu James Halloran in den Hafen von Menethil."}]])
R(472,"Der Fall von Dun Modr",[[description="Dun Modr ist an die Dunkeleisenzwerge gefallen!$b$bMeine Wunden sind schwer, $C. Ein Großteil meines Regiments wurde getötet! Diese Rohlinge der Dunkeleisenzwerge haben uns angegriffen, bevor wir uns nach dem Überfall auf den Thandol-Übergang wieder sammeln konnten.$b$bUnser Anführer, Longbraid, blies zum Rückzug. Als wir die Stadt verließen, wurde ich von einer verirrten Axt in den Rücken getroffen und alles wurde schwarz um mich.$b$bIch wachte hier in Menethil auf, aber ich fürchte um meine Kameraden. Ich hege allerdings noch Hoffnung. Vielleicht ist Longbraid noch am Leben! Seht nach, ob Ihr ihn in der Nähe von Dun Modr finden könnt, $R!",objectives={"Sucht nahe der Stadt von Dun Modr nach Longbraid."}]])
R(473,"Meldung bei Captain Stoutfist",[[description="$N. Der Dragonmawklan der Orcs zeigt nicht nur in Algaz Stärke. Captain Stoutfist wünscht mit denen zu sprechen, die Hilfe gegen diese Orcs anbieten wollen. Er ist in der Burg, im Kriegsraum.",objectives={"Sprecht mit Captain Stoutfist."}]])
R(474,"Sieg über Nek'rosh",[[description="Jetzt, nachdem die Katapulte abgebrannt wurden, sucht und tötet Häuptling Nek'rosh.",objectives={"Tötet Häuptling Nek'rosh.$B$BBringt Nek'roshs Kopf zu Captain Stoutfist."}]])
R(475,"Ein beunruhigender Wind",[[description="Ein beunruhigender Wind weht durch den Wald.$b$bGaerolas Talvethren dient den schlafenden Druiden der Kralle in den Grabhügeln von Ban'ethil als Großer Aufseher. Seine Pflicht als auserwählter Beschützer der Schlafenden ist es, deren Sicherheit zu gewährleisten, auf dass sie ihrem Pakt mit Ysera gerecht werden.$b$bAber es gab länger keine Nachricht von Gaerolas, und ich werde etwas nervös. Reist nach Osten, zum Dorf Starbreeze, und bringt mir einen Bericht von Gaerolas, auf dass ich meine Sorgen begraben kann, da ich weiß, dass meine träumenden Brüder sicher schlummern.",objectives={"Sucht Gaerolas Talvethren im Dorf Starbreeze auf."}]])
R(476,"Die Verderbnis der Knarzklauen",[[description="Der Knarzklauenstamm ist verderbt worden!$b$bDie einstmals friedliebenden Furbolgs haben sich gegen die Beschützer des Waldes gewandt. Sie haben mich hinterrücks überfallen, als ich auf dem Weg zum Grabhügel von Ban'ethil war und liefen weiter, um Starbreeze zu plündern. Ursal der Raufer, ihr Häuptling, benutzt die bösen Mächte des Teufelsmooses, um sie wahnsinnig werden zu lassen.$b$bMeine Wunden sind zu schwer, ich kann nicht zu Athridas zurückkehren und ihm diese schlimme Nachricht überbringen. Junger $C, diese Aufgabe bleibt Euch überlassen. Wir können nur hoffen, dass die verrückten Knarzklauen noch nicht bis nach Ban'ethil vorgedrungen sind!",objectives={"Kehrt zu Athridas Bearmantle nach Dolanaar zurück."}]])
R(477,"Grenzübergänge",[[description="Wie Ihr vielleicht bereits wisst, die Stadt Ambermill ist weiterhin eine Quelle der menschlichen Opposition, die nötige Unterstützung erhalten sie meist durch die Hexer von Dalaran.$b$bIch weiß nicht, wie ihr Plan aussieht, aber ihr Interesse an einem Hinterwäldler-Dorf wie Ambermill zeigt mir, dass es von größerer Bedeutung sein muss.$b$bVon Hillsbrad aus haben sie wagenweise Kisten geliefert. Viele dieser Vorräte werden in ein kleines Camp nördlich von Pyrewood gebracht. Bringt mir den Inhalt einer dieser Kisten.",objectives={"Holt den Inhalt einer der Kisten von den Hexern aus Dalaran. Ihr findet Pyrewood im Süden."}]])
R(478,"Karten und Runen",[[description="<Schnell entnehmt Ihr den Anhänger aus der Kiste und setzt den Deckel wieder auf.>",objectives={"Bringt den seltsamen Anhänger zu Schattenpriester Allister in dem Grabmal."}]])
R(479,"Ambermill-Nachforschungen",[[description="Dalar versucht die Quelle für die Zaubereien der Hexer zu finden. In der Zwischenzeit müssen wir ihren Fortschritt mit allen Mitteln aufhalten...$b$bAlle Herbeizauberer, Magier und Beschützer tragen mit Sicherheit ihre Anhänger. Nehmt sie ihnen ab und bringt sie hierher.$b$bFolgt der Hauptstraße in südlicher Richtung und nehmt dann die östliche Abzweigung nach Ambermill.",objectives={"Beschafft 8 Anhänger aus Dalaran für Schattenpriester Allister beim Grabmal."}]])
R(480,"Der Wirker",[[description="Ein Erzmagier von großer Macht leitet die Reaktivierung des Leyenergieknotens. Angesichts ihres Fortschritts liegt unsere einzige Hoffnung, sie noch aufzuhalten, darin, ihn zu töten. Das ist eine schwierige Tat, denn ohne Zweifel wird er von anderen Magiern und Wärtern beschützt.$b$bIhr müsst ihn schnellstens erledigen. Bringt mir seinen Stab, sobald er tot ist. Geht jetzt.",objectives={"Tötet den Erzmagier von Dalaran und bringt seinen Stab zu Schattenpriester Allister in dem Grabmal."}]])
R(481,"Dalars Analyse",[[description="Bringt den Anhänger zu Dalar Dawnweaver, vielleicht kann er Licht in das Dunkel der Hexerpläne bringen.",objectives={"Bringt den mit Runen gravierten Anhänger zu Dalar Dawnweaver in dem Grabmal."}]])
R(482,"Dalaran Absichten",[[description="Natürlich! Wie konnte ich das vergessen?$b$bAmbermill war einer der Orte, die von den Kirin Tor gekennzeichnet wurden, weil dort ein ruhender Leyenergieknoten liegt. Mit Sicherheit haben die Hexer vor, diesen Knoten wiederzuerwecken und seine Energien für etwas Größeres zu nutzen.$b$bDas dürfen wir nicht zulassen...$b$bUm die Leyenergien des Gebietes zu aktivieren, bedarf es einer großen Macht. Wir können sie aufhalten, indem wir die Anhänger der Hexer an uns nehmen.$b$bBringt diese Information zu Allister, er wird dann über das weitere Vorgehen entscheiden.",objectives={"Sprecht mit dem Schattenpriester Allister in dem Grabmal."}]])
R(483,"Die Relikte des Erwachens",[[description="Eindringlinge der Knarzklauen wurden beim Überfall im Westen des Ban'ethil-Grabhügels gesehen.$b$bWenn wir ihnen nicht zur Hilfe kommen, werden die schlummernden Druiden auf ewig im Smaragdgrünen Traum gefangen gehalten, vollkommen ahnungslos ihrem Schicksal ausgeliefert. Das empfindliche Ritual des Großen Schlafes kann ohne die Relikte des Erwachens nicht unterbrochen werden.$b$bReist zum Höhlenbau und bringt den Rabenkrallentalisman, den schwarzen Federkiel, den Saphir des Himmels sowie die Rune des Nistens herbei. Die Druiden bewahren sie in heiligen Truhen auf. Bringt sie zu mir, damit ich das Weck-Ritual vorbereiten kann.",objectives={"Bringt die Relikte des Erwachens zu Athridas Bearmantle nach Dolanaar."}]])
R(484,"Häute junger Krokilisken",[[description="Ich bin James Halloran, der Gerber. Meine gegerbten Krokiliskenhäute sind nah und fern begehrt, Lieferungen gehen per Schiff zu allen Häfen der Welt.$b$bHabt Ihr Einar getroffen? Er ist einer der Jäger, die mir Krokiliskenhäute bringen.$b$bMir fehlen zurzeit weichere Häute, wie die von jungen Krokilisken.$b$bDa ich bald keine mehr habe, bin ich bereit, Euch einen Spitzenpreis für einen Stapel der Häute zu bezahlen. Ihr könnt die jungen Kroks in den Marschen gleich außerhalb der Stadt finden.",objectives={"Besorgt Euch 4 Häute junger Krokilisken für James Halloran im Hafen von Menethil."}]])
R(485,"Sucht OOX-09/HL!",[[description="Ihr habt ein merkwürdiges Gerät aus Metall entdeckt, das die Form eines Eis hat. Als Ihr einen der Knöpfe berührt, erwacht das Ei zu Leben und verwandelt sich in eine Art Gnom-Roboter-Apparat! Aus dem Inneren des Roboteis erklingt eine rasselnde Stimme.$B$B\"Mein Name ist Oglethorpe Obnoticus und mein Leitroboter ist abgestürzt! Ich werde Euch belohnen, wenn Ihr ihn aufspürt. Bringt dem Roboter bitte diesen Signalgeber!\"$B$B\"Ich habe jetzt die Koordinaten des Roboters für Euch berechnet. Er ist in der Nähe von Skulk Rock abgestürzt, dort, wo der Fluss entspringt!\"",objectives={"Bringt das Notsignal zu Oglethorpes Leitroboter an der Quelle des Flusses im Hinterland, nahe Skulk Rock."}]])
R(486,"Ursal der Raufer",[[description="Jetzt ist die Zeit gekommen, die Druiden der Kralle zu retten. $N, sollten wir jetzt versagen, sind sie für immer im Schlaf verloren.$b$bIch werde die Relikte des Erwachens vorbereiten und das Ritual durchführen. Damit meine Arbeit Wirkung zeigen kann, muss die verfluchte Bestie, die für diese schreckliche Situation verantwortlich ist, getötet werden. Erst dann ist das Ritual vollkommen.$b$bEs war Ursal der Raufer, der sich in die Berufung unserer Brüder eingemischt hat, und er ist es auch, der nun bezahlen muss, damit sie befreit werden können. Begebt Euch nach Südwesten zur Höhle der Knarzklauen und erschlagt ihn.",objectives={"Tötet Ursal den Raufer und kehrt zu Athridas Bearmantle nach Dolanaar zurück."}]])
R(487,"Die Straße nach Darnassus",[[description="Die Straße nach Darnassus muss sicher bleiben. Reisende, die von Dolanaar nach Darnassus fuhren, haben von ruchlosen Angriffen der verderbten Furbolgs des Knarzklauenstammes berichtet.$b$bJeden Tag gelangen auf diesem Weg wichtige Nachrichten und auch Waren von und nach Darnassus. Es darf einfach nicht sein, dass eine schurkische Bande von Heiden alle terrorisiert.$b$b$C, bewaffnet Euch im Namen des Heiligen Waldes. Ihr Bau liegt irgendwo unterhalb dieser Position. Erschlagt 6 Wegelagerer der Knarzklauen und berichtet mir dann.",objectives={"Erschlagt 6 Wegelagerer der Knarzklauen und kehrt zu Schildwache Amara Nightwalker außerhalb Dolanaars zurück."}]])
R(488,"Zenns Aufträge",[[description="Ihr seid bereit zu arbeiten, wie ich sehe. Ihr habt Glück, denn es vergeht kein Tag, an dem ich mir nicht wünschte, ein junger $C wäre hier, der mir zur Hand geht.$b$bIhr seht, $N , ich kann Euch zu Eurem Glück verhelfen und mit Dingen versorgen, von denen Ihr nie zu träumen wagtet. Damit dies jedoch geschieht, müsst Ihr mir gewisse Dinge beschaffen.$b$bMeine Angelegenheiten im Wald erfordern oft gewisse... Reagenzien. Bringt mir 3 Nachtsäbler-Fangzähne, 3 Strigideulenfedern und 3 Streifen Waldweberspinnenseide.$b$bDas soll unser kleines Geheimnis bleiben, $R.",objectives={"Bringt Zenn Foulhoof außerhalb von Dolanaar 3 Nachtsäblerfangzähne, 3 Strigideulenfedern und 3 Streifen Waldweberspinnenseide."}]])
R(489,"Sucht Befreiung!",[[description="Der Rat des Waldes hat die Meldung erhalten, dass Ihr Zenn Foulhoof behilflich gewesen seid. Der Satyr ist ein Feind des Waldes. Als $R müsstet Ihr eigentlich mehr Verstand haben, als den Wald zu entweihen, indem Ihr Kreaturen der Natur tötet.$b$bIhr müsst Eure Ehre in den Augen des Rates wiederherstellen, wenn Ihr weiterhin ein Freund von Teldrassil bleiben wollt.$b$bErteilt Foulhoof eine Lektion, dann habt ihr Eure Schuld beglichen. Teufelszapfen sind verderbte Samen, die von Bäumen fallen. Sie sondern grünen Rauch ab.$b$bGebt Foulhoof einige davon. Er wird denken, dass Ihr ihm eine harmlose Leckerei gebracht habt.",objectives={"Sammelt 3 Teufelszapfen und gebt sie Zenn Foulhoof außerhalb von Dolanaar."}]])
R(490,"Bounty: Gnarlpine Furbolg",[[description="By strict orders from the Council of Darnassus, I am commissioning a bounty on the Gnarlpine Tribe. They are no longer friends of the forest. Their corruption has left them mindless threats to our people and the creatures of the glade.$b$bAs decreed by the Council, you shall be rewarded for removing the furbolg menaces from Kalidar. Bring to me their fangs as proof of your deeds.",objectives={"Shayla Nightbreeze outside of Darnassus wants you to bring her 20 Gnarlpine Fangs."}]])
R(491,"Zauberstab an Bethor",[[description="Thule erzählte mir einmal, dass er und zwei Kollegen vor langer Zeit einen magischen Zauberstab herstellten, der aus den Lehrlingszauberstäben zusammengewoben wurde, den jeder Magier besaß. Dieser Zauberstab war ein Symbol ihrer Freundschaft, und obwohl Thule ihn hinterher verachtete, konnte er sich doch weder davon trennen noch ihn den anderen überlassen. Also stahl er den Zauberstab und versteckte ihn in Burg Fenris.$B$BHier. Bringt den Zauberstab zu Bethor Iceshard, einem Freund von Thule aus vergangenen Zeiten. Ich bin sicher, er möchte ihn haben.",objectives={"Bringt den gewebten Zauberstab zu Bethor Iceshard in das Magieviertel von Undercity."}]])
R(492,"Eine neue Seuche",[[description="Berichten der Todeswachen zufolge wurde gerade ein weiterer dieser dummen Zwergen-Gebirgsjäger gefangen genommen. Die Todeswächter benutzen gern den Keller der Taverne Zur Galgenschlinge als Übergangszelle, bis man sich \"richtig\" um die Gefangenen kümmern kann.$b$bWarum... kümmert... Ihr Euch nicht um den gefangenen Gebirgsjäger und schaut, wie er das Spezialgetränk verträgt, das ich für ihn gemacht habe? Das ist nur ein kleiner Eindruck dessen, was die dunkle Fürstin für den Rest von Azeroth geplant hat.",objectives={"Bringt Johaans Spezialgetränk zum gefangenen Gebirgsjäger."}]])
R(493,"Reise in das Vorgebirge von Hillsbrad",[[description="Die Königliche Apothekervereinigung steht unter enormem Druck seitens der dunklen Fürstin, eine neue Seuche zu entwickeln. Wir arbeiten sehr hart und haben bereits einige Fortschritte gemacht. Wir denken, dass der Erfolg sich umso schneller einstellen wird, wenn wir innerhalb der Vereinigung Informationen austauschen.$b$bAus diesem Grunde möchte ich, dass Ihr meine letzten Funde an Apotheker Lydon in Tarrens Mühle überbringt, einem kleinen Städtchen, das sich im Vorgebirge von Hillsbrad befindet. Die Reise wird sehr lange dauern.$b$bBegebt Euch Richtung Süden und bleibt auf den Straßen. Beachtet die Schilder auf das Genaueste!",objectives={"Bringt die Funde von Apotheker Renferrel zu Apotheker Lydon nach Tarrens Mühle im Vorgebirge von Hillsbrad."}]])
R(494,"Zeit zum Zuschlagen",[[description="Schweigt und passt auf, $C.$b$bIch wurde an diesen Ort geschickt, um die Stadt Hillsbrad zu sondieren. Es handelt sich um eine Aufklärungsmission. Dabei ist von äußerster Wichtigkeit, dass Ihr sofort die Hochexekutorin Darthalia in Tarrens Mühle benachrichtigt. Bestellt ihr, ich, Todespirscherin Lesh, lasse ihr folgende Nachricht ausrichten:$b$b\"Der Schrei des Raben locket vom Westen her.\"$b$bFolgt der Straße gen Osten und beachtet die Schilder genau. Nun aber schnell! Macht Euch auf den Weg nach Tarrens Mühle. Es ist Eile geboten!",objectives={"Reist nach Tarrens Mühle, um die Nachricht von Todespirscherin Lesh an Hochexekutorin Darthalia zu überbringen."}]])
R(495,"Die Krone des Willens",[[description="Mug'Thol und seine Ogerkriegsmeute wurde nach Alterac geschickt, um die Krone des Willens für Lady Sylvanas zu holen. Anstatt sie zurückzubringen, hat der Idiot allerdings versucht, sie aufzusetzen... Oger können wohl einfach keinen Dingen widerstehen, die glitzern und schimmern, nehme ich an.$b$bSeine stümperhaften Aktionen sind allerdings zu einem Problem geworden. Die Krone des Willens hat ihm geholfen, der Besessenheit zu widerstehen, die ihm auferlegt wurde, damit er Lady Sylvanas dient.$b$bDie dunkle Fürstin möchte ein Exempel statuieren. Begebt Euch nach Tarrens Mühle in Hillsbrad und meldet Euch bei Melisara, meinem dortigen Offizier.",objectives={"Meldet Euch bei Melisara in Tarrens Mühle im Vorgebirge von Hillsbrad."}]])
R(496,"Elixier des Leidens",[[description="Ah, und wieder ein ekelhafter Tag in Tarrens Mühle. Diese ganze gesunde Luft verdirbt mir gründlich die Laune, $n.$b$bJe schneller wir die Menschen hier erkranken lassen können, desto besser. Ich habe intensive Studien über mögliche tödliche Zutaten für meine Gebräue durchgeführt, aber ich habe nicht die Zeit, sie alle zu sammeln.$b$bWenn Ihr Euch nützlich machen wollt, dann besorgt mir Folgendes: 10 Graubärzungen sowie das sehr seltene und schwer zu findende Krabblersekret. Bären und Krabbler könnt Ihr gleich außerhalb von Tarrens Mühle finden.",objectives={"Apotheker Lydon aus Tarrens Mühle möchte 10 Graubärzungen und etwas Krabblersekret."}]])
R(497,"<UNUSED>",[[description="As a child, raised as a gladiator at Durnholde Keep, I was befriended by Taretha, the daughter of my wet nurse and mistress of the damned bastard Blackmoore.$b$bThe past is the past, $n, but reports of human movements in Hillsbrad reminded me of that time. I dispatched a small party to the area to investigate and to retrieve an... item... given to me by Taretha, if they could.$b$bA fruitless task, no doubt, but perhaps...$b$bThey should have returned by now, I want you to go to Tarren Mill to investigate.",objectives={"Go to Tarren Mill and find out the status of the party sent by Thrall."}]])
R(498,"Die Rettung",[[description="Ich und einige andere Krieger wurden vom Kriegshäuptling geschickt, um ein Objekt aus Durnholde zu holen und dieses so genannte Syndikat zu untersuchen.$b$bAls wir nach Durnholde kamen, um uns umzusehen, wurden wir von einer großen Anzahl der Menschen überrascht. Wir haben mutig gekämpft, aber allein ihre Anzahl war so überwältigend groß, um uns zu besiegen. Sie haben einige von uns als Gefangene genommen, aber ich konnte entkommen.$b$bDurnholde befindet sich nicht weit südöstlich von uns, nur über den Fluss. Drull und Tog'thar werden dort gefangen gehalten, Ihr müsst sie retten.",objectives={"Krusk in Tarrens Mühle braucht Euch, um Drull und Tog'thar aus der Burg Durnholde zu befreien."}]])
R(499,"Elixier des Leidens",[[description="Es wird einen Moment dauern, diese Komponenten zu vermengen, damit ein, wie ich es nenne, Elixier des Leidens entsteht.$b$bDann mal los! Ah, es gibt doch nichts Schöneres in diesem elendiglichen Vorgebirge, als ein wenig Leiden in die Welt zu bringen.$b$bLasst uns mal überprüfen, ob unser kleiner Trank auch seine gewünschte Wirkung hat.$b$bGebt meiner Assistentin Umpi einen kleinen Schluck von dem, was die Dunkle Fürstin sowohl für Menschen als auch für die Geißel geplant hat.",objectives={"Gebt Umpi das Elixier des Leidens"}]])
R(500,"Crushridge-Kopfgeld",[[description="Die Crushridge-Oger haben einen Ogerhort im Alteracgebirge nahe der verfallenen Stadt Alterac gebaut. Meine Späher berichteten mir, dass sie auch die Ruinen da erobert haben.$B$BWir dürfen aber nicht zulassen, dass sie sich da fest einnisten. Falls sie sich dort zu sicher fühlen, werden sie bestimmt ins Vorgebirge eindringen und wären dann praktisch vor unserer Haustür!$B$BBegebt Euch nach Norden in das Alteracgebirge auf Ogerjagd. Bringt mir die schmutzigen Knöchelknochen, die sie tragen, und Ihr habt Euch ein hübsches Kopfgeld verdient.",objectives={"Sammelt 9 schmutzige Knöchelknochen von Crushridge-Ogern im Alteracgebirge. Bringt sie zu Marshal Redpath in Southshore."}]])
R(501,"Elixier der Schmerzen",[[description="Oh, $N..., in Hillsbrad blühen die Blumen und die Luft ist so klar und rein. Ich muss in diesem ganzen Elend baden. Ich sehe aus meinem verdreckten Fenster und sehne den Tag herbei, an dem unsere neue Seuche dieser Welt ihren wohlverdienten Tod bringt.$b$bSo gern ich auch den ganzen Tag hier herumsitzen und mit Grübeln verbringen würde, meine Pflicht gegenüber der dunklen Fürstin ruft mich. Würdet Ihr mir helfen? Meine Forschungen führen mich zu der Annahme, dass sich aus Berglöwenblut ein vorzüglicher Todestrank herstellen lässt. Bringt mir etwas davon, dann können wir ein bisschen Spaß haben.",objectives={"Bringt 10 Phiolen mit Berglöwenblut zu Apotheker Lydon in Tarrens Mühle."}]])
R(502,"Elixier der Schmerzen",[[description="Ah, es geht doch nichts über den Geruch von frischem Blut im Vorgebirge!$b$bDann lasst uns eine Prise davon und ein wenig hiervon vermischen - und der einzig wahre Spaß kann beginnen! Die Kreation aus diesem Blut möchte ich Elixier der Schmerzen nennen. Wenn meine Berechnungen korrekt sind, sollte dieses Gebräu der Anfang von etwas Wunderbarem für Lady Sylvanas sein. Aber wir müssen erst mal einen Testlauf machen.$b$bBringt dieses Elixier zum nördlichen Hof in den Feldern von Hillsbrad im Südwesten. Lasst uns sehen, wie Stanley, dem kleinen Hund von Bauer Ray, dieses 'Leckerli' so schmeckt.",objectives={"Füttert Stanley mit dem Elixier der Schmerzen."}]])
R(503,"Gol'dir",[[description="Soweit ich das aus den Dokumenten, die Ihr herbrachtet, ersehen kann, wird Gol'dir in einem großen Syndikatsstützpunkt im Norden festgehalten, höchstwahrscheinlich im Alteracgebirge. Er ist schon zu lange dort gefangen und muss endlich befreit werden.",objectives={"Befreit Gol'dir und kehrt dann zu Krusk in Tarrens Mühle zurück."}]])
R(504,"Crushridge-Kriegstreiber",[[description="Nun, da Ihr die Bekanntschaft der Crushbridge-Oger gemacht habt, möchte ich, dass Ihr ihnen so richtig zeigt, was eine Harke ist...$B$BGeht zu den Ruinen von Alterac und sucht die Crushridge-Kriegstreiber. Ihr sollt eine große Anzahl von ihnen erschlagen - das ist der einzige Weg, um diese Schläger von dem Gebiet der Allianz fern zu halten.",objectives={"Erschlagt 15 Crushridge-Kriegstreiber und kehrt dann zu Marshal Redpath in Southshore zurück."}]])
R(505,"Auftragsmörder des Syndikats",[[description="Ich bin der neue Magistrat von Southshore. Ich wurde erst kürzlich ernannt, nachdem der vorherige Magistrat ermordet worden ist. Die Mörder wurden nie gefunden, aber unsere Nachforschungen haben ergeben, dass sie höchstwahrscheinlich vom Syndikat angeworben wurden - einer Gruppe von Dieben, angeführt von schurkischen Edlen des jetzt gefallenen Königsreichs von Alterac.$B$BDas Syndikat hat ein Lager nördlich von Tarrens Mühle, das von der Horde besetzt ist, und unsere neuesten Hinweise führen genau in dieses Lager. Erschlagt die Syndikatsmitglieder, die Ihr dort vorfindet.",objectives={"Tötet 12 Schleicher des Syndikats und 8 Diebe des Syndikats, kehrt dann zurück zu Magistrat Henry Maleb nach Southshore."}]])
R(506,"Blackmoores Vermächtnis",[[description="Vor ein oder zwei Tagen erhielt ich Besuch vom Anführer dieses Syndikats. Sein Name war Aliden Perenolde und er nannte sich selbst Lord dieses Landes. Er vertraute mir seine Pläne an, die Orcs, die sich gegen ihn gewandt hatten, zu Sklaven zu machen, genau wie es einst auch sein Vater und Mentor, der geächtete Blackmoore, geplant hatte.$b$bAber viel wichtiger war, dass er seine Geliebte mitbrachte, ein zartes Mädchen namens Elysa. Um ihren Hals trug sie den Anhänger, den der Kriegshäuptling als sein Eigen wünscht.$b$bGeht jetzt, ich gehe meine eigenen Wege, nachdem ich meine Geschäfte hier erledigt habe.",objectives={"Bringt die von Gol'dir gesammelten Informationen zu Krusk in Tarrens Mühle."}]])
R(507,"Lord Aliden Perenolde",[[description="Es ist unumstritten, dass Perenolde getötet werden und seine Verderbtheit ausgelöscht werden muss. Sein Herrenhaus liegt weit nördlich von hier, an den Ufern des Lordameresees. $n, tut Eure Pflicht, holt danach den Anhänger, den der Kriegshäuptling zu haben wünscht, und kehrt dann hierher zurück.",objectives={"Tötet Lord Aliden Perenolde und befragt seine Geliebte Elysa nach Tarethas Anhänger."}]])
R(508,"Tarethas Geschenk",[[description="Den Anhänger? Aber natürlich könnt Ihr ihn haben... Nehmt ihn! Nichts soll mich an ihn erinnern... nur bitte geht, bitte geht in Frieden...",objectives={"Bringt Tarethas Anhänger zu Krusk nach Tarrens Mühle."}]])
R(509,"Elixier der Pein",[[description="Ein neuer Tag, ein neues Elixier. Wenn ich was zu sagen hätte, würde ich diese lächerlichen Menschen und die Geißel die Sache einfach unter sich ausmachen lassen. Sie scheinen ohnehin absolut darauf versessen zu sein, sich gegenseitig umzubringen.$b$bAber leider hat es sich unsere dunkle Fürstin in den Kopf gesetzt, das Ganze ein wenig zu beschleunigen. Also warum diese düsteren Tage nicht dazu nutzen und hier ein wenig Tod und Krankheit verbreiten?$b$b$N, das ist mein Plan: Ihr macht Euch auf den Weg zur Nethander-Siedlung. Das ist südlich von Tarrens Mühle und östlich des Flusses und Southshore. Sammelt in den Feldern dort 6 Morastschnauzenkappen für mein nächstes Elixier.",objectives={"Bringt 6 Morastschnauzenkappen zu Apotheker Lydon in Tarrens Mühle."}]])
R(510,"Furchteinflößende Pläne",[[description="Unter diesen Dokumenten befindet sich eine Liste der benötigten Vorräte. Das sind unter anderem ganz banale Dinge (Nahrung, Waffen, Kleidung) wie auch etwas exotischere Ausrüstungsgegenstände (Masken, Öl, Gift).$B$BAber am auffälligsten ist die Dringlichkeit dieses Auftrags - diese Vorräte werden schnellstens benötigt, um eine Unternehmung zu starten, die in dem Dokument als 'wichtige Mission gegen Southshore' beschrieben wird.",objectives={"Bringt die furchteinflößenden Pläne zu Magistrat Henry Maleb nach Southshore."}]])
R(511,"Verschlüsselter Brief",[[description="Einer der Briefe auf diesem Tisch ist verschlüsselt und nicht zu ergründen.",objectives={"Bringt den verschlüsselten Brief zum Meister der Lehren Dibbs nach Southshore."}]])
R(512,"Tod der Edlen",[[description="Ich fürchte, die Führung, die hinter dem Syndikat steht, will Southshore unbedingt ruinieren. Wir müssen diese Anführer mit aller Kraft schlagen, bevor sie ihre Pläne in die Tat umsetzen können.$B$BGeht zu den Ruinen von Strahnbrad, im Alteracgebirge im Norden. Wir glauben, dass das Syndikat dieses Gebiet als Hauptquartier benutzt.$B$BWir wissen, dass diese Bande von Halsabschneidern von ehemaligen Adligen von Alterac angeführt wird. Sie mögen sich als normale Agenten des Syndikats verkleiden, aber wenn Ihr sie tötet, werdet Ihr einen Edlen an dem Siegelring erkennen, den er trägt.$B$BBringt mir diese Siegelringe.",objectives={"Bringt 7 Alteracsiegelringe zu Magistrat Henry Maleb nach Southshore."}]])
R(513,"Elixier der Pein",[[description="Gerade dachte ich noch, ein weiterer Tag ohne jegliches Amüsement, und da kommt Ihr und bringt diese wunderbaren Morastschnauzenkappen.$b$bZuerst werde ich sie zu einem feinen Gemisch zusammenrühren. Dann werden wir Meisterapotheker Faranell in Undercity benötigen, damit er seine Paste des Verfalls hinzufügt, und dann geht der Spaß erst richtig los!$b$bHier, $N, nehmt dieses Morastschnauzengemisch und bringt es schnell zu Meister Faranell.",objectives={"Bringt das Morastschnauzengemisch zu Meisterapotheker Faranell in Undercity."}]])
R(514,"Brief an Stormpike",[[description="Ich habe einen Kollegen in Ironforge, der bei der Entschlüsselung dieses Briefes behilflich sein kann. Begebt Euch zur Bibliothek in der Halle der Forscher in Ironforge und sprecht mit Ausgrabungsleiter Stormpike. Richtet ihm aus, dass ich Euch geschickt habe, und zeigt ihm diesen Brief. Wenn es jemanden nördlich der Blackrockspitze gibt, der das hier lesen kann, dann ist er das.",objectives={"Bringt den geschickt verschlüsselten Brief zu Ausgrabungsleiter Stormpike nach Ironforge."}]])
R(515,"Elixier der Pein",[[description="Ein Morastschnauzengemisch? Das ist wirklich brillant! Warum ist mir das nicht eingefallen?$b$bLasst mich meine Paste des Verfalls diesem Teufelsgebräu hinzufügen.$b$bDamit die verunreinigenden Agenzien in dieser Morastschnauzenmixtur aktiviert werden, benötigt Lydon starken Trollbluttrank, sowie einige Säbelflossenschuppen und Fetzenflossenaugen von der Südküste Hillsbrads. Er wird wissen, was zu tun ist, sobald Ihr alle Reagenzien zusammengetragen habt. Ich kann es kaum abwarten zu erfahren, wie sein Experiment ablaufen wird!",objectives={"Bringt die Morastschnauzenmixtur, einen starken Trollbluttrank, 5 Säbelflossenschuppen und 5 Fetzenflossenaugen zu Apotheker Lydon nach Tarrens Mühle."}]])
R(516,"Beren's Peril",[[description="Ich habe Berichte erhalten, dass eine Gruppe Untoter sich zusammenrottet, um einen Angriff gegen uns vorzubereiten. Mit diesen Informationen können wir den Spieß umdrehen und sie zuerst angreifen, damit wäre ihr Plan erledigt.$b$bLeider sind meine Informationen gelinde gesagt unvollständig. Laut Bericht verstecken sie sich an einem Ort, der als Beren's Peril bekannt ist. Ihr genauer Standort ist unbekannt, aber es scheint eine Höhle in den Hügeln zu sein, nahe einem Nest der Hexer von Dalaran.$b$bIch vertraue auf Euren Einfallsreichtum. Findet sie und macht alles dem Erdboden gleich.",objectives={"Findet zuerst Beren's Peril, tötet 6 Zwangsarbeiter von Rabenklaue sowie 6 Wächter von Rabenklaue und kehrt dann zu Schattenpriester Allister in das Grabmal zurück."}]])
R(517,"Elixier der Pein",[[description="Das neue Elixier ist endlich bereit für einen Test. Aber warum solch eine vollkommene, höchst ansteckende Seuche an einen einfachen Frosch oder Hund verschwenden? Wir sollten uns in Lady Sylvanas Namen eine kleine Freude erlauben.$b$bGeht nach Dun Garok. Ihr kennt doch die Kasernen, in denen diese widerlichen kleinen Zwerge umhersausen. Ihr stehlt ein Fässchen Shindigger-Starkbier für mich. Sobald ich dieses Fässchen habe, können wir beide, Ihr und ich, eine kleine Party feiern, $N.",objectives={"Bringt ein Fässchen mit Shindigger-Starkbier zu Apotheker Lydon nach Tarrens Mühle."}]])
R(518,"Die Krone des Willens",[[description="Mug'Thol und seine Crushridge-Oger haben die Ruinen von Alterac überrannt. Ihm eine schwere Strafe zukommen zu lassen, ohne die Anzahl der Oger zu verringern, wird nicht einfach sein.$b$bWir machen sie erst weich und sehen dann weiter.$b$bVerstanden? Gut. Dann geht.",objectives={"Tötet 14 Crushridge-Raufer für Melisara in Tarrens Mühle."}]])
R(519,"Die Krone des Willens",[[description="Targ, Muckrake und Glommus sind Mug’Thols Offiziere. Sie sind ihm loyal ergeben, aber wer weiß schon, was einen Oger loyal sein lässt.$b$bBringt mir ihre Köpfe, $n, und dann muss nur noch Mug'Thols Kopf, mitsamt Krone, rollen.",objectives={"Tötet Targ, Muckrake und Glommus und bringt ihre Köpfe zu Melisara nach Tarrens Mühle."}]])
R(520,"Die Krone des Willens",[[description="Nun, da Mug'Thols Offiziere tot sind, muss nur noch Mug'Thol selbst getötet und die Krone des Willens wieder zurückgebracht werden. Ich bin mir ziemlich sicher, dass er sie nur äußerst unwillig wieder hergeben wird. Außerdem wird er Euch wahrscheinlich bereits erwarten, in Anbetracht des... Ablebens... seiner Kumpanen.$b$bFindet Mug'Thol und bringt mir seinen Kopf und die Krone. Der Crushridge-Widerstand wird damit beendet sein.",objectives={"Tötet Mug'Thol und bringt seinen Kopf mit der Krone des Willens zu Melisara nach Tarrens Mühle."}]])
R(521,"Die Krone des Willens",[[description="Es bleibt nur noch, die Krone des Willens zu Sharlindra nach Undercity zu bringen. Sie wird dafür sorgen, dass sie an Lady Sylvanas weitergeleitet wird. Ich warne Euch, auch nur daran zu denken, sie für Eure eigenen Zwecke zu verwenden, $N, Mug'Thols Schicksal sollte Beispiel genug sein.",objectives={"Bringt die Krone des Willens zu Sharlindra in Undercity."}]])
R(522,"Auftragsmördervertrag",[[description="Dies ist ein Vertrag für die Ermordung des Magistrats Henry Maleb. Er wurde mit einem unverwechselbaren Siegelring in rotem Wachs gestempelt und versiegelt.",objectives={"Bringt den Auftragsmörder-Vertrag zu Magistrat Maleb nach Southshore."}]])
R(523,"Ableben des Barons",[[description="Der Vertrag, den Ihr gebracht habt, wurde von Baron Vardus unterschrieben, einem Edlen aus dem ehemaligen Königreich von Alterac, und jemand der bekannt ist für seine Kaltherzigkeit und brutale Vorgehensweisen. Es überrascht mich nicht, dass jemand wie der Baron dahinter steckt.$B$BFindet diesen Mann. Findet ihn und führt ihn seiner gerechten Strafe zu. Er befindet sich sicherlich irgendwo in den Schlupfwinkeln des Syndikats - vielleicht in den Ruinen von Strahnbrad oder irgendwo in dem Tal im Norden davon.",objectives={"Bringt den Kopf von Baron Vardus zu Magistrat Maleb nach Southshore."}]])
R(524,"Elixier der Pein",[[description="Nebenan halten die Todeswachen einige Bauern als Geiseln gefangen. Hochexekutorin Darthalia hatte vermutet, dass sich einer der Militärstrategen aus Stormwind unter ihnen versteckte. Anscheinend wurde dieser Militärstratege gestern Nacht tot in den Pestländern gefunden. Darthalia denkt ja immer so nett an mich und hat entschieden, dass die Gefangenen mir zu überlassen sind.$b$bIch denke, es ist höchste Zeit, dass wir für diese Bauern eine kleine Party schmeißen. Hört sich doch nach einer tollen Zeit an!$b$bStellt dieses besudelte Fässchen auf den Teppich in ihrem Zimmer. Seuchenbräu für alle!",objectives={"Stellt das besudelte Fässchen auf den Teppich für die gefangenen Bauern."}]])
R(525,"Weitere Geheimnisse",[[description="Ich habe den Brief dechiffriert, aber ich weiß nicht, was ich davon halten soll. Ihr habt ihn unter Dieben im Vorgebirge von Alterac gefunden? Sehr seltsam...$B$BIhr solltet ihn zum Magistrat nach Southshore bringen. Auch wenn dieser Brief geheimnisvoll klingt, seine Stadt liegt Alterac am nächsten, wenn eine Bedrohung sich zusammenbraut, dann sollte gerade er davon erfahren.",objectives={"Bringt den entschlüsselten Brief zu Magistrat Maleb nach Southshore."}]])
R(526,"Lichtschmiedeblöcke",[[description="Ihr mögt zwar einen Lichtschmiedeblock in dieser Truhe gefunden haben, aber das reicht nicht aus, um irgendetwas von Nutzen daraus zu schmieden.$B$BIhr solltet zurückgehen und nach weiteren suchen. Vielleicht tragen die Murlocs in der Nähe des Schiffswracks Lichtschmiedeblöcke mit sich herum.",objectives={"Sammelt 5 Lichtschmiedeblöcke und kehrt dann zu Glorin Steelbrow im Sumpfland zurück."}]])
R(527,"Kampf um Hillsbrad",[[description="Steht gefälligst stramm, wenn Ihr mit mir sprecht, $C.$b$bIch stehe unter direktem Kommando von Varimathras. Wir sollen der menschlichen Plage Einhalt gebieten, bis unsere Apotheker eine neue Pest entwickeln können.$b$bUnseren Informationen zufolge bietet Hillsbrad einen guten Angriffspunkt. Eure erste Aufgabe ist darauf gerichtet, die Nahrungsversorgung und Infrastruktur zu unterbrechen.$b$bBegebt Euch nach Westen. Überfallt die nördlichsten Höfe der Felder von Hillsbrad. Und stellt sicher, dass die Landeigner, Bauer Ray und Bauer Getz, ebenfalls exekutiert werden.",objectives={"Tötet 6 Landarbeiter von Hillsbrad, 6 Bauern von Hillsbrad, Bauer Ray und Bauer Getz und meldet Euch dann wieder bei Darthalia in Tarrens Mühle."}]])
R(528,"Kampf um Hillsbrad",[[description="Die Berichte vom Angriff auf die nördlichen Höfe haben die Stadtbevölkerung in Panik versetzt. Vorzüglich.$b$bUnsere Todespirscher melden, dass Arbeiter in die Felder ins südliche Hillsbrad flüchten. Diese Narren glauben doch tatsächlich, dass sie sich in den Obsthainen verstecken und so ihrer Verdammnis entkommen können.$b$bBeweist ihnen das Gegenteil, $N. Kehrt zu den Feldern von Hillsbrad zurück und macht die feigen Arbeiter ausfindig. Vernichtet sie im Namen der dunklen Fürstin.$b$bWeggetreten!",objectives={"Tötet 15 Arbeiter von Hillsbrad und erstattet Bericht bei Darthalia in Tarrens Mühle."}]])
R(529,"Kampf um Hillsbrad",[[description="Die Menschen in Hillsbrad leisten unerwarteten Widerstand. Das Problem scheint darin zu bestehen, dass die Bewohner durch den örtlichen Schmied mit Waffen versorgt werden. Wir müssen alle Versorgungsmöglichkeiten abschneiden.$b$bEure Aufgabe ist es, Schmied Verringtan zu eliminieren. Tötet auch gleich seine Lehrlinge. Wenn Ihr schon dort seid, bringt auch gleich eine Eisenlieferung aus ihrem Vorratslager mit zurück. Nach der Eroberung von Hillsbrad werden diese Vorräte uns gelegen kommen, wenn wir mit der Verwüstung von Southshore beginnen.",objectives={"Tötet Schmied Verringtan und 4 Schmiedelehrlinge von Hillsbrad.$b$bBesorgt eine Eisenlieferung und erstattet Bericht bei Darthalia in Tarrens Mühle."}]])
R(530,"Rache eines Ehemanns",[[description="Valdred, einst ein guter Freund von mir, ist der Mörder meiner Frau. Auch wenn ich keine Trauer empfinden kann, so sehne ich mich doch nach Rache. Wenn Ihr Valdred tötet und mir seine verfluchten Hände bringt, werde ich Euch belohnen.$B$BDas Letzte, was ich hörte, war, dass er sich im südlichen Silberwald beim Greymane-Wall aufhält und in das Königreich von Gilneas flüchten will.",objectives={"Tötet Valdred Moray.$B$BBringt seine Hände zu Raleigh Andrean nach Undercity."}]])
R(531,"Vyrins Rache",[[description="Licht! Bringt solche Dinge nicht in die Lodge... das ist unhygienisch, unaussprechlich, un... un... unhygienisch!$b$bBringt es bitte einfach nur raus hier, ja? Niemand will Eure kleine blutige Trophäe sehen, nu wirklich nicht!",objectives={"Bringt Old Sootys Kopf zu Vyrin Swiftwind in die Weitschreiter-Lodge."}]])
R(532,"Kampf um Hillsbrad",[[description="Hillsbrad ist ein einziges Chaos und wir sind der Meinung, dass die Stadt bald fallen wird. Nichtsdestotrotz müssen wir weiterhin an unserer Ruchlosigkeit festhalten bis der menschliche Abschaum ein für alle Mal von diesem Vorgebirge verschwunden ist.$b$bTrotz ihrer überwältigenden Verluste sammeln die Menschen sich weiterhin um ihre Führungskraft und kämpfen weiter. Wir müssen ihren Anführer, Magistrat Burnside eliminieren und mit ihm den ganzen Stadtrat. Zerstört ihr heißgeliebtes politisches Dokument, die Proklamation von Hillsbrad, gleich mit. Und wenn Ihr schon dabei seid, stehlt das Stadtregister.",objectives={"Tötet Magistrat Burnside und 5 Ratsherren von Hillsbrad. Zerstört die Proklamation von Hillsbrad. Stehlt das Stadtregister von Hillsbrad. Meldet Euch danach bei Darthalia in Tarrens Mühle."}]])
R(533,"Unterwanderung",[[description="Endlich haben wir eine Spur und können nach Hinweisen auf Gol'dirs Aufenthaltsort suchen. Die Menschen haben ihn immer wieder umquartiert, aber wir konnten unsere Suche einengen und konzentrieren uns jetzt auf das große Syndikatlager nördlich von hier.$b$bBegebt Euch dorthin, $n, und beschafft alle Informationen, an die Ihr herankommen könnt.",objectives={"Holt Informationen über Gol'dirs Aufenthaltsort für Krusk in Tarrens Mühle ein."}]])
R(534,"<UNUSED>")
R(535,"Valik",[[description="Arrrgh... Verletzt, sterbend und den Feind direkt vor Augen...$b$bDa Ihr mich ja sowieso töten werdet, könntet Ihr mir da vielleicht zuvor ein Southshore-Starkbier bringen - Euresgleichen trinkt doch auch, oder? - und ich werde Euch sagen, was Ihr wissen wollt.",objectives={"Bringt einen Becher mit Southshore-Starkbier zu Valik in das Lager des Syndikats."}]])
R(536,"Die Küste entlang",[[description="Von der Stadtwache von Stormwind nach Southshore versetzt, eine Stadt, die man gleich wieder verlassen sollte... wie's aussieht. Der Gestank vom Hafen Tag und Nacht.$b$bGanz zu schweigen vom alten Redpath... Will, dass ich mich um die Murlocs kümmere. Ha! $b$bKann mich kaum aufraffen, die Unterschlüpfe dieser übergroßen Fische unten am Weststrand aufzusuchen. Wenn Ihr für mich gehen und Euch um sie kümmern würdet, wäre ich Euch sehr dankbar.",objectives={"Tötet 10 Gezeitenjäger der Fetzenflossen und 10 Orakel der Fetzenflossen für Lieutenant Farren Orinelle in Southshore."}]])
R(537,"Der Dunkle Rat",[[description="Der Brief, den Ihr mir gebracht habt, wurde von einem Wesen geschrieben, das sich selbst Nagaz nennt, ein Mitglied der Arguswacht. Ich weiß nicht, was diese Arguswacht ist, aber wenn sie mit dem Syndikat zusammenarbeiten, dann sind sie eine Bedrohung.$B$BIch möchte, dass Ihr Nagaz und die Schattenmagier der Arguswacht, die in diesem Brief erwähnt werden, findet. Ihr sollt sie finden und dann töten.$B$BSucht im Oberland, wo das Syndikat am stärksten ist. Es liegt nördlich von Strahnbrad.$B$BMit etwas Glück könnt Ihr die Abgesandten der Arguswacht dort finden.",objectives={"Tötet 4 Schattenmagier der Arguswacht.$B$BBringt den Kopf von Nagaz zu Magistrat Maleb nach Southshore."}]])
R(538,"Southshore",[[description="$N. Wenn Ihr einer langen Reise nicht abgeneigt seid, dann habe ich eine neue Aufgabe für Euch, Stormwind erneut bei der Bestückung seiner Bibliothek behilflich zu sein.$B$BDas alte Königreich von Alterac ist nach dem großen Krieg gefallen und es besaß eine umfangreiche Büchersammlung. Es ist eine große Tragödie, dass die Stadt verfallen ist, aber es ist weitaus tragischer, dass all ihr Wissen verloren geht! Wir müssen retten, was zu retten ist.$B$BSouthshore liegt den Ruinen von Alterac am nächsten. Begebt Euch dorthin und sprecht mit dem Meister der Lehren Dibbs. Er kann Euch den Weg zu den Ruinen erklären und welche Bücher dort zu finden sind.",objectives={"Sprecht mit dem Meister der Lehren Dibbs in Southshore."}]])
R(539,"Kampf um Hillsbrad",[[description="Das Stadtregister von Hillsbrad deutet an, dass der Azurschacht unter der Kontrolle der Allianz steht. Außerdem ist die Mine eine erstklassige Quelle für Eisenerz für die Waffenkammern der Allianz.$b$bAuch wenn wir der Stadt von Hillsbrad einen entscheidenden Schlag versetzen konnten, unterstützt und beschützt die Allianz den Azurschacht immer noch aufs Äußerste.$b$bDie Mine liegt genau im Süden von Hillsbrad. Begebt Euch dorthin und tötet den Großknecht, einen Menschen namens Bonds. Tötet auch gleich seine Minenarbeiter. Das sollte der Allianz ein deutliches Zeichen setzen.",objectives={"Tötet Großknecht Bonds sowie 10 Minenarbeiter von Hillsbrad und erstattet Bericht bei Darthalia in Tarrens Mühle."}]])
R(540,"Wissen bewahren",[[description="Diese barbarischen Oger haben sich in den Ruinen von Alterac ausgebreitet und es schüttelt mich bei dem Gedanken, was sie mit den wertvollen Büchern dort anstellen könnten. Ihr müsst retten, was immer Ihr könnt!$B$BGeht zu den Ruinen von Alterac und sucht dort nach Folianten, die die Oger gestohlen haben. Nehmt, was immer Ihr finden könnt, und bringt alles zu mir, aber sucht insbesondere ein ganz bestimmtes Buch: Der Arm von Gri'lek. Es enthält alte Trolllehren, die ich erlernen muss. Die Ruinen von Alterac waren der letzte bekannte Ort, an dem es ein intaktes Exemplar dieses Buches geben soll.",objectives={"Bringt 5 geborgene Folianten und das abgenutzte Lederbuch, das 'Der Arm von Gri'lek' enthält, zum Meister der Lehren Dibbs nach Southshore."}]])
R(541,"Kampf um Hillsbrad",[[description="Zwerge helfen Menschen? Diese verdammten, dreckigen kleinen Bestien.$b$bWir werden die Stärke dieser so genannten Allianz testen. Wir werden ja sehen, wie sehr diese kleinen Wadenbeißer den Menschen noch helfen wollen, nachdem sie unseren Zorn zu spüren bekommen haben. Wir wissen ganz genau, wo sie in diesem Gebiet ihre Hochburg haben.$b$bSie haben eine Kaserne namens Dun Garok im südöstlichen Hillsbrad entlang des Thoradin-Walls errichtet. Die letzte Order in diesem Kampf ist die Belagerung von Dun Garok, $C. Captain Eisenberg, ihr Anführer muss sterben.",objectives={"Begebt Euch nach Dun Garok, tötet 10 Gebirgsjäger, 8 Scharfschützen, 4 Priester sowie Captain Eisenberg und erstattet danach Bericht bei Darthalia in Tarrens Mühle."}]])
R(542,"Rückkehr zu Milton",[[description="Ich werde einige Zeit benötigen, um das Buch Der Arm von Gri'lek zu studieren, das Ihr mir gebracht habt. Ich bin sicher, Milton kann es kaum erwarten, die anderen geborgenen Bücher in die Sammlung von Stormwind zu integrieren.$B$BHier sind die Bücher, die Ihr aus den Ruinen von Alterac mitgebracht habt, verpackt und katalogisiert. Bringt sie zu Milton Sheaf in Stormwind und ich versichere Euch, dass er sehr dankbar sein wird.",objectives={"Bringt die Folianten von Alterac zu Milton Sheaf nach Stormwind."}]])
R(543,"Die Perenolde-Tiara",[[description="Die Perenolde-Tiara ist ein altes Erbstück der \"Edlen\" von Perenolde - der Herrscherfamilie von Alterac, bevor das Königreich verfiel. Es heißt, dass sie von Meisterjuwelieren in Ironforge hergestellt und mit den schönsten Smaragden besetzt wurde.$B$BAls Alterac zerstört wurde, ging die Tiara verloren, aber Gerüchten zufolge soll ein Ogermagier, Grel'borg der Horter, die Tiara gefunden haben und jetzt in den Ruinen von Alterac auf der Suche nach weiteren Schätzen umherwandern.$B$BWir möchten, dass Ihr die Tiara für uns beschafft.",objectives={"Bringt die Perenolde-Tiara zu Remington Ridgewell nach Stormwind."}]])
R(544,"Gefängnis-Einbruch",[[description="Eigentlich kam ich zu Forschungszwecken nach Tarrens Mühle, aber jetzt muss ich eine Krise verhindern. Wisst Ihr, vier Verlassene sind vor einigen Monaten aus Undercity geflohen. Sie haben ihren Brüdern den Rücken zugekehrt, aber was viel schlimmer ist... sie haben die dunkle Fürstin bestohlen.$B$BDiese Diebe sind in ein gesichertes Gewölbe eingebrochen und haben vier Artefakte gestohlen; Gegenstände, die unsere Apotheker für bestimmte Studien benötigen. Sylvanas will, dass diese Artefakte zurückgebracht werden.$B$BDie Diebe sind aus Undercity nach Dalaran geflohen und diese Hexer haben sie in Quarantäne in das Lordamere-Internierungslager gesteckt.",objectives={"Findet diese Verräter, sammelt ihre Artefakte ein und kehrt dann zu Magus Voidglare nach Tarrens Mühle zurück."}]])
R(545,"Patrouillen von Dalaran",[[description="Die Hexer von Dalaran haben eine riesige, magische Kuppel um ihren Stadtkern errichtet. Einige glauben, dass es zum Schutz gegen die Gewalt unserer Zeit gemacht wurde, andere wiederum sagen, dass sie einfach Ruhe zum Studieren und Pläneschmieden haben wollen.$B$BMir persönlich ist der Grund egal. Aber mir ist nicht egal, dass die verfallenen Vororte der Stadt, die außerhalb der Kuppel liegen, möglicherweise wertvolle magische Schätze beherbergen.$B$BAber dieses Gebiet wird von den Hexern und ihren Elementarsklaven patrouilliert.$B$BAlso jagt sie und kehrt erst zurück, wenn ihre Anzahl einigermaßen reduziert worden ist.",objectives={"Tötet 6 Beschwörer von Dalaran sowie 12 Elementarsklaven und kehrt dann zu Magus Voidglare nach Tarrens Mühle zurück."}]])
R(546,"Andenken des Todes",[[description="Ich habe gehört, Ihr wurdet von Darthalia eingezogen, um Krieg gegen die Menschen von Hillsbrad zu führen. Ich bin ganz grün vor Neid...$b$bIhr habt den ganzen Spaß... Menschen erschlagen, die Stadt plündern, Unschuldige terrorisieren..., und ich stecke hier fest und darf in Tarrens Mühle Wache schieben.$b$bVielleicht habt Ihr ja etwas Mitleid mit einer alten Todeswache wie mir? Wisst Ihr, ich sammle nämlich menschliche Schädel. Und Ihr werdet eine recht lange Zeit gegen Menschen kämpfen. Bringt mir im Verlauf Eures langen Kampfes 30 Schädel, und ich werde Euch für Eure Mühe entlohnen.",objectives={"Todeswache Samsa aus Tarrens Mühle will 30 menschliche Schädel aus Hillsbrad."}]])
R(547,"Humberts Schwert",[[description="Hochexekutorin Darthalia hat mich hergeschickt, um Dun Garok aus der Ferne zu beobachten. Ich hatte mein Lager gerade außer Sichtweite aufgeschlagen. Am Morgen, als ich Wasser kochen wollte, ging ich Feuerholz sammeln.$b$bAls ich ins Lager zurückkam, entdeckte ich, dass meine Ausrüstung verschwunden war.$b$bAnscheinend waren ein paar Zwergenspäher von Dun Garok vorbeigekommen und hatten alles mitgenommen. Ich brauche mein Schwert! Wenn Ihr es für mich zurückholen könntet, wäre ich Euch sehr dankbar. So viele Zwerge hier... es wird ganz schön schwierig sein, den kleinen dreckigen Dieb zu finden, der es gestohlen hat.",objectives={"Bringt das Schwert von Todeswache Humbert aus Dun Garok zu ihm nach Tarrens Mühle zurück."}]])
R(548,"<NYI> <TXT> Bloodstone Pendant",[[description="This will start the Bloodstone Pendant quest line...<NYI>"]])
R(549,"GESUCHT: Syndikatspersonal",[[description="In Lady Sylvanas Namen sollen alle Mitglieder der Organisation, die sich das Syndikat nennt, getötet werden. Diejenigen, die bereits gefangen genommen wurden, werden gemeinschaftlich hingerichtet. Wir wissen, dass sie sich im Moment in den Ruinen der Burg Durnholde im Südosten von Tarrens Mühle sammeln.$b$bFür alle diejenigen, die Beweise ihrer Taten zu Hochexekutorin Darthalia bringen, ist eine reiche Belohnung ausgesetzt.",objectives={"Tötet 10 Schurken des Syndikats und 10 Wachmänner des Syndikats. Kehrt danach zu Hochexekutorin Darthalia nach Tarrens Mühle zurück."}]])
R(550,"Kampf um Hillsbrad",[[description="Da Ihr mit solcher Verbissenheit und Ehre in der Schlacht von Hillsbrad gekämpft habt, habe ich für Euch diese Belobigung geschrieben, in der Eure Heldentaten im Kampf angemessen gerühmt werden, sodass das Oberkommando sie anerkennt.$b$bBringt die versiegelte Belobigung zu Varimathras nach Undercity. Geht erhobenen Hauptes, $C.",objectives={"Bringt Darthalias versiegelte Belobigung zu Varimathras nach Undercity."}]])
R(551,"Das Verhexte Pergament",[[description="Dieses Pergament ist mit einer Verzauberung versehen, die es unlesbar macht. Nur ein Wort oben am Blattanfang ist lesbar:$B$B$B Nagaz$B$B",objectives={"Bringt den verschlüsselten Brief zum Meister der Lehren Dibbs nach Southshore."}]])
R(552,"Helculars Rache",[[description="Meister Helcular hatte seine Transformation in einen Lich fast vollständig abgeschlossen, als ein menschlicher Lynch-Mob seinen rituellen Unterschlupf in den Hügeln entdeckte und ihn brutal ermordete. Was die Angelegenheit noch schlimmer macht, ist, dass sie seinen Leichnam auf dem Friedhof von Southshore begraben haben.$b$bDiese Missachtung eines großen Hexers ist einfach nicht akzeptabel. Als sein Lehrling werde ich dafür sorgen, dass der Regen der Rache auf Southshore fallen wird.$b$bAber zuerst benötigen wir Helculars Rute. Yetis befinden sich jetzt in seinem rituellen Unterschlupf. Bestimmt hat sich eine dieser Bestien die Rute angeeignet.",objectives={"Holt Helculars Rute von dem Yeti und bringt sie zu Novize Thaivand nach Tarrens Mühle zurück."}]])
R(553,"Helculars Rache",[[description="Hier, nehmt die Rute von Helcular. Ihr werdet sie brauchen.$b$bHelcular stellte 3 zeremonielle Scheiterhaufen als Teil seines mächtigsten Zaubers auf. Die Flamme von Azel und die Flamme von Veraz liegen in den Vorgebirgshöhlen. Die Flamme von Uzel liegt in einer Höhle über diesen Höhlen, weiter nördlich in den Bergen.$b$bDie Rute von Helcular muss mit jeder der drei Flammen aufgeladen werden. Sobald das Ritual abgeschlossen ist, stoßt Ihr die Rute in Helculars Grab in Southshore, der streng bewachten Menschen-Stadt im Süden. Die Rache wird unser sein!",objectives={"Ladet die Rute von Helcular mit der Macht der Flamme von Azel, der Flamme von Veraz und der Flamme von Uzel auf.$b$bStoßt die aufgeladene Rute in Helculars Grab in Southshore."}]])
R(554,"Stormpikes Entschlüsselung",[[description="Ausgrabungsleiter Stormpike ist ein Meister der Dechiffrierung und Entschlüsselung. Wenn Ihr das Pergament, das Ihr gefunden habt, zu ihm bringt, kann er mit etwas Glück herausfinden, was darin steht. Im Moment studiert Stormpike im Ausgrabungsleiter-Hauptquartier in Ironforge.$B$BWenn Ihr ihn seht, richtet ihm aus, dass Ihr mit mir gesprochen habt, - ich habe ihm in letzter Zeit einiges zu tun gegeben.",objectives={"Bringt das verhexte Pergament zu Ausgrabungsleiter Stormpike nach Ironforge."}]])
R(555,"Milde Schildkrötensuppe",[[description="Wenn es etwas Wissenswertes über Southshore gibt, dann dass wir hier die beste Küche nördlich von Stormwind haben!$b$bNehmt als Beispiel nur mal mein Rezept für Schildkrötensuppe. Ich habe Leute getroffen, die sogar von Dunkelhain hergekommen sind, nur um eine Schüssel voll davon zu kosten. Da wir gerade davon sprechen, in letzter Zeit konnte ich keine mehr kochen. Ich bin früher selbst bis kurz hinter Dalaran an den Lordameresee gereist, um Schnappkiefer zu jagen, aber das ist jetzt zu gefährlich. Wenn Ihr mir etwas Schildkrötenfleisch von den Schnappkiefern aus dem Norden bringt und dazu noch feine Gewürze, dann werd ich eine kochen!",objectives={"Bringt 10 Stücke Schildkrötenfleisch und einige feine Gewürze zu Küchenchef Jessen nach Southshore."}]])
R(556,"Steinmarken",[[description="Ein bemerkenswertes Talent der Hexer von Dalaran ist ihre Vertrautheit mit den Elementaren: mächtige Kreaturen aus anderen Dimensionen. Die Hexer benutzen magische Marken als Mittel, diese Elementare zu kontrollieren. Magus Voidglare hätte gern einige dieser Marken, damit er sie studieren kann.$B$BBegebt Euch auf das Gebiet der Hexer von Dalaran, westlich von Hillsbrad, und sammelt die Marken ein.$B$BJeder Einwohner von Dalaran hat solche Marken, aber ich schlage vor, dass Ihr im Internierungslager auf die Suche geht. Dort ist es sicherer als in Dalaran selbst.",objectives={"Bringt 10 abgenutzte Steinmarken zu Bewahrer Bel'varil nach Tarrens Mühle."}]])
R(557,"Armschienen der Bindung",[[description="Der Magus wird die Steinmarken, die Ihr gesammelt habt, einige Zeit lang intensiv untersuchen, aber ich weiß, dass er später mit Bestimmtheit auch Exemplare ihrer Gegenstücke haben will: Armschienen der Bindung. Diese befinden sich an den Handgelenken von echten Elementaren und binden sie in die Dienste der Magier.$B$BMacht Jagd auf Elementare in den Ruinen von Dalaran und sammelt ihre Armschienen der Erdbindung, und der Magus wird sehr erfreut sein.",objectives={"Bringt 4 Armschienen der Erdbindung zu Bewahrer Bel'varil nach Tarrens Mühle."}]])
R(558,"Jainas Autogramm",[[description="Ich habe gehört, dass Lady Jaina Prachtmeer aus Theramore eine der größten Heldinnen ist, die die Allianz je gesehen hat. Wenn ich mal groß bin, möchte ich auch ein Held der Allianz werden!$B$BKennt Ihr Jaina, $n? Tut Ihr mir einen Gefallen? Kriege ich ein Autogramm von ihr? Ich weiß gar nicht, wie ich sie ansprechen soll, und wahrscheinlich ist sie sowieso viel zu beschäftigt, um mich zu beachten... aber was ist mit Euch? Ihr seid doch genau wie sie ein Abenteurer! Euch gibt sie bestimmt ein Autogramm!$B$BBitte, $n. Bitte...",objectives={"Reist nach Theramore und versucht für Euren Schützling ein Autogramm von Lady Jaina Prachtmeer zu ergattern."}]])
R(559,"Farrens Beweis",[[description="Was haltet Ihr davon, $N? Redpath war nicht zufrieden mit den ganzen Murlocs, die wir getötet haben - seid nur nicht so bescheiden, Ihr wart ja auch dran beteiligt. Jetzt verlangt er von mir, dass ich ihren Tod beweise und kalte, schleimige Murlocköpfe abhacke und sie ihm bringe, um seine Anerkennung zu erlangen.",objectives={"Sammelt 10 Murlocköpfe von den Murlocs am Weststrand für Lieutenant Farren Orinelle in Southshore."}]])
R(560,"Farrens Beweis",[[description="Wisst Ihr, $n, ich würde die Köpfe am liebsten gar nicht anfassen... Da Ihr sie nun schon mal angefasst habt, würde es Euch sehr viel ausmachen, sie zu Redpath zu bringen?",objectives={"Bringt den Sack mit den Murlocköpfen zu Marshal Redpath nach Southshore."}]])
R(561,"Farrens Beweis",[[description="Bitte informiert Lieuntenant Orinelle über meinen Wunsch, er möge seine Aufmerksamkeit erneut auf die Nagaplage am Oststrand richten. Sobald er Resultate erzielt hat, soll er persönlich bei mir Bericht erstatten.",objectives={"Sprecht mit Lieutenant Farren Orinelle in Southshore."}]])
R(562,"Stormwind Ho!",[[description="Mein ehemaliger Mentor bei der Stadtwache von Stormwind hat mir eine Nachricht zukommen lassen, dass sich das Oberkommando der Allianz langsam Sorgen macht um die Bedrohung, die von den Naga ausgeht. Er hat gehört, dass es gute Aussichten auf eine Beförderung - oder zumindest Versetzung - für jeden gibt, der sich in dieser Angelegenheit als hilfreich erweist.$b$bEs gibt da nur ein winzigkleines Problem... Ich schaff die Naga nicht, $N. Klar, ich kann eine Kneipenschlägerei auflösen, oder einen aggressiven Bettler wegschaffen, aber die Naga sind einfach zu viel für mich. Ihr müsst mir helfen, $N!",objectives={"Tötet 10 Küstenjäger der Säbelflossen und 10 Sirenen der Säbelflossen für Lieutenant Farren Orinelle in Southshore."}]])
R(563,"Versetzungen",[[description="Es dürfte kein Problem sein, meinen Bericht zu beachten. Der neue Captain der Wachen, Major Samuelson, war mein Mentor, während ich in Stormwind stationiert war. Der Bericht sollte ihm mehr als genug Grund geben, mich wieder in die Stadt zu versetzen. Aber ich brauche Euch, damit Ihr meinen Bericht zu ihm bringt... der alte Redpath soll nichts davon mitkriegen.",objectives={"Bringt Farrens Bericht zu Major Samuelson in die Burg Stormwind."}]])
R(564,"Teure Bedrohung",[[description="Nix macht mich wütender als wenn ich diese schönen Pferdchen verlieren tu. Und glaubt's mir, wir hab'n 'ne ganze Menge verloren, an die eklichen untoten Unholde, das verdammte Syndikatsgesocks und all die anderen tunichgute Schurken, die hier so rumlaufen tun.$b$bAber ich schwör beim Grab von mein alten Opa, 'ne größere Gefahr für uns're Pferdchen als die vonne Berglöwen in Alterac tut's nich' geben tun. Komm' alle Nase lang vonne Berge runner und machen mir dat Leben schwer.$b$bUnd Ihr seid also 'n Held? Dann geht mal und tut was dagegen unternehm' tun!",objectives={"Darren Malvew aus Southshore will, dass Ihr 8 Berglöwen und 10 titanische Berglöwen tötet."}]])
R(565,"Bartolos Yetifellumhang",[[description="Ich, der große Bartolo, werde für Euch den weltberühmten, allianzweit bekannten Yetifellumhang anfertigen.$b$bIch wette mit Euch: Auch wenn Ihr die ganze Welt bereist, findet Ihr keinen besseren Umhang. Oh, wartet mal, was ist das, kleiner $R? \"Bartolo, es gibt keinen feineren Umhang!\" Ja, ja! Das habe ich schon öfter gehört.$b$bBartolo benötigt einen Wollstoffballen, einen Umhang des Hügelwächters von einem geschickten Lederer, feinen Faden und natürlich Yetifell. Bringt mir diese Dinge und Ihr werdet ein glücklicher Kunde!",objectives={"Bringt Bartolo Ginsetti in Southshore einen Wollstoffballen, einen Umhang des Hügelwächters, feinen Faden und 10 Haufen Yetifell."}]])
R(566,"GESUCHT: Baron Vardus",[[description="Laut Befehl der Hochexekutorin Darthalia wird der unter dem Namen Baron Vardus bekannte Mensch wegen Verbrechen gegen die Verlassenen gesucht. Vardus ist bekannt als hochrangiges Mitglied der Organisation, die sich das Syndikat nennt.$b$bZuletzt wurde er im Oberland des Alteracgebirges im Norden von Tarrens Mühle gesehen.$b$bEr soll getötet werden. Für den Erhalt der Belohnung müssen Beweise seines Todes zu Hochexekutorin Darthalia gebracht werden.",objectives={"Tötet Baron Vardus und bringt seinen Kopf zu Hochexekutorin Darthalia in Tarrens Mühle."}]])
R(567,"Gefährlich!",[[description="Gefährlich!$b$bDie folgenden Menschen aus Hillsbrad werden als gefährlich erachtet. Ein Kopfgeld ist von Hochexekutorin Darthalia auf sie ausgesetzt worden.$b$bAmtmann Horatio Whitesteed. Gesucht wegen Mordes an Todeswache Toma.$b$bBürger Wilkes. Gesucht wegen Mordes an Apotheker Eli.$b$bMinenarbeiter Hackett. Gesucht wegen Mordes an Todespirscher Fry.$b$bBäuerin Kalaba. Gesucht wegen hinterhältigem Überfall auf Vorräte von Undercity.$b$bJeder dieser Feinde hat sich versteckt und wird nur sehr schwer zu finden sein. Auf die Nachricht ihres Todes wird eine Belohnung gewährt.",objectives={"Hochexekutorin Darthalia in Tarrens Mühle hat ein Kopfgeld auf Amtmann Horrace Whitesteed, Bürger Wilkes, Minenarbeiter Hackett und Bäuerin Kalaba ausgesetzt."}]])
R(568,"Die Verteidigung von Grom'gol",[[description="Throm-ka, $C!$b$bEure Ankunft in Grom'Gol kommt wahrlich zur rechten Zeit. Als Kommandant des Kriegshäuptlingsstützpunkts hier im Dschungel bin ich durch meine Ehre gebunden und verpflichtet, die Sicherheit aller Mitglieder der Horde zu gewährleisten. Unsere Aufgabe, eine sichere Versorgungskette nach Stonard zu gewährleisten wird durch einige der örtlichen Einwohner schwer behindert.$b$bIch gebe Euch den Auftrag, die Raptorpopulation außerhalb Grom'gols zu reduzieren. Sobald Ihr nennenswerte Fortschritt erzielt habt, erstattet mir Bericht und Ihr erhaltet einen neuen Auftrag.",objectives={"Kommandant Aggro'gosh vom Basislager von Grom'gol will, dass Ihr 15 Schmetterschwanzraptoren tötet."}]])
R(569,"Die Verteidigung von Grom'gol",[[description="Als wir in diesem Dschungel ankamen, hatten wir nicht vor, die hier ansässigen Stämme zu bekämpfen. Unsere Mission, Stonard zu versorgen, hat höchste Priorität. Aber es gibt Komplikationen. Eine hier ansässige Gruppe von Ogern hat die Ruinen von Mizjah im Südosten von Grom'gol besetzt. Trotz unserer Warnungen überfallen sie weiterhin unsere Nachschubkarawanen.$b$bIch beauftrage Euch hiermit, Euch mit diesen unkooperativen Ogern auseinander zu setzen.$b$bReist zu den Ruinen und versucht, sie aus diesem Gebiet zu vertreiben. Das sollte ihnen zumindest ein eindeutiges Zeichen setzen.",objectives={"Kommandant Aggro'gosh vom Basislager von Grom'gol will, dass Ihr 10 Ogerschläger und 5 Ogerhexendoktoren tötet."}]])
R(570,"Mok'Thardins Verzauberung",[[description="Die Macht der Dschungelmagie muss erkannt und kann dann von der Horde genutzt werden. Meine Rituale waren bislang erfolgreich. Ich kann sehr mächtige Verzauberungen wirken. Für Euch, mutiger $C, werde ich einen wirklich ganz besonderen Gegenstand herstellen.$b$bBringt mir einige Schattentatzenpantherkrallen und den Fangzahn einer Tigerin. Es darf aber nicht irgendein Fangzahn sein. Er muss sich in einem makellosen Zustand befinden.$b$bDiese Bestien lauern im gesamten Dschungel, aber Ihr könnt einige ganz in der Nähe finden. Überquert den Fluss von den Mizjah-Ruinen aus in südöstlicher Richtung.",objectives={"Scharfseher Mok'thardin im Basislager von Grom'gol will 8 Schattentatzenkrallen und einen makellosen Tigerinnenfangzahn."}]])
R(571,"Mok'Thardins Verzauberung",[[description="Was ich nun von Euch benötige, ist sehr schwer zu bekommen.$b$bIch benötige ein magisches Band, um all diese Federn, Krallen und den makellosen Fangzahn zu befestigen. Nur die Sehne eines alten Gorillas ist dazu geeignet.$b$bEine solche könnt Ihr nur von einem alten Nebeltalgorilla bekommen. Sie sind oft auf Nahrungssuche im Osten von Booty Bay.$b$bDie Sehne muss in vollkommenem Zustand sein. Ihr werdet wahrscheinlich mehrere Tiere töten müssen, bis Ihr genau das erhaltet, was ich benötige, aber das ist es in jedem Fall wert.",objectives={"Bringt die Sehne eines alten Gorillas zu Scharfseher Mok'thardin nach Grom'gol."}]])
R(572,"Mok'Thardins Verzauberung",[[description="Die Dinge, die Ihr von den katzenartigen Bestien des Tales gesammelt habt, sind nur die erste Voraussetzung für einen machtvoll verzauberten Gegenstand. Diese Dschungelornamente, in Verbindung mit meinem Schamanenritual, werden Euch mit einem äußerst nützlichen Werkzeug versehen, mit dessen Hilfe Ihr der Horde und dem Kriegshäuptling beistehen könnt.$b$bAber jetzt müsst Ihr für mich einige Dschungelpirscherfedern sammeln. Für gewöhnlich tragen die Bestien diese Federn an ihren Armbändern. Ihr findet einen Stamm dieser Raptoren direkt südlich von Grom'gol, nicht weit von der großen Arena.",objectives={"Bringt 10 Dschungelpirscherfedern zu Scharfseher Mok'thardin nach Grom'gol."}]])
R(573,"Mok'Thardins Verzauberung",[[description="Es fehlt nun nur noch ein Reagenz, um die Verzauberung zu vervollständigen.$b$bIm Süden, nahe der Westküste, liegt ein Heiliger Quell, hoch über den Steilhängen. Dieser Quell ist das Objekt großer Konflikte zwischen religiösen und mystischen Gelehrten. Jede einzelne Gruppe in Azeroth vertritt die Auffassung, dass das Quellwasser nur für das eigene Volk göttlich gemacht wurde.$b$bMeine letzte Aufgabe für Euch: Bringt mir Wasser der Heiligen Quelle. Aber ich warne Euch: Eine Expedition von Forschern der Naga ist auf dem Weg zu der Quelle. Mit ihnen müsst Ihr Euch ebenfalls befassen.",objectives={"Scharfseher Mok'thardin von Grom'gol benötigt Wasser der Heiligen Quelle. Er will auch, dass Ihr 10 Forscher der Naga tötet."}]])
R(574,"Spezialtruppe",[[description="Nun, da viele von seinen regulären Truppen gefallen sind, müsst Ihr es mit seinen hochtrainierten Streitkräften aufnehmen. Wenn sie nicht in der Wildnis unsere Rebellensoldaten erschlagen, kann man sie tief innerhalb von Kurzens Truppenlager finden, in einer Höhle, die sie das Vorratslager nennen.$B$BIch kenne einige von Kurzens Truppen persönlich und weiß, dass sie geschickt, loyal und grausam sind. Dies ist keine einfache Aufgabe, mit der ich Euch betraue, $N.$B$BNachdem Ihr sie besiegt habt, meldet Euch bei Lieutenant Doren, meinem befehlshabenden Offizier. Er wird Euren Bericht aus erster Hand haben wollen.",objectives={"Tötet 10 von Kurzens Kommandosoldaten und 6 von Kurzens Kopfschrumpfer.$B$BErstattet Bericht bei Lieutenant Doren im Rebellenlager."}]])
R(575,"Angebot und Nachfrage",[[description="Der beste Ledermacher der südlichen Meere und der Alten wie der Neuen Welt. So nennen sie mich. Mich! Drizzlik! Der beste Le... ähem. Nun ja.$b$bMeine Lederwaren sind nah und fern als absolut vorzüglich bekannt, erste Wahl der wahren Kenner!$b$bGerade habe ich eine Bestellung von Direktor Riddlevox vom Tüftlerverband über ein Dutzend seiner Lieblingsstiefel aus der Exzelsiorlinie erhalten. Unsere Verkaufsschlager, ehrlich gesagt.$b$bFür die Grundform benötige ich Krokiliskenhäute von den Kroks entlang des Flusses im Norden des Schlingendorntals.",objectives={"Bringt 2 große Flusskrokiliskenhäute zu Drizzlik nach Booty Bay."}]])
R(576,"Ein Auge offen halten",[[description="Haltet ein! Wer da?$b$bGrrr, ich bin so gut wie nutzlos ohne mein verzaubertes Spezialauge. Als ob es nich' schon schlimm genug is', dass ich meine Augen im Kampf verlor'n hab! Aber zum Glück haben wir in Menethil angelegt und ein reisender Hexer hat 'n Spezial-Glasauge verzaubert, mit dem ich wieder was sehen kann.$b$bGestern Nacht hab'n mir aber 'n paar von den Blutsegelbukanier'n auf'm Weg nach Haus aufgelauert. Die ham mir doch echt mein Auge geklaut! Scheint, als hätt'n die Burschen Booty Bay gefunden.$b$bKönnt'er 'nem alten Seebären helfen und mir mein Auge zurückholen?",objectives={"Dizzy One-Eye in Booty Bay möchte, dass Ihr sein Auge von den Blutsegelbukanieren zurückholt."}]])
R(577,"Etwas Zusammenbau benötigt",[[description="Nun, ich habe die Grundform der Stiefel so weit und sie werden auch sehr gut, aber die Häute, die Ihr mir brachtet, werden leider nicht für die inneren Schichten ausreichen.$b$b\"Was sollen wir tun, Drizzlik?\" Diese Frage brennt Euch zweifelsohne auf den Lippen, und Ihr habt wirklich Glück, dass Ihr mit Drizzlik sprecht, denn er wird Euch genauestens erklären, was wir zu tun gedenken!$b$bDie inneren Schichten sieht sowieso nie jemand, also werden wir uns zum Ausfüllen der Stiefel einige der billigeren, dickeren Häute der Krokos holen, die um den Nazferitisee leben.",objectives={"Bringt 5 Schnappkieferkrokiliskenhäute zu Drizzlik nach Booty Bay."}]])
R(578,"Der Stein der Gezeiten",[[description="Wenn es wirklich einen Goblinmagier und Wasserelementare gibt, die auf dieser Insel ihr Unwesen treiben, dann heißt das, dass der Stein der Gezeiten wirklich mir gehören kann!$b$bIch will, dass Ihr diese Spukinsel findet und herausfindet, wie es dort zugeht. Oh, und falls Ihr mehr über den Stein der Gezeiten herausfinden wollt, bringt diesen Schein zur Bibliothek von Stormwind, sie sollten dort ein Exemplar des Buches für Euch finden, in dem ich zuerst von der Legende gelesen habe.$b$bSollte es möglich sein, dass Gazban wirklich den Stein gefunden hat...?",objectives={"Findet die Spukinsel für Baron Revilgaz in Booty Bay."}]])
R(579,"Bibliothek von Stormwind")
R(580,"Whiskey Slim's verlorener Grog",[[description="Wir waren dabei, uns tüchtig einen hinter die Binde zu gießen, konnten 's Hinterland schon sehen. Dachten schon, die See wollte uns ganz und gar verschlingen.$b$bOl' Slim weiß alles über flüssigen Mut! Der Käpt'n hatte eine Kiste mit Pupellyverbos-Portwein, den wir auf'm Weg nach Stormwind von 'nem Freibeuter geholt hatten.$b$bAls der Sturm uns dann vom Hinterland aus getroffen hat, bin ich also in den Grog rein. Große Welle kam und hat die Flaschen über Bord gespült. Der Käpt'n wird mich bestimmt mit der Katze streicheln, wenn Ihr mir nich' helft, die wieder zurückzubringen!",objectives={"Whiskey Slim in Booty Bay möchte, dass Ihr ihm die Flaschen Pupellyverbos-Portwein bringt, die er verloren hat."}]])
R(581,"Die Suche nach Yenniku",[[description="Unheil droht. Unheil für den jüngsten Sohn meines Häuptlings, Yenniku. Der Sitte unseres Volkes nach wurde er den Gurubashitrollen von Zul'Gurub gegeben, aber nachdem mein Stamm, der Darkspearstamm, mit dem Orc Thrall gegangen ist, war der arme Yenniku für uns verloren. Ich wurde aus dem fernen Orgrimmar zurück ins Schlingendorntal geschickt, um nach dem Sohn meines Häuptlings zu suchen.$B$BUnd ich glaube, dass der Bloodscalpstamm ihn hat.$B$BWenn Ihr mir helfen wollt, dann jagt die Bloodscalps. Ihr könnt sie im Norden finden. Sammelt ihre Hauer und kehrt zu mir zurück.",objectives={"Bringt 9 Hauer der Bloodscalp zu Nimboya in das Basislager von Grom'gol."}]])
R(582,"Kopfjägerei",[[description="Wir müssen herausfinden, ob Yenniku tot ist.$B$BErschlagt die Kopfjäger der Bloodscalp und nehmt ihnen ihre Schrumpfköpfe ab. Ihr müsst viele, viele Köpfe sammeln und ich werde sie überprüfen, um sicherzugehen, dass Yennikus Kopf nicht dabei ist.$B$BSollte Yenniku von den Bloodscalps getötet worden sein, möge ein Fluch für 600 Jahre auf den Geist ihres Häuptlings, Gan'zulah, kommen!$B$BGeh, $N. Viele Kopfjäger könnt Ihr bei den Ruinen von Zuuldaia und Zul'Kunda an der Küste im Norden finden.",objectives={"Bringt 20 Schrumpfköpfe zu Nimboya in das Basislager von Grom'gol."}]])
R(583,"Willkommen im Dschungel",[[description="Willkommen im Schlingendorntal!$b$bIhr seid es Euch vielleicht nicht bewusst, aber der Zwerg dort drüben ist der wunderbare Hemet Nesingwary, weitbekannter Kriegsheld der Allianz und Meistergroßwildjäger. Er ist nicht gerade sehr bekannt dafür, dass er Fremde in seinem Lager sehr mag, aber Ihr seht aus, als hättet Ihr schon das eine oder andere Abenteuer erlebt, $C.$b$bDa er selbst ein erfahrener Kriegsveteran ist, hat Meister Nesingwary eine Schwäche für andere Helden.$b$bGeht und sprecht mit ihm. Vielleicht kann er Euch einige Ratschläge für die Jagd mitgeben.",objectives={"Sprecht mit Hemet Nesingwary."}]])
R(584,"Köpfe des Bloodscalpklans",[[description="Yenniku war nicht unter den Köpfen, der Großen Schlange sei Dank. Aber wir sind noch weit entfernt davon, ihn zu finden.$B$BWir müssen die Wahrheit herausfinden, und ich fürchte, dass nur der Häuptling der Bloodscalp und sein Hexendoktor sie kennen. Sie sind Feinde des Darkspearstammes und werden nicht freiwillig reden, also müssen wir die Wahrheit von ihren toten Lippen erzwingen!$B$BBringt mir die Köpfe von Gan'zulah und Nezzliok dem Düsteren und legt sie in diesen Kessel.$B$BSie halten sich in den Tiefen von Zul'Kunda auf. Bringt ihre Köpfe... wir werden sie schon zum Sprechen bringen.",objectives={"Bringt Gan'zulahs Kopf und Nezzlioks Kopf zum blubbernden Kessel im Basislager von Grom'gol."}]])
R(585,"Mit Nezzliok sprechen",[[description="<Der Kopf von Nezzliok spricht.>$B$BEs stimmt. Ich weiß, wo das Kind der Darkspears hingebracht wurde. Ihr habt mich besiegt und meinen Geist gebunden, aber ohne Gegenleistung sage ich nichts!$B$BDie Bloodscalps streiten mit den Skullsplitters. Um mein Wohlwollen zu erhalten, stehlt 3 der Trophäenschädel von den Skullsplittern und legt sie hierher zu uns, sodass mein Geist im Nether Sklaven zur Verfügung hat. Ein Schädel muss aus ihrem Trophäenstapel in Balia'mah, der zweite von Ziata'jai und der dritte von Zul'Mamwe stammen.",objectives={"Bringt eine Balia'mah-Trophäe, eine Ziata'jai-Trophäe und eine Zul'Mamwe-Trophäe zum blubbernden Kessel im Basislager von Grom'gol."}]])
R(586,"Mit Gan'zulah sprechen",[[description="<Der Kopf von Gan'zulah spricht.>$B$BVerflucht seid Ihr! Und auch Eure Vorfahren!$B$BNur Blut und Rache können meine Wut beschwichtigen; wenn das Euer Wunsch ist, dann... tut Folgendes:$B$BWerft Euch in das Herz der Skullsplitter im Osten. Erschlagt die schrecklichsten unter ihnen, und wenn Ihr überleben solltet... dann tretet gegen ihren Häuptling, Ana'thek den Grausamen, an. Ha! Bringt mir seine zerschmetterte Rüstung, wenn Ihr es vermögt!$B$BMöge er Eure Glieder ausreißen und Euch der Fäulnis ausliefern und den Geiern zum Fraß vorwerfen.",objectives={"Tötet 8 Jäger der Skullsplitter, 6 Kopfjäger der Skullsplitter und 4 Berserker der Skullsplitter.$B$BBringt die zerbrochene Rüstung von Ana'thek zum blubbernden Kessel in das Basislager von Grom'gol."}]])
R(587,"Auf dem Schnupftabak",[[description="Ah, das Leben auf See. Ich sag nicht, dass es das wahre Leben ist, aber es ist mein Leben.$b$bWenn ich in den Hafen komme, such ich mir eine gute Flasche Grog und sehr guten Schnupftabak. Schlechte Angewohnheiten, ich weiß, aber irgendein Laster muss'n Pirat ja nun mal haben , nich?$b$bAlso könnt Ihr Euch vielleicht vorstellen, wie niedergeschlagen ich war, als ich herausfand, dass der Kräuterkundige nichts von dem Zeug mehr da hatte. Erzählte mir, dass seine Lieferung von den verdammten Räubern der Blutsegelbukaniere geklaut worden ist.$b$bIch wette, ein furchtloser $C wie Ihr könnte sie überreden, die Ware zu teilen, nich?",objectives={"Deeg in Booty Bay möchte, dass Ihr ihm 15 Teile Schnupftabak bringt."}]])
R(588,"Yennikus Schicksal",[[description="<Nezzliok spricht>$B$BIhr habt mich und meinen Häuptling beschwichtigt, also werde ich Euch verraten, was Ihr zu wissen wünscht...$B$BDer junge Yenniku ist für seinen Klan verloren.$B$BEr wurde von dem Hexendoktor Zanzil, dem Ausgestoßenen, verschleppt. Sein Körper und sein Geist werden jetzt durch Zanzil kontrolliert und nur eine mächtige Magie kann ihn wieder befreien.$B$BEine Magie, über die Ihr nicht verfügt, $C.$B$BMöglicherweise können Eure Verbündeten bei den Darkspear Euch etwas Hoffnung auf Yennikus Rettung bieten. Aber dies bezweifle ich.",objectives={"Sprecht mit Kin'weelay."}]])
R(589,"Die singenden Kristalle",[[description="Die Legenden berichten von einem Juwel, das tief im Herzen des Schlingendorntals versteckt liegt. Wir nennen es das Gedankenauge. Es verfügt über große Macht. Wenn Ihr dieses Auge finden könnt, dann können wir es vielleicht nutzen, um den verlorenen Yenniku aus der Dunkelheit zurückzubringen.$B$BIch werde mit den Geistern des Dschungels beraten, um das Gedankenauge zu finden. Während ich das tue, geht Ihr in die Kristalladermine, die sich südöstlich von hier befindet, und sammelt pulsierende blaue Splitter von den Eisenkieferbasilisken. Die Splitter gibt es nur sehr selten, aber wir benötigen ihre Magie, um das Gedankenauge unserem Willen zu unterwerfen.",objectives={"Bringt 3 pulsierende blaue Splitter zu Kin'weelay in das Basislager von Grom'gol."}]])
R(590,"Ein Schurkenhandel",[[description="Was?$B$BWas?!$B$BIhr wollt Geld? Ich schulde Euch kein Geld.$B$BBrief? Was für ein Brief? Oh, Ihr wollt also kämpfen? Nun, gut Kumpel... dann lasst uns anfangen! Schulde Euch Geld...",objectives={"Besiegt Calvin Montague in Deathknell."}]])
R(591,"Das Gedankenauge",[[description="Das Gedankenauge befindet sich bei einem Ogermagier, in den Tiefen des Ogerhügels der Mosh'Ogg östlich von hier. Sein Name ist Mai'Zoth. Ich kenne ihn noch von der Zeit, als sich die Darkspears im Schlingendorntal aufhielten - er ist bösartig und seine Magie ist stark.$B$BUnd wenn er im Besitz des Gedankenauges ist, dann ist seine Magie noch stärker.$B$BIhr müsst gegen Mai'Zoth antreten und ihm das Gedankenauge abnehmen. Es ist eine gefährliche Aufgabe, aber es ist die einzige Hoffnung, die wir haben, Yenniku zu retten.",objectives={"Bringt das Gedankenauge zu Kin'weelay in das Basislager von Grom'gol."}]])
R(592,"Yennikus Rettung",[[description="Ich habe das Gedankenauge in einen Seelenedelstein umgeformt. Somit hat er zweierlei Zwecke: Erst verwendet Ihr ihn, um Yenniku zu betäuben, und sobald er betäubt ist, legt Ihr den Seelenedelstein auf seinen Kopf, um seine Seele einzufangen.$B$BDann bringt Ihr den Edelstein zu Nimboya.$B$BYenniku ist bei Zanzil dem Ausgestoßenen, in den Ruinen von Aboraz, entlang des Kristallufers am fernen Kap des Schlingendorntals.",objectives={"Bringt den gefüllten Seelenedelstein zu Nimboya."}]])
R(593,"Den Seelenedelstein füllen")
R(594,"Flaschenpost",[[description="In der Notiz steht Folgendes in recht guter Handschrift:$B$BAn alle, die mir helfen können:$B$BBitte, ich benötige dringend Hilfe. Ein großer Blaumähnengorilla hält mich auf einer Insel in den südlichen Meeren gefangen.$B$BDie Sternbilder am Nachthimmel sind mir nicht vertraut und von Dschungelbäumen verdeckt, aber an klaren Tagen kann ich die wilden Ufer im Nordwesten erkennen und im Südwesten etwas, das große Segelschiffe sein könnten.$B$BIch flehe Euch an, mein möglicher Retter, bitte helft mir.",objectives={"Findet den Schreiber dieser Flaschenpost."}]])
R(595,"Die Blutsegelbukaniere",[[description="Ihr scheint ja sehr erpicht auf Arbeit zu sein, Kumpel. Bin nicht sicher, warum eine Landratte wie Ihr, $R, und ein $C noch dazu, den Schwarzmeerräubern Hilfe anbietet, aber ich werd Euch nicht fortschicken.$b$bUnser Schiff hat gerade hier in Booty Bay angedockt und es heißt, dass unsere Rivalen - diese verdammten, dreckigen Blutsegelbukaniere - sich im gesamten Süden des Schlingendorntals herumtreiben.$b$bMeine Jungs sind aber zu beschäftigt, sich einen anzusaufen und Mädchen nachzugaffen! Was ich brauch, ist ein Späher.$b$bBegebt Euch zur Bucht im Norden von Booty Bay an der ungezähmten Küste und schaut, was Ihr so findet.",objectives={"Erster Maat Crazz will, dass Ihr die Bucht nördlich von Booty Bay überprüft."}]])
R(596,"Blutige Knochenhalskette",[[description="Ich wurde nach Grom'gol geschickt, um Nimboya auf seiner Suche zu begleiten, aber... Ich habe meine eigenen Gründe, hier zu sein.$B$BDer Bloodscalpstamm ist der Feind unseres Stammes. Wenn wir Trophäen unserer Feinde sammeln, erhalten wir Macht über sie. Ihr könnt unserem Stamm behilflich sein, indem Ihr unsere Feinde jagt.$B$BSie leben im Norden. Erschlagt die Trolle der Bloodscalp und nehmt ihre blutigen Knochenhalsketten mit. Wenn Ihr viele davon sammelt, wird Eure Belohnung groß sein.",objectives={"Bringt 25 blutige Knochenhalsketten zu Kin'weelay in das Basislager von Grom'gol."}]])
R(597,"Die Blutsegelbukaniere",[[description="Die Karte zeigt Booty Bay mit einem roten \"X\" genau an dem Punkt, wo Ihr gerade steht.$b$bDer hingekritzelte Text lautet:$b$b\"Leute, errichtet ein Lager an dieser Stelle und verhaltet euch schön unauffällig. Wartet auf das Signal vom südlichen Kommandoposten, bevor ihr angreift. Wenn sich jemand euch nähert, tötet ihr ihn.\"",objectives={"Berichtet dem ersten Maat Crazz in Booty Bay von Euren Funden."}]])
R(598,"Spaltknochenhalskette",[[description="Nun, da Ihr Bloodskalp-Trophäen gesammelt habt, habe ich eine weitere Aufgabe für Euch. Der Skullsplitterstamm der Trolle lebt im Südwesten und wir bekämpfen sie schon seit Jahren. Obwohl keine Darkspears mehr im Schlingendorntal leben, sind wir immer noch dem Konflikt mit den Skullsplittern verpflichtet.$B$BAlso, jagt sie. Sammelt ihre Spaltknochenhalsketten und kehrt zu mir zurück. Helft uns in unserem Krieg und Ihr werdet die Freundschaft der Darkspears erlangen.",objectives={"Bringt 25 Spaltknochenhalsketten zu Kin'weelay in das Basislager von Grom'gol."}]])
R(599,"Die Blutsegelbukaniere",[[description="Neee, isses denn wahr! Also planen die Blutsegelbukaniere einen Angriff auf Booty Bay? Diese Schurken haben vielleicht Nerven. Booty Bay wird immer von den Schwarzmeerräubern beherrscht werden!$b$bDas ist ein größeres Unterfangen als ich dachte. Erstattet Flottenmeister Seehorn sofort Bericht über alles, was Ihr erfahren habt! Der alte Seebär ist irgendwo in der Stadt...",objectives={"Erstattet Flottenmeister Seehorn Bericht über den geplanten Angriff der Blutsegelbukaniere."}]])
R(600,"Venture Company-Bergbau",[[description="Die Venture Company hat ein paar Sachen im Schlingendorntal am Laufen, die hart arbeitende Goblins, wie ich es einer bin, davon abhalten, ehrliches Gold zu verdienen. Bitte, Ihr müsst mir helfen!$B$BDie Venture Company betreibt einen Stollen in der Nähe der Kristalladermine im Norden. Sie kommen nicht in die Mine hinein wegen der ganzen Basilisken, aber trotzdem sind sie in der Lage, singende Kristalle aus den umgebenden Hügeln herauszugraben.$B$BNehmt ihnen die Kristalle ab und zeigt ihnen, dass sie im Dschungel nichts zu melden haben.$B$BUnd... ähm... bringt mir diese Kristalle als Beweis!",objectives={"Bringt 10 singende blaue Kristalle zu Crank Fizzlebub nach Booty Bay."}]])
R(601,"Wasserelementare",[[description="Die Wasserelementare wurden ohne Zweifel von Gazban, dem Goblinhexer beschworen, von dem man behauptet, er habe den Stein der Gezeiten entdeckt. Wie Ihr vielleicht wisst, verflucht der Stein der Gezeiten seinen Träger, sodass er ständig zwischen Sein und Nicht-Sein wandelt.$b$bVielleicht können wir einen Weg finden, dem Fluch entgegenzuwirken. Ein Magier von Dalaran kann die magischen Überreste einer der Armschienen des Wasserelementars für uns analysieren. Ihr müsst wieder zurück zur Insel und einige Exemplare davon herbringen.",objectives={"Holt 6 Wasserelementararmschienen für Baron Revilgaz in Booty Bay."}]])
R(602,"Magische Analyse",[[description="Wie ich gehört habe, sind die Magier von Dalaran sehr damit beschäftigt, ihre zerstörte Stadt wieder aufzubauen. Ich bin aber trotzdem sicher, dass Ihr einen finden könnt, der sich etwas Zeit für diese Armschienen nehmen wird. Denn wenn ich etwas über Magier weiß, dann, dass sie einem magischen Rätsel einfach nicht widerstehen können.$b$bNehmt diese Tasche mit Wasserelementararmschienen und findet heraus, ob sie in irgendeinem Zusammenhang mit dem Fluch des Steins stehen. Sucht vor allem nach dem Erzmagier Ansirem Runeweaver. Ich hatte schon zuvor mit ihm zu tun und er verfügt über unglaubliches Wissen.",objectives={"Bringt die Wasserelementararmschienen nach Dalaran zu Erzmagier Ansirem Runeweaver."}]])
R(603,"Ansirems Schlüssel",[[description="Der Magier, der im Besitz dieses Steins ist, verstärkt seine Macht durch ein Zentrum... eine Art Altar. Ihr solltet in der Lage sein, dies zu unterbrechen, indem Ihr es überwältigt.$b$bWie es der Zufall will, weiß ich auch genau womit: ein alter Dolch, ein weiteres Trollrelikt. Es gibt da nur ein... winzigkleines Problem.$b$bWisst Ihr, ich fand den Dolch auf einer Forschungsreise im Schlingendorntal, aber ich gab ihn meiner eigenwilligen Tochter, Catelyn, die mir nach Booty Bay weglief, um Piratin zu werden.",objectives={"Sprecht mit Catelyn in Booty Bay."}]])
R(604,"Die Blutsegelbukaniere",[[description="Crazz lobt Eure Hingabe an die Schwarzmeerräuber in hohen Tönen. Ich werde Euch mit einer Mission betrauen, die für die Flotte von höchster Bedeutsamkeit ist.$b$bBespitzelt den so genannten südlichen Kommandoposten, den die Blutsegelbukaniere an den wilden Ufern aufgebaut haben. Überfallt das Lager. Bringt mir ihre Karten zusammen mit ihren schriftlichen Befehlen. Wir werden ganz genau herausfinden, was dieser Abschaum so vorhat.",objectives={"Flottenmeister Seehorn in Booty Bay will, dass Ihr 10 Schwadroneure der Blutsegelbukaniere tötet und die Blutsegelkarten sowie die Blutsegelbefehle zurückbringt."}]])
R(605,"Singende blaue Splitter",[[description="Die singenden Kristalle gibt es nur im Schlingendorntal und sie sind für gewisse Gruppierungen äußerst wertvoll. Ich kann diese Kristalle bewegen, aber die verfluchte Venture Company macht es einem ehrlichen Unternehmer wie mir fast unmöglich, überhaupt welche zu sammeln.$B$BIch würde Euch gern anheuern.$B$BDie Basilisken des Schlingendorntals essen die Kristalle. Dadurch erhalten sie ihre harte Haut und manchmal können Kristalle von ordentlicher Qualität von den Häuten abgesammelt werden.$B$BIhr könnt sie von jedem Basilisken sammeln, aber die nicht ganz so bösartigen leben an der Küste südlich von Zul'Kunda, im Norden.",objectives={"Bringt 10 singende Kristallsplitter zu Crank Fizzlebub."}]])
R(606,"Zitterhand Angst einjagen",[[description="Wenn ich etwas nicht leiden kann, dann sind das Leute, die ihre Spielschulden nicht bezahlen! Und es gibt 'ne Menge Leute, die mir was schulden. Ob Ihr mir wohl beim Eintreiben helfen könnt?$B$BDa ist zuerst mal \"Zitterhand\" Phillipe unten bei den Docks. Er schuldet mir eine Menge nach dem Spiel letzte Woche und ich will mein Geld jetzt! Aber um da dranzukommen, müssen wir ihm gehörig Angst einjagen.$B$BVerlasst die Stadt und jagt alte Nebeltalgorillas. Sucht Euch ein paar nette Innereien heraus und bringt sie zu Zitterhand. Sagt ihm ja nicht, dass sie von einem Tier stammen, er soll ruhig das Schlimmste annehmen.",objectives={"Bringt 5 Nebeltalinnereien zu \"Zitterhand\" Phillipe nach Booty Bay."}]])
R(607,"Rückkehr zu MacKinley",[[description="Hier, nehmt diesen Beutel und gebt ihn Seewolf. Und sagt ihm, dass ich ihm alles zurückzahlen wollte! Ich schwöre!!$B$BIch hab nur ein bisschen viel getrunken und mich verlaufen, und... Ihr wisst ja, wie es so geht. Er wird es verstehen - Ihr müsst nicht erst grob werden!",objectives={"Bringt Zitterhands Bezahlung zu \"Seewolf\" MacKinley."}]])
R(608,"Die Blutsegelbukaniere",[[description="Dieser verdammte Firallon! Könnte kein Boot in einem Stück über den Kristallsee bringen, ganz zu schweigen eine ganze Flotte gegen uns führen.$b$bDie Blutsegelbukaniere werden für ihre Sorglosigkeit teuer bezahlen. Jetzt, da wir ihren Angriffsplan kennen, können wir unseren Gegenschlag starten, bevor sie überhaupt merken, was los ist.$b$bAber warum sollten wir die ganze Flotte schicken, wenn eine mutige Gruppe von Abenteurern das auch allein schaffen kann? $n, nehmt einige von Euren geschicktesten Kameraden zu Firallons Ankerplatz und tötet die Führungskräfte der Blutsegelbukaniere. Ihre Flotte wird bald danach sinken ...",objectives={"Flottenmeister Seehorn in Booty Bay will, dass Ihr Kapitän Stillwasser, Käpt'n Kielhol und Flottenmeister Firallon tötet."}]])
R(609,"Voodooschulden",[[description="Meine Liste wird kürzer, aber da sind immer noch Leute, die mir was schulden.$B$BAls Nächste haben wir da Maury \"Klumpfuß\" Wilkins, Jon-Jon die Krähe und Chucky \"Zehn Daumen\".$B$BDie Schulden dieser räudigen Hunde stehen schon seit Monaten aus und ich dachte schon, dass sie die Stadt verlassen hätten, nur um nicht zahlen zu müssen! Später hab ich gehört, dass sie jetzt verflucht und verhext sind und in den Dschungelruinen ihr Unwesen treiben. Aber ihr Schicksal ist mir ziemlich egal - ich will nur, was mir zusteht!$B$BSie halten sich in den Ruinen von Aboraz und den Ruinen von Jubuwal nordöstlich von hier auf. Sucht sie und holt das Geld.",objectives={"Bringt Maurys Klumpfuß, Jon-Jons goldenes Handfernrohr und Chuckys gewaltigen Ring zu \"Seewolf\" MacKinley in Booty Bay."}]])
R(610,"Schönling Duncan",[[description="Mein VATER hat Euch geschickt? Dachte, der alte Knacker hätte mich mittlerweile aufgegeben.$b$bEs war ja nicht unbedingt sein Fehler, dass ich weggerannt bin, er hätte einfach nicht erwarten dürfen, dass ich Lust auf ein langweiliges Leben hab, alte muffige Bücher lese und mich mit grauhaarigen, steifen, hochnäsigen Magiern abgebe!$b$bWenn Ihr meinen Dolch braucht, müsst Ihr ihn von \"Schönling\" Duncan wiederholen, einem der Blutsegelbukaniere. Rammt einfach was zwischen seine Schultern und er wird ihn sicherlich sofort rausrücken.",objectives={"Holt Catelyns Dolch von \"Schönling\" Duncan."}]])
R(611,"Der Fluch der Gezeiten",[[description="Ihr sucht also nach einer Art Altar? Nun, ich bin zwar kein Experte für Trollruinen wie mein Vater, aber ich habe von einer versunkenen Trollstadt nah bei der Insel gehört, die Ihr sucht. Vielleicht solltet Ihr dort mal suchen.$b$bIhr habt mein Messer für mich wiedergeholt, also könnt Ihr es Euch auch borgen... Ich will es aber wiederhaben, wenn Ihr fertig seid!",objectives={"Zerstört den Altar der Gezeiten mit Catelyns Klinge, tötet Gazban und bringt dann den Stein der Gezeiten sowie Catelyns Klinge zurück zu Baron Revilgaz."}]])
R(613,"Maurys Fuß aufbrechen",[[description="Verflucht noch eins! Dieser Blödmann Maury hat ein Schloss an seinem Fuß befestigt und ich kann es nicht öffnen! Seine Beute ist in dem Fuß, und das sind seine Schulden!$B$BWir müssen den Schlüssel finden, dann kriegen wir auch das Schloss auf. Maury hat mit den Ogern der Mosh'Ogg gespielt, in ihrem Hügel im Nordosten. Als er noch lebte, erzählte er mir, dass sie ihn das letzte Mal von dort verjagt hätten, weil er zu viel gewonnen habe. Vielleicht haben die Oger ja seinen Schlüssel.$B$BWenn sie ihn haben sollten, müsstet Ihr eine ganze Menge von ihnen beseitigen, bevor Ihr den richtigen findet.",objectives={"Bringt Maurys Schlüssel zu \"Seewolf\" MacKinley in Booty Bay."}]])
R(614,"Die Truhe des Kapitäns",[[description="Früher hab ich ein Schiff von hier bis ganz nach Ratchet, in Kalimdor gesegelt. Ich war ein erfolgreicher Kapitän mit einem einwandfreien Ruf.$B$BBis...$B$BDiese verfluchten Meeresriesen mich ruinierten! Sie haben mein Schiff zerschmettert, meine Crew umgebracht und mich in ein Rettungsboot nach Booty Bay gesteckt. Einer dieser Riesen, Gorlash, hat meine Kapitänstruhe gestohlen. Er sagte, er wolle sie als Schnupftabakdose. Diese Dreistigkeit!$B$BIch habe gehört, dass Gorlash an der Küste östlich von hier sein Unwesen treibt. Findet ihn und bringt mir meine Truhe zurück! Tut das, und Ihr habt Euch die Dankbarkeit eines Kapitäns verdient!",objectives={"Bringt Smotts' Truhe zu Hecklebury Smotts nach Booty Bay."}]])
R(615,"Der Entersäbel des Kapitäns",[[description="Nachdem ich mein Schiff an diese Riesen verlor, kaufte ich mir ein neues. Ich hab es SMOTTS' REVENGE genannt, Vorräte gekauft, eine Crew angeheuert und Segel gesetzt, um diese Schurken ausfindig zu machen. Ich habe sie auch gefunden, aber... sie haben mich besiegt. Sie haben die SMOTTS' REVENGE zerschmettert, meine zweite Crew umgebracht und mich in einem weiteren Rettungsboot ausgesetzt.$B$BDieses Mal hat ein anderer Riese, Negolash, meinen Entersäbel gestohlen.$B$BStellt Euch Negolash und bringt mir meinen Entersäbel!$B$BSprecht mit Knirpsens. Er war mein Smutje auf der SMOTTS' REVENGE und hat den letzten Angriff überlebt. Er kann Euch helfen, den Riesen zu finden.",objectives={"Sprecht mit Knirpsens."}]])
R(616,"Die Spukinsel",[[description="Für Baron Revilgaz höre ich mich immer nach Gerüchten von seltsamen und ungewöhnlichen Dingen in Booty Bay und im Schlingendorntal um. Normalerweise gebe ich ja nicht viel auf Geistergeschichten, aber ich habe ein paar Seeleute in der Taverne über eine Insel nahe der Küste reden hören, auf der es spuken soll. Sie erzählten von Wasserelementaren und einem rasenden Goblingeist.$b$bWenn Ihr mit Revilgaz sprechen solltet, erzählt Ihr ihm davon?",objectives={"Sprecht mit Baron Revilgaz in Booty Bay."}]])
R(617,"Bündelweise Akiris",[[description="Sucht'er Arbeit, $n? Hab vielleicht was für Euch, wenn'er Euch was traut.$B$BMein Freund Groy verdient sich dumm un' dämlich mit dem Verkauf von dem Zeuch, das die Naga Akirisschilfrohr nennen: is' so 'ne Art wertvolles Meeresschilfrohr. Bin nich' sicher, für was es gut is', aber er bezahlt gut für Bündel von dem Zeuch.$B$BWenn Ihr mir 10 Stängel von dem Zeuch bringt, sind wa im Geschäft. Die Naga wurden zuletzt am Strand nördlich von hier gesehen.",objectives={"Bringt 10 Stängel Akirisschilfrohr zu Freibeuter Bloads nach Booty Bay."}]])
R(618,"Negolash entgegentreten",[[description="Negolash ist ein hungriger Riese.$B$BAls die Riesen unser Schiff zerstörten, ging Negolash schnurstracks in meine Kombüse. Er hatte keinen Appetit auf die Crew wie die anderen Riesen. Negolash wollte Wein... und meine gegrillten Bussardflügel. Die sind meine Spezialität. Für das Rezept musste ich bis ins Ödland reisen!$B$BWenn Ihr den Riesen anlocken wollt, dann besorgt Euch etwas Wein und einen Haufen Bussardflügel. Legt sie in unser altes Rettungsboot, an der Küste südöstlich von hier. Sobald Negolash das Essen riecht, wird er bestimmt kommen!",objectives={"Bringt 10 gegrillte Bussardflügel und 5 Flaschen Dschungelrankenwein zu Käpt'n Smotts Rettungsboot.$B$BTötet Negolash und bringt Smotts' Entersäbel zu Captain Smotts ins Schlingendorntal."}]])
R(619,"Negolash anlocken")
R(620,"The Monogrammed Sash",[[description="This fine sash has the letters \"HS\" embroidered along its hem.",objectives={"Return the Monogrammed Sash to its owner."}]])
R(621,"Zanzils Geheimnis",[[description="Zanzil der Ausgestoßene hält sich mit seinen Anhängern in den Ruinen von Aboraz und Jubuwai auf, nordöstlich von Booty Bay. Sein Stamm hat ihn verbannt. Warum? Nun...$B$BZanzil hat eine Methode, den Geist von anderen zu beugen, und seine Anführer fürchten ihn. Er benutzt eine Mixtur von Dschungelpflanzen, die den Willen seiner Anhänger unterdrücken und ihre Körper stärken.$B$BSeine Mixtur könnte sehr wertvoll für diejenigen sein, die andere zu kontrollieren wünschen.$B$BBringt mir Proben seiner Mixtur und ich werde einen Nutzen für sie finden.",objectives={"Bringt 12 Proben von Zanzils Mixtur zu Crank Fizzlebub nach Booty Bay."}]])
R(622,"Rückkehr zu Corporal Kaleb",[[description="Während Ihr fort wart, habe ich den Topf, den Ihr mir brachtet, repariert. Ich habe sogar noch eine zusätzlich Dampfpfeife angebracht, und seht mal! Da ist ein neues Hackbeil am Boden, das kann Beinknochen durchtrennen.$B$BJa, ja, Krazeks Spezialtopf weiß, was Köche wünschen! Sein Besitzer wird bestimmt erfreut sein.",objectives={"Bringt Krazeks reparierten Topf zu Corporal Kaleb im Rebellenlager."}]])
R(623,"Bündelweise Akiris",[[description="Ach ja, $N, fein dass Ihr hier seid. Während Eurer Abwesenheit hab ich 'ne Nachricht von Groy gekricht. Er sachte, dass er mit der letzt'n Lieferung sehr zufrieden war und dass 'n Kunde von ihm noch mehr von dem Zeuch hab'n will und das sofort.$B$BIch fahr erst inner Woche wieder nach Theramore, aber wenner den Weg nich' scheut, dann könnter auch gleich das Zeuch für mich mitnehmen.$B$BAbenteuerlustich? Wissen tut er ja, wo die Marschen von Dustwallow sin', nich'? Ich wär aber vorsichtich, Theramore kann gefährlich sein, wenn man inne falschen Kreise kommt.",objectives={"Bringt ein Bündel Akirisschilfrohr zu Freibeuter Groy nach Theramore."}]])
R(624,"Cortellos Rätsel",[[description="Eine Brücke verziert und stark frequentiert$bUnter ihr werdet Ihr finden was Euch sehnlichst erwartet$bManche nennen es Hinweis andere Tipp$bEs liegt östlich der Schlucht der Totenwinde und südlich vom Rotkammgebirge$bFür unendliche Zeit genau dort wird es liegen$bIn den Sümpfen des Elends sich für immer wiegen$b",objectives={"Löst das Rätsel!"}]])
R(625,"Cortellos Rätsel",[[description="Im fernen Kalimdor wartet ein Land$bDie Hoffnung hielt dort den Gefahren nicht stand$bDas Wetter östlich des Brachlandes ist harsch$bDunkel und Tod droh'n in der Dustwallowmarsch$bDoch in einer Höhle, Richtung Südwest$bLiegt ein Hinweis für alle, die wagen den Test.",objectives={"Löst das Rätsel!"}]])
R(626,"Cortellos Rätsel",[[description="Nach Lordaeron! Schwerer Aufruhr dort wütet$bSoldatenmut wird mit dem Tode vergütet$bSucht Euren Weg durch den Aufstand dort$bund Eure Such' ist beendet an einem Ort$bAm Fuße der großen Fälle, entlang der Küste im Hinterland$bIm Wasser dort tief unten, nehmt Ihr Euren Schatz in die Hand!",objectives={"Löst das Rätsel!"}]])
R(627,"Gefallen für Krazek",[[description="Es gibt eine Berghöhle in der Schlucht der Trockenstoppel, weit im Norden des Arathihochlands. In dieser Höhle findet sich ein seltenes Erz: Blutstein. Der Blutstein in dieser Höhle ist zwar nicht von höchster Qualität, aber auch Blutstein von minderer Qualität ist wertvoll... für diejenigen, die wissen, wie er zu nutzen ist.$B$BIch hätte gerne etwas davon.$B$BIch werde Euren Spezialtopf reparieren, aber während ich daran arbeite, möchte ich, dass Ihr mir einige Blutsteinproben bringt. Bringt mir genügend und Ihr erhaltet einen Bonus.$B$BOh, und falls Ihr nicht wisst, wie man ihn abbaut... findet jemanden, der es kann!",objectives={"Bringt 4 Ladungen geringes Blutsteinerz zu Krazek nach Booty Bay."}]])
R(628,"Exzelsior",[[description="Die Innenseiten sind fertig gestellt, jetzt fehlt nur noch die äußere Schicht. Dafür verwende ich nur die besten Häute der alten Krokilisken. Sie sind widerstandsfähiger und eine bessere Leinwand - wenn Ihr es so nennen wollt - für die Muster und Akzente, die Drizzliks Exzelsiorlinie ausmachen.$b$bEs ist allerdings äußerst schwierig, diese vollkommene Haut zu finden; die Einzige, die meinen Plänen gerecht wird, ist die eines alten Salzwasserkrokilisken. Die Alten kommen nur heraus, um die anderen Salzwasserkroks zu verteidigen, also werdet Ihr wahrscheinlich einige töten müssen, um einen von der Sorte herauszulocken.",objectives={"Bringt die Haut eines alten Krokilisken zu Drizzlik nach Booty Bay."}]])
R(629,"Das finstere Riff",[[description="Vor langer Zeit, als ein großes Beben die Welt erschütterte, versank eine alte Trollstadt in den Wassern der ungezähmten Küste im Nordwesten. Wir nennen diesen Ort das finstere Riff, denn Murlocs bewohnen jetzt die Ruinen der Stadt und greifen jeden an, der sich ihnen nähert.$B$BIn diesen alten Ruinen liegt eine alte Schrifttafel, die die uralte Geschichte von Gri'lek erzählt, einem Helden der Trolllegenden. Diese Geschichte ist dem Darkspearstamm heilig und auch wenn die Tafel zu groß ist, um sie zu bewegen, so möchte ich doch einen Splitter davon, damit ich ihn in unserer neuen Heimat in Orgrimmar in einen Schrein legen kann.",objectives={"Bringt 1 Schrifttafel-Splitter zu Kin'weelay in das Basislager von Grom'gol."}]])
R(630,"Flaschenpost",[[description="$N, ich setze meine ganze Hoffnung in Euch und jeden, den Ihr gewinnen könnt, um mich zu befreien. Der große Blaumähnenkönig Mukla hat mich gefangen genommen. Er befehligt die Bestien dieser Insel und sie halten mich mit Hilfe dieser Kette gegen meinen Willen hier fest. Wenn Ihr ihn töten und den Schlüssel für diese Fessel finden könnt, stehe ich tief in Eurer Schuld.$B$BIch habe ihn oft auf der südöstlichen Seite der Insel gehört, aber bitte seid vorsichtig: Man darf ihn nicht unterschätzen.",objectives={"Erschlagt König Mukla und kehrt mit dem Schlüssel zu Prinzessin Poobah zurück, um sie zu befreien."}]])
R(631,"Der Thandol-Übergang",[[description="Eine enorme Explosion donnerte durch die Hügel hinweg. 's war furchtbar, sag ich Euch!$b$bGute Soldaten starben bei der Verteidigung des Thandol-Übergangs. Longbraid sagt, wir werden uns noch an den Dunkeleisenzwergen rächen.$b$bAber wir befinden uns in einer Welt voller Schmerz, und Verstärkung ist noch lange nicht in Sicht. Longbraid hat Ol' Rustlocke als Späher zur östlichen Brücke geschickt, um rauszufinden, ob wir sie sichern können.$b$bDas ist aber schon Tage her. Und jetzt, wo Dun Modr belagert wird, haben wir nicht genug Leute, um nach ihm zu suchen.$b$bVielleicht könnt Ihr ihn finden...",objectives={"Rhag Garmason will, dass Ihr Ol' Rustlocke findet."}]])
R(632,"Der Thandol-Übergang",[[description="Es sieht ganz so aus, als sei der arme Ol' Rustlocke in einen Hinterhalt der Dunkeleisenzwerge geraten. Ihr bemerkt ein Pergament neben seinen geballten Fäusten.$b$bErstattet Rhag Garmason Eure traurigen Neuigkeiten und zeigt ihm, was Ihr gefunden habt.",objectives={"Meldet Euch bei Rhag Garmason zurück und zeigt ihm das Pergament, das Ihr bei Rustlockes Leichnam gefunden habt."}]])
R(633,"Der Thandol-Übergang",[[description="Um Himmelswillen, nein! Armer Rustlocke. Das ist wirklich eine fürchterliche Tragödie.$b$bSein Tod darf nicht vergebens sein. Das Pergament, das Ihr entdeckt habt, zeigt an, dass Kam Deepfury, der hinter dem eigentlichen Angriff steckt, dafür gesorgt hat, dass ein Behälter mit Sprengstoff hinter dem Thandol-Übergang im Arathihochland versteckt wurde.$b$bWenn dieser Sprengstoff  zur Brücke gelangt, wird unsere Hauptversorgungsverbindung in den Norden gekapp! Der Behälter muss zerstört werden, $n! Kehrt zu mir zurück, wenn Ihr Eure Mission erfüllt habt.$b$bIhr seid unsere einzige Hoffnung.",objectives={"Zerstört den Sprengstoffbehälter"}]])
R(634,"Hilfegesuch an die Allianz",[[description="Ich bitte Euch noch um einen kleinen Gefallen, $C. Wir erwarten die Reserven von Ironforge. Roggo hat jedoch von einem Lager der Allianz im Norden des Arathihochlands bei der Zuflucht erfahren.$b$bReist dorthin und macht Captain Nials ausfindig. Fragt den guten Captain, ob die Allianz einige Soldaten erübrigen kann, die uns behilflich sein können, Dun Modr und den Thandol-Übergang zurückzuerobern.",objectives={"Macht Captain Nials bei der Zuflucht ausfindig."}]])
R(635,"Kristall in den Bergen",[[description="Dieser Splitter pulsiert während Ihr ihn haltet...$B$BIhr habt das Gefühl, als ob ein Bitten vom Splitter ausgeht, als ob jemand versucht, mit Euch zu kommunizieren, jemand, der verzweifelt Eure Hilfe sucht.$B$BVor Eurem inneren Auge erscheint eine Vision - die nördlichen Berge von Arathi und ein blitzender Kristall, der dort aus dem Boden ragt.$B$BIhr spürt, wie es Euch dorthin zieht.",objectives={"Findet den Kristall aus Eurer Vision."}]])
R(636,"Legends of the Earth",[[description="Dieses Buch erzählt die Geschichte einer Prinzessin der Elementare, Myzrael, und ihrer Gefangenschaft tief unterhalb des Arathihochlandes.$B$BEs erzählt auch von dem verborgenen Auftreten von Kristallen im Hochland. Diese Kristalle, die Splitter von Myzrael, sind Fenster zum Gefängnis der Prinzessin.$B$BWenn eine mutige Seele die Splitter von Myzrael fände, dann könnte $Ger:sie; vielleicht mit ihr sprechen...",objectives={"Findet die Splitter von Myzrael."}]])
R(637,"Sully Balloos Brief",[[description="Der durchnässte und zerrissene Umschlag löst sich in Euren Händen auf und Euch bleiben nur einige Seiten eines Briefes, der mit viel Mühe geschrieben wurde.$b$bDer Brief ist adressiert an eine Mrs. Sara Balloo in Ironforge und beginnt mit den Worten, \"Meine liebe Sara ...\".",objectives={"Bringt Sully Balloos Brief zu Sara Balloo."}]])
R(638,"Trollbane",[[description="Da Thoras Trollbane tot ist und Stromgarde in Schutt und Asche liegt, hat Vol'jin Anweisungen gegeben, dass wir alles tun sollen, um das legendäre Schwert Trol'kalar den menschlichen Händen zu entreißen, auf dass wir es in zukünftigen Kämpfen gegen die Trolle von Zul'Gurub nutzen können.$b$bZengu, einer unserer erfahrenen Jäger, wurde nach Hammerfall im Nordosten des Arathihochlands entsandt, um seine Beschaffung zu leiten.",objectives={"Reist nach Hammerfall im Arathihochland und sprecht mit Zengu."}]])
R(639,"Siegelzeichen von Strom",[[description="In den alten Zeiten kämpften Trolle gegen das Arathorianische Reich und unseren geschicktesten Feind, Lord Ignaeus von Strom, genannt Trollbane. Er ritt in die Schlacht und schwenkte dabei sein Schwert Trol'kalar - was in ihrer alten Sprache Trolltöter heißt.$b$bAber jetzt sind die Söhne von Trollbane geschwächt, ihre Festung ist dem Verfall preisgegeben.$b$bDas Schwert wird von mehreren Siegelzeichen beschützt, die unter den Überlebenden von Stromgarde verteilt wurden. Wir müssen sie alle bekommen.$b$bDas Erste wurde von dem Syndikat mitgenommen, einer ihrer Männer in Stromgarde sollte es haben.",objectives={"Holt das Siegelzeichen von Strom für Zengu in Hammerfall."}]])
R(640,"Das zerbrochene Siegelzeichen",[[description="Thoras Trollbanes Grabmal wird durch drei Siegelzeichen beschützt - das Erste davon habt Ihr dem Syndikat entwendet. Es wird allerdings schwieriger sein, an die anderen beiden heranzukommen, da sie sich bei der Miliz von Stromgarde befinden und diese sich gut verschanzt hat.$b$bDas Siegelzeichen von Thoradin wurde von Thoras' Sohn, Galen, in 11 Teile aufgeteilt und unter den Verteidigern von Stromgarde verteilt. Holt die Stücke und bringt sie zu Tor'gan, dem Trollschamanen, er kann sie wieder zum vollständigen Siegelzeichen binden.",objectives={"Holt die 11 Siegelzeichen-Fragmente von den Verteidigern in Stromgarde und bringt sie zu Tor'gan in Hammerfall."}]])
R(641,"Siegelzeichen des Thoradin",[[description="Die Rekonstruktion ließ sich problemlos durchführen. Das Siegelzeichen kann nun benutzt werden, um das Siegel auf Trollbanes Grabmal aufzuschließen. Bringt es zu Zengu, er hat ohne Zweifel weitere Aufgaben, die Ihr erfüllen müsst.",objectives={"Bringt das wiederhergestellte Siegelzeichen von Thoradin zu Zengu in Hammerfall."}]])
R(642,"Die gefangene Prinzessin",[[description="Mein Name ist Myzrael. Ich bin eine Prinzessin der Erde und meine Häscher, die Riesen, halten mich tief unterhalb des Arathihochlandes fest. Diese Kristallsplitter sind meine einzige Möglichkeit, mit der oberen Welt zu sprechen.$B$BBitte helft mir! Kobolde der Trockenstoppel, die Verbündete der Riesen sind, haben einen Splitter wie diesen hier in ihrer Schlucht im Osten. Um die Gruppe zu aktivieren, müsst Ihr die Körner von Myzrael von den Kobolden holen und sie an der Gruppe anwenden.$B$BIch flehe Euch an, $n, helft mir!",objectives={"Sammelt 12 Körner von Myzrael und bringt sie zu den regenbogenfarbenen Splittern in der Schlucht der Trockenstoppel."}]])
R(643,"Siegelzeichen von Arathor",[[description="Obwohl man kaum behaupten kann, dass sie Stromgarde kontrollieren, geschweige denn das gesamte Arathihochland, marschiert der menschliche Prinz trotzdem mit den Überbleibseln seiner Kavallerie durch das Land. Ich versteh ja nicht, warum er das tut, aber wer versteht schon, wie Menschen ticken, hm?$b$bWas auch immer seine Gründe sein mögen, er hat eines der Siegelzeichen Lieutenant Heldenruf, dem Anführer seiner Kavallerie übergeben. Findet ihn und bringt mir sein Siegelzeichen zurück.",objectives={"Holt das Siegelzeichen von Arathor und bringt es Zengu in Hammerfall."}]])
R(644,"Siegelzeichen von Trollbane",[[description="Das letzte Siegelzeichen, das benötigt wird, um das Siegel auf dem Grabmal von Thoras Trollbane zu öffnen, wird von seinem Sohn höchstpersönlich aufbewahrt. Er hält sich tief innerhalb Stromgardes auf, in einer Kapelle in den von der Miliz bewachten Distrikten. Prinz Galen wird gut bewacht und da er selbst ein ausgezeichneter Krieger ist, wird diese Aufgabe wahrscheinlich die schwierigste sein.",objectives={"Tötet Prinz Galen Trollbane und bringt das Siegelzeichen von Trollbane zu Zengu in Hammerfall."}]])
R(645,"Trol'kalar",[[description="Was ist das? Die vier Siegelzeichen haben sich zu einem Siegelzeichen zusammengefügt. Ohne Zweifel ist dieses in der Lage, die Schutzzeichen zu zerbrechen, die sich auf Trollbanes Grabmal befinden.$b$bTrollbanes sterbliche Überreste sind im Sanktum hinter der Kapelle in Stromgarde zur Ruhe gebettet worden. Holt Trol'kalar.",objectives={"Holt Trol'kalar aus Trollbanes Grabmal in Stromgarde."}]])
R(646,"Trol'kalar",[[description="Das Licht verglüht langsam, das Schwert Trol'kalar, das sich in einer steinernen Scheide befindet, ist freigegeben.",objectives={"Bringt Trol'kalar zu Zengu nach Hammerfall."}]])
R(647,"MacKreels Fusel",[[description="Was hab ich gestern gesoffen! Longbraid würde mich sofort köpfen, wenn er wüsste, dass ich während meiner Wache eingepennt bin.$b$bMein Schädel brummt vielleicht. Fühlt sich an, als wäre eine ganze Brigade von Belagerungsmaschinen drübergerollt, dieses Gerumpel.$b$bOh weh, so spät schon! Hab Braumeister Bilger in Southshore versprochen, dass ich meine Schulden mit ein wenig Fusel bei ihm bezahlen würde.$b$bUnd ich hab nur noch 15 Minuten! Könntet Ihr ihm diese Lieferung nicht bringen, bitte? Und beeilt Euch!",objectives={"Bringt MacKreels Fusel zu Braumeister Bilger nach Southshore."}]])
R(648,"Rettet OOX-17/TN!",[[description="Aus dem Roboter ertönt erneut die blecherne Stimme des Gnoms:$B$B\"Ich muss OOX-17/TN an einen offenen, sicheren Ort schaffen, wo er die langwierige Startprozedur beginnen kann. Er hat eine eingebaute Tarnvorrichtung, aber ich brauche etwas Zeit, um sie von hier aus wieder funktionstüchtig zu machen. Ihr müsst den Roboter von seinem derzeitigen Standort nach, sagen wir, Steamwheedle bringen! Das sollte der perfekte Ort für mein Vorhaben sein, und bis Ihr dort seid, sollte ich auch alles vorbereitet haben und online gehen können.\"$B$B\"Eskortiert ihn sicher bis zum Hafen und kommt dann zu mir nach Booty Bay! Oglethorpe Obnoticus - Ende!\"",objectives={"Eskortiert OOX-17/TN nach Steamwheedle und meldet Euch dann bei Oglethorpe Obnoticus in Booty Bay."}]])
R(649,"Bergung der Welle",[[description="Ich habe eine kleine Bergungsaktion für Euch, und falls Ihr ein Liebhaber von feiner Welle seid, so wie ich, dann werdet Ihr diese Aufgabe lieben. Welle!$B$BDas ist ein Getränk, Schafskopf.$B$BEin verlassener Außenposten der Horde verfügt über ein Lager mit Hinterland-Honigwelle aus der Zeit, als sie noch im Geschäft waren. Solch feine Welle bekommt Ihr sonst nirgendwo! Einer von Maltons Strohmännern weiß Bescheid, also begebt Ihr Euch dorthin und bringt mir eine Kiste verpackter Welle und zwei für meine eigene Sammlung! Sprecht mit Malton, er wird Euch die Einzelheiten mitteilen.",objectives={"Sprecht mit Malton Droffers in Orgrimmar."}]])
R(650,"Bergung der Welle",[[description="Der Elf, mit dem Ihr sprechen müsst, ist Gilveradin Sunchaser. Er erkennt jeden Wein, mit Jahrgang und allem, allein am Geruch! Er kann die Welle verpacken, die wir benötigen, daher müsst Ihr mit ihm sprechen. Sechs Flaschen müssen verpackt werden, zwei für meinen Vater, und so viele wie er selbst will... und glaubt mir, er wird welche wollen. Wenn Ihr die Welle verpackt habt und auch die zwei Flaschen für meinen Vater, dann kommt hierher zurück!$B$BGilveradins Lager befindet sich in der Nähe einer Hochelf-Lodge im Hinterland, und diese Hochelfen führen nichts Gutes im Schilde. Glaubt mir.",objectives={"Sprecht mit Gilveradin Sunchaser; sein Lager befindet sich im Hinterland."}]])
R(651,"Steine der Bindung",[[description="Vier Steine der Bindung sind in ganz Arathi verteilt. Diese Steine halten mich unter der Erde fest.$B$BUm sie zu öffnen, müsst Ihr den stärksten öffnen: den Stein der Inneren Bindung. Um das tun zu können, müsst Ihr Schlüssel von den drei Übrigen sammeln.$B$BDiese Steine werden von Wächtern bewacht, aber wenn Ihr es geschickt anstellt oder Glück habt, findet Ihr vielleicht einen Weg, sie auszuschalten.",objectives={"Holt den brennenden Schlüssel, den Wappenschlüssel und den donnernden Schlüssel vom Stein der westlichen Bindung, dem Stein der östlichen Bindung und dem Stein der äußeren Bindung."}]])
R(652,"Den Hauptstein zerbrechen",[[description="Das Öffnen der Steine der Bindung hat den Großteil meiner Fesseln gelöst, aber ein Schloss hält mich immer noch gefangen. Es ist der Hauptstein, den Ihr in diesem Kreis von Steinen sehen könnt. Und der Schlüssel wird von einem meiner Häscher bewahrt, dem Steinbehüter Fozruk.$B$BIhr müsst diesen Schlüssel, den die Steinbehüter die Rute der Ordnung nennen, von Fozruk in Besitz nehmen und mit ihm den Hauptstein öffnen.$B$B$n, Ihr habt schon so viel für mich getan. Nur noch eine kleine Hilfe... und meine Dankbarkeit wird die Erde in ihren Grundfesten erschüttern!",objectives={"Findet und tötet Fozruk. Bringt die Rute der Ordnung zum Hauptstein im Arathihochland."}]])
R(653,"Myzraels Verbündete",[[description="<Myzrael spricht.>$B$BFrei! ICH BIN FREI! Ich bin frei und kann meine Kräfte sammeln, verborgen vor denen, die mich gefangen nahmen. Denn wenn ich mich ihnen jetzt stellen müsste, würden sie mich sicherlich überwältigen und erneut einkerkern.$B$BAber bald werde ich mich den Riesen stellen und sie werden es bitter bereuen, mich als Gefangenen gehalten zu haben!$B$BIhr seid ein edelmütiger Verbündeter, $N. Ich werde Eure Hilfe bald wieder benötigen. Wenn ich bereit bin, müsst Ihr mich an die Oberfläche beschwören.$B$BSprecht mit Gerrig Bonegrip. Er befindet sich in Ironforge in einem Geschäft im düsteren Viertel. Er weiß, wie ich beschworen werden kann.",objectives={"Sprecht mit Gerrig Bonegrip im düsteren Viertel von Ironforge."}]])
R(654,"Tanaris-Feldproben",[[description="Nach Aktivierung der Kraftquelle beginnt das Feldtestset zu glühen und zu vibrieren. Es scheint, als würde es funktionieren wie geplant.$B$BLaut Chefingenieur Bilgewhizzle habt Ihr zwei Stunden Zeit, um die benötigten Daten in der Tanariswüste zu sammeln. Falls Ihr sie nicht innerhalb von zwei Stunden sammelt, gehen alle Daten verloren und Ihr müsst eine weitere Kraftquelle von ihm erstehen.$B$BKehrt zu ihm zurück, wenn Ihr Eure Aufgabe erfüllt habt.",objectives={"Sammelt akzeptable Proben von 8 Basilisken, 8 Hyänen und 8 Skorpionen. Bringt das Testset zurück nach Gadgetzan zu Chefingenieur Bilgewhizzle, bevor die Kraftquelle erschöpft ist."}]])
R(655,"Hammerfall",[[description="Ich erinnere mich, als wär es gestern gewesen... So viele Jahre ohne Hoffnung, mit Holz und Stahl, die mich an diesen fürchterlichen Ort banden. Und dann endlich, endlich! Da war der Kriegshäuptling. Doomhammer in seiner Mitternachtsrüstung, sein Kriegshammer hoch erhoben.$b$bEs war... zu schrecklich... Dass der Schlag eines Feiglings unseren größten Helden niederschlagen konnte. Er kam von hinten angestürmt auf seinem Pferd und dann rammte er seine Lanze einfach durch ihn hindurch... Ich fiel auf die Knie. Welche Hoffnung gab es noch? Welche Hoffnung gibt es noch...",objectives={"Sprecht mit Tor'gan in Hammerfall."}]])
R(656,"Beschwören der Prinzessin",[[description="Ihr müsst Myzrael besiegen, bevor ihre Kraft größer wird. Wenn Ihr es nicht tut, wird sie ihre Häscher herausfordern, sobald sie genug Stärke gesammelt hat! Einige glauben zwar, dass man sie kontrollieren könnte, aber wenn sie kontrolliert werden kann, warum haben die Riesen sie dann überhaupt in Fesseln gelegt?$B$BSeltsame Logik, nicht?$B$BUm sie zu besiegen, beschwört sie bei den Splittern von Myzrael, wo Ihr zuerst mit ihr spracht. Besiegt sie und sammelt ihre geisterhaften Fesseln ein. Bindet diese dann an die Splitter von Myzrael.$B$BTut das, und sie wird erneut gefangen sein.",objectives={"Geht zu den Splittern von Myzrael, beschwört und besiegt sie.$B$BSammelt ihre geisterhaften Fesseln, und bindet diese an die Splitter von Myzrael."}]])
R(657,"Hinweise auf eine neue Seuche?",[[description="<Quae beginnt, den Ordner durchzusehen.>$B$BDas IST interessant. Es scheint, als habe Apotheker Jorell an einigen tödlichen Experimenten hier in Go'Shek gearbeitet. Bin nicht sicher, was das mit Hillsbrad zu tun hat, aber Phin würde es nicht gefallen, wenn wir das einfach so laufen ließen.$B$BWährend Ihr fort wart, hatten wir ein Zusammentreffen mit ein paar Orcs und ich bin nicht in der geeigneten Verfassung, um Kinelory zu helfen. Wenn Ihr es vermögt ... Sie wird Schutz gut gebrauchen können, wenn sie zum Hof geht, um zu stehlen, was Jorell noch nicht nach Tarrens Mühle geschickt hat.",objectives={"Sprecht mit Kinelory."}]])
R(658,"Hinweise auf eine neue Seuche?",[[description="Phin hat Euch also geschickt, um nach uns zu sehen? Wundert mich nicht - er macht sich zu viele Sorgen.$B$BWir beobachten den Hof seit Tagen, und Kin sagt, es sei noch gar nicht so lange her, dass sie einen Kurier aus dem kleinen Haus da südlich hat kommen sehen.$B$BSie erzählt viel, aber ich kann ihrem Instinkt immer trauen, wenn wir uns auf gefährlichem Terrain befinden.$B$BIhr seid nicht zufällig ein geschickter Fährtenleser, oder? Wir glauben, dass der Kurier Notizen nach Tarrens Mühle bringen könnte. Wenn wir diese Dokumente in die Hände bekommen könnten, könnten wir vielleicht Näheres über die Vorgänge in Hillsbrad erfahren.",objectives={"Findet den Kurier der Verlassenen und bringt den versiegelten Ordner zu Quae in der Nähe von Go'Sheks Hof."}]])
R(659,"Hinweise auf eine neue Seuche?",[[description="Seid mir gegrüßt, $N. Ich bin der Anführer einer Abenteurergruppe, die die seltsamen Vorgänge in diesem Gebiet untersucht.$B$BMein Cousin in Hillsbrad musste letztens seinen Hund Stanley einschläfern lassen, weil das Tier seltsamerweise auf eine immense Größe heranwuchs und jeden bösartig angegriffen hat, der ihm näher kam.$B$BIch glaube, dass die Untoten darin verwickelt sind, und wir suchen nach Anzeichen, die das bestätigen.$B$BZwei meiner Kameraden, Quae und Kinelory, haben sich zur Go'Sheks Hof im Arathihochland aufgemacht und haben seit Tagen nichts von sich hören lassen. Könntet Ihr sie für mich finden? Ich mache mir langsam Sorgen.",objectives={"Findet Quae und Kinelory in der Nähe von Go'Sheks Hof im Arathihochland."}]])
R(660,"Hinweise auf eine neue Seuche?",[[description="Nun gut, $n. Bereit, wenn Ihr es seid.$B$BSollen wir?",objectives={"Beschützt Kinelory bis sie zu Quae zurückkehrt."}]])
R(661,"Hinweise auf eine neue Seuche?",[[description="Kinelory sah nach einer Nacht in der Taverne schon schlechter aus als jetzt. Ihr habt sie offensichtlich sehr gut beschützt.$B$BDiese Gegenstände, die sie von der Farm mitgebracht hat, sollten Phin zumindest einen Anhaltspunkt davon geben, was in Arathi so vor sich geht. Wir werden hier noch ein Weilchen bleiben, nur um sicherzugehen, dass nach Eurem Angriff kein Gegenschlag kommt. Wärt Ihr bereit, nach Southshore zurückzukehren und mit Phin zu sprechen?",objectives={"Findet Phin Odelic in Southshore."}]])
R(662,"Tiefsee-Bergung",[[description="O'Breen führte die Schiffe in die Bucht. Wir waren ziemlich sicher, dass der Schatz dort zu finden sei. Die HARBINGER konnte noch sicher andocken, aber als die TOLLE MINNA und die SILBERGEIST näher kamen, senkte sich der Meeresspiegel plötzlich ab. So was Seltsames hab ich mein Lebtag nich' gesehn!$b$bDiese beiden Schiffe sind auf irgendetwas aufgelaufen... eine Art Tempel im Riff. Sie sind irre schnell gesunken, eine echte Tragödie.$b$bWir müssen ihre Logbücher und auch ihre Karten wiederbekommen, bevor wir hier wieder weg sind. Wir dürfen diese Informationen nicht einfach für neugierige Augen zurücklassen.",objectives={"Der erste Maat Nilzlix will, dass Ihr die Karten und Logbücher von der TOLLEN MINNA und der SILBERGEIST zurückholt."}]])
R(663,"Land Ho!",[[description="Lolo sieht was Winziges, es ist ein $R! Immerzu Ausschau halten, ja, ja, das tut Lolo!$b$bWillkommen in der Faldirbucht. Kapitän O'Breen hat gesagt, dass wir nur für ein paar Stunden hier wären. Grad lang genug, um den Schatz einzusammeln und zurück nach Booty Bay zu segeln.$b$bAber Lolo denkt, dass wir noch sehr lange hier bleiben werden. Wir haben die anderen beiden Schiffe von unserer Formation verloren. Die arme SILBERGEIST und die arme TOLLE MINNA. Sie ruhen jetzt auf dem Grund des Meeres!$b$bLolo schlägt vor, dass Ihr mit Kapitän O'Breen sprecht, wenn Ihr länger hier bleiben wollt.",objectives={"Sprecht mit Kapitän O'Breen in der Faldirbucht."}]])
R(664,"Ertrunkene Trauer",[[description="Grr, 's ist ein elendes Leben. Ich sollte in meinem nassen Grab liegen und nicht hier am Feuer sitzen und frische Luft atmen.$b$bDie Crew hat ihr Bestes gegeben um meine wunderschöne Tolle Minna zu retten. Gesegnet seien die Jungs, gesegnet ihre Herzen.$b$bO'Breen hat es sicher ans Ufer geschafft, aber wir hatten nicht so viel Glück. Das Meer sank einfach auf uns herab, ich schwöre es!$b$bIn der einen Sekunde lagen wir auf dem Wasser und in der nächsten stürmte das Wasser auf uns ein. Und diese Bestien! Haben alle Überlebenden getötet. Elender Nagaabschaum. Mir gingen die Lichter aus und ich kam hier oben wieder zu mir, gerettet.$b$bIch will diese Biester tot sehen.",objectives={"Captain Steelgut in der Faldirbucht will, dass Ihr 10 Räuber der Säbelflossen und 3 Zauberhexerinnen der Säbelflossen tötet."}]])
R(665,"Versunkener Schatz",[[description="Da wir jetzt richtige Schwarzmeerräuber sind, ist es nun unsere Aufgabe, Herrn O'Breen bei der Suche nach dem verlorenen Elfenschatz behilflich zu sein.$b$bEs ist fast unmöglich, die Edelsteine ohne Hilfe im dunklen Meer zu finden. Der Doktor hat eine Schutzbrille konstruiert, die dabei hilft. Er muss die Schutzbrille mit der Energie aufladen, die von dem verzauberten Stein in der Höhle auf dem Hügel dort ausgeht.$b$bAber die Höhle ist verflucht! Sobald wir uns ihr nähern, werden wir überfallen. Wenn Ihr mich verteidigt, kann ich die Energie vom Stein in die Schutzbrille leiten.",objectives={"Begleitet Professor Phizzlethorpe zur Höhle und zurück."}]])
R(666,"Versunkener Schatz",[[description="Der Schatz befand sich so lange auf dem Meeresboden, dass die Edelsteine von einer dicken Kalkschicht umgeben sind. Aber die Macht, die in dieser Schutzbrille gefangen ist, wird Euch ermöglichen, sie leicht zu finden.$b$bEin wenig gnomischer Einfallsreichtum ist schon was Schönes!$b$bAlso nehmt Euch die Edelsteinjagdschutzbrille, $n, und versucht, ein wenig vom verlorenen Schatz für Kapitän O'Breen einzusammeln.$b$bIch würde ja selbst hinuntertauchen, aber... ähem... ich, nun ich muss mich um äußerst wichtige wissenschaftliche Dinge kümmern, oben auf dem sicheren, trockenen Land... ähem, ja.",objectives={"Doktor Draxlegauge in der Faldirbucht will, dass Ihr 10 Elfen-Edelsteine einsammelt und die Edelsteinjagdschutzbrille zurückgebt, sobald Ihr fertig seid."}]])
R(667,"Tod von unten",[[description="Das ist übel. Es scheint, als ob die Säbelflossen sich zum Angriff sammeln.$b$bNaga sind bekannt für ihre Ruchlosigkeit im Kampf. Sie werden so lange angreifen, bis ich tot bin.$b$bIch schätze mein eigenes Leben nicht höher als das meiner Crew, aber Ihr müsst helfen, mich zu verteidigen. Die Crew ist nicht in der Lage, ohne meine Kenntnisse des Meeres nach Booty Bay zurückzufinden.$b$bDie Naga werden vom Meer her kommen. Ihr müsst mit mir hier oben bleiben, um den Angriff abzuwehren. Bemannt die Kanone und treibt sie zurück.$b$bSeid Ihr bereit, $N?",objectives={"Beschützt Shakes O'Breen während des Angriffs."}]])
R(668,"Versunkener Schatz",[[description="Wir sollten Kapitän O'Breen nicht warten lassen. Er wird diese Edelsteine sofort sehen wollen. Darum sind wir ja schließlich hier!$b$bUnd nach ein paar Wochen Zusammenleben mit diesen Piraten sind der Professor und ich zum Schluss gekommen, dass es ganz und gar nicht gut für unsere Gesundheit ist, wenn sie denken, dass wir uns ihre Schätze einverleiben wollen.$b$bHier, $n, bringt das zu O'Breen.",objectives={"Bringt die Elfen-Edelsteine zu Kapitän O'Breen."}]])
R(669,"Versunkener Schatz",[[description="Flottenmeister Seehorn will über unseren Fund sofort informiert werden.$b$bAber, wie Ihr selbst sehen könnt, sind wir nicht unbedingt in der Lage, von hier wegzukommen. Es ist nicht nur der zu niedrige Wasserstand, sondern auch diese verdammten Viecher, die wir gestört haben, und die jetzt jede unserer Bewegungen aufs Genaueste beobachten.$b$bIhr könnt den Schwarzmeerräubern einen sehr großen Dienst erweisen, wenn Ihr Flottenmeister Seehorn in Booty Bay davon in Kenntnis setzen könntet, dass wir den Schatz gefunden haben und dabei sind, weitere Steine zu bergen. Bringt ihm diese Probe zum Beweis.",objectives={"Bringt die Probe zu Flottenmeister Seehorn nach Booty Bay."}]])
R(670,"Versunkener Schatz",[[description="Sagt, $n, Ihr seht aus wie jemand, der einem Abenteuer nicht abgeneigt ist. Meine Flotte liegt hier in Booty Bay fest, bis wir unsere Vorräte auffüllen können.$b$bHier und auch außerhalb braut sich so einiges zusammen und ich muss ein paar äußerst geheime Nachrichten an Shakes O'Breen übermitteln, der vor der Arathi-Küste festsitzt.$b$bKann ich auf Euch vertrauen, dass Ihr diese Nachricht sicher und unberührt überbringt?",objectives={"Bringt Seehorns Brief zu Kapitän O'Breen im Arathihochland."}]])
R(671,"Elende Magien",[[description="Ich fühlte etwas Fremdes in der Luft... ein Gefühl, das mein Blut köcheln lässt. Ich hatte auch schon einen Verdacht. Ich bin ausgezogen, um die Quelle meiner Unruhe aufzuspüren, und im Northfold-Anwesen im Westen fand ich restliche Spuren einer Dämonenbeschwörung. Als ich näher kam, begann mein Blut zu sieden und die Wut in mir wuchs.$b$bAuf dem Boden entdeckte ich ein Blutsteinamulett, das bei Dämonenbeschwörungen als Hilfe benutzt wird. Das Amulett, das ich fand, war jedoch entleert. Ich benötige ein weiteres, um es zu untersuchen, aber ich wage nicht, zum Anwesen zurückzukehren. Könnt Ihr mir ein paar bringen?",objectives={"Holt 10 Blutsteinamulette für Tor'gan in Hammerfall."}]])
R(672,"Mut machen",[[description="Wir haben versucht, es ihm gemütlich zu machen, ihn aufzumuntern, haben ihm Geschichten erzählt von unserer mächtigen Stadt in Orgrimmar in Kalimdor, aber nichts, gar nichts hat ihn berührt.$b$bGeschichten von unserem jungen Kriegshäuptling, Thrall, der die Rüstung und den Hammer von Orgrim trägt... aber vielleicht... Vielleicht! Eine kleine Demonstration von unserer neu gefundenen Schamanen-Magie könnte ihm neue Hoffnung geben. Einen Versuch ist es wert!$b$bEin kleines Objekt könnten wir für ihn machen, ja... Bringt mir ein paar Raptoraugen und ich werde sehen, was ich tun kann.",objectives={"Bringt 10 Hochlandraptorenaugen von Hochlandschreitern und Hochlandhauern zu Tor'gan in Hammerfall."}]])
R(673,"Elende Magien",[[description="Ich habe keinerlei Zweifel, dass ein mächtiger Hexenmeister sich innerhalb der Mauern Stromgardes aufhält. Von Zeit zu Zeit hat dieser Hexenmeister mit Hilfe eines arkanen magischen Relikts abscheuliche Dämonen in großer Zahl herbeibeschworen. Wir müssen ihm die Quelle seiner Energie nehmen.$b$bSucht den Hexenmeister und tötet ihn. Bringt mir alle magischen Objekte, die Ihr bei ihm finden könnt, und ich werde die geeigneten Schritte unternehmen, sie zu zerstören, damit ihre Macht nicht mehr dazu benutzt wird, dieses Land weiterhin zu besudeln.",objectives={"Bergt Marez Cowls Blutsteinkugel und bringt sie zu Tor'gan in Hammerfall."}]])
R(674,"Mut machen",[[description="Hier, übergebt dieses Amulett Gor'mul und beobachtet, ob die Kraft der Raptoren das Feuer des Kriegers, das einst in seinen Adern brannte, erneut erwecken kann.",objectives={"Gebt das Raptorkrallen-Amulett an Gor'mul."}]])
R(675,"Mut machen",[[description="<Gor'mul wirft das Amulett zu Boden.>$b$bTor'gans hat Euch geschickt, oder? Pah! Warum er mir gegenüber Gnade empfindet, geht über meinen Verstand. Gnade wurde mir verweigert, als es mir nicht vergönnt war, mit meinem Kriegshäuptling im Kampf zu sterben. Das Schicksal hat mir einen harten Schlag versetzt ...",objectives={"Sprecht mit Tor'gan."}]])
R(676,"Der Hammer kann fallen",[[description="Schwächlinge... alle miteinander. Ihr da, $C, was schaut Ihr so dämlich? Denkt wohl, Ihr seid was Besonderes, was? Wollt Ihr's nicht mal beweisen?$B$BDer Außenposten von Hammerfall in Arathi wird angegriffen. Wenn wir der Besatzung nicht bald Hilfe schicken, steht ihr Ableben unmittelbar bevor.$B$BAber bevor Ihr jetzt einfach losrennt, möchtet Ihr vielleicht Eure Fähigkeiten erst testen. Nordöstlich von Stromgarde in Arathi befindet sich ein Ogerhort, der von den Felsfaustogern bewohnt wird. Wenn Ihr die Oger und Vollstrecker dort in den Griff bekommt, erstattet Drum Fel in Hammerfall Bericht.",objectives={"Tötet 8 Oger der Felsfäuste und 10 Vollstrecker der Felsfäuste und sucht dann Drum Fel im Außenposten von Hammerfall im Arathihochland auf."}]])
R(677,"Zu den Waffen",[[description="Die Trolle der Witherbark und die Felsfaustoger von Arathi arbeiten zusammen daran, uns von diesem Land zu vertreiben, aber unser Schicksal liegt weder in ihren noch in irgendwessen anderen Händen. Wir werden sie erledigen und ihnen zeigen, dass dies auch unsere Heimat ist. $B$BDie Trolle haben sich von uns abgewandt, die Oger würden uns als Nahrung und Bettvorleger benutzen, wenn wir es zuließen - das darf nicht sein.$B$BWir werden unseren Angriff auf die Trolle der Witherbark südlich von hier beginnen. Erschlagt sie in Scharen und kehrt erst zurück, wenn ihre Lager dick mit Blut bedeckt sind.",objectives={"Erschlagt 10 Axtwerfer der Witherbark, 10 Kopfjäger und 8 Hexendoktoren und kehrt zu Drum Fel im Außenposten von Hammerfall zurück."}]])
R(678,"Zu den Waffen",[[description="Eure Kraft ist offensichtlich, $n. Dann zeigt mal, wie Ihr Euch mit echten Feinden schlagt.$B$BDie Felsfaustoger haben einen Unterschlupf südwestlich von hier, Richtung der Zwergenbrücke, und, wenn ich mich nicht täusche, werden die Raufer und Magi dort eine etwas größere Herausforderung darstellen - für uns waren sie das bislang zumindest.$B$BErschlagt so viele wie Ihr irgend könnt und kommt persönlich zu mir, wenn Ihr erfolgreich seid, oder erscheint mir als Geist, wenn Ihr versagt. Ich werde Eure Beharrlichkeit in der Schlacht in jedem Falle preisen.",objectives={"Tötet 10 Schläger der Felsfäuste und 4 Magi der Felsfäuste und sucht dann Drum Fel im Außenposten von Hammerfall auf."}]])
R(679,"Zu den Waffen",[[description="Der Kopf der Bestie kann abgetrennt werden... mit einem mächtigen Schlag, $n. Ihr habt alle Zeichen dafür gezeigt, dass Ihr in der Lage seid, uns mit diesem letzten mächtigen Schlag zu helfen. Die Anführer dieser Angriffe haben ihren Unterschlupf innerhalb der Ruinen von Stromgarde gewählt, einem grellen Symbol menschlicher Schwachheit.$B$BFindet und erschlagt diese Lords der Felsfäuste und ihre speichelleckenden Schamanen, die versuchen, uns aus diesem Land zu vertreiben.",objectives={"Tötet 15 Schamanen der Felsfäuste und 10 Lords der Felsfäuste und kehrt zu Drum Fel im Außenposten von Hammerfall im Arathihochland zurück."}]])
R(680,"Die echte Bedrohung",[[description="Ihr seid meinem Gemahl ein treuer Diener, $C, aber er weiß nicht, warum Hammerfall angegriffen wird.$B$BOr'Kalar, Mugh'thols Helfer in Stromgarde hasst meinen Gemahl aufs Äußerste, und er wünscht sich nichts mehr, als ihn tot zu sehen, da mein Gemahl ihn vor Jahren einmal besiegte.$B$BDie Vorzeichen verrieten mir, dass Or'Kalar eine Falle für meinen Gemahl ausgelegt hat. Aus diesem Grund habe ich Hinweise auf den Aufenthaltsort des Ogers vor ihm versteckt.$B$BMein Gemahl wird Hals über Kopf losschlagen, sobald er vom Aufenthaltsort des Ogers erfährt, und ich wollte Eure Hilfe bei der Tötung der Kreatur erbitten.",objectives={"Erschlagt Or'Kalar und bringt seinen Kopf zu Korin Fel in den Außenposten von Hammerfall."}]])
R(681,"Northfold-Anwesen",[[description="Wir kämpfen einen Kampf um Stromgarde, und wir verlieren ihn. Die Oger, das Syndikat und wir haben unsere einst große Stadt geteilt und jede Fraktion bekämpft die andere bis zu einem blutigen Unentschieden.$B$BAber unsere Streitkräfte schwinden, während unsere Feinde immer stärker werden.$B$BWir brauchen Hilfe aus der Stadt Southshore, aber Vorräte sind nur schwer zu bekommen, solange das Syndikat das Gebiet zwischen uns kontrolliert.$B$BBegebt Euch zum Syndikatsstützpunkt im Northfold-Anwesen und tötet sie alle. Dann wird der Druck auf unsere Versorgungszüge ein wenig nachlassen und ein größerer Teil wird durchkommen.",objectives={"Tötet 10 Straßenräuber des Syndikats und 6 Söldner des Syndikats.$B$BKehrt zu Captain Nials bei der Zuflucht zurück."}]])
R(682,"Abzeichen von Stromgarde",[[description="Das Syndikat in Stromgarde bekämpft das Kontingent unserer Miliz dort. Um diesen Pöbel dazu zu bringen, sich mit unseren disziplinierteren Streitkräften zu schlagen, haben die Syndikatsanführer ein Kopfgeld auf unsere Soldaten ausgesetzt und belohnen jedes Abzeichen von Stromgarde, das toten Milizleuten abgenommen wurde, mit Gold.$B$BWir wollen diese Abzeichen zurück - wir dürfen es diesen Halsabschneidern nicht erlauben, Trophäen von unseren mutigen Gefallenen zu rauben!$B$BBegebt Euch in das vom Syndikat kontrollierte Gebiet von Stromgarde und jagt ihnen unsere Abzeichen ab.",objectives={"Bringt Abzeichen von Stromgarde zu Captain Nials bei der Zuflucht."}]])
R(683,"Sara Balloos Hilfegesuch",[[description="$n, ich habe nur eine kleine Bitte an Euch.$b$bBringt diese Mitteilung, die ich vorbereitet habe, zu unserem großen Monarchen von Ironforge, König Magni Bronzebeard. Es ist fast lächerlich, diese kleine Aufgabe von Euch zu verlangen, von jemandem, der für die Sache der Allianz bislang eine so große Unterstützung war.$b$bAber in meinem von Trauer übermannten Zustand vor den König zu treten, wäre meinem Anliegen nicht im Geringsten dienlich. Das versteht Ihr sicher.",objectives={"Bringt Sara Balloos Notiz zu König Magni Bronzebeard von Ironforge."}]])
R(684,"GESUCHT: Marez Cowl",[[description="Es wurde ein Kopfgeld auf Marez Cowl ausgesetzt, einer hochrangigen Beraterin und Agentin des Syndikats. Sie wurde zuletzt in dem vom Syndikat kontrollierten Gebiet von Stromgarde gesehen.$B$BDas Kopfgeld kann von Captain Nials abgeholt werden.$B$BIch warne Euch: Marez ist eine geschickte und gerissene Hexenmeisterin und bekannt dafür, dass sie sich mit Dämonen abgibt. Bei ihrer Verfolgung ist äußerste Vorsicht geboten.",objectives={"Bringt Marez' Kopf zu Captain Nials bei der Zuflucht."}]])
R(685,"GESUCHT: Falkenstein und Otto",[[description="Die Miliz von Stromgarde hat Kopfgelder auf Lord Falkenstein und seine Leibwache Otto ausgesetzt. Falkenstein zeichnet für die Bemühungen des Syndikats im Arathihochland verantwortlich und sein Tod wäre eine erhebliche Störung dieser Bemühungen.$B$BSeine Leibwache Otto ist zwar kein strategisch wichtiges Ziel, aber er ist ein starker Gegner und hat Dutzende unserer Verteidiger auf dem Gewissen.$B$BIhre Kopfgelder können bei Captain Nials abgeholt werden.",objectives={"Bringt Ottos und Falkensteins Köpfe zu Captain Nials bei der Zuflucht."}]])
R(686,"Ehrerbietung von einem König",[[description="Ich erwarte nicht, dass Zwerge wie die gute Frau Balloo es verstehen, warum so ein Krieg für das größere Wohl unseres Volkes ertragen werden muss. Der Verlust ihres Gemahls und der Verlust jedes einzelnen Zwerges, der im Namen der Allianz kämpft, lastet schwer auf meiner Seele.$b$bAuch wenn ich nicht in der Lage bin, ihren Gemahl aus dem wirbelnden Nether zurückzuholen, so kann ich ihm doch meine Ehrerbietung erweisen. $b$bIch werde einen Gedenkstein für Sully Balloo bei Großsteinmetz Marblesten in Auftrag geben.$b$bBenachrichtigt ihn sofort, $C. Ihr werdet die Durchführung meines Auftrags beaufsichtigen.",objectives={"König Magni Bronzebeard will, dass Ihr mit Großsteinmetz Marblesten sprecht."}]])
R(687,"Theldurin der Verirrte",[[description="Theldurin der Verirrte war einst ein Mitglied unseres Ordens, dem Twilight-Hammer. Aber er wurde verrückt und hat unsere Lehren verdammt. Bevor er uns davonlief, hat er die Rolle von Myzrael gestohlen! Wir konnten ihn nicht einfangen, aber Gerüchte besagen, dass er sich im Ödland versteckt, sabbelnd und wahnsinnig.$B$BIhr müsst die Rolle finden, denn nur so könnt Ihr die Fürstin zu uns zurückbringen. Und dafür müsst Ihr Theldurin finden.",objectives={"Findet Theldurin den Verirrten."}]])
R(688,"Myzraels Verbündete",[[description="<Myzrael spricht.>$B$BFrei! ICH BIN FREI! Ich bin frei und kann meine Kräfte sammeln, verborgen vor denen, die mich gefangen nahmen. Denn wenn ich mich ihnen jetzt stellen müsste, würden sie mich sicherlich überwältigen und erneut einsperren.$B$BAber bald werde ich mich den Riesen stellen und sie werden es bitter bereuen, mich als Gefangene gehalten zu haben!$B$BIhr seid ein edelmütiger Verbündeter, $n. Ich werde Eure Hilfe bald wieder benötigen. Wenn ich bereit bin, werdet Ihr mich an die Oberfläche beschwören müssen.$B$BSprecht mit Zaruk in Hammerfall. Er weiß, wie ich beschworen werden kann.",objectives={"Sprecht mit Zaruk in Hammerfall."}]])
R(689,"Ehrerbietung von einem König",[[description="Unser guter König will also, dass wir einen Gedenkstein zu Ehren eines Soldaten mit Namen Sully Balloo errichten? Und Ihr sagt, dass der arme Kerl bei der Tragödie am Thandol-Übergang gestorben sei?$b$bBah, wird denn jemals Frieden auf Azeroth herrschen?$b$bWie dem auch sei, ein Auftrag vom König hat die allerhöchste Priorität. Und um ein wahrhaft episches und bleibendes Werk zu schaffen, will ich mit dem besten Stein arbeiten, der verfügbar ist. Begebt Euch nach Darrow Hill in Hillsbrad und besorgt mir etwas Alteracgranit.",objectives={"Großsteinmetz Marblesten aus Ironforge will 5 Stücke Alteracgranit."}]])
R(690,"Malins Gesuch",[[description="Seid gegrüßt, $N. Ihr seht aus wie ein Abenteurer und ich habe eine Aufgabe, die erledigt werden muss.$B$BErzmagus Trelane, mein früherer Meister, ist vor nicht allzu langer Zeit aus Stromgarde im Arathihochland geflohen und er hat mich gebeten, bei der Wiederbeschaffung einiger Gegenstände, die er zurückließ, behilflich zu sein.$B$BDie Stadt wird belagert und er hat versucht, den Turm von Arathor zu verteidigen, aber ohne Erfolg. Ich habe bereits Agenten im Hochland, aber sie haben mich gebeten, weitere Hilfe zu schicken. Seid Ihr interessiert?",objectives={"Sucht Skuerto bei der Zuflucht im Arathihochland auf."}]])
R(691,"Das Gewicht in Gold wert",[[description="Erzmagier Malin schickte Skuerto und mich hierher, um für ihn ein paar Reagenzien zu besorgen. Ich hatte keine Ahnung, wie ich die Gegenstände beschaffen sollte, aber da Ihr jetzt hier seid, hat sich mein Problem wohl gelöst.$B$BIch brauche Folgendes: Hauer der Witherbark, Medizinbeutel der Witherbark und ein Schattenjägermesser.$B$BKönntet Ihr mir das besorgen? Die Witherbark leben südöstlich von Arathi.",objectives={"Sucht für Lehrling Kryten bei der Zuflucht 10 Hauer der Witherbark, 4 Medizinbeutel der Witherbark und 1 Schattenjägermesser."}]])
R(692,"Die verlorenen Fragmente",[[description="Die Rolle von Myzrael... die Rolle von Myzrael?! Die wollt Ihr doch wohl nicht haben! Ihre Magie kann Myzrael an die Oberwelt locken, und wenn Ihr das tut, sind wir alle in Gefahr!$B$BOder... vielleicht ist es schon zu spät. Vielleicht ist sie schon frei. Vielleicht sammelt sie nur ihre Kraft, bevor sie sich auf uns stürzt. Wenn es so ist, BRAUCHT Ihr die Rolle!$B$BZu dumm, dass sie zerstört wurde. Wütende Elementare haben sie gestohlen und kämpfen jetzt um die Fragmente.$B$BWenn Ihr diese Fragmente jedoch sammeln könntet, können wir sie vielleicht wieder zusammensetzen...",objectives={"Bringt Theldurin dem Verirrten das zerrissene Rollenfragment, das zerknüllte Rollenfragment und das angesengte Rollenfragment."}]])
R(693,"Zauberstab gegen Faust",[[description="He, $N. Tut mir Leid, dass ich früher Euch gegenüber so kurz angebunden war... und nein, das sollte jetzt kein Wortspiel sein.$B$BIch habe herausgefunden, wo Trelanes erster Gegenstand gelandet ist: Kor'gresh in der Halle der Felsfäuste hat ihn. Und so wie er seinen Leuten die Hölle heiß gemacht hat, damit sie nicht aus der Reihe tanzen, muss er wohl kurz davor sein herauszufinden, wie man seine gesamte Macht nutzen kann.$B$BDie Halle der Felsfäuste liegt südlich von hier und östlich vom Thandol-Übergang. Findet diesen Oger und holt den Zauberstab.$B$BWährend Ihr weg seid, werde ich versuchen herauszufinden, was wir wegen Stromgarde unternehmen können.",objectives={"Sucht Trelanes Zauberstab der Herbeirufung und bringt ihn Skuerto bei der Zuflucht."}]])
R(694,"Trelanes Verteidigung",[[description="Na, erholt?$B$BDas hier ist der nächste Schritt: Um den Turm von Arathor in Stromgarde herum wimmelt es nur so von Ogern. Wir müssen die Verteidigungsanlagen des Turms aktivieren, wenn wir eine Chance gegen sie haben und es lebend zu den Gegenständen schaffen wollen. Dazu brauchen wir ein paar Edelsteine, an denen die Schamanen der Felsfäuste Gefallen gefunden haben. Sie nahmen die aus dem Turm, aber sie werden nicht mehr lang in ihrem Besitz bleiben.$B$BHolt einen dieser Edelsteine und bringt ihn Kryten - er kennt den Zauber, mit dem man sie verzaubern kann, sodass sie wie ein Schlüssel funktionieren.",objectives={"Sucht einen azurblauen Achat und bringt ihn Lehrling Kryten bei der Zuflucht."}]])
R(695,"Des Lehrlings Verzauberung",[[description="Bitte sehr, $N. Der Edelstein muss nur gegen einen der Sockel nahe dem Fuß des Turms gepresst werden, um dessen Verteidigung zu aktivieren. Benutzt ihn, wenn Ihr bereit seid, den Turm zu betreten und nach den restlichen Gegenständen Trelanes zu suchen. $B$BViel Glück. Ich warte hier im Lager auf Eure Rückkehr. Oh, und sprecht mit Skuerto, bevor Ihr geht. Er gibt Euch die restlichen Details, die Ihr braucht.",objectives={"Sprecht mit Skuerto."}]])
R(696,"Angriff auf den Turm",[[description="Danach müsst Ihr suchen: Trelanes Phylakterium, Trelanes Kugel, Trelanes Glutachat.$B$BAlle drei Dinge sollten sich innerhalb des Turms in Truhen befinden und es sollte Euch keine Schwierigkeiten bereiten, diese Truhen selbst zu öffnen; Ihr müsst Euch nur vor den Ogern in Acht nehmen.$B$BDie Verteidigungen des Turms kümmern sich nicht selbstständig um die Oger, Ihr müsst Eure Waffen jederzeit griffbereit haben. Wenn diese Oger herausfinden, dass Ihr dort seid, um sie zu bestehlen, werden sie Euch in die Mangel nehmen.$B$BSeid vorsichtig - und viel Glück.",objectives={"Sucht Trelanes Phylakterium, Trelanes Kugel und Trelanes Glutachat und bringt ihn Skuerto bei der Zuflucht."}]])
R(697,"Malins Gesuch",[[description="Bringt diesen Brief nach Stormwind und lasst Malin wissen, dass Kryten und ich bald wieder zu Hause sind. Ich zweifle nicht daran, dass er Euch reichlich für Eure Hilfe uns gegenüber belohnen wird, $N.$B$BSichere Reise.",objectives={"Bringt dem Erzmagier Malin im Magierviertel von Stormwind den versiegelten Brief."}]])
R(698,"Mangelnde Reserven",[[description="Ich versuche, einige Vorräte für unseren Außenposten in der Nähe des Strandes im Osten zusammenzutragen - Tok'Kar tut, was er kann, aber neben dem Dienst als Wache und Kochen für seine Soldaten ist nicht mehr viel Zeit übrig vom Tag.$B$BWann immer sie können, kochen sie dort mit Begeisterung Sägezahnfleisch, aber ich hatte einfach keine Zeit, ihnen eine neue Ladung rüberzuschicken. Würdet Ihr mir da aushelfen?$B$BDie jungen Sägezähne sind nicht so schmackhaft wie die älteren, macht also einen Bogen um sie; gebt ihnen ein oder zwei Jahre, um zur vollen Größe heranzuwachsen.",objectives={"Bringt Tok'Kar in den Sümpfen des Elends 8 Stück unverarbeitete Sägezahnflanken."}]])
R(699,"Mangelnde Reserven",[[description="Man hat uns wegen der Murlocplage entlang der Küste hier stationiert, um andere vor Gefahren jeglicher Art, die Stonard bedrohen könnten, zu beschützen - oder zu warnen, falls deren Streitkräfte zu groß werden. Das gibt uns nicht viel Zeit, um auszuruhen, und wir könnten weitere Hilfe Eurerseits gebrauchen, wenn Ihr gewillt seid.$B$BDie Sägezahnschnapperklauen geben erstklassige Waffen ab, wenn sie richtig vorbereitet werden. Bringt mir ein paar ihrer Klauen, dann werde ich zusehen, dass Ihr eine unserer Waffen als Dank für das Frischfleisch und die angenehme Gesellschaft bekommt.",objectives={"Bringt Tok'Kar in den Sümpfen des Elends 6 Sägezahnschnapperklauen."}]])
R(700,"Ehrerbietung von einem König",[[description="Ah, welch edle Steine doch aus Lordaeron kommen. Was für eine Schande, dass in diesem Land ein solches Chaos herrscht.$b$bAber der Gedenkstein ist sehr schön geworden! Ich glaube, der König wird damit sehr zufrieden sein.$b$bWürdet Ihr so gütig sein und Seiner Majestät eine Nachricht senden, dass der Gedenkstein wie gefordert fertig gestellt wurde?",objectives={"Erstattet Meldung an König Magni Bronzebeard."}]])
R(701,"Arglist des Raptors",[[description="Mit ein paar weiteren Dingen kann ich einen Gegenstand schaffen, der Gor'mul mit der Magie der Arglist des Raptors erfüllt! Wenn ihn die Macht des Raptors durchströmt, wird Gor'mul unsere neue Macht erkennen und den Krieger neu entdecken, der in ihm schlummert!$b$bUm den Gegenstand und den Zauber zu schaffen, werden Raptorherzen benötigt.",objectives={"Besorgt für Tor'gan 12 Raptorherzen von Hochlandfleischpirschern."}]])
R(702,"Arglist des Raptors",[[description="Nehmt diese Kugel und nutzt ihre Energie, um Gor'mul die Essenz des Raptors zu spenden. Sie wird seinen Geist erfrischen und ihm einen neuen Lebensinhalt geben. Sobald er wieder normal ist, können wir ihn über die aktuelle Situation der Horde informieren und wir werden einen großen Krieger bei unseren unaufhörlichen Kämpfen an unserer Seite haben.",objectives={"Gebt Gor'mul Tor'gans Kugel."}]])
R(703,"Gegrillte Bussardflügel",[[description="Oh ja, meine gegrillten Bussardflügel sind ein Renner! Die Sauce ist gehaltvoll und das Fleisch würzig. Und der Duft lockt alle hungrigen Mäuler in einem Umkreis von Meilen an!$B$BIch habe alles, was ich brauche, um eine Menge zu kochen. Alles... außer Bussardflügel!$B$BWenn Ihr etwas davon haben möchtet, besorgt mir Bussardflügel. Bringt Ihr mir genügend davon, gebe ich Euch vielleicht sogar das Rezept dafür!",objectives={"Bringt Rigglefuzz 4 Bussardflügel."}]])
R(704,"Agmonds Schicksal",[[description="Der letzte Bericht, den ich von Agmond erhalten habe, ist sehr beunruhigend, umso mehr, da er jetzt tot ist! Er erwähnte, dass seine Buddler an der Grabungsstätte vor Uldaman \"uralte Urnen\" entdeckt hätten. Ich fürchte, dass die dort gefundenen Urnen die Troggs erzürnt haben, ebenso wie die Götzen, die ich dort fand.$B$BIch möchte, dass Ihr uns die Urnen bringt, damit wir sie untersuchen können. Geht zur Grabungsstätte Uldaman, sammelt die Urnen ein und kehrt dann zu mir zurück.",objectives={"Bringt Ausgrabungsleiter Ironband am Loch Modan 4 verzierte Steinurnen."}]])
R(705,"Perlentauchen",[[description="Das Ödland ist eine unwirtliche Gegend voller heimtückischer Raubtiere und dreister Aasfresser. Unheimlich, besonders für einen so kleinen Goblin. Ich muss gewitzt sein, wenn ich überleben möchte!$B$BIch kenne das Rezept für Blitzstrahlbomben. Die benutze ich, um wilde Tiere zu verjagen. Leider geht mir langsam eine der Zutaten aus: zu Pulver zermahlene blaue Perlen. Bringt mir welche, dann soll es Euer Schaden nicht sein.$B$BHe, und ich hoffe, Ihr habt gute Stiefel an. Die blauen Perlen, die ich brauche, stammen von Muscheln am finsteren Riff.$B$BGenau, dem finsteren Riff im Schlingendorntal!",objectives={"Bringt Rigglefuzz im Ödland 9 blaue Perlen."}]])
R(706,"Feuerverzauberungen",[[description="Als Lehrling Feranor Steeltoes habe ich seine Spezialtechnik erlernt, wie man feurige Verzauberungen auf Waffen wirkt. Als ich das letzte Mal von ihm hörte, arbeitete er mit einer Jägergruppe in einer Schmiede, oben in Lordaeron.$b$bIch kann Euch nicht viel darüber sagen, an was genau er dort arbeitete, nur dass dazu Blut eines noch schlagenden Herzens eines seltenen Schwarzdrachen-Welpen nötig ist. Ohne Neuigkeiten aus Ironforge habe ich nicht viel zu tun. Wenn Ihr mir ein Herz eines Welpen aus der Lethlorklamm bringt, zeige ich Euch meine Fertigkeiten!",objectives={"Besorgt Sigrun Ironhew ein Schwarzdrachenherz."}]])
R(707,"Ironband sucht Euch!",[[description="$N. Ich habe Berichte von Ausgrabungsleiter Ironband von der Ausgrabungsstätte am Loch Modan erhalten - er braucht jemanden, der ihm die Rennerei auf einer unserer anderen Ausgrabungen abnimmt.$B$BIch habe keine weiteren Details, aber wenn Ihr Euch ein bisschen die Füße vertreten wollt, dann sprecht mit Ironband.",objectives={"Sprecht auf Ironbands Ausgrabungsstätte am Loch Modan mit Ausgrabungsleiter Ironband."}]])
R(708,"Der Flugschreiber",[[description="Die Oberfläche dieses metallenen Flugschreibers ist stark angegriffen, so, als hätte man ihn in Säure getaucht... er muss lange im Magen des Riesenkondors gelegen haben.$B$BIhr dreht die Kiste um und entdeckt ein Symbol, das in den Boden eingeprägt ist. Unter dem Symbol stehen folgende Wörter:$B$B\"Motor Nr. 19 - Belagerungsbrigade von Eisenschmiede\"",objectives={"Bringt den zerfressenen Flugschreiber in die Halle der Waffen in Eisenschmiede."}]])
R(709,"Lösung der Verdammnis",[[description="Oh je! Oh je! Unheil naht! Hört auf mich! Unheil!$B$BNein, ich darf nicht darüber sprechen... darf nicht ihre Namen aussprechen, sie könnten mich hören! Aber wenn wir mehr über sie lernen, ja, mehr... dann könnten wir vielleicht lernen, wie man sie aufhalten kann!$B$BVielleicht.$B$BGeht nach Uldaman. Nein! Ich hab's gesagt! Ihr müsst... die Schrifttafel von... Ryun'eh finden. Ja, findet sie! Und bringt mich nicht dazu, diesen Namen noch einmal auszusprechen!$B$BSie ist verborgen an diesem Ort, in einer uralten Truhe. Da ist sie versteckt... in einer Truhe, die gefertigt wurde, lang bevor Zwerge solche Werke vollbrachten.",objectives={"Bringt Theldurin dem Verirrten die Schrifttafel von Ryun'eh."}]])
R(710,"Element-Studie: Fels",[[description="Ich habe die Arbeit an meinem neuesten Projekt hier im Ödland erst mal eingestellt: meine Fesseln der Elementarbindung.$B$BWenn sie vollendet sind, werden Magier noch mächtigere Elementare beschwören und sie in noch größerer Zahl nutzen können. Ich brauche zunächst kleine Felssplitter, um einige meiner neuesten Angriffszauber und ein paar der Dingsdas zu testen, die ich zusammengebastelt habe.$B$BDie Splitter kann man leicht von den kleinen Felselementaren westlich von hier sammeln. Würdet Ihr mir ein paar bringen?",objectives={"Sucht 10 kleine Felssplitter und bringt sie Lotwil Veriatus im Ödland."}]])
R(711,"Element-Studie: Fels",[[description="Ihr habt Euch als fähiger erwiesen als all meine Lehrlinge zusammen, $n.$B$BFür die nächsten Aktionen ist etwas mehr Krafteinsatz erforderlich. Wenn Ihr vorsichtig genug seid, könnt Ihr bei Felselementaren große Steinplatten finden. Ihre Körper sind kräftiger und größer und deshalb kommt man bei ihnen eher an Teile heran, die groß genug für meine Tests sind. Ihr findet sie weiter westlich von hier oder südöstlich entlang des Gebirgsrandes.$B$BLasst Euch Zeit, ich brauche eine Weile, um diese kleineren Stücke zu testen, die Ihr mir gebracht habt.",objectives={"Bringt Lotwil Veriatus im Ödland 3 große Steinplatten."}]])
R(712,"Element-Studie: Fels",[[description="$n, ich brauche noch ein weiteres Teil von den Elementaren hier im Ödland: die Armschienen der Steinbindung von den großen Felselementaren. Meinen Berechnungen nach sollten diese Armschienen ausreichen, um die Kraft meiner Fesseln zu beurteilen.$B$BBei meinen Wahrsageversuchen über die großen Felselementare sah ich eine Gruppe von ihnen südwestlich von hier, in der Nähe von ein paar Ogern, wenn ich mich recht erinnere.$B$BBringt mir 5 ihrer Armschienen, damit ich ein paar in Reserve habe. Servo ist berüchtigt dafür, meine Reagenzien und Forschungen zu verlegen.",objectives={"Bringt Lotwil Veriatus im Ödland 5 Armschienen der Steinbindung."}]])
R(713,"Kühlaufsätze setzen sich durch",[[description="Lasst mich Euch etwas über Frostöl erzählen: Nichts kann einen Motor oder ein Getriebe besser vor Überhitzung schützen.$B$BSeine Kühleigenschaften sind außerordentlich und seine Langlebigkeit als Schmiermittel ist ohnegleichen. Aber das ist nicht alles: Es trägt auch dazu bei, die Verzauberung magischer Gegenstände zu erhalten.$B$BIch brauche eine Phiole davon, um die magische Kapazität meiner Fesseln zu erhöhen und sie mächtig genug zu machen, um unseren beschworenen Freund davon abzuhalten, uns alle umzubringen.$B$BBro'kin, einer meiner Goblin-Freunde, kann Euch lehren, wie man es herstellt. Er wohnt in Alterac.",objectives={"Sucht Frostöl und bringt es Lotwil Veriatus im Ödland."}]])
R(714,"Gyro... Was?",[[description="Ihr habt Eure Arbeit überdurchschnittlich gut gemacht, $n.$B$B<Lotwil ist offensichtlich durch seine Arbeit abgelenkt.>$B$BFalls wir uns in Kharanos jemals wiedersehen, scheut Euch nicht, zu mir zu kommen und nach Arbeit zu fragen.$B$BUpps! Schnell, nehmt das... ja, das da. Danke.$B$BJetzt brauche ich nur noch eines. Es ist ein kleines Teil, aber leider ziemlich ausschlaggebend: ein Gyrochronatom.$B$BWenn Ihr irgendwo einen auftreiben und mir bringen würdet, könnte ich das hier fertig stellen.",objectives={"Bringt Lotwil Veriatus im Ödland einen Gyrochronatom."}]])
R(715,"Flüssigstein",[[description="Ich glaube, die Gegenstände, die Ihr Lotwil besorgt habt, werden unsere geringste Sorge sein, $n. Andererseits habt Ihr Euch in den Wissenschaften, die Lotwil so heilig sind, mehr als talentiert gezeigt; also wie wäre es, wenn Ihr jetzt mir ein bisschen helft?$B$BIch brauche einen Unsichtbarkeitstrank und einen Heiltrank; beides könnte sich als nützlich erweisen, sobald er erst mit seinem Ding angefangen hat.$B$BDafür gebe ich Euch dieses Rezept für einen Trank, den ich entwickelt habe, als ich noch bei Lotwil in die Lehre ging. Er basiert auf einigen der Forschungen, die er hier im Ödland durchführte.",objectives={"Bringt Lucien Tosselwrench im Ödland einen Heiltrank und einen geringen Unsichtbarkeitstrank."}]])
R(716,"Stein ist besser als Stoff",[[description="Ich weiß, wie knickerig Lotwil sein kann, $n, also lasst mich etwas als Belohnung für all Eure Mühen fertigen. Vielleicht kann es Euch sogar vor der Scheußlichkeit schützen, die Lotwil gerade erfindet.$B$BIch habe alle zusätzlichen Steine verarbeitet, die Ihr für ihn gesammelt hattet, und kann Euch ein paar hübsche Armschienen machen, die Ihr möglicherweise gebrauchen könnt. Sie sind natürlich verzaubert.$B$BIch brauche nur noch gemusterte bronzene Armschienen, die ein Schmied hergestellt hat, um die fertig zu stellen, die ich für Euch mache.",objectives={"Bringt Lucien Tosselwrench im Ödland einige gemusterte bronzene Armschienen."}]])
R(717,"Erdbeben",[[description="Es ist offensichtlich, dass wir nicht mehr gewährleisten können, Schattenbringer und Hematus noch länger in Lethlor festzuhalten. Die schwarzen Großdrachen haben sich dort niedergelassen, und dass es den Ogern gelungen ist, das Zeichen zu stehlen, weist darauf hin, dass drastischere Maßnahmen ergriffen werden müssen.$b$bDas Gefängnis der Drachen wird von drei Runensteinen gebildet, die man nur mit Hilfe des Zeichens der Erde wegnehmen kann. Diese Runensteine können dann dazu verwendet werden, das Siegel zu zerbrechen, das sie gefangen hält.$b$b$N... sorgt dafür, dass sie süß träumen... für immer.",objectives={"Benutzt das Zeichen der Erde, um die Amethyst-, Opal- und Diamantsäulen zu aktivieren und die Runensteine zu holen.$b$bLegt die Runensteine auf das Siegel der Erde, um Schattenbringer und Hematus zu befreien.$b$bTötet sie und bringt dann Garek Schattenbringers Bindung, Hematus' Ketten und das Zeichen der Erde."}]])
R(718,"Illusionen",[[description="Wir hatten es so eilig, die Ausgrabungsstätte von Uldaman zu verlassen, dass wir uns gezwungen sahen, unterwegs viele Wagen und Nachschubkisten zurückzulassen. Die Oger von Camp Kosh haben sich auf unsere zurückgelassene Ausrüstung gestürzt wie Geier auf faulende Kadaver. Riechen auch nicht besser. Als die Kadaver, meine ich.$b$bWie dem auch sei, sie haben sich den Wagen mit unseren Waffen und anderem Zeug geschnappt und deshalb - tja, es ist ein bisschen peinlich - konnten wir uns nichts zum Essen beschaffen.$b$bWir stecken echt ganz schön in der Klemme. Könnt Ihr uns vielleicht helfen?",objectives={"Holt die Nachschubkiste für Sigrun Ironhew."}]])
R(719,"Ein Zwerg und sein Werkzeug",[[description="He, $N. Seid lieber vorsichtig. Es sind Dunkeleisenzwerge in der Nähe - scheinen vom Schattenschmiedeklan zu sein.$B$BSie haben gerade die Ausgrabungsstätte angegriffen, auf der ich arbeite - haben fast alle dort umgebracht, darunter meinen Boss Hammertoe. Ich bin gerade noch lebendig weggekommen.$B$BDie Stätte liegt nördlich von hier und ich versuche, mir einen Plan auszudenken, wie wir einen Teil unserer Vorräte zurückbekommen könnten, insbesondere meine Glückshacke.$B$BMeint Ihr, Ihr könntet mir ein bisschen helfen? Einer von diesen verdammten Dunkeleisenzwergen muss meine Hacke haben! Es könnte jeder von denen sein.",objectives={"Sucht Ryedols Glückshacke und bringt sie Ausgrabungsleiter Ryedol in der Hammertoe-Grabungsstätte."}]])
R(720,"Ein Hoffnungsschimmer",[[description="<Text wurde mit Kreide auf die Karte gekritzelt.>$B$B\"Ryedol, $BSie bringen mich nach Uldaman. Schickt Hilfe.$B- Hammertoe\"",objectives={"Sucht Ausgrabungsleiter Ryedol und teilt ihm mit, dass Hammertoe Grez noch am Leben ist."}]])
R(721,"Ein Hoffnungsschimmer",[[description="$N, geht Ihr ihn suchen? Sucht Ihr Hammertoe in Uldaman?$B$BWenn diese dreckigen Zwerge der Schattenschmiede ihn als Geisel genommen haben, um herauszubekommen, was er über die Titanenausgrabungen weiß, könnte ganz Ironforge in großer Gefahr sein.$B$BSeit langer Zeit schon trachten die Dunkeleisenzwerge nach Magie, um noch mächtigere Golems zu erschaffen. Hammertoe hatte dasselbe vor, aber natürlich nur, um sie aufzuhalten.$B$BVielleicht lassen sie ihn am Leben, bis sie herausbekommen haben, was er weiß; Ihr müsst Euch beeilen, wenn Ihr ihn retten wollt!",objectives={"Sucht in Uldaman nach Hammertoe Grez."}]])
R(722,"Amulett der Geheimnisse",[[description="Ihr seid mutig... (((hustet))) dass Ihr Euch wegen mir nach Uldaman wagt, $C.$B$BWenn Ihr wirklich hier seid, um dem... ollen Hammertoe zu helfen, dann... (((hustet)))... müsst Ihr nach... meinem Amulett suchen.$B$BGrubenschatten hat es... Magregan Grubenschatten. Muss hier irgendwo sein... in den Ruinen, das ist sicher. Das Amulett wird sie... (((hustet)))... genau zu den Rollen führen, wenn sie keiner aufhält. Es ist an Euch, $N. Bitte... holt das Amulett.$B$BDie Rollen werden es den Dunkeleisenzwergen ermöglichen, noch mächtigere Golems zu erschaffen. Ich weiß es einfach. Spür's in meinen Knochen.",objectives={"Sucht Hammertoes Amulett und bringt es ihm nach Uldaman."}]])
R(723,"Ein Funken Hoffnung",[[description="<Hammertoe fasst an seine Wunden und braucht einen Moment, um sich zu sammeln, bevor er weiterspricht.>$B$BFindet Ryedol, $N. Bringt ihm mein Amulett. <hustet> Er... <hustet>... wird wissen, was zu tun ist; er weiß, dass ich nach den Wurzeln unseres Volks suchte, und er... <hustet>... weiß, dass es meine Aufgabe war, den Schattenschmiedeklan aufzuhalten. Sie dürfen die Rollen nicht finden... <hustet>",objectives={"Bringt Ausgrabungsleiter Ryedol im Ödland Hammertoes Amulett."}]])
R(724,"Ein Funken Hoffnung",[[description="Okay, okay... Wer könnte wissen, was zu tun ist?$B$BHistoriker Karnik! Genau!$B$BEr lebt in Ironforge. Er kann helfen. Er und Hammertoe haben zusammengearbeitet, um in Uldaman nach den verschollenen Artefakten zu suchen.$B$BSchätze, die Zwerge der Schattenschmiede haben rausgefunden, dass die beiden mehr wussten, als sie sagten.$B$BErzählt Karnik, was mit Hammertoe geschehen ist, und gebt ihm das Amulett - er wird Euch dann sagen, was als Nächstes zu tun ist.",objectives={"Bringt Historiker Karnik in Ironforge Hammertoes Amulett."}]])
R(725,"Kunde über die Bedrohung breitet sich aus",[[description="$N, lauft los und findet so schnell wie möglich Berater Belgrum; sagt ihm, was Ihr gesehen habt, und fragt ihn, wie wir weiter vorgehen sollen. Diese Notiz wird ihm alles Weitere erklären.$B$BIn der Zwischenzeit werde ich mir die Zeit nehmen, um mit Hammertoes Geist zu sprechen. Vielleicht weiß er etwas, das uns helfen könnte, die Aktivitäten der Zwerge der Schattenschmiede hier im Ödland zu unterbinden. Wir können nur beten.",objectives={"Sucht Berater Belgrum und gebt ihm die Notiz."}]])
R(726,"Kunde über die Bedrohung breitet sich aus",[[description="<Berater Belgrum erreicht das Ende der Notiz und für einen Moment weiten sich seine Augen.>$B$BAch, das sind schlimme Nachrichten.$B$B$n, bitte kehrt zu Historiker Karnik zurück und sagt ihm, dass er im Auftrag des Königs schnell und entschlossen gemäß dieser Information handeln soll. Er muss die Aktivitäten der Zwerge der Schattenschmiede im Ödland unterbinden.",objectives={"Sprecht mit Historiker Karnik."}]])
R(727,"Auf nach Ironforge zu 'Yagyins Zusammenstellung'",[[description="Die Schrifttafel erklärt vieles. Aber nicht genug! Nicht annähernd genug!$B$BEs gibt ein Buch, eine Zusammenstellung, die Yagyin vor Unzeiten verfasst hat. Die... Leute, vor denen ich geflohen bin... bewahren dieses Buch an vielen verschiedenen Orten auf. Und die höchstgebildeten von ihnen studieren es. Es enthält riesiges Wissen. Wissen, das uns beschützen kann!$B$BGeht zu Gerrig Bonegrip. Er befindet sich in Ironforge in einem Geschäft im düsteren Viertel. Zeigt ihm dieses Siegelzeichen, dann wird er Euch für einen der ihren halten. Fragt ihn nach 'Yagyins Zusammenstellung'... und bringt sie mir!",objectives={"Gebt Gerrig Bonegrip im düsteren Viertel von Ironforge das Siegelzeichen des Hammers."}]])
R(728,"Auf nach Undercity zu 'Yagyins Zusammenstellung'",[[description="Die Schrifttafel erklärt vieles. Aber nicht genug! Nicht annähernd genug!$B$BEs gibt ein Buch, eine Zusammenstellung, die Yagyin vor Unzeiten verfasst hat. Die... Leute, vor denen ich geflohen bin... bewahren dieses Buch an vielen verschiedenen Orten auf. Und die höchstgebildeten von ihnen studieren es. Es enthält riesiges Wissen. Wissen, das uns beschützen kann!$B$BSucht den Bewahrer Bel'dugur in Undercity von Lordaeron auf. Zeigt ihm dieses Siegelzeichen, dann wird er Euch für einen der ihren halten. Fragt ihn nach 'Yagyins Zusammenstellung'... und bringt sie mir!",objectives={"Bringt dem Bewahrer Bel'dugur in Undercity das Siegelzeichen des Hammers."}]])
R(729,"Der geistesabwesende Ausgrabungsleiter",[[description="Was war es doch für eine Ehre, als Meister Greywhisker mir auftrug, unter der Führung des großen Ausgrabungsleiters Remtravel zu arbeiten. Jeder an der Akademie in Ironforge kannte Remtravels großartige Entdeckungen.$b$bAber der Ausgrabungsleiter ist sich nicht so recht ... ähm ... bewusst ... was um ihn herum so vor sich geht.$b$bWir hatten Hinweise auf eine große Kultur entdeckt. Schreckliche Golems brachen aus dem Boden hervor und überrannten die Grabungsstätte. Remtravel schien gar nichts bemerkt zu haben. Ich rannte nach Auberdine, um Hilfe zu holen.$b$bBitte reist nach Süden und seht nach, ob es dem Ausgrabungsleiter gut geht!",objectives={"Reist nach Süden und seht nach Ausgrabungsleiter Remtravel."}]])
R(730,"Ärger in Dunkelküste?",[[description="Wie schön, ein $C, der an den großartigen archäologischen Wundern unserer Welt interessiert ist.$b$bOftmals wird unser Wirken von unseren Freunden der Allianz nur als reines Hobby abgetan. Aber was viele nicht einsehen wollen ist, dass die jüngsten Entdeckungen in Khaz Modan bewiesen haben, dass eine große und mächtige Kraft ganz Azeroth bedroht, von Lordaeron bis nach Kalimdor.$b$bIch bin höchst besorgt um meine Mannschaft, die ich nach Dunkelküste geschickt habe. Meine Leute haben seit Wochen nichts mehr von sich hören lassen.$b$bReist nach Auberdine und sucht nach Hinweisen auf ihren Aufenthaltsort.",objectives={"Reist nach Auberdine und sucht nach Hinweisen auf das Zwergenausgrabungsteam."}]])
R(731,"Der geistesabwesende Ausgrabungsleiter",[[description="Also dann, Hollee... ach ja, richtig, Ihr seid ja gar nicht Hollee. Wo ist Hollee?$b$bPah, das ist ja jetzt auch nebensächlich. Wir müssen diesen Handfeger finden... Ich meine, das rätselhafte Fossil! Wir müssen dieses Fossil finden. Die Forscherliga in Darnassus wird ein paar Hinweise darauf haben wollen, was ich hier die ganze Zeit getrieben habe.$b$bLasst es mich wissen, wenn Ihr bereit seid, dann machen wir uns auf die Jagd nach diesem Feger... Ich meine, Fossil! Wir sollten irgendeine Niederschrift finden, damit die Liga zufrieden ist.$b$bAlso, seid Ihr so weit?",objectives={"Beschützt Ausgrabungsleiter Remtravel, während er nach dem rätselhaften Fossil sucht, und kehrt dann zur Archäologin Hollee in Auberdine zurück."}]])
R(732,"Erdbeben",[[description="Ich habe von Sigrun gehört, dass Ihr ihm eine große Hilfe gewesen seid. Vielleicht darf ich Eure Hilfe ja auch in Anspruch nehmen. Mein Meister, Krasus von den Kirin Tor, hat mich hergeschickt, um die Probleme zu lösen, die sich in der Lethlorklamm zusammenbrauen.$b$bIch darf nicht preisgeben, was genau meine Mission ist oder was ich unternehmen soll, aber seid versichert, dass es von großer Wichtigkeit ist.$b$bEine Bande nomadisierender Oger, die gelegentlich in der Nähe vom Camp Boff gesichtet wurden, hat einen Gegenstand gestohlen, das so genannte \"Zeichen der Erde\", und ich muss es wiederhaben. Bringt es mir und ich verrate Euch mehr.",objectives={"Beschafft für Garek das Zeichen der Erde."}]])
R(733,"Schnorrerei",[[description="Es wird hier ganz schön haarig werden, wenn es mir nicht gelingt, Material aufzutreiben, um ein paar Verteidigungslinien und andere Notwendigkeiten zu konstruieren. Mir ist aufgefallen, dass die Oger in diesem Gebiet über jede Menge Metallschrott verfügen. Vielleicht sind die Geschichten über Belagerungsmaschinen im Ödland doch gar nicht so weit hergeholt...$b$bWie dem auch sei, die Ausgrabungsleiter machen sich langsam Sorgen um die Lage in unserem kleinen Lager, deshalb würde ich gern, sobald es geht, mit der Arbeit beginnen.$b$bDas Hauptlager der Oger liegt bei der Staubspeiergrotte, eine ordentliche Strecke von hier aus Richtung Westen.",objectives={"Bringt Sigrun 7 Teile Metallschrott."}]])
R(734,"Das wird schwierig",[[description="Wunderbar, wunderbar.$B$B<Lotwil sieht Euch einen Moment lang an, bevor er sich wieder seinen Fesseln zuwendet.>$B$BSprecht mit Lucien, $n. Ich brauche ein Zahnrad Nr. 5. Bringt es mir bitte, ja?",objectives={"Sprecht im Ödland mit Lucien Tosselwrench."}]])
R(735,"Der Stern, die Hand und das Herz",[[description="Yagyins Zusammenstellung', eh? Wollt Ihr vielleicht irgendwo eine neue Ortsgruppe aufbauen? Egal, es steht mir nicht zu, Euch das zu fragen.$B$BIch werde Euch helfen, weil ich ein Exemplar davon besitze, das ich entbehren kann. Und eine Hand wäscht die andere, stimmt's? Daher werden wir groß.$B$BIch brauche drei mächtige Gegenstände. Bringt sie mir, dann gebe ich Euch die Zusammenstellung.$B$BIch werde ihre Namen nicht nennen. Man könnte uns belauschen. Aber wartet, ich schreibe sie auf.",objectives={"Bringt Gerrig Bonegrip in Ironforge die Gegenstände in Bonegrips Notiz."}]])
R(736,"Der Stern, die Hand und das Herz",[[description="Ihr braucht 'Yagyins Zusammenstellung'? Dann wollt Ihr also eine neue Herde sammeln? Natürlich... und natürlich werde ich Euch helfen, $gBruder:Schwester;.$B$BAber Ihr müsst mir auch helfen.$B$BIch brauche drei mächtige Gegenstände. Bringt sie mir, dann gehört die Zusammenstellung Euch.$B$BIch darf die Namen dieser Gegenstände nicht aussprechen, aber ich werde sie aufschreiben.$B$BBringt mir die Gegenstände, die auf dieser Liste stehen. Wenn Ihr das schafft, seid Ihr wahrlich würdig, ein eigenes Kapitel über unseren Orden zu beginnen.",objectives={"Bringt dem Bewahrer Bel'dugur in Undercity die Gegenstände von Bel'dugurs Notiz."}]])
R(737,"Verbotenes Wissen",[[description="Ich habe die Zusammenstellung für Euch, $n. Ich muss Euch wohl nicht sagen, dass Ihr sie sorgfältig behandeln solltet. Und dass Ihr sie nicht in unfreundliche Hände gelangen lassen solltet. $B$BDieses Buch enthält viele Wahrheiten...$B$B... und die Wahrheit kann manchmal wehtun.",objectives={"Bringt Theldurin 'Yagyins Zusammenstellung'."}]])
R(738,"Sucht Agmond",[[description="Ausgrabungsleiter Agmond hatte die Verantwortung über unsere Ausgrabungsstätten im Ödland, im Südwesten. Ich sagte \"hatte\", weil... also, ich habe schon seit Wochen nichts mehr von ihm gehört. Ich möchte, dass Ihr Agmond sucht, damit er mir Bericht erstatten kann.$B$BZuletzt hörte ich, dass sich Agmond in der südlichsten Grabungsstätte im Ödland aufhalten würde - einer winzigen Unternehmung hinter der Festung Angor. Ich würde dort mit der Suche beginnen.",objectives={"Sucht Agmond."}]])
R(739,"Murdaloc",[[description="Agmonds Spuren führen nach Westen. Anhand der Blutspuren auf den Felsen und im Sand ist unschwer zu erraten, dass sich der Zwerg ein ganzes Stück weit geschleppt haben muss.$B$BUnd hier ist er dann gestorben.$B$BBei näherer Betrachtung ist das Wort \"Murdaloc\" erkennbar, das grob aus Sandsteinen des Ödlands zusammengestückelt wurde.$B$BDirekt neben Agmonds toter Hand.",objectives={"Tötet Agmonds Mörder Murdaloc.$B$BTötet 12 Knochenknacker der Steingrufttroggs.$B$BErstattet Ausgrabungsleiter Ironband am Loch Modan Bericht."}]])
R(741,"Der geistesabwesende Ausgrabungsleiter",[[description="Der Ausgrabungsleiter will also das geheimnisvolle Fossil zur Forscherliga nach Darnassus schicken? Es schmeckt mir gar nicht, Dunkelküste ohne ihn zu verlassen.$b$bHier, $N, bringt Ihr dem Chefarchäologen Greywhisker in Darnassus das rätselhafte Fossil.",objectives={"Bringt dem Chefarchäologen Greywhisker in Darnassus das rätselhafte Fossil."}]])
R(742,"Die Jagd in Ashenvale",[[description="Achtung, junge Abenteurer! Die Wildnis von Ashenvale erwartet Euch!$B$BDie Horde hat eine starke Präsenz in den Ländern nördlich des Brachlandes aufgebaut. Unsere beiden Außenposten - der Splintertreeposten und der Zoramstrandposten - wollen der Horde zu Ruhm gereichen! Diejenigen, die sich beweisen möchten, sollten dort nach Anleitung suchen. Wichtiger Hinweis: Senani Thunderheart im Splintertreeposten, direkt nördlich des Brachlandes, sucht Abenteurer, die an einer großen Jagd in Ashenvale teilnehmen wollen!",objectives={"Sprecht mit Seneni Thunderheart im Splintertreeposten in Ashenvale."}]])
R(743,"Windfuriengefahr",[[description="Danke, dass Ihr Euch die Zeit genommen habt, mit mir zu sprechen, $n. Ich bin Ruul, Krieger und Lehrer.$B$BIhr habt offensichtlich ein Alter erreicht, in dem Ihr Euch auf Eure Aufgaben vorbereiten müsst, wenn Ihr auf Abenteuer weit außerhalb von Mulgore aus seid.$B$BWenn Ihr Eure Kraft erproben möchtet, versucht Euch zuerst an den Windfurienharpyien im Südosten. Sie treiben sich an den Bergrändern fernab der Straße herum.$B$BSie gehören mit zu unseren natürlichen Feinden hier in Mulgore und sind gut geeignet, um Eure Fertigkeiten einzuschätzen.",objectives={"Bringt Ruul Eagletalon in Bloodhoof 8 Windfurienkrallen."}]])
R(744,"Vorbereitungen auf die Zeremonie",[[description="$N, mein Bruder wird schon bald vor Häuptling Bloodhoof treten und es ist mir eine Ehre, einen Kopfputz für ihn anfertigen zu dürfen.$B$BIch möchte Euch um einen Gefallen bitten, während ich die letzten dieser Lederriemen gerbe. Ich habe keine Zeit mehr, um genügend Federn zu suchen, und ich habe mich gefragt, ob Ihr wohl noch ein paar für mich sammeln würdet?$B$BIhr könnt Federn in der richtigen Größe bei den Harpyien finden, die ganz weit im Norden und nordwestlich von Thunder Bluff leben. Ich brauche nur 6 azurblaue und 6 bronzene Federn, um die Ausführung zu vervollständigen.",objectives={"Sammelt 6 azurblaue und 6 bronzene Federn und bringt sie Eyahn Eagletalon in Thunder Bluff."}]])
R(745,"Gemeinsame Nutzung des Landes",[[description="Viele Konflikte verwunden dieses Land, $N. Ich hoffe, dass Ihr nicht so viele wie ich ertragen müsst. Es gibt nur einen, bei dem ich um Eure Mithilfe bitten möchte. Er wird Euch deutlich machen, wie schrecklich sogar eine kleine Bedrohung für das Land sein kann, wenn man sie ignoriert.$B$BBleichmähnengnolle haben sich südlich von Bloodhoof in einer Höhle im Westen niedergelassen. Sie missachten unsere Versuche, mit ihnen zu kommunizieren, und vernichten ungezügelt die Tierwelt Mulgores.$B$BWorte allein genügen nicht mehr als Antwort.",objectives={"Tötet 10 Gerber der Bleichmähnen, 8 Kürschner der Bleichmähnen und 5 Wilderer der Bleichmähnen und kehrt dann zu Baine Bloodhoof in Bloodhoof zurück."}]])
R(746,"Zwergen-Buddelei",[[description="Im Nordwesten bereiten Zwerge eine Grabungsstätte vor. Sie glauben, dass Geheimnisse in der Erde verborgen seien, und das stimmt auch; dies ist jedoch kein Grund, das Land bei der Suche nach diesen Lehren auszuhöhlen und zu besudeln.$B$BSammelt die Grabwerkzeuge der Zwerge ein, zerstört sie und kehrt mit den zerbrochenen Werkzeugen der Zwerge zu mir zurück.$B$BIhr könnt die Werkzeuge in einer Schmiede zerschlagen. Ihr findet eine in Thunder Bluff, aber jede Schmiede, sogar eine Schmiede im Zwergenlager, eignet sich dazu.",objectives={"Sammelt 5 Ausgrabungsleiterhacken ein.$B$BZerschlagt die Ausgrabungsleiterhacken in einer Schmiede, um zerbrochene Werkzeuge zu erhalten.$B$BBringt Baine Bloodhoof in Bloodhoof 5 zerbrochene Werkzeuge."}]])
R(747,"Die Jagd beginnt",[[description="Ihr seht viel versprechend aus, und ich denke, Ihr werdet Euch dem Stamm gegenüber beweisen. Vielleicht wird man Euch eines Tages in der großen Stadt Thunder Bluff willkommen heißen. Bevor das jedoch möglich ist, müsst Ihr Euch meinem Vater, Häuptling Hawkwind, beweisen.$b$bWir hier oben auf der Red Cloud Mesa sind stolz auf unsere hervorragenden Jagdfertigkeiten. Tauren jagen aus Notwendigkeit und als sportlichen Wettkampf. Unsere Fleischvorräte gehen zur Neige und wir brauchen Federn, um Kleidung herzustellen. Jagt die in der Nähe herumwandernden Ebenenschreiter und beweist Euch, indem Ihr für Nachschub für das Dorf sorgt.",objectives={"Grull Hawkwind im Camp Narache möchte, dass Ihr ihm 7 Ebenenschreiterfedern und 7 Stücke Ebenenschreiterfleisch bringt."}]])
R(748,"Vergiftetes Wasser",[[description="Goblins und ihre Gefolgsleute haben unsere heiligen Wasserbrunnen besudelt! Das dürfen wir nicht zulassen.$B$BUm alle Brunnen zu säubern, muss ich ein Säuberungstotem herstellen und Ihr müsst dieses Totem dann zu den Brunnen bringen und ein Säuberungsritual durchführen.$B$BZuerst werden wir ein Säuberungstotem für den Wasserbrunnen von Winterhoof herstellen. Dabei muss uns das Land behilflich sein. Jagt Präriewölfe wegen ihrer Tatzen und erwachsene Ebenenschreiter wegen ihrer Krallen. Sie sind im Südwesten zu finden.$B$BKehrt mit den Tatzen und Krallen zu mir zurück, $N.",objectives={"Bringt Mull Thunderhorn in Bloodhoof 6 Präriewolftatzen und 4 Ebenenschreiterkrallen."}]])
R(749,"Die überfallene Karawane",[[description="Vor ein paar Tagen haben wir am Nordufer des Stonebullsees eine bewachte Karawane der Venture Company entdeckt. Wir haben bei früheren Kämpfen mit ihnen zwei unserer Leute verloren, deshalb haben wir mit der Karawane kurzen Prozess gemacht.$b$bWir haben ihre Nachschubkisten zurückgelassen, weil wir dachten, unsere Fackeln würden alles Wertvolle zerstören, aber da man in der Nähe der ausgebrannten Wagen Bergungstrupps der Venture Company gesichtet hat, haben wir uns wohl geirrt.$b$bWürdet Ihr zur Karawane gehen und den Inhalt der Kisten untersuchen?",objectives={"Morin Cloudstalker möchte, dass Ihr den Inhalt einer Nachschubkiste der überfallenen Karawane untersucht."}]])
R(750,"Die Jagd geht weiter",[[description="Ein Tauren, der in der Fertigkeit des Jagens bewandert ist, weiß, dass seine Beute nicht nur eine Trophäe ist. Die Wildtiere der Ebenen versorgen uns mit allem, was wir zum Überleben brauchen. Ihr würdet die Ältesten ziemlich beeindrucken, wenn Ihr ein paar hochgeschätzte Bergpumapelze erjagen würdet. Ihr findet die Wildtiere in den Hügeln im Süden.$b$bUnsere Kinder brauchen Kleidung und unsere Zelte müssen repariert werden.",objectives={"Grull Hawkwind im Camp Narache möchte, dass Ihr ihm 10 Bergpumapelze bringt."}]])
R(751,"Die überfallene Karawane",[[description="Als Ihr den Deckel der Kiste aufstemmt, findet Ihr sie vollgestopft mit einem Sortiment aus Erzen und Mineralien, weitere Beweise für den Bergbau der Venture Company in Mulgore. Oben auf dem Erz und den Mineralien liegt ein fest verschnürtes Bündel Papiere, das Ihr an Euch nehmt.$b$bVom Vorgebirge im Osten her könnt Ihr schwach Arbeitsgeräusche hören und Ihr seht Rauch von einem großen Feuer aufsteigen.",objectives={"Bringt Morin Cloudstalker in der Nähe von Bloodhoof die Dokumente der Venture Company."}]])
R(752,"Eine bescheidene Bitte",[[description="Alle Mitglieder des Stammes teilen die Harmonie des Lebens miteinander. Wir leben und arbeiten zusammen.$b$bMit der Verpflichtung, füreinander da zu sein, haben wir eine große Verantwortung übernommen. Ich habe eine bescheidene Bitte an Euch.$b$bMeine Mutter ist heute Morgen fortgegangen, um Wasser aus dem Brunnen südöstlich von Narache zu holen. Das ist jetzt schon eine Weile her. Würdet Ihr wohl an meiner Stelle nach ihr sehen, während ich mich hier um Stammesangelegenheiten kümmere?",objectives={"Häuptling Hawkwind möchte, dass Ihr seine Mutter beim Brunnen südöstlich vom Camp Narache sucht."}]])
R(753,"Eine bescheidene Bitte",[[description="Ich habe in meinem Leben so viele Pfade beschritten und meinen alten Beinen mangelt es an der Energie, die sie einst hatten. Ich kann aber immer noch meine Pflichten innerhalb des Stammes erfüllen. Manchmal braucht eine alte Frau eben nur etwas länger dafür.$b$bAber Ihr scheint mir ein eifriger $C zu sein. Wir sollten Eure jugendliche Vitalität auf die Probe stellen. Holt eine Wasserkanne vom Brunnen und bringt sie meinem Sohn, dem Häuptling im Camp Narache.$b$bVergesst nicht, dass selbst die bescheidenste Tat die Anerkennung der Ahnen finden kann.",objectives={"Holt eine Wasserkanne vom Wasserbrunnen.$b$bBringt die Kanne Häuptling Hawkwind im Camp Narache, das nordwestlich des Wasserbrunnens liegt."}]])
R(754,"Säuberung von Winterhoof",[[description="Ich habe das Totem angefertigt, um den Wasserbrunnen von Winterhoof zu säubern. Jetzt müsst Ihr es zum Brunnen bringen und ein Säuberungsritual durchführen. Ihr findet ihn im Südosten, bewacht von elenden Goblins!$B$BDas wird keine leichte Aufgabe, aber Ihr müsst es tun, wenn wir jemals wieder sein Wasser trinken sollen.$B$BViel Glück, $N.",objectives={"Benutzt das Säuberungstotem von Winterhoof beim Wasserbrunnen von Winterhoof und kehrt dann zu Mull Thunderhorn zurück."}]])
R(755,"Riten der Erdenmutter",[[description="Eure Bereitschaft, für die Tauren von Narache eine bescheidene Bitte zu erfüllen, und Euer Eifer zu lernen sind edle Charakterzüge, $n. Ich weiß, eines Tages wird man in Thunder Bluff von Euch als einer bedeutenden Person sprechen, $C.$b$bBevor es so weit ist, müsst Ihr jedoch die Riten der Erdenmutter bestehen, derer es drei gibt.$b$bDie erste Prüfung ist der Ritus der Kraft. Begebt Euch zu Seher Graytongue und sagt ihm, dass Häuptling Hawkwind Euch schickt.$b$bIhr findet die Behausung des Sehers direkt südlich des Lagers Narache in den Hügeln verborgen.",objectives={"Begebt Euch zu Seher Graytongue, der in den Hügeln direkt südlich des Lagers Narache lebt."}]])
R(756,"Thunderhorn-Totem",[[description="Um das Säuberungstotem von Thunderhorn zu schaffen, benötigt Ihr die Klauen der Raubtiere der Mulgoreebene. Jagt Präriepirscher wegen ihrer Pirscherklauen und Flachlandpumas wegen ihrer Pumaklauen und kehrt dann zu mir zurück.$B$BIhr findet die Präriepirscher und Flachlandpumas im Osten und Westen.",objectives={"Bringt Mull Thunderhorn 6 Pirscherklauen und 6 Pumaklauen."}]])
R(757,"Ritus der Kraft",[[description="Die Riten der Erdenmutter sind die Schritte, die ein junger Tauren gehen muss, um sich in Thunder Bluff Respekt zu verschaffen.$b$bIhr müsst zuerst den Ritus der Kraft bestehen. Bei dieser Prüfung müsst Ihr Euren Mut beweisen, indem Ihr Feinde des Stammes tötet.$b$bDer Borstennackenstamm aus der Dornrankenklamm im Osten ist in unser Stammesterritorium eingedrungen. Sie überfallen unsere Jägergruppen und rauben in der Dunkelheit unsere Dörfer aus.$b$bZeigt Euren Wagemut, indem Ihr diese Bösewichte zur Strecke bringt und dem Häuptling des Lagers Narache ihre Gürtel zum Beweis Eurer Taten vorlegt.",objectives={"Tötet die Borstennacken in der Dornrankenklamm und bringt Häuptling Hawkwind im Camp Narache 12 Gürtel der Borstennacken."}]])
R(758,"Säuberung von Thunderhorn",[[description="Das Totem ist bereit, $N. Und wiederum ist es Eure Aufgabe, das Ritual der Säuberung durchzuführen.$B$BGeht zum Wasserbrunnen von Thunderhorn nördlich des Dorfes und benutzt das Säuberungstotem von Thunderhorn bei Eurem Ritual. Kehrt danach zu mir zurück.$B$BMögen Euch die Geister leiten.",objectives={"Benutzt dasSäuberungstotem von Thunderhorn beim Wasserbrunnen von Thunderhorn und kehrt dann zu Mull zurück."}]])
R(759,"Wildmane-Totem",[[description="Es gibt nur noch einen Wasserbrunnen, der gesäubert werden muss; er trägt den Namen des Wildmaneklans. Damit dieser Brunnen wieder rein wird, muss das Land die Zähne eines wilden Raubtiers opfern, die eines Präriewolfalphatiers. Findet die Alphatiere im Norden und kehrt dann zu mir zurück, wenn Ihr Eure Jagd beendet habt.$B$BAlphatiere streifen oft am Fuße unserer mächtigen Stadt Thunder Bluff umher.",objectives={"Bringt Mull Thunderhorn in Bloodhoof 8 Präriealphazähne."}]])
R(760,"Säuberung von Wildmane",[[description="Die Geister sprechen von Eurer Säuberung der Wasserbrunnen von Winterhoof und Thunderhorn, junger $N. Das Totem von Wildmane ist fertig und die letzte Aufgabe erwartet Euch.$B$BDer Wasserbrunnen von Wildmane liegt nördlich von Thunder Bluff. Führt das Ritual durch! Heilt das Land vom Gift der Goblins! Lasst das Wasser wieder klar und rein fließen!",objectives={"Benutzt das Säuberungstotem von Wildmane beim Wasserbrunnen von Wildmane und kehrt dann zu Mull Thunderhorn zurück."}]])
R(761,"Sturzfliegerjagd",[[description="Der Sturzflieger ist ein gewitzter Vogel, der schwer zu finden und zu jagen ist. Eine Sammlung Sturzfliegerkiele ist ein Zeichen der Geschicklichkeit und Entschlossenheit eines Jägers.$B$BWenn Ihr gewillt seid, diese Aufgabe anzunehmen, zieht in die Ebene hinaus und jagt die Sturzflieger.$B$BBringt mir ihre Kiele und macht Eurem Klan Ehre.$B$BSturzflieger findet man überall in Mulgore, aber Ihr müsst sehr scharfe Augen haben, um sie zu entdecken, und Ihr braucht flinke Hufe, um sie zu fangen.",objectives={"Bringt Harken Windtotem in Bloodhoof 8 Trophäen-Sturzfliegerkiele."}]])
R(762,"Ein Botschafter des Bösen",[[description="Ragnaros persönlich schickte den Gesandten Infernus zur Festung Angor, damit er dort die Suche der Zwerge der Schattenschmiede nach in Uldaman verschollenen Artefakten organisiert.$B$BUnser Volk hat bereits einen enormen Verlust erlitten, aber in letzter Zeit hat sich die Lage offensichtlich noch verschlimmert. Ich wage kaum zu schätzen, wie viele Artefakte sie finden und gegen Ironforge einsetzen könnten.$B$BUnser Ziel ist einfach, $C. Kehrt ins Ödland zurück und beseitigt den Botschafter Infernus. Sobald die Bedrohung aus der Welt geschafft ist, kehrt mit einem Beweis Eures Sieges zu Berater Belgrum zurück.$B$BEs liegt jetzt in Euren Händen.",objectives={"Tötet den Botschafter Infernus in der Festung Angor und bringt Berater Belgrum in Ironforge einen Beweis seines Tod."}]])
R(763,"Riten der Erdenmutter",[[description="Damit Ihr die Riten der Erdenmutter fortsetzen könnt, müsst Ihr noch zwei weitere Prüfungen bestehen. Es ist an der Zeit, Eure Erfahrungen zu erweitern, $n.$b$bReist nach Bloodhoof und sprecht mit Häuptling Baine Bloodhoof, dem Sohn von Cairne. Dort könnt Ihr Eure Reise fortsetzen und Euch die Anerkennung der Ältesten von Thunder Bluff verdienen.$b$bBringt Baine dieses Totem. Er wird meine Schnitzereien erkennen und Euch helfen.$b$bFolgt der Straße, die aus dem Camp Narache herausführt, und beeilt Euch. Schweift nicht von der Straße ab, Ihr  könntet Euch sonst verirren.",objectives={"Bringt Baine Bloodhoof in Bloodhoof Hawkwinds Totem. Folgt der Straße, die aus dem Camp Narache herausführt."}]])
R(764,"Die Venture Company",[[description="Das erklärt auch die Aufstockung von Angestellten und Ausrüstung der Venture Company, die wir in Mulgore gesehen haben. Diese Goblins... ihre Firma wächst viel zu schnell, als dass es gut für sie wäre. Es heißt doch, zeigt man einem Goblin etwas, kann man gleich im Hintergrund die Registrierkasse klingeln hören.$b$bGierige kleine Teufel. Bedauerlich für ihre geschäftlichen Vorhaben, aber wir Tauren können es nicht zulassen, dass sie ihre Arbeiten hier in unserem Land durchführen. Begebt Euch zu ihrer Mine nordöstlich der Überfallenen Karawane und schickt ihnen eine Nachricht.",objectives={"Tötet für Morin Cloudstalker in der Nähe von Bloodhoof 14 Tagelöhner der Venture Co. und 6 Vorsteher der Venture Co."}]])
R(765,"Vorsteher Fizsprocket",[[description="Laut der Dokumente, die Ihr von der Karawane geborgen habt, hat die Venture Company viele Pläne parat, um zu versuchen, uns von unserem Land hier zu vertreiben und damit freie Bahn zur Plünderung des Landes zu haben.$b$bIch bin entsetzt und es stößt mich ab, auf welches Niveau man sich herablassen kann, um seine Ziele durchzusetzen; ich will, dass der führende Kopf hinter ihren Plänen vernichtet wird. Er heißt Vorsteher Fizsprocket, Ihr findet ihn in der Mine der Venture Co. östlich der überfallenen Karawane. Bringt mir sein Klemmbrett, vielleicht finden wir damit ja etwas Nützliches heraus.",objectives={"Tötet Vorsteher Fizsprocket und bringt Morin Cloudstalker in der Nähe von Bloodhoof dessen Klemmbrett."}]])
R(766,"Mazzranache",[[description="Mein Großvater erzählte mir Geschichten von seinen Kämpfen gegen einen Schreiter namens Mazzranache. Er erzählte mir von seinen dämonischen roten Augen, rasiermesserscharfen Krallen und seinem giftigen Biss.$b$bWie der Zufall so spielt, stieß ich auf einer meiner Reisen durch die Ebene auf ihn und trug eine üble Bisswunde an meiner Schulter davon. Er war so Furcht erregend wie ihn mein Großvater beschrieben hatte. Ich werde ein paar nur sehr schwer zu findende Körperteile von Tieren benötigen, um die Infektion durch seinen Biss zu säubern: ein Herz eines Präriewolfs, einen Knochen eines Flachlandpumas, eine Schuppe eines Ebenenschreiters und einen Muskelmagen eines Sturzfliegers.$b$bSchnell, Zeit ist hier entscheidend.",objectives={"Bringt Maur Raincaller in Bloodhoof ein Herz eines Präriewolfs, einen Knochen eines Flachlandpumas, eine Schuppe eines Ebenenschreiters und einen Muskelmagen eines Sturzfliegers."}]])
R(767,"Ritus der Sicht",[[description="Der Ritus der Sicht, einer der Riten der Erdenmutter, wird Euch helfen, den Respekt der Ältesten von Thunder Bluff zu erlangen.$b$bUnser Volk hat gelernt, dass das Land unser allerheiligster Versorger ist. Um am Ritus der Sicht teilzunehmen, müsst Ihr mit dem geistigen Anführer des Dorfes sprechen, Zarlman Two-Moons.",objectives={"Sprecht in Bloodhoof mit Zarlman Two-Moons."}]])
R(768,"Leder sammeln",[[description="Seid gegrüßt. Ihr habt so einen Glanz in den Augen; Ihr brennt darauf, in die Ebene zurückzukehren, um zu jagen. Möget Ihr Eurem Klan Ehre machen!$B$BIch arbeite mit den Häuten von Wildtieren und fertige daraus Kleidung und Rüstung für die Leute von Thunder Bluff.$B$BWenn Ihr Wildtiere jagt und mir ihre Häute bringt, fertige ich Euch etwas daraus.",objectives={"Bringt Veren Tallstrider in Thunder Bluff 12 Stücke leichtes Leder."}]])
R(769,"Kodobalgtasche",[[description="Die Kodowildtiere von Mulgore sind stark und robust - Charaktereigenschaften, die wir sehr schätzen. Wenn Ihr in der Lederverarbeitung bewandert seid und wissen möchtet, wie man eine Kodobalgtasche fertigt, bringt mir die Materialien, die ich für mein Handwerk brauche.$B$BDann teile ich mein Wissen mit Euch.",objectives={"Bringt Veren Tallstrider in Thunder Bluff 4 Einheiten leichtes Leder und 4 grobe Fäden."}]])
R(770,"Der Dämonennarbenumhang",[[description="Der struppige Balg von Geistheuler trägt immer noch die schreckliche Wunde, die der Wolf im Kampf gegen die Brennende Legion davongetragen hat.$B$BVielleicht weiß jemand in Bloodhoof, wie Geistheuler starb...",objectives={"Sucht jemanden, der etwas über Geistheuler weiß."}]])
R(771,"Ritus der Sicht",[[description="Um den Ritus der Sicht zu bestehen, müsst Ihr die Zutaten sammeln, die für das Wasser der Seher benötigt werden:$b$bIch brauche Quellsteine, die man in der Nähe von Wasserbrunnen in Mulgore findet. Diese kombiniere ich mit Bernsteinkorn, das von den mächtigen Bäumen in unserem Land fällt.$b$bDiese Reagenzien enthalten magische Elemente, und wenn sie erhitzt und vor dem Stammesfeuer verzehrt werden, bekommt man eine Vision. Folgt ihr, dann wird sie Euch zum nächsten Schritt dieser heiligen Suche führen.",objectives={"Sammelt 2 Quellsteine und 2 Bernsteinkörner und bringt sie Zarlman Two-Moons in Bloodhoof."}]])
R(772,"Ritus der Sicht",[[description="Hier ist es nun, das Wasser der Seher.$b$bWenn Ihr bereit seid, trinkt das Wasser in der Nähe des Stammesfeuers. Nachdem Ihr das heilige Wasser getrunken habt, wird es einen Moment dauern, bis die Vision vor dem Feuer erscheint.$b$bDann liegt es bei Euch, ihr zu Eurer Bestimmung zu folgen ...",objectives={"Trinkt vor dem Stammesfeuer in Bloodhoof das Wasser der Seher und folgt der Vision, sobald sie erscheint."}]])
R(773,"Ritus der Weisheit",[[description="Um die Anerkennung der Ältesten von Thunder Bluff zu verdienen, müsst Ihr als Nächstes den Ritus der Weisheit absolvieren.$b$bJetzt, da Ihr den Ritus der Sicht bestanden habt, geben Euch die Vorfahrengeister der Teufelsfelsen den Segen unserer Vorfahren. Nur jene, die von dem Wasser der Seher getrunken haben, können diesen Segen erhalten.$b$bReist von Thunder Bluff gen Osten zu den Teufelsfelsen und sprecht mit dem Vorfahrengeist, $N.",objectives={"Reist von Thunder Bluff gen Osten zu den Teufelsfelsen und sprecht mit dem Vorfahrengeist."}]])
R(774,"<UNUSED>")
R(775,"Reise nach Thunder Bluff",[[description="Jetzt wird man Euch in unserer großen Stadt verehren. Ein $R, der würdig ist, die Riten der Erdenmutter abzuschließen, hat diese Ehre verdient.$b$bFür Eure letzte Aufgabe sucht unseren edlen Anführer Cairne Bloodhoof auf, der auf der höchsten Mesa in Thunder Bluff residiert.",objectives={"Sprecht in Thunder Bluff mit Cairne Bloodhoof."}]])
R(776,"Riten der Erdenmutter",[[description="Ihr habt die Riten der Erdenmutter absolviert und Euch einen Platz in Thunder Bluff verdient.$b$bUm den Platz zu verteidigen, den Ihr Euch so hart erarbeitet habt, müsst Ihr allerdings auch weiterhin Euren Wert für unser Volk beweisen.$b$bWir sind Jäger, $n. Unten in Mulgore gibt es einen mächtigen Kodo namens Arra'chea. Zeigt mir Euer Können im Fährtenlesen und Jagen, indem Ihr mir das Horn von Arra'chea bringt.",objectives={"Cairne Bloodhoof in Thunder Bluff möchte, dass Ihr ihm das Horn von Arra'chea bringt."}]])
R(777,"Das wird schwierig",[[description="Bitte sehr, das ist für Euch.$B$BIch werde hier drüben sein... in Deckung.$B$BGesellt Euch ruhig zu mir.",objectives={"Bringt Lotwil Veriatus ein Zahnrad Nr. 5."}]])
R(778,"Das wird schwierig",[[description="Haha! Fertig! Die Fesseln sind fertig!$B$BDer Moment ist gekommen, Lucien. Der Moment ist gekommen, Servo!$B$BSeid Ihr bereit, Zeuge der perfekten Verschmelzung von Alchimie, Ingenieurskunst und des Arkanen zu werden, $N?$B$BIch werde jetzt einen mächtigen Elementar beschwören. Das ist heute ein Bahn brechender Tag für uns alle.",objectives={"Besiegt den Fam'retor-Wächter und bringt Lotwils Fesseln der Elementarbindung zu Lotwil Veriatus zurück."}]])
R(779,"Siegel der Erde")
R(780,"Die Kampfeber",[[description="Die Kampfeber der Dornrankenklamm im Osten sind in unser Stammesjagdterritorium eingedrungen. Sie wurden von den Borstennackenstachelebern, mit denen wir uns im Krieg befinden, abgerichtet, niederträchtig zu sein.$b$bTötet diese elenden Kreaturen und bringt mir ein paar ihrer Schnauzen und Flanken, damit wir daraus einen Eintopf für unsere Jungen zubereiten können.",objectives={"Grull Hawkwind im Camp Narache möchte, dass Ihr für ihn Kampfeber tötet und ihm 8 Kampfeberschnauzen und 8 Kampfeberflanken bringt."}]])
R(781,"Angriff auf Camp Narache",[[description="Nachdem Ihr die Karte sorgfältig studiert habt, erkennt Ihr, dass Eure Entdeckung die geheimen Pläne des Grimmhauer-Kriegshäuptlings für eine ausgedehnte Belagerung des Lagers Narache sind.$b$bHäuptling Hawkwind wird diese Informationen sicherlich gut gebrauchen können!",objectives={"Bringt Häuptling Hawkwind im Camp Narache die Angriffspläne der Borstennacken."}]])
R(782,"Zerbrochene Allianzen",[[description="Durch die Allianz der Horde mit dem Großdrachen Deathwing während des zweiten Krieges wissen wir, dass zwei ihrer Offiziere, Schattenbringer und Hematus, in der Lethlorklamm weit im Osten eingesperrt sind. Wir müssen unsere verderbten Verbündeten von damals zum Stillschweigen bringen, um die Ehre der Horde wiederherzustellen!$B$BWir hatten Tho'grun und seine Gruppe Ogersöldner angeheuert, damit sie uns helfen, das Zeichen der Erde in die Hände zu bekommen, ein Schlüssel, mit dem das Gefängnis des Drachen geöffnet werden kann. Tho'grun hat uns jedoch verraten, uns überrumpelt und ihn sich selbst angeeignet. Begebt Euch zum Camp Boff und holt ihn zurück!",objectives={"Tötet Tho'grun und bringt Gorn in Kargath das Zeichen der Erde."}]])
R(783,"Die Bedrohung von innen",[[description="Ich hoffe, Ihr habt Euren Gürtel festgezurrt, $C, denn es gibt hier in Nordhain viel Arbeit.$B$BUnd ich meine damit nicht Landarbeit.$B$BDie Wachen von Stormwind haben alle Hände voll zu tun, um den Frieden zu bewahren; viele von uns weilen in fernen Ländern und viele Bedrohungen rücken immer näher. Deshalb rekrutieren wir jeden, der gewillt ist, seine Heimat zu verteidigen. Und die Allianz.$B$BFalls Ihr hier seid, um dem Aufruf zu folgen, sprecht mit meinem Vorgesetzten, Marshal McBride. Er ist in der Abtei hinter mir.",objectives={"Sprecht mit Marshal McBride."}]])
R(784,"Vernichtet die Verräter",[[description="Angeführt von Admiral Proudmoore drangen die Menschen von Kul Tiras nach Durotar vor und brachen damit den Pakt, den der Kriegshäuptling vor Jahren mit Jaina Proudmoore geschlossen hatte, um Archimonde zu besiegen.$b$bDie Menschen-Aggressoren wurden zurückgeschlagen und Burg Tiragarde fiel. Kürzlich jedoch hat die Reserve des Admirals unter der Führung von Lieutenant Benedict die Burg zurückerobert und stellt erneut eine Bedrohung für unser Heimatland dar. Diese Menschen haben keinen Respekt vor Diplomatie.$b$bBeweist Eure Ehre und reist gen Süden zur Burg Tiragarde, um die Menschen-Eindringlinge zu eliminieren.",objectives={"Tötet 10 Matrosen von Kul Tiras, 8 Marinesoldaten von Kul Tiras sowie Lieutenant Benedict und kehrt dann zu Gar'Thok in Klingenhügel zurück."}]])
R(785,"A Strategic Alliance",[[description="Thrall is a most wise and noble leader. His tenacity on the battlefield is matched only by his diplomatic tact.$b$bThe Darkspear Trolls have proven to be invaluable allies to orckind. Out of loyalty and honor we have sworn a pact of protection with them.$b$bThe Warchief has sent orders to make sure our Darkspear friends in Sen'jin Village are not under any direct threat. One of their most trusted scouts, Lar Prowltusk is keeping a close watch on their western flank.$b$bSeek out Lar and assist as needed.",objectives={"Seek out Lar Prowltusk on the western flank of Sen'jin Village."}]])
R(786,"Vereitelung der Kolkaraggression",[[description="Sprecht leiser, $C. Die Zentauren der Kolkar liegen gleich hinter jener Kuppe im Westen der Kolkarklippe.$b$bWährend ihres Angriffs letzte Nacht schlich ich mich in ihr Dorf und fand heraus, dass diese dreckigen Bestien einen dreistufigen Angriff auf die Trolle und Orcs von Durotar geplant hatten.$b$bIhre Invasion muss verhindert werden. Vielleicht könnt Ihr die Streitmacht zusammenziehen, die nötig ist, um die Kolkarklippe zu unterwandern und deren Angriffspläne zu vernichten.$b$bZuletzt sah ich, dass Sie sich auf drei ihrer Anführer verteilten.",objectives={"Lar Prowltusk außerhalb von Sen'jin möchte, dass Ihr die 3 Sets der Angriffspläne zerstört, die innerhalb der Kolkarklippe verwahrt werden."}]])
R(787,"Die neue Horde",[[description="Throm-ka, $C. Ich bin Eitrigg, von Thrall beauftragt, die Ausbildung der Rekruten zu beaufsichtigen.$b$bDie Horde ist nicht mehr das, was sie einmal war. Es gab eine Zeit, da ich die Horde verließ, enttäuscht durch den wachsenden Einfluss der machthungrigen Marionetten der Brennenden Legion. Während meines Exils wurde ich von einer Gruppe Menschen gefangen genommen, aber dann von dem Kriegshäuptling gerettet. Er erzählte mir von seiner Vision einer Horde, frei von dämonischen Einflüssen, von den Schamanen geleitet, und so kehrte ich zurück.$b$bGornek wird weitere Anweisungen für Euch haben.",objectives={"Meldet Euch bei Gornek beim Höhlenbau."}]])
R(788,"Scharfe Zähne",[[description="Als Erstes werden wir Euer Rückgrat etwas kräftigen. Ich könnte Euch ins Brachland schicken, um Kodos zu jagen, aber mal ehrlich, lebend seid Ihr uns nützlicher als tot.$b$bIch glaube, die scheckigen Eber nördlich von hier wären genau das Richtige für Euch.",objectives={"Tötet 10 scheckige Eber und kehrt dann zu Gornek beim Höhlenbau zurück."}]])
R(789,"Stich des Skorpiden",[[description="Sowohl mächtige Krieger als auch tollpatschige Anfänger fallen dem Giftstachel der Skorpiden zum Opfer. Nordwestlich von hier findet Ihr eine größere Ansammlung Skorpiden. Bringt mir 10 ihrer Schwänze als Beweis für Eure Leistungsfähigkeit im Kampf.$b$bDas Gegengift für ihren Stich wird aus genau dem Gift, das aus ihren Stacheln extrahiert wurde, gewonnen. Wir haben immer einen großen Vorrat an Gegengift für dieses Skorpidgift, um Grünschnäbel wie Euch damit zu heilen...$b$bAber Ihr werdet das doch bestimmt nicht brauchen, oder?",objectives={"Bringt 10 Skorpidarbeiterschwänze zu Gornek im Höhlenbau."}]])
R(790,"Sarkoth",[[description="$C! Ich dachte schon, ich müsste hier draußen sterben und niemand würde es bemerken. Auf der Jagd nach den Skorpiden des Tals stieß ich auf ein besonders heimtückisches Exemplar. Ich stürzte mich auf ihn und konnte einer seiner Klauen einen ordentlichen Draufschlag versetzen, bevor sie sich um mein Bein schloss.$b$bIch hatte jedoch nicht mit seinem Stecher gerechnet, den er tief in meine Brust trieb, mit dem er mein Fleisch zerschnitt und mir einen großen Blutverlust verursachte. Bitte, Ihr müsst den Skorpid für mich töten! Meine Ehre darf nicht besudelt werden! Da oben auf dem Plateau im Süden habe ich gegen ihn gekämpft.",objectives={"Tötet Sarkoth und bringt seine Klaue zu Hana'zua."}]])
R(791,"Akzeptiert Euer Schicksal",[[description="Das Alter hat mich nutzlos für die Schlacht gemacht. Jetzt mache ich mich eben auf andere Weise nützlich.$b$bVon diesem Aussichtspunkt aus achte ich auf Eindringlinge. Während unsere Kraft hier zunimmt, muss ich mein Signalhorn immer seltener benutzen.$b$bUm mir die Zeit zu vertreiben, fertige ich Dinge an, die den jüngeren und fähigeren Kriegern bei der Verteidigung unserer Heimat helfen können.$b$bFür Euch könnte ich eine Tasche für Eure Habseligkeiten anfertigen. Falls ein solcher Gegenstand Euch nützlich sein könnte, bringt mir etwas Segeltuch, ein Material, das unter Menschen und Zentauren verbreitet ist.",objectives={"Furl Scornbrow im Wachturm von Klingenhügel möchte 8 Segeltuchreste haben."}]])
R(792,"Üble Familiare",[[description="Ich denke, das Tal der Prüfungen wird Euch viel lehren, $C.$B$BMan hat mich eigentlich ins Tal geschickt, um Euch anzuleiten, aber ich habe dort eine sich ausbreitende Besudelung entdeckt...$B$BEine Gruppe, die sich die 'Burning Blade' nennt, hat hier im Tal der Prüfungen einen Koven für ihre Mitglieder. Sie lungern im Nordosten in einer Höhle herum und ihre üblen Familiare kriechen daraus hervor, um Chaos anzurichten.$B$BAls erste Aktion gegen die Burning Blade bitte ich Euch, diese Familiare zu vernichten. Tötet so viele Ihr könnt, und falls Ihr überlebt, kehrt zu mir zurück.",objectives={"Tötet 12 üble Familiare.$B$BKehrt dann zu Zureetha Fargaze beim Höhlenbau zurück."}]])
R(793,"Zerbrochene Allianzen",[[description="Das Siegel der Erde wird von drei Runensteinen gebildet, die in der Lethlorklamm auf Säulen aus Diamant, Opal und Amethyst liegen. Ihr könnt die Runensteine mit Hilfe des Zeichens der Erde entfernen und so das Siegel der Erde brechen.$b$bSeid jedoch vorsichtig, $n, die Schwarzdrachen Schattenbringer und Hematus sollte man nicht unterschätzen. Tötet sie und kehrt mit ihren Bindungen zu mir zurück.$B$BUm die Klamm zu erreichen, müsst Ihr in den östlichsten Teil des Ödlandes reisen. Lasst jedoch Vorsicht walten, da die Klamm zahllose Drachen beherbergt.",objectives={"Benutzt das Zeichen der Erde, um die Säulen aus Diamant, Opal und Amethyst zu aktivieren und die Runensteine zu holen.$b$bLegt die Runensteine auf das Siegel der Erde, um Schattenbringer und Hematus zu befreien.$b$bTötet sie und bringt dann Gorn Schattenbringers Bindung, Hematus' Ketten und das Zeichen der Erde."}]])
R(794,"Medaillon der Burning Blade",[[description="Durch meine hellseherischen Kräfte weiß ich, dass im Koven der Burning Blade ein Gegenstand der Macht verborgen ist, der durch Bestien und schwarze Magie bewacht wird.$B$BEr wird das Medaillon der Burning Blade genannt und Eure nächste Aufgabe besteht darin, es zu finden und aus dem Koven zu entfernen.$B$BSeid jedoch vorsichtig, denn das Medaillon könnte im Besitz eines Agenten der Burning Blade sein, und falls dem so ist, ist die Macht dieses Agenten weitaus stärker als die der Familiare, auf die Ihr bereits gestoßen seid.$B$BGeht, $N. Ihr findet den Koven in einer Höhle im Norden und Westen.",objectives={"Bringt Zureetha Fargaze beim Höhlenbau das Medaillon der Burning Blade."}]])
R(795,"Siegel der Erde")
R(796,"<UNUSED>")
R(797,"<UNUSED>")
R(798,"<UNUSED>")
R(799,"<UNUSED>")
R(800,"<UNUSED>")
R(801,"<UNUSED>")
R(802,"<UNUSED>")
R(803,"<UNUSED>")
R(804,"Sarkoth",[[description="Was Ihr für mich getan habt, gibt mir Zuversicht. Ich darf nicht einfach so gehen! Ich muss durchhalten!$b$bOhne Hilfe schaffe ich jedoch den Weg zurück zum Höhlenbau nicht. Bitte, $n, kehrt zum Höhlenbau zurück und berichtet Gornek von meiner Lage. Vielleicht kann er mir helfen.",objectives={"Informiert Gornek beim Höhlenbau über Hana'zuas Notlage."}]])
R(805,"Bericht erstatten in Sen'jin",[[description="Eure Prüfungen durch die Burning Blade sind beendet... jedenfalls hier im Tal. Ich möchte aber, dass Ihr von Euren Funden berichtet.$B$BBegebt Euch in das Trolldorf Sen'jin und sucht nach Meister Gadrin. Sen'jin liegt östlich hinter dem Tal und dann geht es an der Weggabelung nach rechts.$B$BBerichtet Gadrin von den Burning Blade und dass sie das Tal der Prüfungen erreicht haben. Bringt von ihm in Erfahrung, ob sie Sen'jin schon erreicht haben.$B$BGeht, $N, und beeilt Euch. Ich fürchte, dass das Böse, das wir im Koven der Burning Blade entdeckt haben, nur der Vorbote eines viel größeren Übels ist...",objectives={"Sprecht mit Meister Gadrin in Sen'jin."}]])
R(806,"Dunkle Stürme",[[description="Wir können den Burning Blade nicht erlauben, in Durotar Fuß zu fassen! Wir müssen sie vernichten, bevor das Böse zu schwären beginnt!$B$BIch habe selbst Nachforschungen unternommen und herausgefunden, dass ein Hexenmeister der Burning Blade, der Goblin Fizzle Dunkelsturm, nahe dem Donnergrat im Nordwesten kampiert. Er und seine Kultdiener verbreiten dort Chaos.$B$BSucht und besiegt Fizzle und bringt mir seine Klaue!",objectives={"Bringt Fizzles Klaue zu Orgnil Soulscar in Klingenhügel."}]])
R(808,"Minshinas Schädel",[[description="Ich höre die Stimme meines Bruders Minshina, der in meinen Träumen zu mir spricht.$B$BEr wurde von Zalazane, dem Hexenmeister auf den Echoinseln im Osten, gefangen genommen. Und er ist tot.$B$BAber der Tod bedeutet nicht Freiheit für meinen Bruder. Minshinas Geist ist durch Zalazanes Magie in seinem eigenen Schädel gefangen. In meinen Träumen sehe ich ihn zusammen mit weiteren Schädeln in einem Kreis der Macht auf der Größten der Echoinseln. Solange er dort bleibt, ist die Seele meines Bruders verdammt.$B$BBitte, $n. Sucht den Kreis und bringt Minshinas Schädel zurück. Bringt ihn mir.$B$BBefreit ihn!",objectives={"Holt Minshinas Schädel aus dem Kreis der Macht auf den Echoinseln.$B$BBringt ihn Meister Gadrin in Sen'jin."}]])
R(809,"Ak'Zeloth",[[description="Seit dem letzten großen Krieg, in dem die Brennende Legion besiegt wurde, suche ich nach den Quellen dämonischer Verderbnis innerhalb der Orc-Gesellschaft. Das Halsband, das Ihr mir brachtet, bestätigt meine Befürchtungen.$B$BEs gehört den Burning Blade, einem Kult, der sich um einen Gegenstand dämonischer Macht schart. Er wird 'Dämonensaat' genannt und im Brachland hoch über dem Glutnebelgipfel aufbewahrt. Er muss zerstört werden!$B$BGeht zum Farwatch-Posten an der Grenze zum Brachland im Westen und sprecht dort mit meinem Assistenten Ak'Zeloth. Er wird Euch weitere Anweisungen geben.",objectives={"Sprecht im Brachland mit Ak'Zeloth."}]])
R(810,"<UNUSED>",[[description="You would do well to learn how dangerous this land can be, $c.$B$BThe wildlife here can teach us such things... if we are wise and observant.$B$BThe scorpids are a perfect example of survival in Durotar. If you are to survive, it would be wise to take on some of their characteristics as your own. Their hardened carapaces can protect you from the harshness of the sun, or even a deadly weapon.$B$BBring me 6 Small Scorpid Carapaces from the Clattering Scorpids, $N, and I shall see about rewarding you justly.",objectives={"Bring 6 Small Scorpid Carapaces to Kor'ghan in Sen'jin Village."}]])
R(811,"<UNUSED>",[[description="One of the other traits of the scorpids is their fierce loyalty. They will protect one another if they are in danger--you've probably already seen this behavior in your first scorpid hunt.$B$BYou would do well to heed that lesson and adapt it for yourself: we are stronger as one; we are weak when we are divided into many.$B$BBring me 8 Large Scorpid Carapaces from the Armored Scorpids and I shall reward you for learning this wisdom.",objectives={"Bring 8 Large Scorpid Carapaces to Kor'ghan in Sen'jin Village."}]])
R(812,"Heilmittel benötigt",[[description="$n, Ihr hättet den Zeitpunkt nicht besser wählen können. Ich hoffe nur, dass ich Euch auch zu Eurer Eile beglückwünschen kann.$B$BWährend eines Kampfes mit ein paar Siechstachelskorpiden war ich unvorsichtig und ich wurde von einem von ihnen heftig gestochen. Während wir uns unterhalten, spüre ich, wie sein Gift mich schwächt. Bei dieser Geschwindigkeit bleibt mir vielleicht noch eine Stunde zu leben. Aber selbst dazu brauche ich Eure Hilfe...$B$BKor'ghan in Orgrimmar weiß, wie man das Gegengift herstellt. Sucht ihn... und zwar schnell, $n. Ich werde nicht mehr lange durchhalten. Er sollte sich in der Kluft der Schatten befinden.",objectives={"Sucht Kor'ghan in Orgrimmar und besorgt das Siechstachelgegengift. Bringt das Gegengift dann zu Rhinag an der nordwestlichen Grenze von Durotar."}]])
R(813,"Suche nach dem Gegengift",[[description="Siechstachelskorpide sind eine der tödlichsten Skorpidarten in ganz Durotar. Es war dumm von Rhinag, sie zu jagen, ohne etwas von dem Gegengift mit sich zu führen, aber momentan ist eine ordentliche Standpauke das Letzte, was er benötigt.$B$BBringt mir ein paar Giftbeutel von den Siechstachelskorpiden in der Nähe des Eingangs nach Orgrimmar, dann stelle ich ein Gegengift für ihn her.$B$BBeeilt Euch, $n. Einer der Unseren braucht Eure Hilfe.",objectives={"Bringt Kor'ghan in Orgrimmar 4 Giftbeutel eines Siechstachelskorpiden."}]])
R(814,"<UNUSED>",[[description="Cook and clean--that's all I do!$B$BYou want to eat, you get me some more meat! I don't have all day to hunt and prepare food for all these louses. You got to learn to pull your own weight around here if you wanna be treated equal.$B$BGet me some Chunks of Boar Meat if you want to make yourself useful... or you don't want to starve to death.",objectives={"Bring 10 Chunks of Boar Meat to Cook Torka in Razor Hill."}]])
R(815,"Zerbrecht ein paar Eier",[[description="Pah! Jetzt hätte ich doch beinahe vergessen, Frühstück zu machen.$B$B$n, setzt Euch in Bewegung und bringt mir ein paar Schwanzpeitschereier. Ich brauche mindestens drei davon, wenn ich genug für die morgige Mahlzeit haben möchte.$B$BDie Blutkrallenschwanzpeitscher können ganz schön wild sein und beschützen ihre Eier bis in den Tod. Manchmal vergraben sie ihre Eier allerdings zu tief in der Erde, um sie sicher ausgraben zu können, aber reist doch zu den Echoinseln südöstlich von Sen'jin, dort findet man sie gewöhnlich überall auf den Inseln verteilt.",objectives={"Bringt dem Koch Torka in Klingenhügel 3 Schwanzpeitscher-Eier."}]])
R(816,"Verloren, aber nicht vergessen",[[description="$N, bitte, könnt Ihr mir helfen? Mein Sohn Kron ist vor Tagen auf die Jagd gegangen und immer noch nicht zurück. Er wollte nach Westen in Richtung des Brachlandes, um dort am Ufer des Südstroms Krokilisken zu jagen. Ich fürchte das Schlimmste.$B$BSo stark wie er ist, hat ihn sein starrköpfiger Stolz doch immer wieder in Schwierigkeiten gebracht. Ich habe ihn gewarnt, dass die Krokilisken mächtig und heimtückisch sind. Er wurde wütend und stürmte davon.$B$BFalls Ihr ihn nicht finden könnt, so bringt mir doch wenigstens einen Hinweis darauf, was aus ihm geworden ist ... und wenn Ihr dazu jedem einzelnen Krokilisken an den Ufern des Südstroms den Bauch aufschlitzen müsst.",objectives={"Bringt Misha Tor'kren auf dem Bauernhof nordwestlich von Klingenhügel einen Hinweis auf Krons Schicksal."}]])
R(817,"Praktische Beute",[[description="Viele der Bälge, die wir benutzen, stammen von den Durotar-Tigern, $N. Decken, Rüstungen, Zelte: Es gibt viele Gründe, warum wir Jagd auf die Wildtiere machen, und ebenso viele Gründe, warum wir sie leben lassen.$B$BDie Zeit ist gekommen, dass wir den Bestand dezimieren. Wir werden immer mehr, und unser Bedarf übersteigt bald unsere Bestände. Ich brauche mehr Bälge, wenn ich geeignete Dinge für unser Volk anfertigen möchte.$B$BBringt mir 4 Durotar-Tigerfelle, dann werde ich Euch belohnen. Ihr findet sie auf den Inseln südlich von hier.",objectives={"Bringt Vel'rin Fang in Sen'jin 4 Durotar-Tigerfelle."}]])
R(818,"Ein geistvolles Getränk",[[description="Meine Augen sind zwar nicht mehr so scharf, aber ich kann immer noch gut genug sehen. Immer öfter muss ich mich auf meine Alchimie-Fertigkeiten verlassen, um mir bei Dingen, die mir früher leicht fielen, nun mit Magie zu helfen. Ich weigere mich jedoch, einen Lehrling einzustellen - bislang ist mir noch kein Troll oder Orc begegnet, der sich als würdig genug erwiesen hätte.$B$BSeid Ihr dessen würdig? Ja, natürlich seid Ihr das... natürlich glaubt Ihr, dass Ihr es seid.$B$BIch brauche ein paar Dinge. Würdet Ihr sie für mich besorgen?$B$BIch brauche intakte Makruraaugen und Phiolen mit Kriechersekret. Ihr findet das überall in Durotar, wo es Makruras oder Kriecher gibt. Wir sehen uns bald wieder.",objectives={"Bringt Meister Vornal in Sen'jin 4 intakte Makruraaugen und 8 Phiolen Kriechersekret."}]])
R(819,"Chens leeres Fässchen",[[description="Auf einem kleinen Schild an einem Ende des Fässchens steht:$B$B\"Chen Stormstout -$B$BMöge es Euren Geist erheben und Euch Mut machen.\"",objectives={"Sucht jemanden, der etwas über Chens leeres Fässchen weiß."}]])
R(821,"Chens leeres Fässchen",[[description="Möchtet Ihr eine Kostprobe von Chens Namensvetter? Ahh, das Stormstout ist ein gehaltvolles Gebräu. Chen gab das Rezept an meinen Mentor weiter und mein Mentor gab es mir. Ich möchte, dass Ihr mir ein paar Dinge besorgt, aber eins möchte ich Euch sagen: Der Kick ist es wert.$B$BBringt mir 5 Savannenlöwenhauer von beliebigen Savannenlöwen, 5 Ebenenschreiternieren von beliebigen Ebenenschreitern und 1 Donnerechsenhorn von einer Sturmschnauze. Das sollte bestens funktionieren.$B$BIhr findet diese Zutaten überall im Brachland.",objectives={"Bringt Braumeister Drohn in Ratchet 5 Savannenlöwenhauer, 5 Ebenenschreiternieren und 1 Donnerechsenhorn."}]])
R(822,"Chens leeres Fässchen",[[description="Gutes Zeug, dieses Stormstout, was?$B$BIch habe noch ein Rezept, das ich von Chen gelernt habe. Hättet Ihr Interesse? Die Herstellung dauert nicht lange und es könnte Euch nützlich sein, wenn Ihr Eure Abenteuer fortsetzen wollt.$B$BBringt mir 5 Blitzschlagdrüsen einer beliebigen Sturmechse, 1 Donnerfalkenspeicheldrüse von großen Donnerfalken und eine Kodoleber einer beliebigen Kodoart des Brachlandes.$B$BWie ich sagte, das Zeug hat es in sich; das ist das Troggbräu, das ich kürzlich erwähnte.",objectives={"Bringt Braumeister Drohn in Ratchet 5 Blitzschlagdrüsen, 1 Donnerfalkenspeicheldrüse und 1 Kodoleber."}]])
R(823,"Bericht an Orgnil",[[description="Auch wir in Sen'jin sind nicht ohne eigene Probleme und wir danken Euch für Eure Hilfe. Aber die Neuigkeiten, die Ihr über die Burning Blade bringt, können Probleme für jedermann bedeuten.$B$BIn Klingenhügel ist ein Orc stationiert, Orgnil Soulscar, der Durotar vor solch Bösem wie den Burning Blade bewacht! Geht zu Orgnil und berichtet ihm von unserer Not sowie von Euren Neuigkeiten über das Tal der Prüfungen. Er wird diese Dinge wissen wollen.$B$BKlingenhügel liegt im Norden.",objectives={"Sprecht mit Orgnil Soulscar in Klingenhügel."}]])
R(824,"Je'neu vom Irdenen Ring",[[description="Der Irdene Ring ist eine schamanistische Gruppe, die sich dem Studium und dem Erhalt der Elemente widmet. Sie hat bereits mehr über verrückte alte Götter und uralte Legenden und Lehren vergessen, als die meisten Gelehrten jemals in Erfahrung bringen werden.$B$BZu Eurem Glück kenne ich jemanden hier in Ashenvale, der Mitglied des Irdenen Rings ist. Geht hinüber zum Zoram'gar-Außenposten an der Küste des Zoramstrandes; zeigt Je'neu Sancrea, was Ihr gefunden habt. Wenn überhaupt jemand die Bedeutung dieser Kugel herausfinden kann, dann er.",objectives={"Bringt die beschmutzte Wasserkugel zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale."}]])
R(825,"Aus den Wrackteilen geborgen...",[[description="Einer meiner aufmerksamsten Späher hat mir Kunde gebracht, dass die Trümmer von Proudmoores Flotte immer noch an der Küste Durotars liegen, gleich östlich von Burg Tiragarde.$b$bEs ist kein Geheimnis, dass die Menschen, die sich mit diesen elenden kleinen, als Gnome bekannte Kreaturen verbündet haben, über reichliches Wissen auf dem Gebiet der Mechanik verfügen. Wir müssen so viel wie möglich über unsere potenziellen Feinde in Erfahrung bringen. Dann kann unser Volk von diesem neuen Wissen profitieren.$b$bSchwimmt durch die Wrackteile, $n, und bringt mir die Werkzeuge der Allianz.",objectives={"Gar'Thok von Klingenhügel möchte, dass Ihr 3 Gnomen-Werkzeuge aus den Wrackteilen vor der Küste holt."}]])
R(826,"Zalazane",[[description="Der Hexendoktor Zalazane lebt auf den Echoinseln im Osten. Das sind die Inseln, die wir einst Heimat nannten.$B$BVon dort aus entsendet er seine Trolle zum Festland, wo sie unser Volk verhexen und immer mehr von uns in ihren Bann ziehen.$B$BEr muss aufgehalten werden.$B$BBesiegt Zalazane und seine Diener - ehemalige Trolle der Darkspear, die jetzt nicht mehr zu uns gehören. Bringt mir seinen Kopf, dann weiß ich, dass seine Schreckensherrschaft vorbei ist.",objectives={"Besiegt Zalazane.$B$BTötet 8 Voodootrolle und 8 verhexte Trolle.$B$BBringt Gadrin Zalazanes Kopf."}]])
R(827,"Die Knochenhöhle",[[description="$N. Die Burning Blade haben die Knochenhöhle östlich von Orgrimmar besetzt. Sie führen in dieser Höhle schlimme Rituale durch und fügen sich durch Senghalsbänder selbst Brandwunden zu.$B$BIch glaube, indem sie diese Halsbänder tragen, bringen die Kultisten sich im Einklang mit dämonischen Mächten. Um das zu bestätigen, benötige ich jedoch ein paar dieser Halsbänder, um sie zu studieren.$B$BGeht zur Knochenhöhle und besorgt ein paar Senghalsbänder von den Kultisten, die Ihr dort findet. Bringt sie mir, dann werde ich ihre Geheimnisse enthüllen.",objectives={"Besorgt von den Kultisten an der Knochenhöhle ein paar Senghalsbänder.$B$BBringt sie Margoz in seinem Lager."}]])
R(828,"Margoz",[[description="Margoz, einer unserer Schamanen, weiß mehr über die Verderbnis der Burning Blade. Er sprach von einer Höhle namens Knochenhöhle in den Bergen - gleich vor den Toren Orgrimmars! - dort soll sich eine große Gruppe von Kultisten der Burning Blade eingenistet haben.$B$BBevor Ihr jedoch zur Knochenhöhle geht, sprecht mit Margoz. Er ist weise und sein Rat wird geschätzt.$B$BEr lagert im Nordosten zwischen der Küste und der Staubwindklamm.$B$BFolgt seinem Rat, aber was immer Margoz auch sagt, $N, ich möchte, dass Ihr diese Kultisten vernichtet!",objectives={"Sprecht mit Margoz."}]])
R(829,"Neeru Fireblade",[[description="Die Senghalsbänder, die Ihr mir brachtet, sind mächtige, dämonische Werkzeuge. Ihre Herkunft zu bestimmen liegt jedoch leider außerhalb meiner Künste als Schamane. Wir werden einen Hexenmeister bitten müssen, sie zu studieren.$B$BBringt ein Senghalsband zu Neeru Fireblade. Er ist zwar ein talentierter Hexenmeister, doch nutzt er seine Mächte nur, um Dämonen zu bekämpfen, und er behauptet, dass seine Forschungen auf dem Gebiet des Okkultismus gutartiger Natur sind. Ob es stimmt oder nicht, wir brauchen dennoch seine Hilfe gegen den Dämonenkult in Durotar.$B$BIhr findet Neeru in Orgrimmar in der Kluft der Schatten.",objectives={"Bringt Neeru Fireblade in Orgrimmar ein Senghalsband-Muster."}]])
R(830,"Die Befehle des Admirals",[[description="Ihr öffnet den alten, verwitterten Umschlag und findet darin ein offiziell aussehendes Dokument. Ihr erkennt das Siegel Admiral Proudmoores.$b$bEs sieht wichtig aus. Vielleicht wäre Gar'Thok, Kommandant von Klingenhügel, an diesen Informationen interessiert.",objectives={"Bringt Gar'Thok in Klingenhügel Admiral Proudmoores Befehle."}]])
R(831,"Die Befehle des Admirals",[[description="Menschen kann man nicht trauen. Wir haben immer mit wachsamen Augen an ihrer Seite gekämpft, weil wir wussten, dass sie uns eines Tages verraten würden.$b$bLeider war Admiral Proudmoores Tod nicht genug, um sein Vermächtnis des Betrugs aufzuhalten. Der Menschenabschaum hatte vor seinem Ableben alles gut durchgeplant.$b$bSeine Herrschaft würde, wie es scheint, nicht einmal mit Benedict enden. Wer weiß, wann die nächste Welle von Proudmoores Männern an unseren Küsten landen wird.$b$bWir müssen diese Befehle sofort zu Nazgrel in Orgrimmar bringen! Man findet ihn in Thralls Kammer.",objectives={"Bringt Nazgrel in Thralls Kammer in Orgrimmar Admiral Proudmoores Befehle."}]])
R(832,"Brennende Schatten",[[description="<Die Stimme aus dem Anhänger erreicht direkt Euren Verstand.>$B$BGazz'uz?$B$BGazz'uz... Bericht!$B$BMan hat von Eurer Entdeckung in der Knochenhöhle gehört. Ihr müsst Euch auf einen Angriff vorbereiten!$B$BGazz'uz, ich befehle Euch, mir zu antworten! Sagt etwas, sonst werde ich dafür sorgen, dass Neeru Fireblade von Eurer Anwesenheit erfährt, dann wird es Euch schlecht ergehen.$B$BVersucht nicht, Eure Fertigkeiten mit denen Neerus zu messen...$B$B... Gazz'uz, seid Ihr da...?",objectives={"Bringt Neeru Fireblade dieses Auge."}]])
R(833,"Eine heilige Bestattung",[[description="Nur die tapfersten Tauren werden bei den Teufelsfelsen, unserer heiligen Begräbnisstätte, bestattet. Es ist eine Ehre, die jenen großen Kriegern zuteil wird, die dazu beitrugen, Thunder Bluff zu gründen und zu verteidigen, und jenen, die ihr Leben für das Wohl ihres Stammes und ihrer Häuptlinge gegeben haben.$b$bNun sieht es jedoch so aus, als wäre es einer üblen Bedrohung gelungen, in unser heiliges Land einzudringen. Eine Gruppe Borstennacken-Eindringlinge verheert das Grabmal und ich bin zu alt und gebrechlich, um sie selbst zu vertreiben.$b$bSie müssen mit Gewalt von dort verjagt werden, $N.",objectives={"Der Hüter des Wissens Raintotem möchte, dass Ihr bei den Teufelsfelsen 8 Eindringlinge der Borstennacken tötet."}]])
R(834,"Wind in der Wüste",[[description="Ich bin Rezlak, einer von Gazlowes Jungs. Boss hat mich geschickt, den Orcs hier in Durotar unter die Arme zu greifen. Soweit läuft alles klar, abgesehen von den Karawanen. Ich schaff's einfach nicht, sie zu sichern! Das erschwert mir meinen Job ganz schön, wisst Ihr?$b$bDie letzte Lieferung, meine Güte, die hatten garantiert, dass sie durchkommt! Aber sie wurde von den Staubschwingenharpyien von... wo war das noch... in der Klingenschlucht geklaut.$b$bIch muss dieses Zeug zurückhaben, sonst kriege ich hier nie mehr was zu tun! Folgt dem großen Canyon nach Süden, dort findet Ihr eine Klamm direkt westlich und östlich der Wände.",objectives={"Holt 5 Säcke Vorräte und bringt sie Rezlak in der Nähe von Orgrimmar."}]])
R(835,"Sicherung der Linien",[[description="Gazlowe sagte mal zu mir: \"Rezlak. Eines musst du im Leben wissen: Wenn du was richtig gemacht haben willst, dann tu's selbst.\"$b$bIch kann es mir nicht leisten, all unsere Karawanen zu verlieren, also muss ich die Sache selbst in die Hand nehmen. Die Staubwindklamm liegt hinter dem Ostteil der Klingenschlucht. Wenn wir alle Harpyien dort töten, ist die Route wieder sicher.$b$bNatürlich gab's da noch was, das Gazlowe mir beigebracht hat, und das ist: \"Wenn die Kohle stimmt, kriegt man alles.\" Also, werdet Ihr mir helfen, $n?",objectives={"Tötet für Rezlak in der Nähe der Staubwindklamm 12 Wilde der Staubschwingen und 8 Sturmhexen der Staubschwingen."}]])
R(836,"Rettet OOX-09/HL!",[[description="Aus dem Roboter ertönt erneut die blecherne Stimme des Gnoms:$B$B\"Ich muss OOX-09/HL an einen offenen, sicheren Ort schaffen, wo er die langwierige Startprozedur beginnen kann. Er hat eine eingebaute Tarnvorrichtung, aber ich brauche etwas Zeit, um sie von hier aus wieder funktionstüchtig zu machen. Eskortiert den Roboter von seinem derzeitigen Standort... hmmm, ja, zur Küste jenseits der Aussichtsklippen! Das sollte der perfekte Ort für mein Vorhaben sein, und bis Ihr dort seid, sollte ich auch alles vorbereitet haben und online gehen können.\"$B$B\"Eskortiert ihn sicher bis zur Küste und kommt dann zu mir nach Booty Bay! Oglethorpe Obnoticus - Ende!\"",objectives={"Eskortiert OOX-09/HL zur Küste jenseits der Aussichtsklippen und meldet Euch dann bei Oglethorpe Obnoticus in Booty Bay."}]])
R(837,"Übergriff",[[description="Als wir hier ankamen, war ein Großteil des Landes im Besitz der Grimmhauerstacheleber, die sich als ein ziemlicher Dorn im Auge erwiesen. Durch unsere Anstrengungen konnten wir einen großen Teil von ihnen vertreiben, aber es gibt doch noch welche, die sich in einigen Gebieten verschanzt haben.$b$bDas geht jetzt jedoch schon viel zu lange so. Zu unserer eigenen Sicherheit dürfen wir nicht zulassen, dass sich die Grimmhauer in unserem Land festsetzen. Ihre Lager befinden sich westlich von hier. Sucht nach dem Dornengestrüpp, dann findet Ihr sie. Heute vertreiben wir sie aus Durotar, morgen vielleicht schon aus Kalimdor.",objectives={"Tötet für Gar'Thok in Klingenhügel 4 Stacheleber der Grimmhauer, 4 Späher der Grimmhauer, 4 Staubläufer der Grimmhauer und 4 Schlachtwachen der Grimmhauer."}]])
R(838,"Scholomance",[[description="Auf der Insel Caer Darrow liegt die Scholomance - eine Schule, die als Festung für die Geißel dient. Unser Feind haust dort, wo er sicher Forschungen betreiben kann, die seine Macht stärken. Eine Tür versperrt den Weg, und ganz gleich was wir versuchen, der Zutritt ist nur mit dem richtigen Schlüssel möglich.$B$BApotheker Dithers weiß viel über die Scholomance und hat eine Idee, wie ein Schlüssel zu erlangen ist. Ihr habt mir Euren Wert als jemand bewiesen, der knifflige Dinge erledigen kann; ich vertraue Euch nun diese Aufgabe an. Sprecht mit ihm über diese Angelegenheit.",objectives={"Sprecht mit Apotheker Dithers am Bollwerk, Westliche Pestländer."}]])
R(839,"<UNUSED>")
R(840,"Freiwilliger der Horde",[[description="Hmmm, Ihr seht mir recht stark aus.$B$BHört mal, mein guter Freund Kargal braucht ein paar neue Rekruten für den Dienst im Brachland. Ich weiß, dass Ihr immer nur das Richtige für die Horde tun wollt. Das ist jetzt Eure Chance.$B$BBringt Kargal diesen Anwerbungsbrief und seht, ob er ihn unterzeichnet.",objectives={"Folgt der westlichen Straße aus Klingenhügel ins Brachland und über die Brücke.$B$BMacht bei dem Außenposten der Orcs auf der anderen Seite Halt.$B$BGebt Kargal Battlescar im Brachlandaußenposten Euren Anwerbungsbrief."}]])
R(841,"Eine weitere Kraftquelle?",[[description="Ich stelle mal eine Vermutung an - Ihr habt, welch weltbeendende, ruchlose Tat Ihr auch unternommen habt, diese Tat nicht rechtzeitig beendet. Nein, wartet, noch besser... Ihr habt die Sache in den Sand gesetzt! Nun, was auch immer der Grund sein mag, ich verfüge über eine weitere Kraftquelle, die ich Euch verkaufen werde. Dieses Mal wird sie Euch aber zehn, JAWOHL ZEHN Wasserbeutel eines Wüstenläufers kosten!$B$BDie Zeiten hier sind schwer, $n, und Kraftquellen wachsen nicht auf Bäumen! Hmm, aber was wäre wohl, wenn sie es täten... Vielleicht könnten wir einen Kraftquellenbaum MACHEN...",objectives={"Bringt Chefingenieur Bilgewhizzle in Gadgetzan 10 Wasserbeutel eines Wüstenläufers im Austausch gegen eine weitere Kraftquelle."}]])
R(842,"Crossroads-Wehrpflicht",[[description="Bringt diesen unterzeichneten Anwerbungsbrief nach Crossroads.$B$BSergra Darkthorn, verflucht sei sie, hat dort das Kommando. Sie ist eine grässliche Schamanin, die Euch erst schwindelig redet, bevor Sie Euch etwas Nützliches tun lässt. Thrall ist davon überzeugt, dass sie etwas ganz Besonderes ist, aber ich bin mir da nicht so sicher.$B$BMacht Euch selbst ein Bild davon, Jungspund ...",objectives={"Folgt der Straße von Kargals fernem Farwatch-Außenposten nach Westen.$B$BWendet Euch bei der Einmündung nach links und folgt dann der Straße in südliche Richtung. $B$BSucht Sergra Darkthorn an der Kreuzung zweier Straßen in Crossroads auf."}]])
R(843,"Ganns Rekultivierung",[[description="In Einsamkeit wandere ich auf diesen Straßen.$b$bDie Zwerge Bael Modans haben keinen Respekt vor meinem Land. Entsetzliche Schläge reißen tiefe Wunden in den Boden und brüllende Maschinen zerfetzen die Hügel. Land, das meinem Stamm einst als Heimat und Versorger diente, ist jetzt von zerstörerischen Zwergen durchfurcht.$b$bAlle Versuche, zu einer diplomatischen Einigung zu kommen, sind fehlgeschlagen. Jetzt ist die Zeit für entschlossenes Handeln gekommen.$b$bVertreibt die Zwerge mit Gewalt von der Bael Modan-Ausgrabung und bringt mir das Tagebuch ihres Anführers, Ausgrabungsleiter Khazgorm.",objectives={"Gann Stonespire möchte, dass Ihr 15 Ausgräber von Bael'dun und 5 Großknechte von Bael'dun tötet.$b$bBringt Gann Stonespire dann Khazgorms Tagebuch."}]])
R(844,"Ebenenschreiter-Bedrohung",[[description="Eure erste Beute wird einfach sein.$B$BDie Ebenenschreiter im Osten fallen immer wieder über unsere Lebensmittelvorräte her und sind zu einer Plage geworden.$B$BVernichtet die Ebenenschreiter und bringt mir ihre Schnäbel.",objectives={"Besorgt 7 Ebenenschreiterschnäbel und bringt sie Sergra Darkthorn in Crossroads."}]])
R(845,"Die Zhevras",[[description="Die Zhevras sind etwas wilder als die Ebenenschreiter, auch wenn sie nicht die stärksten Wildtiere im Brachland sind. Aber macht Euch keine Sorgen - wir werden Euch bei Gelegenheit gegen größere Beute ausschicken. Vorerst könnt Ihr jedoch noch ein bisschen Übung gebrauchen.$B$BJagt die Zhevras im Norden und Süden und sammelt ihre Hufe. Bringt sie mir, und vielleicht werden wir Euch als Nächstes eine schwierigere Aufgabe stellen.",objectives={"Erschlagt Zhevra-Läufer, um für Sergra Darkthorn in Crossroads 4 Zhevra-Hufe zu erhalten."}]])
R(846,"Ganns Rache",[[description="Es ist klar, dass ein Ausgrabungsleiter von Sprengstoff und diesen lärmenden Fahrzeugen abhängig ist, um den Boden aufzureißen. Wir müssen damit rechnen, dass schon bald ein neuer Großknecht die Sache übernimmt.$b$bIch möchte den Zwergen ihre eigene Medizin zu schmecken geben. Wenn wir laut diesen Plänen Nitroglyzerin mit Holzbrei und Natriumnitrat mischen, erhalten wir eine Sprengladung. Es ist bekannt, dass die Scharfschützen, Soldaten und Offiziere in der Burg diese Dinge besitzen.$b$bHolt diese Sachen und bringt sie mir; ich werde daraus eine Sprengladung basteln, die die Zwerge so schnell nicht vergessen werden!",objectives={"Gann Stonespire möchte, dass Ihr ihm 6 Phiolen Nitroglyzerin, 6 Teile Holzbrei und 6 Proben Natriumnitrat bringt."}]])
R(847,"Arglist des Raptors",[[description="Diese... diese Macht... Ist das die Macht der Schamanen, die Tor'gan mir zeigen wollte? Ich muss sagen, das ist wirklich interessant. Sagt Tor'gan, dass er mich überzeugt hat... jedenfalls für den Augenblick. Ich werde mir anhören, was er zu sagen hat.",objectives={"Sprecht mit Tor'gan."}]])
R(848,"Pilzsporen",[[description="Die Oasen des Brachlandes verbergen ein Mysterium. In ihren Wassern fließt Lebensenergie, die alle Pflanzen und Wildtiere erquickt, die davon trinken.$B$BErquickt und verändert.$B$BEs gibt einen Pilz, der in der Nähe dieser Oasen wächst. Seine Sporen besitzen Eigenschaften, die wir, die Apotheker Lordaerons, sehr nützlich finden.$B$BBringt mir diese Sporen, dann seid Ihr unserer Dankbarkeit gewiss.",objectives={"Bringt dem Apotheker Helbrim in Crossroads 4 Pilzsporen."}]])
R(849,"Ganns Rache",[[description="Wenn wir uns an Khazgorms Pläne halten, sollte es eigentlich kein Problem sein, eine Sprengladung herzustellen.$b$bAh, fertig.$b$bAlso, $n, ich möchte Euch mit einer besonderen Aufgabe betrauen. Nehmt diese Dynamitstange und jagt damit den Flugapparat bei Bael Modan in die Luft.$b$bDieser Flugapparat ist nicht nur ein wichtiger Bestandteil der Infrastruktur der Grabungsstätte, sondern auch eine Kriegswaffe. Vor allem ist sie aber ein Symbol der Macht und eine Beleidigung des Andenkens an meinen Stamm.$b$bMacht mich stolz, indem Ihr diese heldenhafte Aufgabe erledigt, dann soll es Euer Schaden nicht sein.",objectives={"Zerstört den Flugapparat bei Beal Modan und kehrt dann zu Gann Stonespire zurück."}]])
R(850,"Anführer der Kolkar",[[description="Die Zentauren haben die Tauren seit Jahren geplagt. Die Kolkarzentauren des Brachlandes sind seit kurzem zu einer echten Bedrohung geworden. Normalerweise sind sie in diesen Landen eher unorganisiert, aber es haben sich unter ihnen neue Anführer erhoben. Sie sammeln sich.$B$BWir müssen diese Zentaurenanführer vernichten, um unsere Position hier zu bewahren.$B$BBringt mir den Kopf von Barak Kodobann. Er lagert in der Nähe der vergessenen Teiche im Norden.$B$BBesiegt ihn und kehrt dann zu mir zurück.",objectives={"Bringt Regthar Deathgate westlich von Crossroads Baraks Kopf."}]])
R(851,"Verog der Derwisch",[[description="Der Zentaur Verog der Derwisch durchwandert das Brachland und wird daher schwer auffindbar sein. Er hat jedoch ein Zentaurenkommandozelt bei der brackigen Oase im Südosten. Vielleicht könnt Ihr ihn zu Euch locken.$B$BReist zur brackigen Oase im Südosten und greift Zentauren in der Nähe des Kommandozeltes an. Es wird gefährlich werden, aber wenn Ihr genug Zentauren tötet, werden sie Alarm schlagen. Und Verog wird kommen.$B$BBringt mir seinen Kopf, dann lege ich ihn neben den von Barak Kodobann.",objectives={"Bringt Regthar Deathgate westlich von Crossroads Verogs Kopf."}]])
R(852,"Hezrul Blutmal",[[description="Hezrul Blutmal ist der Anführer der Kolkarzentauren im Brachland. Er ist wild, brutal und schlau. Könnte man ihn besiegen, würde das die Kolkars spalten und zerschlagen und die Bedrohung durch sie enorm entschärfen.$B$BAlso tötet ihn. Und bringt mir genau wie zuvor bei Barak und Verog Hezruls Kopf.$B$BEr führt sein Volk von der blühenden Oase im Süden aus an.",objectives={"Bringt Regthar Deathgate westlich von Crossroads Hezruls Kopf."}]])
R(853,"Apothekerin Zamah",[[description="Ich habe die Sporen, die Ihr mir gabt, zu einer Emulsion verarbeitet. Die muss ich jetzt meiner Kollegin schicken, der Apothekerin Zamah. Wenn Ihr sie ihr bringen könntet, würde sie Euch bestimmt etwas aus ihrem Vorrat alchimistischer Waren anbieten.$B$BSie lebt bei den Teichen der Visionen in einer Höhle unter den Schamanen von Thunder Bluff. Der Pfad zu dieser Höhle ist gut versteckt, aber Ihr könnt ihn am Steilhang der Anhöhe der Geister finden.$B$BBeeilt Euch. Die Emulsion verliert nach einer Weile ihre Wirksamkeit und muss vorher luftdicht verschlossen und weiterverarbeitet sein.",objectives={"Bringt der Apothekerin Zamah in Thunder Bluff die weiterverarbeiteten Sporen, bevor die Zeit abgelaufen ist."}]])
R(854,"Reise nach Crossroads",[[description="Ich habe Eure Ankunft vorausgesehen, junger $C. Aber vielleicht seid Ihr ja gar nicht mehr so jung.$B$BIch glaube, dass es an der Zeit ist, dass Ihr Euch tiefer in dieses Land vorwagt. Ich fühle, dass Ihr zu Größerem berufen seid.$B$BCrossroads wartet auf Euch, denn die Orcs, mit denen wir eng verbunden sind, brauchen Unterstützung. Folgt dieser Straße weiter nach Osten und dann weiter nach Norden bis nach Crossroads. Sucht Thork in seinen Mauern, er hat den Segen der Erdenmutter.",objectives={"Sprecht mit Thork in Crossroads im Brachland."}]])
R(855,"Zentaurenarmschienen",[[description="Die Kolkar sind eine echte Bedrohung für die Besitzansprüche der Horde im Brachland und wir müssen deren Truppen unbedingt dezimieren. Deshalb habe ich eine lohnenswerte Aufgabe für Euch.$B$BErschlagt ihre Krieger, während Ihr Euch auf dem Territorium der Kolkar befindet, und sammelt Zentaurenarmschienen ein. Kommt zurück, wenn Ihr eine ordentliche Menge Armschienen beisammen habt, dann wird Euch die Horde reich belohnen.",objectives={"Bringt Regthar Deathgate westlich von Crossroads 15 Zentaurenarmschienen."}]])
R(856,"<UNUSED>",[[description="Though you have reached the Barrens, your journey is not complete. You must continue on to the Crossroads, where you are needed most.$B$BFollow the road as you were, and turn left where the path gives you the choice. Follow it North until you see the walls of the Crossroads.$B$BJust before you enter, you should see the Ancestral Sage, he will have words of wisdom for you.",objectives={"Continue down the road from Camp Taurajo.$B$BTurn left at the T intersection and continue North.$B$BFollow the path to the Ancestral Sage outside the Crossroads."}]])
R(857,"Die Träne der Monde",[[description="Ich hatte die Macht! In diesen meinen Händen! Und ich möchte sie wiederhaben! Wiederhaben möchte ich sie!$b$bDiese dreckigen Ausgräber haben sie entdeckt... sie war so wunderschön. Die Träne der Monde war die erste größere Entdeckung, die wir in Bael Modan gemacht haben.$b$bSie hätte mir gehören sollen! Mir!$b$bGeneral Twinbraid war eifersüchtig auf die Macht, die sie mir verlieh; er sperrte sie weg, in der Burg. Sagte, sie sei verflucht! Dieser Dummkopf!$b$bAndere wollten sie auch haben und sie mussten daran gehindert werden! Dieser Bastard Twinbraid jagte mich weg.$b$bJetzt möchte ich sie wiederhaben. Wiederhaben möchte ich sie!",objectives={"Feegly der Verbannte möchte, dass Ihr ihm die Träne der Monde zurückbringt."}]])
R(858,"Zündung",[[description="Euch hat nicht etwa Sputtervale geschickt? Ich stecke hier in der Klemme. Ich bin hier reingesprungen, ohne daran zu denken, dass ich einen Schlüssel brauche, um die Antriebswelle des Schredders aufzuschließen. Einer der anderen Schredderbediener fragte mich, ob alles in Ordnung sei, und da bin ich in Panik geraten! Statt ihm zu sagen, dass ich meinen Schlüssel nicht dabei hatte, sagte ich ihm, dass es irgendeine mechanische Störung gäbe.$b$bWir müssen hier weg, und zwar schnellstens! Geht hinauf zum Kontrollraum oben auf dem Kran, der Vorsteher sollte einen Schlüssel für diesen Schredder haben.$b$bHelft mir hier raus!",objectives={"Holt den Zündschlüssel und bringt ihn Wizzlecrank."}]])
R(860,"Sergra Darkthorn",[[description="Wenn Ihr den Pfad der Jäger beschreiten möchtet, dann führt Euch Eure Reise ins Brachland. Die dortigen Wildtiere sind willensstark und unglaublich wild. Ihr werdet beim Jagen dort viel lernen und Euer Geist wird sich entfalten.$B$BSprecht mit Sergra Darkthorn. Sie wird im Brachland Eure Führerin sein.$B$BSergra ist in Crossroads zu finden. Um zu ihr zu gelangen, müsst Ihr von Bloodhoof aus gen Osten ins Brachland reisen und dann an der Weggabelung nach Norden abbiegen. Und seid vorsichtig auf dieser Reise - das Brachland hält für die Unvorbereiteten und Unachtsamen große Gefahren bereit.",objectives={"Sprecht in Crossroads mit Sergra Darkthorn."}]])
R(861,"Der Weg der Jäger",[[description="Euch hat das Jagdfieber gepackt, wie ich sehe. Auch ich war einst wanderlustig...$B$BWollte wandern und jagen. Denn die Jagd ist die größte Ehre für einen Tauren.$B$BWenn Ihr ernsthaft das Leben eines Jägers führen wollt, dann wird Euch Melor Stonehoof den Weg weisen. Er lebt in Thunder Bluff auf der Anhöhe der Jäger.$B$BBringt ihm die Klauen der Flachlandstreuner von Mulgore, um ihm Eure Fertigkeit und Eure Entschlossenheit zu beweisen. Sie sind zäh und schlau - angemessene Beute für einen wie Euch, $C, der so jung wie Ihr auf dem Pfad der Jäger wandeln möchte.",objectives={"Bringt Melor Stonehoof in Thunder Bluff 4 Flachlandstreunerklauen."}]])
R(862,"Grubenratteneintopf",[[description="Ein $C wie Ihr muss hier im Brachland doch ziemlich hungrig sein. Ich bin den ganzen Tag am Verhungern.$b$bIch sag Euch was, ich bereite Euch einen feinen Eintopf zu. Ich brauche nur ein paar Grubenratten.$b$bScheint so, als würden diese dreckigen Zwerge in Bael Modan von unser aller Lieblingsspeise überrannt. Also reist gen Süden nach Bael Modan und bringt mir ein paar Grubenratten.$b$bIhr dürft Euch erst einen erfahrenen Abenteurer nennen, wenn Ihr Euch ein bisschen mit der Rattenjagd beschäftigt habt! Ha!",objectives={"Bringt Grub östlich von Crossroads 8 Grubenratten."}]])
R(863,"Die Flucht",[[description="Ich würde mal sagen, ich kann das nach und nach lernen... Kann ja nicht so schwer sein. Ein paar Knöpfchen hier, ein oder zwei Hebelchen da... Also, seid Ihr bereit zu gehen?",objectives={"Schützt Wizzlecrank und den gestohlenen Goblinschredder auf dem Weg zu Sputtervalve in Ratchet."}]])
R(864,"Kehrt zu Apothekerin Zinge zurück",[[description="\"Wir sind so weit, die Kraftquelle ist entfernt und die Daten sind gesichert. Also dann, sichere Reisen und all das. Ich hoffe, das ruchlose Wissenschaftsexperiment hat sich für Euch ausgezahlt.\"$B$BDer Goblin wendet sich von Euch ab, um sich den Belangen der Gadgetzan Water Company zu widmen. Ihr verstaut das versiegelte Testset sicher für die Reise zurück nach Undercity. Dort wartet Apothekerin Zinge auf Euch und das versiegelte Feldtestset.",objectives={"Bringt das versiegelte Feldtestset nach Undercity zu Apothekerin Zinge."}]])
R(865,"Raptorhörner",[[description="Die Raptoren des Brachlandes sind intelligenter als die Raptoren anderer Länder. Und ich glaube, dass ihre ganze Intelligenz in ihren Hörnern sitzt! Wenn dem so ist, könnte ich ihre Hörner zu Pulver zermahlen und benutzen, um \"Klugheitstränke\" zu kreieren. Dafür würde ich ein Vermögen bekommen!$B$BUnd Ihr könntet mir helfen; sucht und bringt mir intakte Raptorhörner von Bluthornsensenklauen. Sie durchstreifen den Süden sowie den Norden des Brachlandes an der Grenze zum Wald von Ashenvale.",objectives={"Sammelt 5 intakte Raptorhörner von Bluthornsensenklauen und bringt sie Mebok Mizzyrix in Ratchet."}]])
R(866,"Wurzelproben",[[description="Die Kräuter des Brachlandes sind anders als Kräuter anderer Länder. Ihre Eigenschaften sind zwar fast dieselben, aber das Oasenwasser hier verändert die Pflanzen; sie sind ein klein bisschen anders.$B$BIch möchte diese Unterschiede studieren... um zu sehen, ob man daraus nicht Kapital schlagen kann!$B$BFalls Ihr in der Kräuterkunde bewandert seid, sammelt doch ein paar Wurzelproben der Kräuter, die Ihr im Brachland findet. Bringt mir diese Proben, damit ich sie mit Kräutern aus anderen Regionen vergleichen kann.",objectives={"Bringt Mebok Mizzyrix in Ratchet 8 Wurzelproben."}]])
R(867,"Räuberische Harpyien",[[description="Die verdammten Harpyien haben unsere Karawanen lang genug geplündert; es ist an der Zeit, dass wir einigen von ihnen die Hälse abschneiden und ihre Anzahl verkleinern.$B$BIch hab mich bei ihren Nestern mal ein bisschen umgeschaut und herausgefunden, wer da wen anführt. Der vernichtendste Angriff wird einen guten Teil ihrer niederen Befehlskette zerstören und dann können wir uns bis zur Spitze vorarbeiten.$B$BWir fangen langsam an; schaltet die Harpyien der Hexenschwingen und Wildfedern der Hexenschwingen im Nordwesten aus und bringt mir 8 Krallen der Hexenschwingen. Das sollte ein guter Anfang sein...",objectives={"Sammelt 8 Krallen der Hexenschwingen.$B$BBringt sie Darsok Swiftdagger in Crossroads."}]])
R(868,"Eierjagd",[[description="He, $N. Man hat mich nach Crossroads geschickt, damit ich über das Land wache und meinen Meistern in Orgrimmar über eventuelle Vorkommnisse berichte.$B$BEines meiner Studienobjekte sind die insektenartigen Kreaturen, die man im Süden auf dem Feld der Riesen findet. Wir wissen nur wenig über diese Kreaturen, also haben wir es uns zur Aufgabe gemacht, mehr über sie zu erfahren. Sie scheinen intelligent zu sein, intelligenter als normale Tiere.$B$BNehmt diese Grabgabel und grabt ein paar ihrer Eier aus den Hügeln aus, aber seid vorsichtig: einmal aufgeschreckt, werden sie Euch angreifen.",objectives={"Bringt Korran in Crossroads 12 Silithideneier und die Grabgabel."}]])
R(869,"Raptorendiebe",[[description="Vor kurzem wurde eine Ladung Silber aus unserem Wachturm entwendet. Sie war als Sold für die Crossroads-Wachen gedacht und wir wollen das Silber zurückhaben.$B$BDas Seltsamste daran ist... wir haben einen der Diebe in der Nacht des Raubes erwischt. Und... es war ein Raptor! Unglaublich!$B$BIch weiß nicht, wofür Raptoren Silber brauchen könnten. Aber das ist mir auch egal - ich will die Raptoren tot sehen, damit sie uns nicht wieder bestehlen!$B$BJagt Raptoren im Brachland. Sammelt ihre Köpfe für mich!",objectives={"Bringt Gazrog in Crossroads 12 Raptorenköpfe."}]])
R(870,"Die vergessenen Teiche",[[description="Vor langer Zeit war das Brachland ein üppiger Ort voller Leben. Aber Krieg und Katastrophen verheerten das Land, verbrannten es und jetzt ist es nur noch eine ausgedörrte Hülse. So ist es nun einmal und es macht mich traurig.$B$BIn den letzten Jahren jedoch sind Oasen im Brachland entstanden und das Leben blüht wieder auf. Und wir Druiden spüren eine Macht von ganz tief unten an die Oberfläche dringen.$B$BWir müssen ihre Quelle finden. Reist zu den vergessenen Teichen nordwestlich von Crossroads. Sucht in den dortigen Gewässern nach einer Quelle der Macht und kommt dann hierher zurück.",objectives={"Berichtet Tonga Runetotem von Euren Entdeckungen."}]])
R(871,"Vereitelung der Angriffe",[[description="Alle Stacheleber sind unsere Feinde, $N. Manche sind nur lästiger als andere.$B$BDer Grimmhauerstamm hat unsere Nachschublinien von Durotar aus angegriffen, was uns nicht wenig Ärger bereitet. Ich habe Späher ausgeschickt, um den Anführer dieser Überfälle zu finden, aber bis es so weit ist, könnte es uns schon helfen, wenn Ihr diese dreckigen Schweinemenschen etwas dezimieren würdet.$B$BBeginnt im Nordosten in Richtung Durotar. Ihr könnt ihre Baue immer an den riesigen, dornigen Ranken erkennen, die aus dem Boden wachsen. Sucht sie und erschlagt sie.",objectives={"Tötet 8 Wassersucher, 8 Dornwirker sowie 3 Jäger des Grimmhauerstamms und kehrt dann zu Thork in Crossroads zurück."}]])
R(872,"Das Ende der Unterbrechungen",[[description="Einer meiner Späher war Zeuge eines Angriffs auf eine Karawane aus Durotar, $N. Die Übeltäter waren in der Tat vom Grimmhauerstamm der Stacheleber. Ein ganz bestimmter Stacheleber führte den Überfall an: Kreenig Grantelschnauze. Man hat ihn nordöstlich von hier gesehen, gleich südlich der Straße von Durotar. Wenn diese Bedrohung jemals ein Ende finden soll, dann muss Kreenig sterben.$B$BDamit diese Angriffe auch wirklich aufhören, würde ich sagen, dass wir das Ganze auf die Spitze treiben sollten. Tötet Kreenig und andere seines Stammes und kehrt dann zu mir zurück, wenn Ihr seine Hauer habt.",objectives={"Tötet 8 Geomanten der Grimmhauer, 8 Verteidiger der Grimmhauer und Kreenig Grantelschnauze.$B$BBringt dann Thork in Crossroads Kreenig Grantelschnauzes Hauer."}]])
R(873,"Isha Awak",[[description="Isha Awak ist der Herr über diese Gewässer. Groß ist seine Kraft und edel sein Stolz. Die Menschen an der Küste fürchten ihn, denn er hat großen Schaden unter ihnen angerichtet.$B$BIch jedoch fürchte ihn nicht. Ich bin froh, dass er hier ist. Er ist eine würdige Herausforderung und eine ehrenhafte Beute.$B$BWenn Ihr bereit seid, schwimmt hinaus und sucht nach Isha Awak, der Tiefsten Verdammnis.$B$BSein Geist wohnt in seinem Herzen, und dieses schlagen zu hören heißt, Euer Schicksal zu kennen.",objectives={"Bringt Mahren Skyseer das Herz von Isha Awak."}]])
R(874,"Mahren Skyseer",[[description="Ihr habt die Wildtiere des Brachlandes gejagt. Euer Geist ist stark. Ein Jäger muss jedoch immer vorbereitet sein. Ein wahrer Jäger kann auf allen Pfaden seine Beute finden. Weder Berg noch Sumpf wird ihn wanken lassen.$B$BNicht einmal das Meer.$B$BSucht meine Schwester Mahren. Sie jagt die großen Wassertiere entlang der Küste. Sie wird Euch etwas über sie lehren.$B$BSeid jedoch vorsichtig, während Ihr nach ihr sucht, denn die Küste des Brachlandes ist in den Händen der Menschen.",objectives={"Sprecht mit Mahren Skyseer."}]])
R(875,"Offiziere der Harpyien",[[description="Hahaha, $N. Ihr wollt noch mehr? Gut, das hör ich gern.$B$BDieses Mal möchte ich, dass Ihr ein paar der Offiziere der Harpyien in den trockenen Hügeln meuchelt. Nur Töter der Hexenschwingen können Offiziere werden und Ihr erkennt sie an den Ringen, die sie tragen. Sie sind ein übler Haufen, aber sie führen ein paar der Unterlinge in diesem Gebiet an. Schaltet Ihr 6 davon aus, wird das ein Entscheidungsschlag gegen ihr Matriarchat sein.$B$BSorgt dafür, dass sie schmerzvoll sterben, $n. Wir möchten, dass diese Dirnen von Harpyien lernen, wie wahnwitzig es ist, sich mit der Horde anzulegen.",objectives={"Sammelt 6 Harpyienoffiziersringe von den Tötern der Hexenschwingen und kehrt dann zu Darsok Swiftdagger in Crossroads zurück."}]])
R(876,"Serena Blutfeder",[[description="Ihr habt das mit den Offizieren und Unterlingen so gut erledigt, dass ich Euch noch um einen letzten Dienst bitten möchte.$B$BSerena Blutfeder ist die Schwester einer Harpyie namens Blutfeder, die Rexxar vor einer ganzen Weile erschlug. Offensichtlich wurden die Karawanen der Horde angegriffen, um ihre Schwester zu rächen.$B$BIch möchte, dass Ihr ihr die Kehle durchschneidet und mir ihren Kopf bringt. Er soll die nächste Karawane schmücken, die wir losschicken... Gebt diesen Harpyien etwas, über das sie nachdenken können.",objectives={"Erschlagt Serena Blutfeder und bringt Darsok Swiftdagger in Crossroads ihren Kopf."}]])
R(877,"Die brackige Oase",[[description="Erdrisse wie jene, die Ihr bei den vergessenen Teichen gefunden habt, könnte es auch bei anderen Oasen im Brachland geben. Wenn es so ist, sind diese Risse vielleicht die Lebensquelle dieser Oasen.$B$BWir müssen das überprüfen.$B$BHier, nehmt diese Samen. Sie sind tot und unfruchtbar, aber bringt sie dennoch zur brackigen Oase im Südosten. Falls es dort einen Riss gibt, legt die Samen hinein und ... wartet ab.",objectives={"Kehrt zu Tonga in Crossroads zurück, nachdem Ihr die brackige Oase untersucht habt."}]])
R(878,"Stämme im Krieg",[[description="Ihr müsst meine Feinde schlagen. <schnaubt> Ihr müsst Quetschzahn und dem Grimmhauerstamm helfen, indem Ihr die Borstennacken schwächt. Beide Stämme sind sehr spirituell - gebunden an die Erde und ihre Kraft. <schnaubt> Sie gibt uns Stärke in allen Dingen... besonders im Krieg.$B$BWenn ihr herausfinden wollt, wer Thork <schnaubt> und der Horde wirklich solche Angst bereitet, dann helft Quetschzahn! Ihr greift die spirituellen Anführer der Borstennacken im Norden an und schwächt sie, sodass die Grimmhauer sie besiegen und das Brachland beherrschen können.",objectives={"Erledigt 6 Wassersucher der Borstennacken, 12 Dornenwirker der Borstennacken sowie 12 Geomanten der Borstennacken und kehrt zu Quetschzahn im Camp Taurajo im Brachland zurück."}]])
R(879,"Verräter in den eigenen Reihen",[[description="Drei meines Stammes kamen aus dem Kral, um die Überfälle gegen die Horde anzuführen, $R. <schnaubt> Sie sind ruchlos und schlau und wenn Ihr sie besiegt, dann werden Crossroads und auch der Großteil des Brachlandes Frieden haben... <schnaubt> zumindest vor dem Grimmhauerstamm. <schnaubt>$B$BSucht nach Nak, Kuz und Lok Orcbane. Sie befinden sich weit im Süden des Brachlandes. Einer ist ein Zauberer, ein weiterer ein Fährtenleser und ihr Anführer, den sie Orcbane nennen, <schnaubt> ist ein Krieger. Tötet sie, $R, so wie sie mich töteten.",objectives={"Tötet Nak, Kuz und Lok Orcbane und bringt Quetschzahn im Camp Taurajo im Brachland ihre Schädel."}]])
R(880,"Veränderte Wesen",[[description="Eure Entdeckungen sind erstaunlich, $N. Diese Oasen haben Eigenschaften, die von einer Quelle außerhalb stammen müssen. Oder vielleicht von einer inwärtigen.$B$BIch muss wissen, auf welche Weise diese Felsspalten die Wildtiere beeinflussen, die vom Wasser der Oasen trinken.$B$BJagt Oasen-Schnappkiefer in der blühenden Oase und der brackigen Oase. Bringt mir ihre Schalen, damit ich sie untersuchen kann.",objectives={"Bringt Tonga Runetotem in Crossroads 8 veränderte Schnappkieferschalen."}]])
R(881,"Echeyakee",[[description="Whitemist, Echeyakee in der Sprache der Tauren, ist der König der Savannenkatzen. Er jagt mit solcher Verstohlenheit, dass man sagt, er sei wie ein dünner, weißer Nebel auf der Erde. Und er tötet so schnell, dass seine Beute weder Angst noch Schmerz verspürt.$B$BDie Tauren sagen, er sei sowohl Gnade als auch Tod.$B$BIhr werdet erfahren, ob das wahr ist, denn ich schicke Euch aus, um Echeyakee zu jagen. Sein Unterschlupf befindet sich im Nordosten von Crossroads, zwischen den Knochen des riesigen Kodos.$B$BGeht jetzt. Blast dieses Horn, wenn Ihr seinen Unterschlupf erreicht. Blast das Horn und er wird kommen.",objectives={"Bringt Sergra Darkthorn in Crossroads Echeyakees Balg."}]])
R(882,"Ishamuhale",[[description="Ishamuhale - Speerzahn - ist der wildeste Bluthornraptor des Brachlandes. Er jagt weder zum Spaß noch für Nahrung. Er jagt, weil Jagen seine Leidenschaft ist. Er tötet, weil Töten seine Natur ist.$B$BUnd Ihr werdet Euch mit seiner Natur vertraut machen, $N, denn Euer Weg folgt jetzt den Krallenspuren Ishamuhales.$B$BBeginnt mit der Jagd. Erlegt seine Lieblingsbeute, ein Zhevra, und bringt den Kadaver zum toten Baum im Nordwesten von Ratchet. Ishamuhale wird den Kadaver riechen und von ihm angezogen werden.$B$BSeid bereit, wenn er kommt.",objectives={"Bringt Jorn Skyseer im Camp Taurajo Ishamuhales Fangzahn."}]])
R(883,"Lakota'mani",[[description="Lakota'manis Huf ist ein Symbol für die Kraft der großen Kodos.",objectives={"Bringt Jorn Skyseer im Camp Taurajo Lakota'manis Huf."}]])
R(884,"Owatanka",[[description="Wenn man Owatankas Schwanzstachel berührt, stieben Funken auf.",objectives={"Bringt Jorn Skyseer im Camp Taurajo Owatankas Schwanzstachel."}]])
R(885,"Washte Pawne",[[description="Eine Berührung mit der Feder von Washte Pawne ist schmerzhaft.",objectives={"Bringt Jorn Skyseer im Camp Taurajo Washte Pawnes Feder."}]])
R(886,"Die Oasen des Brachlandes",[[description="Die Druiden von Thunder Bluff spüren eine große Macht, die östlich von Mulgore ins Brachland sickert.$B$BTonga Runetotem wurde entsandt, um die Quelle dieser Macht ausfindig zu machen, aber wir befürchten, dass er Hilfe brauchen wird.$B$BReist ins Brachland und sprecht mit Tonga. Er wird in Crossroads sein. Um dorthin zu gelangen, folgt der Straße von Bloodhoof aus nach Osten. Betretet das Brachland und wendet Euch bei der Weggabelung weiter nach Norden. Geht weiter Richtung Norden, dann gelangt Ihr nach Crossroads.$B$BUnd haltet Euch immer auf der Straße, $N, denn das Brachland ist ein raues Land.",objectives={"Sprecht in Crossroads mit Tonga Runetotem."}]])
R(887,"Südmeerfreibeuter",[[description="Ich wünschte, Vize-Admiral Grezzlik würde bessere Arbeit bei der Sicherung der Meere für unsere Handelsschiffe leisten. Bei all dem Gold, das die Handelsbarone in die Handelsflotten gesteckt haben, macht es mich rasend zu sehen, wie viele Piraten unbehelligt unterwegs sind, meine Schiffe überfallen und meine Waren stehlen!$b$bMir kam zu Ohren, dass die Südmeerfreibeuter südlich von hier ein Lager aufgeschlagen haben. Sie sind mir ein echter Dorn im Auge, und wenn sich Grezzlik nicht um sie kümmert, könnt Ihr mir vielleicht helfen, sie loszuwerden?",objectives={"Tötet für Gazlowe in Ratchet 12 Briganten der Südmeerfreibeuter und 6 Kanoniere der Südmeerfreibeuter."}]])
R(888,"Gestohlene Beute",[[description="Ich hätte zwar gern, dass Ihr mir all meine Waren zurückbringt, aber das dürfte wohl unmöglich sein. Es gibt jedoch ein paar Dinge, die ich unbedingt wiederhaben muss!$b$bWie Ihr seht, ist mein Observatorium fast einsatzbereit, aber es fehlt noch die kleinere der zwei Linsen. Die erste Linse ist mit der Karawane aus Durotar gekommen, aber die zweite wurde per Schiff verschickt und ist nie hier eingetroffen. Ebenso ist meine Stiefellieferung von Drizzlik aus Booty Bay nicht hier angekommen!$b$bBegebt Euch zum Piratenlager und seht mal nach, ob Ihr die Dinge dort finden könnt.",objectives={"Bringt Gazlowe in Ratchet die Stiefellieferung und die Teleskoplinse zurück."}]])
R(889,"Geist des Windes",[[description="Wenn die Ranken aus der Erde brechen, treten oftmals auch Mineralvorkommen an die Oberfläche.$B$BEin ganz spezielles Mineral, das in der Nähe der Ranken zu finden ist, heißt Bluterz; der Borstennackenstamm glaubt, das Bluterz sei heilig und ein Teil von Agammagans Körper. Sie tragen manchmal Splitter davon als Glücksbringer bei sich.$B$BIch glaube, ich könnte aus diesem Erz eine neue Legierung herstellen, wenn ich genug davon hätte. Sucht südlich von hier auf der anderen Seite des ausgetrockneten Flussbetts nach Stammesmitgliedern der Borstennacken und bringt mir so viele Blutsplitter, wie Ihr könnt.",objectives={"Bringt Tatternack Steelforge in Crossroads 20 Blutsplitter."}]])
R(890,"Die verloren gegangene Lieferung",[[description="Ich warte schon eine Ewigkeit auf meine letzte Warenlieferung aus Booty Bay! Ich bin mir ziemlich sicher, dass die Seeräuber sie gestohlen haben; würdet Ihr wohl, nur um sicher zu sein, zu den Docks gehen und Dizzywig fragen, ob meine Waren vielleicht ohne mein Wissen bereits ins Lagerhaus gebracht wurden?$b$bHier, nehmt mein Geschäftsbuch mit zu Dizzywig, damit er meine Inventaraufzeichnungen mit seinen Büchern gegenprüft.",objectives={"Bringt Werftmeister Dizzywig Gazlowes Geschäftsbuch."}]])
R(891,"Die Kanonen von Northwatch",[[description="Wieder ist ein Schiff meiner Flotte diesen übereifrigen Menschen der Feste Northwatch in die Hände gefallen!$b$bMan muss sich um diese Bastarde kümmern. Ihr Verfolgungswahn hat sie in eine Art Raserei versetzt. Diese schießwütigen, rücksichtslosen Rüpel schießen auf alles, was sich bewegt.$b$bReist gen Süden entlang der Händlerküste zur Feste und belagert ihre Streitkräfte. Bringt mir die Medaillen ihrer Soldaten als Beweis. Und erschlagt um meiner Flotte willen Captain Hellstieg und ihre übereifrigen Kanoniere!",objectives={"Kapitän Thalo'thas Brightsun aus Ratchet möchte, dass Ihr 10 Medaillen von Theramore sammelt und Captain Hellstieg, Kanonier Knoch und Kanonier Hecksler tötet."}]])
R(892,"Die verloren gegangene Lieferung",[[description="Laut meinen Aufzeichnungen ist alles in Ordnung, $n. Geht zurück und sagt Gazlowe, dass er wohl Pech gehabt hat. Es würde mich nicht überraschen, wenn sich die Piraten seine Waren geschnappt hätten.$b$bIch kann leider nicht mehr für ihn tun. Oh... Ihr könnt ihm allerdings sagen, dass ich ein paar Dinge aus Undermine für ihn habe, falls er die Zeit findet, sie abzuholen.",objectives={"Bringt Gazlowe in Ratchet sein Geschäftsbuch zurück."}]])
R(893,"Ausgewählte Waffen",[[description="Die Stacheleber des Grimmhauerstamms im Süden, hinter dem Feld der Riesen, haben keine erfahrenen Schmiede, soweit ich weiß, aber Sie haben anscheinend begonnen, stabilere Waffen zu entwickeln. Ich hätte gern ein paar verschiedene Arten davon, um etwas über ihre Techniken zu erfahren, so möglich.$B$BWenn Ihr der Horde Ehre bringen wollt, dann bringt mir Exemplare von ihren Waffen. Besorgt mir einen Dolch von ihren Schleichern, einen Zauberstab von ihren Sehern und einen Schild von ihren Kriegsberserkern. Das sollte reichen!",objectives={"Bringt Tatternack Steelforge im Camp Taurajo im Brachland einen Grimmhauerrückenstecher, einen verkohlten Grimmhauerzauberstab und einen Grimmhauerkriegsschild."}]])
R(894,"Samophlang",[[description="Die Venture Company hat weit nördlich von hier, südwestlich des Schlickermoores, eine kleine Forschungseinrichtung errichtet. Was die Leute dort tun, weiß ich nicht genau, aber ich habe herausgefunden, dass sie dort mit etwas experimentieren, das 'Samophlang' genannt wird.$b$bWas zum Teufel ist ein Samophlang? Na ja, was immer es auch ist, ich möchte es untersuchen, also brauche ich jemanden, der eines beschafft.$b$bIch habe ein Exemplar der Bedienungsanleitung für ihr Steuersystem in die Finger bekommen; Ihr solltet also herausfinden können, wie man das Samophlang daraus entfernt.",objectives={"Verschafft Euch Zugang zur Steuerkonsole in der Forschungseinrichtung der Venture Company."}]])
R(895,"GESUCHT: Baron Küstenschipper",[[description="GESUCHT!$b$bBaron Küstenschipper, Kapitän der GNADENLOS$b$bCaptain Küstenschipper aus Gilneas befehligt Schiffe der Südmeerfreibeuter und wird wegen Piraterie gesucht. Seine Überreste müssen in noch erkennbarem Zustand sein!$b$b- Gazlowe",objectives={"Bringt Gazlowe in Ratchet Baron Küstenschippers Kopf."}]])
R(896,"Des Minenarbeiters Vermögen",[[description="Als Werftmeister eines so geschäftigen Hafens wie Ratchet habe ich mein Ohr immer am Puls der Zeit. Ich weiß alles über den Verkehr von Waren und Geld zwischen hier und Booty Bay.$b$bDie jüngste Neuigkeit, die ich erfahren habe, betrifft die Felsadermine der Venture Company nordöstlich des Schlickermoores. Einer der Minenarbeiter hat dort einen faustgroßen Smaragd gefunden. Ich kenne ein paar Käufer, die sich die Finger nach so etwas ablecken würden... und ich würde bei einem Verkauf Halbe-Halbe machen.",objectives={"Beschafft Euch von einem der Vorarbeiter oder Vollstrecker der Venture Company den Katzenaugensmaragd und bringt ihn zu Dizzywig in Ratchet."}]])
R(897,"Der Ernter",[[description="Diese seltsame, insektenartige Kreatur scheint außerhalb der natürlichen Ordnung zu stehen, so als würde sie nicht ins Brachland gehören.",objectives={"Bringt den Ernterkopf zu Jorn Skyseer."}]])
R(898,"Aus der Gefangenschaft befreit",[[description="Endlich! Jemand rettet mich!$b$bIch kann es nicht glauben, dass Ihr an den Wachen vorbeigekommen seid. Diese Fanatiker aus Theramore müssen verrückt sein. Sie haben unser Schiff versenkt und mich, den einzigen Überlebenden, eingesperrt. Sie nannten mich ihren Feind und eine Gefahr für die Allianz.$b$bIch! Eine Gefahr für diesen Riesenschwindel, den sie Allianz nennen? Ich war Decksmann auf einem Fuseltransporter zwischen Ratchet und Booty Bay.$b$bGenug geredet. Helft Ihr mir, zurückzukommen nach Ratchet, ja? Lasst es mich wissen, wenn Ihr bereit seid, hier auszubrechen.",objectives={"Begleitet Gilthares Firebough sicher zurück zu Kapitän Brightsun in Ratchet."}]])
R(899,"Von Hass zerfressen",[[description="Vielleicht kennt Ihr diesen Schmerz der Ungewissheit, $C, vielleicht auch nicht. Doch wisset: Ich stehe hier jeden Tag, vom Aufgang der Sonne bis zu ihrem Untergang, und suche den Horizont nach diesen Monstern ab. Ich habe jeden Schweinemenschen getötet, den ich seitdem gesehen habe, doch der Durst nach ihrem Blut ist noch lange nicht gestillt. Vielleicht hätte ich mich nach Taurajo begeben sollen, statt nördlich nach Crossroads.$B$BIhr, $C, könntet mir helfen.$B$BTötet sie. Tötet so viele Ihr könnt und bringt mir ihre Hauer, dann werden wir ihren Tod miteinander feiern.",objectives={"Bringt Mankrik in Crossroads 60 Stacheleberhauer der Borstennacken."}]])
R(900,"Samophlang",[[description="Die drei Steuerventile sind momentan geöffnet. Die verschiedenen Anzeigen der Steuerkonsole führen Euch zu der Annahme, dass man sie zunächst schließen muss, bevor der Apparat ausgeschaltet werden kann.",objectives={"Schließt das Treibstoffzufuhrventil, das Regelventil und das Hauptsteuerventil, und benutzt dann noch einmal die Steuerkonsole."}]])
R(901,"Samophlang",[[description="Da der Apparat jetzt ausgeschaltet ist, kann die Steuerkonsole geöffnet und das Samophlang entfernt werden. Alles andere sollte unangetastet bleiben und Ihr benötigt jetzt nur noch den Schlüssel, mit dem die Konsole geöffnet werden kann.",objectives={"Besorgt Euch bei Tüftler Sniggles den Konsolenschlüssel, um damit die Steuerkonsole zu öffnen."}]])
R(902,"Samophlang",[[description="Nach dem Öffnen der Front der Steuerkonsole zeigt sich ein dichtes Gewirr aus Kabeln, Schläuchen und anderen seltsamen, mechanischen Objekten - die meisten davon scheinen keinen praktischen Nutzen zu haben. Ihr schiebt sie beiseite und arbeitet Euch tiefer in die Konsole vor, bis Ihr schließlich das Samophlang gefunden habt. Mit einem Ruck zieht Ihr es aus der Halterung.",objectives={"Bringt das Samophlang zu Sputtervalve in Ratchet."}]])
R(903,"Streuner des Brachlandes",[[description="Es ist nun an der Zeit, etwas zu jagen, das sich wirklich wehrt. Die Streuner des Brachlandes sind von zäher Art. Zäh, erfinderisch, listig... und tödlich. Ihr findet sie zwischen den hohen Gräsern. Ihr werdet viele südwestlich von Crossroads finden.$B$BSeid vorsichtig, wenn Ihr sie jagt, $n, oder Ihr werdet feststellen, dass Ihr nicht mehr Jäger, sondern Gejagter seid.",objectives={"Besorgt für Sergra Darkthorn in Crossroads 7 Streunerklauen von den Savannenstreunern."}]])
R(904,"<UNUSED>")
R(905,"Die wütenden Sensenklauen",[[description="Tja, $N, die Jagd wird schwieriger. Jetzt müsst Ihr Eure Beute besiegen und dann Euren Weg zu ihrem Unterschlupf finden.$B$BJagt die Bluthornraptoren im Süden. Erledigt sie und nehmt Euch die Federn, die sie tragen. Legt die Federn in die Sensenklauennester südwestlich der brackigen Oase. Zeigt ihren Brüdern, dass Ihr sie nicht fürchtet!",objectives={"Tötet Bluthornraptoren und nehmt ihre Federn mit. Benutzt die Federn bei den drei Sensenklauennestern. Kehrt zu Sergra Darkthorn in Crossroads zurück."}]])
R(906,"Verräter in den eigenen Reihen",[[description="Bringt Loks Kopf zu Thork in Crossroads, $R. <schnaubt> Er sollte ohne Worte wissen, was meinem Stamm zugestoßen ist - ha, nicht dass er denken würde, Quetschzahn hätte bei <schnaubt> solchen Dingen geholfen. Aber ich bin sicher, er wird Euch für das Ausführen einer solch großen Tat belohnen. <schnaubt>$B$BIch werde Euch auch weiterhin mit Agammagans Macht segnen, solange ich in diesem Käfig verbleibe, $R. Bis dann, lebt wohl.",objectives={"Bringt Loks Kopf zu Thork in Crossroads im Brachland."}]])
R(907,"Wütende Donnerechsen",[[description="Nun denn, $n, jetzt müsst Ihr den großen Donnerechsen gegenübertreten. Diese Bestien sind so groß, dass der Boden erbebt, wenn sie über die Ebenen stampfen. Seid vorsichtig, wenn Ihr gegen sie kämpft, denn ein einziger falscher Schritt, und schon findet Ihr Euch unter ihren Füßen wieder.$B$BIhr findet die Donnerechsen im Südlichen Brachland. Man kennt sie als Sturmschnauzen, Sturmechsen und Donnerköpfe. Kehrt zu mir zurück, nachdem Ihr sie überwältigt habt.",objectives={"Bringt das Blut von 3 Donnerechsen ins Camp Taurajo zu Jorn Skyseer."}]])
R(908,"Inmitten der Ruinen",[[description="Die Twilight-Hammer sind in die Mondschreinruinen der Blackfathom-Tiefe eingezogen. Ihre Gegenwart kann nur dazu dienen, die Elemente gegen uns aufzubringen. Wenn dem kein Einhalt geboten wird, gehört ihnen diese Region bald ganz und gar.$B$B$N, geht nach Blackfathom und findet den Fathom-Stein der Ruinen. Er dürfte irgendwo in deren Nähe im Wasser liegen. Darin ist ein Fathom-Kern. Das ist ein Gerät, das, wenn man es richtig abliest, eine Aufstellung über alle Aktivitäten der Elementare liefert. Wenn ich es habe, können der Irdene Ring und ich vielleicht etwas tun, um sie aufzuhalten.",objectives={"Bringt den Fathom-Kern zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale."}]])
R(909,"Baron Aquanis",[[description="Der besiegte Wasserelementar hat eine seltsame Wasserkugel zurückgelassen. Ihr vermutet, dass das Objekt die Kreatur irgendwie mit Energie versorgte. In der Kugel schwappt eine faulig aussehende Wassergestalt herum. Die Kugel selbst zeigt sich unbeeindruckt von jeder äußerlichen Krafteinwirkung.$B$BWenn irgendwer aus diesem Gegenstand schlau wird, wäre das wohl Je'neu Sancrea vom Irdenen Ring. Er befindet sich im Zoram'gar-Außenposten der Horde in Ashenvale.",objectives={"Bringt die seltsame Wasserkugel zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale."}]])
R(910,"Unten an den Docks",[[description="Ich hab' Geschichten gehört von riesigen Schiffen, die zwischen Ratschet und Beutebucht hin- und hersegeln. Es wäre so toll, auf dem Ozean zu segeln und fantastische Seeschlachten erleben zu können. Wenn ich erwachsen bin, werde ich vielleicht auch ein mächtiger Seefahrer der Horde!$B$BKönnt Ihr mir bitte die Docks von Ratschet zeigen? Ich verspreche, auch nicht ins Wasser zu fallen oder Ärger zu machen. Ich will nur einmal die großen Schiffe sehen und das salzige Meerwasser riechen!",objectives={"Bringt Euren Schützling zu den Docks von Ratschet im Brachland."}]])
R(911,"Das Tor zur Grenze",[[description="Sie sagen, dass das Eschental das neue Grenzland und der Schutzwall von Mor'shan im Brachland das Tor dorthin wären. Es wäre so toll, ein Pionier zu sein und alles, was man zum Überleben braucht, in der Wildnis zu sammeln! Sie sagen, dass dies der Ort ist, an welchem in Zukunft die Horde und die Allianz ihre Kämpfe austragen werden. Ich möchte unbedingt dahin!$B$BKönnen wir bitte zum Schutzwall von Mor'shan gehen? Ich würde so gerne mal das Grenzland sehen! Ich möchte sehen, wie die Horde diese stinkenden Nachtelfen von dort vertreibt.",objectives={"Begleitet Euren Schützling zum Schutzwall von Mor'shan im nördlichen Teil des Brachlands, kurz bevor man das Eschental betritt."}]])
R(912,"Stonesplinter Trogg Disguise")
R(913,"Der Ruf des Donnerfalken",[[description="Der Donnerfalke, $N, ist eine ungestümes Wildtier. Es ist an der Zeit für Euch, ihm gegenüberzutreten. Ihr müsst herausfinden, wo er umherstreift, und mir seine Flügel als Beweis für Eure erfolgreiche Jagd bringen.$B$BWenn Ihr das tut, wird Eure Zeit mit mir sich ihrem Ende nähern.",objectives={"Sucht und erschlagt einen Donnerfalken und bringt Jorn Skyseer in Taurajo seine Flügel."}]])
R(914,"Anführer der Giftzähne",[[description="Die Druiden in den Höhlen des Wehklagens, die Druiden des Giftzahns, sind eine Verirrung der Natur. Einst gehörten sie einem Orden edler Druiden an, deren Plan es war, das Brachland zu heilen, doch jetzt trachten sie danach, das Land ihren eigenen verderbten Träumen gleichzumachen.$B$BDie Druiden des Giftzahns haben vier Anführer, und jeder besitzt einen Traumedelstein. Selbst jetzt noch verfolgen mich ihre Gesichter! Besiegt die Anführer und bringt mir ihre Edelsteine, dann wird das Brachland endlich wieder Frieden haben.$B$BGeht, $n. Sie halten sich tief in den Höhlen des Wehklagens verborgen.",objectives={"Bringt die Edelsteine von Kobrahn, Anacondra, Pythas und Serpentis nach Thunder Bluff zu Nara Wildmane."}]])
R(915,"Lecker Eis",[[description="EISCREME! Oh, könnt Ihr mir bitte, bitte, bitte, etwas Eiscreme besorgen? Am liebsten mag ich Erdbeere und es gibt einfach kein besseres Erdbeereis als das von Tigule und Foror. Das ist mein liebstes Eis auf der ganzen Welt!$B$BFrüher gab es das immer auf der Rennstrecke in der Schimmernden Ebene, aber ich habe mal gehört, dass man es jetzt auch in der Stadt kaufen kann. Kriege ich bitte eins? Bitte? Am liebsten Tigules und Forors Eiscreme.",objectives={"Besorgt für Euren Schützling etwas Erdbeereis. Der Kleine scheint die Marke 'Tigules und Forors Eiscreme' zu bevorzugen."}]])
R(916,"Waldwebergift",[[description="Ich kam nach Shadowglen, um hier die Waldweberspinnen zu beobachten, die in der Schattenweberhöhle leben. Sie sind mit einer wesentlich kleineren Spinnenart verwandt. Ich glaube, der Weltbaum hat einen nicht unerheblichen Effekt auf sie und ich hätte gern ein paar Exemplare von ihnen, um dies zu belegen.$B$BAls Erstes hätte ich gern etwas von ihrem Gift. Sammelt Giftbeutel der Waldweberspinnen, die in und um die Schattenweberhöhle herum zu finden sind. Dann kann ich ihren und das Gift ihrer kleineren Verwandten auf Gemeinsamkeiten hin untersuchen.",objectives={"Bringt Gilshalan Windwalker in Aldrassil 10 Waldwebergiftbeutel."}]])
R(917,"Waldweberei",[[description="Jetzt, da ich das Spinnengift habe, hätte ich gern auch ein paar lebende Exemplare, um sie zu studieren. Leider kann ich Euch nicht darum bitten, eine lebende Riesenspinne für mich einzufangen, $C. Eine Riesenspinne kann ich allein sowieso nicht bewältigen!$B$BWenn Ihr mir allerdings ein unausgebrütetes Ei besorgen könntet, wäre es viel einfacher, lebende Exemplare zu bekommen, und ich könnte dafür sorgen, dass die noch nicht ausgeschlüpften Exemplare ordentlich unter Verschluss gehalten werden.$B$BTief in der Schattenweberhöhle gibt es angeblich ein Nest. Bitte, beschafft mir ein Ei aus diesem Nest und bringt es mir.",objectives={"Bringt Gilshalan in Aldrassil ein Waldweberei."}]])
R(918,"Bäumlingssamenkörner",[[description="Die Bäumlinge von Teldrassil sind Naturelementare. In ihnen spiegelt sich in gewisser Weise die natürliche Ordnung von Flora und Fauna unseres großen Baums wider.$B$BDaher ist es höchst beunruhigend zu sehen, dass die Bäumlinge so wütend geworden sind.$B$BIch glaube, es hat etwas mit dem Erdboden zu tun. Ich habe mich viel mit verschiedenen Düngemethoden für Pflanzen beschäftigt und würde sie gern an Bäumlingssamenkörnern ausprobieren. Würdet Ihr bitte in der Gegend des Al'Amethsees ein paar Bäumlingssamenkörner sammeln und mir bringen?",objectives={"Bringt Denalan am Al'Amethsee 8 Bäumlingssamenkörner."}]])
R(919,"Bäumlingssprossen",[[description="Kleine Bäumlinge sprießen rund um das Wasser des Al'Amethsees. Ich fürchte, dass man diesen Schösslingen nicht mehr helfen kann - wir sollten versuchen, sie auszureißen, bevor sie groß genug sind, um Probleme zu bereiten.$B$BWenn Ihr auf Euren Wanderungen um den See Bäumlingssprossen seht, reißt sie bitte aus. Helft dabei, unser Land rein zu halten!",objectives={"Bringt Denalan am Al'Amethsee 12 Bäumlingssprossen."}]])
R(920,"Tenarons Einladung",[[description="Ihr seid $n, nicht wahr? Ich hörte, dass Tenaron nach Euch gefragt hat. Ihr findet ihn in dem am höchsten gelegenen Raum in Aldrassil.$b$bWir mögen zwar ein langes Leben haben, aber Ihr solltet ihn dennoch nicht allzu lang warten lassen.",objectives={"Sprecht in Shadowglen über den Dächern von Aldrassil mit Tenaron Stormgrip."}]])
R(921,"Krone der Erde",[[description="Es ist an der Zeit herauszufinden, was Euer Schicksal ist, $n. Doch bevor Ihr bereit seid, in die Welt hinter unseren verzauberten Wäldern hinauszuziehen, gibt es noch vieles, das Ihr über unsere jüngste Vergangenheit lernen müsst.$b$bSeit der Schlacht am Berg Hyjal hat sich für unser Volk so viel verändert. Nordrassil ist nur noch ein Schatten ihres früheren Selbst, ihre Macht wurde benutzt, um Archimonde in die Knie zu zwingen und die Brennende Legion zurückzutreiben ...$b$bIhr müsst eine Aufgabe erledigen. Geht zum Mondbrunnen nördlich von Aldrassil und bringt mir eine Phiole mit Wasser daraus.",objectives={"Füllt die Kristallphiole und bringt sie Tenaron Stormgrip über den Dächern von Aldrassil."}]])
R(922,"Rellian Greenspyre",[[description="$N, würdet Ihr wohl eines der Samenkörner, die Ihr mir besorgt habt, meinem Freund Rellian Greenspyre bringen? Er ist Druide in Darnassus, und bei unserem letzten Gespräch machte er deutlich, dass er an meiner Arbeit mit den Bäumlingen interessiert sei. Er hatte selbst ein paar Ideen und würde sich über ein Exemplar dieser Samenkörner sicherlich freuen.$B$BDanke, $N. Ihr wart mir eine große Hilfe. Ich hoffe, dass ich Euch eines Tages die Früchte meiner Arbeit zeigen kann.$B$BIhr findet Rellian normalerweise die Wege der Enklave des Cenarius in Darnassus entlangwandernd.",objectives={"Bringt Rellian Greenspyre in Darnassus ein Bäumlingssamenkorn."}]])
R(923,"Tumore",[[description="Bosheit wuchert in den Bäumlingen. Wir versuchen, die Ursache dafür zu finden, aber bis dahin... Aus Sorge um Teldrassils Sicherheit müssen wir alle Bäumlinge fällen, denen nicht mehr geholfen werden kann. Diejenigen, die die Gegend um den Wellspringsee im Norden von Teldrassil durchstreifen, sind am schlimmsten betroffen. Sie müssen ausgemerzt werden!$B$BVernichtet alle Bäumlinge, die Ihr dort findet, und sammelt die moosartigen Tumore, die auf ihnen wachsen. Bringt mir die Tumore, damit ich sie verbrennen kann.",objectives={"Bringt Rellian Greenspyre in Darnassus 5 moosartige Tumore."}]])
R(924,"Die Dämonensaat",[[description="Die Dämonensaat ist ein mächtiges Werkzeug der Brennenden Legion. Sie lebt in einer Höhle des Glutnebelgipfels, oberhalb eines dämonischen Altars des Feuers.$B$BIch habe Kraftsteine vorbereitet, die, wenn sie in der Nähe der Saat platziert werden, deren Verbindung zur Legion unterbrechen.$B$BNehmt einen Stein vom Tisch und bringt ihn zum Altar des Feuers oben auf dem Glutnebelgipfel. Reist nach Westen und bei der Weggabelung weiter nach Norden. Der Gipfel liegt zu Eurer Linken. Die sicherste Aufstiegsmöglichkeit zur Spitze bietet sich an der Nordseite.$B$BUnd beeilt Euch - die Energie des Steins nimmt mit der Zeit ab.",objectives={"Nehmt einen fehlerhaften Kraftstein. Bringt ihn zum Altar des Feuers, bevor dessen Wirkung erlischt, und kehrt dann zu Ak'Zeloth zurück."}]])
R(925,"Cairnes Hufabdruck",[[description="Ich habe gehört, dass Cairne Bluthuf einer der größten Helden ist, den die Horde je gesehen hat. Wenn ich mal groß bin, möchte ich auch ein Held der Horde werden!$B$BKennt Ihr Cairne, $n? Tut Ihr mir einen Gefallen? Kriege ich ein Autogramm von ihm? Ich weiß gar nicht, wie ich ihn ansprechen soll, und wahrscheinlich ist er sowieso viel zu beschäftigt, um mich zu beachten...aber was ist mit Euch? Ihr seid doch genau wie er ein Abenteurer! Euch gibt er bestimmt ein Autogramm!$B$BBitte, $n. Bitte...",objectives={"Reist nach Donnerfels und versucht für Euren Schützling einen Hufabdruck von Cairne Bluthuf zu ergattern."}]])
R(926,"Fehlerhafter Kraftstein")
R(927,"Das moosumschlungene Herz",[[description="Das Herz von Schwarzmoos dem Stinker ist mit einem dunklen, öligen Moos bedeckt. Dass es sich wirklich um ein Herz handelt, kann man eigentlich nur daran erkennen, dass es langsam und rhythmisch schlägt... Ein Herzschlag, der sogar jetzt noch anhält.$B$BVielleicht würde Denalan dieses Herz gern einmal sehen.",objectives={"Bringt Denalan am Al'Amethsee das moosumschlungene Herz."}]])
R(928,"Krone der Erde",[[description="Ich könnte Euch zwar noch so viel mehr über die Mondbrunnen und Teldrassil erzählen, doch leider muss ich Euch fortschicken. Corithras Moonrage erwartet Euch. Ich habe das Wasser der Phiole, die Ihr mir brachtet, in dieses Gefäß geschüttet, damit Ihr es ihm bringen könnt.$b$bFragt nach Corithras. Ihr findet ihn am Mondbrunnen in Dolanaar. Folgt der Straße südlich von Aldrassil, die aus Shadowglen hinausführt und dann weiter auf dem Kopfsteinpflaster in Richtung Westen.$b$bBleibt unbedingt immer auf der Straße, $n. Es gibt neuerdings ziemlich gefährliche Bestien in den Wäldern.",objectives={"Bringt Corithras Moonrage in Dolanaar das teilweise gefüllte Gefäß."}]])
R(929,"Krone der Erde",[[description="Lasst mich Euch zunächst ein bisschen mehr von der Aufgabe erzählen, die Euch erwartet. Die Druiden in Darnassus verbrauchen das Wasser der Mondbrunnen Teldrassils, und deshalb muss ihr Mondbrunnen von Zeit zu Zeit wieder aufgefüllt werden. Ihr könnt mit diesen speziell gefertigten Phiolen Wasser aus den Mondbrunnen schöpfen.$b$bNehmt dieses Gefäß zum Mondbrunnen außerhalb von Starbreeze im Osten mit und füllt es mit Wasser. Kehrt dann zu mir zurück. Wenn Ihr Eure Aufgabe erledigt habt, erzähle ich die Geschichte da weiter, wo Tenaron aufgehört hat ...",objectives={"Füllt die Jadephiole und bringt sie Corithras Moonrage in Dolanaar zurück."}]])
R(930,"Die leuchtende Frucht",[[description="Unter den Wedeln dieser leuchtenden Pflanze befindet sich eine große, runde Frucht.$B$BDenalan würde diese Frucht bestimmt gern studieren, da seid Ihr Euch sicher.",objectives={"Bringt Denalan am Al'Amethsee die leuchtende Frucht."}]])
R(931,"Der schimmernde Wedel",[[description="Die Wedel der Pflanze schimmern im Dämmerlicht des Waldes und verleihen ihr eine wabernde, pulsierende Aura.$B$BIhr glaubt, dass Denalan bestimmt gern ein Exemplar davon hätte.",objectives={"Bringt Denalan am Al'Amethsee einen der schimmernden Wedel."}]])
R(932,"Krankhafter Hass",[[description="Ich muss Euch warnen, $n, das hier muss absolut unter uns bleiben. Die Satyrn bereiten uns schon genug Ungelegenheiten, aber dieser eine hier scheint sich zu einer echten Bedrohung zu entwickeln.$B$BLord Melenas ist sein Name. Er lebt in der Nähe des Teufelsfelsens in einer Höhle, in der er ein großes Kontingent Grellkrieger um sich versammelt hat. Sein Herz ist so schwarz wie die Nacht und er führt etwas äußerst Übles im Schilde.$B$BIhr müsst ihn in der nahe gelegenen Höhle gleich nördlich von hier suchen und mir seinen Kopf bringen.",objectives={"Tötet Lord Melenas und bringt Tallonkai Swiftroot in Dolanaar seinen Kopf."}]])
R(933,"Krone der Erde",[[description="Südöstlich des Ortseinganges von Darnassus, an den Ufern der Teiche von Arlithrien, gibt es noch einen Mondbrunnen. Die Schildwachen können aufgrund von Angriffen und der ständig schlimmer werdenden Hinterhältigkeit der Knarzklauenfurbolgs kaum durch dieses Gebiet patrouillieren.$b$bSeid auf der Hut, wenn Ihr Euch dem Brunnen nähert, und haltet Eure Waffen stets griffbereit.",objectives={"Füllt die Turmalinphiole und bringt sie Corithras Moonrage in Dolanaar."}]])
R(934,"Krone der Erde",[[description="Mit Teldrassil stand es jedoch nicht zum Besten. Hirschhaupts sorgfältig durchdachte Pläne für den neuen Weltenbaum entwickelten sich nicht so, wie er gehofft hatte, denn es gab ein kleines Problem. Ein Problem, das die Ursache für viele weitere Probleme Teldrassils ist.$b$bWie dem auch sei, dazu komme ich später. Ihr müsst den letzten Mondbrunnen nordwestlich von hier in der Lichtung des Orakels aufsuchen. Unter den Ästen des Orakelbaums befindet sich der wichtigste und mächtigste unserer Brunnen. Beschafft eine Phiole seines Wassers und bringt sie mir.",objectives={"Füllt die Amethystphiole und bringt sie Corithras Mondzorn in Dolanaar."}]])
R(935,"Krone der Erde",[[description="Ohne den Segen Alexstraszas der Lebensbinderin und Nozdormus des Zeitlosen gab es Makel in Teldrassils Wachstum. Man berichtet von seltsamen Wildtieren, die sich buchstäblich aus dem Nährboden des Baums erhoben haben, und von wahnsinnigen Furbolgs, die durchziehende Reisende angreifen.$b$bIch kann nur hoffen, dass der Erzdruide schnellstens eine Lösung für das Problem findet. Ich werde alles Wasser der Phiolen, die Ihr mir brachtet, in dieses Gefäß schütten, damit Ihr es nach Darnassus bringen könnt.$b$bBringt es Fandral Staghelm, Ihr findet ihn im Druidenhain.",objectives={"Bringt dem Erzdruiden Fandral Staghelm in Darnassus das gefüllte Gefäß."}]])
R(936,"Erzdruide Runetotem helfen",[[description="Entschuldigung, $C, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?$B$BDer Zirkel des Cenarius in Thunder Bluff ist sehr an erfahrenen Abenteurern wie Euch interessiert, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein Geringerer als Hamuul Runetotem an der Spitze dieses Projektes steht.$B$BBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm auf der Anhöhe der Ältesten in Thunder Bluff.",objectives={"Sprecht in Thunder Bluff mit Erzdruide Hamuul Runetotem."}]])
R(937,"Die verzauberte Lichtung",[[description="Man hat mich mit einer kleinen Gruppe Schildwachen hierher beordert, um den Orakelbaum vor den Harpyien zu beschützen, die überall im Tal Nester gebaut haben. Wir versuchen, sie langsam aber sicher zurückzudrängen.$b$bBeim Versuch des Orakelbaums, einen Läufer mit einem Bericht nach Darnassus zu entsenden, wurde dieser von einer Gruppe eben jener Harpyien angegriffen und getötet.$b$bWenn Ihr glaubt, dieser Aufgabe gewachsen zu sein, begebt Euch zu ihren Nestern, erschlagt sie und bringt mir zum Beweis Eurer Taten deren Gürtel.",objectives={"Beschafft 6 Blutfedergürtel und bringt sie der Schildwache Arynia Cloudsbreak in der Lichtung des Orakels."}]])
R(938,"Nebel",[[description="Das Fell der Säblerkatze ist von einer auffälligen grauen Farbe, die sich nur wenig vom sie umgebenden Wald abhebt. Wie sie da liegt, erkennt Ihr, dass sie schwer verletzt ist und tiefe Wunden an Rücken und Bauchseite aufweist.$b$bSie hebt ihren Kopf und starrt Euch an, ihre glänzenden blauen Augen voll wacher Intelligenz. Sie scheint Euch folgen zu wollen.",objectives={"Begleitet Nebel zur Schildwache Arynia Cloudsbreak beim Mondbrunnen in der Nähe des Orakelbaums."}]])
R(939,"Flöte des Xavaric",[[description="Ihr untersucht die einfache Holzflöte, die Ihr nach dem Sieg über Xavaric aufgehoben habt.$B$BDas knorrige Holz fühlt sich fest an, aber es scheint, als würden sich die Spiralen und Muster auf der Oberfläche bewegen und herumwirbeln, als Ihr sie in den Händen dreht. Plötzlich überkommt Euch ein Gefühl der Furcht...$B$BIhr schüttelt den Kopf, sicher, dass Euch Euer Gehirn einen Streich spielt.$B$BMöglicherweise tragen andere Satyrn Hinweise darüber mit sich, was Ihr da gefunden habt. Bringt Euren Fund zu dem Druiden Eridan Bluewind, der im südlichen Teil des Teufelswalds lebt.",objectives={"Bringt die Flöte von Xavaric und 5 Jadefeuerteufelsbinder zu Eridan Bluewind im südlichen Teil des Teufelswalds."}]])
R(940,"Teldrassil",[[description="Der Wald flüstert von Euren wagemutigen Heldentaten, $n. Sobald die Harpyien aus ihren Nestern vertrieben waren, spürte ich, wie sich große Ruhe im Wald verbreitete, und dass sich die Kreaturen des Waldes wieder sicher fühlten. Ich habe nicht gewagt, noch einen Boten zum Erzdruiden zu schicken, aber ich weiß, dass Ihr dafür sorgen werdet, dass ihn meine Nachricht sicher erreicht.$b$bBringt ihm dies und wisset, dass der Wald Euch auf all seinen Wegen beschützen wird, sodass Ihr den Wald aus Stein sicher erreicht.",objectives={"Überbringt dem Erzdruiden Fandral Staghelm in Darnassus den Bericht des Orakelbaums."}]])
R(941,"Das Einpflanzen des Herzens",[[description="Ich habe das üble Moos von dem Herzen entfernt, aber es bleibt dennoch besudelt...$B$BVersucht, das Herz in meinem Blumentopf einzusetzen. Er ist mit einer nährstoffreichen Krume gefüllt, die das Herz säubern und heilen kann.",objectives={"Pflanzt das besudelte Herz in Denalans Blumentopf ein."}]])
R(942,"Der geistesabwesende Ausgrabungsleiter",[[description="Dieses Fossil hat eine auffallende Ähnlichkeit mit einem anderen, das ich einst in Ironforge sah. Ein Archäologe namens Flagongut brachte es zur jährlichen Forscherliga-Konferenz mit. Er dachte, das Fossil besäße eine besondere Macht, die man irgendwie freisetzen könnte.$b$bDas Letzte, was ich von Flagongut hörte war, dass er sich in der Deepwater-Taverne im Hafen von Menethil verschanzt hatte und dort auf eine Eskorte zu Whelgars Ausgrabungsstätte wartete. Sucht ihn auf und zeigt ihm Remtravels Fossil. Vielleicht kann er die Geheimnisse der Vergangenheit lüften.$b$bDas Schiff nach Menethil liegt in Auberdine.",objectives={"Bringt das rätselhafte Fossil zum Archäologen Flagongut im Hafen von Menethil."}]])
R(943,"Der geistesabwesende Ausgrabungsleiter",[[description="Ausgrabungsleiter Whelgar ist jetzt im Besitz des Originalfundstücks. Er hält sich in seiner Ausgrabungsstätte im Sumpfland auf. Als ich den Stein von Relu entdeckte, glaubte ich, dass er der Schlüssel sei, mit dem das Rätsel des Fossils gelöst werden könne.$b$bAuf dem Weg zu Whelgar wurde ich dann von Raptoren angegriffen und das Relikt ging verloren. Ich weiß nicht, welche dieser scheckigen Bestien das Relikt verschlungen hat, aber falls es Euch gelingen sollte, es zurückzuholen, könnte ich die Macht dieser Artefakte freisetzen.$B$BBringt mir den Stein von Relu und das Originalfossil.",objectives={"Der Archäologe Flagongut im Hafen von Menethil möchte, dass Ihr ihm den Stein von Relu und Flagonguts Fossil bringt."}]])
R(944,"Die Meistergleve",[[description="Wie seltsam, dass sich Naga hier herumtreiben, hier in Dunkelküste. Aber was noch seltsamer ist... es sind auch welche vom Klan der Twilight-Hammer da. Dieser Kult verehrt die alten, alten Lords der Erde. Lords, die schon vor Unzeiten besiegt wurden.$B$BDie Meistergleve im Süden ist ein Ort, an dem ein solcher Lord einst gefallen ist.$B$BBegebt Euch dorthin und sucht nach weiteren Anhängern der Twilight-Hammer-Kultisten.$B$BNehmt diese Wahrsagephiole. Erschafft damit eine Wahrsageschale, nachdem Ihr die Meistergleve durchsucht habt. Sprecht dann mit mir mittels der Schale.",objectives={"Tragt Informationen zusammen und benutzt dann die Wahrsagephiole, um eine Wahrsageschale zu erschaffen. Benutzt die Schale, um mit Onu zu sprechen."}]])
R(945,"Therylunes Flucht",[[description="Hilfe!$B$BDiese dreckigen Kultisten haben mich umzingelt, während ich durch die Meistergleve spazierte. Was für ein Glück, dass ich so gut im Verstecken bin!$B$BKönnt Ihr mir hier raushelfen? Ich sollte auch meiner Schwester Therysil Bescheid geben, dass es mir gut geht. Sie wohnt in Ashenvale im Süden, beim Schrein von Aessina.",objectives={"Verhelft Therylune zur Flucht und teilt dann Therysil beim Schrein von Aessina mit, dass ihre Schwester in Sicherheit ist."}]])
R(946,"<UNUSED>")
R(947,"Höhlenpilze",[[description="Ich entwickle gerade einen Trank, für den rare Pilze erforderlich sind. Pilze, die nur in einer bestimmten Höhle wachsen. Diese Höhle liegt hinter Cliffspring Falls im Osten, leicht nördlich entlang der Berge.$B$BIch würde ja selbst dorthin gehen, aber der Hain der Uralten hat mir geraten, mich von diesem Ort fern zu halten. Unsere altehrwürdigen Verbündeten spüren, dass die Höhle ein Versteck für etwas Neues, Böses in Dunkelküste ist.$B$BBitte, $N, sammelt doch ein paar Pilze für mich, und wenn Ihr schon dabei seid, könntet Ihr auch gleich die Höhle erkunden, um die Befürchtungen der Urtume eventuell zu bestätigen.",objectives={"Bringt Barithras Moonshade in Auberdine 5 Schorfstänglinge und 1 Todeskappe."}]])
R(948,"Onu",[[description="Onu, ein Urtum der Lehren im Hain der Uralten, hat von Eurer Reise nach Cliffwaterfalls erfahren und möchte Euch sprechen. Der Hain liegt im Süden, im Schatten der Berge.$B$BDie Urtume sind geduldig und weise, $N. Aber wenn Onu Euch um Rat bezüglich dessen ersucht, was Ihr in den Falls gesehen habt, fürchte ich, dass es wichtig ist.",objectives={"Sprecht im Hain der Uralten mit Onu."}]])
R(949,"Das Twilight-Lager",[[description="Niemand weiß, was der Klan der Twilight-Hammer in der Meistergleve vorhat. Aber es muss etwas Böses sein.$B$BDurchsucht ihr Lager bei der Meistergleve... Sucht nach etwas, das uns ihre Absichten verraten könnte.$B$BWir müssen unbedingt wissen, was sie im Schilde führen, bevor wir einen Plan schmieden können.",objectives={"Sucht im Lager des Klans der Twilight-Hammer in der Meistergleve nach einem Hinweis."}]])
R(950,"Rückkehr zu Onu",[[description="Der Blick in den Twilight-Folianten kann einen wahnsinnig machen. Der Text verschwimmt und tanzt vor Euren Augen, kaum dass Ihr ihn einen Moment betrachtet habt, und die einst so wunderschönen Illustrationen verzerren sich zu grotesken Formen und Mustern.$B$BIhr könnt gerade noch eine Seite des irrsinnigen Gekritzels herausreißen, bevor Ihr ohnmächtig werdet.",objectives={"Bringt Onu das irrsinnige Gekritzel, das Ihr gefunden habt."}]])
R(951,"Mathystra-Relikte",[[description="Das Pergament, das Ihr in der Meistergleve gefunden habt, ist eine Seite aus einem alten Text... geschrieben von Elfen! Es ist übelst verflucht und besudelt von der Verderbnis des Klans der Twilight-Hammer, aber es scheint, als würde der Kult alte Elfenmagie benutzen, um seine alten Lords in unsere Welt zurückzuholen.$B$BReist zu den Ruinen von Mathystra im Nordosten und sucht nach alten Relikten unter dem Gras und den zerbrochenen Steinen. Indem wir sie studieren, können wir vielleicht herausbekommen, auf welche Weise der Klan der Twilight-Hammer die Magie der Elfen nutzen will.",objectives={"Bringt 6 Mathystra-Relikte zu Onu in den Hain der Uralten."}]])
R(952,"Der Hain der Uralten",[[description="Wenn Ihr genug Zeit hattet, um für den Orakelbaum Nachrichten zu übermitteln, kann ich Euch sicherlich dazu bewegen, eine Nachricht in den Hain der Uralten in Dunkelküste zu bringen, südlich von Auberdine.$b$bIhr werdet höchstwahrscheinlich ein sicheres Transportmittel wie einen Hippogryphen benötigen, aber ich baue darauf, dass Ihr das regeln könnt. Bringt dies Onu, dem Urtum der Lehren. Er wartet auf eine Nachricht von mir, so wie ich auf Neuigkeiten aus der Lichtung des Orakels wartete.",objectives={"Bringt Fandrals Nachricht zu Onu in den Hain der Uralten in Dunkelküste, südlich von Auberdine."}]])
R(953,"Der Untergang von Ameth'Aran",[[description="Im Osten findet Ihr die Ruinen von Ameth'Aran. Sie werden heute von den ruhelosen Geistern der Hochgeborenen bewohnt, die einst dort lebten. Damals jedoch war es ein Ort, an dem die Diener Azsharas ihre mächtige Magie ungestört praktizieren konnten.$b$bMan hat mich geschickt, die Ruinen zu erkunden und ich stieß auf zwei große Schrifttafeln, auf denen die Geschichten Ameth'Arans und seines Unterganges beschrieben werden. Während ich die Runen las, traten Geister an mich heran und ich floh.$b$bBitte, wenn es Euch möglich ist, begebt Euch zu den Ruinen und entziffert an meiner statt die Schrifttafeln.",objectives={"Studiert die Schrifttafeln, die von Ameth'Aran und ihrem Untergang erzählen, und kehrt dann zur Schildwache Tysha Moonblade in Dunkelküste zurück."}]])
R(954,"Bashal'Aran",[[description="Die Ruinen von Bashal'Aran im Osten sind von dämonischen Dienern überrannt worden. Die Grimmlinge und Satyrn haben sich in dem Gebiet niedergelassen und nähren sich von den magischen Energien dort. Ihre Macht wächst, je länger sie sich dort aufhalten.$b$bDennoch habe ich festgestellt, dass es dort einen Schrein gibt, dem sie nicht zu nahe kommen wollen. An der Westseite der Ruinen auf einem kleinen Steilhang entspringt eine seltsame blaue Aura ... Das muss eine Erklärung für das Widerstreben der Dämonen sein.$b$bIch hätte gern, dass Ihr das untersucht.",objectives={"Sucht in den Ruinen von Bashal'Aran nach der Quelle der seltsamen blauen Aura."}]])
R(955,"Bashal'Aran",[[description="Sollte ich jemals gehalten sein, die Geschichte meines Lebens zu erzählen, würde dies zweifellos die Grenzen Eurer Geduld überstrapazieren. Sagen wir einfach, dass mein Leben lang und schmerzvoll war, und dass diese meine spektrale Gestalt die schlimmste Pein von allem ist.$b$bIch werde durch Magie hier festgehalten. Mögen meine Worte auch unaufrichtig erscheinen, so versichere ich Euch doch, dass ich über die Maßen dankbar wäre, würdet Ihr mir helfen, den Grund für meine Gefangenschaft herauszufinden. Ein Siegel bindet mich, und vielleicht finde ich einen Hinweis darauf, wenn ich den Ohrschmuck der Grimmlinge und Grells nur näher betrachten könnte.",objectives={"Beschafft für Asterion in Bashal'Aran 8 Grell-Ohrringe."}]])
R(956,"Bashal'Aran",[[description="Wenn die Grells erst kürzlich mit dem Siegel in Berührung gekommen sind, das mich an dieses ewige Gefängnis bindet, glaube ich, den Grund dafür zu wissen. Zweifellos ist das Siegel in den Besitz des Satyrs gelangt, der sie anführt.$b$bIch bin mir ganz sicher, dass es so ist, $n. Einer der Satyrn muss es besitzen. Wenn Ihr es an Euch bringen könntet, würde es mich der Überwindung der Gitterstäbe meines Gefängnisses so nahe bringen, dass es mich zu Tränen rühren würde.",objectives={"Beschafft das alte Mondstein-Siegel und bringt es Asterion in Bashal'Aran."}]])
R(957,"Bashal'Aran",[[description="Es war die Kunst eines der mächtigsten Hochgeborenen, der das Siegel erschuf, das mein Gefängnis war. In Ameth'Aran, den Ruinen im Süden, die diesen hier aufs Haar gleichen, gibt es sogar heute noch eine uralte Flamme, blau ist ihre Farbe. In dieser Flamme könnte man dieses Siegel zerstören.$b$bAchtet auf die Ruinen, $n!",objectives={"Zerstört das alte Mondstein-Siegel in der uralten Flamme in Ameth'Aran und kehrt dann zu Asterion in Bashal'Aran zurück."}]])
R(958,"Werkzeuge der Hochgeborenen",[[description="$C. Ich möchte Euch um etwas bitten.$b$bHabt Ihr die Ruinen von Ameth'Aran gesehen? Falls nicht, findet Ihr sie auf der Ostseite der Hauptstraße, ein paar Straßen weiter südlich. Einst waren sie die Heimat vieler mächtiger Hochgeborener, doch heute sind sie Zeugnis der Zerstörung, die sie mit ihrem Dilettantismus angerichtet haben.$b$bDie Schildwachen sagten mir, dass die Geister der Hochgeborenen immer noch umgehen und dass sie ihre alten, magischen Utensilien immer noch benutzen. Wir müssen uns diese Relikte aneignen, damit wir sie zerstören können.",objectives={"Sucht sieben Hochgeborenenrelikte und bringt sie Thundris Windwirker in Auberdine."}]])
R(959,"Ärger auf den Docks",[[description="Upps!$b$bWie Ihr seht, ist mir ein kleines Malheur passiert! Die Morgenlieferung aus Booty Bay war umfangreich. Wirklich gewaltig! Noch nie habe ich so viele Kisten gesehen. Tja, ich wollte die Sache etwas beschleunigen, deshalb habe ich begonnen mehr abzuladen, als ich auf einmal bewältigen konnte. Und dann ist alles zusammengebrochen.$b$bBevor ich wusste, was überhaupt los war, sah ich diese Nervensäge Zausel den Verrückten mit einer Flasche 99-jährigem Portwein wegrennen. Hab ihn bis zu den Höhlen des Wehklagens verfolgt. Da wollte ich auf keinen Fall rein.$b$bVielleicht seid Ihr ja mutig genug, um nach ihm zu suchen?",objectives={"Kranführer Bigglefuzz in Ratchet möchte, dass Ihr Zausel dem Verrückten, der sich in den Höhlen des Wehklagens versteckt, die Flasche mit 99-jährigem Portwein wieder abnehmt."}]])
R(960,"Onu meditiert")
R(961,"Onu meditiert")
R(962,"Schlangenflaum",[[description="Die Königliche Apothekervereinigung, die in der großen Undercity Lordaerons ansässig ist, hat mich geschickt, um eine ganz besondere Aufgabe zu erledigen, $n. Vielleicht möchtet Ihr mich und damit auch die dunkle Fürstin bei unseren Bemühungen, die Verlassenen weiterzubringen, unterstützen.$b$bIch studiere seit kurzem eine rare Pflanzenart namens Schlangenflaum. Ich denke, dass dieses Kraut in größeren Mengen außerordentliches Potenzial besitzt.$b$bLeider findet man Schlangenflaum nur in den dunkelsten Winkeln der Höhlen des Wehklagens, einem gefährlichen Höhlensystem im Brachland.",objectives={"Die Apothekerin Zamah in Thunder Bluff möchte, dass Ihr zehn Schlangenflaum für sie sammelt."}]])
R(963,"In ewiger Liebe",[[description="Nach den Schlachten um den Brunnen der Ewigkeit hörte ich, dass Ameth'Aran zerstört wurde und alle Bewohner ums Leben kamen, darunter auch meine geliebte Anaya.$b$bIch hätte nie gedacht, dass mich noch heute, Tausende von Jahren später, die Erinnerungen an Anaya um den Schlaf bringen würden. Ich wanderte wie in Trance durch die Wälder von Dunkelküste und fand mich schließlich in den Ruinen von Ameth'Aran wieder... wo ich den gequälten Geist meiner Geliebten sah.$b$bSie muss befreit werden, aber ich kann es nicht über mich bringen, dies zu tun. Ihr Geist muss zerstört werden.",objectives={"Befreit den Geist von Anaya Dawnrunner und bringt ihren Anhänger zu Cerellean Whiteclaw in Auberdine."}]])
R(964,"Skelettfragmente",[[description="Der Schlüssel zur Scholomance wird 'Skelettschlüssel' genannt. Er muss aus den Überresten eines Skeletts geschmiedet werden- eigentlich aus mehreren - und er darf nur durch die stärksten Metalle in einer geeigneten Form gehärtet werden. Ein Signet der Macht von einem Wesen, das das Portal zur Scholomance natürlich öffnen kann, gibt dem Schlüssel seine endgültige Funktion.$B$BAber eines nach dem anderen, $N. Wir benötigen Skelettfragmente für das Schmieden des Schlüssels. Skelette innerhalb von Andorhal sollten den gewünschten Effekt bringen, aber die außerhalb der Mauern könnten vielleicht auch ausreichen.",objectives={"Bringt 15 Skelettfragmente zu Apotheker Dithers am Bollwerk, Westliche Pestländer."}]])
R(965,"Der Turm von Althalaxx",[[description="Grüße, $R. Ich bin Elissa Starbreeze und es ist meine Aufgabe, Auberdine vor Schaden zu schützen.$b$bAus diesem Grund habe ich Balthule Shadowstrike ausgeschickt, um die seltsamen Vorkommnisse rund um den Turm von Althalaxx im Nordosten zu beobachten.$b$bEr hätte eigentlich schon längst wieder zurück sein sollen. Daher fürchte ich, dass er im Wald auf eine unvorhersehbare Gefahr gestoßen ist. Ich würde es außerordentlich zu schätzen wissen, wenn Ihr nach ihm suchen und dafür sorgen würdet, dass es ihm gut geht.",objectives={"Sucht Balthule Shadowstrike in der Nähe des Turms von Althalaxx in Dunkelküste."}]])
R(966,"Der Turm von Althalaxx",[[description="Eine Gruppe Hexenmeister hat sich in und um den Turm herum niedergelassen. Ich wollte ja schon früher nach Auberdine zurückkehren, um Elissa Bericht zu erstatten, aber ich befürchtete, hier etwas zu verpassen, solange ich fort wäre.$b$bDelgren vermutete, dass sich eine solche Gesellschaft beim Turm versammeln würde, aber er wusste nicht, warum.$b$bEin paar Pergamentfetzen, die die Hexenmeister bei sich führten, sind mir in die Hände gefallen, aber ich brauche noch mehr, um das Rätsel zu lösen. Ich warne Euch jedoch, geht lieber nicht in den Turm hinein, denn die Hexenmeister dort sind noch viel mächtiger!",objectives={"Sammelt 4 abgenutzte Pergamentfetzen für Balthule Shadowstrike in der Nähe des Turms von Althalaxx."}]])
R(967,"Der Turm von Althalaxx",[[description="Mein Meister, Delgren der Läuterer, ist ein Paladin, der gütigerweise seine Unterstützung bei der Verteidigung unseres Waldes vor den Streitkräften der Dämonen und Untoten angeboten hat. Er hat mich viel über das Heilige Licht und die Kampfkunst gelehrt.$b$bDelgren muss sofort über die Machenschaften des Kults informiert werden.$b$bIhr findet ihn ganz weit südlich von hier in Maestras Posten in Ashenvale. Beeilt Euch, ich fürchte nämlich, dass die Bedrohung durch den dunklen Strangs stündlich größer wird.",objectives={"Überbringt Delgren dem Läuterer in Ashenvale Balthules Brief."}]])
R(968,"Die Macht in der Tiefe",[[description="Obwohl das Buch ziemlich abgenutzt und zerfleddert ist, ist der Titel auf dem Buchdeckel noch gut lesbar:$B$B'Die Macht in der Tiefe'$B$BIn diesem Buch findet sich eine Auflistung unaussprechlicher Namen mit viel sagenden Betitelungen, Verehrungsmethoden und bevorzugten Opferritualen ... bei denen sehr oft lebende, humanoide Kreaturen verwendet werden.$B$BAuf der Innenseite des Einbands stehen die Worte: 'Bonegrips Runen und Verhängnisse, Düsteres Viertel, Ironforge. Inhaber: Gerrig Bonegrip.'$B$BWenn Bonegrip derartige Bücher verkauft, nimmt er dieses hier vielleicht zurück.",objectives={"Bringt das Buch: 'Die Macht in der Tiefe' zu Gerrig Bonegrip im düsteren Viertel in Ironforge."}]])
R(969,"Das Glück sei mit Euch",[[description="Ah, ich seh's Euch direkt an: Ihr möchtet, dass ich Euch einen Glücksbringer anfertige. Mau'ari weiß immer Bescheid!$B$BIm Süden, findet Ihr eine Schlucht und Riesen, die komplett aus Eis bestehen. Die Riesen tragen die Splitter manchmal bei sich, aber Ihr könnt sie auch selbst in der Schlucht sammeln. Diese Splitter haben mächtige reflektierende Eigenschaften.$B$BBringt mir 10 Frosthagelsplitter und mein Glücksbringer wird Euch gehören.",objectives={"Sammelt 10 Frosthagelsplitter für die Hexendoktorin Mau'ari in Everlook."}]])
R(970,"Der Turm von Althalaxx",[[description="Balthules Brief verkündet Unheil. Dieser Kult des Dunklen Strangs ist mir ein Dorn im Auge, der entfernt werden muss. Ich hatte nordöstlich von hier in Ordil'Aran schon einmal mit dem Abschaum des Dunklen Strangs zu tun. Eines seiner Mitglieder besitzt einen Seelenedelstein, der, wie ich glaube, das Geheimnis der Macht des Kults enthält.$b$bBringt ihn mir, dann kann ich die darin zu findenden Geheimnisse entschlüsseln.",objectives={"Beschafft einen leuchtenden Seelenedelstein und bringt ihn Delgren dem Läuterer in Maestras Posten."}]])
R(971,"Wissen in der Tiefe",[[description="Wie Ihr vielleicht wisst, trage ich Lehren zusammen. Alte Lehren. Mächtige Lehren. Lehren, die Portale öffnen, und Lehren, die die Schlafenden erwecken können.$B$BEs kursieren Gerüchte um einen alten Teil einer Lehre, das 'Lorgalis-Manuskript', das sich tief unten in den Blackfathom-Tiefen in Ashenvale befinden soll. Dieser Ort ist die ehemalige Heimat längst verstorbener Elfen. Elfen, die über großes Wissen verfügten, bevor ihre Stadt zerfiel.$B$BSucht in den Blackfathom-Tiefen nach dem Manuskript. Wenn Ihr das tut, werde ich Euch das nie vergessen. Auch nicht ... nach dem Ende aller Tage.",objectives={"Bringt das 'Lorgalis-Manuskript' zu Gerrig Bonegrip in Ironforge."}]])
R(972,"Wassersapta")
R(973,"Der Turm von Althalaxx",[[description="Ilkrud Magthrull. Ja, ich kenne ihn. Er ist ein mächtiger Orc-Hexenmeister, der im Fire Scar-Schrein lebt, einem äußerst bösen Ort im südwestlichen Ashenvale.$b$bBislang ist er nur ein geringes Ärgernis und ich hatte noch nichts mit ihm zu tun, aber es sieht so aus, als wäre jetzt seine Zeit gekommen.",objectives={"Bringt Delgren dem Läuterer in Maestras Posten Ilkrud Magthrulls Folianten."}]])
R(974,"Die Quelle finden",[[description="Die heißen Quellen hier sind eine Quelle der Geheimnisse für mich. Woher kommt die Hitze?$B$BWenn ich mir überlege, wie nah diese Teiche beim Feuerfedergrat sind, frage ich mich wirklich, ob der Vulkan etwas damit zu tun hat. Ich habe ein Thermometer entwickelt, um die Temperaturen am Vulkan zu messen, und ich würde gern die heißeste Stelle finden. Es zeigt die Messungen in Grad Kraklenheit an!$B$BHier, nehmt es und messt die Temperaturen am Grat, wann immer Ihr eine heiße Stelle seht!",objectives={"Krakle im Un'Goro Krater möchte, dass Ihr den heißesten Bereich des Feuerfedergrats findet.$B$BImmer, wenn Ihr eine heiße Stelle findet, klickt Ihr das Thermometer mit der rechten Maustaste an, um die Temperatur zu überprüfen. Sucht, bis Ihr die heißeste Stelle gefunden habt."}]])
R(975,"Behälter von Mau'ari",[[description="Also, bevor ich Euch dies'n Glücksbringer geb, erklär ich Euch besser, wie er zu verwenden is'.$B$BWenn Ihr den Glücksbringer bei Euch tragt, werdet Ihr feststell'n, dass die Kreaturen, gegen die Ihr kämpft, bestimmte Gegenstände fallen lassen. Wenn Ihr den Glücksbringer nich' dabei habt, werdet Ihr sie nich' find'n. Kapiert?$B$BIhr erkennt diese speziellen Gegenstände am Namen - sie werden E'ko genannt. Wenn Ihr solche Gegenstände findet, bringt Ihr sie einfach der alten Mau'ari, und sie hilft Euch.$B$BWartet hier, während ich Euren Glücksbringer anfertige.",objectives={"Wartet einen Moment und sprecht dann erneut mit Hexendoktorin Mau'ari, um den Glücksbringer zu erhalten."}]])
R(976,"Nachschub für Auberdine",[[description="Delgren hat mich gebeten, der Schildwache Starbreeze in Auberdine Nachrichten und Nachschub zu bringen, aber es schmeckt mir gar nicht, allein dorthin zu gehen. Im Wald sind gefährliche Feinde zugange und ich möchte nicht riskieren, dass der Nachschub und die Informationen in die falschen Hände geraten.$b$bWenn Ihr und ein paar andere als Wachen mit mir kämen, könnte ich sofort gehen. Mit Eurem Schutz zweifle ich nicht daran, dass wir diese Dinge sicher nach Auberdine bringen können.",objectives={"Sprecht mit Delgren dem Läuterer bei Maestras Posten, nachdem Ihr Feero sicher durch Ashenvale geführt habt."}]])
R(977,"Sind wir endlich da, Yeti?",[[description="Nachdem ich jetzt alles habe, was ich benötige, um die mechanischen beweglichen Teile abzudecken, benötige ich nur noch eine weitere Sache. Na ja, eigentlich zwei. Zwei Hörner!$B$BDie Eisdistelpatriarchen und -matriarchen haben die größten Hörner, also will ich natürlich diese. Diese Yetiart bewohnt eine Höhle im Südosten. Es gibt viele von ihnen; Ihr solltet keine Probleme haben, sie zu finden.$B$BDenkt daran, ich will nur die bestaussehenden - keine beschädigten oder zerbrochenen Hörner, bitte!",objectives={"Sammelt 2 makellose Yetihörner für Umi Rumplesnicker in Everlook."}]])
R(978,"Mondbestrahltes Wildekin",[[description="Wildekinfedern aus dem Hinterland scheinen Spuren magischer Fähigkeiten zu enthalten. Diese Kräfte... sie scheinen von den Kreaturen nicht bewusst eingesetzt zu werden, es scheint eher, als wären sie der Art angeboren; ein Teil ihres innersten Wesens.$B$BWährend meiner Studien habe ich gehört, dass eine große Population von Wildekins die schneebedeckten Länder von Winterspring bewohnt. Könnten diese Kreaturen über die gleichen Kräfte verfügen? Helft mir bitte, eine Antwort zu finden, $N. Begebt Euch nach Winterspring und sammelt die auf dem Boden gefallenen Federn ein. Kehrt dann zu mir zurück.",objectives={"Sammelt 10 mondbestrahlte Federn aus Winterspring und kehrt dann zu Erelas Ambersky in Rut'theran zurück."}]])
R(979,"Ranshalla suchen",[[description="Ja, ja, diese Federn scheinen die gleiche magische Verzauberung zu enthalten, die mir schon zuvor auffiel... Auch wenn ich mir nicht sicher bin, was wir vorfinden werden, solltet Ihr weiterhin nach Antworten suchen, $N.$B$BEine meiner Kolleginnen reiste kürzlich nach Winterspring, um die Wildekin dort in ihrer heimischen Umgebung zu beobachten. Warum sucht Ihr sie nicht auf und seht, was sie herausgefunden hat?",objectives={"Sucht nach Ranshalla im östlichen Winterspring."}]])
R(980,"Die neuen Quellen",[[description="Tja, ich habe von anderen heißen Quellen an einem Ort namens Winterspring gehört, von hier aus gesehen weit im Norden. Das Merkwürdige ist, dass es dort in der Nähe keine Vulkane gibt. Interessant, ich weiß.$B$BAlso, wenn Ihr mehr herausfinden möchtet, solltet Ihr Euch nach Winterspring begeben und mit einer Freundin von mir sprechen. Ihr Name ist Donova Snowden und sie hält sich derzeit bei den heißen Quellen dort auf.$B$BIch danke Euch erneut, dass Ihr mir mit meinem Thermometer geholfen habt! Auf dann!",objectives={"Reist nach Winterspring und sprecht mit Donova Snowden."}]])
R(981,"Der Turm von Althalaxx",[[description="Für all das, was Ihr geleistet habt, habt Ihr eine ordentliche Belohnung verdient. Kehrt zu Delgren zurück und sagt ihm, dass Ihr Athrikus Narassin eigenhändig den Garaus gemacht habt, und dass der Kult des Dunklen Strangs zerschlagen ist.",objectives={"Sprecht mit Delgren dem Läuterer in Maestras Posten."}]])
R(982,"Tiefer Ozean, weites Meer",[[description="Nahe der Ufer von Dunkelküste im Norden liegen zwei havarierte Schiffe - die SILBERMORGEN und die NEBELSCHLEIER. Vor einiger Zeit kollidierten die beiden Schiffe wegen der verfluchten Murlocs, als sie über das weite Meer nach Auberdine segelten. Jetzt liegen sie auf dem Grund des Ozeans als Trophäen für diese Satanskreaturen.$B$BBeide Kapitäne haben es in dieser Nacht nicht geschafft, ihre Schiffe zu verlassen. Ihre Logbücher und anderen Habseligkeiten befinden sich immer noch dort unten in Schließkassetten. Ich möchte Euch bitten, sie für uns zu beschaffen; es würde den Mannschaftsmitgliedern, die sich noch hier aufhalten, viel bedeuten.",objectives={"Beschafft die Schließkassette der SILBERMORGEN und die Schließkassette der NEBELSCHLEIER für Gorbold Steelhand in Auberdine. Beide Gegenstände findet Ihr an Bord der Schiffswracks nördlich des Dorfes."}]])
R(983,"Dröhnkiste 827",[[description="He! Helft mir bei meiner neuesten Erfindung, der Dröhnkiste. Man kann damit mit Leuten sprechen, die weit weg sind!$B$BVielleicht habt Ihr sie schon mal gesehen, das sind kleine Kästchen mit Hebeln daran. Ihr einziges Problem ist, dass sie ständig gewartet werden müssen.$B$BJede hat ein anderes Problem, aber ich hab mir etwas ziemlich Schlaues ausgedacht. Ich habe alle in der Nähe von Kreaturen platziert, die über die passenden Teile verfügen, um die jeweilige Maschine zu reparieren. Momentan hat Dröhnkiste 827 den Geist aufgegeben. Sie steht südlich von Auberdine, also gleich in der Nähe. Es werden sechs Kriecherbeine benötigt, um sie zu reparieren. Ich bezahl Euch auch dafür ...",objectives={"Sammelt 6 Kriecherbeine und baut sie in Dröhnkiste 827 ein."}]])
R(984,"Wie groß ist die Bedrohung?",[[description="Einige meiner Brüder konnten in Teldrassil vor einem verderbten Furbolg gerettet werden und ich habe geschworen, weitere Gräueltaten zu verhindern, bevor noch mehr von uns verletzt werden... oder schlimmer.$B$BIch habe auch in Dunkelküste schon die ersten Anzeichen von Verderbnis entdeckt, jedoch noch nichts gefunden, was auf Ausbreitung hindeutet. Ich denke, es wäre logisch, wenn man die Untersuchungen bei den Furbolgs fortsetzen würde. Würdet Ihr wohl eines ihrer Lager aufsuchen und zu mir zurückkehren, falls Ihr dort irgendwelche Anzeichen von Verderbnis entdeckt?",objectives={"Sucht in Dunkelküste nach einem verderbten Furbolglager und kehrt dann zu Terenthis in Auberdine zurück."}]])
R(985,"Wie groß ist die Bedrohung?",[[description="Ihr habt Euer Talent im Ausspähen unserer Feinde bereits unter Beweis gestellt, $n. Aber habt Ihr auch das Zeug dazu, sie zu bekämpfen?$B$BNicht alle Abenteurer ziehen ein offenes Gefecht der Kunst der Verstohlenheit und des Ausweichens vor.$B$BWenn Ihr glaubt, der Aufgabe gewachsen zu sein, solltet Ihr Euch das Furbolglager südlich von Auberdine vornehmen. Das stellt momentan die größte Bedrohung für unser Volk dar. Ihr werdet dort ein paar Mitglieder des Schwarzfellstamms finden. Tötet 8 Pfadfinder und 5 Windsprecher und kommt dann zu mir zurück.",objectives={"Tötet 8 Pfadfinder der Schwarzfelle und 5 Windsprecher und kehrt dann zu Terenthis in Auberdine zurück."}]])
R(986,"Ein verirrter Meister",[[description="$N, Eure Fertigkeiten haben mir bei meinen Bemühungen sehr geholfen. Kann ich es wagen, Euch dennoch erneut zu bitten, Grimmklaue und seinem Meister Volcor zu helfen? Ich könnte Euch dazu einen magischen Umhang anfertigen, mit dem Ihr ungehindert an den Kreaturen Dunkelküstes vorbeigelangt, während Ihr nach ihm sucht.$B$BUm den Umhang anzufertigen, benötige ich fünf Mondpirscherpelze von einer Mondpirschermatriarchin oder einem Mondpirscherpatriarchen, um genügend Material zur Verfügung zu haben. Die Katzen findet Ihr südlich von hier, in der Nähe des Flusses Wildbend, oder noch weiter im Süden, in der Nähe von Ashenvale.",objectives={"Sucht 5 feine Mondpirscherpelze und bringt sie Terenthis in Auberdine."}]])
R(987,"<UNUSED>")
R(990,"Marsch nach Ashenvale",[[description="$N, meine Herrin Raene Wolfrunner erwartet Euch in Astranaar in Ashenvale. Mit Eurer Hilfe könnten wir vielleicht wenigstens eines Teils der Verderbnis Herr werden, die sich dort breit gemacht hat.$B$BGeht von hier aus nach Süden und haltet Euch dicht an der Straße. Wenn Ihr Euch an diese Richtungsangaben haltet, erreicht Ihr problemlos Euer Ziel.",objectives={"Sucht Raene Wolfrunner in Ashenvale auf."}]])
R(991,"Raenes Säuberung",[[description="$N, ein alter Freund von mir unterstützt hier in Ashenvale ebenfalls die Schildwachen, aber er ist noch nicht zurückgekehrt.$B$BEr ging einer Spur nach, die zu einem Gegenstand führte, der seiner Meinung nach die Angriffe der Furbolgs auf unser Volk verlangsamen könnte - eine Rute, die von einem mittlerweile verstorbenen, bösen Hexer geschaffen wurde.$B$BVor seiner Abreise erwähnte er, dass er nach einem Edelstein für die Rute suchen wolle.$B$BEr meinte, dass dieser Edelstein möglicherweise in dem Schrein im Falathimsee am Fuße der Berge im Westen versteckt sei. Dort wurde der Edelstein jedenfalls aufbewahrt, bevor der Schrein überrannt worden ist.$B$BBitte, $N, findet meinen Freund.",objectives={"Sucht in Ashenvale nach Teronis."}]])
R(992,"Gadgetzan Wassersondierung",[[description="Wenn Ihr interessiert seid, hätten wir einen offenen Posten im Rang eines temporären Unterfeldmessers in der Gadgetzan Water Company.$B$BDa die Nomaden unsere Brunnen erobern, müssen wir weitere freie Wasserquellen ausschöpfen! Es gibt Wasser in der Wüste, aber nur für die, die klug genug sind, sie erst zu erforschen.$B$BNehmt diesen Wünschelrutenapparat und zapft damit eine Wasserprobe vom Teich in der Nähe der Sandsorrow-Wache. Er befindet sich direkt in Sichtweite der Trolle dort. Bringt mir den angezapften Apparat zurück, wenn Ihr fertig seid!",objectives={"Benutzt den unangezapften Wünschelrutenapparat in der Nähe des Teichs bei der Sandsorrow-Wache. Bringt den angezapften Wünschelrutenapparat zum Leitenden Feldmesser Fizzledowser nach Gadgetzan zurück, wenn Ihr die Probe entnommen habt."}]])
R(993,"Ein verirrter Meister",[[description="Der Umhang ist fertig, $n. Jetzt ist es an der Zeit, Volcor zu suchen. Ich hoffe nur, dass wir es noch rechtzeitig schaffen.$B$BDie Magie des Umhangs hält nicht lang an, nachdem sie herbeigerufen wurde - etwa fünf Minuten. Es liegt an Euch zu entscheiden, wann Ihr sie benutzt: Ich schlage vor, dass Ihr damit wartet, bis Ihr Grimmklaue gefunden habt.$B$BFalls es wahr ist, was er mir erzählte, findet Ihr seinen Meister in einer Höhle südlich von hier. Grimmklaue wird an der Straße auf Euch warten. Gebt ihm ein Signal, indem Ihr winkt, sobald Ihr ihn gesehen habt, dann wird er Euch den Weg zu seinem Meister weisen.",objectives={"Sucht Volcor in Dunkelküste und gebt ihm den verzauberten Mondpirscherumhang."}]])
R(994,"Flucht durch Gewalt",[[description="Gut, $n, dann sei es Gewalt. Lasst uns hier verschwinden, sobald Ihr bereit seid. Wir werden uns unseren Weg hinunter zur Straße erkämpfen - Grimmklaue dürfte immer noch dort sein. Sobald wir sie erreicht haben, können wir uns trennen.$B$BTerenthis wird sofort Eure Version der Geschichte hören wollen, also geht nach Auberdine, sobald wir es hier herausgeschafft haben.",objectives={"Beschützt Volcor, bis Ihr die Straße erreicht habt und sprecht dann mit Terenthis in Auberdine."}]])
R(995,"Flucht durch Verstohlenheit",[[description="Na gut... wenn Ihr sicher seid, werden wir uns hier hinausschleichen. Lasst uns verschwinden, sobald Ihr bereit seid.$B$BVergesst nicht, Euch in Auberdine mit Terenthis zu treffen, sobald Euch die Flucht gelungen ist. Ich werde mich auf eigene Faust dort hinbegeben, da ich wahrscheinlich schneller bin als Ihr.",objectives={"Flieht aus der Furbolghöhle und trefft Euch in Auberdine mit Terenthis."}]])
R(996,"Verderbte Windblüte")
R(997,"Denalans Erde",[[description="Seid Ihr nach Süden unterwegs? Zum Al'Amethsee? Wenn dem so ist, möchte ich Euch um einen Gefallen bitten...$B$BMein Kollege Denalan hat am Ostende des Sees ein Lager aufgeschlagen, in dem er die Pflanzenwelt Teldrassils studiert und Experimente betreibt. Er hat in Darnassus ein Gebinde rarer Erde bestellt, und die Lieferung kam erst kürzlich mit Verspätung hier in Dolanaar an.$B$BWürdet Ihr ihm dieses Gebinde wohl bringen?",objectives={"Bringt Denalan am Al'Amethsee das Gebinde rarer Erde."}]])
R(998,"Verderbte Windblüte")
R(999,"When Dreams Turn to Nightmares")
R(1000,"Die neue Grenze",[[description="Aufgemerkt, Helden!$B$BDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.$B$BInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Weitere Informationen erhaltet Ihr beim Erzdruiden Hamuul Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.",objectives={"Sprecht auf der Anhöhe der Ältesten in Thunder Bluff mit dem Erzdruiden Hamuul Runetotem über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor."}]])
R(1001,"Dröhnkiste 411",[[description="Aus dem Inneren der Maschine ist eine leise Stimme zu hören.$B$B\"Hier spricht Wizbang! Die nächste Dröhnkiste befindet sich nördlich von Auberdine, am Strand.$B$BAlso, es ist die Dröhnkiste mit der Nummer 411 und es werden 3 Drescheraugen benötigt, um sie zu reparieren. Sie befinden sich direkt vor der Küste! Die Dunkelküstendrescher... *Hick*... Tut mir Leid...$B$BÜbrigens, wie beim letzten Mal wird die Dröhnkiste Eure Belohnung ausspucken, sobald Ihr die Sachen in die Maschine eingebaut habt. *Hick*... Was? Nein, mir geht's gut!\"",objectives={"Besorgt Euch 3 Drescheraugen von den Dunkelküstendreschern im tiefen Meer in der Nähe der Dröhnkiste 411."}]])
R(1002,"Dröhnkiste 323",[[description="Die Dröhnkiste gibt statische Geräusche von sich, als Wizbang zu sprechen beginnt.$B$B\"Die nächste Dröhnkiste ist Nummer 323. Schteht nördlich von Auberdine, aber... wo's das Bier? Wa...? Oh, schteht direkt an der Straße, kann man gar nicht verfehlen, gleich neben der Brücke.\"$B$BWizbang murmelt wirres Zeug vor sich hin, bevor Ihr ein lautes Schluckgeräusch hört.$B$B\"Der da fehlen Mondpirscherfangzähne... sechs davon.\"",objectives={"Sammelt 6 Mondpirscherfangzähne und baut sie in Dröhnkiste 323 ein."}]])
R(1003,"Dröhnkiste 525",[[description="Wizbangs zitternde Stimme übertönt die Blubber- und Tropfgeräusche, die aus dem Inneren der Maschine dringen.$B$B\"Näxte is' die Straße weiter runter nach Süden. Is' leicht zu find'n... direkt am Straßenrand... neben ei'm Sssaun. Glaub, ich hab sie hinner'n paar Büscheln verschteckt... Büschen. Hehehe... Jaaa, Dröhnkiste 525 fehlen ergraute Skalps von dies'n grauhaarigen Dischtelbären. Mann, das schpricht sich blöd. Dissstelbär... Hehehe...\"$B$BIhr hört weitere Schluckgeräusche, dann schaltet sich die Maschine aus. Plötzlich erwacht sie jedoch wieder zum Leben.$B$B\"4!\"",objectives={"Sammelt 4 ergraute Skalps von ergrauten Distelbären südlich von Auberdine und legt sie in die Dröhnkiste 525."}]])
R(1004,"Die neue Grenze",[[description="Aufgemerkt, Helden!$B$BDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.$B$BInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Weitere Informationen erhaltet Ihr beim Erzdruiden Hamuul Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.",objectives={"Sprecht auf der Anhöhe der Ältesten in Thunder Bluff mit dem Erzdruiden Hamuul Runetotem über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor."}]])
R(1005,"What Lurks Beyond")
R(1006,"What Lies Beyond")
R(1007,"Die antike Statuette",[[description="Ich würde Euch gern eine Aufgabe übertragen, $N.$B$BIch war auf meinem kleinen Schiff und kreuzte über den versunkenen Ruinen von Zoram, als ich plötzlich von Naga angegriffen wurde, die aus dem Wasser stießen und mich mit ihren Klauen beharkten! Ich floh und nahm alle Vorräte mit, die ich tragen konnte, um dieses bescheidene Lager zu errichten.$B$BAls ich jedoch die Küste erreichte und weglief ... verlor ich meinen liebsten Besitz.$B$BBitte, $N, geht zu dem Ort vor der Küste im Norden, an dem ich in den Hinterhalt geriet, und sucht dort nach einer antiken Statuette. Sie ist der Grund, warum ich die Gefahren des Zoramstrands auf mich genommen habe.",objectives={"Bringt Talen im Lager in der Nähe des Zoramstrands die antike Statuette."}]])
R(1008,"Der Zoramstrand",[[description="Böses lauert an unserer nordwestlichen Küste, die als Zoramstrand bekannt ist.$B$BEs ist die Ruhestätte der untergegangenen Stadt Zoram, die während der großen Teilung zerstört wurde und im Meer versank. Die Nachtelfen verloren sie vor Unzeiten. Sie war verloren und fast vergessen.$B$BJetzt allerdings sind die Naga zurückgekehrt, aber warum, wissen wir nicht. Es ist auch unwichtig. Wir müssen diese Scheusale vernichten und zurück in die Tiefe treiben!$B$BKehrt zu mir zurück, wenn Ihr Eure Mission abgeschlossen habt.",objectives={"Bringt Shindrell Swiftfire in Astranaar 20 Köpfe von Rächerflossen."}]])
R(1009,"Ruuzel",[[description="Ich fürchte, die Geheimnisse der antiken Statuette werden für immer verborgen bleiben, wenn Ihr nicht den Schlüssel zu ihrem antiken Schloss findet.$B$BDieser Schlüssel ist ein Ring, der Ring von Zoram. Er gehörte einst den Herrschern dieser Stadt, bevor sie in den Wellen der großen Teilung unterging.$B$BÜber Jahre hinweg war der Ring verloren, aber die Naga haben ihn vor kurzem gefunden.$B$BRuuzel, ihr Anführer, haust auf einer Insel am Nordrand von Zoram. Bitte, $N, holt mir meinen Ring!",objectives={"Bringt Talen im Lager in der Nähe des Zoramstrands den Ring von Zoram."}]])
R(1010,"Bathranshaar",[[description="Es gibt eine Pflanze, die früher einmal in den alten Ruinen von Bathrans Schlupfwinkel im Norden wuchs. Die Pflanze namens Bathranshaar war als Heilmittel für Krankheiten des Geistes bekannt.$B$BEin Kind im Dorf ist krank geworden und ich glaube, dass es sich nicht nur um eine körperliche Krankheit handelt. Würdet Ihr wohl zu Bathrans Schlupfwinkel reisen und dort für mich nach Bathranshaar suchen? Ich könnte es brauchen, wenn ich das Kind richtig behandeln soll.$B$BBathrans Schlupfwinkel liegt nördlich von Maestras Posten und gleich südlich der Grenze zu Dunkelküste.",objectives={"Bringt Orendil Broadleaf in Ashenvale 5 Bathranshaar-Pflanzen."}]])
R(1011,"Verlassenenkrankheit",[[description="Die Verlassenen, der untote Arm der Horde, haben sich in Ashenvale eingeschlichen und treiben sich in unseren Ruinen und Grabhügeln herum. Wir glauben, dass sie die Krankheit im Land der Nachtelfen verbreiten wollen. Wir müssen das genau wissen!$B$BDie Verlassenen haben südlich von hier, in der Nähe des Dor'danil-Grabhügels, ein Lager, in dem sie Gifte und Krankheiten entwickeln und in Flaschen füllen. Kämpft Euch in das Lager hinein und stehlt eine Krankheitsflasche. Bringt mir eine solche Flasche. Ich werde sie testen und herausfinden, was sie bewirkt.",objectives={"Bringt Kayneth Stillwind in Forest Song eine Krankheitsflasche."}]])
R(1012,"Irrsinnige Druiden",[[description="Als ich mich mit den Giften der Verlassenen abplagte, hatte ich eine Vision. Ich sah die Druiden des Dor'danil-Grabhügels vergiftet... ermordet von den Untoten! Sie sind jetzt Geister, die getrennt von ihren Körpern und in den Wahnsinn getrieben ziellos umherirren.$B$BIhr müsst den Dor'danil-Grabhügel betreten und die früheren großen Anführer vernichten, damit die Geister der Druiden eines Tages wieder Frieden finden: Taneel Darkwood, Uthil Mooncall und Mavoris Cloudsbreak.$B$BTut dies und kehrt dann zu mir zurück.",objectives={"Tötet die Druiden Taneel Darkwood, Uthil Mooncall und Mavoris Cloudsbreak und kehrt dann zu Kayneth Stillwind in Forest Song zurück."}]])
R(1013,"Das Buch von Ur",[[description="$N, in der Burg Shadowfang gibt es ein Buch, das Buch von Ur, das ich unbedingt in meiner Sammlung haben möchte. Ur war einst ein großer Magier aus Dalaran bevor die Geißel kam. Seine Studien anderer Welten sind von großem Wert für... bestimmte Kreise der Verlassenen.$B$BBetretet die Burg Shadowfang und sucht das Buch. Bringt es mir, dann kann ich unserer dunklen Fürstin von Euren Diensten berichten...",objectives={"Bringt dem Bewahrer Bel'dugur im Apothekarium in Undercity das Buch von Ur."}]])
R(1014,"Arugal muss sterben",[[description="Arugal lebt immer noch in der Burg Shadowfang. Wir können Silberwald erst dann als strategische Festung für die dunkle Fürstin beanspruchen, wenn Arugal erschlagen ist.$b$bIch werde mich darum kümmern, seine Magie zu neutralisieren, $n. Ich überlasse es jedoch Euch, für Arugals Tod zu sorgen, den er mehr als verdient.$b$bReist zur Burg Shadowfang und setzt Arugals üblen Zaubern ein für alle Mal ein Ende. Bringt mir den Kopf dieses niederträchtigen Hexers!",objectives={"Tötet Arugal und bringt Dalar Dawnweaver in dem Grabmal seinen Kopf."}]])
R(1015,"Die neue Grenze",[[description="Aufgemerkt, Helden!$B$BDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.$B$BInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Sprecht in Darnassus mit dem Erzdruiden Fandral Staghelm, er hat weitere Informationen!",objectives={"Sprecht in der Enklave des Cenarius in Darnassus mit dem Erzdruiden Fandral Staghelm über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor."}]])
R(1016,"Elementararmschienen",[[description="Nehmt diese Rolle der Bestimmung; sie kann den Schöpfer dieser Elementare bestimmen. Aber Ihr werdet etwas von ihnen benötigen, um es als Reagenz zum Fokussieren der Magie dieser Rolle zu verwenden; ihre Armschienen sollten hervorragend dafür geeignet sein.$B$BEin paar wenige intakte Armschienen dieser Kreaturen dürften reichen. Die anderen Armschienen werden für unsere Zwecke nutzlos sein, aber sie könnten einem Händler etwas wert sein, wenn Ihr sie verkaufen wollt. Nachdem Ihr die intakten Armschienen habt, versucht die Rolle zu verwenden. Kehrt mit den Ergebnissen zu mir zurück und dann werden wir weitersehen.",objectives={"Sammelt 5 intakte Elementararmschienen und wendet die Rolle der Bestimmung darauf an. Bringt danach der Schildwache Velene Starstrike in der Silberwindzuflucht die Rolle der Bestimmung."}]])
R(1017,"Magier-Beschwörer",[[description="Es gibt nur einen untoten Magier im Brachland, der in der Lage wäre, so viele Wasserelementare zu entweihen. Er ist auch der Einzige, der dumm genug wäre, es zu versuchen. Sarilus Foulborne sitzt wahrscheinlich jetzt gerade oben auf dem Glutnebelgipfel und lacht mich aus.$B$B$N, Ihr müsst Euch in Feindesland begeben und diesen Übeltäter vernichten. Ich habe genug von seinem Schwachsinn und wir müssen ihm zeigen, was mit jenen geschieht, die die Schildwachen verärgern.$B$BVernichtet ihn und bringt mir seinen Kopf. Vorsicht allerdings, die Horde könnte nach Euch Ausschau halten.",objectives={"Erschlagt Sarilus Foulborne und bringt Schildwache Velene Starstrike in der Silberwindzuflucht seinen Kopf."}]])
end f(R) end
do local function f(R)
R(1018,"Die neue Grenze",[[description="Aufgemerkt, Helden!$B$BDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.$B$BInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Weitere Informationen erhaltet Ihr beim Erzdruiden Hamuul Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.",objectives={"Sprecht auf der Anhöhe der Ältesten in Thunder Bluff mit dem Erzdruiden Hamuul Runetotem über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor."}]])
R(1019,"Die neue Grenze",[[description="Aufgemerkt, Helden!$B$BDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.$B$BInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Sprecht in Darnassus mit dem Erzdruiden Fandral Staghelm, er hat weitere Informationen!",objectives={"Sprecht in der Enklave des Cenarius in Darnassus mit dem Erzdruiden Fandral Staghelm über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor."}]])
R(1020,"Orendils Heilmittel",[[description="$N, ich habe ein Heilmittel entwickelt, mit dem man dem erkrankten Kind bestimmt helfen kann. Bringt es nach Astranaar und gebt es dem Vater des Kindes, Pelturas Whitemoon.$B$BUm nach Astranaar zu gelangen, folgt der Straße gen Süden und dann gen Osten.",objectives={"Bringt Pelturas Whitemoon in Astranaar Orendils Heilmittel."}]])
R(1021,"Elende Satyrn! Die Dryaden sind in Gefahr!",[[description="Ich weiß zwar nicht, wer Ihr seid, aber ich brauche Eure Hilfe. Meine Schwestern wollten den Satyrn den Zweig des Cenarius abnehmen. Sie sagten, dass sie bald zurück sein werden, aber das war vor zwei vollen Tagen!$B$B$N, Ihr müsst sie finden! Sie wollten nach den Ruinen eines Nachtelfentempels in Xavian im Nordosten suchen. Ich weiß nicht, was ich davon halten soll. Sucht nach Anilia, sie wollte sie bei der Suche führen.",objectives={"Sucht in Xavian nach Anilia."}]])
R(1022,"Das heulende Tal",[[description="Obwohl wir viele Mittel und große Bemühungen investiert haben, um auch die letzten Dämonen aus dem Teufelswald im Norden zu vertreiben, hatten wir nur wenig Erfolg damit. Wir konnten jedoch einen Großteil der Dämonen von Ashenvale fern halten.$b$bIm Norden, nahe der Grenze zum Teufelswald, wurde der verfallene Mel'Thandris-Schrein von rätselhaften Wolfmenschen übernommen. Ihre Schreie, die einem das Blut in den Adern gerinnen lassen, haben dem als \"Das heulende Tal\" bekannten Gebiet seinen Namen gegeben. Der Foliant von Mel'Thandris, der im Schrein aufbewahrt wird, könnte etwas Licht darauf werfen, warum die Wolfmenschen hier sind.",objectives={"Begebt Euch ins heulende Tal, studiert den Folianten von Mel'Thandris und kehrt dann zur Schildwache Melyria Frostshadow beim Schrein von Aessina zurück."}]])
R(1023,"Raenes Säuberung",[[description="Während Ihr Teronis Habseligkeiten durchstöbert, stoßt Ihr auf ein Tagebuch, das noch in gutem Zustand ist.$B$BIhr nehmt das Tagebuch und lasst Teronis' Kadaver so wie er ist zurück.$B$BJetzt müsst Ihr nur noch eines tun: den Edelstein finden, den Teronis suchte. Raene deutete an, dass er sich in diesem Gebiet befinden würde. Vielleicht haben ihn die Murlocs ...",objectives={"Sucht den leuchtenden Edelstein und bringt ihn zusammen mit Teronis' Tagebuch zu Raene Wolfrunner in Astranaar."}]])
R(1024,"Raenes Säuberung",[[description="Ihr werdet selbst Nachforschungen anstellen müssen, aber gemäß Teronis' Notizen scheint es unsere nächste Aufgabe zu sein, die anderen Teile der Rute zu finden, die Dartol erschuf. Ich würde mich zunächst zum Mondbrunnen östlich des Irissees begeben. Wenn Ihr bereit seid, folgt der Straße und wendet Euch gen Norden, wenn Ihr einen kleinen Sitzbereich zu Eurer Linken erreicht.$B$BDort findet Ihr eine Dryade namens Shael'dryn, die Euch eine bessere Führerin sein wird. Sucht sie auf.$B$BBehaltet den Edelstein - Shael'dryn wird ihn brauchen, um Euch bei der Wiederherstellung der Rute zu helfen.",objectives={"Sucht Shael'dryn beim Mondbrunnen im Nordosten auf."}]])
R(1025,"Eine aggressive Verteidigung",[[description="Bevor Ihr zum Mondbrunnen aufbrecht, habe ich noch eine andere Aufgabe für Euch, wenn Ihr gern Eure Fertigkeiten auf die Probe stellen und dem Volk von Ashenvale helfen würdet.$B$BEntlang der Straße, die nach Osten führt, haben Furbolgs kurz vor dem Falfarren Reisende angegriffen. Ihre gequälten Seelen nähren sich von Angst und sie stillen ihren Appetit mit dem Blut Unschuldiger.$B$BHelft den Schildwachen, das Land zu schützen, indem Ihr diesen Monstern dieselbe Gnade zeigt, die sie uns erwiesen haben.$B$BIch glaube, ihre Lager liegen südlich der Straße ... seid vorsichtig.",objectives={"Tötet 1 Höhlenbehüter, 2 Ursa, 10 Totemiker sowie 12 Krieger der Fäulnisklauen und kehrt dann zu Raene Wolfrunner in Astranaar zurück."}]])
R(1026,"Raenes Säuberung",[[description="Ich wünschte, Ihr hättet bessere Nachrichten.$B$BRaene hat Recht, ich weiß von Dartols Werk und den Treants, den Baumwesen in diesem Gebiet - zumindest wusste ich es einst. Heute sind sie verderbt, ihre Natur verzerrt.$B$BFalls es Euer Ziel ist, das nächste Teil der Rute zu finden, solltet Ihr zunächst den Schlüssel suchen, mit dem die Truhe geöffnet werden kann, in dem es sich befindet.$B$BEiner der Treants nordöstlich von hier in der Nähe des Teufelswalds hat ihn. Sobald Ihr ihn habt, sucht nach einem kleinen Tal westlich der Straße nahe der Grenze zum Teufelswald... die Truhe ist dort irgendwo versteckt.",objectives={"Sucht den hölzernen Schlüssel und das Teil von Dartols Rute, bevor Ihr zu Shael'dryn beim Mondbrunnen zurückkehrt."}]])
R(1027,"Raenes Säuberung",[[description="Das letzte Teil der Rute wurde in die Obhut der Druiden von Dor'danil gegeben. Ich habe keine Ahnung, wo sie es versteckt haben. Es tut mir Leid, dass ich Euch da nicht weiterhelfen kann.$B$BIch kann Euch nur sagen, folgt der Straße, die zum Brachland führt. Die Druiden suchten östlich dieser Straße Zuflucht, aber sie werden Euch nicht viel helfen können: Sie wurden kürzlich getötet ... Ich mag gar nicht darüber nachdenken.$B$BWenn Ihr das letzte Teil gefunden habt, bringt es mir, dann helfe ich Euch, die Rute wieder zusammenzusetzen.",objectives={"Sucht das letzte Teil von Dartols Rute und bringt es Shael'dryn beim Mondbrunnen."}]])
R(1028,"Raenes Säuberung",[[description="Hier habt Ihr die vollständige Rute, $n. Es war nicht schwer, sie wieder zusammenzusetzen... Den Schrein zu finden, der die Kraft hat, sie wieder aufzuladen, ist der schwierige Teil.$B$BMit etwas Konzentration und Einsatz sollte es für jemanden wie Euch, der bereits so viel erreicht hat, allerdings nicht zu schwer sein.$B$BGeht von hier aus nach Südosten - es gibt nur wenige Wege, also seid vorsichtig - und behaltet immer den Norden im Auge. Der Schrein liegt in den Bergen verborgen, die dieses Tal umgeben.$B$BDort angekommen legt Ihr die Rute in den Schrein... der Rest ist Magie. Hehe.",objectives={"Sucht den verborgenen Schrein und verzaubert Dartols Rute erneut."}]])
R(1029,"Raenes Säuberung",[[description="Ich schlage vor, dass Ihr Raene aufsucht und sie wissen lasst, dass die Rute fertig gestellt ist. Sie weiß bestimmt, was Ihr als Nächstes tun solltet.$B$BViel Glück, $N.",objectives={"Kehrt zu Raene Wolfrunner in Astranaar zurück."}]])
R(1030,"Raenes Säuberung",[[description="Leider bin ich mir nicht ganz sicher, was er als Nächstes vorhatte.$B$BWenn es wahr ist, was er über die Macht der Rute sagte, könnt Ihr mit ihrer Hilfe eine völlig andere Gestalt annehmen. Welche Gestalt weiß ich allerdings nicht.$B$BVielleicht wollte er ihre Kräfte nutzen, um näher an die besudelten Furbolgs heranzukommen, aber selbst die nicht verderbten Kreaturen hätten ihn getötet, wäre er nicht vorsichtig gewesen. Durch die Rute verwandelt, hätte Dartol wahrscheinlich mit einem Furbolg gesprochen, der gegen die Auswirkungen des Teufelsmooses gefeit ist.$B$BIhr solltet Eure Suche südöstlich des Mystralsees beginnen.",objectives={"Sucht einen nicht verderbten Furbolg und benutzt die Macht von Dartols Rute der Transformation, um mit ihm zu sprechen."}]])
R(1031,"Der Zweig des Cenarius",[[description="Anilia legt Euch die Hände auf die Schultern und zieht Euch zu sich heran. Nach Luft ringend zeigt sie in Richtung des Bogens im Norden, bevor sich ihre Augen schließen und sie einen letzten, keuchenden Atemzug ausstößt. \"Er hat ihn... Geltharis...\" In Eurem Herzen wisst Ihr, dass es Anilias letzter Wunsch war, den Zweig des Cenarius wieder in den Händen der Dryaden zu sehen.",objectives={"Tötet Geltharis und bringt Illiyana beim Schrein von Aessina den Zweig des Cenarius."}]])
R(1032,"Satyrn schlachten!",[[description="Ich kann nicht glauben, dass Anilia von uns gegangen ist... Wir haben doch immer zusammen in den Wäldern gespielt. Ich fühle beinahe so etwas wie... Trauer.$B$BEs gibt aber etwas, das mich vielleicht aufheitern könnte! Bitte, erschlagt die Satyrn, die mir Anilia genommen haben! Bringt mir ihre Hörner als Beweis Eurer Taten und Ihr könnt Euch auf ewig meines Dankes gewiss sein.",objectives={"Bringt Illiyana im Schrein von Aessina 16 Satyrhörner."}]])
R(1033,"Elunes Träne",[[description="Ich hatte gehofft, Orendils Heilmittel würde Relara retten, aber ich fürchte, es hat die Krankheit, die in meinem Kind wütet, nur gedämpft. Wir müssen eine stärkere Medizin finden! Zum Glück hat mir Orendil von weiteren Arzneien erzählt, sollte seine Erste versagen.$B$BTräne von Elune ist eine Gesteinsart, die nur an einem Ort vorkommt: auf der Insel im Irissee, östlich von Astranaar. Orendil sagte, der Stein könne Verderbnis wegwaschen ... Bitte, $N, bringt mir eine Träne von Elune und betet, dass sich die Erkrankung meiner Tochter damit heilen lässt!",objectives={"Bringt Pelturas in Astranaar die Träne von Elune."}]])
R(1034,"Die Sternenstaubruinen",[[description="Die Träne von Elune hat einen Teil der Erkrankung meiner Tochter weggewaschen. Ihre Alpträume haben nachgelassen und ich danke der Göttin für ihren Segen. Aber... immer noch wütet das Fieber in ihr.$B$BOrendil erzählte mir von einem gefrorenen Staub, den man in den Sternenstaubruinen findet. Vielleicht kann man damit Relaras Fieber senken. Sammelt etwas von diesem Staub und kommt dann bitte wieder zu mir zurück.$B$BDie Sternenstaubruinen liegen im Süden, $N. Möge Elune Eure Reise beschleunigen.",objectives={"Bringt Pelturas in Astranaar 5 Hand voll Sternenstaub."}]])
R(1035,"Fallenskysee",[[description="Relara hat kein Fieber mehr, aber sie ist immer noch sehr schwach. Ich glaube nicht, dass sie wieder zu Kräften kommt, wenn wir einfach nur abwarten. Ich glaube, dazu bedarf es der Kraft eines Mondsteins.$B$BWir haben Mondsteine früher immer beim Fallenskysee im Südosten gesammelt... bis die Schattendickichtbäumlinge kamen.$B$BIhr Anführer, das Schattendickichtorakel, hat alle gefallenen Mondsteine eingesammelt und hortet sie. Jetzt müsst Ihr Euch einen Mondstein von dem Orakel holen.$B$BUnd dazu werdet Ihr ihn wohl erschlagen müssen, fürchte ich.",objectives={"Holt von dem Schattendickichtorakel einen gefallenen Mondstein und bringt ihn Pelturas in Astranaar."}]])
R(1036,"Hierher, Taugenichts",[[description="$n... Ja, ich habe von Euch gehört. Ich habe gehört, dass Ihr kein Freund von Beutebucht seid - genau wie wir Blutsegelbukaniere. Flottenmeister Firallon sucht nach gesunden und tüchtigen $gMännern:Frauen; wie Euch für eine spezielle Mission.$B$BWenn Ihr interessiert seid, begebt Euch zur Purpurschleier und sprecht mit ihm unter Deck. Sie ankert vor der wilden Küste östlich von hier, bei der Springflut und der Maid im Glück.",objectives={"Sprecht mit Flottenmeister Firallon an Bord der Purpurschleier vor der Küste des Schlingendorntals."}]])
R(1037,"Velinde Starsong",[[description="Velinde Starsong war hier in Ashenvale meine Vorgängerin. Zunächst schien es, als hätte sie die Lage im Teufelswald unter Kontrolle, aber nach und nach ließen ihre Bemühungen nach. Eines Tages verschwand sie einfach.$b$bMan schickte mich hierher, um ihre Arbeit fortzusetzen. Ich fürchte jedoch, dass ich nichts über die Priesterin weiß. Vielleicht weiß Thyn'tel Bladeweaver, eine der Kommandantinnen der Schildwache, mehr über ihr Verschwinden, das ich nicht miterlebt habe.$b$bSie wird sicherlich wissen, wie wichtig diese Informationen sind.",objectives={"Sprecht auf der Terrasse der Krieger in Darnassus mit Thyn'tel Bladeweaver."}]])
R(1038,"Velindes Besitztümer",[[description="Der Foliant von Mel'Thandris hat Euch das gezeigt? Dann könnte es wohl nicht schaden, wenn ich Euch erlaubte, ihre Habseligkeiten durchzusehen. Mit diesem Schlüssel könnt Ihr die Truhe öffnen, in der wir ihre Sachen in der Schildwachenbaracke aufbewahren. Sie führte ein Tagebuch über ihre Pflichten und wenn es etwas zu erfahren gibt, dann daraus.$b$bIch sollte Euch noch sagen, dass die Schildwachen denken, dass sie Gründe für ihr Verschwinden hatte und damit rechnen, dass sie jederzeit wieder auftaucht. Die Priesterin hat in der Vergangenheit viel geleistet und unser Vertrauen verdient.",objectives={"Durchsucht Velindes Truhe nach ihrem Tagebuch und bringt es zusammen mit dem Schlüssel nach Darnassus zu Thyn'tel Bladeweaver."}]])
R(1039,"Der Brachlandhafen",[[description="Ratchet ist der einzige Hafen des Brachlandes. Höchstwahrscheinlich hat Velinde in Ratchet ein Handelsschiff gefunden, das sie zur Schwarzmeerbucht in Azeroth brachte. Wir haben nur wenig mit den Goblins zu tun, die den Hafen leiten, aber der Dockmeister sollte über das Kommen und Gehen von Schiffspassagieren informiert sein.$b$bFolgt der Straße in südöstlicher Richtung durch Ashenvale, dann gelangt Ihr irgendwann ins Brachland. Seid auf der Hut, $n, Krieger der Horde streifen durch das Land. Im Hafen werdet Ihr jedoch sicher sein.",objectives={"Sprecht in Ratchet mit Werftmeister Dizzywig."}]])
R(1040,"Passage nach Booty Bay",[[description="Ah ja, da steht's ja. Hättet mir sagen sollen, dass sie vor so langer Zeit hier durchgekommen ist. Mal sehen.$b$bVelinde. Hat eine Passage auf der BLACK OSPREY nach Booty Bay gebucht. Da hier nichts anderes steht, nehme ich an, dass sie den Hafen dort sicher erreicht hat.$b$bViel mehr Hilfe kann ich Euch nicht anbieten, aber sie hat mich nach einem Überlandtransport zur anderen Seite der Welt gefragt und ich habe ihr Ruzzgot vorgeschlagen, einen Karawanenführer aus Booty Bay. Kann sein, dass Velinde mit ihm gereist ist.$b$bUnd jetzt fort mit Euch. Ich hab zu tun.",objectives={"Nehmt ein Schiff nach Booty Bay und sprecht dort mit dem Karawanenführer Ruzzgot."}]])
R(1041,"Die Karawanenstraße",[[description="Da hab ich mich wohl in Euch getäuscht und das passiert mir nicht alle Tage.$b$bZufällig erinnere ich mich an diese Velinde, nach der Ihr sucht. Kommt nicht jeden Tag vor, dass eine Nachtelfenpriesterin mit einer schmutzigen alten - aber alle Transportwünsche erfüllenden - Karawane wie der meinigen reisen will.$b$bAuf dem Weg nach Norden trennten wir uns, sie wollte weiter nach Dunkelhain. Der Amtmann dort macht alle möglichen Aufzeichnungen. Kann sein, dass er etwas Nützliches weiß.$b$bSeid im Dschungel vorsichtig, der ist selbst in günstigsten Zeiten tödlich.",objectives={"Sprecht in Dunkelhain mit Amtmann Daltry."}]])
R(1042,"Die Familie Carevin",[[description="Nein, ich habe keinen Eintrag über eine Velinde Starsong, die sich in Dunkelhain aufgehalten haben soll... Wenn Ihr erlaubt, ich kann mir auch nicht vorstellen, dass eine Nachtelfenpriesterin sich in einem Gasthaus einquartiert, wenn Ihr wisst, was ich meine.$b$bDiese Wolfmenschen, die Ihr erwähntet, von denen hab ich schon mal gehört. Erst kürzlich kam Calor mit einer ganzen Reihe Köpfe von denen in die Stadt zurück. Er arbeitet für die Familie Carevin. Sie jagen Dämonen, Untote und andere Monster. Sprecht mit Jonathan, er ist der Haushaltsvorstand.",objectives={"Sprecht mit Jonathan Carevin in Dunkelhain."}]])
R(1043,"Die Sense von Elune",[[description="Eure Geschichte klingt glaubhaft... Ich habe Eure Beweggründe zwar noch nicht ganz begriffen, aber wenn es zu Euren Angelegenheiten hier im Dämmerwald gehört, die Worgs im Wald auszurotten, dann können mir Eure Beweggründe auch herzlich egal sein, solange das Ergebnis stimmt.$b$bIm Süden gibt es eine Mine, die von Worgs überrannt wurde... Sie kamen aus dem Nichts, aber nach allem, was wir wissen, hat man sie dort zuerst gesehen.$b$bGeht Ihr nur Euren Angelegenheiten nach, aber ich möchte Euch bitten, dass Ihr mir Bescheid gebt, sobald Ihr etwas Wichtiges entdeckt. Wir sind für jede Hilfe gegen das Böse dankbar.",objectives={"Sucht nach Hinweisen auf die Sense von Elune und kehrt dann zu Jonathan Carevin in Dunkelhain zurück."}]])
R(1044,"Beantwortete Fragen",[[description="Wir werden das Worgproblem in den Griff bekommen, keine Frage. Das Böse, das Eure Freundin in unseren Wald gebracht hat, wird eingedämmt werden und ich nehme ihr ihre Handlungen nicht übel. In letzter Zeit gehen seltsame Dinge vor sich, $n, und die Dunkelheit kennt keine Atempausen.$b$bIch will Euch nicht länger aufhalten. Mir scheint, dass auch andere erfahren sollten, was Ihr in den Minen des Dämmerwalds entdeckt habt.",objectives={"Kehrt nach Darnassus zu Thyn'tel Bladeweaver zurück."}]])
R(1045,"Raenes Säuberung",[[description="Die Nachtelfen sind so alt wie die Zeit, aber sie zerstören ihre eigene Welt durch ihre Arroganz. Und jetzt zerstören sie auch noch unser Leben. Doch das kann man nicht mehr verhindern...$B$BIch gebe den Elfen für viele Dinge die Schuld, aber wir sind immer noch für unsere Handlungen selbst verantwortlich. Wir sind sogar trotz der Verderbnis noch zu jeder Menge Bösem fähig.$B$BRan Blutreißer ist einer dieser Bösen. Machthungrig, gierig... die Verderbnis hat ihn nur noch stärker gemacht. Mein Hass auf die Elfen lodert, aber ich wünsche ihren Kindern nichts Schlimmes, wir müssen uns selbst im Zaum halten.",objectives={"Tötet Ran Blutreißer sowie 4 Wachen von Blutreißer und kehrt dann zu Krolg in der Nähe des Mystralsees zurück."}]])
R(1046,"Raenes Säuberung",[[description="Kehrt zu Eurem eigenen Stamm zurück und lasst ihn von Eurem Sieg hier wissen.$B$BZeigt ihm Eure Trophäe und sonnt Euch in Eurem Ruhm...",objectives={"Bringt Raene Wolfrunner in Astranaar Ran Blutreißers Schädel und Dartols Rute der Transformation."}]])
R(1047,"Die neue Grenze",[[description="Aufgemerkt, Helden!$B$BDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.$B$BInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Sprecht in Darnassus mit dem Erzdruiden Fandral Staghelm, er hat weitere Informationen!",objectives={"Sprecht in der Enklave des Cenarius in Darnassus mit dem Erzdruiden Fandral Staghelm über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor."}]])
R(1048,"In das Scharlachrote Kloster",[[description="Während die dunkle Fürstin sich um die dringende Angelegenheit des Vormarsches des Lichkönigs im Norden kümmert, sorge ich dafür, dass Dinge, die uns unmittelbar betreffen, entsprechend geregelt werden.$b$bDie Menschenplage, die sich selbst Scharlachroter Kreuzzug nennt, hat sich als der schärfste Dorn in unserem Fleisch erwiesen. Tirisfal wimmelt förmlich von diesen kleinen roten Ameisen.$b$bBegebt Euch zum Kloster, $C, und vernichtet Hochinquisitor Whitemane und seine obersten Offiziere.",objectives={"Tötet Hochinquisitor Whitemane, den Scharlachroten Kommandant Mograine, Herod, den Scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Varimathras in Undercity."}]])
R(1049,"Kompendium der Gefallenen",[[description="Der Irdene Ring hatte nur die besten Absichten, was unsere geplagten Brüder betraf. Aber wer weiß schon, welche Absichten jene verfolgen, die dem Ältestenrat Dinge einflüstern?$b$bDie Geschichte der Verlassenen, mit denen wir uns verbündet haben, ist von Lug und Trug durchzogen. Zu übereilt gingen wir unseren Pakt ein. Vielleicht hätte Cairne gut daran getan, die Warnungen aus Orgrimmar zu beherzigen.$b$bTief im Inneren des Scharlachroten Klosters liegt das 'Kompendium der Gefallenen' verborgen, das von irren menschlichen Zeloten bewacht wird. Ihr Tun ist von ihrem Wahnsinn geprägt, aber ihre Forschungen könnten nützlich für uns sein.",objectives={"Holt das 'Kompendium der Gefallenen' aus dem Kloster in Tirisfal und bringt es zu Sage Truthseeker in Thunder Bluff."}]])
R(1050,"Mythologie der Titanen",[[description="Die Zukunft ist unausweichlich! Wir stürzen ihr entgegen wie Regentropfen, die auf das Große Meer prasseln.$b$bAber vielleicht erfahren wir, indem wir die Vergangenheit studieren, was uns erwartet, und könnten uns besser auf das Unbekannte vorbereiten.$b$bBevor Lordaeron von all diesen schrecklichen Dingen heimgesucht wurde, gab es eine Bastion des Wissens, die in Tirisfal versteckt lag. Gerüchten zufolge soll es in der Bibliothek des alten Klosters ein Buch mit dem Titel 'Mythologie der Titanen' gegeben haben.$b$bBringt es mir, dann können wir vielleicht gemeinsam die Geheimnisse der Vergangenheit entschlüsseln!",objectives={"Holt die 'Mythologie der Titanen' aus dem Kloster und bringt die der Bibliothekarin Mae Paledust in Ironforge."}]])
R(1051,"Vorrels Rache",[[description="Trotz meines freien Willens kann ich der dunklen Fürstin nicht mehr dienen. Ich fühle, dass meine Zeit in Azeroth zu Ende geht. Meine Lebenskraft ist zerschmettert.$b$bDas hat mir Befrager Vishas angetan! Wochenlang quälte er mich! Nahm mir meinen Ehering und gab ihn seiner Frau. Dieser Bastard!$b$bRache ... Ich will Rache!$b$bDer eingebildete Narr prahlte immer mit seiner ach so kostbaren Frau Nancy, die am Lordameresee lebte. Spürt diese Frau auf, erschlagt sie und bringt meiner Frau Monika in Tarrens Mühle meinen Ehering.$b$bDies ist mein letzter Wille ...",objectives={"Bringt Monika Sengutz in Tarrens Mühle den Ehering von Vorrel Sengutz."}]])
R(1052,"Auf dem Scharlachroten Pfad",[[description="Wir vom scharlachroten Kreuzzug erheben Anspruch auf die Festungen zwischen Hearthglen und Tirisfal. Wir sind recht stolz auf unsere Bastionen der Säuberung in ganz Lordaeron.$b$bIhr habt Euch gegen die Untoten in Desolace bewiesen. Doch die wahre Bedrohung durch die Seuche liegt in Lordaeron.$b$bBegebt Euch nach Southshore in den östlichen Königreichen. Sucht dort nach einem Kreuzzügler namens Raleigh der Andächtige. Gebt ihm dieses Empfehlungsschreiben, das mein Siegel trägt, dann wird er Euch zu einem ehrwürdigen Ort in unserem scharlachroten Kloster führen.",objectives={"Bringt Raleigh dem Andächtigen in Southshore Bruder Antons Empfehlungsschreiben."}]])
R(1053,"Im Namen des Lichts",[[description="Einst diente ich dem Scharlachroten Kreuzzug mit Ehre, Treue und Stolz. Ich hielt das Ziel, das sie verfolgten, für edel: Azeroth von den Untoten befreien.$b$bAls ich jedoch im Kloster in Tirisfal weilte, erkannte ich, dass sie langsam den Bezug zur Wirklichkeit verloren. Jetzt halten sie jeden für verseucht, der nicht das Wams des Kreuzzuges trägt. Unschuldige Männer und Frauen wurden gefoltert, weil sie angeblich verseucht waren. $b$bDer Scharlachrote Kreuzzug muss im Namen des Lichts zerschlagen werden. Ihr, $n, müsst ihr wahnwitziges Regime beenden.",objectives={"Tötet Hochinquisitor Whitemane, den Scharlachroten Kommandant Mograine, Herod, den Scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Raleigh dem Andächtigen in Southshore."}]])
R(1054,"Die Auswahl der Bedrohung",[[description="Direkt im Norden Astranaars leben die Furbolgs vom Distelfellstamm. Meine Späher berichten, dass ihre Zahl sich in den letzten Monaten erhöht hat. Sollten es zu viele werden, könnten sie den Mut finden, Astranaar direkt anzugreifen.$B$BTötet so viele von ihnen, wie Ihr könnt, aber bringt mir den Schädel ihres Häuptlings zum Beweis dafür, dass ihr Bemühen im Keim erstickt wurde ... vorläufig.$B$BIch bleibe hier in Astranaar und warte auf Kunde von Euch. Elune sei mit Euch.",objectives={"Bringt Raene Wolfrunner in Astranaar Dal Blutklaues Schädel."}]])
R(1055,"Raenes Säuberung",[[description="Die Rute, jetzt wieder heil, liegt in Euren Händen. Shael'dryn wird von Eurem Erfolg hören wollen.",objectives={"Kehrt zu Shael'dryn beim Mondbrunnen zurück."}]])
R(1056,"Reise zum Steinkrallengipfel",[[description="Die Waldgeister sagten mir, dass Ihr mutig und zu reisen gewillt seid.$b$bIm Süden, nicht weit vom Mystralsee entfernt, liegt ein Tunnel namens Steinkrallenpfad. Durch diesen Tunnel gelangt Ihr in ein Gebiet, das im Steinkrallengebirge als Scherwindklippe bekannt ist. Dort angelangt reist südwestlich weiter, am Felskesselsee vorbei und dann nach Norden, den steilen Abhang hinauf, bis Ihr den Steinkrallengipfel erreicht.$b$bDort werdet Ihr von Hüter Albagorm erwartet. Tut, was er sagt, $R.$b$bDie Reise wird gefährlich.",objectives={"Reist zu Bewahrer Albagorm auf dem Steinkrallengipfel."}]])
R(1057,"Die Rückeroberung des verbrannten Tals",[[description="Als Beschützer der Waldgeister könnt Ihr sicher unschwer erraten, warum ich beunruhigt bin.$b$bIhr seid durch diese Berge gereist, um diesen Gipfel zu erreichen. Sicherlich habt Ihr das Zerrbild gesehen, zu dem das Land geworden ist. Gier hat zur Zerstörung dieser heiligen Hügel geführt.$b$bDie gierige motorisierte Armee der Industrialisten hat das verbrannte Tal im Süden in Brand gesteckt. Was noch schlimmer ist, die Blutfurien, die in unser Land eingedrungen sind, lassen uns nicht dorthin, um mit der Neuanpflanzung zu beginnen.$b$bVertreibt diese elenden Harpyien, $n!",objectives={"Bewahrer Albagorm auf dem Steinkrallengipfel möchte, dass Ihr 7 Harpyien der Blutfurien, 7 Wegelagerinnen der Blutfurien, 7 Töterinnen der Blutfurien und 7 Wildfedern der Blutfurien erschlagt."}]])
R(1058,"Jin'Zils Waldmagie",[[description="Ich bin ja so aufgeregt!$b$bDrei kleine Käfige mit drei kleinen Elfen! Aber was tun wir nur mit unseren süßen Baumschützer-Freunden? Na, lassen wir sie doch... wie nennen sie das doch gleich... Waldmagie schmecken!$b$bIch brauche einen ordentlichen Schuss Steinkrallensaft. Dann brauche ich ein paar Mondlichtläuferschnurrhaare von diesen schrecklichen Katzen. Das schreit nach einer Menge Renneraugen - man kann nie genug Augen haben. Oh, und bevor wir es vergessen, die wertvolle Schuppe eines Siechdrachen.$b$bSchnell zum Steinkrallengipfel, $n, damit ich etwas Waldmagie zusammenbrauen kann!",objectives={"Hexendoktor Jin'Zil in Malaka'jin möchte 5 Portionen Steinkrallensaft, 5 Schnurrhaare eines Mondlichtläufers, 30 Renner-Augen und die Schuppe eines Siechdrachen."}]])
R(1059,"Die Rückeroberung des verbrannten Tals",[[description="Die Blutfurien wurden besiegt. Sie werden sich jedoch schon bald wieder neu gruppieren, wenn wir nichts unternehmen.$b$bGanz weit im Süden des Brachlandes liegt ein Land, das als Tausend Nadeln bekannt ist. Wenn Ihr in Tausend Nadeln nach Westen reist bis zum üppigen Waldrand von Feralas, stoßt Ihr auf einen Druiden namens Falfindel Waywarder.$b$bDieser große und weise Druide kann große Waldgeister herbeirufen, die bei der Rekultivierung des verbrannten Tals helfen können.$b$bErzählt ihm von unserer Notlage! Sucht ihn sofort auf!",objectives={"Reist zu Falfindel Waywarder an der Grenze zwischen Tausend Nadeln und Feralas."}]])
R(1060,"Brief an Jin'Zil",[[description="Ihr habt mir sehr geholfen, $n. Ihr seid ein echter Glücksbringer, wie eine Hasenpfote, und ich möchte, dass Ihr Euch das hier einmal anseht.$B$BDie Harpyien stammen nicht aus dem Brachland. Sie kommen aus einem Ort namens Steinkrallengebirge, ganz weit nordwestlich von hier. Dort könnte es möglicherweise gefährlich für Euch sein, aber dieser Brief muss an einen alten Freund von mir überbracht werden, der dort lebt, ein Hexendoktor mit dem Namen Jin'Zil.$B$BEr wird sich freuen zu hören, dass Serena Blutfeder tot ist, und ich glaube, Ihr werdet das Steinkrallengebirge sehr interessant finden.",objectives={"Überbringt Jin'Zil in seiner Höhle im Steinkrallengebirge Darsoks Brief."}]])
R(1061,"Die Geister des Steinkrallengebirges",[[description="Die Geister des Steinkrallengebirges sind verärgert, weil Goblins und ihre Gefolgsleute das Land ausplündern und brandschatzen. Das Land rief um Hilfe, und jene, die auf so etwas achten... haben es gehört.$B$BSeereth Stonebreak, eine aufstrebende Schamanin der Horde, wurde in das Steinkrallengebirge geschickt. Sie berichtet von umfangreichen Rodungen durch die Goblins und bittet um Hilfe.$B$BTrefft Euch im Steinkrallengebirge mit Seereth. Um zu ihr zu gelangen, folgt der Straße westlich aus Crossroads im Brachland. Sie hat in der Nähe des Hochwipfeltals ein Lager aufgeschlagen.",objectives={"Sprecht im Steinkrallengebirge mit Seereth Stonebreak."}]])
R(1062,"Goblin-Eindringlinge",[[description="Die von Goblins geleitete Venture Company ist in das Steinkrallengebirge umgezogen, um dort Bäume zu fällen und ganze Waldflächen zu brandroden. Die Geister dort sind außer sich vor Schmerz und Wut. Wir müssen der Venture Company Einhalt gebieten!$B$BBegebt Euch nach Nordwesten, jenseits des Hochwipfeltals, und zur Scherwindklippe. Ihr werdet dort die Goblins und ihre Gefolgsleute bei der Arbeit vorfinden - zeigt ihnen, dass die Horde eine Ausbeutung des Steinkrallengebirges nicht billigt. Zeigt es ihnen in der Sprache, die sie am besten verstehen...$B$BGewalt.",objectives={"Tötet 15 Holzfäller der Venture Co. und kehrt dann zu Seereth Stonebreak an der Grenze des Steinkrallengebirges und dem Brachland zurück."}]])
R(1063,"Die Ältestengreisin",[[description="Um die Geister des Steinkrallengebirges wirklich zu beschwichtigen, müssen wir uns an die Taurenältesten wenden.$B$BIch kenne nicht viele ihrer Anführer, aber einen Namen kenne ich: Magatha. Ich habe gehört, dass sie sehr alt sein soll und sehr viel weiß. Wenn jemand die Tauren um geistige Hilfe bitten kann, dann sie.$B$BMagatha lebt in der Tauren-Hauptstadt Thunder Bluff auf der Anhöhe der Ältesten - dem Steilhang im Nordosten der Stadt. Sprecht mit Magatha und berichtet ihr von der Not im Steinkrallengebirge.",objectives={"Sprecht in Thunder Bluff mit Magatha."}]])
R(1064,"Die Hilfe der Verlassenen",[[description="Die Tauren sind mit dem Land verbunden, und es schmerzt mich, von der Not im Steinkrallengebirge zu hören. Ich fürchte jedoch, dass wir zunächst die Krankheit ausmerzen müssen, bevor wir das Land heilen können.$B$BIst es nicht eine glückliche Fügung, dass wir mit den Verlassenen verbündet sind? Sie wissen viel über Krankheiten. Ich glaube, sie werden uns helfen können, was das gegenseitige Vertrauen zwischen unseren Völkern stärken wird.$B$BSprecht mit Apothekerin Zamah. Sie ist eine Gelehrte und Botschafterin der Verlassenen. Ihr findet sie bei den Teichen der Visionen unterhalb der Anhöhe der Geister.",objectives={"Sprecht bei den Teichen der Visionen mit der Apothekerin Zamah."}]])
R(1065,"Reise nach Tarrens Mühle",[[description="Um die Venture Company aus dem Steinkrallengebirge zu vertreiben, müssen wir extreme Maßnahmen ergreifen. Extrem, aber ohne Blutvergießen.$B$BEiner meiner Kollegen hat vielleicht genau das Werkzeug, das wir benötigen. Er heißt Lydon und wohnt in Tarrens Mühle im Vorgebirge von Hillsbrad, das im weit entfernten Lordaeron liegt.$B$BUm nach Hillsbrad zu gelangen, reist mit dem Zeppelin in unsere Hauptstadt, nach Undercity. Geht von dort aus nach Norden nach Tirisfal, dann südwestlich nach Silberwald und südlich nach Hillsbrad.$B$BSucht Lydon auf und gebt ihm diese Notiz. Sie wird ihm alles erklären.",objectives={"Bringt Apotheker Lydon in Tarrens Mühle Zamahs Notiz."}]])
R(1066,"Das Blut Unschuldiger",[[description="Ich werde ein Toxin herstellen, mit dem wir der Venture Company die Gewalt entziehen und sie schwach und sanftmütig werden lassen. Das sollte das Problem der Horde im Steinkrallengebirge lösen, meint Ihr nicht?$B$BUm das Toxin herzustellen, benötige ich jedoch das Blut Unschuldiger, eine Zutat, an die man nur schwer herankommt.$B$BGlücklicherweise beschäftigt das Syndikat, das ist eine Gruppe menschlicher Briganten in dieser Region, Schattenmagier ... und diese Magier beschaffen sich das Blut Unschuldiger für ihre eigenen unappetitlichen Machenschaften.$B$BIhr finded die Schattenmagier des Syndikats in der Burg Durnholde im Südosten.",objectives={"Bringt Apotheker Lydon in Tarrens Mühle 5 Phiolen mit dem Blut Unschuldiger."}]])
R(1067,"Rückkehr nach Thunder Bluff",[[description="Hier habt Ihr das Toxin. Wenn Ihr es gegen die Venture Company einsetzt, sollte es positive, vielleicht sogar ansteckende Ergebnisse erzielen. Ich muss sagen, es ist ziemlich aufregend zu sehen, dass mein Werk tatsächlich eingesetzt wird!$B$BBringt es aber erst der Apothekerin Zamah, bevor Ihr es einsetzt. Sie muss eine Anwendungsmethode für das Toxin entwickeln, um einen größtmöglichen Effekt zu erzielen.",objectives={"Bringt Apothekerin Zamah in Thunder Bluff Lydons Toxin."}]])
R(1068,"Schreddermaschinen",[[description="Es gibt eine Verbindung zwischen der spirituellen Magie der Schamanen und der natürlichen Magie der Druiden. Deshalb können die Schamanen auch das Flehen der Geister des Steinkrallengebirges hören. Vieles, das sie flüstern, verstehe ich nicht, aber eine Nachricht, eine Vision, ist eindeutig ...$B$BIch hatte die Vision zweier menschenähnlicher Maschinen, die auf der Scherwindklippe nordwestlich des Hochwipfeltals mit ungeheuerlicher Geschwindigkeit Bäume fällten. Diese Metallbestien müssen aufgehalten werden!$B$BIn meiner Vision trugen diese Maschinen seltsame Symbole:$B$BXT:4 und XT:9.",objectives={"Vernichtet die Schredder XT:4 und XT:9 und kehrt dann zu Seereth Stonebreak an der Grenze zwischen dem Steinkrallengebirge und dem Brachland zurück."}]])
R(1069,"Eier der Kluftmoosspinnen",[[description="Omeletts aus Spinneneiern sind der letzte Schrei in Booty Bay! Das Problem ist nur... dass es in Booty Bay keine Eier gibt.$B$BDas riecht nach einer Geschäftsidee!$B$BAn der Scherwindklippe und im Sishircanyon nordwestlich im Steinkrallengebirge, lebt die Kluftmoosspinne. Bringt mir ihre Eier, dann werde ich Euch reichlich entlohnen!$B$BAn der Scherwindklippe sind die Eihaufen unter den noch verbliebenen Bäumen zu finden.$B$BIm Sishircanyon... tja, wenn Ihr einen schwachen Magen habt, solltet Ihr vielleicht nur die Eier an der Scherwindklippe sammeln...",objectives={"Bringt Mebok Mizzyrix in Ratchet 15 Kluftmooseier."}]])
R(1070,"Wache halten im Steinkrallengebirge",[[description="Hallo, $N.$B$BSo wie Ihr ausseht, scheint Ihr voller Reiselust zu sein. Wart Ihr schon mal im Steinkrallengebirge? Es ist ein Land, das von der Venture Company und anderen Feinden der Nachtelfen heimgesucht wird.$B$BErst neulich schickte Schildwache Wolfrunner meine Freundin Kaela Shadowspear dorthin, um zu untersuchen, was mit dem Land geschehen ist, aber ich habe seitdem nichts mehr von ihr gehört. Was mir noch mehr Sorgen macht ist, dass die Allianz sie zusammen mit einem Gnomen-Magier losgeschickt hat ... das deutet definitiv auf Probleme hin.$B$BWürdet Ihr sie suchen und mir dann Bericht erstatten?",objectives={"Sucht Kaela Shadowspear, die auf der Scherwindklippe im Steinkrallengebirge den Taleingang beobachtet."}]])
R(1071,"Der Aufschub des Gnoms",[[description="Wisst Ihr, $N, ich bin Mitglied der Erleuchteten Vereinigung der Arkanologie, Alchimie und Ingenieurwissenschaften, und es ist mein Ziel... nein, meine PFLICHT!, den Nachtelfen zu zeigen, dass eine Mischung aus Magie, Mixturen und Mechanismen dazu beitragen kann, ihren Wald zu retten.$B$BEs ist jedoch ein Kampf gegen Windmühlen, und die Goblins vermehren sich wie die Kaninchen, wie es scheint. Ich hatte sogar nicht mal Zeit, um meine neuesten Erfindungen zu bauen!$B$BIch brauche etwas Zeit, um zu planen und zu organisieren. Dazu brauche ich jedoch Eure Hilfe bei der Eindämmung der Goblins auf der Scherwindklippe im Osten...",objectives={"Tötet 10 Holzfäller der Venture Co. und 10 Roder der der Venture Co. und kehrt dann zu Gaxim Rustfizzle im Steinkrallengebirge zurück."}]])
R(1072,"Ein alter Kollege",[[description="Das Gerät, das mir vorschwebt, wird meine am weitesten entwickelte Erfindung sein. Aber wir brauchen einen speziellen Trank, wenn es funktionieren soll. Ich glaube, wir sollten uns gleich an das gute Zeug halten, immerhin könnte das unsere letzte Mission sein.$B$BUnd deshalb brauchen wir einen hochwirksamen Sprengstoff: Nitromirglyceronium.$B$BDie einzige Person, die NG-5 herstellen kann, ist ein alter Freund von mir: Lomac Gearstrip. Sucht in Tüftlerstadt nach ihm.$B$BWenn Ihr ihn überreden könnt, uns etwas NG-5 herzustellen, kann ich mich an die Platzierung meiner Geräte machen.",objectives={"Sprecht mit Lomac Gearstrip in Ironforge."}]])
R(1073,"Stümperhaftigkeit + Chemikalien = Riesenspaß!",[[description="Hahaha... Ihr braucht Nitromirglyceronium, um Goblins daran zu hindern, einen Wald zu zerstören?!$B$BEs ist mir egal, ob Ihr Gaxim kennt oder nicht... Ich würde Euch das Zeug allein schon deshalb geben, weil ich sehen will, wie Ihr oder sie in klitzekleine Fetzen explodieren.$B$BEs gibt allerdings ein Problem: Ich hab nichts mehr.$B$BAber ich sag Euch was: Bringt mir die richtigen Tränke, dann stelle ich sofort etwas für Euch her.$B$BDas Mindeste, was Ihr tun könnt, ist, mir ein paar Eurer Alchimisten-Fertigkeiten vorzuführen, bevor ich Euch eine Kostprobe meiner größten Erfindung gebe.",objectives={"Bringt Lomac Gearstrip in Ironforge 4 schwache Manatränke und 2 Elixire der Seelenstärke."}]])
R(1074,"Stümperhaftigkeit + Chemikalien = Riesenspaß!",[[description="Bitte sehr, Fremdling. Seid jedoch vorsichtig damit... das Zeug ist hochexplosiv.$B$BFalls Ihr wirklich ein Freund von Gaxim seid, grüßt ihn von mir. Falls nicht, dann viel Spaß beim Selbst-in-die-Luft-jagen.",objectives={"Bringt Gaxim Rustfizzle im Steinkrallengebirge das Nitromirglyceronium."}]])
R(1075,"Eine Rolle von Mauren",[[description="Gut, wenden wir uns jetzt dem Teil meines Planes mit der Fernzündung zu... oh, das hab ich ja noch gar nicht erklärt, stimmt's?$B$BAlso dann mal die Kurzversion: Mit etwas Magie kann ich dafür sorgen, dass der Sprengstoff hochgeht, ohne dass Ihr dabei sein müsst. Ich bastele ein Gerät zusammen, bei dem Ihr nur einen Knopf drücken müsst, damit das NG-5 explodiert, wenn Ihr bereit seid.$B$BIch brauche jedoch einen Zauber von einem Freund in Stormwind - er heißt Collin Mauren. Ihr findet ihn im dortigen Magierviertel. Er ist ein Mensch, daher solltet Ihr ihn kaum verfehlen können.",objectives={"Sucht Collin Mauren in Stormwind auf."}]])
R(1076,"Teufel in Westfall",[[description="Ah, ich glaube, ich hab's. Ein Nachrichtenzauber... Er dürfte den Effekt haben, nachdem er sucht.$B$BIch muss eine Rolle herstellen, auf die der Zauber geprägt ist. Dazu benötige ich die Überreste eines Staubteufels.$B$BWarum geht Ihr nicht nach Westfall und sucht eine dieser elenden Kreaturen, während ich den Rest der Komponenten sammle? Sie sind gefährlich, aber ich bin mir sicher, dass Ihr schon damit klarkommt, zumal Ihr sogar gewillt seid, an einem von Gaxims Experimenten teilzunehmen.$B$BIch werde hier sein, wenn Ihr zurückkommt.",objectives={"Bringt Collin Mauren in Stormwind die Überreste eines Staubteufels."}]])
R(1077,"Speziallieferung für Gaxim",[[description="Bitte sehr, $n. Das sollte funktionieren.$B$BBitte grüßt Gaxim von mir, wenn Ihr ihn das nächste Mal seht. Ich freue mich schon so darauf, von diesem Abenteuer zu hören, wenn Ihr es überstanden habt.$B$BLebt wohl.",objectives={"Bringt Gaxim Rustfizzle im Steinkrallengebirge die Rolle der Nachrichtenübermittlung."}]])
R(1078,"Suche für Mauren",[[description="Immer wieder fragen mich Reisende über das Steinkrallengebirge aus. Scheint ein beliebter Ort unter Abenteurern zu sein; spielt keine Rolle, ob man Flügeldrachen oder Elementare sucht, oder ob man Geschäfte mit der Venture Company machen will.$B$BIm verbrannten Tal tief im Steinkrallengebirge gab es mal eine Basiliskenart, deren Schuppen, wenn man sie zu Staub zermahlte, ein wunderbares Reagenz für einige der Zauber ergab, die ich ersonnen habe.$B$BWenn diese Basilisken noch leben, hätte ich liebend gern ein paar ihrer Schuppen.$B$BLasst Euch Zeit, ich hab keine Eile, aber ich kann Euch gut bezahlen.",objectives={"Bringt Collin Mauren in Stormwind 8 kristallisierte Schuppen."}]])
R(1079,"Geheimoperation Alpha",[[description="Das ist es, $n. Seht genau hin. Die Geräte sind fertig und einsatzbereit.$B$BNehmt diese Blätter - sie erklären mehr über die Zünder und den Sprengstoff und wo Ihr ihn platzieren solltet.$B$BDenkt daran, der Erfolg Eurer Mission hängt nicht davon ab, wie viel Schaden Ihr anrichtet. Der Erfolg von Plan Alpha hängt davon ab, dass Ihr die Ingenieurspläne der Venture Company aus dem Sägewerk südlich des Felskesselsees holt.",objectives={"Holt die Ingenieurspläne der Venture Company aus dem Sägewerk auf der Scherwindklippe."}]])
R(1080,"Geheimoperation Beta",[[description="Plan Beta funktioniert genau wie Plan Alpha, $n.$B$BWir stiften Verwirrung und stehlen dann ihre wertvollen Dokumente.$B$BWir müssen unbedingt diese Dokumente haben... vergesst das nicht.$B$BDie Blätter, die Ihr bereits habt, zeigen Euch, wo Ihr den Sprengstoff platzieren müsst. Kommt mir nur heil und mit diesen Dokumenten zurück...",objectives={"Holt die Dokumente der Venture Company aus der Scherwindmine am Ostende der Scherwindklippe."}]])
R(1081,"Tyrandes Empfang",[[description="$N, ich bin mir sicher, dass Tyrande Whisperwind Euch persönlich für Eure Teilnahme an dieser Mission danken wollen wird.$B$BEs mag auf den ersten Blick zwar nicht so aussehen, aber Ihr habt dazu beigetragen, etwas in Gang zu setzen, das unsere Position im Steinkrallengebirge erheblich stärken wird.$B$BFalls Ihr Euch als unseren Verbündeten im Kampf gegen diese Gräueltaten betrachtet, sucht Tyrande im Tempel des Mondes in Darnassus auf.",objectives={"Sucht Tyrande Whisperwind in Darnassus auf."}]])
R(1082,"Neuigkeiten für Schildwache Thenysil",[[description="$N, Ihr habt Großes geleistet, indem Ihr uns hier geholfen habt.$B$BDie Schildwachen von Ashenvale werden Euch reichlich belohnen, wenn Ihr ihnen mitteilt, dass Gaxim und ich noch am Leben sind. Sagt ihnen, dass wir beim Aufhalten der Venture Company und der Heilung des Landes gute Fortschritte machen.$B$BSucht Tara Thenysil in Astranaar auf. Sie wird sich freuen, dass Ihr mit guten Neuigkeiten kommt.",objectives={"Kehrt zu Schildwache Thenysil in Ashenvale zurück."}]])
R(1083,"Wütende Geister",[[description="Ich weiß nicht genau, was die Venture Company dem Tal angetan hat, aber es ist offensichtlich, dass es von den dortigen Kreaturen überwältigt wurde.$B$BSie steckten den Wald in Brand und benutzten ihre zerstörerischen Erfindungen, um so viel wie möglich des Tals zu zerstören.$B$BIn ihrer Dummheit haben sie jedoch auch noch etwas anderes entfesselt: brennende Geister, Elementare der Flammen, der Steine und der Wut.$B$BDas Land wird Elune nicht mehr lächeln sehen, solange diese Kreaturen frei herumstreifen.$B$BBringt mir ihre glimmenden Überreste, um mir zu zeigen, dass Ihr sie dezimiert habt.",objectives={"Bringt Kaela Shadowspear im Steinkrallengebirge 8 glimmende Überreste der Feuerelementare des verbrannten Tals."}]])
R(1084,"Verletzte Urtume",[[description="Es scheint mir offensichtlich, dass die Beschützer des Tales - die Treants - irgendetwas damit zu tun hatten, dass die Venture Company zurückgeschlagen wurde. Leider wurden selbst diese einst so großen Wächter jetzt verderbt.$B$BGaxim glaubt, dass ihre Verderbnis irgendwie mit den Waffen zusammenhängt, die die Goblins während ihres Rückzuges benutzten.$B$BIch bat ihn, eine Probe von einem verwundeten Treant zu nehmen und sie zu untersuchen, um herauszufinden, ob das wirklich stimmt.$B$BBringt mir ein paar Späne, damit der Gnom mehr darüber herausfinden kann ...",objectives={"Bringt Kaela Shadowspear im Steinkrallengebirge ein Stück eines zerfressenen Spans."}]])
R(1085,"Wache halten im Steinkrallengebirge",[[description="Die Lage hier im Steinkrallengebirge ist offensichtlich düster, wenn Nachtelfen und Gnome zusammenarbeiten.$B$BDie Venture Company hat das Land verwüstet und ich habe einen Großteil meines Leben damit zugebracht, der Zerstörung ein Ende zu setzen.$B$BMan sollte Gaxim nicht vorschnell beurteilen; er versteht die Notwendigkeit, warum wir zusammenarbeiten müssen.$B$BWenn Ihr uns helfen wollt, sprecht zunächst mit Gaxim.$B$BEs tut mir leid, dass ich Euch jetzt noch nicht mit guten Neuigkeiten zu Tara zurückschicken kann. Aber vielleicht schon bald.",objectives={"Sprecht mit Gaxim."}]])
R(1086,"Der Flugapparathafen",[[description="Das Toxin ist bereit. Jetzt muss es nur noch ausgeliefert werden. Ihr, $n, müsst es ausliefern.$B$BDie Venture Company muss irgendwelche Mittel und Wege haben, Nachrichten und leichte Fracht zwischen ihrem Hauptquartier und dem Betrieb im Steinkrallengebirge hin- und herzuschicken. Es könnte ein kleiner Flugplatz sein - nicht groß genug für einen Zeppelin, aber vielleicht für einen Flugapparat. Ihr müsst die Gebiete, die von der Venture Company kontrolliert werden, durchsuchen und diesen Flugplatz finden, falls er existiert. Solltet Ihr ihn finden, platziert das Toxin dort.$B$BPlatziert es und lauft, was Ihr könnt.",objectives={"Bringt den Toxinvernebler zum Flugplatz der Venture Company und kehrt dann zu Apothekerin Zamah zurück."}]])
R(1087,"Cenarius' Vermächtnis",[[description="Ihr könnt Euch nicht vorstellen, wie groß mein Hass auf dieses elende Land ist. Solche Leute wie Cenarius und die Kaldoreidruiden auf dem Gipfel benutzen ihre lächerlichen Mächte, um den Magiefluss zu stoppen, sogar noch so weit von ihrem lächerlichen Besitz entfernt ... ihren geliebten Wäldern.$b$bIch wünschte, ich könnte nach Jaedenar zurückkehren und im Fluss der Magie baden, aber mein Meister erlaubt mir erst dorthin zurückzukehren, wenn meine Arbeit getan ist.$b$bZweifellos liebt Ihr die Nachtelfen und ihre Verbündeten genauso wenig wie ich. Helft mir, dann haben wir vielleicht beide etwas davon.",objectives={"Tötet für Brealyn Firehand in Sonnenfels 4 Söhne des Cenarius, 4 Töchter des Cenarius und 4 cenarische Botaniker."}]])
R(1088,"Ordanus",[[description="Sie dachten, dass man den Fluss der Magie zum Erliegen bringen könnte. Sie haben sich geirrt. Sie dachten, dass sie Ordanus verstecken könnten, aber ich will seinen Kopf!$b$bDie Magie gewährt mir Durchblick. Ja... da ist er. Ein Scheideweg... auf dem Wipfel eines großen Baumes in Ashenvale. Ein Name... Raynewood. Einer der ältesten Söhne des Waldgottes. Sie haben ihn aus dem Wipfel geschleust, bevor ich ihn finden konnte, aber ihm läuft langsam die Zeit davon.$b$bBringt ihn mir, dann teile ich ein großes Geschenk mit Euch.",objectives={"Bringt Braelyn Firehand in der Nähe von Sonnenfels Ordanus' Kopf."}]])
R(1089,"Der Höhlenbau",[[description="Die Druiden errichteten den Krallenbau auf dem Steinkrallengipfel, in dem sie viele mächtige Gegenstände aufbewahren.$b$bSie haben sich ein komplexes Schema ausgedacht, damit sie nicht in die falschen Hände gelangen.$b$bGlücklicherweise konnte ich einem von ihnen... ein paar Details entlocken.$b$bVersteckt in einer kleinen Laterne am Eingang des Baus werdet Ihr den Torhüterschlüssel finden. Damit könnt Ihr die Behälter öffnen, die über den ganzen Bau verteilt sind. Mit den Gegenständen aus diesen Behältern wiederum könnt Ihr ihren Hort öffnen, der sich in einem der zentralen Bereiche befindet.",objectives={"Begebt Euch zum Höhlenbau auf den Steinkrallengipfel. Benutzt den Torhüterschlüssel, um Euch die versteckten Gegenstände der Druiden zu besorgen. Benutzt diese Gegenstände, um den Hort des Krallenbaus zu öffnen."}]])
R(1090,"Gerenzos Befehle",[[description="Wisst Ihr, ich war hier einst die zweitwichtigste Person. Das hat sich alles geändert, als Gerenzo hier übernahm. Hat meinen Boss Ziz Fizziks gefeuert und mich zum Arbeiten nach unten in die Minen geschickt. Ziz sagte mir aber, dass ich hier bleiben und Informationen sammeln solle. Sein neuer Boss wird uns gut bezahlen, wenn wir rausfinden, was Gerenzo plant.$b$bEgal, was ich weiß ist, dass Gerenzo befohlen hat, dass Riesenmengen von diesem gold-grünen Erz abgebaut werden sollen. Ich hol Euch eine Probe, damit Ihr sie Ziz bringen könnt, aber Ihr müsst Euch vor Patrouillen hüten, während ich es hole.",objectives={"Nehmt das rätselhafte Erz, nachdem Piznik es fertig abgebaut hat."}]])
R(1091,"Kaelas Update",[[description="$n, bringt Kaela diese Briefe. Ich bin mir sicher, dass sie das interessiert. Oder zumindest die Schildwachen.$B$BErzählt Ihr unbedingt, wie erfolgreich wir waren und dass wir es ohne ein bisschen Magie nie geschafft hätten.",objectives={"Bringt Kaela Shadowspear die Dokumente der Venture Company."}]])
R(1092,"Gerenzos Befehle",[[description="Ich glaube, ich sollte auch langsam darüber nachdenken, hier zu verschwinden. Es wird nicht lange dauern, bis die da oben erfahren, was hier gelaufen ist, und ich bin sicher, dass die keinen großen Wert darauf legen, mich wiederzusehen.$b$bIch schleich mich raus und treff mich mit Ziz. Hoffentlich kann er mir einen neuen Job besorgen!$b$bIch werde versuchen, hier ein bisschen Ordnung zu schaffen, aber Ihr solltet die Erzprobe sofort zu Ziz bringen. Er sagte mir, dass er irgendwo an der Westseite der Scherwindklippe sein Lager aufgeschlagen hat. Viel Glück.",objectives={"Bringt Ziz Fizziks im Steinkrallengebirge das unbekannte Erz."}]])
R(1093,"Superschnitter 6000",[[description="Schrecklich, was die Venture Company hier getan hat, was? Was haben die sich dabei gedacht? Eine Goblin-Firma, die einen Gnom anheuert!$b$bEin Glück für mich, dass Sputtervalve ein Genie erkennt, wenn es vor ihm steht. Hat mich eingestellt, gleich nachdem ich gefeuert wurde!$b$bSagte mir, sie wollten eine riesige Holzfällmaschine bauen, und Sput möchte, dass ich für ihn die Pläne dazu stehle. Leider wird Gerenzo - dieser verdammte Gnom - mich umlegen, sobald er mich sieht ... würdet Ihr vielleicht die Pläne für mich stehlen? Ihr solltet sie bei einem ihrer Maschinenführer finden.",objectives={"Besorgt für Ziz Fizziks im Steinkrallengebirge die Blaupausen für den Superschnitter 6000."}]])
R(1094,"Weitere Instruktionen",[[description="In diesem Umschlag befinden sich alle Informationen, die ich mir schnappen konnte, bevor sie mich vor die Tür setzten... Interne Dokumente der Venture Company, ein paar Handbücher, technisches Zeugs... Oh, und natürlich die Blaupausen für den Superschnitter 6000.$b$bSputtervalve hat sich bei Ratchet im Brachland niedergelassen. Sollte nicht schwer sein, ihn zu finden. Er ist ein kleiner, grüner Kerl.",objectives={"Bringt Sputtervalve im Brachland den versiegelten Umschlag."}]])
R(1095,"Weitere Instruktionen",[[description="Die Tatsache, dass die Venture Company diesen Gnom angestellt hat, hat in Undermine für einiges Aufsehen gesorgt. Die Handelsbarone finden es nicht gut, dass Razdunk mit Gerenzo gemeinsame Sache macht.$b$bRiddlevox hat mich gebeten, mich um das Problem zu kümmern und ich bin mir sicher, dass einer oder zwei dieser Handelsbarone ihn dazu angewiesen haben. Natürlich hat mir der Direktor das nicht erzählt. Sagen wir einfach, ich hätte so eine Ahnung.$b$bWie dem auch sei, Gerenzo muss entfernt werden und es wäre eine passende Prüfung, das Fizzik erledigen zu lassen.",objectives={"Bringt Ziz Fizziks im Steinkrallengebirge die neuen Befehle."}]])
R(1096,"Gerenzo Wrenchwhistle",[[description="Ich habe Gerenzo einmal getroffen, und lasst mich Euch eines sagen, er ist nicht gerade eine Schönheit. Sein Fleisch sieht aus, als würde es faulen. Dazu hat er noch überall an seinem Körper Metallteile und Zeugs angeflanscht und sogar einige seiner Körperteile durch mechanische ersetzt.$b$bNordöstlich von hier, weit oberhalb des Felskesselsees in der Nähe des Wasserrades beaufsichtigt Gerenzo die gesamte Stätte. Ich könnte mich unmöglich bis da hinauf durchkämpfen und schon gar nicht mich mit Gerenzo anlegen ... Aber Ihr seht aus, als könntet Ihr es schaffen.$b$bWenn Ihr ihn für mich tötet, soll es Euer Schaden nicht sein!",objectives={"Bringt Ziz Fizziks im Steinkrallengebirge Gerenzo Wrenchwhistles mechanischen Arm."}]])
R(1097,"Elmores Aufgabe",[[description="In Stormwind gibt es einen Zwergen-Waffenschmied namens Grimand Elmore, der mal angedeutet hat, dass er Hilfe bei einer Lieferung bräuchte. Ich glaube, er möchte ein Paket in seine Heimat im Norden schicken.$B$BIhr habt da ein paar schöne kräftige Beine! Falls Ihr also an ein wenig Beinarbeit interessiert seid, sprecht mit Grimand. Wir könnten Euch hier unten brauchen, aber wir müssen auch unsere Bande mit den Zwergen stärken.$B$BIhr findet Grimand Elmore im Waffenladen im Zwergendistrikt von Stormwind, im nordöstlichen Teil der Stadt.",objectives={"Sprecht mit Grimand Elmore."}]])
R(1098,"Todespirscher in Shadowfang",[[description="Als Vorbereitung auf einen Überfall auf Shadowfang wurden zwei Todespirscher in die Burg geschickt, um Informationen zu sammeln. Das war vor mehreren Tagen und sie sind noch nicht wieder zurück, aber wir brauchen ihren Bericht, wenn wir auf einen erfolgreichen Angriff hoffen wollen!$B$BDas ist Eure Aufgabe, $N. Geht zu Burg Shadowfang im Süden und sucht die Todespirscher Adamant und Vincent. Findet sie und helft ihnen, falls es erforderlich ist.$B$BDiese Mission ist nicht nur gefährlich, sondern auch lebenswichtig, $N. Versagt bitte nicht.",objectives={"Sucht die Todespirscher Adamant und Vincent."}]])
R(1099,"Goblins Win!")
R(1100,"Lonebrows Tagebuch",[[description="Ihr öffnet langsam das verwitterte Tagebuch des Henrig Lonebrow...",objectives={"Lest Henrig Lonebrows Tagebuch."}]])
R(1101,"Die Greisin des Krals",[[description="Armer Heralath! Und dieser Zwerg... Lonebrow. Was war er doch für eine mutige Seele.$b$bSo viel Heldenmut darf nicht umsonst gewesen sein. Diese Greisin... Charlga Razorflank... muss aufgehalten werden.$b$bSicher, es wird gefährlich werden, den Kral zu bespitzeln. Wir haben keine Zeit, um Darnassus zu informieren. $n, stellt eine Gruppe zusammen, um die Greisin zu erschlagen.$b$bBringt mir Razorflanks Medaillon zum Beweis ihres Ablebens.",objectives={"Bringt Falfindel Waywarder in Thalanaar Razorflanks Medaillon."}]])
R(1102,"Ein schreckliches Schicksal",[[description="Es war edel von unserem Anführer Cairne, unser Volk hier in Thunder Bluff zu vereinen.$b$bIch kann jenen jedoch nicht vergeben, die uns so leicht aus dem Land unserer Vorfahren vertrieben haben. Jahrhundertelang lebte mein Volk im südlichen Brachland. Das Land war uns heilig. Aber wir wurden von zahllosen Feinden vertrieben.$b$bEin schreckliches Schicksal erwartet die Greisin Charlga Razorflank, die im Kral von Razorfen eine abscheuliche Armee zusammenzieht.$b$bBringt mir Razorflanks Herz, damit ich in Frieden sterben kann, $n.",objectives={"Bringt Auld Stonespire in Thunder Bluff Razorflanks Herz."}]])
R(1103,"Ruf des Wassers",[[description="Seid gegrüßt, $g Bruda:Schwesta;! Seid auch Ihr gekommen, um das Wasser hier zu läutern und Islen Euer Wissen zu beweisen?$B$BIch habe den verderbten Wassergeist gerade selbst bezwungen und bin grad dabei, die Armschienen un' verbleibenden Wassertropfen in die Kohlenpfanne zu geben.$B$BWas'n das? Ahhh. Tiev versteht nur zu gut, wenn wat falsch läuft. Tja, Tiev kann Euch echt helfen, wenn Ihr den Wassergeist wieda seh'n wollt.$B$BBringt mir 'in Wassersapta von Islen als Beweis, dass Ihr bereit seid, un' ich bin bereit, meinen Teil beizutrag'n.",objectives={"Bringt Tiev Mordune im Silberwald ein Wassersapta, wenn Ihr nicht mit der schwachen Wassermanifestation gesprochen habt."}]])
R(1104,"Salziges Gift",[[description="Ich habe so viele Pläne für unseren Raketenwagen! So viele! Und ich muss sie alle ausprobieren!!!$B$BIch arbeite gerade an einem neuen Treibstoff; an einem, der wirklich, wirklich, wirklich heiß ist! Die Mixtur stimmt zwar noch nicht ganz, aber ich glaube, ich weiß, was noch fehlt...$B$BDie Skorpide, die die Schimmernde Ebene durchwandern, haben ein Gift mit Unmengen Salz darin. Es ist einzigartig! Und es ist genau das, was ich brauche!$B$BBringt mir das Gift und vertraut mir: unser Wagen wird fliegen!",objectives={"Bringt Fizzle Brassbolts in der schimmernden Ebene 6 Einheiten salziges Skorpidgift."}]])
R(1105,"Gehärtete Schalen",[[description="Mein Bruder arbeitet an einem neuen Treibstoff für seinen Raketenwagen. Er ist brillant, ehrlich. So brillant, dass... Ich glaube, der neue Treibstoff, den er da entwickelt, ist stark genug, um sich durch das Chassis des Wagens zu fressen!$B$BIch würde gern die Treibstofftanks verstärken, bevor das passiert.$B$BDie Schildkröten draußen auf der Ebene haben sehr starke Panzer. Ich möchte daraus neue Tanks für unseren Raketenwagen bauen. Tanks, die den neuen Treibstoff meines Bruders aushalten.$B$BIhr seht mir verantwortungsbewusst genug aus. Holt Ihr mir solche Panzer?",objectives={"Bringt Wizzle Brassbolts in der schimmernden Ebene 9 gehärtete Schildkrötenpanzer."}]])
R(1106,"Martek der Verbannte",[[description="Ich entwickle einen neuen Motor, mit dem der Wagen so schnell wie der Wind wird! Schnell genug, um zu fliegen, ich weiß es! Ich muss nur ein paar Kolben herstellen, die sehr, sehr große Belastungen aushalten. All meine bisherigen Versuche sind fehlgeschlagen, weil ich die Kolben einfach nicht robust genug herstellen kann!$B$BAber es gibt jemanden, der wissen könnte, wie es geht.$B$BSein Name ist Martek der Verbannte. Er ist ein großartiger Schmied und weiß mehr über Metall als alle anderen. Bringt ihm diesen Brief, ich weiß, dass er helfen kann!$B$BAber er lebt weit, weit weg - in Azeroth, im Ödland, in einem Lager, zusammen mit einem Goblin!$B$BSucht ihn!",objectives={"Bringt Martek dem Verbannten im Ödland Fizzles Brief."}]])
R(1107,"Verkrustete Schwanzflossen",[[description="Unser Raketenwagen ist das schnellste, was es auf der Ebene gibt! So schnell, dass... ich fürchte, die Reibung reißt ihn auseinander!$B$BUm das zu verhindern, muss ich einen Stoff entwickeln, der die beweglichen Teile des Wagens überzieht. Er muss hart sein, aber nicht spröde, und er muss resistent gegen Salzkorrosion sein, sonst wird der Wagen, während er sich in der Schimmernden Ebene befindet, zerfressen.$B$BHabt Ihr schon mal vom Finsteren Riff gehört, $n? Es liegt vor der Küste des Schlingendorntals. Dort leben Salzschuppenmurlocs, deren Schwanzflossen unabdingbare Zutaten zu meinem Stoff sind.",objectives={"Bringt Fizzle Brassbolts in der schimmernden Ebene 10 verkrustete Schwanzflossen."}]])
R(1108,"Indurium",[[description="Ich bin nicht hier draußen, weil ich mich vor Leuten verstecken will. Das Ödland ist reich an Metall, $N, wenn man den Mut hat, es sich zu holen.$B$BDas Metall heißt Indurium, und wie das Schicksal so spielt, soll es angeblich hohen Widerstand gegen Hitze und Belastung bieten. Das könnte genau das Richtige für Fizzles Wagen sein.$B$BAber wir sollten sichergehen. Bringt mir eine Indurium-Probe, dann kann ich seine Eigenschaften testen.$B$BEchtes Induriumerz liegt tief drinnen in Uldaman, aber die Steingrufttroggs des Ödlandes tragen manchmal Späne davon mit sich herum. Bringt mir diese Späne.",objectives={"Bringt Martek dem Verbannten im Ödland 10 Induriumspäne."}]])
R(1109,"Go, Go, Guano!",[[description="Wie Ihr seht, $N, befassen wir uns mit einigen sehr... interessanten Experimenten in der Königlichen Apothekervereinigung.$b$bAls Meister hier ist es meine Aufgabe, die anspruchsvollsten unserer alchimistischen Versuche zu überwachen. So viel Arbeit und nur so wenig Zeit!$b$bIhr seht weit gereist aus, $C. Vielleicht könnt Ihr mir helfen.$b$bIch brauche eine rare Substanz. Es ist dieses widerliche Zeug, das von einer raren Fledermausart stammt, die man nur in einem Dreckloch namens Kral von Razorfen findet. Bringt mir den Guano der Kral-Fledermäuse, damit wir mit unserer Arbeit beginnen können...",objectives={"Bringt dem Apothekermeister Faranell in Undercity 1 Häufchen Kral-Guano."}]])
R(1110,"Raketenwagenteile",[[description="Hi-hi, bei den vielen Rennen, die hier stattfinden, ist es nicht verwunderlich, wenn dabei ein paar Unglücksfälle passieren. Wenn man sich in der Schimmernden Ebene umschaut, sieht man ständig Spuren vergangener Unfälle - überall liegen Teile von Raketenwagen herum.$B$BUnd diese Teile bedeuten für die Gnome und Goblins bares Geld. Sie suchen ständig nach weiteren neumodischen Apparaten, um sie an ihre Autos anzubauen.$B$BAlso zieht los und bringt mir die Teile. Bringt mir einen Haufen und ich werde Euch gut bezahlen.",objectives={"Bringt 30 Raketenwagenteile zu Kravel Koalbeard in der schimmernden Ebene."}]])
R(1111,"Werftmeister Dizzywig",[[description="Mein Job ist es, den Leuten zu beschaffen, was sie möchten, und diese Gnome da drüben möchten Teile bestellen. Ihre Teile wurden vor einer Woche nach Ratchet geschickt, aber es war mir nicht möglich, dorthin zu reisen.$B$BAlso, seid Ihr bereit, mir die Kleinarbeit abzunehmen? Geht nach Ratchet und gebt diese Teile-Bestellung an Werftmeister Dizzywig - er wird wahrscheinlich bei den Docks sein.$B$BWenn Ihr das macht, habe ich weitere Aufträge für Euch.$B$BAufträge, bei denen eine Menge Profit rausspringen kann ...",objectives={"Bringt Kravels Teile-Bestellung zu Werftmeister Dizzywig in Ratchet."}]])
R(1112,"Teile für Kravel",[[description="Hier ist Kravels Paket, $n. Und wenn Ihr es zustellt, sagt ihm bitte... wenn er weitere spezielle Lieferungen möchte, dann muss er bezahlen!",objectives={"Bringt Kravels Teile zu Kravel Koalbeard in der schimmernden Ebene."}]])
R(1113,"Herzen des Eifers",[[description="Warum ich eine rare Art von Guano benötige, fragt Ihr Euch? Also bei diesem Experiment möchte ich wissen, wie zwei diametral entgegengesetzte chemische Substanzen aufeinander wirken, besonders wenn beide mit einem höchst toxischen Agens kombiniert werden, um die ... garstigsten Resultate zu erzielen.$b$bIn der Nordostspitze von Tirisfal liegt das Scharlachrote Kloster. Dort versammeln sich die wahnsinnigen Jünger des Scharlachroten Kreuzzuges. Tötet sie und bringt mir ihre übereifrigen Herzen.$b$bUnser Gebräu wird äußerst tückisch sein!",objectives={"Apothekermeister Faranell in Undercity möchte 20 Herzen des Eifers."}]])
R(1114,"Lieferung für die Gnome",[[description="Jetzt, wo ich habe, was ich brauche, gebt diese Teile Fizzle Brassbolts. Er wartet schon lange darauf - ich bin sicher, das kleine Teil, das ich behalten habe, wird er nicht vermissen...$B$BUnd ich würde ihn auch nicht darauf hinweisen. Es war klein und wertlos.$B$BGlaubt mir.",objectives={"Bringt die empfindlichen Autoteile zu Fizzle Brassbolts."}]])
R(1115,"Der Gerüchteverbreiter",[[description="Jetzt, da wir diesen Dienst für die Gnome geleistet haben, wird es Zeit, den Goblins einen Gefallen zu tun! $B$BIch habe gehört, dass der Goblin-Rennfahrer Nazz Steamboil diesen Namen nicht immer getragen hat. Ich frage mich, weshalb er ihn änderte. Ob es wohl ein Geheimnis ist und... wie viel ihm dieses Geheimnis wert ist.$B$BWenn jemand die Wahrheit kennt, dann Krazek aus Booty Bay an der Südspitze des Schlingendorntals. Sprecht mit Krazek und fragt ihn nach unserem Goblin-Rennfahrer.$B$BWenn Ihr nützliche Informationen aus ihm herausbekommt, springt vielleicht Profit für uns raus.",objectives={"Sprecht mit Krazek in Booty Bay."}]])
R(1116,"Traumstaub im Sumpf",[[description="Es ist ein großer Gefallen, diese Informationen über Nazz zu beschaffen, $n. Ja, ein großer Gefallen. Aber Ihr habt den weiten Weg von der Schimmernden Ebene auf Euch genommen... seid Ihr bereit, noch etwas weiter zu reisen?$B$BIhr könntet doch etwas für mich besorgen, während ich Kontakt mit meinen Informanten aufnehme, hm?$B$BHmm... was könnte es denn sein? Wie wäre es mit Traumstaub von den Großdrachenwelpen und Wyrmkin aus den Sümpfen des Elends? Ja, ich hätte gern etwas Traumstaub für meinen Schnupftabakbeutel!$B$BBringt ihn mir, $n, und ich gebe Euch die gewünschten Informationen.",objectives={"Bringt 10 Körnchen Traumstaub zu Krazek in Booty Bay."}]])
R(1117,"Gerüchte für Kravel",[[description="Ich musste einige Gefälligkeiten erweisen, eine rare Flasche Elfenwein herschenken und mir selbst einiges zusammenreimen! Aber ich habe die Informationen, die Ihr sucht.$B$BHier, ich habe einen Brief mit einigen sehr interessanten Infos über Euren Freund Nazz Steamboil verfasst. Macht damit, was Ihr wollt - für mich wäre es zu gefährlich, ihn zu benutzen.$B$BSagt nur keinem, woher Ihr das habt!",objectives={"Bringt die Goblin-Gerüchte zu Kravel Koalbeard in der schimmernden Ebene."}]])
R(1118,"Zurück nach Booty Bay",[[description="$N, Ihr seid ein $C, dem ich trauen kann. Ihr werdet den Auftrag erledigen und die Klappe halten.$B$BIch habe einen neuen Plan geschmiedet. Er ist riskant, aber wenn er funktioniert, könnten wir beide gut absahnen! Und ich glaube, Ihr seid der Richtige, um das durchzuziehen.$B$BAls Erstes müsst Ihr nach Booty Bay zurückkehren. Nun, ich bitte um Verzeihung, $N. Ich weiß, meine letzte Aufgabe führte Euch dorthin. Aber sprecht diesmal mit Crank Fizzlebub.$B$BGebt ihm diesen Brief. Und wenn er um Unterstützung bittet, dann tut, was Ihr könnt, um ihm zu helfen. Es wird sich lohnen.",objectives={"Bringt Kravels Plan zu Crank Fizzlebub in Booty Bay."}]])
R(1119,"Zanzils Mixtur und Fools Starkbier",[[description="Ich habe herausgefunden, wie man aus Zanzils Mixtur mit Starkbier ein mächtiges Getränk macht. Fools Starkbier. Und ich glaube, genau das braucht Kravel. Probiert es einfach mal aus und lasst mich wissen, wie es wirkt.$B$BUnd behaltet das Zeug nicht zu lange unbenutzt, $n. Zanzils Mixtur hat eine seltsame Wirkung auf die Hefe des Starkbiers und regt sie heftig an. Sie bleibt nicht ewig frisch.",objectives={"Bringt Fools Starkbier zu Kravel in der schimmernden Ebene zurück."}]])
R(1120,"Die Gnome betrunken machen",[[description="Wir müssen Fools Starkbier an einem aus der Boxencrew ausprobieren. Wenn Ihr es an den Gnomen erproben wollt, hier - nehmt das Starkbier und gebt es dem Gnomen-Boxenboss.$B$BUnd wartet nicht zu lange. Das Starkbier wird mit der Zeit schlecht.",objectives={"Bringt Fools Starkbier zum Gnomen-Boxenboss."}]])
R(1121,"Die Goblins betrunken machen",[[description="Wir müssen Fools Starkbier an einem aus der Boxencrew ausprobieren. Wenn Ihr es an den Goblins erproben wollt, hier - nehmt das Starkbier und gebt es dem Goblin-Boxenboss.$B$BUnd wartet nicht zu lange. Das Starkbier wird mit der Zeit schlecht.",objectives={"Bringt Fools Starkbier zum Goblin-Boxenboss."}]])
R(1122,"Meldet Euch bei Fizzlebub",[[description="Fools Starkbier hat astrein gewirkt! Ich habe beim nächsten Rennen gesetzt... hoffen wir, das Team, das Ihr betrunken gemacht habt, hat sein Auto nummeriert!$B$BBleibt nur noch eine Aufgabe für Euch - bringt diese Notiz zu Crank Fizzlebub in Booty Bay. Er wird von dem erfolgreichen Test wissen wollen.$B$BHoffentlich bekommen wir mehr von Fools Starkbier für künftige Rennen!",objectives={"Bringt den Bericht über Fools Starkbier zu Crank Fizzlebub in Booty Bay."}]])
R(1123,"Rabine Saturna",[[description="Für diese Aufgabe sucht Majordomus Rabine Saturna für Bewahrer Remulos in Moonglade Unterstützung bei der Erforschung des riesigen Ödlandes weit im Westen von Tanaris und Un'Goro. Er lebt in Nighthaven, dem Hauptort von Moonglade.$B$BVorher möchte ich Euch jedoch noch von der Wichtigkeit Eurer Anwesenheit in Kenntnis setzen. Es gibt zunehmend Spannungen zwischen den Nachtelfen von Darnassus und dem Zirkel des Cenarius in Moonglade. Lasst Euch nicht von völkischer Engstirnigkeit beirren und verlasst Euch auf die Weisheit Eurer Vorfahren, wenn Ihr dort mit dem Zirkel zu tun habt, $N. Viel Glück.",objectives={"Sprecht mit Rabine Saturna im Dorf Nighthaven in Moonglade. Moonglade liegt zwischen dem Teufelswald und Winterspring, und Ihr erreicht es über den Pfad, der aus der Holzschlundfeste herausführt."}]])
R(1124,"Einöde",[[description="Westlich des Un'Goro Kraters entlang des nordwestlichen Grats liegt ein raues Ödland - Silithus. Nur wenige wissen, dass sich hier vor Urzeiten ein Krieg zwischen den Nachtelfen und einer bösartigen, außerirdischen Macht abgespielt hat. Das Böse wurde versiegelt, aber jetzt befürchten wir, dass Kräfte am Werk sind, um diesen... unaussprechlichen Horror wieder zu entfesseln.$B$BSprecht mit Layo Starstrike, einem unserer Agenten in Silithus. Sucht nach ihm in Heldenwacht, der letzten Ruhestätte der Gefallenen des Ödlandes. Gebt Ihm diesen Brief, damit erwerbt Ihr sein Vertrauen.",objectives={"Sprecht in der Nähe des Friedhofs Heldenwacht in Silithus mit Layo Starstrike und zeigt ihm Rabines Brief."}]])
R(1125,"Die Geister vom Südwindposten",[[description="Südwestlich von uns liegt ein tragischer Schauplatz - die Ruinen vom Südwindposten. Dort sollten wir mit unserer Arbeit beginnen, $N.$B$BNach allem, was wir wissen, war dieses Dorf einst ein Stützpunkt der Nachtelfen für Operationen in Silithus. In der Zwischenzeit wurde es längst von den Silithidschwärmen überrannt, die die Wüsten durchziehen. Ich vermag mir den Horror kaum vorzustellen, als die Zerstörung des Dorfs begann...$B$BDie gequälten Geister gefallener Druiden und Schildwachen wandern ziellos durch die Ruinen. Erforscht diesen Ort und befreit die Seelen dieser unglücklichen Kreaturen, wo immer es erforderlich ist.",objectives={"Befreit die Geister von 8 gequälten Druiden und 8 gequälten Schildwachen beim Südwindposten und kehrt dann zu Layo Starstrike auf den Friedhof Heldenwacht in Silithus zurück."}]])
R(1126,"Schwarmbau im Turm",[[description="Wir müssen uns um den Schwarmbau beim Südwindposten kümmern, und ich glaube, ich weiß auch schon, wie wir an ihn herankommen. Meiner Erfahrung nach reagieren die Schwarmbauten der Silithiden empfindlich auf ihre Umgebung. Das erklärt auch ihre Angriffe, als sie die Todesschreie der Geister hörten.$B$BIm Turm sind die Silithiden am stärksten - dort, wo massenweise Wespen herumschwirren. Besteigt den Turm und scheucht den Schwarmbau auf. Meldet Euch zurück, sobald Ihr etwas erfahren habt, aber seid vorsichtig! Wenn Ihr irgendetwas Hilfreiches entdeckt, bringt es zu mir.",objectives={"Besteigt den Turm beim Südwindposten und findet eine Möglichkeit, den Schwarmbau der Silithiden aufzuscheuchen. Bringt alles Ungewöhnliche, das Ihr dabei entdeckt, zu Layo Starstrike auf den Friedhof Heldenwacht in Silithus."}]])
R(1127,"Fools Starkbier",[[description="Ihr möchtet also etwas von Fools Starkbier, hm? Denkt Ihr daran, wieder die Rennen zu besuchen...?$B$BGut, bringt mir mehr von Zanzils Mixtur und ich braue noch etwas mehr Starkbier für Euch.",objectives={"Bringt 12 von Zanzils Mixturen zu Crank Fizzlebub in Booty Bay."}]])
R(1130,"Melor schickt Kunde",[[description="$N, Melor Stonehoof hat von Euren Taten gehört und Euch einen Weg geebnet.$B$BWenn Ihr ihn einschlagen möchtet, dann geht nach Thunder Bluff und sprecht mit Melor. Ihr findet ihn auf der Anhöhe der Jäger.",objectives={"Sprecht mit Melor Stonehoof in Thunder Bluff."}]])
R(1131,"Stahlbiss",[[description="Manchmal jagen wir wegen Essen. Manchmal jagen wir wegen der Ehre. Und manchmal jagen wir, um der Lehren der Erdenmutter teilhaftig zu werden.$B$BDoch die Jagd, auf die ich Euch jetzt schicke, hat damit nichts zu tun. Es geht darum, eine Kreatur zu töten, die nicht unter dem Segen der Erdenmutter steht.$B$BDie Hyäne Stahlbiss streift südlich des Brachlandes durch Tausend Nadeln. Sie ist eine Tyrannin, die andere Hyänen anlockt und Furcht und Blutvergießen unter den friedlicheren Wildtieren verbreitet.$B$BSucht Stahlbiss, $n. Sucht und besiegt sie.",objectives={"Bringt Stahlbiss' Rippe zu Melor Stonehoof in Thunder Bluff."}]])
R(1132,"Fiora Longears",[[description="Ach, wieder auf See zu sein! Den Kuss des Windes zu spüren und mich von den Wellen wiegen zu lassen wie vor langer Zeit von meiner gesegneten Mutter!$B$BOh, hätte ich doch nur Euer Glück, $C, denn ich sehe das Meer in Eurer Zukunft!$B$BMeine Aufgabe ist es, eifrige Seelen nach Kalimdor zu bringen, in das Land der unbegrenzten Möglichkeiten! Wenn Ihr Euer Glück in Übersee machen wollt, dann reist von hier mit dem Schiff in den wunderschönen Hafen Theramore. Sprecht mit meiner Partnerin, der Elfin Fiora Longears.$B$BSie wird Euer Abenteuer in Kalimdor beginnen lassen!",objectives={"Sprecht mit Fiora Longears in Theramore."}]])
R(1133,"Reise nach Astranaar",[[description="Wenn Ihr gerade vom Boot von Menethil kommt, dann solltet Ihr als Erstes nach... Astranaar gehen. Ich bin sicher, ein eifriges Mitglied der Allianz kann dort viel Gutes tun. Sprecht mit Shindrell Swiftfire und bietet Eure Dienste an.$B$BAber erwähnt nicht, wer Euch geschickt hat. Shindrell kennt mich nicht...",objectives={"Sprecht mit Shindrell Swiftfire in Astranaar."}]])
R(1134,"Prachtschwingen des Steinkrallengebirges",[[description="Wir führen keinen offenen Krieg mit der Horde, aber der Frieden ist brüchig. Ihre Agenten gehen häufig gegen uns vor, aber stets heimlich.$B$BEiner dieser Feldzüge wurde uns durch geheime Informanten in Theramore enthüllt, die behaupten, dass die Orcs Gift der Prachtschwingen beim Mirkfallonsee im Steinkrallengebirge im Süden sammeln. Dann benutzen Orc-Auftragsmörder das Gift bei ihren geheimen Feldzügen gegen die Allianz!$B$BWenn das stimmt, dann müssen wir sie aufhalten, $N. Wir müssen ihnen den Zugang zu dem Gift versperren.",objectives={"Bringt 12 Prachtschwingengiftbeutel zu Shindrell Swiftfire in Astranaar."}]])
R(1135,"Steilhanggift",[[description="Wie Ihr sicher wisst, werden Flügeldrachen oft von Orcs als Reittiere gezähmt. Weniger bekannt indessen ist, dass das Gift eines Flügeldrachen in manchen Kreisen höher geschätzt wird als die Bestie selbst. Falls Ihr also keine Angst vor einer kleinen Flügeldrachenjagd habt... habe ich einen Job für Euch.$B$BEs gibt einen Ort im Land Tausend Nadeln, er liegt westlich von hier, welcher als der Steilhang bekannt ist. Die dort lebenden Steilhangflügeldrachen haben ein starkes Gift. Stark und kostbar.",objectives={"Bringt 10 Steilhanggiftbeutel zu Fiora Longears in Theramore."}]])
R(1136,"Frostrachen",[[description="$n, jetzt ist es Zeit, weit entfernte Länder zu bereisen. Ihr seid bereit.$B$BIhr jagt jetzt Frostrachen, einen Yeti im Alteracgebirge. Er ist schwer zu erkennen, da sein weißes Fell mit den Schneefeldern seiner Bergheimat verschmilzt. Man bekommt ihn kaum je zu sehen.$B$BAber ich zeige Euch, wie man eines solchen Geschöpfes habhaft wird. Hier, nehmt diese Rolle. Ich habe darauf vermerkt, wie man Frostrachen anlocken kann.$B$BGeht jetzt, $n. Eure Reise ist lang und viele Herausforderungen harren Eurer. Erst wenn Ihr mit Frostrachens Mähne zurückkehrt, ist Eure Aufgabe abgeschlossen.",objectives={"Bringt Frostrachens Mähne zu Melor Stonehoof in Thunder Bluff."}]])
R(1137,"Neuigkeiten für Fizzle",[[description="Indurium besitzt einen erstaunlichen Hitzewiderstand! Ich bin sicher, es taugt für Fizzles Kolben. Aber er braucht echtes Indurium, nicht nur die Späne.$B$BDas Erz muss tief in den Minen von Uldaman abgebaut werden, an der Nordgrenze des Ödlandes. Das ist die wahre Quelle von Indurium.$B$BBestellt Fizzle Brassbolts Grüße von mir und sagt ihm, was ich Euch gesagt habe.$B$BAngenehme Reise, $N. Ich wäre nicht überrascht, wenn wir uns wiedersehen - wenn Fizzle von dem Indurium erfährt, schickt er Euch wahrscheinlich nach Uldaman, um es zu holen!",objectives={"Sprecht mit Fizzle Brassbolts in der schimmernden Ebene."}]])
R(1138,"Meeresfrüchte",[[description="Ich liebe Krebse. Krebse sind die Früchte des Meeres! Man kann sie backen, grillen, kochen und braten. Man kann sie in der Pfanne braten, frittieren und kurzbraten. Es gibt Krebssalat, Krebssuppe, Krebseintopf, Pfefferkrebs, Zitronenkrebs, Peitscherwurzelkrebs und Ironforgekrebs à la Surprise. Das ... das war's eigentlich.$B$BIch angle hier gerade und daher kann ich mir keine feinen Krebsbrocken besorgen. Mann kann sie aus Riffkriechern und verkrusteten Gezeitenkriechern kratzen. Man kann viel mit ihnen anstellen. Man kann sie backen, grillen, kochen ...",objectives={"Sammelt 6 feine Krebsbrocken für Gubber Blump in Auberdine."}]])
R(1139,"Die verlorene Tafel des Willens",[[description="Wir haben den Schattenschmiedeklan ausgebremst, indem wir ihn von der Blackrockspitze abgeschnitten haben, doch Hammertoes Mission wurde noch nicht erfüllt. Sein Tod darf nicht umsonst gewesen sein. Er träumte davon, die Schrifttafel des Willens zu finden: eine Steintafel, graviert mit Magie durch die Titanen selbst, die helfen, ihren Schöpfungen Leben einzuhauchen und ihnen damit einen eigenen Willen ermöglichen. So jedenfalls heißt es in den Legenden.$B$BDennoch müssen wir die Tafel bergen, ehe der Schattenschmiedeklan sie finden kann.$B$BKehrt nach Uldaman zurück, sucht die Tafel und kommt unverzüglich wieder her.",objectives={"Sucht die Tafel des Willens und bringt sie zu Berater Belgrum in Ironforge."}]])
R(1140,"Der Turm von Althalaxx",[[description="Díe Schrift der Orcs ist kaum mehr als das Gekritzel eines Kindes. Viele meines Ordens spotteten, als ich ihre Sprache lernen wollte, aber ich fand es hilfreich, meine Feinde besser zu verstehen.$b$bIlkruds Gekritzel zufolge scheint Athrikus immer noch zwei Seelenedelsteine zu besitzen, und die werden in Nightrun und Satyrnaar aufbewahrt, Satyrgebiete im nordöstlichen Ashenvale.$b$bSeid vorsichtig da draußen, $n, die bluttriefenden Tempel der Satyrn können selbst für abgebrühte $C wie Euch beängstigend sein.",objectives={"Befreit die Hochgeborenenseelen in Night Run und Satyrnaar und kehrt zu Delgren dem Läuterer in Maestras Posten zurück."}]])
R(1141,"Die Familie und die Angel",[[description="Ich liebe das Angeln. Die Blump-Familie ist berühmt fürs Angeln. Mein Name ist Gubber Blump; ich angle.$B$BEs gibt eine Fischart, die ich hier in der Gegend gern fange. Sie heißt Dunkelküstenbarsch. Früher fuhr ich mit einem Boot hinaus, um Barsche zu angeln, aber seitdem die gemeinen Murlocs gekommen sind, fahren keine Boote mehr raus. Ich wette, dass sie auch alle Barsche aufgefressen haben.$B$BSagt, wollt Ihr mir helfen, Dunkelküstenbarsche zu fangen? Ich würde Euch eine echte Blump-Familienangel geben, wenn Ihr es tun würdet! Es ist eine wirklich gute Angel, um damit Fische zu fangen.",objectives={"Fangt 6 Dunkelküstenbarsche für Gubber Blump in Auberdine."}]])
R(1142,"Die Sterblichkeit schwindet",[[description="Ich habe nicht mehr lange zu leben... so... so... schwach.$b$b... der t-t-tapfere Zwerg Lonebrow hat jemanden geschickt, Falfindel zu w-w-warnen...$b$bAber bevor ich... s-s-sterbe...$b$b... meine Frau Treshala... ihr Anhänger des Bundes mit mir... gestohlen... von einem der n-n-niederträchtigen Angreifer...$b$bB-B-Bitte sucht ihn... und bringt ihn Treshala in Darnassus zurück...$b$b... mit der Nachricht meines einsamen... Todes.",objectives={"Sucht und bringt Treshalas Anhänger zu Treshala Fallowbrook in Darnassus."}]])
R(1143,"Der Turm von Althalaxx",[[description="Verstehe. Also wenn das stimmt, was Ihr sagt, dann ist jetzt die Zeit gekommen, endlich zuzuschlagen. Ich glaube, Athrikus residiert in der Turmspitze. Aber seid vorsichtig, er ist von vielen mächtigen Hexenmeistern umgeben, die tödlicher sind als Eure bisherigen Gegner.",objectives={"Tötet Athrikus Narassin und bringt seinen Kopf zu Balthule Shadowstrike nahe des Turms von Althalaxx."}]])
R(1144,"Willix der Importeur",[[description="Endlich ist Hilfe eingetroffen!$b$bIhr habt keine Ahnung, wie lang ich hier gefangen gehalten wurde. Ich kann mich nicht erinnern, wann ich zum letzten Mal draußen war.$b$bWisst Ihr, ich bin Unternehmer. Immer am abkupfern, wie man so sagt. Ich habe Wind davon bekommen, dass Mebok Mizzyrix gut für Rotlaubknolle aus diesem Schweinepferch hier bezahlt. Ich dachte mir, das würde ein leichtes Spiel werden. Wie Ihr sehen könnt, habe ich mich geirrt!$b$bWie auch immer, wenn Ihr so freundlich wärt, mir hier raus zu helfen, sollte es Euer Schaden nicht sein.",objectives={"Führt Willix den Importeur aus dem Kral von Razorfen hinaus."}]])
R(1145,"Der Schwarm wächst",[[description="Viele Reisende, die durch Crossroads kamen, halfen mir, Eier vom Feld der Riesen zu sammeln, und viele können Geschichten erzählen, wie tödlich diese Kreaturen sind. Ich habe genug gehört, um diese Insekten als größere Bedrohung einzustufen als meine Meister zuerst dachten.$B$BIch brauche einen Kurier, der nach Orgrimmar reist und sich mit Belgrom Rockmaul trifft. Das dürfte keine Kleinigkeit werden und es sollte nur jemand gehen, der die Aufgabe ernst nimmt.$B$BBelgrom ist für gewöhnlich vor der Halle der Kriegerhelden zu finden.",objectives={"Stellt Korrans versiegelte Notiz Belgrom Rockmaul in Orgrimmar zu."}]])
R(1146,"Der Schwarm wächst",[[description="Korran ist also zu einer ähnlichen Schlussfolgerung hinsichtlich dieser Insekten gekommen - sie scheinen doch eine größere Bedrohung zu sein, als wir dachten.$B$BVor ein paar Tagen kehrte ein Jäger halbtot aus Tausend Nadeln zurück. Er gehörte zu einem Stoßtrupp, der geschickt wurde, um ein Ausgrabungsteam der Zwerge von der Schimmernden Ebene zu verjagen. Während des Angriffs kamen noch mehr von diesen Insekten aus einer Höhle an der Grabungsstätte und hätten die Gruppe fast getötet.$B$BIhr Anführer war Moktar Krin und sie suchten Zuflucht an der Grenze der Schimmernden Ebene. Bringt ihm diese Notiz.",objectives={"Stellt Belgroms versiegelte Notiz Moktar Krin in Tausend Nadeln zu."}]])
R(1147,"Der Schwarm wächst",[[description="Hmm. Offenkundig hält Belgrom die Monster für eine Bedrohung. Er möchte sie in die Tiefen zurückgedrängt haben, aus denen sie gekommen sind.$B$BDie Zwerge zu töten, die von der Forscherliga geschickt wurden, genügte wohl nicht - jetzt muss ich eine Gruppe halbtoter Krieger in einen neuen Kampf führen. Aber selbst können wir das nicht; nicht unter diesen Bedingungen. Die Grabungsstätte liegt südlich von hier. Es sollten keine Zwerge mehr in der Gegend sein. Habt Ihr Lust, Klinge oder Stab in die Hand zu nehmen und uns zu unterstützen?",objectives={"Tötet 5 Silithidsucher, 5 Silithidschwarmdrohnen sowie 5 Silithideindringlinge und kehrt zu Moktar Krin in Tausend Nadeln zurück."}]])
R(1148,"Teile des Schwarms",[[description="Ihr untersucht den Knochenpanzer gründlich. Als Ihr ihn in den Händen dreht, stellt Ihr fest, dass die Chitinplatten derart verflochten sind, dass er dadurch unglaublich hart wird. So etwas habt Ihr noch nie gesehen. Ihr untersucht den Rest des Kadavers und kommt zu dem Schluss, dass diese Kreaturen sehr kräftig und hochentwickelt sind.$B$BAls ihr einen weiteren Blick auf den Knochenpanzer werft, wird Euch klar, dass Korran diese Kreaturen gewiss gern studieren würde. Er könnte dadurch herausfinden, was diese Kreaturen sind und woher sie kommen.",objectives={"Bringt 1 Silithidenherz, 5 Silithidenkrallen und 3 intakte Silithidenknochenpanzer zu Korran in Crossroads."}]])
R(1149,"Test des Glaubens",[[description="Ihr habt mich also gesucht, oder führt Euch das Schicksal zu mir? Einerlei. Ihr seid jetzt hier, und so wird Eure Reise erneut beginnen.$B$BDas Sein besteht aus vielen Aspekten: Geist, Körper, Verstand. Einige davon kann man anhand der Traditionen einer Kultur bewerten. Von anderen können wir nur hoffen, dass sie in uns selbst existieren. Wenn Ihr einverstanden seid, möchte ich einige der Aspekte in Euch testen.$B$BWenn Ihr besteht, werdet Ihr stärker werden. Wenn Ihr scheitert, werdet Ihr die Weite des Nether begreifen.$B$BAls Erstes ein Test des Glaubens.",objectives={"Wenn Ihr festen Glaubens seid, dann springt von den Planken über Tausend Nadeln."}]])
R(1150,"Test der Belastbarkeit",[[description="Ich sehe mit Freuden, dass Euer Mut im Lichte Eurer bisherigen Taten unerschütterlich bleibt. Da Euer Glaube stark ist, wird es Zeit, Euren Körper zu testen.$B$BAls Erstes ein Test der Belastbarkeit. Geht mit Freunden zum Bau der Wildfedern westlich vom Freiwindposten. Steigt in die Tiefen ihres Unterschlupfes hinab und zerstört ihre Nahrungsvorräte. Damit solltet Ihr deren Zorn angestachelt haben. Wenn Ihr lange genug überlebt, wird Grenka Blutkreischer Euch persönlich heimsuchen. Tötet sie und bringt mir ihre Klaue, um den Test abzuschließen.",objectives={"Bringt Grenkas Klaue zu Dorn Plainstalker in Tausend Nadeln."}]])
R(1151,"Test der Kraft",[[description="Zu Zeiten der Alten Götter bewohnten Elementare einen Großteil dieser Welt. Sie beteten die Alten Götter an, und die Götter fesselten die Elementare durch ihre Macht an diese Welt. Als die Alten Götter verbannt wurden, verblassten die Elementare in unserer Welt und kehren jetzt auf Geheiß mächtiger Magier zurück.$B$BAber es gibt Ausnahmen. Einige Elementar waren mächtig genug, aus eigenen Stücken hier zu bleiben. Solch ein Elementar ist Rok'Alim.$B$BSucht Rok'Alim in Tausend Nadeln und tötet ihn, um Eure Kraft zu beweisen.",objectives={"Bringt Fragmente von Rok'Alim zu Dorn Plainstalker in Tausend Nadeln."}]])
R(1152,"Test der Lehre",[[description="Eure Zeit bei mir neigt sich dem Ende zu. Ich bin wissend, aber den Test der Lehre kann ich Euch nicht stellen. Es gilt, Lektionen zu erlernen und Orte zu besuchen, die in der Zuständigkeit anderer liegen.$B$BWenn Ihr bereit seid, dann sucht Braug Dimspirit auf - er ist ein höchst weiser Schamane. Er wird Euch weiter testen, also achtet auf seine Worte, $N.$B$BWenn Ihr bereit seid, dann sucht den Tunnel, der das Steinkrallengebirge mit Ashenvale verbindet. Dort in der Nähe lebt Braug. Und seid vorsichtig, $N, die Nachtelfen versuchen vielleicht, Euren Test zu behindern.",objectives={"Sucht Braug Dimspirit in der Nähe des Eingangs zum Steinkrallenpfad im Steinkrallengebirge."}]])
R(1153,"Eine neue Erzprobe",[[description="$C, Ihr habt mir auch früher schon geholfen. Der Kriegshäuptling ist mit meinen bisherigen Leistungen zufrieden und bittet mich, mit neuer Entschlossenheit fortzufahren. Meine Ehre gebietet, dass ich den Kriegshäuptling wissen lasse, was Ihr alles vollbracht habt, doch zuvor möchte ich Euch abermals um Hilfe bitten.$B$BJüngst kamen Reisende aus dem Süden von einem Ort namens Tausend Nadeln. Dort töteten sie einen Kobold, der eine außergewöhnliche Erzprobe bei sich hatte, wollten sie aber nicht verkaufen. Ich möchte eine Probe dieses Erzes untersuchen.",objectives={"Sucht eine unbearbeitete Erzprobe bei einem Buddler oder Feldmesser der Bruchschnauzen und bringt sie zu Tatternack Steelforge im Camp Taurajo im Brachland."}]])
R(1154,"Test der Lehre",[[description="Ihr habt Dorns Tests bestanden und wollt jetzt Eure nächste Prüfung absolvieren. Sehr gut. Bisher sind alle Eure Herausforderungen kindisch gewesen. Es ist leicht, Euren Körper zu testen - bei Eurem Verstand sieht das schon anders aus.$B$BIch werde es mit einfachen Worten erklären: sucht das Buch, das ich Euch nenne, lest es und beantwortet meine Fragen nach seinem Inhalt.$B$BWas für ein Buch, werdet Ihr fragen? Das 'Vermächtnis der Aspekte'. Man findet es in den Tiefen des Dor'danil-Grabhügels im südlichen Ashenvale, wo es von den toten Druiden und deren Tötern bewacht wird.",objectives={"Sucht das 'Vermächtnis der Aspekte' und bringt es zu Braug Dimspirit in der Nähe des Eingangs zum Steinkrallenpfad im Steinkrallengebirge zurück."}]])
R(1155,"<NYI> <TXT> bug crystal side quest",[[description="x",objectives={"x"}]])
R(1156,"<NYI> <TXT> speak to alchemist pestlezugg",[[description="x",objectives={"x"}]])
R(1157,"<NYI> <TXT> pestlezugg needs items")
R(1158,"<NYI> <TXT> speak to rabine saturna",[[description="x",objectives={"x"}]])
R(1159,"Test der Lehre",[[description="Gut gemacht, $n. Ihr habt den ersten Teil des Tests der Lehren bestanden, aber es bleibt noch eine Frage zu beantworten. Aber es ist nicht an mir, diese Frage zu stellen.$B$BBesucht Parqual Fintallas in Lordaeron. Er war ein bedeutender Historiker der Menschen, bevor die Seuche ihn erwischte. Jetzt sucht er immer noch Erleuchtung, freilich einer ganz anderen Art.$B$BEr wird eine weitere Forderung an Euch stellen, bevor er Euch etwas fragt, aber Ihr habt Euch bisher meisterhaft geschlagen - ich bin sicher, Ihr werdet dieses Hindernis überwinden.",objectives={"Sucht Parqual Fintallas in Undercity."}]])
R(1160,"Test der Lehre",[[description="Ich sage Euch, was Ihr suchen müsst und werde Euch sogar meine Frage stellen, aber nicht, weil Ihr Euch beweisen wollt. Wissen ist weit wichtiger als Kraft. Auch wenn andere Euch in ihren Fähigkeiten überlegen sein mögen, Euer Wissen über die Welt ist wertvoller.$B$BGeht zu dem Kloster im Norden Tirisfals. In der dortigen Bibliothek steht ein Buch mit dem Titel Die Anfänge der Bedrohung durch die Untoten. Es wurde von den jetzt verderbten Paladinen benutzt, um sie in meiner Art des Kampfes auszubilden.$B$BBringt es mir.",objectives={"Sucht Die Anfänge der Bedrohung durch die Untoten und bringt es zu Parqual Fintallas in Undercity."}]])
R(1161,"<NYI> <TXT> gossip shade of ambermoon",[[description="x",objectives={"x"}]])
R(1162,"<NYI> <TXT> speak to hamuul runetotem",[[description="x",objectives={"x"}]])
R(1163,"<NYI> <TXT> speak to tyrande whisperwind",[[description="x",objectives={"x"}]])
R(1164,"Von Dieben stehlen",[[description="Die Hure! Das Flittchen! Kenata lebt noch; ihre Familie blüht und gedeiht, während ich leide. Verlassene, wahrhaftig!$B$BMeine Familie wurde Opfer der Seuche. Unser Besitz ebenfalls dahin, während des Kriegs geplündert und niedergebrannt. Und nach alledem haben sie und ihre lausigen Kinder die Stirn, das einzig Kostbare zu stehlen, das ich noch hatte.$B$BMir sind die Sachen, die sie gestohlen haben, längst einerlei. Ich möchte ihre Köpfe!$B$BTötet sie für mich! Geht zum Bauernhof der Dabyries in Arathi, nordöstlich der Zuflucht.",objectives={"Bringt Kenata, Fardel und Marcel Dabyries Köpfe zu Genavie Callow in Undercity."}]])
R(1166,"Oberanführer Mok'Morokks Sorgen",[[description="Verbeugen Euch vor Oberanführer Mok'Morokk!$b$bRexxar mich machen zu mächtigem Anführer von Stonemaulklan!$b$bIch gut Anführer. Ich Klan sicher machen.$b$bGroße Drachen kommen und machen Feuer in alte Heimat. Ich klug Oger. Finden neu Heimat für Klan hier.$b$bAlte Heimat so schnell verlassen, ich Sachen vergessen. Winzig $R, gehen mein Sachen holen. Gehen nach Süden und suchen mein lecker Grog, mein Schnupftabak und mein Geldkassette. Ich Euch mögen, wenn Ihr das tun. Ihr in Flammenbau und Stonemaul Ruinen schauen... sie dort sein, ich sicher!",objectives={"Oberanführer Mok'Morokk in Brackenwall möchte, dass Ihr seinen Grog, seinen Schnupftabak und seine Geldkassette aus dem Dustwallowsumpf holt."}]])
R(1167,"Der Turm von Althalaxx",[[description="Bevor Ihr Athrikus konfrontiert, wäre es vermutlich klug, Balthule zu konsultieren. Zweifellos ist er wachsam in seinem Wachturm gewesen und könnte Informationen über jüngste Entwicklungen haben.",objectives={"Sprecht mit Balthule Shadowstrike beim Turm von Althalaxx."}]])
R(1168,"Armee des schwarzen Großdrachen",[[description="Mok'Morokk wurde von Rexxar zum Oberanführer gemacht. Ihm liegt mehr an Macht als an den Ogern.$b$bSchwarze Großdrachen töten viele Oger. Töten Thargs Frau. Mok'Morokk sagt uns, wir müssen fliehen. Lässt uns hierher kommen.$b$bOger sollten kämpfen. Oger nicht gut im Weglaufen. Mok'Morokk schert sich nur um Mok'Morokk.$b$bFür mich Stonemaul Ruinen Heimat. Mir gefallen im Süden. Dieser Ort nicht Heimat.$b$bHelft Ogern, Armee der schwarzen Großdrachen zu bekämpfen. Ich wollen Rache. Ich wollen nach Hause.",objectives={"Tharg in Brackenwall möchte, dass Ihr 15 Späher der Feuermähnen, 10 Aschenschweife der Feuermähnen und 5 Bannschuppen der Feuermähnen tötet."}]])
R(1169,"Die Brut identifizieren",[[description="Während der törichte Narr Mok'Morokk seine Macht genießt und Tharg mit den Dämonen des Kummers und der Rache ringt und um die Führerschaft des Klans buhlt, scheine ich der Einzige zu sein, der die Ursache der Aggression in unserer alten Heimat herausfinden möchte.$b$bWarum der verwirrte Blick, $n? Erwartet Ihr, dass ich wie ein tumber Grobian spreche, nur weil ich ein Oger bin?$b$bDoch zurück zum Geschäft, bringt mir die Herzen und Zungen der Welpen und Jungtiere. Ich werde die Wurzel dieses Übels finden...",objectives={"Draz'Zilb in Brackenwall hätte gern, dass Ihr ihm 15 sengende Zungen und 15 sengende Herzen bringt."}]])
R(1170,"Die Brut von Onyxia",[[description="Das Dorf Stonemaul wurde von der Brut von Onyxia überrannt. Aber warum sollte die Tochter des Schwarzen-Großdrache-Lords Deathwing über unser Land herfallen?$b$bDas ist sehr beunruhigend. Gewiss wurde Onyxia aus einem anderen Grund hergeschickt, als eine kleine Schar von Ogern zu belagern.$b$bVerständigt unverzüglich Mok'Morokk! Es muss gehandelt werden.",objectives={"Sprecht mit Oberanführer Mok'Morokk in Brackenwall."}]])
R(1171,"Die Brut von Onyxia",[[description="Ihr lasst mich jetzt in Ruhe. Sagt Draz'Zilb, wir bleiben hier. Keine schwarzen Großdrachen hier.",objectives={"Sprecht mit Draz'Zilb in Brackenwall."}]])
R(1172,"Die Brut von Onyxia",[[description="Onyxias Brut wurde über das Drachendüster verstreut. Es dürfen auf keinen Fall weitere Welpen schlüpfen.$b$bBegebt Euch eilig zum Drachensumpf in den Marschen von Dustwallow. Gewiss hat sie dort einen Hort angelegt. Sucht die Eier der bösen Großdrachen und vernichtet sie.$b$bWir können das Dorf Stonemaul nie zurückerobern, wenn das Umland eine Brutstätte bleibt.$b$bWas Mok'Morokk angeht ... Für den Jammerlappen habe ich andere Pläne.",objectives={"Draz'Zilb in Brackenwall möchte, dass Ihr 5 Eier von Onyxia zerstört."}]])
R(1173,"Fordert Oberanführer Mok'Morokk heraus",[[description="Ihr wagt es, Oberanführer Mok'Morokk herauszufordern?$b$bHa!$b$bIch zerschmettern einen Winzling von $R!$b$bIhr mir sagen, wenn bereit für ordentliche Tracht Prügel.",objectives={"Besiegt Mok'Morokk und bringt die Nachricht zu Draz'Zilb in Brackenwall."}]])
R(1174,"Gnomes Win!")
R(1175,"Eine Straßenunebenheit",[[description="Nach dem schweren Zusammenstoß des Red-Thunder-Rennwagen der Goblins und einem Basilisken hat Kronkrider mich angeheuert, um die Strecke zu warten. Keine Ahnung, was die Tiere in der Ebene fressen, dass sie so groß werden, aber wir müssen sie dezimieren, damit sie nicht auf die Fahrbahn laufen, wenn ein Rennen stattfindet.$b$bIch sag Euch was. Wenn ihr ein wenig Profit machen wollt, zieht los und entfernt die Basilisken aus der Gegend.",objectives={"Tötet 10 Salzsteinbasilisken, 10 Salzsteinkristallhäute und 6 Salzsteinstarrer für Rennsteckenleiter Zherin in der Schimmernden Ebene."}]])
R(1176,"Gewicht reduzieren",[[description="Wenn es um Rennen geht, zählt jede Kleinigkeit! Ob es sich nun um ein leises Quietschen der Kraftübertragung, eine geringfügige Schwäche der Stoßdämpfer oder ein leichteres Gewicht der Karosserie handelt, man muss alles berücksichtigen.$b$bWir benutzen Geierknochen für kleinere Modifikationen am Chassis unserer Rennwagen, die das perfekte Gleichgewicht zwischen Stärke und Gewicht haben. Und sie sind, was noch besser ist, leicht zu beschaffen, da es in der Salzwüste von Geiern wimmelt.$b$bBringt mir ein paar und ich zahle einen guten Preis dafür.",objectives={"Beschafft 10 hohle Geierknochen für Pozzik in der Schimmernden Ebene."}]])
R(1177,"Hunger!",[[description="Mud großer Oger.$b$bIch hungrig.$b$bGeht Fische hauen. Bringt Mud Essen.$b$bIhr füttert Mud oder Mud frisst Euch.",objectives={"Mudcrush Durtfeet im nördlichen Dustwallow möchte 12 Schlammflossenköpfe."}]])
R(1178,"Goblin-Sponsoring",[[description="Unser Rennfahrer-Team ist der Stolz aller Goblins. Ihr wärt überrascht, welche Leute unser Team auf die eine oder andere Weise unterstützen.$b$bKennt Ihr Gazlowe? Er treibt auf der ganzen Welt Ersatzteile für uns auf. Er kam sogar mal her, um an einer unserer Aufhängungen zu arbeiten!$b$bVor ein paar Wochen wollte er uns den Prototyp einer neuen Treibstoffeinspritzpumpe schicken, aber sie ist noch nicht eingetroffen. Sonst ist er immer zuverlässig ... Würde es Euch vielleicht etwas ausmachen, nach Ratchet zu gehen und ihn danach zu fragen? Ich will ja nicht drängen, aber die Gnome holen langsam auf!",objectives={"Sprecht mit Gazlowe in Ratchet."}]])
R(1179,"Die Brüder Brassbolt",[[description="Schon von der Schimmernden Ebene gehört, ja? Das ist eine Salzwüste drüben in Kalimdor, direkt südlich vom Canyon der Tausend Nadeln. Der ideale Austragungsort für Rennen, weil es da so flach ist!$B$BDa draußen sind zwei Gnomenbrüder, Freunde von mir, die ihren neuen Raketenwagen erproben, und soweit ich gehört habe, ist er schnell! Hey, so schnell, dass die Fahrer immer verunglücken. Und Gehirnerschütterungen bekommen.$B$BDarum baten sie mich um ein paar Helme für Belagerungsmaschinen, aber ich kann hier nicht weg, meine Pflicht fesselt mich an diesen Ort. Ich kann die Reise also nicht machen!$B$BKönnt Ihr es?",objectives={"Bringt die Kiste mit Schutzhelmen zu Wizzle Brassbolts in der schimmernden Ebene."}]])
R(1180,"Goblin-Sponsoring",[[description="Zurück zum Grund Eures Hierseins. Ich weiß, ich habe Pozzik versprochen, dass ich ihm eine neue Treibstoffeinspritzpumpe schicke, aber ich habe sie selbst noch nicht bekommen. Revilgaz drüben in Booty Bay sagte, er würde sie herschicken, aber irgendwie scheint da was schief gelaufen zu sein.$b$bWenn das stimmt, können wir wenig dagegen tun. Aber wir können wenigstens herausfinden, wann sie von Booty Bay abgeschickt wurde.$b$bFragt drüben bei Werftmeister Lozgil nach, er müsste die Frachtbriefe überprüfen können.",objectives={"Sprecht mit Werftmeister Lozgil in Booty Bay."}]])
R(1181,"Goblin-Sponsoring",[[description="Ich fürchte, ich kann Euch nicht weiterhelfen, $n. Wenn Ihr der Sache weiter nachgehen möchtet, würde ich vorschlagen, Ihr geht zum Baron persönlich. Wenn jemand über die Geschäfte von Revilgaz Bescheid weiß, dann Revilgaz selbst.$b$bIhr findet ihn in der Taverne jenseits des Hafens, Obergeschoss.",objectives={"Sprecht mit Baron Revilgaz in Booty Bay."}]])
R(1182,"Goblin-Sponsoring",[[description="Wisst Ihr, die Schredder der Venture Company draußen am Nazferitisee (im Norden des Schlingendorntals) wurden mit einer neuartigen Treibstoffeinspritzpumpe ausgerüstet. Ich dachte mir, Pozzik könnte Kapital daraus schlagen, wenn er einige Einzelheiten erfahren könnte. Leider scheint Cozzle, der dortige Großknecht, etwas schlauer zu sein als ich ihm zugestehen wollte.$b$bAber Ihr seht aus, als könntet Ihr es schaffen, die Blaupausen zu finden. Ich weiß, dass er sie in seinem Haus aufbewahrt, aber mit Sicherheit verschlossen und verriegelt.",objectives={"Bringt die Treibstoffreglerblaupausen zu Baron Revilgaz in Booty Bay."}]])
R(1183,"Goblin-Sponsoring",[[description="Ihr solltet zum Aufbruch bereit sein. Bestellt Pozzik schöne Grüße und sagt ihm, wenn er etwas braucht, soll er keine Hemmungen haben, zu fragen. Ich warte auf die baldige Nachricht, dass er den Streckenrekord gebrochen hat!",objectives={"Bringt die Blaupausen der Treibstoffeinspritzpumpe zu Pozzik in der Schimmernden Ebene."}]])
R(1184,"Teile des Schwarms",[[description="Geht zurück zu Belgrom in Orgrimmar und sagt ihm, dass Moktar in Tausend Nadeln ganz in seinem Sinne handelt. Sagt ihm auch, dass meine Studien voranschreiten und ich hoffe, dass ich bald mehr gelernt habe. Das sollte ihn freuen.",objectives={"Kehrt zu Belgrom Rockmaul in Orgrimmar zurück."}]])
R(1185,"Unter dem Chitin war...")
R(1186,"Der achtzehnte Rennfahrer",[[description="Ich werde damit beschäftigt sein, diese neue Treibstoffeinspritzpumpe in unsere Rennwagen einzubauen, aber wenn Ihr dem Team noch weiter helfen möchtet, sprecht mit Razzeric. Er ist unser Fahrer - unser achtzehnter Fahrer, um genau zu sein -, und er nimmt selbst gern Veränderungen an den Rennwagen vor.$b$bAber er ist ein wenig daneben, bemüht Euch daher, nicht zu überrascht zu wirken.",objectives={"Sprecht mit Razzeric in der schimmernden Ebene."}]])
R(1187,"Razzerics Basteln",[[description="Pozzik ist ein toller Mechaniker, das weiß ich, aber er hat Angst davor, einfach was mit viel Power einzubauen und dann loszudüsen. Aber ich nicht.$b$bWenn Pozzik mit einem Rennwagen fertig ist, nehme ich mir die Zeit und baue eigene Veränderungen ein - Ihr wisst schon, die Steuerung lockern, Teile des Rahmens entfernen und ihm mehr Saft geben!$b$bIch habe einen Zephyriumnachbrenner von Shreev im Gizmorium in Gadgetzan bestellt, aber offenbar musste der Zeppelin, mit dem er geschickt wurde, in den Marschen von Dustwallow notlanden! Ich muss das Ding haben, $N!",objectives={"Bergt den Zephyriumnachbrenner für Razzeric in der Schimmernden Ebene."}]])
R(1188,"Sicherheit zuerst",[[description="Doch wartet, was ist das? Shreev hat die Sicherung aktiviert gelassen. Das reduziert die Menge Energie, die ich aus dem Nachbrenner rausholen kann. Ich sagte ihm, ich wollte sie deaktiviert haben! Das ist nicht gut.$b$bIhr müsst das ins Gadgetzan-Gizmorium in der Tanariswüste bringen und es von Shreev entfernen lassen.",objectives={"Bringt den Zephyriumnachbrenner zu Shreev in Gadgetzan."}]])
R(1189,"Sicherheit zuerst",[[description="So, ich habe getan, was Razzeric wollte. Sagt ihm nur, er soll vorsichtig sein, wenn er das zündet. Wenn er den kleinsten Fehler macht, fährt er nicht los, sondern ist nur noch ein Brandfleck auf der Rennstrecke.$b$bWäre doch ein Jammer, wenn das passiert. Wer weiß, ob unser neunzehnter Fahrer genauso gut wäre?",objectives={"Bringt den umgebauten Zephyriumnachbrenner zu Razzeric in der schimmernden Ebene."}]])
R(1190,"Tempo halten",[[description="Die Brassbolts-Brüder haben einen neuen Baustoff entdeckt, das ist die einzig logische Erklärung. Ihre Rennwagen fahren schneller als vorher, aber Design und alle anderen Daten ihrer Probefahrten sind noch dieselben.$b$bWir wissen, dass Rizzle Brassbolts sich fast ununterbrochen mit den Plänen seiner neuen Entdeckung befasst hat.$b$bZamek kann ein Ablenkungsmanöver inszenieren, damit Ihr diese Pläne von ihnen stehlen könnt.",objectives={"Lasst Zamek ein Ablenkungsmanöver inszenieren und stehlt dann Rizzles Pläne für Pozzik in der schimmernden Ebene."}]])
R(1191,"Zameks Ablenkungsmanöver")
R(1192,"Induriumerz")
R(1193,"Die beschädigte Falle")
R(1194,"Rizzles Baupläne",[[description="Rizzles Baupläne beschreiben den Vorgang der Veredelung von Induriumerz. Man kann dem Gekritzel entnehmen, dass Induriumerz an der Ausgrabungsstätte Uldaman der Zwerge im Ödland zu finden ist.$b$bDie anderen Notizen behandeln fast ausschließlich seinen Hitzewiderstand.$b$bAls Briefbeschwerer der Pläne dient ein Klumpen, der wie unbearbeitetes Induriumerz aussieht.",objectives={"Bringt die Induriumerzprobe zu Pozzik in der schimmernden Ebene."}]])
R(1195,"Die heilige Flamme",[[description="Die Galakzentauren von Tausend Nadeln beschützen ein Artefakt aus der Zeit der Erschaffung der Zentauren.$b$bWir würden es gern bergen, benötigen aber eine Phiole Wasser aus einem der Mondbrunnen der Nachtelfen.$b$bUm dieses Wasser zu beschaffen, müsst Ihr zuerst eine Phiole besorgen, wie sie die Dryaden beim Raynewood im Herzen von Ashenvale besitzen. Am Westufer des Falfarren, südlich der Hauptstraße, befindet sich ein Mondbrunnen, in dem Ihr die Phiole füllen könnt.",objectives={"Bringt eine gefüllte geätzte Phiole zu Zangen Stonehoof in Thunder Bluff."}]])
R(1196,"Die heilige Flamme",[[description="Bringt die gefüllte Phiole zu Rau Cliffrunner beim Freiwindposten im Südosten von Tausend Nadeln. Ihr gelangt nach Tausend Nadeln, wenn Ihr den großen Aufzug am Südrand des Brachlandes benutzt.$b$bIch wäre nicht überrascht, wenn Ihr uns weiter behilflich sein könntet.",objectives={"Bringt die gefüllte geätzte Phiole zu Rau Cliffrunner im Freiwindposten."}]])
R(1197,"Die heilige Flamme",[[description="Wenn Ihr das Wasser benutzt, das Ihr mitgebracht habt, könnt Ihr vorübergehend die Flamme löschen, die das Zentaurenrelikt schützt. Aber der Effekt ist nicht von Dauer, daher müsst Ihr rasch handeln.$b$bIhr findet die Spalthufklippe, die Festung der Zentauren, nördlich von hier. Die Flamme wird in der Spalthufhöhle bewahrt, einem schwer bewachten Teil der Klippe.$b$bAber seid vorsichtig, die Zentauren der Galak sind dort in großer Zahl zugegen und dürften etwas, das ihnen so teuer ist, nicht freiwillig hergeben.",objectives={"Holt den gespaltenen Huf für Rau Cliffrunner im Freiwindposten."}]])
R(1198,"Auf der Suche nach Thaelrid",[[description="Heutzutage kursieren viele Gerüchte über die Vereinigung der Twilight-Hammer und Naga in der Blackfathom-Tiefe an den Küsten von Ashenvale.$b$bMeine Rolle hier bei der Argentumdämmerung besteht darin, so viele Informationen wie möglich zu sammeln, damit wir wissen, wann und wo Hilfe erforderlich ist.$b$bEs ist jetzt Wochen her, seit ich einen Späher losschickte, um die Aktivitäten in der Blackfathom-Tiefe auszuspähen. Argentumwache Thaelrid hat sich noch nicht zurückgemeldet.$b$bMeine anderen Späher sind mit dringenden Angelegenheiten beschäftigt.$b$bSucht und unterstützt Thaelrid für mich, $N.",objectives={"Sucht Argentumwache Thaelrid in der Blackfathom-Tiefe auf."}]])
R(1199,"Die Twilight fallen",[[description="Mit der Macht der uralten Rituale der chaotischen Alten Götter versuchen die Mitglieder der Twilight-Hammer, ihre dunklen Schutzherren zurückzuholen und Tod und Schrecken in der Welt zu verbreiten.$b$bWir glauben, dass die Twilight-Hammer sich mit den Naga verbündet haben und sich in der Blackfathom-Tiefe an den Küsten von Ashenvale zusammenrotten.$b$bWelch schändliche Pläne in den Tiefen des alten Tempels auch immer geschmiedet werden, wir müssen sie vereiteln.$b$bFührt Krieg gegen die Hammer und bringt Beweise Eurer Taten mit. Eure Bemühungen sollen reich belohnt werden.",objectives={"Bringt 10 Twilight-Anhänger zu Argentumwache Manados in Darnassus"}]])
R(1200,"Schurkerei in Blackfathom",[[description="Die Kraft hat mich verlassen. Ich benötige Eure Hilfe!$b$bDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.$b$bAku'Mai, die Dienerin der Alten Götter, erhob sich aus den Wassern.$b$bDie Kultisten der Twilight-Hammer haben sich mit den Naga verschworen, um diese Ländereien zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'Mai, um Macht zu erlangen.$b$bBitte, erschlagt Kelris und bringt Selgorm in Darnassus seinen Kopf, $N.",objectives={"Bringt den Kopf des Twilight-Lords Kelris zu Dämmerungsbehüter Selgorm in Darnassus."}]])
R(1201,"Theramores Spione",[[description="Die Horde und die Allianz wahren einen brüchigen Waffenstillstand. Beide Seiten liefern sich Scharmützel und heimliche Angriffe. Wir müssen dafür sorgen, dass die Horde stets die Oberhand behält!$B$BJetzt haben wir die Chance, genau das zu tun.$B$BSpitzel der Allianz haben Stellungen östlich des Dorfs Brackenwall bezogen. Sie spionieren das Dorf aus und melden unsere Bewegungen Theramore, was wir nicht dulden können.$B$BJagt die Spitzel und schaltet sie aus. Schickt eine deutliche Botschaft an ihre Vorgesetzten, dass wir die Anwesenheit ihrer Spione nicht dulden!",objectives={"Tötet 9 Spitzel von Theramore und kehrt dann zu Nazeer Bloodpike in Brackenwall zurück."}]])
R(1202,"Die Docks von Theramore",[[description="$n, zwei unserer Spione wurden ausgeschickt, um Dokumente von einem Schiff bei den Docks von Theramore zu stehlen. Sie bekamen die Papiere, wurden aber entdeckt und waren gezwungen, die Dokumente ins Meer zu werfen.$B$BSpäter konnte ein Spion entkommen, die Beute aber nicht bergen. Er informierte mich über sein Scheitern und jetzt gebe ich Euch die Aufgabe.$B$BDie Dokumente sind in einer Schließkiste irgendwo im Wasser unter den Docks von Theramore. Sucht diese Dokumente, $n, und bringt sie mir.",objectives={"Bringt die Dokumente des Kapitäns zu Nazeer Bloodpike in Brackenwall."}]])
R(1203,"Jarl braucht eine Klinge",[[description="Ich habe zu schneiden. Ich kann Euch nicht sagen, was ich schneiden werde, aber... Ich brauche eine Klinge. Eine ganz bestimmte Klinge...$B$BManche Leute sprechen von einem Mondstahlbreitschwert. Ich nenne es eine Schwingklinge.$B$BHelft Ihr mir? Vielleicht findet Ihr sie in der Stadt, vielleicht sprecht Ihr mit einem Schmied und er macht sie eigens.$B$BAber schlaft nicht noch darüber. Was ich schneide, das hält nicht ewig...",objectives={"Bringt ein Mondstahlbreitschwert zu Jarl in den Marschen von Dustwallow."}]])
R(1204,"Schlammpanzersuppe mit Käfern",[[description="Ich arbeite an einem Gericht namens \"Schlammpanzersuppe mit Käfern\". Die wichtigsten Zutaten fehlen mir leider noch immer... aber ich glaube nicht, dass ich einen Fußmarsch durch die Dustwallow-Marschen durchhalten könnte.$B$BNun denn, $N, könntet Ihr für mich auf die Jagd gehen? Als Erstes brauche ich die Zungen von Schlammpanzerschildkröten. Ihr findet die Schlammpanzer entlang der Küste, hauptsächlich im Bereich der Bucht.$B$BAber ich will nicht jede beliebige Zunge! Ich habe gehört, dass die Zungen von einigen Schlammpanzerschildkröten gespalten sind...$B$BMan sagt, diese gespaltenen Zungen hätten einen charakteristischen Geschmack, und den möchte ich in meinem Gericht...",objectives={"Bringt Morgan Stern in Theramore 8 gespaltene Schlammpanzerzungen."}]])
R(1205,"Schlammwühler",[[description="Schlammwühler ist ein uralter Krokilisk in den Marschen von Dustwallow. Und seine Zeit zum Sterben ist gekommen.$B$BAlte Knochen knirschen, wenn er seinen gewaltigen Leib durch den Sumpf schleppt, und auch wenn er sich noch mit der Kraft und dem Tempo der Jugend bewegt, martert sein alter Körper den großen innewohnenden Geist, ein Geist, dessen Flamme nicht erlischt.$B$BHeutzutage jedoch leidet er unablässig qualvolle Schmerzen. Ihr müsst das Leben dieser edlen Kreatur beenden, $N. Ihr müsst Schlammwühler Frieden geben.",objectives={"Bringt Schlammwühlers Zahn zu Melor in Thunder Bluff."}]])
R(1206,"Jarl braucht Augen",[[description="Augensaft ist ein guter Saft zum Trinken. Leider haben die meisten Tierwesen nur zwei Augen.$B$BAber Spinnen haben eine Menge Augen. Jede Menge. Und Graunebelaugensaft ist lecker. Samtig und salzig! Unzerplatzte Spinnenaugen... Ich schmecke sie schon förmlich.$B$BGraunebelspinnen leben westlich von hier in den Graunebelhöhlen. Glaubt Ihr, die Spinnen wurden nach der Höhle benannt... oder ist es umgekehrt?",objectives={"Bringt 40 unzerplatzte Graunebelaugen zu \"Sumpfauge\" Jarl im Swamplight-Anwesen."}]])
R(1218,"Feine Gewürze",[[description="Ich koche gern. Leckere Sumpfküche. Frittierte grüne Froschschenkel und dergleichen.$B$BUnd zum Kochen brauch ich Gewürze. Feine Gewürze. Dann mache ich einen Eintopf und topfe ihn ein und schlabber ihn aus und geb Euch auch was ab.$B$BMögt Ihr Eintopf?",objectives={"Bringt 3 feine Gewürze zu \"Sumpfauge\" Jarl in den Dustwallow-Marschen."}]])
R(1219,"Der Orc-Bericht",[[description="Beim Durchsuchen der lockeren Erde wird die abgetrennte Hand eines Orcs gefunden. Die Hand hält eine aus Knochen geschnitzte Röhre umklammert. Und in der Röhre befindet sich ein fleckiges Pergament.$B$BDas Pergament ist in der Sprache der Orcs verfasst... und sieht wichtig aus.",objectives={"Bringt den Bericht des Spions zu einem Lieutenant in Theramore."}]])
R(1220,"Captain Mumm",[[description="Captain Mumm sollte den Orcbericht sehen, den Ihr gefunden habt, $N. Er kennt die Sprache der Orcs besser als die meisten. Und er sollte wissen, dass sich Spione der Horde bei Theramore aufhalten!$B$BDer Captain befindet sich in der Kaserne auf der nordöstlichen Seite der Insel Theramore.",objectives={"Bringt den Bericht des Spions zu Captain Garran Mumm."}]])
R(1221,"Blaulaubknollen",[[description="Blaulaubknollen gelten auf der ganzen Welt als Delikatesse! Aber sie sind rar, sehr rar. Man findet sie nur hier im Brachland, tief in der Erde des Krals von Razorfen.$B$BUnd selbst dann sind sie fast nicht zu finden, wenn man nicht weiß, wo man suchen muss! Darum habe ich diese Schnüffelnasenziesel abgerichtet, damit sie sie für mich aufstöbern. Sie haben unheimlich empfindliche Nasen und riechen eine Knolle aus fünfzig Schritt Entfernung.$B$BEs wird nicht einfach sein, aber wenn Ihr mir ein paar Knollen bringt, bezahle ich Euch gut dafür.",objectives={"Schnappt Euch eine Kiste mit Löchern.$BSchnappt Euch einen Schnüffelnasenleitstecken.$BSchnappt Euch das Handbuch für Schnüffelnasenbesitzer und lest es.$B$BBenutzt im Kral von Razorfen die Kiste mit Löchern, um ein Schnüffelnasenziesel zu beschwören, und benutzt den Leitstecken bei dem Ziesel, damit es nach Knollen sucht.$B$BBringt 6 Blaulaubknollen, den Schnüffelnasenleitstecken und die Kiste mit Löchern zu Mebok Mizzyrix in Ratchet."}]])
R(1222,"Stinkis Flucht",[[description="Klasse, endlich etwas, das mich nicht essen möchte!$B$BIch brauche Hilfe mit den Tierwesen hier, und Ihr kommt gerade recht, $gJungchen:Lady;.$B$BDer Koch Morgan Stern arbeitet an einem neuen Rezept und hat mich hierher geschickt, um Sumpfbohnenblätter zu sammeln. Ich glaube, er findet sie lecker.$B$BWie auch immer, während ich nach einer Sumpfbohnenpflanze suchte ... Wurde ich umzingelt! Könnt Ihr mir hier raus helfen und auf mich aufpassen, während ich nach den Sumpfbohnen suche?",objectives={"Begleitet \"Stinki\" Ignatz und sprecht dann mit Morgan Stern in Theramore."}]])
R(1238,"Der verlorene Bericht",[[description="Beim Durchsuchen der lockeren Erde wird die abgetrennte Hand eines Orcs gefunden. Die Hand hält eine aus Knochen geschnitzte Röhre umklammert. Und in der Röhre befindet sich ein fleckiges Pergament.$B$BDas Pergament ist ein Bericht von einem Orc, der die Stadt Theramore über Wochen ausspionierte.$B$BAls Ihr das Pergament überflogen habt, ist klar, dass es zum Orc-Spionagemeister in Brackenwall gebracht werden muss.",objectives={"Bringt den Bericht des Spions zu Nazeer Bloodpike in Brackenwall."}]])
R(1239,"Der abgetrennte Kopf",[[description="Ausgiebiges Graben fördert den Kopf eines männlichen Orcs zu Tage, der am Hals abgesägt worden war. Seine Lippen sind zu einer höhnischen Grimasse verzerrt, seine dunklen Augen blicken trotzig.",objectives={"Bringt den Kopf des aufsässigen Orcs zu Nazeer Bloodpike in Brackenwall."}]])
R(1240,"Der Troll-Hexendoktor",[[description="Wir müssen die Umstände von Margs Tod erfahren! Und das können wir nur, $N, durch die Hexenmagie der Trolle.$B$BBringt Margs Kopf zu Kin'weelay im Schlingendorntal im Basislager von Grom'gol.$B$BKin'weelay ist der mächtigste Hexendoktor der Darkspeartrolle. Wenn jemand mit Marg Nighteyes Geist sprechen kann, dann er.",objectives={"Bringt den Kopf des aufsässigen Orcs zu Kin'weelay im Schlingendorntal im Basislager von Grom'gol."}]])
R(1241,"Der vermisste Diplomat",[[description="Kürzlich wurde ein Diplomat nach Theramore geschickt, um sich mit Jaina Proudmoore zu treffen. Dieser Diplomat kam nie an.$B$BIch glaube, die Defias sind in diese Verschwörung verwickelt, weiß aber nicht, wie. Das Verschwinden des Diplomaten wurde noch nicht publik, aber lange kann das nicht mehr so bleiben.$B$BAgenten des Königs durchkämmen die Stadt bereits nach Hinweisen, aber ich habe eigene Verbindungsleute, die ich gern einschalten würde.$B$BIm Tal der Helden lebt ein alter Freund von mir namens Jorgen. Sucht ihn, gebt ihm diese Notiz und folgt seinen Anweisungen.",objectives={"Sucht Jorgen in der Stadt Stormwind."}]])
R(1242,"Der vermisste Diplomat",[[description="Bringt diese Notiz zu Elling Trias. Sagt sonst nichts zu ihm. Seid nur höflich und wartet auf seine Antwort. Und keine Bange, er wird antworten.$B$BIch sage Euch das nur noch einmal, $n: nehmt diese Sache ernst und haltet die Klappe.$B$BIhr findet Trias in seinem Käseladen, Trias' Käse, im Handelsdistrikt. Viel Glück.",objectives={"Bringt Jorgens versiegelte Notiz zu Elling Trias in der Stadt Stormwind."}]])
R(1243,"Der vermisste Diplomat",[[description="Jorgen, alter Pickel! Aha, so soll es also sein, hm?$B$BNa gut, damit kann ich leben. Ich hoffe, er findet den Wirbelnden Nether umso früher!$B$BSo wird es ablaufen, $n. Ich werde meine Verbindungsleute hier kontaktieren, aber Ihr werdet den Großteil der Beinarbeit erledigen, damit ich ein wenig spare.$B$BGeht nach Dunkelhain im Dämmerwald und sucht Behüter Backus - er patrouilliert meist auf der Nordstraße vor der Stadt. Sagt ihm nur, dass Ihr für mich die Aktivitäten der Defias untersucht, dann wird er Euch mit allen verfügbaren Informationen weiterhelfen.",objectives={"Gebt Behüter Backus im Dämmerwald die versiegelte Notiz."}]])
R(1244,"Der vermisste Diplomat",[[description="Defiasaktivität? Es gibt immer etwas Aktivität; selbst wenn sie unter sich bleiben, betrachten wir sie als Bedrohung.$B$BAber jetzt, wo ich darüber nachdenke, kam es jüngst zu einer seltsamen Beobachtung. Es muss so zwei Wochen her sein, da hatten sich einige ihrer Agenten in Addles Siedlung versammelt. Dem Bericht glaubte ich zu entnehmen, dass etwas Großes vor sich ging.$B$BWarum seht Ihr da nicht zuerst nach und bringt mir alles, was Ihr findet?$B$BDer Bauernhof liegt südlich der Straße von Westfall direkt am Rand des Dämmerwalds.",objectives={"Sucht die Liste der Defias und kehrt zu Behüter Backus im Dämmerwald zurück."}]])
R(1245,"Der vermisste Diplomat",[[description="Boah, das sieht zu komplex aus, um Euch nur auf eine falsche Fährte zu locken. Ich sollte das nicht einmal ansehen. Sprecht mit Trias - er kann es bestimmt verstehen. Und lasst Euch durch NICHTS aufhalten. Dies ist größer als ich. Vielleicht sogar größer als er, aber wir werden sehen.$B$BUnd tut mir einen Gefallen, $N, sagt keinem, dass ich Euch geholfen habe. Wenn meine Vorgesetzten erfahren, dass ich davon wusste und sie nicht informiert habe, hängen sie mich wahrscheinlich.",objectives={"Bringt die Liste der Defias zu Elling Trias in Stormwind."}]])
R(1246,"Der vermisste Diplomat",[[description="Ja, jetzt, wo ich darüber nachdenke... Dashel... Dashel irgendwas... Wie war sein Name? FIST! Dashel Stonefist. In manchen Kreisen nennen sie ihn Fist - wahrscheinlich, weil er ein Raufbold ist.$B$BIhr könnt ihn normalerweise in der Altstadt finden - direkt mitten im Zentrum. Redet mit ihm. Wenn es sein muss, dann benutzt ein Schwert oder etwas Schweres und Stumpfes, um ihn zum Reden zu bringen. Und zögert nicht. Wenn er so tief drinsteckt, wie diese Papiere andeuten, wird er Euch freiwillig keine Informationen geben.",objectives={"Sprecht mit Dashel Stonefist in Stormwind."}]])
R(1247,"Der vermisste Diplomat",[[description="Ja, also... hm... Vielleicht weiß ich was über dieses Treffen in Addles Siedlung. Das war, glaube ich, vor ein paar Wochen. Ich hatte wirklich nichts damit zu tun. Meine Rolle war vorbei, als Plan A schief ging... verdammte Abenteurer.$B$BDer Kerl, den wir für Plan B hatten, kam aus Menethil; ein Typ namens Slim. Mehr weiß ich nicht über ihren Ersatzplan.",objectives={"Sprecht mit Elling Trias in Stormwind."}]])
R(1248,"Der vermisste Diplomat",[[description="Ein Verbindungsmann von mir verbringt seinen Ruhestand in der Hafenstadt Menethil im Sumpfland. Er sollte Euch auf Euer Wort hin helfen, wenn Ihr ihm sagt, dass Ihr für mich arbeitet. Sein Name ist Mikhail. Bevor er Stormwind vor ein paar Jahren verließ, erwähnte er, dass er Schankkellner werden wollte.$B$BSprecht mit ihm, sucht diesen Slim und findet heraus, ob es noch etwas über diesen entführten Diplomaten zu wissen gibt. Wir müssen herausfinden, wohin sie ihn gebracht haben, oder wenigstens, wer er ist. In der Liste steht nichts von ihren Plänen nach seiner Entführung.",objectives={"Sprecht mit Mikhail im Sumpfland."}]])
R(1249,"Der vermisste Diplomat",[[description="Ihr sagt, Elling hat Euch geschickt? Dann soll Euch meine Gastfreundschaft zehnfach zuteil werden. Wenn Ihr etwas braucht, fragt nur. Ich tue mein Bestes, Euch zu unterstützen.$B$BHmm, Slim sagt Ihr? Bei dem Namen klingelt nichts, aber ich werde nach ihm Ausschau halten.$B$BSchaut jetzt nicht hin, $N, aber der Herr dort am Ausgang sieht herüber. Er folgt unserer Unterhaltung etwas zu intensiv, wenn Ihr versteht, was ich meine. Ich an Eurer Stelle würde tun, was ich kann, um ihn zu schnappen, bevor er zur Tür flieht.",objectives={"Schnappt Tapoke Jahn bevor er entkommt und kehrt dann zu Mikhail in Menethil zurück."}]])
R(1250,"Der vermisste Diplomat",[[description="Die Defias zahlten mir nicht genug, um für diese Sache zu sterben. Sie entführten den König. Ja, den König von Stormwind, keinen kleinen Diplomaten. Er war auf dem Weg nach Theramore, um sich mit Jaina Proudmoore zu treffen - offenbar eine große Sache und streng geheim. Aber es sind nicht nur die Defias darin verwickelt. Sie arbeiten mit jemandem zusammen. Ich glaube, sie wussten, dass das ihre Kräfte übersteigt.$B$BMeine Aufgabe war es, ihren Mann an Bord des königlichen Schiffes zu bringen, als es im Hafen lag. Der Typ hieß Hendel. Mehr weiß ich nicht. Ich schwöre es!",objectives={"Sprecht mit Mikhail im Sumpfland."}]])
R(1251,"Der Schwarze Schild",[[description="Ein Eisenschild, vom Feuer geschwärzt, das in dem Gasthaus wütete, ist an dem verfallenen Kamin befestigt, einer der wenigen erhaltenen Teile des Gebäudes, das einmal das Gasthaus Zur süßen Ruh war.$b$bDer Schild lässt sich von den Mauersteinen des Kamins ablösen.",objectives={"Bringt den geschwärzten Eisenschild zu Krog in Brackenwall."}]])
R(1252,"Lieutenant Paval Reethe",[[description="Unter dem Geröll sticht Euch ein Funkeln ins Auge. Kaum sind Schmutz und Asche von dem Objekt gewischt, kommt das Emblem eines goldenen Ankers auf einer weißen Emailleoberfläche zum Vorschein: das Zeichen von Theramore.$b$bUnter dem Anker ist der Name \"Lieutenant Paval Reethe\" eingeprägt.",objectives={"Bringt Reethes Abzeichen zu Captain Garran Mumm in Theramore."}]])
R(1253,"Der Schwarze Schild",[[description="Ein Eisenschild, vom Feuer geschwärzt, das in dem Gasthaus wütete, ist an dem verfallenen Kamin befestigt, einer der wenigen erhaltenen Teile des Gebäudes, das einmal das Gasthaus Zur süßen Ruh war.$b$bDer Schild lässt sich von den Mauersteinen des Kamins ablösen.",objectives={"Bringt den geschwärzten Eisenschild zu Captain Garran Mumm in Theramore."}]])
R(1258,"...und Käfer",[[description="Eine weitere Komponente meines neuen Rezepts ist das gepanzerte Bein eines Riesenkrebses. Und die Krebse, die sie in Dustwallow haben - Matschpanzer nennen sie sie -, taugen einfach nichts! Ich fürchte, die einzigen akzeptablen Krebse leben in den Sümpfen des Elends.$B$BDie Schale des Krebsbeins ist das wichtigste Element der Präsentation des Gerichts, daher brauche ich makellose, unverletzte Beine. Ein ausgewachsener Krebs hat möglicherweise nur ein oder zwei Beine, die in Frage kommen, aber ich brauche viel mehr für mein Gericht.$B$BAlso, $N ... seid Ihr bereit für eine Reise?",objectives={"Bringt 12 makellose Kriecherbeine zu Morgan Stern in Theramore."}]])
R(1259,"Lieutenant Paval Reethe",[[description="Ich kenne den Namen Lieutenant Paval Reethe nicht. Am besten erkundigt Ihr Euch bei Adjudant Tesoran. Er hat alle Aufzeichnungen über die Wachen von Theramore, vom Personal bis hin zur Ausrüstung.$b$bEr sollte Euch nach einem Blick in seine Bücher sagen können, wer dieser Reethe ist.",objectives={"Findet bei Adjudant Tesoran in Theramore mehr über Reethe heraus."}]])
R(1260,"Morgan Stern",[[description="Ich entwickle ein neues Menü für das Restaurant. Es soll aus regionalen Gerichten mit einem Hauch von \"Bayou\" bestehen. Ich glaube, meine Kunden im Blauen Eremiten werden es lieben!$B$BIch schickte meinen Neffen Morgan nach Theramore, einer Stadt am Rand der Dustwallow-Marschen. Er sammelt die Rezepte der Einheimischen und ich muss wissen, was er bisher gefunden hat.$B$BDie Reise nach Theramore ist lang. Zu lang für mich. Aber ich wette, ein $C wie Ihr einer seid, nutzt jede Chance für eine Reise, ja?",objectives={"Sprecht mit Morgan Stern in Theramore."}]])
R(1261,"Marg spricht",[[description="Verfluchter Matschpanzer! Man kann Marg nicht töten! Ah, aber ich bin tot. Also muss er mich getötet haben...$B$BAber meine Mission! Meine Mission! Ihr, $n, müsst sie beenden.$B$BIn der Nähe von Theramore sah ich eine Gruppe Soldaten der Allianz am Ufer kampieren. Ein Soldat trug einen Anhänger... einen Anhänger mit mehr Edelsteinen, als ihn sich ein Soldat leisten könnte!$B$BIn jener Nacht schlich ich in ihr Lager und stahl den Anhänger, aber nach meiner Rückkehr zum Stützpunkt tötete mich ein Matschpanzerkrebsmann!$B$B$n, Ihr müsst diesen Matschpanzer finden und den Anhänger retten!",objectives={"Bringt den juwelenbesetzten Anhänger zu Nazeer in Brackenwall."}]])
R(1262,"Bei Zor melden",[[description="Wie seltsam, dass sich der Anhänger, den Marg stahl, in den Händen eines gemeinen Soldaten befand. Vielleicht hatte sich sein Besitzer verkleidet, oder die Soldaten selbst hatten ihn gestohlen!$B$BWas auch immer, dies ist der Anhänger eines Adligen und wir müssen seinen wahren Besitzer finden, wenn wir das Rätsel lösen wollen.$B$BBringt den Anhänger zu Zor Lonetree in Orgrimmar. Er ist mit der Politik der Allianz vertraut und wird wissen, ob dieser Anhänger etwas mit der Geschichte der Adligen von Stormwind zu tun hat.",objectives={"Bringt den Edelstein-Anhänger zu Zor Lonetree in Orgrimmar."}]])
R(1263,"The Burning Inn <CHANGE TO GOSSIP>")
R(1264,"Der vermisste Diplomat",[[description="Am Anfang jedes Monats werden die Marines von Kul Tiras bezahlt und verlassen Theramore meist mit anderen Zielen. Viele kommen hierher, um Frauen aufzureißen, zu zechen und ihren Spaß zu haben. Eine dieser Gruppen betrachte ich als Stammgäste der Taverne, und ich glaube, dieser Hendel ist dabei.$B$BKommandant Samaul in Theramore könnte Euch helfen, ihn zu finden, wenn Hendel noch hier stationiert ist. Er ist Proudmoore treu ergeben, aber wenn Ihr Ellings Namen erwähnt, dürfte er Euch helfen... diskret.",objectives={"Sucht Kommandant Samaul in den Marschen von Dustwallow."}]])
R(1265,"Der vermisste Diplomat",[[description="Hendel? Ja, ich kenne den Mann. Aber wozu braucht Ihr einen meiner Soldaten?$B$BHat Elling Euch geschickt, ihn zu finden? Hmm, das gefällt mir ganz und gar nicht. Elling hätte Euch nicht zuerst zu mir geschickt, wenn Euer Anliegen nicht beunruhigend wäre. Ich verstehe, wenn Ihr mir nicht sagen könnt, worum es geht, aber denkt daran: Ich muss dieses Land beschützen. Wenn Ihr vorhabt, die Ruhe zu stören, solltet Ihr mich so viel wie möglich wissen lassen.$B$BIch glaube, Hendel war im ersten Turm außerhalb von Theramore stationiert. Seid vorsichtig.",objectives={"Sucht die Späherwacht nach Spuren des Gefreiten Hendel ab."}]])
R(1266,"Der vermisste Diplomat",[[description="Der Gefreite Hendel hält sich westlich von hier auf. Im Augenblick ist er auf Wache und beschützt einige von Theramores Spitzeln, während sie ausruhen. Sie behalten Brackenwall, den Stützpunkt der Horde, im Auge und suchen nach allem, das unsere Grenzen bedrohen könnte.$B$BIhr müsstet ihn problemlos finden können; sucht einfach nach Zelten am Straßenrand.$B$BIch muss mich um andere Dinge kümmern, stoße aber bestimmt bald zu Euch. Ihr könnt mich immer im Turm von Lady Proudmoore in Theramore finden, falls Ihr Probleme habt.",objectives={"Sucht den Gefreiten Hendel in den Marschen von Dustwallow."}]])
R(1267,"Der vermisste Diplomat",[[objectives={"Sprecht mit Jaina Proudmore im Dustwallowsumpf."}]])
R(1268,"Verdächtige Hufabdrücke",[[description="Reihen von Hufspuren führen von den noch rauchenden Überresten des Gasthauses Zur süßen Ruh weg. Wenigstens einige Abdrücke sind klar erkennbar, weitere Reihen sind im weichen Schlamm des Sumpfs kaum zu sehen.",objectives={"Berichtet Krog in Brackenwall von den verdächtigen Abdrücken beim Gasthaus Zur süßen Ruh."}]])
R(1269,"Lieutenant Paval Reethe",[[description="Unter dem Geröll sticht Euch ein Funkeln ins Auge. Kaum sind Schmutz und Asche von dem Objekt gewischt, kommt das Emblem eines goldenen Ankers auf einer weißen Emailleoberfläche zum Vorschein: das Zeichen von Theramore.$b$bUnter dem Anker ist der Name \"Lieutenant Paval Reethe\" eingeprägt.",objectives={"Bringt Reethes Abzeichen zu Krog in Brackenwall."}]])
R(1270,"Stinkis Flucht",[[description="Klasse, endlich etwas, das mich nicht essen will!!!$B$BIch brauche Hilfe mit den Tierwesen hier, und Ihr kommt gerade recht, $gJungchen:Mädel;.$B$BEin Goblin aus Ratchet namens Mebok Mizzyrix braucht ein paar Sumpfbohnenblätter für einen Trank oder so... Mir ist ganz ehrlich einerlei, warum - er hat gut bezahlt und ich kenne diesen Sumpf, also bin ich hier.$B$BZu dumm, dass ich umzingelt wurde, bevor ich die Sumpfbohnen fand! Könnt Ihr mir hier raushelfen und auf mich aufpassen, während ich nach Meboks Pflanze suche?",objectives={"Begleitet \"Stinki\" Ignatz und sprecht dann mit Mebok Mizzyrix in Ratchet."}]])
R(1271,"Festmahl im Blauen Eremiten")
R(1273,"Befragt Reethe",[[description="Es hat lange gedauert, aber ich fand Reethe. Für einen Menschen hatte er sich gut versteckt.$b$bOgron hatte Angst, nach der langen Zeit im Sumpf könnte er verrückt sein. Ihr kommt mit mir, denn wir brauchen Antworten von ihm.",objectives={"Geht mit Ogron und sprecht mit Reethe, dann kehrt zu Krog in Brackenwall zurück."}]])
R(1274,"Der vermisste Diplomat",[[description="Pardon, $gwerter Herr:holde Dame;. Bischof DeLavey bat mich, Abenteurer zu suchen, die ihm in einer delikaten Angelegenheit helfen könnten.$B$BWenn Ihr so gut sein könntet, heimlich zur Burg Stormwind zu reiten und mit ihm zu sprechen, sobald es Euch genehm ist - er wäre Euch sicherlich für Eure Hilfe dankbar. Und nochmals, bitte seid diskret. Es ist eine wichtige Angelegenheit.",objectives={"Sucht Bischof DeLavey in der Burg Stormwind."}]])
R(1275,"Erforschung der Verderbnis",[[description="Törichte Blutelfen spielen mit Dämonenmagie. Wurden sie nicht Zeugen, was mit den Naga und den Satyrn von Kalimdor geschehen ist?$b$bIch fürchte, die Blutelfen werden auf ähnliche Weise deformiert. Azeroth darf kein weiteres Volk abscheulicher Monster hervorbringen.$b$bIch möchte die Hirnstämme der Satyrn und Naga untersuchen, damit ich daraus folgern kann, welches Schicksal die Elfen erwartet. In der Blackfathom-Tiefe, an der Küste von Ashenvale, werdet Ihr sowohl Satyrn als auch Naga finden.$b$bEs ist eine lange Reise, $N.",objectives={"Gershala Nightwhisper in Auberdine möchte 8 verderbte Hirnstämme."}]])
R(1276,"Der Schwarze Schild",[[description="Ah, jetzt erinnere ich mich! Mosarn ist ein angesehener Schmied in Thunder Bluff. Ich wusste, ich habe den Namen schon einmal gehört.$b$bAls Dank belohnte mich der irdene Ring mit einem von Mosarn hergestellten Satz Rüstungen. Sehr gute Arbeit.$b$bVielleicht kann er Euch mehr über den Schild sagen, den er anfertigte.$b$bEs ist nicht viel, aber da wir aus Reethe nichts Nützliches herausbekamen, haben wir nichts anderes.",objectives={"Bringt den geschwärzten Eisenschild zu Mosarn in Thunder Bluff."}]])
R(1277,"<nyi> <TXT> The Centaur Hoofprints",[[description="Kagoro has revealed that the centaur hoofprints belong to some chumps in Mauradon.",objectives={"Beat down."}]])
R(1278,"<nyi> <TXT> The Grim Totem Clan")
R(1279,"<nyi> <TXT>The Centaur Hoofprints",[[description="Finish one of the three."]])
R(1280,"<nyi> <TXT>The Centaur Hoofprints")
R(1281,"Jim's Song <CHANGE TO GOSSIP>")
R(1282,"Sie nennen ihn den lächelnden Jim",[[description="Ich kann nicht anders, der alte Jim da tut mir Leid. Er war nicht immer so. Hatte eine Zeitlang ein Gasthaus im Sumpf, wunderbares Lokal.$b$bHört zu, ich will wirklich nicht darüber sprechen. Besprecht es mit Captain Mumm, wenn es sein muss.",objectives={"Sprecht mit Captain Garran Mumm in Theramore."}]])
R(1283,"Fire at the Shady Rest <CHANGE TO GOSSIP>")
R(1284,"Verdächtige Hufabdrücke",[[description="Reihen von Hufspuren führen von den noch rauchenden Überresten des Gasthauses Zur süßen Ruh weg. Wenigstens einige Abdrücke sind klar erkennbar, weitere Reihen sind im weichen Schlamm des Sumpfs kaum zu sehen.",objectives={"Berichtet Captain Garran Mumm in Theramore von den verdächtigen Abdrücken beim Gasthaus Zur süßen Ruh."}]])
R(1285,"Daelins Männer",[[description="Reddon... Redpath... Oh, da haben wir ihn! Lieutenant Paval Reethe.$b$bTrat den Wachen von Theramore zusammen mit den meisten Rekruten bei, die mit Lady Proudmoore über das Meer kamen. Meldete sich mit sechzehn Jahren zu den Marines in Kul Tiras. Herausragende Dienste, Beförderungen...$b$bIst als vermisst eingetragen.",objectives={"Kehrt mit den Informationen über Reethe zu Captain Garran Mumm in Theramore zurück."}]])
R(1286,"Die Deserteure",[[description="Es war ein ständiger Kampf, in den Marschen präsent zu bleiben, aber durch die Kraft unserer Entschlossenheit konnten wir mehrere Wachtürme in diesem Gebiet zur Verteidigung halten.$b$bDie aktuellsten Informationen und Späherberichte, die ich bekam, deuten darauf hin, dass eine Gruppe Deserteure sich in unserem alten Turm bei der verlassenen Wacht, südöstlich des Gasthauses, eingenistet hat.$b$bAnführer der Deserteure ist ein Mann namens Jacken. Seht zu, ob Ihr Informationen über ihn bekommt.$b$bSeid gewarnt, $N. Er könnte sich als harte Nuss erweisen.",objectives={"Sammelt Informationen über Reethe von Balos Jacken und den Deserteuren in den Marschen von Dustwallow."}]])
R(1287,"Die Deserteure",[[description="Reethe? Dieser Feigling?$b$bWir warfen ihn aus dem Lager hinaus, weil er dauernd die Vorräte der Oger in Brackenwall plündern wollte. So viele sind wir nicht, dass wir es mit diesen hirnlosen Schlägern aufnehmen könnten.$b$bEr hat das Fass zum Überlaufen gebracht, daher haben wir ihn sich selbst überlassen.$b$bAlso ich hab Euch geholfen ... Warum helft Ihr jetzt nicht uns und vergesst, dass Ihr uns gefunden habt?",objectives={"Sprecht mit Captain Garran Mumm in Theramore über Reethe."}]])
R(1288,"Mumms Bericht",[[description="Ihr habt gute Arbeit geleistet, $N, die Beste, die ich je von einem Amateur sah.$b$bLady Proudmoore bat mich, sie über diese delikate Situation auf dem Laufenden zu halten, aber ich habe eine Weile nicht mit ihr gesprochen.$b$bIch wollte ihr meinen Bericht später bringen, aber es scheint mir passender, wenn Ihr mit ihr darüber sprecht. Ihr könnt ihre Fragen wahrscheinlich besser beantworten als ich.",objectives={"Bringt Mumms Bericht zu Lady Jaina Proudmoore in Theramore."}]])
R(1289,"<nyi> Mumms Bericht",[[description="Dem Bericht von Hauptmann Mumm entnehme ich, dass Ihr eine gro?e Hilfe bei den Ermittlungen gewesen seid, und dafür danke ich Euch.$B$BIch bin beruhigt, da ich wei?, dass die Angelegenheit in so tüchtigen H?nden ruht. Wenn es Euch Recht ist, würde ich Euch bitten, zu Hauptmann Mumm zurückzukehren und mit ihm zusammen dem R?tsel auf den Grund zu gehen.",objectives={"Kehrt zu Hauptmann Garran Mumm in Theramore zurück."}]])
R(1293,"<nyi> <TXT> Centaur Hoofprints")
R(1294,"<nyi> <TXT>Centaur Sympathies")
R(1295,"<nyi> <TXT> Course of Action")
R(1296,"<nyi> <TXT> Course of Action")
R(1297,"<nyi> <TXT> Course of Action")
R(1299,"<nyi> <TXT> Thrall's Dirty Work")
R(1300,"<nyi> <TXT> Lorn Grim Totem")
R(1301,"James Hyal",[[description="Bevor ich hier im Blauen Eremiten arbeitete, wurde ich von einem der besten Küchenchefs und Gastwirte ausgebildet, die ich kenne. Sein Name war James Hyal. Alles, was ich besitze und im Leben erreicht habe, verdanke ich ihm.$b$bIch frage mich, was er wohl so treibt... Sein Bruder Vincent und er wollten in einer Taverne im Hafen von Menethil arbeiten, aber ich habe lange nichts von ihm gehört.$b$bWenn Ihr jemals in diese Gegend kommen solltet, könntet Ihr ihm dann Grüße von mir bestellen?",objectives={"Sprecht mit Vincent Hyal im Hafen von Menethil."}]])
R(1302,"James Hyal",[[description="Mein Bruder James fuhr mit Lady Proudmoore über das Meer. Als Letztes hörte ich, dass die Kämpfe dort drüben beigelegt waren und James irgendwo auf dem Kontinent ein Gasthaus eröffnete. Wo immer er sein mag, ich bin sicher, seine Geschäfte blühen. Er war ein verdammt guter Koch.$b$bAber ich habe eine Weile nichts mehr von ihm gehört - zu sehr mit seinem Gasthaus beschäftigt, denke ich. Der Amtmann in Theramore könnte Euch vielleicht zu ihm führen.",objectives={"Sprecht mit Amtmann Lendry in Theramore."}]])
R(1318,"Die offene Rechnung der Gordok",[[description="Nun Ihr de' König sein, vielleicht Ihr kriegen zurück wertvolles Artefakt der Gordok von gruseligen Elf, der sich selbst nennen Prinz! König vor Euch hat versagt, so wie alle Könige seit Tortheldrin - de' gruselige Elf - es gestohlen hat, von damaligen Gordokkönig!$B$BArtefakt heißen Stulpen der Gordokmacht. Alte Zeit Geschichten sagen, nur wahre König de' Gordok kann sie zurückholen. Alte Zeit Geschichten sagen auch, der gruselige Elf ist immer noch hier - Ihr finden es und es werden Eure mächtigen Stulpen, für immer! Yar, ich zeigen!",objectives={"Findet die Stulpen der Gordokmacht und bringt sie zu Hauptmann Krombruch in Düsterbruch.$B$BKrombruch zufolge sagen die \"Alte Zeit Geschichten\", dass Tortheldrin - ein \"gruseliger\" Elf, der sich selbst als Prinz bezeichnet- sie einem der Gordokkönige gestohlen hat."}]])
R(1319,"Der Schwarze Schild",[[description="Ich kann Euch leider nicht weiterhelfen, $n, schicke Euch aber zu jemandem, der es kann. Caz Twosprocket, einer unserer besten Schmiede, arbeitet in der Schmiede.$b$bBringt ihm den Schild und hört Euch an, was er zu sagen hat.",objectives={"Zeigt den geschwärzten Eisenschild Caz Twosprocket in Theramore."}]])
R(1320,"Der Schwarze Schild",[[description="Ah, das hätte ich fast übersehen... Der Ledergurt an der Rückseite muss verbrannt sein, aber er war offenbar für eine große Person gemacht. Ich schätze, für einen Tauren.$b$bMehr kann ich Euch nicht sagen. Sagt Captain Mumm, es tut mir Leid, dass ich nicht mehr helfen konnte.",objectives={"Sprecht mit Captain Garran Mumm in Theramore."}]])
R(1321,"Der Schwarze Schild",[[description="Hmm... Ich sehe nichts Ungewöhnliches an diesem Schild. Do'gol, der Schmied, sollte ihn sich ansehen. Vielleicht kann er uns mehr sagen, aber große Hoffnungen würde ich mir nicht machen...",objectives={"Zeigt den geschwärzten Eisenschild Do'gol in Brackenwall."}]])
R(1322,"Der Schwarze Schild",[[description="Hmmm, hier am Rand des Schildes steht etwas geschrieben, aber durch die Brandspuren kann man es kaum lesen.$b$bIch brauche Säure, um ihn zu reinigen. Das Gift der Dunkelzahnspinnen im Sumpf würde helfen. Bringt mir ihre Giftsäcke und ich reinige diesen Schild.",objectives={"Bringt 6 säurehaltige Giftbeutel zu Do'gol in Brackenwall."}]])
R(1323,"Der Schwarze Schild",[[description="Oh, ich glaube, ich habe zu viel Säure auf den Schild geschüttet. Lasst mich ein wenig rubbeln...$b$bHm, schwer zu lesen, sieht aber wie der Name Mosarn aus. Nie von ihm gehört. Vielleicht weiß Krog etwas. Krog kennt viele Leute.",objectives={"Sprecht mit Krog in Brackenwall."}]])
R(1324,"Der vermisste Diplomat",[[description="Was?! Ihr kommt hierher und werft mir vor, ich mache mit den Defias gemeinsame Sache und glaubt, ich höre mir diese Beleidigungen an? Etwas sagt mir, dass Ihr das schon lange verdient habt.",objectives={"Besiegt den Gefreiten Hendel in den Marschen von Dustwallow."}]])
R(1338,"Stormpikes Bestellung",[[description="Es gibt einen Rüstungsschmied bei den Zwergen, dessen Arbeit ich sehr bewundere. Sein Name ist Furen Longbeard und seine Fertigkeit unübertroffen. Ich brauche einen neuen Schild und muss einen von ihm haben!$B$BDas Problem ist... Furen lebt weit im Süden im Zwergendistrikt von Stormwind. Im Menschenland! Ich kann mir nicht vorstellen, warum er dort lebt, so weit weg von Ironforge. Die Menschen müssen ihn fürstlich bezahlen, damit er dort bleibt!$B$BWenn Ihr reisen wollt und nichts gegen das Geldverdienen habt, würdet Ihr Furen dann meine Bitte nach einem Schild überbringen?",objectives={"Bringt Stormpikes Bitte zu Furen Longbeard in Stormwind."}]])
R(1339,"Gebirgsjäger Stormpikes Aufgabe",[[description="Ich hörte, Gebirgsjäger Stormpike sucht nach einem Läufer. Jemand, der eine Reise für ihn unternimmt. Wie wäre es? Seid Ihr ein $R, der für den Job geeignet ist?$B$BWenn ja, findet Ihr Stormpike auf der Spitze des nördlichen Wachturms.",objectives={"Sprecht mit Gebirgsjäger Stormpike."}]])
R(1358,"Probe für Helbrim",[[description="Ein Kollege in Kalimdor, Apotheker Helbrim, untersucht die Auswirkungen von Lordaerons Toxinen auf die Wildtiere von Kalimdor. Er wäre an einer Probe der Wolfherzen interessiert, die Renferrel mir geschickt hat.$B$BHelbrim lebt im Brachland in einem Dorf, das Crossroads heißt. Um ihn zu erreichen, müsst Ihr per Zeppelin zur Orc-Hauptstadt Orgrimmar reisen und dann zu Fuß Richtung Süden nach Durotar. Geht durch das Brachland nach Westen und Ihr erreicht bald den Ort Crossroads.",objectives={"Bringt die Wolfherzprobe zu Apotheker Helbrim ins Brachland."}]])
R(1359,"Zinges Lieferung",[[description="Die Wolfherzen, die Ihr beschafft habt, verfügen über ein Merkmal, das es in ähnlichen Proben nicht gibt. Sie verfügen über eine Giftigkeit, die für genau die Wölfe tödlich sein müsste, in denen die Herzen schlagen!$B$BEs ist unglaublich und wir müssen das weiter untersuchen. Ich habe einige Proben der gewonnenen Herzen aufbewahrt. Bringt sie zu meiner Kollegin, Apothekerin Zinge. Ihr findet sie in unserem Hauptquartier in Undercity.",objectives={"Bringt die Wolfherzproben zu Apothekerin Zinge nach Undercity."}]])
R(1360,"Wiederbeschaffte Schätze",[[description="Ich hatte selbst eine gute Arbeitsstelle als Buddler an der Uldaman-Ausgrabungsstätte im Ödland... das heißt, bis diese verfluchten Troggs auftauchten. Ich konnte gerade noch mit heiler Haut entkommen, das war alles. In dem Chaos habe ich meinen wertvollsten Besitz zurückgelassen. Natürlich ist er in meiner Truhe sicher vor den Troggs, aber die befindet sich mitten unter ihnen.$B$BIch wäre in Eurer Schuld, sowohl in Ehre als auch in Münze, wenn Ihr sie für mich besorgen könntet! Eine Truhe mit meinem Namen darauf befindet sich am Ende der Nördlichen Bankenhalle. Dorthin müsst Ihr gelangen.",objectives={"Holt Krom Stoutarms wertvollen Besitz aus seiner Truhe in der nördlichen Bankenhalle von Uldaman und bringt den Schatz zu ihm nach Ironforge."}]])
R(1361,"Regthar Deathgate",[[description="Ein Krieger der Horde, Regthar Deathgate, rekrutiert Agenten für einen Einsatz im Land Desolace. Sprecht mit ihm, wenn Ihr Euch freiwillig melden wollt. Er lebt im Brachland in einer Reihe von Bunkern westlich von Crossroads.$B$BUnd schärft Eure Waffen. Desolace ist ein vom Krieg zerrissener Ort.",objectives={"Sprecht mit Regthar Deathgate."}]])
R(1362,"Die Kolkar von Desolace",[[description="Die Kolkarzentauren leben in Desolace. Ihre Truppen sind in das Brachland vorgestoßen. Das ist bekannt. Agenten der Horde kümmern sich dort um sie.$B$BAber so lange die Zentauren in Desolace so stark sind, werden sie immer eine Bedrohung sein. Mit der Zeit schaffen wir uns diese Bedrohung vom Hals.$B$BSprecht mit Felgur Twocuts beim Geistwandlerposten in Desolace. Seine Aufgabe war es, Informationen über die Zentauren zu sammeln. Er weiß bestimmt, wie man am besten mit den Kolkar von Desolace fertig wird.",objectives={"Sprecht mit Felgur Twocuts beim Geistwandlerposten in Desolace."}]])
R(1363,"Mazens Befehl",[[description="Als Verwalter der Arbeit hier in der Bibliothek der Akademie der Arkanen Künste und Wissenschaften liegt es in meiner Verantwortung, dafür zu sorgen, dass alle magischen Folianten und Rollen stets erfasst sind. Wer weiß, was Schlimmes geschehen würde, fielen einige dieser verzauberten Texte in die falschen Hände?$b$bDabei fällt mir ein ... mein Assistent Dellis machte letzte Woche einen schrecklichen Fehler. In der Bibliothek ist er recht tüchtig, aber inkompetent, wenn er die Tore von Stormwind hinter sich lässt. Seid ein Held und helft dem alten Dellis, ja?",objectives={"Sprecht mit Akolyt Dellis in Stormwind."}]])
R(1364,"Mazens Befehl",[[description="Meister Mazens Anweisungen waren ganz klar: Bringt einen sehr wichtigen Essay zu Behüter Mahar Ba in der Burg Nethergarde.$b$bAber ich bin noch nie in den Verwüsteten Landen gewesen. Die Reise war beängstigend!$b$bAls ich an die Sümpfe des Elends kam, bog ich falsch ab und war plötzlich von grässlichen pflanzenartigen Sumpfwesen umzingelt. Sie schienen mich angreifen zu wollen, also lief ich weg. Doch in meiner Hast ließ ich den Essay fallen. Ich bin sicher, eine der Bestien hat ihn genommen.$b$bKönntet Ihr bitte versuchen, ihn zu holen und zu Mahar Ba zu bringen?",objectives={"Rettet Khadgars 'Abhandlungen über dimensionale Konvergenz' und bringt sie zu Behüter Mahar Ba in der Burg Nethergarde."}]])
R(1365,"Khan Dez'hepah",[[description="Die Kolkar sind nicht die einzigen Zentauren von Desolace. Viele Klans ziehen durch diese trockenen Ebenen, bekämpfen einander und sterben. Und es ist gut, dass sie sich untereinander bekämpfen, denn sie sind stark und brutal. Vereinten sich die Zentauren gegen uns, wären sie ein schrecklicher Gegner.$B$BWir müssen sie erledigen, bevor sie sich zusammentun.$B$BEuer erster Schritt ist, den Kolkarklan zu schwächen. Macht das, indem Ihr den Anführer Khan Dez'hepah besiegt.$B$BDas Dorf Kolkar liegt nordöstlich von hier. Geht, und möge Euch das Glück hold sein.",objectives={"Bringt Khan Dez'hepahs Kopf zu Felgur Twocuts in Desolace."}]])
R(1366,"Zentaurenkopfgeld",[[description="Da Ihr die Zentaurenklans jetzt eingeschüchtert habt, wird es Zeit, sie bluten zu lassen. Wenn Ihr durch Desolace reist, jagt Zentauren. Mir ist gleich, welchen Klan Ihr jagt. Sammelt nur Ohren. Bergeweise Ohren.$B$BWenn Ihr ihre Zahl dezimiert, schwächt Ihr ihre Entschlossenheit und macht alle Gedanken an Expansion zunichte.$B$BGute Jagd, $n.",objectives={"Bringt 15 Zentaurenohren zu Felgur Twocuts in Desolace."}]])
R(1367,"Allianz mit den Magram",[[description="Um die Zentauren zu schlagen, müssen wir ihren Hass gegen sie wenden. Wir verbünden uns mit einem Klan und lernen durch ihn, wie wir alle Klans besiegen können.$B$BWenn Ihr Euch mit den Magram verbünden wollt, dann tötet ihre Gegner, die Gelkis. Das wird Euch den Respekt der Magram einbringen. Wenn Ihr genug verdient habt, dann trefft Euch mit dem Sprecher der Magram Warug am Rand des Dorfes Magram im Südosten von Desolace.",objectives={"Baut Euch einen freundlichen Ruf bei den Magram auf und sprecht dann mit Warug."}]])
R(1368,"Allianz mit den Gelkis",[[description="Um die Zentauren zu schlagen, müssen wir ihren Hass gegen sie wenden. Wir verbünden uns mit einem Klan und lernen durch ihn, wie wir alle Klans besiegen können.$B$BWenn Ihr Euch mit den Gelkis verbünden wollt, dann tötet ihre Gegner, die Magram. Wenn Ihr Euch den Respekt der Gelkis verdient habt, dann trefft Euch mit der Schamanin der Gelkis Uthek der Weisen am Rand des Dorfes Gelkis im Südwesten von Desolace.",objectives={"Baut Euch einen Ruf als freundliche Person bei den Gelkis auf und sprecht dann mit Uthek der Weisen."}]])
R(1369,"Zerbrochene Tränen",[[description="Die Gelkis glauben, dass unsere Zentaurenmutter Theradras uns beschützt. Sie sind dumm. Niemand beschützt die Zentauren. Die Magram brauchen keinen Schutz! Wir sind die Stärksten!$B$BZeigt den Gelkis, dass sie dumm sind. Geht zu der Höhle in ihrem Dorf. Sie horten Kristalle in dieser Höhle, die Tränen von Theradras. Zerstört die Tränen und bringt mir die zerbrochenen Stücke!",objectives={"Wahrt Euren Ruf bei den Magram und bringt 3 zerbrochene Tränen zu Warug im Dorf Magram."}]])
R(1370,"Diebstahl von Vorräten",[[description="Wenn wir nicht im Krieg sind, jagen wir wegen Fleisch. Fleisch gibt uns Kraft und volle Bäuche kämpfen besser als leere.$B$BSo ist es bei den Magram. Sie lagern extra Fleisch ein, damit sie zwischen den Jagdausflügen länger kämpfen können. Wenn man ihr Dorf im Osten überfällt und ihre Fleischvorräte raubt, wird ihre Kraft schwinden.",objectives={"Bringt 6 Taschen primitiv getrocknetes Fleisch zu Uthek der Weisen im Dorf Gelkis."}]])
R(1371,"Gizmo für Warug",[[description="Vor langer Zeit kam ein kleiner Gnom nach Desolace. Er hatte Pferde und einen Karren, und auf dem Karren viele seltsame Dinge. Komische Dinge. Dinge, die in verschiedenen Farben brannten. Dinge, die sich bewegten und doch nicht lebten. Ich tötete den kleinen Gnom, aber vorher ... brachte er mich zum Lachen.$B$BIch behielt mein liebstes Ding von dem Wagen. Es war ein Mensch aus Holz, der mir zuwinkte, bis ich ihn schlug und zerbrach.$B$BIch will einen Neuen. Besorgt mir einen Neuen!",objectives={"Wahrt Euren Ruf bei den Magram und bringt eine hochentwickelte Zielattrappe zu Warug im Dorf Magram in Desolace."}]])
R(1372,"Nichts als die Wahrheit",[[description="Auf Befehl von Varimathras wurde unsere Expeditionsstreitmacht ausgeschickt, um das untere Azeroth zu vermessen.$b$bBeim Spähen bemerkte ich einen Spitzel der Menschen, der den Bettlerschlupfwinkel ausspionierte. Ehe ich ihn festnehmen konnte, schnappten ihn einige unserer ... Orcbrüder ... und brachten ihn nach Stonard, ihrer Festung in den Sümpfen des Elends.$b$bIch möchte unseren Orcverbündeten ... helfen. Sie sahen unser Lager hier nicht, dennoch wollte ich sie unterstützen.$b$bIch arbeitete hier mit Faustin, um ein ... Wahrheitsserum für unseren Freund in Stonard zu entwickeln.",objectives={"Sprecht mit Apotheker Faustin im Bettlerschlupfwinkel."}]])
R(1373,"Ongeku",[[description="Ihr müsst noch mehr beweisen und Eure nächste Aufgabe führt Euch weit weg, daher werden die Gelkis die Magram vorerst ohne Euch bekämpfen.$B$BDie Erde flüstert jenen, die zuhören, viele Geheimnisse zu. Ein Geheimnis, von dem ich höre, betrifft einen roten Kristall. Er heißt Draenethyst und ist neu auf unserer Erde. Er stammt von einem Ort, wo Berge fliegen und Dämonen herrschen.$B$BBringt mir einen Splitter Draenethyst; er macht meine Magie stark! Der Splitter befindet sich an einem Ort namens Sümpfe des Elends und ist im Besitz von Ongeku, dem Verirrten.",objectives={"Wahrt Euren Ruf bei den Gelkis und bringt einen Draenethystsplitter zu Uthek der Weisen im Dorf Gelkis in Desolace."}]])
R(1374,"Khan Jehn",[[description="Die Erde spricht zu mir und sagt, dass die Magram schwach werden. Jetzt ist es Zeit, ihren Khan zu töten!$B$BBringt mir den Kopf des Magramkahns Jehn!",objectives={"Bringt Khan Jehns Kopf zu Uthek der Weisen im Dorf Gelkis in Desolace."}]])
R(1375,"Khan Shaka",[[description="Ihr helft den Magram und ich mag Euch. Tötet jetzt den Khan der Gelkis! Er ist Khan Shaka und ich will seinen Kopf! Ich möchte seinen Kopf ansehen und ihn auslachen!",objectives={"Wahrt Euren Ruf bei den Magram und bringt den Kopf von Khan Shaka zu Warug im Dorf Magram in Desolace."}]])
R(1380,"Khan Hratha",[[description="$N, Ihr habt uns gegen die Magram geholfen. Jetzt helft uns dabei, die Maraudine zu schlagen! Tötet den Anführer ihres Klans, Khan Hratha!$B$BUm ihn herauszufordern, blast das Kriegshorn der Maraudine. Es befindet sich auf einem hohen Steilhang im Tal der Speere.$B$BDoch um das Horn zu blasen, müsst Ihr erst ein Kriegshornmundstück erwerben. Diese Teile sind selten und sind ausschließlich im Besitz der vertrauenswürdigsten Maraudinezentauren.$B$BNachdem das Horn geblasen wurde, werden Zentauren kommen. Tötet sie, bis Hratha auftaucht.$B$BKhan Hratha besitzt ein Stück eines... Schlüssels. Bringt es mir...",objectives={"Wahrt Euren Ruf bei den Gelkis und bringt das Schlüsselfragment der Maraudine zu Uthek der Weisen im Dorf Gelkis."}]])
R(1381,"Khan Hratha",[[description="Der Khan der Gelkis ist tot, und jetzt werden die Maraudine fallen! Tötet Hratha, den Khan der Maraudine!$B$BUm ihn herauszufordern, blast das Horn auf dem hohen Steilhang im Tal der Speere. Doch um das Horn zu blasen, braucht Ihr erst ein Kriegshornmundstück. Um ein Mundstück zu erwerben, müsst Ihr Zentauren der Maraudine töten. Tötet sie so lange, bis Ihr ein Mundstück findet. Dann blast das Horn.$B$BTut dies, und Zentauren der Maraudine werden zum Turm kommen. Tötet sie, bis Khan Hratha auftaucht. Khan Hratha besitzt ein Stück eines Schlüssels. Gebt mir dieses Stück...",objectives={"Wahrt Euren Ruf bei den Magram und bringt das Schlüsselfragment der Maraudine zu Warug im Dorf Magram in Desolace."}]])
R(1382,"Seltsame Allianz",[[description="Wir können von Glück reden, dass die Zentauren sich untereinander bekämpfen, denn als vereinigte Kraft könnte sie nichts aufhalten. Ja, das kommt uns zu Gute und wir sollten unseren Vorteil ausbauen.$B$BEiner der Zentaurenklans, der Gelkisklan, führt einen brutalen Krieg gegen den Magramklan. Wenn wir die Magram angreifen, können wir vielleicht eine Allianz mit den Gelkis schmieden.$B$BSprecht mit Uthek der Weisen im Randbezirk der Gelkislager im Südwesten von Desolace. Durch sie könnten wir eine Allianz mit den Gelkis schmieden.",objectives={"Baut eine freundliche Beziehung zu den Gelkis auf und sprecht dann mit Uthek der Weisen."}]])
R(1383,"Nichts als die Wahrheit",[[description="Mir schwebt genau das richtige Serum vor. Es wird die Wahrheit genau so behandeln, wie die Wahrheit behandelt werden sollte.$b$bFür dieses Gebräu brauche ich mehrere Schattenpantherherzen aus dem Sumpf. Außerdem brauche ich den verzauberten Fungus des Morastlords, der dort haust. Ich bin sicher, jemand, der so tüchtig ist wie Ihr, $n, kann ihn überreden, sich von einigen zu trennen.$b$bDie schwierigste Aufgabe wird sein, einen Tiefschreitertumor aus dem fernen Desolace zu beschaffen. Nur sehr selten werden die Riesen dort krank, sodass ein Tumor entsteht.$b$bUnd jetzt fort mit Euch!",objectives={"Apotheker Faustin im Bettlerschlupfwinkel braucht 5 Schattenpantherherzen, Morastlordfungus und einen Tiefschreitertumor."}]])
R(1384,"Überfall auf die Kolkar",[[description="Die Kolkarzentauren glauben, ihre Magie sei stark. Die wissen nicht, was Magie ist! Nie und nimmer würden die richtige Magie überhaupt erkennen!$B$BIhr werdet ihnen zeigen, dass ihre Magie schwach ist. Geht zu den Kolkar im Nordosten und tötet sie. Nehmt ihre Glücksbringer. Bringt mir die Glücksbringer und ich werfe sie ins Feuer und lache!",objectives={"Wahrt Euren Ruf bei den Gelkis und bringt 10 kunstlose Glücksbringer zu Uthek der Weisen im Dorf Gelkis in Desolace."}]])
R(1385,"Brutale Politik",[[description="Desolace ist ein Land im Krieg. Die Zentauren führen Krieg untereinander und wir glauben, der Sieger wird marschieren und unsere Festungen bedrohen. Das können wir nicht dulden.$B$BWir müssen lernen, wie man die Zentauren schlägt, und dazu... müssen wir uns mit einem der Klans verbünden. Die Zentauren der Magram führen Krieg mit den Gelkis. Wenn Ihr gegen die Gelkis kämpft, dann erwägen die Magram vielleicht eine Allianz.$B$BErringt die Gunst der Magram und sprecht dann mit Warug im Dorf Magram im Südosten von Desolace.",objectives={"Baut Euch einen freundlichen Ruf bei den Magram auf und sprecht dann mit Warug."}]])
R(1386,"Angriff auf die Kolkar",[[description="Die Kolkar halten sich für stark, aber wir lachen über sie! Wir lachen und wir töten sie! Tötet auch Ihr sie. Zeigt mir, dass Ihr Kolkar genauso wie wir töten könnt. Geht nach Norden und tötet sie alle!",objectives={"Haltet Euren Ruf bei den Magram aufrecht. Tötet 12 Zentauren der Kolkar, 12 Späher der Kolkar sowie 6 Raufer der Kolkar und kehrt dann zu Warug ins Magramdorf in Desolace zurück."}]])
R(1387,"Zentaurenkopfgeld",[[description="Viele Klans bilden das Volk der Zentauren. Jeder hat seinen Anführer und eine Agenda, aber alle Klans haben eines gemeinsam: Grausamkeit.$B$BWenn wir je Frieden finden wollen, müssen die Zentauren entfernt werden. Und ich übertrage Euch die Aufgabe, genau das zu tun.$B$BWenn Ihr durch Desolace zieht, jagt Zentauren und sammelt ihre Ohren. Bringt mir viele, viele Ohren.$B$BMacht das im Dienst der Allianz, $n, und wir sind dem Ende des Krieges einen Schritt näher.",objectives={"Bringt 15 Zentaurenohren zu Corporal Melkins bei der Nijelspitze in Desolace."}]])
R(1388,"Nichts als die Wahrheit",[[description="Alles läuft genau nach Plan, $n. Ich möchte, dass Ihr dieses Wahrheitsserum dem Todespirscher Zraedus gebt. Er wird Euch zeigen, wie man es richtig... anwendet.$b$bHa-ha!",objectives={"Gebt Faustins Wahrheitsserum dem Todespirscher Zraedus im Bettlerschlupfwinkel."}]])
R(1389,"Draenethystkristalle",[[description="Die Verirrten, die im Fallow Heiligtum leben, sehen aus wie wir, aber sie sind Monster... die üblen Unbilden auf unserem Trek nach Azeroth haben sie wahnsinnig gemacht. Einst waren sie unsere Brüder, doch nun leben sie im Fallow Heiligtum im Osten und fangen oder töten alle, die sich in die Nähe wagen.$B$BUnd sie haben uns etwas Heiliges gestohlen - Draenethystkristalle.$B$BUns fehlt die Kraft, das Fallow Heiligtum zu betreten und unseren gestohlenen Draenethyst von ihren Hütten und Lagerfeuern zu holen, aber ohne diese Kristalle... könnten auch wir vom rechten Weg abkommen.",objectives={"Bringt 6 Draenethystkristalle zu Magtoor im Sicheren Hafen in den Sümpfen des Elends."}]])
R(1390,"Oops, We Killed Them Again.",[[description="Missing text",objectives={"Missing text"}]])
R(1391,"Nichts als die Wahrheit",[[description="Wir müssen mit einer gewissen Diskretion vorgehen. Immerhin werdet Ihr nicht da reinspazieren und den Narren überzeugen, Faustins Gebräu zu trinken, richtig?$b$bAber wenn es eines gibt, zu dem die Menschen nicht nein sagen können, dann ist es Fusel. Ich nehme Faustins Serum und mische es in dieses Bier. Der arme Kerl wird garantiert keine Hemmungen haben, wenn es darum geht, ein Gebräu zu kippen.$b$bGeht hastig nach Stonard in den Sümpfen des Elends, $n. Und schweigt schön stille über unsere kleine Mission ...",objectives={"Bringt Zraedus' Bräu zu Spitzel Marksen in Stonard."}]])
R(1392,"Noboru der Knüppel",[[description="Noboru verseuchte die Draenei des sicheren Hafens seit Monaten; sein Knüppel ist ein Symbol der Brutalität, die sie sich von den Verirrten gefallen lassen mussten.",objectives={"Bringt Noborus Knüppel zum Anführer des Sicheren Hafens in den Sümpfen des Elends."}]])
R(1393,"Galens Flucht",[[description="Bitte helft! Diese Kreaturen werden mich fressen!$B$BHelft mir hier raus und ich gebe Euch einen großen Schatz! Er ist in meinem Lager im Sumpf im Norden von Stonard, aber in einer Geldkassette eingeschlossen, die man mit einem Trick öffnet, den nur ich beherrsche.$B$BWenn ihr mir zur Flucht verhelft, zeige ich ihn Euch.",objectives={"Eskortiert Galen, bis er außer Gefahr ist, sucht dann sein Lager in den Sümpfen des Elends und öffnet seine Geldkassette."}]])
R(1394,"Letzte Überfahrt",[[description="Ihr habt Eure Sache gut gemacht, $n. Ihr habt meinen Test und die Tests vor meinem bestanden. Kehrt zu Dorn in Tausend Nadeln zurück. Er wird die Veränderung in Euch spüren und sehen, dass Euer Verstand, Körper und Geist stark genug sind, dass Ihr für Eure Bemühungen belohnt werden solltet.$B$BBleibt dem Gleichgewicht treu, das Ihr während all dieser Prüfungen gezeigt habt, $n. Wenn Ihr das tut, wird Dorn Euch irgendwann noch einmal prüfen.",objectives={"Sprecht mit Dorn Plainstalker in Tausend Nadeln."}]])
R(1395,"Vorräte für Nethergarde",[[description="Diese Kiste mit Kraftsteinen muss in die Burg Nethergarde in den Verwüsteten Landen. Sie werden ihre Macht nicht lange halten, daher können wir sie nicht mit der nächsten Karawane aufgeben.$B$BIhr müsst sie nehmen, und zwar schnell.$B$BBringt sie zu Rüstmeister Lungertz in der Burg Nethergarde. Um die Burg zu erreichen, müsst Ihr nach Osten über den Gebirgspass der Totenwinde, dann nach Osten durch die Sümpfe des Elends und dann nach Süden durch die Verwüsteten Lande.$B$BSeid vorsichtig, $n. Ihr müsst durch gefährliche Länder und dürft doch nicht verzagen.",objectives={"Bringt die Kiste mit den Kraftsteinen zu Rüstmeister Lungertz, bevor die Kraft verbraucht ist."}]])
R(1396,"Lauernde Tierwelt",[[description="Meine Karawane sollte zur östlichen Küste ziehen, aber wir erreichten unser Ziel nicht. Verirrte haben uns angegriffen, die Wachen getötet und die Vorräte verstreut.$B$BIch allein habe ihren Angriff überlebt. Ich habe geschworen, die verbliebenen Vorräte zu schützen, aber wilde Kreaturen schleichen in der Nähe herum. Bitte helft mir, mein Lager gegen diese Bestien zu verteidigen!",objectives={"Tötet 8 junge Sägezahnkrokilisken, 10 Trauerspinner sowie 10 Sumpfjaguare und kehrt dann zu Behüter Biggs in den Sümpfen des Elends zurück."}]])
R(1398,"Treibholz",[[description="Ich stehe tief in Eurer Schuld, $N. Ein ehrenhaftes Herz schlägt in Eurer Brust. Und jetzt habe ich eine andere Aufgabe, für die ich demütig um Eure Mithilfe bitte.$B$BWenn ich Nethergarde erreichen soll, dann muss ich diesen Wagen reparieren. Und dafür ... brauche ich Holz. Starkes, trockenes Holz - nicht das schimmelige, krumme Holz der Sumpfbäume.$B$B$N, geht nach Osten zur Küste und sucht nach in der Sonne getrocknetem Treibholz. Bringt es mir.",objectives={"Bringt 8 Stücke sonnengetrocknetes Treibholz zu Behüter Biggs in den Sümpfen des Elends."}]])
R(1418,"Neeka Bloodscar",[[description="Das Ödland ist unwirtlich und liegt nahe am Land des Loch Modan, das von der Allianz beherrscht wird, daher wird die Kommunikation zwischen Stonard und den Ödland-Außenposten von Kargath oft unterbrochen.$B$BBeweist Euch, $N. Reist ins Ödland und sprecht mit Neeka Bloodscar, der obersten Späherin des Kargath-Außenpostens. Sprecht mit ihr und bringt mir ihren Bericht.",objectives={"Sprecht mit Neeka Bloodscar."}]])
R(1419,"Kojoten-Diebe",[[description="Habt Ihr viele Tage im Ödland verbracht, $C? Habt Ihr sein Herz gespürt? Habt Ihr den Bestien getrotzt, die durch die staubigen Ebenen schleichen? Dann wird es aber höchste Zeit.$B$BKlippenkojoten sind zähe Burschen. Zäh und tollkühn genug, dass sie sich nach Kargath schleichen und unsere Essensvorräte stehlen. Helft mit, den Außenposten von diesen Dieben zu befreien!$B$BJagt Klippenkojoten, $n. Jagt sie und bringt mir ihre Kieferknochen. Bringt mir genügend und ich glaube Euch vielleicht, wenn Ihr sagt, dass Ihr das Ödland kennt.",objectives={"Bringt 30 Kojotenkieferknochen zu Neeka Bloodscar in Kargath."}]])
R(1420,"Bericht für Helgrum",[[description="Ich schrieb einen neuen Bericht für Helgrum in Stonard. Bringt ihn zu ihm.$B$BUnd wenn Ihr Euch als Kundschafter betrachtet, kommt nicht vom Weg ab. Oder fallt einem Feind in die Hände.",objectives={"Bringt Neekas Bericht zu Helgrum dem Hurtigen in Stonard."}]])
R(1421,"Die verlorene Karawane",[[description="Ich wurde während des Angriffs der Verirrten betäubt, aber bevor mir schwarz vor Augen wurde, sah ich einen unserer Wagen, der zum Fallow Heiligtum gezerrt wurde, zum Dorf der Verirrten im Norden.$B$BEine Karawanentruhe mit wertvollen Reagenzien war in diesem Wagen, Reagenzien, die unabdingbar für die Studien der Hexer der Burg Nethergarde sind. Sucht die Truhe und holt diese Reagenzien, $N. Holt sie und bringt sie mir.",objectives={"Sucht die Karawanentruhe im Fallow Heiligtum, beschafft Euch die Reagenzien der Hexer und bringt sie zu Behüter Biggs."}]])
R(1422,"Gefahr aus dem Meer",[[description="Warum unterhaltet Ihr Euch nicht mit Katar, während ich an Eurer Waffe arbeite? Er erwähnte, dass er Hilfe bei Patrouillen am Strand braucht, und mir wäre es lieber, Ihr würdet Euren Geist und Eure Waffen trainieren, anstatt Euch mit den anderen Tunichtguten in diesem Lager zu betrinken.",objectives={"Sprecht mit Katar in den Sümpfen des Elends."}]])
R(1423,"Die verlorenen Vorräte",[[description="Dieses Fass ist klein, aber stabil. Seine Ritzen sind mit einem gelben, duftenden Wachs versiegelt. Auf der Unterseite des Fasses stehen die Worte:$B$BRÜSTMEISTER LUNGERTZ$B$BBURG NETHERGARDE",objectives={"Bringt die verlorenen Vorräte zu Rüstmeister Lungertz."}]])
R(1424,"Tränenteich",[[description="Der Kriegshäuptling schickt uns, die seltsamen Vorkommnisse im Tempel von Atal'Hakkar zu untersuchen.$B$BDie Trolle des Stammes der Atal'ai sind ein Stamm dunkler Zauberkundiger, die dafür bekannt sind, verbotene Magie auszuüben. Ihr könnt Euch vorstellen, wie erstaunt wir waren, als wir hier eintrafen und feststellten, dass der Tempel versunken war.$B$BDie grünen Großdrachen hüten nun die Stelle und spielen sich als Beschützer von Azeroth auf.$B$BWir müssen herausfinden, was geschehen ist. Forscht rund um den Tränenteich und sammelt Artefakte der Atal'ai. Damit kann ich dieses Rätsel lösen.",objectives={"Fel'Zerul in Stonard möchte, dass Ihr 10 Artefakte der Atal'ai sammelt."}]])
R(1425,"Überbringen der Lieferung",[[description="Während ich diesen Wagen repariere, $N, habe ich eine letzte Aufgabe für Euch.$B$BIch habe die wichtigsten Vorräte eingepackt, die ich vor den Angriffen der Oger retten konnte. Bringt sie zur Burg Nethergarde. Die Burg schmiegt sich an die nördlichen Hügel der verwüsteten Lande und wacht über das Dunkle Portal.$B$BFolgt der Straße nach Osten, um Nethergard zu erreichen. Geht an der Gabelung nach Süden in die verwüsteten Lande und bei der nächsten Gabelung nach links. Folgt der Straße, $N, und seid wachsam.",objectives={"Bringt die Ladung für Nethergarde zu Rüstmeister Lungertz in der Burg Nethergarde."}]])
R(1426,"Gefahr aus dem Meer",[[description="Ich mag weder das Meer noch die Kreaturen, die ich aus seiner Tiefe kommen sah. Es ist eine mächtige, aber blinde Herrin; launisch und brutal. Es wäre mir ein Vergnügen, die Fischmenschen zu Hunderten zu töten, wenn es in meiner Macht stünde. Eine kleine Freude ist es mir wenigstens, sie durch die Hände all derer sterben zu sehen, die den Willen der Horde erfüllen.$B$BUnd damit sind wir bei Euch, $C . Wie viele könnt Ihr besiegen? Würdet Ihr Euch mit dem Mächtigsten ihrer Art messen?",objectives={"Tötet 10 Marschenmurlocs, 10 Marschentintenspucker und 10 Marschenfleischfresser und kehrt dann zu Katar in den Sümpfen des Elends zurück."}]])
R(1427,"Gefahr aus dem Meer",[[description="Sprecht wieder mit Tok'Kar, bevor Ihr Euch ausruht. Während Ihr fort wart, hat er, glaube ich, ein paar Waffen vollendet. Für Eure Hilfe würde er Euch eine davon anbieten. Ihr tätet gut daran, ihre Kraft an den Fischmenschen zu erproben, wenn Ihr bereit seid ... aber nur, um mich weiterhin zu erfreuen.",objectives={"Sprecht mit Tok'Kar in den Sümpfen des Elends."}]])
R(1428,"Fortwährende Gefahr",[[description="Freut mich zu sehen, dass Euer Hass auf die Fischmenschen mit meinem wächst.$B$BSucht mehr von ihnen am Strand entlang, und wenn Ihr genug vom Gefecht habt, kommt zu mir zurück. Dann sprechen wir über eine Belohnung für Eure Ausdauer.",objectives={"Tötet 10 Marschentintenspucker, 10 Marschenfleischfresser und 10 Marschenorakel und kehrt dann zu Katar in den Sümpfen des Elends zurück."}]])
R(1429,"Der Verbannte der Atal'ai",[[description="Während Ihr den Gefahren des Tränenteichs getrotzt habt, kehrte einer meiner Späher mit einer in Blut und auf getrocknetem Fleisch geschriebenen Rolle zurück. Es scheint sich um ein Urteil gegen einen der Priester des Stammes der Atal'ai zu handeln.$B$BDer Priester wurde zu etwas Schlimmerem als dem Tod bei den Atal'ai verurteilt.$B$BEr wurde ins Hinterland zu den Trollen der Witherbark verbannt.$B$BIch bündle diese Artefakte. Ihr müsst den Verbannten suchen und ihren wahren Verwendungszweck herausfinden. Kommt wieder zu mir, wenn Eure Reise beendet ist.",objectives={"Bringt das Artefaktbündel der Atal'ai zu dem Verbannten der Atal'ai ins Hinterland."}]])
R(1430,"Frischfleisch",[[description="Bei meinen Kunden besteht eine enorme Nachfrage nach dem saftigen Geschmack von Kriecherfleisch; besonders nach dem Fleisch der monströsen Kriecher.$B$BWenn Ihr vorhabt, zur Küste zu reisen, könnte es sich lohnen, wenn Ihr mir einige ihrer Beine bringt, damit ich sie nach Orgrimmar transportieren lassen kann.$B$BDie Küste liegt östlich von hier. Ihr solltet keine Probleme haben, die Kreaturen zu finden, die an den Stränden und im Meer umherhuschen.",objectives={"Bringt 10 monströse Kriecherbeine zu Dar in den Sümpfen des Elends."}]])
R(1431,"Allianz-Beziehungen",[[description="Seid still, $n, und lasst mich Euch etwas Wichtiges über unser Volk sagen, das nicht auf der Hand liegt.$B$BWir sind ein stolzes Volk und der Krieg gegen die Menschen hat selbst Thralls große Geduld auf die Probe gestellt. Wisst Ihr, unser Kriegshäuptling ist weise und umsichtig und sein Volk kommt stets an erster Stelle. Letztendlich ist er ein Diplomat und hat in seiner Zeit bei den Menschen viel von ihrer Art gelernt.$B$BWenn die Geschichte, die ich begonnen habe, Euer Interesse weckt, dann geht zu Keldran beim westlichen Ausgang der Stadt. Dort steht seine Hütte.",objectives={"Sprecht mit Keldran in Orgrimmar."}]])
R(1432,"Allianz-Beziehungen",[[description="Wenn die Allianz immer tiefer nach Kalimdor vorstößt, könnten falsche Schlussfolgerungen über mögliche Bündnisse der Horde mit der Brennenden Legion gezogen werden. Dazu darf es der Kriegshäuptling nicht kommen lassen. Und mit seinem Segen übernehme ich die Aufsicht darüber, dass alle Missverständnisse ausgeräumt werden.$B$BIch habe Agenten in der Gegend von Desolace am Geistwandlerposten nördlich des großen Kodofriedhofs. Wenn Ihr vom verbrannten Tal im Steinkrallengebirge aus südwärts geht, solltet Ihr dort vorbeikommen. Wenn Ihr eintrefft, sucht Takata Steelblade auf.",objectives={"Sprecht mit Takata Steelblade in Desolace."}]])
R(1433,"Allianz-Beziehungen",[[description="Die Burning Blade haben eigene Ziele verfolgt; doch wisst, dass sie bis ins Mark böse sind und ihr Geist verderbt wurde. Sie zu vernichten ist die einzige Möglichkeit, ihnen Einhalt zu gebieten.$B$BKeldran schickte Maurin mit mir, weil er die Klinge und die Arglist ihrer Hexenmeister kennt.$B$BEr leitet unsere Verschwörungen gegen die Klinge, während ich mich um die anderen dämonischen Bedrohungen in Desolace kümmere.$B$BSprecht mit ihm und er wird Euch in seine Pläne einweihen.",objectives={"Sprecht mit Maurin Bonesplitter in Desolace."}]])
R(1434,"Beschmutzt durch Satyrn",[[description="Eine Dämonenplage geschieht nicht ohne andere Einflüsse - etwas anderes ermöglicht dem Bösen, Fuß zu fassen.$B$BEs mag mit einem schwachen Geist beginnen, einer unnötigen Gier nach Macht, möglicherweise Rachedurst oder der Verlockung nach höchster Gerechtigkeit. Wenn der Schmerz uns übermannt, dann nutzt uns das Böse aus - das Böse wie die Satyrn.$B$BBande wurden zwischen ihnen und den Burning Blade geknüpft und Thrall hätte sie getötet. Sucht sie nordöstlich von hier und kommt zu mir zurück, wenn Ihr sie zurückgeschlagen habt.",objectives={"Besiegt 7 Schurken der Zornsäer, 7 Teufelsanbeter der Zornsäer, 7 Verräter der Zornsäer sowie 7 Höllenrufer der Zornsäer und kehrt zu Takata Steelblade in Desolace zurück."}]])
R(1435,"Brennender Geist",[[description="Für diese abscheulichen Kreaturen, die ihrem Lehen aus so egoistischen Gründen den Rücken kehren, ist der Tod höchst wünschenswert. Doch wenn man es mit denen zu tun hat, die sich der Dunkelheit verschrieben haben, reicht der Tod allein nicht aus.$B$BNehmt diesen Edelstein. Wenn einer der Burning Blade dem Tode nahe ist, aktiviert seine Magie. Der Zauber wird den verderbten Geist aus seinem Opfer herausziehen und einen damit erfüllten Edelstein hinterlassen.$B$BBringt mir diese erfüllten Edelsteine, damit ich sie angemessen entsorgen kann.$B$BGeht jetzt, und möge Euch der Tod meiden.",objectives={"Bringt den brennenden Edelstein und 15 erfüllte brennende Edelsteine nach Desolace zu Maurin Bonesplitter."}]])
R(1436,"Allianz-Beziehungen",[[description="Der Kampf läuft gut, $n. Vielleicht lässt uns der Kriegshäuptling, bevor die Jahreszeiten wechseln, in unsere Heimat zurückkehren, wenn der Kampf gegen die Dämonen und ihre Unterlinge weiterhin so gute Fortschritte macht.$B$BKehrt zu Keldran zurück und lasst ihn wissen, was wir getan haben. Ich bin sicher, er belohnt Euch für Eure Taten hier. Seine Sache ist ihm wichtig und es wird ihn mit Stolz erfüllen, wenn er weiß, dass der Kriegshäuptling seine Sorgen respektiert.",objectives={"Sprecht mit Keldran in Orgrimmar."}]])
R(1437,"Vahlarriels Suche",[[description="Ich bin Vahlarriel, $n. Ich kam her, um mich nach dem Befinden zweier vermisster Adliger einer Kaufmannsfamilie aus Darnassus zu erkundigen - Haus Malem. Der Vater des Hauses fürchtet das Schlimmste. Ich soll tun, was ich kann, um seine vermissten Kinder zu finden. Ich habe noch nicht mit der Suche nach Tyranis und Dalinda begonnen, hoffe aber, ich werde mich nicht lange hier aufhalten.$B$BZuletzt hörte man, dass sie vor wenigen Wochen durch das Steinkrallengebirge gekommen sein sollen.$B$BFalls Ihr ihren Wagen findet, sucht mich bitte unverzüglich auf.",objectives={"Sucht und findet den Wagen von Tyranis und Dalinda Malem in Desolace."}]])
R(1438,"Vahlarriels Suche",[[description="Sucht Dalinda und Tyranis, wenn Ihr könnt, und berichtet mir von Euren Funden. Beginnt Eure Suche in dieser Festung. Ich setze mich sofort mit meinen Vorgesetzten in Darnassus in Verbindung und informiere sie über die Situation.$B$B$N, ich möchte Euch noch etwas wissen lassen. Meine Vorgesetzten haben Besorgnis wegen Tyranis und seinen Motiven für diese Reise geäußert. Es ist ihnen wichtiger, dass Dalinda gefunden und wohlbehalten zurückgebracht wird. Tyranis soll ... gefesselt werden, ehe man ihn nach Hause bringt.",objectives={"Sucht Dalinda Malem in Desolace."}]])
R(1439,"Suche nach Tyranis",[[description="Wir wurden hierher gebracht, nachdem die Orcs alle unsere Wachen und Diener abgeschlachtet hatten. Oh, was haben sie ihnen Schreckliches angetan! Ich dachte, sie würden uns auf der Stelle töten, doch dann wurde deutlich, dass sie andere Pläne hatten.$B$BTyranis versuchte, mit ihnen zu reden. Ich glaube, er wollte sie mit seinem arkanen Wissen beeindrucken ... Ich bin nicht sicher, warum.$B$BBitte, ich kann hier nicht weg, bevor ich weiß, was meinem Bruder zugestoßen ist. Sucht ihn und kommt zu mir, wenn Ihr sein Schicksal kennt.",objectives={"Sucht Tyranis Malem in Desolace."}]])
R(1440,"Rückkehr nach Vahlarriel",[[description="Also ist die Zeit gekommen? Ich weiß Eure Bemühungen zu schätzen, und wenn auch die Situation dafür nicht geeignet ist, lasst mich Euch jetzt für alles danken, was Ihr für mich und meine Familie getan habt. Wenn Ihr bereit seid, hier hält mich nichts mehr - wir können aufbrechen, falls es Euch passend erscheint.",objectives={"Begleitet Dalinda Malem aus der Festung Thunder Axe und kehrt zu Vahlarriel Demonslayer nach Desolace zurück."}]])
R(1441,"<UNUSED>")
R(1442,"Suche nach dem Kor-Edelstein",[[description="Seid gegrüßt, $N. Was kann ich für einen tun, der dem heiligen Weg folgt?$B$BAh ja, Stilwell, der Schmied... das war vor langer Zeit. Ich erinnere mich gut an ihn, doch ich habe seinen Namen schon eine ganze Weile nicht mehr gehört.$B$BEr schien mir nie ein habgieriger Mann zu sein, daher kann ich nur davon ausgehen, dass sein Wunsch nach einem Kor-Edelstein edle Motive hat.$B$BWenn Ihr wirklich so einen Edelstein möchtet, dann müsst Ihr in den Nordwesten von Ashenvale. Dort findet Ihr die Blackfathom-Tiefe mit einigen alten Ruinen. Die Naga, die diese Edelsteine noch immer benutzen, sind dort unten. Geht nicht allein, $C.",objectives={"Bringt einen Kor-Edelstein zu Thundris Windwirker in Dunkelküste."}]])
R(1444,"Rückkehr zu Fel'Zerul",[[description="Jammal'an der Prophet verbannte mich aus dem Tempel von Atal'Hakkar. Einst empfand ich den Hohepriester als würdigen Anführer.$b$bSein unerschütterlicher Glaube an seine Prophezeiung wird den Untergang der Atal'ai herbeiführen. Wenn es nicht schon geschehen ist.$b$bAls ich meiner Besorgnis Ausdruck verlieh, hieß man mich einen Ungläubigen und verstieß mich aus dem Tempel.$b$bDie Artefakte, die Ihr zu mir brachtet, sind harmlos. Aber wenn Jammal'an die richtige Fetischverzauberung für das Beschwörungsritual gefunden hat, droht der Welt große Gefahr...",objectives={"Kehrt zu Fel'Zerul in Stonard zurück."}]])
R(1445,"Der Tempel von Atal'Hakkar",[[description="Also sprach er von Jammal'ans Prophezeiung?$B$BDer spirituelle Anführer der Atal'ai glaubt, wenn Hakkar aus dem Nether nach Azeroth zurückkehrt, wird der Gott dem Stamm der Atal'ai Unsterblichkeit gewähren.$b$bTörichte Arglist, um den Jüngsten Tag schneller herbeizuführen, wenn Ihr mich fragt.$B$BDoch Ihr sagt, der Verbannte sprach von verzauberten Fetischen? Das erfüllt mich mit großer Sorge. Wenn sie wahrhaftig der Schlüssel zu dem Ritual der Atal'ai sind, das dieses Durcheinander verursachte, müssen wir die Mächte verstehen, die in ihnen wohnen.$B$BBegebt Euch in den Tempel und werdet dieser Fetische habhaft!",objectives={"Sammelt 20 Fetische von Hakkar und bringt sie zu Fel'Zerul in Stonard."}]])
R(1446,"Jammal'an der Prophet",[[description="Meine Gefährten aus Witherbark mögen keine Fremden in ihrer Nähe.$b$bIch? Ich habe keine Heimat mehr. Mein Volk, der große Stamm der Atal'ai aus den Sümpfen des Elends, hat mich verbannt.$b$bJammal'an, unser spiritueller Anführer, hatte eine, wie wir uns ausdrücken, Prophezeiung. Er glaubt, die Beschwörung des Gottes Hakkar bringt den Atal'ai Unsterblichkeit.$b$bIch jedoch drängte auf Vorsicht. Wenn die Prophezeiung nun nichts weiter als Manipulation war?$b$bIch will Rache für meine Verbannung. Bringt mir Jammal'ans Kopf. Vielleicht ist mein Volk dann frei.",objectives={"Der Verbannte der Atal'ai im Hinterland möchte den Kopf von Jammal'an."}]])
R(1447,"Der vermisste Diplomat",[[description="Ja, $C, Ihr seid offenkundig nicht einer der Klügsten Eurer Art, der je nach Stormwind kam, aber einer der Dümmsten, wenn Ihr nicht wieder fortgeht.$B$BHabt Ihr meine Freunde getroffen?",objectives={"Besiegt Dashel Stonefist in Stormwind."}]])
R(1448,"Auf der Suche nach dem Tempel",[[description="Es gab eine Zeit, da war ich jung und voller Kraft, wie Ihr, $C.$b$bDoch jetzt bin ich alt und vermag die Welt nicht mehr zu erforschen wie einst. Ach, was habe ich nicht alles gesehen!$b$bAber ein Geheimnis entzog sich mir stets. Als meinen letzten Auftrag schickte mich die Forscherliga auf die Suche nach dem Tempel von Atal'Hakkar. Er sollte Gerüchten zufolge in den Sümpfen des Elends liegen.$b$bMeines gebrechlichen Zustands wegen reiste ich auf einem Greif durch die Lüfte, fand den Tempel aber nie.$b$bHelft Ihr einem alten Zwerg? Vielleicht habt Ihr zu Fuß mehr Glück.",objectives={"Brohann Caskbelly in Stormwind möchte, dass Ihr den Tempel von Atal'Hakkar sucht."}]])
R(1449,"Ins Hinterland",[[description="Wie ich schon früher sagte, versuchte ich selbst, den Tempel aus der Luft zu finden. Ganz allein war ich freilich nicht.$b$bIch reiste zu dem berühmten Greifenhorst bei Aerie Peak im Hinterland. Dort versicherte ich mich der Hilfe eines ihrer besten Piloten. Der Pilot fiel von seinem Reittier in den Sumpf ...$b$bDen Namen des armen Burschen habe ich im Alter vergessen. Der Meister des Horsts kennt ihn zweifellos noch.$b$bBegebt Euch dorthin und sucht nach Falstad Wildhammer.$b$bWir müssen herausfinden, was dem Piloten zugestoßen ist.",objectives={"Sprecht mit dem obersten Than, Falstad Wildhammer, in Aerie Peak im Hinterland."}]])
R(1450,"Greifenmeister Talonaxe",[[description="Ihr seid also nur ein $gbesserer Botenjunge:besseres Botenmädchen; für einen alten Tattergreis der Forscherliga, hm?$b$bHört mir gut zu, $C. Ich habe keine Ahnung, mit wem Euer alter Kumpel da unten in Azeroth rumgeflogen ist. Seh ich etwa wie der Greifenmeister Talonaxe aus? Ja?$b$bWenn Ihr Euch für die Flugpläne interessiert, warum fragt Ihr dann nicht den Greifenmeister? Wenn Ihr noch länger untätig hier herumhängt, werde ich Euch richtige Arbeit geben.$b$bUnd jetzt trollt Euch.",objectives={"Sprecht mit Greifenmeister Talonaxe im Horst bei Aerie Peak."}]])
R(1451,"Rhapsody-Shindigger",[[description="Rhapsody fand Gefallen am Schnaps. Versteht mich nicht falsch - alle Zwerge hier im Horst wissen ein gutes Bier zur passenden Stunde zu schätzen.$b$bAber der alte Shindigger brauchte den Fusel wie ein Greif den Himmel. Und das war echt ein Jammer. Niemand konnte so fliegen wie Rhapsody.$b$bDie ersten Probleme gab es, als er mit Eurem Freund Brohann von dieser Mission zurückkehrte. Danach ging es rapide bergab. Musste ihn rauswerfen.$b$bZuletzt hörte ich, er habe östlich von hier eine Brauerei eröffnet ...",objectives={"Sucht Rhapsody Shindigger im Hinterland."}]])
R(1452,"Rhapsodys Kalimdor-Cocktail",[[description="Hicks!$b$bDieser irre Narr Brohann schickt Euch also? Wir haben ein tolles Abenteuer zusammen erlebt... Hicks!$b$bWenn ich Euch erzählen soll, was da unten im Sumpf passiert ist, brauch ich was Ordentliches zu trinken. Das war echt kein schöner Anblick. Hicks!$b$bIch sag Euch was... bringt mir, was ich brauche, um einen Kalimdor-Cocktail zu mixen, dann erzähl ich Euch davon.$b$bMan braucht dazu den Muskelmagen eines Roc aus Tanaris... etwas Groddoc- und Eisenfellleber aus Feralas...$b$bEin schöner kräftiger Kalimdor-Cocktail... dann kann ich plaudern!",objectives={"Rhapsody Shindigger im Hinterland möchte, dass Ihr ihm 3 Muskelmägen eines Roc, 3 Groddoc-Lebern und 3 Eisenfelllebern bringt."}]])
R(1453,"Die Geschäfte der Wiederholer in Desolace",[[description="Es gibt Arbeit in Desolace, $n. Das ist ein grässlicher Ort, beschmutzt von Zentauren und anderer Unbill. Aber wenn Ihr eine Woche ehrlicher Arbeit sucht, dann geht dorthin, besucht Kreldig Ungor und sagt ihm, ich hab Euch geschickt.$B$BIhr findet ihn an der Nijelspitze - dem gemütlichen kleinen Lager in den Bergen des nördlichen Desolace. Haltet Euch einfach ostwärts, wenn Ihr vom Steinkrallengebirge kommt. Man übersieht es leicht, also seid wachsam.",objectives={"Sprecht mit Kreldig Ungor in Desolace."}]])
R(1454,"Karnitols Schiffbruch",[[description="Mein erster Auftrag betrifft den Magier Karnitol - eine Art Edelmann in Stormwind. Offenbar wurde sein Schiff vor der Küste im Nordwesten von Meeresriesen angegriffen. Er und seine Gefolgsleute versuchten, eine seiner wertvolleren Truhen an Land zu bringen, aber als die Meeresriesen in Schwärmen angriffen, beschloss er, sie aufzugeben und sich und seine Gefolgsleute in Sicherheit zu teleportieren.$B$BEr möchte, dass wir die Truhe samt ihrem Inhalt finden und zu ihm nach Stormwind bringen.",objectives={"Sucht Karnitols Truhe in Desolace."}]])
R(1455,"Karnitols Schiffbruch",[[description="Ihr überlegt eine Weile, was die Kiste aufgebrochen haben könnte, und bemerkt an den Seiten und am Deckel lange, tiefe Kratzer, die belegen, dass sich etwas anderes als ein Mensch oder Riese dafür interessierte. Solche Spuren scheinen nicht von einem Dolch oder Schwert verursacht worden zu sein.$B$BIhr werft einen Blick in die Truhe und stellt fest, dass sie leer ist.$B$BDa Ihr nicht wisst, was Ihr sonst tun sollt, klappt Ihr die Truhe zu und rüstet zum Aufbruch. Kreldig wird enttäuscht sein.",objectives={"Kehrt zu Kreldig Ungor in Desolace zurück."}]])
R(1456,"Karnitols Schiffbruch",[[description="Faszinierend.$B$BVielleicht besteht ja doch noch Hoffnung.$B$BAn derselben Küste, aber viel weiter nördlich, nahe der Insel Ranazjar, liegen Ruinen der Nachtelfen auf dem Grund des Meeres. Ein Stamm von Naga, die Zackenkämme, sind dort zu Hause. Das dürfte unsere beste Chance sein.$B$BWenn ein Kundschaftertrupp sich so weit in den Süden wagte, müssen sie sehr mächtig sein. Wenn Ihr Kanitols Habseligkeiten finden wollt, würde ich mit den mächtigeren Naga anfangen: den Gezeitenjägern oder den Meerhexen.",objectives={"Sucht Karnitols Ranzen und bringt ihn zu Kreldig Ungor in Desolace zurück."}]])
R(1457,"Karnitols Schiffbruch",[[description="Bringt Karnitols Sachen zu Roetten in Ironforge, er wird Euch die gute Arbeit wohl vergelten.$B$BHaha, wenn Ihr nicht aufpasst, wird er so zufrieden sein, dass er Euch bittet, als Festangestellter bei uns zu bleiben.$B$BWieder einmal gut gemacht, $N.$B$BSeid auf dem Rückweg vorsichtig und lasst Euch nicht zu viel Zeit - Karnitol ist nicht der Geduldigste, aber dennoch höchst großzügig.",objectives={"Bringt Karnitols Ranzen zu Roetten Stonehammer in Ironforge."}]])
R(1458,"Reagenzien für die Wiederholer AG",[[description="Zu meinen Pflichten hier gehört, Reagenzien für Leftwitch zu beschaffen, einen Gnomen-Magier in Kharanos. Roetten glaubt, das sei ein Kinderspiel, da wir ohnehin schon hier draußen sind. Ihm ist es gleich, dass wir auch so schon unterbesetzt sind.$B$BDie ersten paar Gegenstände auf seiner Liste sollten leicht zu beschaffen sein, und für alle, die mir helfen, springt eine satte Belohnung raus.$B$BIch brauche einige Hörner und Klauen von den Satyrn der Zornsäer östlich von hier. Bringt sie mir, dann nehmen wir uns den Rest der Liste vor.",objectives={"Bringt 10 Zornsäerklauen und 10 Zornsäerhörner zu Kreldig Ungor in Desolace."}]])
R(1459,"Reagenzien für die Wiederholer AG",[[description="Als Nächstes steht auf Leftwitchs Liste... mal sehen... hmm. Oh, da haben wir es.$B$BRecht einfach, aber mit sehr expliziten Anweisungen. Er braucht Gift von den Skorpashi und Bälge von Kodos. Im Kleingedruckten steht, beide müssen von bestimmten Kreaturen sein: Das Gift soll von irgendeinem Skorpashi stammen und der Balg muss von einem gealterten Kodo sein, aber keinem sterbenden oder uralten.$B$BMagier, ich sage Euch, was die so alles wollen... abartig.",objectives={"Bringt 7 Phiolen Skorpashigift und 3 Bälge von gealterten Kodos zu Kreldig Ungor in Desolace."}]])
R(1460,"<UNUSED>")
R(1461,"<UNUSED>")
R(1462,"Erdsapta",[[objectives={"Sprecht mit der Seherin Ravenfeather wegen eines weiteren Erdsaptas."}]])
R(1463,"Erdsapta",[[objectives={"Sprecht mit Canaga Earthcaller wegen eines weiteren Erdsaptas."}]])
R(1464,"Feuersapta",[[objectives={"Sprecht mit Telf Joolam wegen eines weiteren Feuersaptas."}]])
R(1465,"Vahlarriels Suche",[[description="Als Ihr Eure Suche nach dem Wagen fortsetzt, findet Ihr nicht nur einen Anhänger, sondern auch Fußspuren, die in Richtung Süden führen. In der Ferne seht Ihr Rauch von einem großen Fort aufsteigen. Der Rauch stammt von einem Lagerfeuer, nicht von brennenden Gebäuden. Euer Instinkt sagt Euch, dass die Malems, wenn sie noch leben, in diese Richtung gebracht wurden.$B$BIhr seid der Ansicht, dass Vahlarriel an der Nijelspitze nicht nur den Anhänger sehen sollte, den Ihr gefunden habt, sondern auch von den Lebenszeichen im Süden wissen sollte.",objectives={"Kehrt mit dem Malem-Anhänger zu Vahlarriel Demonslayer in Desolace zurück."}]])
R(1466,"Reagenzien für die Wiederholer AG",[[description="Das ist der letzte Gegenstand und ganz ehrlich, er ist nicht schön. Ich gehe auch davon aus, dass Ihr dafür etwas länger braucht als für die anderen Gegenstände.$B$BDoch genug der Warnungen, fangen wir an. Leftwitch sagt, er braucht Folgendes: zehn Gehirne, entweder von Manafressern, Magierjägern oder Leyjägern, zehn Netherflügel von einer Nethermaid, -Schwester oder -Zauberhexerin. Und... zehn Phiolen Verdammniswächterblut von einem Captain oder Lord der Verdammniswächter.$B$BGanz einfach, hm? Tja... ich hätte Verständnis dafür, wenn Ihr dies ausschlagen wollt.",objectives={"Bringt 10 Teufelshundgehirne, 10 Netherflügel und 10 Phiolen Verdammniswächterblut zu Kreldig Ungor in Desolace."}]])
R(1467,"Reagenzien für die Wiederholer AG.",[[description="Wenn Ihr Eure Bezahlung wollt, müsst Ihr nach Ironforge zurück und persönlich mit Roetten sprechen. Er dürfte froh sein, wenn er Leftwitchs Päckchen vom Hals hat. Gebt ihm das, es müsste genügen, damit Ihr Euren Anteil bekommt.$B$BKeine Bange, ich werde trotzdem ein gutes Wort für Euch einlegen, wenn ich zurück bin. Ich sollte nicht mehr lange in Desolace bleiben müssen.",objectives={"Bringt Leftwitchs Päckchen zu Roetten Stonehammer in Ironforge zurück."}]])
R(1468,"Die Kinderwoche",[[description="Ihr wollt uns tatsächlich hier im Waisenhaus zur Hand gehen? Seid gesegnet, Freund. Eure Unterstützung in der Kinderwoche ist für uns von unschätzbarem Wert.$B$BNehmt diese Pfeife. Sie kann sieben Tage lang verwendet werden - über die ganze Dauer der Kinderwoche hinweg. Durch Benutzung der Pfeife, könnt Ihr mit dem Waisenkind sprechen, auf das Ihr aufpasst. Verwendet sie erneut, um das Kind wieder zu entlassen.$B$BDas Kind ist schon ganz aufgeregt und freut sich darauf Euch kennenzulernen. Worauf wartet Ihr noch $n, benutzt die Pfeife und trefft Euren Schützling.",objectives={"Benutzt die Pfeife des Menschenwaisenkindes um während der Kinderwoche mit Eurem Schützling zu sprechen."}]])
R(1469,"Rhapsodys Geschichte",[[description="Vor dem Flug trank ich ein ganzes Fass Starkbier. Hicks!$b$bUnd was für ein Flug das war. Ich sauste herum und Brohann folgte mir. Aber ich hab keinen Tempel nicht gesehen. Hicks!$b$bJedenfalls sah ich keinen Tempel, bis mir schwindlig wurde und ich von meinem Reittier fiel. Ich fiel kopfüber ins Wasser und wurde in die Tiefe gesogen. Dort sah ich mich von einer Schar unheimlicher Trolle umringt. Ich schwamm, was das Zeug hielt! Und schaffte es sogar mit diesem Trollsouvenir da raus. Hier, bringt es Brohann und lasst ihn wissen, dass der Tempel tatsächlich da unten ist. Hicks!",objectives={"Bringt das Schrifttafelfragment der Atal'ai zu Brohann Caskbelly in Stormwind."}]])
R(1470,"Der zerrissene Schleier",[[description="Seid gegrüßt, Kind. Ich sehe, dass Ihr noch unerfahren in den Dingen der Hexenmeister seid, dass sich die Macht noch Eurem Griff entzieht. Doch ich spüre Euren Eifer zu lernen.$b$bUnd Ihr werdet lernen.$b$bDurch Ignoranz kann man keine Stärke finden. Wissen ist unsere größte Macht. Indem wir es anwenden, können wir die chaotische Magie und die Wesen der Leere kontrollieren und unserem Willen beugen.$b$bIch zeige Euch, wie Ihr einen Diener an Euren Willen bindet, doch zuerst müsst Ihr mir drei Schädel der klappernden Skelette nahe der verlassenen Schmiede bringen.",objectives={"Bringt Venya Marthand 3 Schädel eines klappernden Skeletts."}]])
R(1471,"Die Bindung",[[description="Gewiss habt Ihr den Kreis der Beschwörung unter uns bemerkt. Nur dort könnt Ihr einen ungebundenen Leerwandler herbeirufen.$b$bMit diesen Runen könnt Ihr ihn herbeirufen, dann müsst Ihr ihn durch die Kraft von Waffen und Magie beherrschen.$b$bWenn er unterworfen wurde, wird er Euch ergeben sein. Kommt dann zu mir und ich werde den Beschwörungszauber erklären, damit er Euch in jeder Hinsicht zu Willen ist.",objectives={"Beschwört mit Hilfe der Runen der Beschwörung einen Leerwandler, unterwerft ihn und bringt die Runen der Beschwörung dann zu Carendin Halger im Tempel der Verdammten zurück."}]])
R(1472,"Verschlinger der Seelen",[[description="Ein Sukkubus ist ein Verschlinger von Seelen, Zerstörer von Herzen, Versucher der Menschen. Eine durch und durch böse und engstirnige Kreatur.$b$bOhne Anreiz kann er nicht in unsere Welt gebracht werden.$b$bDoch wir wenden seine eigene Kraft gegen ihn an. Den Herzen guter, reiner oder liebender Männer kann der Sukkubus nicht widerstehen und tritt in unsere Welt herüber. Dann könnt Ihr ihn beherrschen und zu Eurem Eigen machen.$b$bSprecht mit meinem Assistenten Godrick Farsan im Tempel. Er hilft Euch bei der Suche nach einem Köder.",objectives={"Sprecht mit Godrick Farsan im Tempel der Verdammten."}]])
R(1473,"Kreatur der Leere",[[description="Alle scheinen sich einig, dass Ihr nunmehr bereit seid zu lernen, wie man einen Leerwandler beschwört.$b$bEin aus dem jenseitigen Chaos erschaffenes Wesen - wenn Ihr eines beschwört, es aber nicht kontrollieren könnt, zerreißt es Euch.$b$bEgalin beschwor den ersten Leerwandler und hielt in seinem Zauberfoliant fest, wie es bewerkstelligt wird.$b$bLeider wurde er uns von einem Agenten des Scharlachroten Kreuzzugs gestohlen, der ihn in seinem Stützpunkt in einem Turm im Westen versteckte. Bringt ihn mir und ich lehre Euch das Wissen.",objectives={"Beschafft Egalins Zauberfolianten und bringt ihn zu Carendin Halgar in den Tempel der Verdammten."}]])
R(1474,"Die Bindung",[[description="Benutzt diese Herzen und wirkt einen Zauber am Beschwörungskreis, um eine Tür zu öffnen, durch die der Sukkubus kommen kann. Eure Mächte sind jetzt größer und Ihr werdet sie alle brauchen, um den Sukkubus zu besiegen. $b$bHütet Euch vor seinen Bezauberungen, $n, manch starker Geist wurde schon seinem Willen unterworfen. Wenn er überwunden wurde, kehrt der Sukkubus in die Leere zurück, dann lehre ich Euch den Zauber, um ihn nach Eurem Gutdünken zurückzurufen.",objectives={"Beschwört mit Hilfe der reinen Herzen einen Sukkubus, unterwerft ihn und bringt die reinen Herzen dann zu Carendin Halger im Tempel der Verdammten zurück."}]])
R(1475,"Im Tempel von Atal'Hakkar",[[description="Der Legende zufolge ist der Tempel von Atal'Hakkar ein heiliger Schrein, der dem alten Gott Hakkar dem Seelenschinder geweiht ist. Der Tempel, der von einem tückischen Trollstamm namens Atal'ai unterhalten wird, soll angeblich uneinnehmbar sein.$B$BDa der Tempel jetzt im Tränenteich versunken ist, dürfte es noch schwieriger sein, Artefakte zu bergen. Aber genau das müsst Ihr tun, $n.$B$BHelft mir dabei, indem Ihr die intakten Schrifttafeln der Atal'ai sammelt. Bringt sie mir und ich schicke der Forschergilde einen Helden zurück. Wir werden uns den Ruhm teilen.",objectives={"Sammelt 10 Schrifttafeln der Atal'ai für Brohann Caskbelly in Stormwind."}]])
R(1476,"Herzen der Reinen",[[description="Männer mit Ehre und Güte? Existiert so ein Mann?$b$bViele Recherchen waren erforderlich, doch durch Geschichten, die ich hörte, konnte ich zwei Männer finden, die genügen sollten.$b$bDer Erste ist Dalin Forgewright, der sich der Fürsorge für die Flüchtlinge von Lordaeron verschrieben hat, die von ihresgleichen am Greymane-Wall verstoßen werden.$b$bDer andere ist Comar Villard, ein Mann, der seiner verlorenen Liebsten treu blieb und im Sumpfland nach Spuren seiner Frau sucht.$b$bBringt ihre Herzen zu Carendin. Doch zuvor möchte ich Euch Eure Opfer zeigen.",objectives={"Bringt die Herzen von Dalin Forgewright und Comar Villard zu Carendin Halgar im Tempel der Verdammten."}]])
R(1477,"Überaus wichtige Vorräte",[[description="Unsere Magier führen Forschungen in der Burg Nethergarde in den Verwüsteten Landen durch, die entscheidend für unser Verständnis der Dunklen Portale sind. Sie benötigen fast ununterbrochen Nachschub, doch unsere Nachschubwege nach Nethergarde sind dürftig.$B$BIhr müsst helfen sicherzustellen, dass der Nachschub nach Nethergarde gelangt. Meldet Euch bei Wachhauptmann Sorigal in Dunkelhain und tut, was er verlangt. Diese Aufgabe führt Euch in Feindesland, $n. Macht Euch bereit.",objectives={"Sprecht mit Wachhauptmann Sorigal."}]])
R(1478,"Halgars Beschwörung",[[description="Ah, $n! Carendin Halgar ließ mich soeben wissen, dass er Euch für weitere Ausbildung sehen möchte.$b$bIhr solltet stolz auf Euch sein, $n Es kommt nicht jeden Tag vor, dass Meister Halgar persönlich einen jungen Hexenmeister unterrichtet.$b$bIhr findet ihn im Magieviertel von Undercity nahe des Tempels der Verdammten.",objectives={"Sprecht mit Carendin Halgar in Undercity."}]])
R(1479,"Der Baum der Ewigen",[[description="Ich habe Geschichten von den Nachtelfen gehört, darüber, dass sie ihre Bank in einen Baum gebaut haben, der aber wie ein Bär aussieht. Das ist so cool! Nachtelfen sind niedlich, wie sie die Natur lieben und so, aber Bären sind der Hammer!$B$BWürdet Ihr bitte mit mir den Bärenbaum in Darnassus angucken gehen? Es gibt ein Boot, das uns ganz in die Nähe dorthin bringt und es wird auch bestimmt nicht lange dauern. Bitte, bitte, bitte!",objectives={"Begleitet Euren Schützling zur Bank in Darnassus. Die dortige Bank ist in einen Baum gebaut, welcher als der Baum der Ewigen bekannt ist."}]])
R(1480,"Der Verderber",[[description="Die zerrissene Haut riecht verfault und ist erstaunlich geschmeidig für etwas, das so trocken und zerbrechlich wirkt.$B$BAls Ihr sie aufrollt, könnt Ihr deutlich die roten Zeichen einer Art Sprache auf der einen Seite erkennen. Am unteren Ende der Haut befindet sich ein sehr deutliches Symbol, das Ihr für eine Art Unterschrift haltet.$B$BVielleicht könnte Maurin Euch mehr darüber erzählen?",objectives={"Bringt die geschundene Dämonenhaut nach Desolace zu Maurin Bonesplitter."}]])
R(1481,"Der Verderber",[[description="Ich denke, mit den entsprechenden Reagenzien kann ich diesen Dämonenlord finden.$B$BWenn er wirklich so mächtig ist, wie ich vermute, brauche ich gesammelte Gegenstände von tödlichen Kreaturen. Doch Ihr handelt im Namen des Kriegshäuptlings, daher werdet Ihr die Aufgabe gewiss übernehmen.$B$BAls Erstes muss ich jeden Schutzzauber brechen, den er gegen Wahrsagen hat. Daher brauche ich den Skalp eines Satyrs... aber nicht den eines beliebigen Satyrs. Der Skalp muss von einem Schattenpirscher der Zornsäer stammen.$B$BSucht in den antiken Ruinen nordöstlich von Desolace nach ihnen.",objectives={"Bringt Maurin Bonesplitter in Desolace einen Schattenpirscherskalp."}]])
R(1482,"Der Verderber",[[description="Ein Orakelkristall wäre genau richtig. Die Naga stellen sie her, damit ihre Orakel sie benutzen können.$B$BNordwestlich von hier liegt ein großes Korallenriff vor der Küste, das die Naga als ihre Heimat nutzen, da es so nahe am Ufer liegt. Dort könnt Ihr ihre Orakel finden. Die Zackenkammnaga sind tödlich und reagieren ungnädig auf Euer Eindringen, seid daher vorsichtig und eilt Euch.$B$BWenn Ihr zurückkehrt, suchen wir diesen Dämonenlord Azrethoc.",objectives={"Bringt Maurin Bonesplitter in Desolace einen Orakelkristall."}]])
R(1483,"Ziz Fizziks",[[description="Die Venture Company stahl viele meiner besten Goblin-Denker, aber von Zeit zu Zeit bekommen wir Gelegenheit, einige zurückzustehlen.$b$bVor einiger Zeit stellte die Filiale der Venture Company im Steinkrallengebirge Gerenzo Wrenchwhistle ein... einen Gnom! Ihr anderer Ingenieur, Ziz Fizziks, war so erschüttert davon, dass er mich anflehte, ihm eine neue Stelle beim Tüftlerverband zu besorgen. Ich gab ihm einige Aufgaben, aber möglicherweise braucht er dabei Hilfe.$b$bVielleicht könntet Ihr mal nach dem Rechten sehen? Er ist am Westrand der Scherwindklippe stationiert.",objectives={"Sprecht mit Ziz Fizziks bei der Scherwindklippe."}]])
R(1484,"Der Verderber",[[description="Diese Kreatur ist weitaus gefährlicher als ich dachte. Zweifellos stellt Takata in Frage, dass ich so einer Kreatur gewachsen bin, und es würde ihn in seiner Ehre kränken, wenn er nicht wüsste, was gerade passierte.$B$BSprecht mit dem Schwertkämpfer, sagt ihm, Ihr seid bereit, den Dämon zu erschlagen, wenn er es erlaubt, aber bedrängt ihn nicht zu sehr. Es ist besser, wenn er denkt, dass es seine Idee war.",objectives={"Sprecht mit Takata Steelblade in Desolace."}]])
R(1485,"Üble Familiare",[[description="Die Hexenmeister, die vor uns kamen, weckten das Misstrauen der Horde. Man toleriert uns zwar, aber man liebt uns nicht.$b$bDas ließ die Hexenmeister freilich nicht näher zusammenrücken, da viele in Abgeschiedenheit leben und ihre Magie allein erforschen. Ich will Euch nicht auf den einen oder anderen Weg führen, sondern nur helfen, reifer zu werden.$b$bBevor ich Euch die Kunst des Beschwörens lehre, bringt mir sechs Köpfe der schändlichen Familiare aus der Höhle im Nordosten.",objectives={"Bringt 6 Köpfe schändlicher Familiare zu Ruzan."}]])
R(1486,"Deviatbälge",[[description="Als Naralex tiefer in seinen Alptraum vorstieß, stieg eine seltsame Schar von Bestien unter dem Brachland in die Höhlen des Wehklagens vor.$b$bDiese Deviatkreaturen haben seltsame, überirdische Eigenschaften. Sie sind zwar von Natur aus böse, doch bin ich der Meinung, dass ihre Existenz hier in Kalimdor auch etwas Gutes haben kann. Ich glaube, ihre Bälge sind besonders gut für die Lederverarbeitung geeignet.$b$bWenn Ihr Euch der Aufgabe gewachsen fühlt, steigt in die Höhlen unter uns hinab und holt einige Deviatschuppen.",objectives={"Nalpak in den Höhlen des Wehklagens möchte 20 Deviatbälge."}]])
R(1487,"Ausrottung der Deviat",[[description="Naralex hatte ein edles Ziel.$b$bUnser großer Anführer trachtete danach, in den Smaragdgrünen Traum zu gelangen und dabei zu helfen, aus diesem kargen Land wieder den üppigen Wald zu machen, der hier einst wuchs. Aber etwas ist furchtbar schief gegangen.$b$bNaralex' Traum wurde zum Alptraum. Verderbte Kreaturen siedelten sich in den Höhlen an.$b$bWährend einige Jünger von Naralex versuchen, unseren Meister zu wecken, ist es mein Trachten, die Höhlen von diesen bösen Bestien zu befreien.$b$bWagt Euch in die Höhlen, $n, und löscht die Deviatbrut aus.",objectives={"Ebru in den Höhlen des Wehklagens möchte, dass Ihr 7 Deviatverheerer, 7 Deviatvipern, 7 Deviatschlurfer und 7 Deviatschreckensfange tötet."}]])
R(1488,"Der Verderber",[[description="Wiewohl ich nichts über diesen Lord Azrethoc weiß, stimme ich mit Maurin überein, er muss aufgehalten werden. Besonders wenn er versucht, Einfluss über die Burning Blade zu bekommen, um seine Ziele voranzutreiben.$B$BIhr habt schon gezeigt, dass Ihr den Kriegshäuptling unterstützen möchtet. Ich verlasse mich darauf, dass Ihr eine Truppe zusammenstellt, die den Dämonenlord und seinen Hexenmeisterdiener besiegt.$B$BWenn Ihr bereit seid, geht direkt nach Süden und kehrt zu mir zurück, wenn die Bedrohung beseitigt wurde.",objectives={"Besiegt Lord Azrethoc und Jugkar Grim'rod. Kehrt dann zu Takata Steelblade in Desolace zurück."}]])
R(1489,"Hamuul Runetotem",[[description="Die Schalen, die Ihr mir gebracht habt, haben eine Besudelung, eine, die ich nie zuvor gesehen habe. Ich bin mir sicher, dass das Wasser der Oasen der Grund dafür ist. Ich spüre die Verwirrung, die sie über das Land bringen. Es ist, als würde das Land träumen und nicht erwachen können.$B$BDie Höhlen des Wehklagens müssen die Quelle dieser Besudelung sein. Doch ehe Ihr dorthin geht, solltet Ihr mit dem Druidenältesten Hamuul Runetotem sprechen. Ich ließ ihn über die Vorfälle im Brachland informieren. Er ist weise und kann Euch Rat geben.$B$BIhr findet ihn in Thunder Bluff auf der Anhöhe der Ältesten.",objectives={"Sprecht mit Hamuul Runetotem."}]])
R(1490,"Nara Wildmane",[[description="Ich betrat das Land der Träume und träumte von einem Druidenkult, der in den Höhlen des Wehklagens haust. Ich sah, dass ihre Ziele einst edel waren, sie jedoch vom rechten Weg abkamen. Sie sind jetzt Diener der Besudelung, die das Brachland befallen hat.$B$BIch bin alt und meine Kraft verlässt mich. Ich konnte nicht lange an diesem Traumort verweilen und weiß wenig mehr von den besudelten Druiden. Aber Nara ist jung und starken Willens. Sie blieb in dem Traum zurück, als ich floh.$B$BSprecht mit Nara. Sie ist in jenem Zelt da drüben.",objectives={"Sprecht mit Nara Wildmane."}]])
R(1491,"Klugheitstränke",[[description="Nun gut, die Raptorenhörner haben nicht funktioniert. Aber das macht nichts... nicht alles klappt beim ersten Mal! Außerdem habe ich wohl etwas gefunden, das in meinen Klugheitstränken noch besser funktioniert!$B$BEs gibt eine Substanz, die Klageessenz genannt wird. Ich glaube, sie ist die Ursache für die seltsamen Pflanzen und Tiere im Brachland. Bringt mir etwas davon, dann erprobe ich es in meinem Trank!$B$BIch hörte, die Essenz reichert sich in Ektoplasmakreaturen in den Höhlen des Wehklagens im Westen an. Jagt diese Kreaturen und sammelt die Essenz.",objectives={"Bringt 6 Portionen Klageessenz zu Mebok Mizzyrix in Ratchet."}]])
R(1492,"Werftmeister Dizzywig",[[description="Ich muss eine Kiste mit Tränken, Reagenzien und anderen Gegenständen zu meinen Geschäftspartnern in der alten Welt schaffen. Ich habe kaum Zeit, sie selbst zum Dock von Ratchet zu bringen, und die letzte Karawane ist schon aufgebrochen.$b$bKönntet Ihr sie bitte freundlichst zu Werftmeister Dizzywig bringen? Er wird dafür sorgen, dass sie an Bord des nächsten Schiffes zur Schwarzmeerbucht kommt.",objectives={"Bringt die gesicherte Kiste zu Werftmeister Dizzywig in Ratchet."}]])
R(1498,"Weg der Verteidigung",[[description="Als Krieger ist eine unserer wichtigsten Aufgaben... der Schutz. Wir sind der Schild der Horde und sorgen für die Sicherheit unserer schwächeren Brüder. Wenn Ihr Euch bei uns einreihen möchtet, müsst Ihr mir Eure Tauglichkeit beweisen.$B$BGeht zum Donnergrat in Durotar, wo die Blitzechsen und Donnerechsen hausen. Jagt die Bestien! Zeigt mir, dass Ihr härter als sie seid! Trotzt ihren Angriffen und bringt mir einen Stapel ihrer versengten Schuppen als Beweis.$B$BGelingt Euch das, unterrichte ich Euch.",objectives={"Bringt 5 versengte Schuppen zu Uzzek im Farwatch-Posten im Brachland."}]])
R(1499,"Üble Familiare",[[description="Zureetha hat Novizen wie Euch geschickt, damit sie helfen, die Zahl der Kreaturen in der Höhle einzudämmen, in deren Nähe Ihr gegen die schändlichen Familiare gekämpft habt.$b$bIch finde, es wäre gut für Euch, wenn Ihr Erfahrung sammelt, indem Ihr ihr helft. Erwähnt unbedingt, dass Ihr mitgeholfen habt, das Wichtel-Problem zu lösen, womöglich hat sie eine Belohnung für Euch.",objectives={"Sprecht mit Zureetha Fargaze."}]])
R(1500,"Waking Naralex")
R(1501,"Kreatur der Leere",[[description="So wenige Hexenmeister sind übrig... Wir riskieren viel, doch die Risiken sind gerechtfertigt. Ihr müsst bald Reife in Eurer Fähigkeit erlangen, wenn Ihr der Horde und dem Kriegshäuptling nützlich sein wollt.$b$bEs ist Zeit, dass Ihr einen neuen Beschwörungszauber lernt.$b$bAls Erstes müsst Ihr die Schrifttafel der Verga wiederbeschaffen, die von Hexenmeistern der Burning Blade gestohlen wurde und nun in ihrem Unterschlupf in der Knochenhöhle verwahrt wird. Mit der Tafel zeige ich Euch die Runen, mit denen ein Leerwandler beschworen wird.",objectives={"Holt die Schrifttafel der Verga für Gan'rul Bloodeye in Orgrimmar."}]])
R(1502,"Thun'grim Firegaze",[[description="Es ist wichtig, dass ein Krieger eine hochwertige Waffe hat. Und wenn es einen Orc gibt, der hochwertige Waffen herstellen kann, dann ist das Thun'grim Firegaze. Er ist ein Einsiedler, der auf den Hügeln östlich von Crossroads haust.$B$BWenn Ihr eine Waffe sucht, Krieger, dann solltet Ihr Euch an Thun'grim wenden. Um ihn zu finden reist Ihr zuerst nach Crossroads im Westen und wendet Euch dann nach Osten in die Berge. Sein Lager liegt hoch auf einem Berggipfel.",objectives={"Sprecht mit Thun'grim Firegaze im Brachland."}]])
R(1503,"Geschmiedeter Stahl",[[description="Ich gebe Euch eine Waffe, $N, doch vorher müsst Ihr mir helfen. Vor einigen Nächten kamen die Grimmhauer von Nordwesten in mein Lager. Sie wollten nicht mit mir kämpfen, wissen aber, wie schlecht es um mein Augenlicht bestellt ist. Einige lenkten mich durch Schnauben ab, während die anderen mich bestahlen. Diese Feiglinge!$B$BSie nahmen eine Eisentruhe mit, in der sich Schmiedestahlbarren befanden. Wenn Ihr sie wiederbeschaffen könnt, bekommt Ihr die Waffe, die Ihr sucht.$B$BSucht im Stacheleberlager nach der Eisentruhe und bringt die Schmiedestahlbarren zurück.",objectives={"Bringt die Schmiedestahlbarren zu Thun'grim Firegaze im Brachland."}]])
R(1504,"Die Bindung",[[description="Nun studiert die Schrifttafel der Verga, denn sie enthält die Glyphen, die Ihr für die Beschwörung braucht. Bringt sie zu dem Kreis in Neeru Fireblades Zelt auf der anderen Seite der Höhle. Dort könnt Ihr den Leerwandler herbeirufen.$b$bIhr müsst ihn mit allen körperlichen und magischen Mitteln besiegen, die Euch zur Verfügung stehen. Wenn das vollendet ist, kommt mit den Glyphen der Beschwörung zu mir zurück und ich führe Euch vor, wie Ihr die Kreatur an Euren Willen bindet.",objectives={"Beschwört mit Hilfe der Glyphen der Beschwörung einen Leerwandler, unterwerft ihn und bringt dann die Glyphen der Beschwörung zu Gan'rul Bloodeye in Orgrimmar zurück."}]])
R(1505,"Veteran Uzzek",[[description="Die Horde ehrt ihre Krieger, da ihre Kraft außer Frage steht. Doch die wahrhaft großen Helden sind auch große Schüler.$B$BSucht nach Uzzek. Er ist ein Veteran zahlreicher Kämpfe und unterrichtet jetzt junge Krieger in der Gefechtskunst. Ihr findet ihn südlich des Farwatch-Posten, der Orc-Garnison an der Grenze von Brachland und Durotar im Osten.",objectives={"Sprecht mit Uzzek im Farwatch-Posten."}]])
R(1506,"Gan'ruls Beschwörung",[[description="Ihr da. $n, richtig?$b$bIch hoffe, Ihr seid nicht zu sehr beschäftigt, denn Gan'rul möchte Euch unverzüglich sprechen. Ihr findet ihn mit den Hexenmeisterältesten in der Kluft der Schatten.$b$bMeinen früheren Erfahrungen mit Gan'rul nach zu urteilen, bedeutet Eure Einbestellung entweder etwas sehr Gutes oder etwas sehr Schlechtes.",objectives={"Sprecht mit Gan'rul Bloodeye in Orgrimmar."}]])
R(1507,"Verschlinger der Seelen",[[description="Eure Zeit ist gekommen, mehr über die Beschwörungsmagien zu lernen. Ihr werdet lernen, einen Sukkubus zu beschwören, eine Kreatur mit unglaublichen geistigen Mächten. Er kann sich schwache Geister zu Diensten machen... doch seid unbesorgt! Ich bin sicher, Ihr seid der Herausforderung gewachsen.$b$bEin Sukkubus kann nur beschworen werden, wenn man ihn mit einem Gegenstand ködert, der große Hingabe und Liebe bedeutet. Ich überlasse es Euch, so ein Objekt zu finden.$b$bEin Vorschlag? Sprecht mit Cazul... Es scheint wenig zu geben, das der alte Hexenmeister nicht weiß.",objectives={"Sprecht mit Cazul in der Kluft der Schatten."}]])
R(1508,"Der blinde Cazul",[[description="Hmmm... Aber natürlich seid Ihr nicht gekommen, um deshalb mit mir zu sprechen.$b$bWenn Gan'rul Euch zu mir geschickt hat, dann gewiss, weil Ihr einen Sukkubus beschwören sollt und einen Gegenstand braucht, um ihn anzulocken.$b$bHmm... Wenn Ihr Euch von einem Blinden führen lassen möchtet, $n, dann hört zu. In den Hängen von Orgrimmar, westlich des Himmelsturms im Tal der Stärke, lebt Zankaja. Sie wartet darauf, dass ihr Lebensgefährte zurückkehrt.$b$bGeht zu ihr.",objectives={"Sprecht mit Zankaja in Orgrimmar."}]])
R(1509,"Neuigkeiten von Dogran",[[description="Dogran, mein Gefährte, wurde jüngst zum Dienst nach Crossroads geschickt. Es war eine Beförderung und er war sehr stolz.$b$bIch war natürlich traurig, ließ es ihn aber nicht wissen. Und auch besorgt. Das Brachland ist gefährlicher als Orgrimmar, daher fürchtete ich das Schlimmste.$b$bSeit einer Woche sollte er nun schon zu Hause sein und ich habe kein Wort von ihm gehört...$b$bVielleicht könntet Ihr nach Crossroads gehen und nachfragen, ob es Neuigkeiten gibt? Er arbeitete mit Gazrog, der noch dort stationiert sein sollte.",objectives={"Sprecht mit Gazrog in Crossroads."}]])
R(1510,"Neuigkeiten von Dogran",[[description="Er war im Camp Taurajo stationiert, wo wir versuchten, die Stacheleber auszurotten. Er führte ein paar Grunzer zu einem ihrer Lager, wo er schwer verwundet wurde. Die anderen schafften es zurück und versuchten, ihn zu retten. Er war in einem schlimmen Zustand, seine Wunden eiterten, daher wollten sie ihn nicht mitnehmen, ohne ihn erst zu versorgen.$b$bSie schickten eine Nachricht hierher und baten um ein Heilgebräu von den Trollen der Malaka'jin im Steinkrallengebirge. Wir schickten Leute, um eines zu holen, aber diese sind noch nicht zurückgekehrt.",objectives={"Sprecht mit Ken'zigla am Malaka'jin."}]])
R(1511,"Ken'ziglas Trunk",[[description="Ich dachte mir, dass ein anderer kommen würde, um den Trunk zu holen, daher habe ich ihn dennoch vorbereitet.$b$bDa habt Ihr ihn, $n. Aber denkt daran, Ihr solltet ihm nur die Hälfte geben! Dadurch bekommt er genug Kraft, sich zu bewegen, ohne dass er verblutet. Wartet eine Nacht und gebt ihm dann die andere Hälfte.$b$bWie auch immer, Ihr solltet dies zu Logmar im Camp Taurajo bringen. Nach allem, was er mir gesagt hat, sollte er wissen, wo dieser Dogran ist.",objectives={"Bringt Ken'ziglas Trunk zu Grunzer Logmar im Camp Taurajo."}]])
R(1512,"Die Liebesgabe",[[description="Zankaja ist jung und wunderschön. An einen Invaliden gekettet zu sein... Ich dulde nicht, dass ihr diese Ungerechtigkeit widerfährt.$b$bLasst mich allein, $n. Und habt Dank. Vielleicht beende ich mein Leben im ruhmreichen Kampf statt als leblose Hülle.$b$bUnd bitte erzählt meiner Gefährtin nichts davon... Ich möchte nicht, dass sie sich Schuld auflädt.",objectives={"Bringt den schmutzverkrusteten Anhänger zu Gan'rul Bloodeye in Orgrimmar."}]])
R(1513,"Die Bindung",[[description="Bringt dies zum Beschwörungskreis in Neerus Zelt, $n. Beschwört einen schändlichen Sukkubus und zeigt ihm Eure Überlegenheit. Ich glaube an die Kraft Eurer Magie. Aber seid wie stets wachsam, denn Stolz und Selbstüberschätzung wurden manchem viel versprechenden Hexenmeister zum Verhängnis.$b$bWenn Ihr ihn besiegt habt, bringt den Anhänger zu mir, damit ich Zankaja die Neuigkeit überbringen kann.",objectives={"Beschwört mit Hilfe von Dograns Anhänger einen Sukkubus, unterwerft ihn und bringt dann Dograns Anhänger zu Gan'rul Bloodeye in Orgrimmar zurück."}]])
R(1514,"Verderbte Windblüte")
R(1515,"Dograns Gefangenschaft",[[description="Ihr habt es bis hierher geschafft, wenn Ihr es bis zu Ende durchstehen möchtet, werde ich Euch nicht aufhalten. Aber ich kann keine Leute erübrigen, Ihr seid also auf Euch allein gestellt.$b$bDogran wird in einem Lager der Stacheleber nördlich von hier festgehalten. Sucht nach zwei nebeneinander stehenden Hütten. Er wird schwer bewacht... Das heißt, wenn sie ihn noch nicht getötet haben oder er seinen Verletzungen erlegen ist.$b$bViel Glück.",objectives={"Bringt Ken'ziglas Trunk zu Dogran im Brachland."}]])
R(1516,"Ruf der Erde",[[description="Die Zeit ist gekommen, junger $C. Ihr seid stark geworden und Euer Geist ist ausdauernd wie die Erde. Dass Ihr dem Pfad des Schamanen folgt, zeigt, dass Ihr Weisheit besitzt, sogar bevor Ihr Euch selbst beweist.$B$BDas Element der Erde wird über Euer Schicksal wachen und Teil von Euch werden, wenn Ihr bereit seid. Doch Ihr müsst vor der Erde selbst bestehen. Wenn Ihr bereit seid, werdet Ihr Dinge sehen, von denen nur Schamanen wissen.$B$BSucht die Teufelspirscher im Norden und beschafft Euch zwei ihrer Hufe. Kehrt dann zu mir zurück und wir sprechen weiter über Eure Zukunft.",objectives={"Bringt 2 Teufelspirscherhufe zu Canaga Earthcaller im Tal der Prüfungen."}]])
R(1517,"Ruf der Erde",[[description="Ein Sapta ist ein Getränk, mit dem unsere Seelen an die Elemente gebunden werden. Mit Magie gestärkt lässt dieser Trank die Willensstarken die Elemente sehen, wie es sonst niemand kann. Euer Geist wird mit dem Element verbunden, für das das Sapta geschaffen wurde. Nur wenige auserwählte Schamanen kennen das Rezept.$B$BDas Sapta wird stets an einem heiligen Ort getrunken, niemals anderswo ... vergesst das nicht.$B$BBesucht den Geisterfelsen südwestlich von hier ... er befindet sich am Ende des verborgenen Pfades. Trinkt Euer Sapta dort und ... tja, Ihr werdet schon sehen.",objectives={"Sucht den Geisterfelsen und trinkt das Erdsapta."}]])
R(1518,"Ruf der Erde",[[description="Nehmt diesen Rohquarz von mir und bringt ihn als Beweis für unsere Begegnung zu Canaga Earthcaller. Er wird ein Totem für Euch anfertigen, dessen Herzstück dieser Kiesel sein soll. So winzig er scheinen mag, Ihr werdet feststellen, dass es nicht auf die Größe ankommt und selbst die kleinsten Dinge viele anderen überdauern können.$B$BHabt Geduld, $N. Bleibt stark und sucht Weisheit. Dies verlangt die Erde von Euch. Am Ende solltet Ihr eins mit der Erde werden... respektiert sie so, wie sie Euch respektiert.",objectives={"Bringt den Rohquarz zu Canaga Earthcaller im Tal der Prüfungen."}]])
R(1519,"Ruf der Erde",[[description="Die Zeit ist gekommen, $C. Euer Körper ist ausgereift und stark geworden und Euer Geist ist ausdauernd wie die Erde. Ich sehe es Euch an... Ihr besitzt bereits Weisheit.$B$BDie Erde leitet unser Volk und spricht zu uns... und bald auch zu Euch. Aber Ihr müsst geprüft werden. Wenn Ihr bereit seid, werdet Ihr Dinge sehen, von denen nur unsere Art weiß.$B$BSucht die Schamanen der Borstennacken in ihrer Klamm im Osten auf und beschafft Euch eine ihrer Salben, die sie für ihre Rituale verwenden. Kehrt erst zu mir zurück, wenn Ihr genügend davon für Euren eigenen Trank habt.",objectives={"Bringt 2 Dosen Ritualsalbe zu der Seherin Ravenfeather im Camp Narache."}]])
R(1520,"Ruf der Erde",[[description="Ein Sapta ist ein Getränk, mit dem unsere Seelen an die Elemente gebunden werden. Mit Magie gestärkt lässt dieses Elixier die, die offenen Geistes sind, die Elemente sehen, wie sie zuvor noch von niemandem gesehen wurden. Euer Geist wird ewig an das Element gebunden, für das das Sapta geschaffen wurde. Nur wenige Auserwählte unserer Art kennen das Geheimnis seiner Herstellung.$B$BDas Sapta wird stets an einem heiligen Ort getrunken und niemals anderswo.$B$BSucht den Schamanenschrein östlich von hier und trinkt von dem Sapta.",objectives={"Sucht den Kodofels und trinkt das Erdsapta."}]])
R(1521,"Ruf der Erde",[[description="Nehmt diesen Rohquarz von mir und bringt ihn als Beweis für unsere Begegnung zu der Seherin Ravenfeather. Sie wird ein Totem für Euch anfertigen, dessen Herzstück dieser Kiesel sein soll. So winzig er scheinen mag, Ihr werdet feststellen, dass es nicht auf die Größe ankommt und selbst die kleinsten Dinge Berge überdauern können.$B$BHabt Geduld, $N. Bleibt stark und sucht Weisheit. Dies verlangt die Erde von Euch. Am Ende solltet Ihr eins mit der Erde werden... respektiert sie so, wie sie Euch respektiert.",objectives={"Bringt den Rohquarz zu der Seherin Ravenfeather im Camp Narache."}]])
R(1522,"Ruf des Feuers",[[description="Feuer sei mit Euch, Mann. Ich sehe, Ihr seid schon bewandert in den Wegen der Erde und scheint mir bereit, mit Kranal zu sprechen.$B$BKranal lebt nördlich von Crossroads im Brachland. Er kennt sich mit den Elementen aus und kann Euch was übers Feuer beibringen ... wenn Ihr denkt, dass Ihr bereit seid.$B$BEr ist leicht zu finden, geht nur nicht zu weit. Wenn Ihr zu weit geht, seid Ihr plötzlich im Elfenland.",objectives={"Sucht Kranal Fiss im Brachland."}]])
R(1523,"Ruf des Feuers",[[description="Es ist lange her, seit Ihr zuletzt geprüft wurdet, $N. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über Zerstörung zu lernen... und über Chaos. Ihr könnt das Element des Feuers verstehen lernen, wenn Ihr bereit seid, dafür zu bezahlen.$B$BSucht nach Kranal Fiss im Brachland. Er lebt in einer kleinen Siedlung nördlich von Crossroads, aber gebt Acht, wenn Ihr das Land der Nachtelfen erreicht, seid Ihr zu weit gegangen.",objectives={"Sucht Kranal Fiss im Brachland."}]])
R(1524,"Ruf des Feuers",[[description="Ihr seid mächtig genug, das Totem des Feuers zu tragen, doch bedeutet das nicht, dass Ihr bereit seid.$B$BAm Südstromfluss in Durotar, vor dem großen Meer, liegt ein verborgener Pfad zu einem der höchsten Gipfel des Landes. Sucht einen Weg nach oben. Dann werdet Ihr einen unserer heiligen Schreine finden, den Telf Joolam bewacht ... den Schrein der schlafenden Flamme.$B$BBringt ihm diese Fackel ... sie zeigt, dass Ihr versucht, das Feuer zu bändigen. Bringt sie mir zurück, wenn Ihr sie an der Kohlenpfanne des Schreins entzündet habt, und ich sorge dafür, dass Ihr das Totem des Feuers bekommt.",objectives={"Bringt die Fackel der schlafenden Flamme zu Telf Joolam in Durotar."}]])
R(1525,"Ruf des Feuers",[[description="Aber Ihr seid doch nicht zum Geschichtsunterricht hergekommen, oder? Ihr seid wegen der ewigen Flamme und einem Feuertotem gekommen.$B$BZunächst einmal müsst Ihr ein Sapta anfertigen und Euch selbst an das Feuer binden.$B$BIch kann das Feuersapta für Euch herstellen, wenn Ihr mir zwei Gegenstände bringt. Der Erste ist Feuerteer, ein einfacher Gegenstand, den normalerweise die Zauberer der Grimmhauer im östlichen Brachland mit sich führen.$B$BDer zweite Gegenstand dürfte gefährlicher zu bekommen sein: ein Reagenzienbeutel von einem Kultisten der Burning Blade. Ihr findet sie in einer Höhle über den Klammen nordöstlich von Klingenhügel.",objectives={"Bringt 1 Feuerteerstück und 1 Reagenzienbeutel zu Telf Joolam in Durotar."}]])
R(1526,"Ruf des Feuers",[[description="Das Feuersapta ist fertig. Die Zeit ist gekommen, dass Ihr Euch der Flamme stellt. Benutzt das Sapta am Schrein und geht zum Berggipfel, um Euch dort der Manifestation zu stellen. Er wird Euch erst angreifen, wenn Ihr bereit seid, wird aber wissen, dass Ihr ihn sehen könnt.$B$BSchlagt ihn schnellstens nieder, $n, denn seine Macht wächst, je länger Ihr braucht, um ihn zu besiegen. Wenn er bezwungen wurde, legt seine Glut in die Kohlenpfanne und entzündet die Fackel.",objectives={"Besiegt die geringe Feuermanifestation und legt Glut in die Kohlenpfanne auf dem Schrein der ewigen Flamme."}]])
R(1527,"Ruf des Feuers",[[description="Mit der Fackel fest in der Hand wendet Ihr Euch von der Kohlenpfanne ab und lasst den Blick über Durotar schweifen. Ihr spürt, wie Aufregung Euren Geist erfüllt, als der Wind anschwillt und die Flamme heftig flackern lässt.$B$BAuf der Suche nach Kranal Fiss betretet Ihr den Pfad zurück ins Brachland.",objectives={"Bringt die Fackel der ewigen Flamme zu Kranal Fiss im Brachland."}]])
R(1528,"Ruf des Wassers",[[description="Wasser sei in Eurer Zukunft, Mann. Ich sehe, Ihr seid schon bewandert in den Wegen des Feuers und scheint mir bereit, mit Islen zu sprechen.$B$BIslen lebt an der Küste des Brachlandes. Wenn Ihr am Ufer des Südstroms nach Süden geht, könnt Ihr sie gar nicht verfehlen ... achtet auf den großen Hai! Sie kennt sich mit den Elementen aus und kann Euch etwas übers Wasser beibringen ... wenn Ihr denkt, dass Ihr bereit seid.$B$BSie ist leicht zu finden, geht nur nicht zu weit nach Süden ... sie ist gleich hinter Ratchet.",objectives={"Sucht Islen Waterseer im Brachland."}]])
R(1529,"Ruf des Wassers",[[description="Es ist lange her, seit Ihr zuletzt geprüft wurdet, $N. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über die Reinheit des Wassers zu lernen.$B$BSucht nach Islen Waterseer im Brachland. Sie befindet sich an der Ostküste, südlich von Ratchet und dem Südstrom. Ihr findet sie in ihrer Fischerhütte. Viel Glück, $N.",objectives={"Sucht Islen Waterseer im Brachland."}]])
R(1530,"Ruf des Wassers",[[description="Wenn Ihr eine Lektion über Wasser lernen müsst, dann diese: Wasser bedeutet Wiedergeburt.$B$BSeine Macht fließt, erodiert und reinigt alle Arten von Dingen. Seine Fähigkeit zu heilen und zu regenerieren ist unvergleichlich, jedoch nur, wenn es rein ist.$B$BWenn Ihr begreift, dass verunreinigtes Wasser alles verheeren kann, was es berührt, werdet Ihr schätzen lernen, wie lebenswichtig dieser Rohstoff ist.$B$BWenn Ihr das Wassersapta möchtet, sucht Brine tief im Südlichen Brachland. Ihr Heim wird unablässig von den dortigen Stachelebern heimgesucht.",objectives={"Sucht Brine im südlichen Brachland."}]])
R(1531,"Ruf der Luft",[[description="Macht Euch auf den Weg, Mann. Ihr seid bereit, Euch des Lufttotems würdig zu erweisen, aber zuerst müsst Ihr Prate Cloudseer in Tausend Nadeln finden. Wenn Ihr sie mit ausreichend Respekt behandelt, wird sie bereit sein, Euch zu sagen, wie Ihr das Lufttotem bekommen könnt.$B$BGeht durch das Brachland nach Süden und weiter nach Osten, wenn Ihr Tausend Nadeln erreicht habt. Ihr werdet sie verborgen in einem Erdloch mit ihrem Liebsten finden - haha, sagt ihr nicht, dass ich schlecht über sie geredet habe - das mag sie nicht sonderlich.",objectives={"Sucht Prate Cloudseer in Tausend Nadeln."}]])
R(1532,"Ruf der Luft",[[description="Die Winde von Kalimdor wehen Euch entgegen und Ihr sollt zu den Mächtigsten unserer $gBrüder:Schwestern; gehören. Ich sehe mit Stolz, dass Ihr so weit gekommen seid und so eine viel versprechende Zukunft habt.$B$BDas Luftelement ist schwer zu kontrollieren, doch ich vertraue darauf, dass Eure Fertigkeiten alle Hindernisse überwinden, die Euch den Weg versperren.$B$BGeht zum äußersten Südrand des Brachlandes und betretet Tausend Nadeln. Dort, weit im Osten, werdet Ihr Prate Cloudseer finden. Sie wird Euch mehr beibringen.",objectives={"Sucht Prate Cloudseer in Tausend Nadeln."}]])
R(1534,"Ruf des Wassers",[[description="Nehmt diesen Wasserschlauch und begebt Euch tief in die dichten Wälder, die die Nachtelfen Ashenvale nennen. Sie liegen weit nördlich des Brachlandes.$B$BWenn Ihr den Wald betreten habt, reist nach Westen, an den Bergen entlang, die das Steinkrallengebirge und Ashenvale trennen. Jenseits des Mystralsees findet Ihr einen heiligen Ort: die Sternenstaubruinen. In der Mitte des Sees findet Ihr einen kleinen Brunnen.$B$BBringt mir eine Probe des Brunnenwassers. Das ist die letzte Komponente, die Ihr braucht, ehe ich Euch zu Islen zurückschicke.",objectives={"Füllt den leeren blauen Wasserschlauch bei den Sternenstaubruinen in Ashenvale und kehrt zu Brine im Brachland zurück."}]])
R(1535,"Ruf des Wassers",[[description="Um Wissen zu erlangen und das Sapta von mir zu bekommen, dürft Ihr nur nach den reinsten Formen des Wassers suchen. Doch achtet auf Eure Umgebung, wenn Ihr die Proben für mich beschafft. Hütet Euch vor Kreaturen, die auf das Wasser angewiesen sind, das sie beschützen. Seht, wie es Wälder und Wüsten beeinflusst. Beobachtet, wie die Substanz, die das Leben erhält, Kreaturen dazu zwingt, Leben zu nehmen.$B$BWir beginnen mit einer einfachen Aufgabe: unterhalb meiner Hütte befindet sich ein Tümpel mit der kostbaren Flüssigkeit. Füllt diesen Schlauch damit und kehrt zu mir zurück.",objectives={"Füllt den leeren braunen Wasserschlauch im Wasserloch unterhalb von Brines Hütte und kehrt damit zu Brine im Brachland zurück."}]])
R(1536,"Ruf des Wassers",[[description="Vor langer Zeit folgte ich einigen Gefährten ins Vorgebirge von Hillsbrad. Wir verteidigten uns gegen einige aufmüpfige Menschen, die dort beheimatet sind, und kamen in eine kleine Stadt, die die Verlassenen übernommen hatten: Tarrens Mühle.$B$BDort fand ich etwas höchst Eigentümliches: In der Mitte der Stadt befand sich ein kleiner Brunnen mit frischem Quellwasser. Ich bin nicht sicher, ob die gebeutelten Bewohner der Stadt seinen Wert überhaupt kennen... er ist eine kleine heilige Insel in einem unheiligen Meer.$B$BBringt mir eine Probe dieses Wassers in diesem Wasserschlauch.",objectives={"Füllt den leeren roten Wasserschlauch am Brunnen in Tarrens Mühle und kehrt zu Brine im Brachland zurück."}]])
R(1558,"Der Stonewroughtdamm",[[description="In der Nähe von Eisenschmiede, wo all die Zwerge und Gnome leben, gibt es einen Ort namens Loch Modan und die Zwerge haben da einen grooooßen Staudamm gebaut. Ich habe gehört, dass ist eines von den größten Dingen, die je gebaut wurden. Wow!$B$BKönnt Ihr mir den Damm in Loch Modan zeigen, bitte?! Ich glaube der heißt Stein... äh... Steinwerkdamm? Er ist riesig, so viel ist klar. Ich würde so gerne auf den großen Wasserfall heruntersehen. Ich verspreche, mich auch nicht zu weit vorzulehnen.",objectives={"Begleitet Euren Schützling zum Steinwerkdamm in Loch Modan. Geht mit ihm zur Mitte des Damms, damit er auf den riesigen Wasserfall heruntersehen kann."}]])
R(1559,"Blitzstrahlbombenanleitung")
R(1560,"Toogas Bitte",[[description="Ich habe mich vollkommen verirrt!$b$bTorta, meine Frau, schickte mich Essen holen, aber ich muss irgendwo falsch abgebogen sein.$b$bWürdet Ihr so freundlich sein, mich zu Torta zurückzuführen? Sie wartet südlich von Steamwheedle auf mich.",objectives={"Zeigt Tooga den Weg zurück zu seiner Frau Torta."}]])
R(1578,"Nachschub für die Front",[[description="Die Gebirgsjäger vom Loch Modan kämpfen gegen Troggs und sind damit schwer beschäftigt! Sie benötigen konstanten Nachschub an neuen Rüstungen und Waffen, wenn wir diese Troggs je bezwingen wollen.$B$BDarum ist mein Kollege Thorvald hier und versucht, die Gebirgsjäger gut ausgerüstet zu halten. Wenn Ihr einige Kupferäxte und Kettengürtel aus Kupfer herstellen und sie Thorvald bringen könntet, wäre er Euch sehr verbunden. Vielleicht weiht er Euch sogar in sein Wissen ein.$B$BThorvald ist im südlichem Wachturm des Loch Modan.",objectives={"Bringt 6 Kupferäxte und 6 Kupferne Kettengürtel zu Thorvald im südlichen Wachturm des Loch Modan."}]])
R(1579,"Klemm-Muffen",[[description="Ich kam nach Auberdine wegen der Ruhe. Ich möchte meine Erfindungen machen, wo es ruhig ist, denn nach einer durchzechten Nacht ertrage ich den Lärm von Ironforge nicht!$B$BDaher nahm ich ein Schiff nach Auberdine, trank aber unterwegs ein bisschen viel. Ich ließ meine Kiste mit Klemm-Muffen über Bord fallen! Ich brauche meine Klemmmuffen!$B$BIch weiß nicht genau, wo ich sie fallen ließ, aber vielleicht habt Ihr ja Glück, wenn Ihr im Meer danach fischt...",objectives={"Bringt 8 Klemm-Muffen zu Wizbang Cranktoggle in Auberdine."}]])
R(1580,"Elektropeller",[[description="Wir wissen, dass Ihr Glück habt, aber... wie viel Glück genau, $n?$B$BEines Nachts schlenderte ich durch die Straßen von Dunkelküste. Ich suchte nach einem geeigneten Fluss oder See, um meine neuen propellerbetriebenen explodierenden Entenattrappen auszuprobieren. Ich muss wohl etwas beschwipst gewesen sein, denn Stunden später wachte ich in Auberdine auf. Mein Haar war versengt und meine Tasche mit den Elektropellern war weg! Sie müssen mir ins Wasser gefallen sein!$B$BIch brauche diese Elektropeller! Vielleicht könnt Ihr sie aus einem See oder Bach in Dunkelküste fischen...",objectives={"Bringt 12 Elektropeller zu Wizbang Cranktoggle in Auberdine."}]])
R(1581,"Elixiere für die Bladeleafs",[[description="Unser Kräuter- und Alchimie-Laden floriert, aber mein Mann verbringt so viel Zeit damit, Tränke zu mischen, dass wir nie Zeit füreinander haben.$B$BKönnt Ihr uns helfen?$B$BWenn Ihr mir einen Vorrat an vorgefertigten Elixieren bringt, würde ich mit Freuden mit Euch tauschen. Ich besitze gewisse rare Kräuter, die Euch nützlich sein könnten.",objectives={"Bringt 6 Elixiere Löwenkraft und 2 Elixiere der schwachen Verteidigung zu Syral Bladeleaf in Dolanaar."}]])
R(1582,"Mondscheinweste",[[description="Wir in Darnassus, besonders wir Handwerker, sind sehr beschäftigt. Junge Abenteurer brennen darauf, sich in der Wildnis zu beweisen, und benötigen unablässig Nachschub.$B$BWenn Ihr mir helft, meine Bestellungen an Lederwaren zu erfüllen, kann ich Euch vielleicht eine hochentwickelte Technik der Lederverarbeitung beibringen.",objectives={"Bringt 1 geprägten Lederhandschuh, 5 geprägte Lederstiefel und 5 geprägte Lederumhänge zu Lotherias in Darnassus."}]])
R(1598,"Der gestohlene Foliant",[[description="Ihr da! $n, richtig?$b$bIch hoffe, Ihr seid sicher, dass Ihr ein Hexenmeister werden möchtet, denn wenn Ihr nicht allein besteht, werdet Ihr gewiss untergehen.$b$bIch werde Euch unterrichten, muss aber zuerst sicher sein, dass Ihr stark genug seid.$b$bEin Novize, der an der Abtei studierte, lief weg und schloss sich der Bruderschaft der Defias an. Warum mich das kümmert? Weil er einige wichtige Bücher gestohlen hat.$b$bEines davon war ein Buch, das ich selbst wollte, \"Die Macht der Leere\". Stehlt es für mich, sie haben es in ihrem Zelt in den Weinbergen versteckt.",objectives={"Holt \"Die Macht der Leere\" für Drusilla La Salle zurück."}]])
R(1599,"Anfänge",[[description="Ihr müsst der neue Hexenmeister sein, über den alle tuscheln. Jemand muss Euch sehr mögen, wenn man mich bittet, meine Forschungen aufzuschieben und Eure Ausbildung zu übernehmen.$b$bKeine Bange, ich mache Euch keinen Vorwurf.$b$bDer einfachste Beschwörungszauber, den Ihr lernen werdet, ist der für einen Wichtel. Doch bevor ich ihn Euch beibringe, müsst Ihr beweisen, dass Ihr die notwendigen magischen und körperlichen Fähigkeiten besitzt.$b$bBringt mir drei Federglücksbringer von den Novizen der Frostmane aus der Höhle im Südwesten.",objectives={"Bringt 3 Federglücksbringer zu Alamar Grimm in Anvilmar."}]])
R(1618,"Die Aufrüstung im Rotkammgebirge",[[description="Wir Zwerge sind nicht die Einzigen, die kämpfen. Unsere menschlichen Verbündeten haben auch alle Hände voll zu tun!$B$BDas Rotkammgebirge wird immer wieder von den Blackrockorcs angegriffen und der Vorrat an Ausrüstung ist stets knapp. Ich bin sicher, wenn Ihr ihnen helft, wird der ansässige Schmied, Verner Osgood, Euch den einen oder anderen Trick beibringen.",objectives={"Tormus Deepforge möchte, dass Ihr 4 runenverzierte Kupfergürtel und 4 schwere Kupferschlägel zu Verner Osgood ins Rotkammgebirge bringt."}]])
R(1638,"Die Ausbildung eines Kriegers",[[description="Ihr habt Euch als fähiger Krieger erwiesen, $N. Aber Ihr seid noch jung und müsst noch viel lernen.$B$BSprecht mit Harry Burlguard... er ist meist in der Taverne Zum pfeifenden Schwein in der Altstadt von Stormwind. Harry ist ein alter Veteran und guter Lehrer. Er kann Euch einige Kampftechniken zeigen, die Euer Leben verlängern.",objectives={"Sprecht mit Harry Burlguard."}]])
R(1639,"Bartleby der Trunkenbold",[[description="Ja, ich kann Euch unterrichten. Aber vorher will ich sehen, welche Kampftechniken Ihr schon beherrscht.$B$BSeht Ihr den Betrunkenen am Ende der Bar? Bartleby? Nehmt ihm seinen Krug weg.$B$BHa, und wenn Ihr Bartleby kennt, dann wisst Ihr, dass er ihn nicht freiwillig rausrückt.",objectives={"Sprecht mit Bartleby."}]])
R(1640,"Besiegt Bartleby",[[description="Ihr wollt was??? Ihr seid verrückt!$B$BWenn Ihr diesen Krug wollt, müsst Ihr ihn mir aus den kalten, toten Händen brechen...",objectives={"Besiegt Bartleby und redet dann mit ihm."}]])
R(1641,"Der Foliant der Offenbarung")
R(1642,"Der Foliant der Offenbarung",[[description="Ein Paladin muss in allen Dingen das Licht widerspiegeln, das uns Kraft gibt. Wenn einer unserer Art nach dem Göttlichen strebt, bedeutet das nicht, dass er ein Gott sein möchte... wir trachten nur danach, in allem nur Gutes zu tun.$B$BAuch wenn Ihr in diesen schweren Zeiten berufen seid, das Böse zu zerschmettern, dürft Ihr nicht vergessen, dass die Unterstützung anderer Euch wahrhaft von den Bürgern von Azeroth unterscheidet. Mitgefühl, Geduld, Tapferkeit... das alles bedeutet einem Paladin so viel wie Kraft im Kampf.$B$BBedenket das und vergesst es niemals.",objectives={"Sprecht mit Duthorian Rall in Stormwind."}]])
R(1643,"Der Foliant der Offenbarung",[[description="Eure Aufgabe, $N, besteht darin, jemanden hier in Stormwind zu finden, der der Hilfe bedarf. Jemanden mit reinem Herzen und edlen Motiven. Vielleicht jemanden, der anderen hilft. Vielleicht jemanden, der einen Führer braucht. Was auch immer, die Person muss edle Absichten haben und auf Eure Güte angewiesen sein.$B$BMacht das und kommt zu mir zurück, wenn Ihr fertig seid. Dann sprechen wir weiter über Euren Weg und was es bedeutet, ein Paladin des Lichts zu sein.",objectives={"Sucht im Handelsdistrikt von Stormwind nach Stephanie Turner."}]])
R(1644,"Der Foliant der Offenbarung",[[description="Die meisten der guten Seelen haben keine Familien mehr aufgrund der Angriffe der Geißel im letzten Jahrzehnt.$B$BMein Mann John sammelt die Materialien, die ich brauche, um Hemden und Hosen für die Kinder zu machen, aber nicht einmal dafür hatte ich Zeit. Ich war zu sehr damit beschäftigt, ihnen Essen auf ihre Teller und ein Dach über ihre Köpfe zu geben.$B$BWie war das? Ihr wärt bereit, mir zu helfen? Oh, dem Licht sei Dank und Euch ebenfalls, $n.$B$BWenn Ihr mir etwas Leinen bringen könntet, damit ich den Kindern Kleidung nähen kann, wäre mir das eine große Hilfe.",objectives={"Bringt 10 Stück Leinenstoff zu Stephanie Turner in Stormwind."}]])
R(1645,"Der Foliant der Offenbarung")
R(1646,"Der Foliant der Offenbarung",[[description="Ein Paladin muss in allen Dingen das Licht widerspiegeln, das uns Kraft gibt. Wenn einer unserer Art nach dem Göttlichen strebt, bedeutet das nicht, dass er ein Gott sein möchte... wir trachten nur danach, in allem nur Gutes zu tun.$B$BAuch wenn Ihr in diesen schweren Zeiten berufen seid, das Böse zu zerschmettern, dürft Ihr nicht vergessen, dass die Unterstützung anderer Euch wahrhaft von den Bürgern von Azeroth unterscheidet. Mitgefühl, Geduld, Tapferkeit... das alles bedeutet einem Paladin so viel wie Kraft im Kampf.$B$BBedenket das und vergesst es niemals.",objectives={"Sprecht mit Tiza Battleforge in Ironforge."}]])
R(1647,"Der Foliant der Offenbarung",[[description="Eure Aufgabe, $N, ist es, jemanden hier in Ironforge zu finden, der der Hilfe bedarf. Jemand mit reinem Herzen und edlen Motiven. Vielleicht jemanden, der anderen hilft. Vielleicht jemanden, der einen Führer braucht. Was auch immer, die Person muss edle Absichten haben und auf Eure Güte angewiesen sein.$B$BMacht das und kommt zu mir zurück, wenn Ihr fertig seid. Dann sprechen wir weiter über Euren Weg und was es bedeutet, ein Paladin des Lichts zu sein. Ich warte hier im Tempel auf Eure Rückkehr. Auch andere Paladine brauchen meine Unterstützung.",objectives={"Sucht im äußeren Ring von Ironforge nach John Turner."}]])
R(1648,"Der Foliant der Offenbarung",[[description="Meine Frau und ich führen das Waisenhaus in Stormwind, das überwiegend Kindern vorbehalten ist, die im letzten Jahrzehnt ihre Eltern bei Angriffen der Geißel verloren haben. Ich komme etwa einmal im Monat nach Ironforge und versuche, bei den Bürgern hier mehr Vorräte zu sammeln und mit den verschiedenen Gruppen zu reden, ob sie irgendwie helfen können.$B$BDieser Ausflug war schrecklich langwierig und nicht sehr ergiebig.$B$BKönnte ich doch nur noch etwas mehr Leinen bekommen, damit meine Frau Kleidungsstücke nähen kann, dann könnte ich endlich eine Ladung nach Hause schicken.",objectives={"Bringt 10 Stück Leinenstoff zu John Turner in Ironforge."}]])
R(1649,"Der Foliant der Ehre",[[description="Ehre, und alle Tugenden, die damit einhergehen, sind wie rare Mineralien: man muss sie ihres Wertes wegen bewundern, wenn man sie findet, aber man muss sich auch die Zeit nehmen, sie aufzuheben... zu veredeln. Mischt man sie richtig, entsteht eine starke Legierung, die manchmal selbst die heftigsten Hiebe nicht zerbrechen können.$B$BDiese Kraft, Euer Glauben, Eure Tapferkeit, müssen geprüft werden. Ihr müsst lernen, niemals den Glauben zu verlieren und erkennen, dass Ihr mit der Macht des Lichts Dinge überwinden könnt, vor denen andere klein beigeben müssen.",objectives={"Sprecht mit Duthorian Rall in Stormwind."}]])
R(1650,"Der Foliant der Ehre",[[description="Gut! Da Ihr nicht zögert, seid Ihr gewiss bereit und brennt darauf, Euch zu beweisen. So sei es.$B$BAm äußersten Ende von Longshore in Westfall steht ein kleines Haus über dem Ozean. Dort lebt ein Paar, die Stilwells. Jordan ist ein unglaublicher Schmied und für einige Zeit nach Ironforge gegangen, um sich mit den Zwergen zu treffen. Dadurch ist seine Frau Daphne allein und schutzlos.$B$BEs wird berichtet, dass die Defias fast das gesamte Gebiet übernommen haben. Gut möglich, dass Daphne Schutz vor den Bösewichtern braucht. Geht dorthin.",objectives={"Sucht Daphne Stilwell in Westfall."}]])
R(1651,"Der Foliant der Ehre",[[description="Ich wette, die kommen bald wieder, also macht Euch bereit.$B$BIch habe eine Schusswaffe im Haus. Ich hole sie und helfe Euch gern, aber Ihr werdet weitgehend auf Euch gestellt sein.$B$BIch habe keine Ahnung, wie viele sie schicken, aber es werden sicher mehr sein als die paar beim letzten Mal.$B$BBittet das Licht um jeden erdenklichen Segen, denn ... habt Ihr das gehört? Ich glaube, sie kommen.$B$BWir beziehen Position beim Haus!",objectives={"Verteidigt Daphne Stilwell vor dem Angriff der Defias.$B$BKeiner Eurer Geister darf aus seinen irdischen Fesseln befreit werden, wenn Ihr erfolgreich sein wollt.$B$BSprecht erneut mit Daphne Stilwell, wenn Ihr erfolgreich wart."}]])
R(1652,"Der Foliant der Ehre",[[description="Kehrt bitte zu Duthorian zurück und lasst ihn wissen, dass ich hier vorerst sicher bin. Dafür muss ich Euch und der Kirche danken.$B$BEr wird eine Nachricht nach Ironforge schicken und meinen Jordan wissen lassen, dass er keinen Grund zur Furcht hat.$B$BOh, ich vermisse meinen Mann so sehr. Ich kann es kaum erwarten, bis er wieder da ist.",objectives={"Sprecht mit Duthorian Rall in Stormwind."}]])
R(1653,"Die Prüfung der Rechtschaffenheit",[[description="Ich zweifle nicht daran, dass Jordan Euch persönlich danken möchte, und da ich einen Boten brauche, der ihn wissen lässt, dass es seiner Frau gut geht, scheint Ihr mir die perfekte Wahl zu sein.$B$BJordan sollte ein Paladin des Lichts sein, bevor die Liebe zum Beruf seines Vaters ihn einen anderen Weg einschlagen ließ - er ist innig mit unserer Lebensweise vertraut und wird zu unseren Getreuesten gerechnet.$B$BEr müsste noch in Ironforge sein - tagsüber arbeitet er gern vor den Toren, wohl wegen der kühlen Bergluft.",objectives={"Sprecht mit Jordan Stilwell in Ironforge."}]])
R(1654,"Die Prüfung der Rechtschaffenheit",[[description="Ich würde Euch gern eine Belohnung geben, wenn Ihr bereit seid, eine anzunehmen. Missversteht mich nicht, meine Großzügigkeit hängt davon ab, wie hilfreich Ihr sein könnt, aber ich denke, wir werden beide von einer derartigen Allianz profitieren.$B$BIch werde Euch eine Waffe schmieden, die Eurer Leistung würdig ist, ein Symbol der Paladinschaft und des Lichts, doch zuvor müsst Ihr die Gegenstände sammeln, die ich zu seiner Herstellung brauche. Ich habe schon angefangen, mir Notizen zu den Gegenständen zu machen, und brauche nur jemanden, der tapfer und geschickt genug ist, sie zu beschaffen. Was sagt Ihr dazu, $C?",objectives={"Sucht mit Jordans Waffennotizen etwas Weißsteineichenholz, Bailors aufbereitete Erzlieferung, Jordans Schmiedehammer und einen Kor-Edelstein und bringt alles zusammen zu Jordan Stilwell in Ironforge."}]])
R(1655,"Bailors Erzlieferung",[[description="Ach, Ihr habt mich erschreckt, $G Mann:Frau;! Seht Ihr nicht, dass ich nachdenke?$B$BWie war das? Jordans Lieferung... für Ironforge. Ahhh, ja, ich weiß, wovon Ihr sprecht. Oger der Mo'grosh haben die Erzlieferung meines alten Freundes gestohlen. Die Karawane war auf dem Weg vom Sumpfland hierher und geriet in einen Hinterhalt. Die Wache, die den Angriff überlebte, starb vor wenigen Tagen - der Heiler kam nicht schnell genug hin.$B$BWenn Ihr die Lieferung wollt, müsst Ihr über den Loch nach Nordosten. Dort muss sie irgendwo sein.",objectives={"Bringt Jordans Erzlieferung zu Bailor Stonehand am Loch Modan."}]])
R(1656,"Eine unvollendete Aufgabe",[[description="$N, bitte, ich flehe Euch an, könnt Ihr mir helfen? Ich habe meine Aufgaben hier auf der Mesa noch nicht beendet - ich bin mitten in meinem Ritual der Kraft - und mein Vater bat mich, diese Felle im Gasthaus von Bloodhoof abzuliefern.$B$BIch bin längst nicht erholt genug, mein Ritual und diese Aufgabe für meinen Vater zu beenden. Würdet Ihr an meiner statt gehen?$B$BDas Gasthaus ist angenehm und eine perfekte Oase der Ruhe auf langen Reisen. Ich bin sicher, Ihr stimmt mir zu, wenn Ihr es seht.",objectives={"Bringt das Bündel Felle zu Gastwirt Kauth in Bloodhoof."}]])
R(1657,"Die Verpestung von Southshore",[[description="Feiert die Schlotternächte mit Stil... bereitet unseren Feinden in Southshore Kummer!$B$BNehmt eine dieser speziell angefertigten Stinkbomben. Sie sind mit einem derartig furchtbaren Schrecken gefüllt, dessen Geruch kein Mensch - oder anderes Wesen mit schwachem Gemüt - ertragen kann. Ihr müsst die Stinkbombe direkt ins Herz von Southshore werfen, damit sie richtig wirken kann. Seid also auf eine Auseinandersetzung mit der Allianz gefasst!$B$BSolltet Ihr diese Aufgabe bewältigt haben, kehrt zu mir zurück... es ist ein Beitrag zu unserer Befreiung!",objectives={"Werft drei Stinkbomben der Verlassenen ins Herz von Southshore in Hillsbrad und kehrt zu Ruferin der Dunkelheit Yanka beim Fest des Weidenmanns in Tirisfal zurück."}]])
R(1658,"Bespitzelt das Fest des Weidenmanns",[[description="Ich brauche mutige Freiwillige, die nach Tirisfal ziehen und das Fest des Weidenmanns auskundschaften. Ich möchte nicht lügen - diese Mission ist äußerst gefährlich. Die Wachen des Fests werden besonders bösartig sein. Trotzdem, wir müssen in Erfahrung bringen wie groß das Fest dieses Jahr ist und wieviel Schaden die Verlassenen dieses Mal während der Schlotternächte anrichten.$B$BSolltet Ihr dabei sein, dann geht nach Tirisfal und kundschaftet das Fest aus. Kehrt mit den Informationen zu mir zurück und ich werde für eine angemessene Belohnung sorgen.",objectives={"Macht das Fest des Weidenmanns der Verlassenen in Tirisfal ausfindig. Kehrt zu Sergeant Hartman in Southshore zurück, sobald Ihr Eure Mission erfüllt habt."}]])
R(1659,"<UNUSED>")
R(1660,"<UNUSED>")
R(1661,"Der Foliant des Adels",[[description="Ich grüße Euch erneut, $n. Ich bin stolzer als jemals zuvor, Euch $g Bruder:Schwester; nennen zu können - Euer Engagement ist ein Tribut an uns alle.$B$BDie Zeit ist für mich gekommen, Euch ein wunderbares Geschenk zu übergeben. Wisset aber, dass ich es Euch fürs Erste zwar frei gebe, später jedoch, falls die Zeit es erlaubt, wird dies eine viel größere Herausforderung für alle Paladine sein, die sich dazu entscheiden, meinen Auftrag anzunehmen.$B$BSprecht erneut mit mir und ich werde Euch einen großen Segen gewähren.",objectives={"Sprecht mit Duthorian Rall in Stormwind."}]])
R(1665,"Bartlebys Becher",[[description="Okay, hier ist mein Becher. Wartet! Lasst mich zuerst austrinken... da haben wir es.",objectives={"Bringt Bartlebys Becher zu Burlguard."}]])
R(1666,"Marshal Haggard",[[description="Ihr habt einige Kampftechniken gelernt, braucht aber noch eine anständige Waffe. Ich wette, Marshal Haggard könnte Euch helfen, wenn Ihr mit ihm sprecht.$B$BMarshal Haggard lebt in einem Anwesen im Wald von Elwynn, beim Holzfällerlager des Osttals. Er ist jetzt im Ruhestand, hat aber in seiner Laufbahn eine Menge Ausrüstung gesammelt.$B$BLasst ihn wissen, dass ich Euch geschickt habe, und mit etwas Glück hat er eine Waffe für Euch übrig.",objectives={"Sprecht mit Marshal Haggard."}]])
R(1667,"Stumpfzahn Jack",[[description="Burlguard hat Euch geschickt, nicht? Ja, ich habe Waffen übrig, aber zuerst habe ich eine Aufgabe für Euch...$B$BVor einer Weile überlistete mich ein Bösewicht der Defias, Stumpfzahn Jack. Es war dunkel und er trug ein Stormwindwams, daher dachte ich, er sei Marshal Dughan. Er sagte, er braucht meinen alten Marshalstern aus Stormwind und ich gab ihm diesen... dann lachte er und lief weg, ehe ich ihn packen konnte!$B$BBringt mir meinen Stern! Stumpfzahn Jack hat ihn wahrscheinlich in seinem Lager im Süden versteckt.",objectives={"Holt Marshal Haggards Abzeichen aus Stumpfzahn Jacks Lager und kehrt zu Marshal Haggard zurück."}]])
R(1678,"Vejrek",[[description="Wenn Ihr es in den Reihen der Krieger zu etwas bringen wollt, müsst Ihr zäh sein. Ich kann Euch neue Kampftechniken beibringen, aber zuvor müsst Ihr mir beweisen, dass Ihr gegen richtige Feinde bestehen könnt.$B$BVejrek ist der härteste Troll, den Ihr in dieser Gegend findet. Ihn müsst Ihr besiegen. Er hat eine Hütte im Vorgebirge südlich der Frostmanehöhle.$B$BBringt mir Vejreks Kopf, dann weiß ich, dass Ihr Mumm habt.",objectives={"Bringt Vejreks Kopf zu Muren Stormpike in Ironforge."}]])
R(1679,"Muren Stormpike",[[description="Hallo, Krieger! Ihr seid viel versprechend, aber dennoch müsst Ihr ein paar Tricks lernen, und Muren Stormpike ist genau der Zwerg, der sie Euch beibringen kann.$B$BIhr findet Muren in der Halle der Waffen im Militärviertel von Ironforge. Sprecht mit ihm, wenn Ihr bereit seid zu lernen, was es heißt, ein Krieger zu sein.",objectives={"Sprecht mit Muren Stormpike."}]])
R(1680,"Tormus Deepforge",[[description="Jetzt, da Ihr einige Kampftechniken gelernt habt, wird es Zeit, Euch eine anständige Waffe zu beschaffen. Sprecht mit Tormus Deepforge. Er kann Euch eine Waffe machen, die Euch sicher gefallen wird.$B$BIhr findet Tormus hier in Ironforge bei der großen Schmiede.",objectives={"Sprecht mit Tormus Deepforge."}]])
R(1681,"Ironbands Truppenlager",[[description="Mein Mentor Sturgy Ironband hatte ein Lager südlich des Helmsbedsees im östlichen Dun Morogh. Dort lehrte er die Schmiedekunst und er war der Beste.$B$BAber eines Tages brachte ihm einer seiner Schüler eine Ladung mit seltsamem Erz. Meister Ironband nannte es Umbralerz und konnte es kaum erwarten, damit zu arbeiten. Doch kurz nach der Lieferung griff eine Bande Dunkeleisenzwerge sein Lager an. Sie töteten alle!$B$BBegebt Euch zu Ironbands Lager, $N, und rächt den Tod meines Meisters. Und bringt mir die Ladung Umbralerz, die all das auslöste.",objectives={"Bringt eine Ladung Umbralerz zu Tormus Deepforge in Ironforge."}]])
R(1682,"Waffen aus grauem Eisen")
R(1683,"Vorlus Elendshuf",[[description="Bevor ich Euch unterrichten kann, müsst Ihr mir Eure Entschlossenheit beweisen.$B$BDer Satyr Vorlus Elendshuf hat einen unserer entlegenen Mondbrunnen südöstlich der Grabhügel von Ban'ethil gefunden. Nun planscht er darin und verseucht das reine Wasser mit seinem Schmutz.$B$BSucht Vorlus beim Mondbrunnen und vernichtet ihn. Bringt mir sein Horn als Beweis, dann beginne ich Eure Fortgeschrittenen-Ausbildung zum Krieger.$B$BDer Weg zum Mondbrunnen ist gut verborgen, $n, doch wenn Ihr konzentriert und wachsam bleibt, werdet Ihr ihn finden.",objectives={"Bringt das Horn von Vorlus zu Elanaria in Darnassus."}]])
R(1684,"Elanaria",[[description="Seid gegrüßt, Krieger. Eure Fertigkeiten wachsen, doch Eurer Beruf verlangt mehr, als Ihr für möglich haltet. Um weiter zu kommen müsst Ihr bald einen Lehrer finden.$B$BDie Kriegerin Elanaria weilt in Darnassus auf der Terrasse der Krieger. Sie kann Euch unterweisen.",objectives={"Sprecht mit Elanaria."}]])
R(1685,"Gakins Beschwörung",[[description="Läuft es nicht immer so? Ich habe den ganzen Tag nach Euch gesucht und konnte Euch nicht finden, und jetzt, da ich es nicht erwarte, kommt Ihr einfach zu mir spaziert.$b$bIch habe genug Zeit mit der Suche nach Euch vergeudet, daher möchte ich gleich zur Sache kommen. Meister Gakin hat Euch zu weiterer Ausbildung gerufen. Mir scheint, Ihr solltet ihn so rasch wie möglich aufsuchen.$b$bIhr findet ihn im Keller der Taverne Zum geschlachteten Lamm. Übrigens solltet Ihr diesen Treffpunkt nicht an die große Glocke hängen. Muss ja nicht jeder wissen.",objectives={"Meldet Euch bei Gakin dem Dunkelbinder im Magierviertel von Stormwind."}]])
R(1686,"Eluras Schemen",[[description="Ihr habt viel gelernt, $n. Jetzt fertigen wir Euch eine Waffe an. Die Waffe eines Kriegers.$B$BDazu müsst Ihr nach Dunkelküste reisen.$B$BVor langer Zeit zerschellte ein Schiff auf den Felsen beim Leuchtturm von Auberdine. Viele Kisten Eluniterz sanken auf den Meeresgrund.$B$BAls Erstes müsst Ihr den Wächter des Elunits besiegen, Eluras Schemen. Sie war einst Kapitän des Schiffes und verfluchte sich selbst dazu, für alle Zeiten in der Tiefe zu verweilen und ihre Schiffsladung zu schützen. Besiegt sie, nehmt Ihr das Medaillon ab und sammelt die verlorenen Elunitkisten ein.",objectives={"Bringt 8 Ladungen Eluniterz und das Medaillon von Elura zu Elanaria in Darnassus."}]])
R(1687,"Der gruselige Leuchtturm",[[description="Abends erzählen uns die Matronen manchmal Gruselgeschichten. Die sind spitze! Einmal haben sie uns von einem Geist erzählt, der in einem Leuchtturm in Westfall spukt. Er soll einmal ein Piratenkapitän gewesen sein, dessen Schiff ihm von anderen Piraten weggenommen wurde. Wow!$B$BKönnen wir uns bitte den Leuchtturm in Westfall anschauen? Ich will nachgucken, ob der Geist des Kapitäns noch immer dort ist! Ich bleibe auch immer nah bei Euch. Ich renn' auch bestimmt nicht weg oder so was.",objectives={"Besucht mit Eurem Schützling den Leuchtturm an der Küste von Westfall."}]])
R(1688,"Surena Caledon",[[description="Ich hatte eine Studentin namens Surena Caledon. Sie stand da, wo Ihr jetzt steht, und brannte darauf, die Hexenmeistermagie zu lernen, und ihr Talent war nicht von schlechten Eltern. Mehr als das, sie war jung und eine wahre Augenweide. Hätte ich sie doch nur damals schon durchschaut, die falsche Schlange!$b$bDas diebische Weib brannte mit einem der Defias durch, Erlan Drudgemoor. Ihr Verlust ist unbedeutend, aber ich schenkte ihr einen Blutsteinhalsschmuck, den ich wiederhaben muss.$b$bIhr Leben hat keine Bedeutung mehr für mich. Ihr findet sie bei Brackwells Kürbisbeet. Bringt wieder, was mir gehört.",objectives={"Beschafft Surenas Halsschmuck für Gakin den Dunkelbinder in Stormwind."}]])
R(1689,"Die Bindung",[[description="Ihr habt meinen Halsschmuck zurückgebracht und Surena bezwungen, und damit gezeigt, dass Ihr mindestens ebenso begabt seid wie sie es war.$b$bNichtsdestoweniger kann ich Euch versichern, dass Ihr dringend Ausbildung benötigt. Ihr meistert den Fluss der Magie, ja, aber zu einem Hexenmeister gehört viel mehr als das.$b$bIch zeige Euch, wie man einen Leerwandler beherrscht, aber bevor ich das kann, müsst Ihr einen am Beschwörungskreis herbeirufen und mit allen Euch zur Verfügung stehenden Waffen unterwerfen. Benutzt die Magie dieses Halsschmuckes unten am Beschwörungskreis.",objectives={"Beschwört mit Hilfe des Blutsteinhalsschmucks einen Leerwandler, unterwerft ihn und bringt dann den Blutsteinhalsschmuck zu Gakin dem Dunkelbinder in Stormwind zurück."}]])
R(1690,"Wüstenläufergerechtigkeit",[[description="Ihr da! Für Euch ist es an der Zeit, ein großer Helfer der Gadgetzan Water Company zu sein.$B$BDie Wüstenläufernomaden draußen in der Tanariswüste haben fast alle Wasserbrunnen erobert! Ohne Zugang zu den Brunnen wird unser Wasservorrat im Handumdrehen schwinden. Wenn Ihr Euch unsere Dankbarkeit verdienen wollt, dann helft uns, diese Nomaden der Gerechtigkeit zuzuführen!$B$BBegebt Euch von hier Richtung Osten und schaltet zehn Banditen und Diebe der Wüstenläufer aus und meldet Euch dann umgehend wieder bei mir. Gerechtigkeit wartet auf keinen Mann ... keinen Goblin ... ach, legt einfach los!",objectives={"Erledigt 10 Banditen und Diebe der Wüstenläufer östlich von Gadgetzan und meldet Euch dann wieder bei Chefingenieur Bilgewhizzle."}]])
R(1691,"Noch mehr Wüstenläufergerechtigkeit",[[description="Wir müssen uns jetzt die stärkeren Ränge der Wüstenläufernomaden vornehmen. Ihr habt bisher gute Arbeit geleistet, aber wenn wir diese Wasserbrunnen zurückerobern wollen, dann wäre es gut, wenn uns dabei so wenig Nomaden wie möglich gegenüberstünden!$B$BDieses Mal müsst Ihr ihre Schurken, Auftragsmörder und Schattenmagier erledigen. Ihr werdet sie östlich und südöstlich von hier finden.$B$BIch werde Euch nichts vormachen - das ist eine schlimme Bande. Tut dies für uns, dann sind wir auf dem besten Weg, uns das zurückzuholen, was rechtmäßig uns gehört!",objectives={"Erledigt 10 Schattenmagier der Wüstenläufer, 8 Schurken der Wüstenläufer und 6 Auftragsmörder der Wüstenläufer für Chefingenieur Bilgewhizzle in Gadgetzan."}]])
R(1692,"Schmied Mathiel",[[description="Ich habe das Elunit, das Ihr gesammelt habt, in eine Kiste gelegt. Bringt sie zum Schmied Mathiel, er wird eine Elunitwaffe für Euch anfertigen.$B$BMathiel ist im Süden, an der anderen Seite dieses Gebäudes zu finden.",objectives={"Bringt das Behältnis mit Elunit zu Schmied Mathiel."}]])
R(1693,"Waffen aus Elunit")
R(1698,"Yorus Gerstenbräu",[[description="Yorus Gerstenbräu hat eine Herausforderung für alle tüchtigen Krieger der Allianz verkündet. Er wartet im Gasthaus von Seenhain im Rotkammgebirge und verspricht jedem, der seine Prüfung besteht, eine hohe Belohnung.",objectives={"Sprecht mit Yorus Gerstenbräu."}]])
R(1699,"Der Rethban-Spießrutenlauf",[[description="Ich nenne meine Herausforderung den Rethbanspießrutenlauf. Um die Prüfung zu bestehen, müsst Ihr lediglich die Rethbanhöhlen betreten, bis zur ersten Gabelung gelangen und hierher zurückkehren. Ganz einfach! Aber es gibt da ein paar Hürden...$B$BIhr müsst binnen einer Stunde zurück sein.$B$BGanze Heerscharen von Rotkammgnollen versperren den Weg.$B$BVor dem Start müsst Ihr einen Schluck des Stammgetränks meiner Familie zu Euch nehmen: Gerstenbräu!$B$BWas sagt Ihr dazu? Die Rethbanhöhlen liegen im Vorgebirge nördlich von Seenhain. Seid Ihr bereit, am Rethbanspießrutenlauf teilzunehmen?",objectives={"Betretet die Rethbanhöhlen, geht bis zur ersten Gabelung und kehrt innerhalb der zulässigen Zeit zu Yorus Gerstenbräu zurück.$B$BIhr dürft nicht sterben und Euren Geist befreien."}]])
R(1700,"Grimand Elmore",[[description="Ich fertigte eine Kopie meiner Notizen über die Techniken an, die ich lernte, während ich Eure Rüstung herstellte. Sie muss zu Grimand Elmore geschickt werden. Er ist hier im Zwergendistrikt, im Waffenladen.$B$BUnd duckt Euch, wenn Ihr ihm die gebt. Er bildet sich ungeheuer viel auf seine Fertigkeiten ein. Es wird ihm nicht gefallen, etwas von mir zu lernen ...",objectives={"Bringt Furens Notizen zu Grimand Elmore."}]])
R(1701,"Feuergehärteter Panzer",[[description="Ich gab Euch einen guten Schild, aber dabei muss es nicht bleiben. Ich kenne das Geheimnis, wie man extrem harte Panzerrüstung herstellt. Es ist nicht leicht und erfordert sehr rare Materialien, aber wenn Ihr bereit seid, die Kleinarbeit zu machen, fertige ich ein Teil für Euch an.$B$BWas sagt Ihr dazu, $N? Wenn Ihr Euch der Herausforderung gewachsen fühlt, gebe ich Euch eine Liste, was Ihr beschaffen müsst und wo Ihr es bekommt.",objectives={"Sammelt die Materialien, die Furen Longbeard benötigt, und bringt sie zu ihm nach Stormwind."}]])
R(1702,"Der Schildschmied",[[description="Ihr habt echt gezeigt, aus welchem Holz Ihr geschnitzt seid, als Ihr am Rethbanspießrutenlauf teilgenommen habt, $N. Und ich stehe zu meinem Wort. Ihr bekommt die versprochene Belohnung...$B$BAber sie ist in Stormwind.$B$BSprecht mit meinem Freund Furen Longbeard im Zwergendistrikt von Stormwind. Er ist der beste Schildschmied, den Ihr je gesehen habt, und er schuldet mir einen großen Gefallen.$B$BHier, bringt Furen dieses Fässlein mit Gerstenbräu und bittet ihn um einen Schild. Er wird Euch einen schönen geben.",objectives={"Bringt das Fässlein mit Gerstenbräu zu Furen Longbeard."}]])
R(1703,"Mathiel",[[description="Ich fertigte eine Kopie meiner Notizen über die Techniken an, die ich lernte, während ich Eure Rüstung herstellte. Sie muss zum Schmied Mathiel geschickt werden. Er lebt in Darnassus. Das ist weit weg, aber ich bin sicher, er wird dankbar sein, wenn er erfährt, was ich gelernt habe.",objectives={"Bringt Furens Notizen zu Mathiel."}]])
R(1704,"Klockmort Spannerspan",[[description="Ich fertigte eine Kopie meiner Notizen über die Techniken an, die ich lernte, während ich Eure Rüstung herstellte, und brauche jemanden, der sie zu Klockmort Spannerspan bringt. Er ist ein Gnomen-Schmied in Ironforge, und wenn er herausfindet, was ich herausgefunden habe ... Ich wette, er reißt sich vor Aufregung selbst den Bart aus.",objectives={"Bringt Furens Notizen zu Klockmort Spannerspan."}]])
R(1705,"Brennendes Blut",[[description="Ich gebe nur ungern zu, dass Furen tatsächlich etwas gefunden haben könnte. Aber um ganz sicher zu sein, muss ich seine Techniken an einem neuen Rüstungsteil erproben. Wenn Ihr mir mit den Materialien helft, $N, könnt Ihr die Rüstung haben.$B$BUm die Rüstung herzustellen benötige ich Proben von brennendem Blut und brennendem Felsen.$B$BDie findet man meines Wissens nur im Dämmerwald. Die Worgs der Nachtheuler in der Mine von Rolands Verdammnis haben brennendes Blut, und Gutspill, ihr Anführer, wird den Fels haben.$B$BMöge das Schicksal Euch Schnelligkeit gewähren $N.",objectives={"Bringt 20 Phiolen brennendes Blut und 1 brennenden Fels zu Grimand Elmore in Stormwind."}]])
R(1706,"Grimands Rüstung")
R(1707,"Wasserbeutelkopfgeld",[[description="Seid gegrüßt, $n, mein Name ist Luglunket, und wir haben einen wichtigen Auftrag für Euch, wenn Ihr bereit seid! Hussah!$B$BNichts würde mir als altgedientem Leitungshahnmaschinisten mehr gefallen, als Euch jeden Wasserbeutel eines Wüstenläufers abzunehmen, den Ihr draußen in der Wüste findet. Das ist ja ohnehin unser Wasser - die Nomaden haben es einfach nur gestohlen! Die Gadgetzan Water Company bietet Euch ein offizielles Care-Paket für jeweils fünf, die Ihr abliefert. Am wichtigsten ist aber, dass Ihr Gadgetzan selbst helft!",objectives={"Bringt Leitungshahnmaschinist Luglunket in Gadgetzan 5 Wasserbeutel eines Wüstenläufers."}]])
R(1708,"Eisenkoralle",[[description="Ich möchte Furen Longbeards neue Techniken an einer eigenen Rüstung erproben. Und weil Ihr Furen geholfen habt und er mir, sollt Ihr die Rüstung bekommen, wenn sie fertig ist!$B$BUm das Teil zu beenden, brauche ich eine spezielle Koralle, Sengkoralle. Sie wächst nur an einem Ort - an der Küste südlich des Hafens von Menethil im Sumpfland.$B$BBringt mir genügend Sengkoralle und ich mache mich gleich an die Arbeit. Und beeilt Euch, $N. Ich brenne so sehr darauf, endlich anzufangen, dass meine Zehen jucken!",objectives={"Bringt 20 Ladungen Sengkoralle zu Klockmort Spannerspan in Ironforge."}]])
R(1709,"Klockmorts Kreation")
R(1710,"Sonnenverbrannte Schalen",[[description="Mein Kollege, Furen Longbeard, hat eine Entdeckung gemacht, die ich schnellstens ausprobieren möchte. Ich möchte sie an einer neuen Rüstung erproben, an der ich forsche, denn ich glaube, Furens Techniken werden grandiose Ergebnisse erzielen.$B$BWerdet Ihr mir helfen? Wenn Ihr sammelt, was ich zur Herstellung der Rüstung brauche, fertige ich für Euch auch eine an.$B$BIch brauche sonnenverbrannte Eierschalen der Steilhangflügeldrachen, die am Steilhang in Tausend Nadeln hausen. Sucht unter den Nestern nach den Schalen und kommt zu mir zurück, wenn Ihr eine ausreichende Menge habt.",objectives={"Bringt 20 sonnenverbrannte Schalen zu Mathiel in Darnassus."}]])
R(1711,"Mathiels Rüstung")
R(1712,"Cyclonian",[[description="Ich beobachte diesen Ort seit Ewigkeiten. Ich beobachte, damit ich eines Tages den großen Cyclonian fallen sehen kann. Doch ich fand noch keinen Helden, der den Windlord besiegen konnte.$B$BVielleicht seid Ihr dieser Held.$B$BBeweist es mir. Sammelt die Gegenstände, die ich brauche, um Cyclonian zu beschwören, dann weiß ich, dass Ihr ein großer Krieger seid. Vielleicht könnt Ihr ihn besiegen und sein Wirbelherz bekommen.$B$BWenn ja, übertrage ich die Macht des Herzens in eine Waffe und schenke Euch diese Waffe.$B$BHier ein Pergament mit den Gegenständen, die ich benötige.",objectives={"Bringt die Gegenstände auf Bath'rahs Pergament zu Bath'rah dem Windbehüter in Alterac."}]])
R(1713,"Die Beschwörung",[[description="Ich bin bereit, das Ritual zur Beschwörung Cyclonians durchzuführen. Wenn er beschworen ist, müsst Ihr ihn besiegen und sein Wirbelherz nehmen. Ich werde es benutzen, um eine Waffe mit Cyclonians Macht zu stärken.$B$B$n, seid Ihr bereit, dem Windlord zu trotzen?",objectives={"Bringt das Wirbelherz zu Bath'rah dem Windbehüter."}]])
R(1714,"Essenz der Verbannung")
R(1715,"Zum Geschlachteten Lamm",[[description="Hmph. Früher wurden alle Hexenmeister in Khaz Modan unter der Aufsicht der Meister von Gnomeregan ausgebildet, doch jetzt, wo wir gezwungen wurden, in dieses Rattenloch in Ironforge zu ziehen und Magni beschloss, uns genau zu beobachten, sind wir gezwungen, unsere Novizen zur Ausbildung nach Stormwind zu schicken.$b$bZum Glück ist Gakin kein Tölpel, daher werdet Ihr lernen, was Ihr wissen müsst. Dennoch bringt es mein Blut zum Kochen!$b$bWie auch immer, Ihr findet Gakin im Keller des Geschlachteten Lamms in Stormwind.",objectives={"Meldet Euch bei Gakin dem Dunkelbinder im Magierviertel von Stormwind."}]])
R(1716,"Verschlinger der Seelen",[[description="Ein Sukkubus ist ein Verschlinger der Seelen, Zerstörer der Herzen, Bezwinger des Geistes. Er kennt nur das Böse.$b$bDies ist die Kreatur, die Ihr beschwören und beherrschen lernt, doch ohne Anreiz kann sie nicht in unsere Welt gebracht werden.$b$bMit einem Symbol der Liebe als Köder wird er gewiss auf Euren Ruf reagieren. Dann könnt Ihr ihn besiegen und zu Eurem Werkzeug machen.$b$bEs wird allerdings schwer sein, etwas dieser Art zu finden. Ihr solltet mit dem Seher Takar sprechen. Ihr findet ihn im Brachland von Kalimdor nahe dem Camp Taurajo.",objectives={"Sprecht mit Takar dem Seher im Brachland."}]])
R(1717,"Gakins Beschwörung",[[description="$n! Ich hätte nicht erwartet, Euch in der Gegend zu sehen, wurde aber angewiesen, nach Euch Ausschau zu halten.$b$bHöchste Zeit, dass Eure Ausbildung fortgesetzt wird. Beim nächsten Besuch in Stormwind solltet Ihr bei Gakin reinschauen. Er wird Euch erwarten.",objectives={"Meldet Euch bei Gakin dem Dunkelbinder im Magierviertel von Stormwind."}]])
R(1718,"Der Inselbewohner",[[description="Euer Ruf als Krieger wächst, $N. Jetzt ist es Zeit, Euch mit Euresgleichen zu messen und festzustellen, was Ihr könnt.$B$BVor der Küste des Brachlandes, südlich von Ratchet, liegt eine Insel. Sie heißt Prügel-Eiland und ist ein Treffpunkt für Krieger.$B$BGeht dorthin und kämpft.$B$BSprecht mit Klannoc Macleod, dem obersten Krieger der Insel. Wenn er Euch für würdig erachtet, wird Klannoc Euch weiter auf dem Pfad des Kriegers führen.$B$BUm die Prügel-Eiland zu erreichen, müsst Ihr nach den Sandbankuntiefen entlang der Händlerküste suchen.",objectives={"Sprecht mit Klannoc Macleod."}]])
R(1719,"Der Ringkampf",[[description="Wenn Ihr von mir lernen wollt, müsst Ihr zuerst den Ringkampf absolvieren. Das ist eine Herausforderung hier auf dem Prügel-Eiland, an der wir aufstrebende Krieger teilnehmen lassen, die sich für gut genug halten. Wenn Ihr gewinnt, dann weiß ich, dass Ihr es tatsächlich seid.$B$BGeht als Erstes mitten in diese Menge dort und stellt Euch auf den Rost. Dadurch weiß Twiggy Flathead, dass Ihr bereit seid, und er schickt Euch Herausforderer.$B$BWenn Ihr alle Herausforderer besiegt habt, ruft er Big Will. Tötet Big Will und kehrt innerhalb der von uns gesetzten Frist zu mir zurück.",objectives={"Tötet Big Will und sprecht mit Klannoc Macleod auf dem Prügel-Eiland."}]])
R(1738,"Herzholz",[[description="Als Vorbereitung auf Eure Ankunft nutzte ich mein zweites Gesicht, um über die Welt und hinter die Nebel der Zeit zu schauen. Ich habe herausgefunden, wonach Ihr sucht.$b$bIm Krieg der Urtume fielen zwei Liebende gemeinsam im Kampf. Wo sie ihren letzten Seufzer taten, wuchs ein als Herzholz bekannter Baum als Symbol ihrer unsterblichen Liebe.$b$bEr sollte genügen, um einen Sukkubus anzulocken. Ihr findet ihn in den Ruinen von Ordil'Aran im nordwestlichen Teil des Waldes von Ashenvale.",objectives={"Holt das Herzholz aus Ashenvale und bringt es zu Gakin dem Dunkelbinder im Magierviertel von Stormwind."}]])
R(1739,"Die Bindung",[[description="Mit dem Herzholzkern könnt Ihr einen Zauber am Beschwörungskreis unten in der Gruft wirken und ein Portal öffnen, durch das der Sukkubus kommen kann.$b$bSeid vorsichtig, $n, Sukkubi haben schon den stärksten Geist unterjocht.$b$bWenn Ihr ihn bezwungen und in die Leere zurückgeschickt habt, kommt wieder zu mir, dann zeige ich Euch, wie Ihr ihn rufen und kontrollieren könnt.",objectives={"Beschwört mit Hilfe des Herzholzkerns einen Sukkubus, unterwerft ihn und bringt dann den Herzholzkern zu Gakin dem Dunkelbinder im geschlachteten Lamm zurück."}]])
R(1740,"Die Kugel von Soran'ruk",[[description="Wenn Dämonen der Legion in Ungnade fallen, wird ihr Geist in Kugeln gefangen und an ihre Magier und Hexenmeister verteilt.$b$bViele wurden von ihren Bediensteten in Azeroth getragen. Selbst als Bruchstücke besitzen sie die Macht der darin gefangenen Dämonen.$b$bDie Kugel von Soran'ruk wurde in zwei Teile zerbrochen. Eines davon wurde abermals zerbrochen und von den Akolyten der Twilight-Hammer in der Blackfathom-Tiefe benutzt. Das andere, größere Teil besaß ein Hexer in der Burg Shadowfang. Sucht sie, dann kann ich sie zusammenfügen...",objectives={"Sucht 3 Soran'ruk-Fragmente und 1 großes Soran'ruk-Fragment und bringt sie zu Doan Karhan im Brachland."}]])
R(1758,"Foliant der Kabale",[[description="Mehr als ein einfacher Beschwörungskreis wird erforderlich sein, um einen Teufelsjäger als Herausforderer für Euch herzubringen.$b$bMeine drei Akolyten und ich helfen, die magischen Kreise zu erschaffen. Ihr benötigt eine Kopie des Folianten der Kabale, der seit geraumer Zeit als verschollen gilt. Er wurde von der ersten Gruppe Hexenmeister geschrieben, die ohne Unterstützung einen Teufelsjäger beschwörten.$b$bVielleicht kann Krom Stoutarm Euch dabei helfen. Heute ist er ein fahrender Hexenmeister, hortet alte Schriften und hängt in der Bibliothek von Ironforge herum.",objectives={"Sprecht mit Krom Stoutarm in Ironforge."}]])
R(1778,"Der Foliant der Offenbarung",[[description="Ich werde bald Pläne für meine Heimkehr machen. Hoffentlich geht es Stephanie gut in Stormwind. Ich kann es kaum erwarten, sie wiederzusehen. Auf bald, $C.",objectives={"Sprecht mit Tiza Battleforge in Ironforge."}]])
R(1779,"Der Foliant der Offenbarung",[[description="Ich möchte, dass Ihr das nehmt, $n. Es heißt Symbol des Lebens.$B$BIhr habt bewiesen, dass Ihr barmherzig und geduldig seid. Jetzt sollt Ihr mir zeigen, wie versiert Ihr geworden seid, was Gefecht und Macht angeht.$B$BMein Mann Muiredon kehrte jüngst von einer Begegnung mit Dunkeleisenzwergen zurück und kam gerade noch mit dem Leben davon - er ist da drüben und einer unserer Priester heilt schon seine Wunden.$B$BNehmt das Symbol und redet mit ihm. Wenn Ihr ihm helfen könnt, dann sprechen wir uns bald wieder. Möge das Licht auf Euch scheinen.",objectives={"Nehmt das Symbol des Lebens und sprecht mit Muiredon Battleforge in Ironforge."}]])
R(1780,"Der Foliant der Offenbarung",[[description="Ich bringe das noch heute zu den Kindern. Bitte bleibt unversehrt, $C. Es kommt nicht oft vor, dass $GMänner:Frauen; Eures Charakters in der Stadt auftauchen, doch Ihr habt bewiesen, dass die Paladine in Stormwind die Bedürftigen nicht im Stich lassen.$B$BLebt wohl.",objectives={"Sprecht mit Duthorian Rall in Stormwind."}]])
R(1781,"Der Foliant der Offenbarung",[[description="Nehmt das, $n. Es heißt Symbol des Lebens.$B$BIhr habt bewiesen, dass Ihr barmherzig und geduldig seid. Jetzt ist die Zeit gekommen, um festzustellen, ob Ihr stark genug seid für die größte Gabe des Lichts.$B$BMein Freund Gazin kehrte jüngst von einer Begegnung mit Defias in Elwynn nahe Heldenwache zurück - er kam gerade so mit dem Leben davon. Er ist in der Nähe des Altars, wo unsere Priester seine Wunden heilen.$B$BNehmt das Symbol und sprecht mit ihm. Wenn Ihr ihm helfen könnt, dann sprechen wir uns bald wieder. Möget Ihr Euch im Schein des Lichts sonnen.",objectives={"Bringt das Symbol des Lebens zu Gazin Tenorm in Stormwind."}]])
R(1782,"Furens Rüstung")
R(1783,"Der Foliant der Offenbarung",[[description="Er spionierte einigen Dunkeleisenzwergen nach, die sich südlich des Helmsbedsees eingebunkert hatten. Wir wussten, dass sie nichts Gutes im Schilde führten, daher dachten Narm und ich, wir sollten der Sache nachgehen - wir sahen, wie ihr Anführer seinen Männern Befehle gab.$B$BNarm und ich wollten einige töten, aber sie waren stärker als wir dachten und es wurden immer mehr. Narm sagte mir, ich solle Verstärkung holen, und hier bin ich.$B$BNarm braucht Hilfe und ich werde erst ruhen, wenn er sie bekommt.$B$BKönnt Ihr helfen, $N?",objectives={"Nehmt das Symbol des Lebens und erweckt Narm Faulk in Dun Morogh wieder zum Leben."}]])
R(1784,"Der Foliant der Offenbarung",[[description="Bevor ich im Kampf fiel, hatten Muiredon und ich fast einen der Spione der Dunkeleisenzwerge in der Nähe dieses kleinen Hauses besiegt. Wir wurden Zeugen, wie ihr Captain ihnen Befehle weitergab, und wollten sie töten und die Befehle an uns nehmen.$B$BEinige im Rat von Ironforge glauben nicht, dass sich Dunkeleisenzwerge in Dun Morogh aufhalten. Bekämen wir eines dieser Manuskripte, hätten wir nicht nur den Beweis für ihre Tätigkeiten, sondern möglicherweise auch eine Vorstellung dessen, was sie planen.$B$BBeschafft eines dieser Manuskripte und bringt es zu Muiredon, $N.",objectives={"Beschafft ein Dunkeleisenmanuskript von den Dunkeleisenzwergen beim Helmsbedsee und kehrt zu Muiredon Battleforge in Ironforge zurück."}]])
R(1785,"Der Foliant der Offenbarung",[[description="Ich sehe, meine Frau steht schon da drüben und platzt vor Stolz. Schleppt Euch besser mal hier rüber, aber pronto. Könnte mir denken, dass sie Euch was zu sagen hat.$B$B's Licht soll mit Euch sein, $C. Wenn die Zeit reif ist, such ich nach Euch auf den Schlachtfeldern, wenn es gegen die Geißel und die Dunkeleisenzwerge geht.",objectives={"Sprecht mit Tiza Battleforge in Ironforge."}]])
R(1786,"Der Foliant der Offenbarung",[[description="Henze und ich schafften es nach Heldenwache, einer Insel inmitten des Steinhügelsees im nordöstlichen Elwynn. Wir hörten, dass Defias unsere Grenzen unterwandert hatten und wollten einen Beweis für die Berater des Königs.$B$BAls wir eine Bande dieses Abschaums sahen, die Dokumente durchlasen, griffen wir an. Leider wurden wir recht schnell durch ihre Magier überwältigt.$B$BHenze wehrte sie ab, derweil ich entkam ... der elende Narr muss immer den Helden spielen.$B$BEr ist jetzt da draußen, der gute Henze. Könnt Ihr uns helfen, $N?",objectives={"Nehmt das Symbol des Lebens und erweckt Henze Faulk in Elwynn wieder zum Leben."}]])
R(1787,"Der Foliant der Offenbarung",[[description="Wir müssen uns später ausgiebiger über das Symbol unterhalten. Wichtig ist jetzt, dass wir diese Papiere bekommen, die die Defias studierten. Wenn wir sie in die Finger bekommen, können wir beweisen, dass die Defias Elwynn unterwandert haben und hoffentlich Einblick in ihre weiteren Pläne erhalten.$B$BMomentan bin ich nicht in der Verfassung zu kämpfen, $n. Glaubt Ihr, Ihr seid stark genug, den Defias hier auf der Insel diese Papiere abzunehmen?$B$BWenn Ihr sie beschaffen könnt, bringt sie Gazin und lasst ihn wissen, dass ich wohlauf bin.",objectives={"Beschafft ein Manuskript der Defias von den abtrünnigen Hexern der Defias in Elwynn und kehrt zu Gazin Tenorm in Stormwind zurück."}]])
R(1788,"Der Foliant der Offenbarung",[[description="Ich bringe das Manuskript zu den Beratern des Königs, nachdem Duthorian einen Blick darauf geworfen hat. In der Zwischenzeit solltet Ihr mit Duthorian sprechen. Er wird Euch ganz sicher auf die Schulter klopfen wollen!$B$BNochmals danke, $n. Ich hoffe, wir sehen uns wieder. Ihr seid ein Verbündeter, den ich voller Stolz meinen Freund nenne.",objectives={"Sprecht mit Duthorian Rall in Stormwind."}]])
R(1789,"Das Symbol des Lebens")
R(1790,"Das Symbol des Lebens")
R(1791,"Der Windbehüter",[[description="Jetzt, da Ihr Eure Berserkerhaltung gelernt habt, wollt Ihr bestimmt auch eine hübsche Waffe dazu.$B$BSprecht mit Bath'rah dem Windbehüter. Das ist ein Troll-Einsiedler, der zwischen dem Alteracgebirge und den Westlichen Pestländern lebt. Er ist ein geschickter Waffenmacher und mächtiger Schamane.$B$BUm Bath'rah zu finden, solltet Ihr zu dem Fluss gehen, der an der Ostflanke von Tarrens Mühle entlangfließt. Folgt ihm nach Norden - Bath'rah hat sein Lager nahe den Ruinen am Ostufer des Flusses aufgeschlagen.",objectives={"Sprecht mit Bath'rah dem Windbehüter."}]])
R(1792,"Wirbelwaffe")
R(1793,"Der Foliant der Ehre")
R(1794,"Der Foliant der Ehre")
R(1795,"Die Bindung",[[description="Wenn Ihr hinreichend vorbereitet seid, sollten wir beginnen. Lasst mich Euch den Vorgang erklären.$b$bIch beginne damit, dass ich den Standard-Beschwörungskreis erstelle. Wenn das geschehen ist, werden meine Akolyten mit den Kanalisierungsruten den größeren Kreis erstellen.$b$bIst das abgeschlossen, lest Ihr die Zauberformel aus dem Folianten der Kabale und der Teufelsjäger erscheint. Seid vorsichtig, $n. Ein Teufelsjäger ist ein mächtiger Widersacher. Ich möchte nicht, dass er Euch einen Kopf kürzer macht.",objectives={"Beschwört mit Hilfe des 'Folianten der Kabale' einen Teufelsjäger, unterwerft ihn und bringt den 'Folianten der Kabale' zu Strahad Farsan in Ratchet zurück."}]])
R(1796,"Komponenten für die verzauberte Goldblutrobe",[[description="Der erste Gegenstand, bei dessen Erschaffung ich Euch helfen werde, ist eine Robe. Ihr werdet die Gegenstände für mich sammeln und wir werden sie zusammensetzen. Vorausgesetzt Ihr seid erfolgreich, werdet Ihr danach den ersten von vielen Gegenständen haben, die Euch mächtiger machen und Euch bei Eurem Kampf helfen werden.$B$BFür den Anfang müsst Ihr in den Besitz der Roben von Arcana kommen. Ein Schneider kann sie für Euch machen oder vielleicht könnt Ihr eine von jemandem kaufen... am meisten würde es mich beeindrucken, wenn Ihr sie selbst herstellen könntet... aber wie auch immer, bringt mir die Roben und dann machen wir weiter.",objectives={"Bringt die Roben von Arcana zu Menara Voidrender im Brachland."}]])
R(1798,"Die Suche nach Strahad",[[description="Es ist Zeit, dass Ihr die Beschwörung eines Teufelsjägers lernt, $n. Ich habe nicht die erforderlichen Reagenzien und Gegenstände, um Euch hier zu unterrichten, daher müsst Ihr einen anderen aus unserem inneren Kreis aufsuchen, nämlich Strahad Farsan.$b$bEr hat sich im Goblin-Hafen von Ratchet niedergelassen. Ich werde ihn von Eurer Ankunft in Kenntnis setzen lassen.",objectives={"Sprecht mit Strahad Farsan im Brachland."}]])
R(1799,"Fragmente der Kugel von Orahil",[[description="Gut, dann können wir beginnen.$B$BIhr müsst als Erstes mit meinen Akolyten im Inneren sprechen. Wählt einen ihrer Wege und folgt ihm - sie werden Euch alles erklären.$B$BAls Zweites müsst Ihr nach Desolace reisen und eine Höllenkugel von einem der Hexenmeister von Mannorocs Koven holen. Diese Kugel werdet Ihr mit der Hilfe einer Magierin namens Tabetha tief in den südlichen Marschen von Dustwallow reinigen. Sie wird Euch aufgrund unserer gemeinsamen Vergangenheit helfen.$B$BKommt erst zurück, wenn Ihr beide Dinge erledigt habt, um die ich Euch gebeten habe.",objectives={"Sprecht mit Menaras Akolyten im Inneren des Turms über Ratchet und wählt einen ihrer Wege, um ihm zu folgen.$B$BBringt danach eine Höllenkugel zu Tabetha in den Marschen von Dustwallow."}]])
R(1800,"Der Thronsaal von Lordaeron",[[description="Wenn wir brav sind und die Hausarbeiten ordentlich machen, erzählen uns die Waisenmatronen oft Geschichten von großen Schlachten und darüber, wie Lordaeron fiel und wie der böse Arthas seinen eigenen Vater umbrachte, nur um König zu werden.$B$BEr hatte keine Ehre, $n! Wenn ich erst einmal groß und ein mächtiger Krieger der Horde bin, wird mein Schwert durch die Ehre geleitet werden; niemals durch das Böse!$B$BWürdet Ihr mit mir den Thronsaal besuchen, bitte? Er befindet sich kurz vor dem Abgang, über den man nach Unterstadt heruntergeht.",objectives={"Besucht mit Eurem Schützling den alten Thronsaal in Lordaeron. Er befindet sich kurz vor dem Abgang nach Unterstadt."}]])
R(1801,"Foliant der Kabale",[[description="Mehr als ein einfacher Beschwörungskreis wird erforderlich sein, um einen Teufelsjäger als Herausforderer für Euch herzubringen.$b$bMeine drei Akolyten und ich helfen, die magischen Kreise zu erschaffen. Ihr benötigt eine Kopie des Folianten der Kabale, der seit geraumer Zeit als verschollen gilt. Er wurde von der ersten Gruppe Hexenmeister geschrieben, die ohne Unterstützung einen Teufelsjäger beschwörten.$b$bVielleicht kann Jorah Annison Euch dabei helfen. Heute arbeitet er als Kartograf in Undercity, weiß aber dennoch mehr über alte Schriften als ich.",objectives={"Sprecht mit Jorah Annison in Undercity."}]])
R(1802,"Foliant der Kabale",[[description="Er ist verschollen, aber man glaubt zu wissen, wo man ihn finden könnte.$b$bNur eine Kopie wurde jemals angefertigt, und die wurde einst beschädigt, eine Vielzahl von Seiten herausgerissen. Man munkelt, dass er irgendwie den Zentauren von Tausend Nadeln in die Hände gefallen sein soll.$b$bDer Rest ging an der Küste westlich von Southshore verloren, als er per Schiff zum Hafen von Menethil hätte transportiert werden sollen. Er kam nie an.$b$bAls Gegenleistung für dieses Wissen verlange ich nur, dass Ihr ihn findet und mir zur Ansicht bringt.",objectives={"Beschafft den schimmeligen Folianten und das zerlumpte Manuskript für Krom Stoutarm in Ironforge."}]])
R(1803,"Foliant der Kabale",[[description="Ah! Ich sehe, Ihr seid ein Hexenmeister, der meinen Geschmack teilt. Den Folianten der Kabale zu beschaffen ist ein würdiges Ziel. Habt Ihr gewusst, dass er sich einst innerhalb der Mauern von Lordaeron befand? Aber er wurde beschädigt, fast die Hälfte der Seiten herausgerissen. Wer würde so eine abscheuliche Tat begehen?$b$bDiese Hälfte ist verschollen, doch man munkelt, sie soll den Zentauren von Tausend Nadeln in die Hände gefallen sein.$b$bDer Rest des Textes sollte nach Ironforge gebracht werden, ging aber während der Überfahrt an der Westküste von Southshore verloren.",objectives={"Beschafft den schimmeligen Folianten und das zerlumpte Manuskript für Jorah Annison in Undercity."}]])
R(1804,"Foliant der Kabale",[[description="Ach ja, es ist recht schwer, ihn aus der Hand zu geben. Aber Ihr habt ihn gefunden und natürlich Wichtigeres damit zu tun. Vergesst nur nicht, Strahad zu sagen, dass ich eine Kopie haben möchte.$b$bWährend Ihr fort wart, hat er eine Nachricht für Euch geschickt. Er sagte mir, damit seine Akolyten bei der Beschwörung helfen können, müsst Ihr drei Kanalisierungsruten beschaffen.$b$bEr weiß vielleicht nicht, wo man die findet, aber ich! Sie wurden zuletzt von den Orcs des Dragonmawklans im Sumpfland verwendet. Ich würde mich mal mit ihren Zauberern in Verbindung setzen!",objectives={"Bringt den rekonstruierten Folianten und 3 Kanalisierungsruten zu Strahad Farsan in Ratchet."}]])
R(1805,"Foliant der Kabale",[[description="Das ist einer der interessantesten Texte, die ich in den letzten Jahren gelesen habe. Die Auswahl hier ist nicht sonderlich groß - zum Großteil sind es Bücher über Geographie - und ich habe sie schon alle gelesen. Hoffentlich schickt mir Strahad eine Kopie dieses Folianten, wenn er die Chance dazu hat.$b$bDa wir gerade von ihm sprechen: während Ihr fort wart, habe ich eine Nachricht von ihm erhalten. Für Eure Aufgabe müsst Ihr drei Ruten des Kanalisierens beschaffen.$b$bWeil Ihr mir diesen Text gezeigt habt, weihe ich Euch in ein Geheimnis ein: Ihr findet die Ruten bei den Orcs des Dragonmawklans im Sumpfland.",objectives={"Bringt den rekonstruierten Folianten und 3 Ruten des Kanalisierens zu Strahad Farsan in Ratchet."}]])
R(1806,"Die Prüfung der Rechtschaffenheit",[[description="Warum gehen wir nicht rüber zur Schmiede und fangen damit an? Ich treffe schon seit einiger Zeit Vorbereitungen für Eure Ankunft, daher dürfte es nicht allzu lange dauern.$B$BWenn wir fertig sind, werdet Ihr viel besser gerüstet sein, das Licht zu verteidigen, als bisher, das schwöre ich Euch.$B$BIch will ehrlich sein, $n, wenn ich die Ergebnisse Eurer Taten sehe, erfüllt mich ein gewisser Neid. Doch das Wissen, dass ich auf meine bedeutende Weise zu Euren Abenteuern beitragen kann, erfüllt mich mit Freude.",objectives={"Wartet, bis Jordan Stilwell eine Waffe für Euch geschmiedet hat."}]])
R(1818,"Gespräch mit Dillinger",[[description="Todeswache Dillinger sagte mir, er habe einen Job für jemanden wie Euch. Wenn Ihr bereit seid, den Streitkräften der Dunklen Fürstin Euren Wert zu beweisen, dann meldet Euch umgehend bei Dillinger.$B$BTodeswache Dillingers Posten liegt am Westende von Brill, nahe beim Friedhof.",objectives={"Sprecht mit Todeswache Dillinger in Brill."}]])
R(1819,"Ulag der Spalter",[[description="Als die Geißel durch Tirisfal zog, konnten wir einen ihrer Angehörigen einfangen, um ihn zu studieren. Er hatte einen freien Geist und nannte sich Ulag der Spalter. Doch obwohl er einen freien Willen besaß, stand er noch immer unter dem Bann des Lichkönigs.$B$BWir hofften, wir könnten den Einfluss des Königs auf Ulag brechen, doch es gelang uns nicht. Jetzt ist die Zeit gekommen, ihn zu befreien. $B$BBefreit und tötet ihn.$B$BAktiviert den Schädelstein-Auslöser beim Mausoleum im Norden. Damit wird das magische Siegel entfernt, das ihn bindet.$B$BUnd dann... seid bereit, $N.",objectives={"Tötet Ulag den Spalter und sprecht dann mit Todeswache Dillinger."}]])
R(1820,"Gespräch mit Coleman",[[description="Ihr habt Euren Wert für die dunkle Fürstin bewiesen, vielleicht könnt Ihr ihn nun an einem ihrer Untertanen beweisen.$B$BColeman Farthing wartet auf einen Krieger, der bereit ist, sein Instrument der Rache gegen die Feinde der Verlassenen zu sein.$B$BIhr findet ihn in der Taverne Zur Galgenschlinge im Osten von Brill.",objectives={"Sprecht mit Coleman Farthing."}]])
R(1821,"Agamand-Erbstücke",[[description="Zu Lebzeiten war die Familie Agamand mein Arbeitgeber und sie war die Ursache für meinen Tod. Es ist nur recht und billig, dass die Agamands jetzt hirnlose Diener des Lichkönigs sind.$B$BUnd jetzt möchte ich ihnen den letzten Rest Ehre nehmen. Geht in ihre Familiengruft und stehlt ihnen die Familienerbstücke: ein Schwert, eine Axt, einen Dolch und einen Streitkolben. Bringt sie mir!$B$BDie Gruft der Familie Agamand liegt am nördlichen Ende von Agamands Mühlen. Der Ort wird durch lauernde Angehörige der Geißel und tote Agamands bewacht.",objectives={"Bringt Coleman Farthing die Axt, das Schwert, den Streitkolben und den Dolch der Familie Agamand."}]])
R(1822,"Erbstückwaffe")
R(1823,"Gespräch mit Ruga",[[description="Ihr seid ein Krieger mit Fertigkeiten und wachsendem Ansehen. Vielleicht seid Ihr bereit für Ruga Ragetotems Prüfung. Wenn ja, findet Ihr Ruga im Camp Taurajo im Brachland.$B$BEr wartet auf Krieger, die seinem Ruf folgen.",objectives={"Sprecht mit Ruga Ragetotem."}]])
R(1824,"Prüfung auf dem Feld der Riesen",[[description="Um diese Prüfung zu bestehen, müsst Ihr nach Süden zum Feld der Riesen reisen. Dort findet Ihr einen Schwarm krabbelnder Insektenwesen. Sie sind neu im Brachland und mir gefällt nicht, was sie ankündigen.$B$BBringt mir einen ihrer noch zuckenden Fühler und vergeudet keine Zeit, $N, denn abgetrennte Fühler zucken nicht lange. Bringt mir die Fühler in der genannten Zeit und Ihr werdet die Prüfung bestehen.",objectives={"Bringt 5 zuckende Fühler zu Ruga Ragetotem im Camp Taurajo."}]])
R(1825,"Gespräch mit Thun'grim",[[description="Thun'grim Firegaze, ein berühmter Orc-Schmied, hat von Euren fortgesetzten Heldentaten im Dienst der Horde gehört. Er möchte eine Rüstung für Euch anfertigen und bittet, dass Ihr umgehend mit ihm sprecht.$B$BThun'grims Lager liegt östlich von Crossroads im Brachland.",objectives={"Sprecht mit Thun'grim Firegaze im Brachland."}]])
R(1838,"Brutale Rüstung",[[description="Ich habe Geschichten über Eure Kraft und Tapferkeit gehört und möchte eine Rüstung für Euch anfertigen, eine Unterstützung für Euch, während die Geschichten über Eure Ruhmestaten wachsen.$B$BAber die Herstellung dieser Rüstung wird eine Aufgabe für sich sein, $n. Ich werde Eure Hilfe benötigen und die Hilfe der anderen Schmiede der Horde.$B$BHier, nehmt diese Rolle. In vielen Nächten habe ich mit fast blinden Augen aufgeschrieben, was ich für die Rüstung benötige. Bringt mir die Gegenstände auf dieser Rolle und ich fertige das erste Teil der Rüstung für Euch an.",objectives={"Bringt Thun'grim Firegaze 15 rauchige Eisenblöcke, 10 pulverisierte Azurite, 10 Eisenbarren und 1 Phiole Phlogiston."}]])
R(1839,"Ula'elek und die brutalen Stulpen",[[description="Der Trollschmied Ula'elek wird die brutalen Stulpen für Euch anfertigen. Er wohnt mit seinen Darkspearbrüdern in Durotar in Sen'jin und erwartet Eure Ankunft.",objectives={"Sprecht mit Ula'elek in Durotar."}]])
R(1840,"Orm Stonehoof und der brutale Helm",[[description="Orm Stonehoof wird ob seiner Fertigkeiten hoch geachtet. Er wird den brutalen Helm für Euch machen.$B$BSucht ihn in Thunder Bluff beim Teich nahe dem großen, zentralen Totem der Stadt.",objectives={"Sprecht mit Orm Stonehoof in Thunder Bluff."}]])
R(1841,"Velora Nitely und die brutalen Beinschützer",[[description="Es heißt, vor ihrem Tod hätte Velora Nitely zu den besten Rüstungsschmieden von Lordaeron gehört. Offenbar konnte der Tod ihrem Talent nichts anhaben. Sprecht mit Velora - sie wird die brutalen Beinschützer für Euch machen.$B$BVelora geht ihrem Gewerbe in Undercity unterhalb von Lordaeron nach, im Handwerksviertel.",objectives={"Sprecht in Undercity mit Velora Nitely."}]])
R(1842,"Satyrhufe",[[description="Ich kann Euch ein Paar brutale Stulpen machen, denen große Magie innewohnen wird. Doch vorher müsst Ihr diese Magie sammeln und mir bringen.$B$BDie Satyrn halten sich im nordöstlichen Teil von Ashenvale auf wegen der Macht, die dem Wald innewohnt. Sie nähren sich an seiner Reinheit, saugen sie ab und verderben sie. An den geschwollenen, ungespaltenen Hufen erkennt man, welche Satyrn die meiste Magie Ashenvales aufgenommen haben.$B$BDiese Hufe besitzen große Macht. Ich brauche sie, um Eure Stulpen anzufertigen.",objectives={"Bringt 7 ungespaltene Satyrhufe zu Ula'elek in Sen'jin in Durotar."}]])
R(1843,"Brutale Stulpen")
R(1844,"Schimärenhorn",[[description="Ich mache Euch den Helm, doch vorher müsst Ihr mir zeigen, dass Ihr würdig seid.$B$BEingebettet in die nordwestlichen Ausläufer des Steinkrallengebirges liegt das verbrannte Tal. Das war einst ein fruchtbarer Ort, ist aber heute besudelt und voll Asche. Die Kreaturen, die dort noch hausen, sind wahnsinnig vor Schmerz und Verzweiflung.$B$BAn diesen Ort schicke ich Euch, $N.$B$BIhr müsst zum verbrannten Tal reisen und eine Schimärenmatriarchin suchen. Tötet sie, erlöst sie von ihrem Elend. Bringt mir ihr galvanisiertes Horn als Beweis, dann mache ich den Helm für Euch.",objectives={"Bringt ein galvanisiertes Horn zu Orm Stonehoof in Thunder Bluff."}]])
R(1845,"Brutaler Helm")
R(1846,"Schienbeinknochen der Dragonmaw",[[description="Um brutale Beinschützer zu machen, brauche ich eine Stütze aus stabilem Schienbeinknochen. Die Orcs des Dragonmawklans im Sumpfland haben hübsche, dicke Schienbeinknochen. Die brauche ich.$B$BAber sie müssen stabil sein. Prüft die Schienbeinknochen unbedingt, wenn Ihr sie einsammelt. Wenn Ihr sie mit bloßen Händen zerbrechen könnt, sind sie nicht stabil genug für mich.",objectives={"Bringt 8 stabile Schienbeinknochen eines Dragonmaw zu Velora Nitely in Undercity."}]])
R(1847,"Brutale Beinschützer")
R(1848,"Brutale Halsberge")
R(1858,"Die Shattered-Hand",[[description="Ich überlasse es Euch, Tazans Ranzen zu öffnen und mir seinen Inhalt zu bringen. Der Schlossmechanismus ist komplex, daher wäre es wohl das Beste, wenn Ihr Euch den Schlüssel beschafft.$b$bDa Ihr ihn bei Tazans Leichnam nicht gefunden habt, kann ich nur annehmen, dass er ihn jemandem in Obhut gegeben hat. Ah, ja, ganz recht! Er hatte einen Assistenten namens Gamon. Ein Trunkenbold, vermutlich findet Ihr ihn in der Taverne. Vielleicht könnt Ihr ihm den Schlüssel heimlich abnehmen.",objectives={"Stehlt Tazans Schlüssel, öffnet seinen Ranzen damit und bringt den Inhalt zu Therzok in der Kluft der Schatten in Orgrimmar."}]])
R(1859,"Therzok",[[description="Sprecht leiser, $n. Ja, ich kenne Euren Namen. Mir wurde gesagt, ich soll nach einem Orc Ausschau halten, auf den Eure Beschreibung passt.$b$bSoweit wir gehört haben, könnt Ihr im Gefecht bestehen und habt nichts gegen ein wenig Heimlichtuerei von Zeit zu Zeit einzuwenden.$b$bHabe ich Recht?$b$bWie auch immer, Ihr solltet Therzok in Orgrimmar aufsuchen. Er hat ein Angebot, das Ihr Euch anhören solltet.",objectives={"Sprecht mit Therzok in der Kluft der Schatten in Orgrimmar."}]])
R(1860,"Gespräch mit Jennea",[[description="Wir Magier haben eine Aufgabe, die erledigt werden muss. Sie ist für die Sicherheit von Stormwind und dem Wald von Elwynn von entscheidender Bedeutung.$B$BJennea Cannon kennt die Einzelheiten. Sie studiert im Magiersanktum im Magierviertel von Stormwind. Ihr solltet Euch eiligst zu ihr begeben.",objectives={"Sprecht in Stormwind mit Jennea Cannon."}]])
R(1861,"Spiegelsee",[[description="Diese Welt ist gewaltigen mystischen Kämpfen zum Opfer gefallen, die magische Ströme aus ihren einst stabilen Kanälen rissen. Wir haben Mühe, die Auswirkungen dieser Veränderungen herauszufinden. Einige von uns fürchten das Schlimmste.$B$BAber davon werde ich Euch später mehr erzählen. Im Augenblick müsst Ihr Informationen für uns sammeln.$B$BHier, nehmt dieses Fläschchen. Geht zum Wasserfall des Spiegelsees, südwestlich der Tore von Stormwind, und holt dort eine Probe des Wassers. Bringt sie mir, damit ich die magische Besudelung messen kann.",objectives={"Bringt eine Probe des Spiegelsee-Wassers zu Jennea Cannon in Stormwind."}]])
R(1878,"Wasserbeutelkopfgeld")
R(1879,"Gespräch mit Bink",[[description="$N! Bink, meine Gnomen-Kollegin in Ironforge, hat sich gemeldet. Sie hat eine Aufgabe zu erledigen und will sich dabei nur auf einen Magier verlassen! Seid Ihr $gein Magier:eine Magierin;, $N?$B$BWenn ja, sprecht mit Bink. Sie verbringt ihre Zeit in Ironforge in der Halle der Mysterien im mystischen Krieg.",objectives={"Sprecht mit Bink in Ironforge."}]])
R(1880,"Magitastischer Gizmonitor",[[description="Wir Magier machen mehr als nur mit den Fingern schnippen und hübsche Funken regnen lassen. Wir kontrollieren die Magie, die Grundsubstanz unserer Welt! Das erfordert große Umsicht und Entschlossenheit. Und Wissen... viel, viel Wissen!$B$BEines meiner Geräte, der magitastische Gizmonitor, sammelt und speichert dieses Wissen in riesigen Mengen! Aber ich verlor ihn! Als wir aus unserer Heimat Gnomeregan flohen, ließ ich ihn in einer Truhe in einer unserer Hütten vor der Stadt, und jetzt wimmelt es dort von Lepragnomen!$B$BBitte, $n, findet meinen Gizmonitor wieder!",objectives={"Bringt Bink ihren magitastischen Gizmonitor."}]])
R(1881,"Gespräch mit Anastasia",[[description="$N, Anastasia Hartwell hat eine Aufgabe für jemanden mit Euren Talenten. Sprecht mit ihr im Magieviertel von Undercity und bereitet Euch auf den ersten Auftrag der Magier der Verlassenen vor.",objectives={"Sprecht mit Anastasia Hartwell."}]])
R(1882,"Balnirs Bauernhof",[[description="Die Pestländer im Osten sind entartet. Der Lichkönig hat sie ersonnen, und jetzt breitet sich ihre Magie im Erdboden aus und verdirbt und tötet alles Leben. Die zerstörerischen Kräfte der Seuche haben zwar eine gewisse Bezauberung, doch wir, die Magier der Verlassenen, sind der Meinung, sie ist ungehörig und muss ausgemerzt werden.$B$BDoch zuerst müssen wir herausfinden, wie weit sie sich nach Tirisfal ausgebreitet hat. Geht zu Balnirs Bauernhof im Osten von Tirisfal. Im Garten blühen Blumen - Löwenmäulchen. Sammelt sie und kehrt zurück.",objectives={"Bringt Balnir-Löwenmäulchen zu Anastasia Hartwell im Magierviertel von Undercity."}]])
R(1883,"Gespräch mit Un'thuwa",[[description="Un'thuwa, Stammesmagier in Sen'jin, spürt eine Störung in den magischen Strömen von Durotar und bittet um Unterstützung. Sprecht mit Un'thuwa und tut, was Ihr könnt, um ihm zu helfen.$B$BGelingt Euch das, werden Euch zu gegebener Zeit weitere Geheimnisse enthüllt.",objectives={"Sprecht mit Un'thuwa."}]])
R(1884,"Jujuhaufen",[[description="Der Hexenmeister Zalazane von den Echoinseln hat den normalen Fluss der Magie in Durotar gestört. Das vollbringt er mit besudelten Fetischen, Jujuhaufen, die er auf der Echohauptinsel in seinen Hütten aufgeschichtet hat.$B$BDiese Haufen haben unser Ökosystem verdorben und Hexenmeistern und Höllenkreaturen, die in den dunklen Winkeln des Landes hausen, Macht gegeben.$B$BIhr müsst diese Jujuhaufen zerstören, $n, bevor der Fluss der Magie für immer verändert ist.",objectives={"Zerstört 4 Jujuhaufen und kehrt dann zu Un'thuwa in Sen'jin zurück."}]])
R(1885,"Mennet Carkad",[[description="$n? Nicht ganz das, was ich erwartet hatte, wenn man bedenkt, dass Carkad selbst Interesse an Euch gezeigt hat. Aber das Aussehen kann täuschen, nicht?$b$bSo oder so, Ihr solltet ihn schnellstmöglich aufsuchen. Ihr könnt Euch nicht vorstellen, was aus den Letzten geworden ist, die seinem Ruf nicht Folge leisteten.",objectives={"Sprecht mit Mennet Carkad im Schurkenviertel von Undercity."}]])
R(1886,"Die Todespirscher",[[description="Wenn Ihr Euch den Todespirschern anschließen möchtet, der Elitewache von Lord Varimathras, müsst Ihr Euren Wert beweisen.$b$bIch will Euch nichts vormachen, $N, diese Aufgabe könnte Euren Tod bedeuten.$b$bIch habe ein paar Angelegenheiten, die geregelt werden müssen. Ich benötige die persönlichen Habseligkeiten von Astor Hadren, einem Boten, der zwischen Silberwald und Undercity pendelt. Die Beschaffungsmethode überlasse ich ganz Euch.$b$bJe weniger Ihr über diese Angelegenheit Bescheid wisst, desto besser. Wenn Ihr Erfolg habt, sage ich Euch mehr.",objectives={"Beschafft Astors Empfehlungsschreiben und bringt es zu Mennet Carkad im Schurkenviertel."}]])
R(1898,"Die Todespirscher",[[description="Das Empfehlungsschreiben sollte Andron überzeugen, dass Ihr der Bote seid, auf den er gewartet hat. Ich kenne Andron, er ist nicht so helle im Kopf, dass er Verdacht schöpfen würde.$b$bLord Varimathras vermutet, dass Andron einer anderen Gruppe Unterstützung zuteil werden ließ. Er möchte wissen, was das für eine Organisation ist, und braucht einen Beweis.$b$bIch möchte, dass Ihr mit Andron sprecht und diese Information bekommt. Ihr findet ihn in seinem Geschäft nahe des Apothekariums.",objectives={"Sprecht mit Andron Gant in Undercity."}]])
R(1899,"Die Todespirscher",[[description="Ihr findet das Geschäftsbuch mit den Informationen, die Eure Auftraggeber suchen, auf dem Bücherregal hinter mir. Überbringt es mit meinen besten Wünschen und sagt ihnen, dass ich es bevorzugen würde, wenn sie Euch schicken, sollte unsere Übereinkunft ihnen so lieb und teuer sein, dass sie sie fortsetzen möchten.",objectives={"Bringt Astors Geschäftsbuch zu Mennet Carkad im Schurkenviertel von Undercity."}]])
R(1918,"Das beschmutzte Element",[[description="Der erschlagene Elementar hat eine intensiv glühende Kugel aus Wasser zurückgelassen. Der Inhalt dieser Kugel ist bestenfalls als abstoßend zu bezeichnen. Es ist eine sichere Annahme, dass, was auch immer das Wasser des Mystralsees beschmutzt hat, höchstwahrscheinlich im Wasser dieser Kugel enthalten ist.$B$BEs ist nicht gerade weit bekannt, wer sich für solch einen Fund interessieren könnte. Vielleicht weiß die Person etwas darüber, die Euch ursprünglich zum See hinausgeschickt hatte - Mastok Wrilehiss im Splintertreeposten.",objectives={"Bringt die beschmutzte Wasserkugel zu Mastok Wrilehiss im Splintertreeposten in Ashenvale."}]])
R(1919,"Meldung bei Jennea",[[description="Euer Wissen über das Handwerk wächst, $N. Seid Ihr jetzt bereit, die wahren Lektionen zu beginnen? Seid Ihr bereit, Euren Platz in dem geheimen Krieg einzunehmen, den wir führen?$B$BWenn ja, sprecht mit Jennea Cannon im Magiersanktum im Magierviertel von Stormwind. Sie hat eine Aufgabe für Euch, die Euer erstes Fenster in die Welt des Unsichtbaren öffnen wird.",objectives={"Sprecht in Stormwind mit Jennea Cannon."}]])
R(1920,"Untersuchungen im Blauen Eremiten",[[description="Es wurde von einer Störung in der Taverne 'Zum blauen Eremiten' im Magierviertel berichtet. Jetzt wandern seltsame unsichtbare Kreaturen durch die Taverne. Ich fürchte, dort hat sich ein Manariss gebildet.$B$BIch möchte, dass Ihr die Taverne untersucht und diese Kreaturen fangt. Benutzt die Inkantation der Manifestation, um die Kreaturen in der Taverne sichtbar zu machen, überwältigt sie und fangt sie dann mit einem Verwahrungskasten ein. Wenn Ihr genug habt, kommt mit den gefüllten Kästen, den leeren Kästen und der Anrufung zu mir zurück.",objectives={"Nehmt Euch die Inkantation der Manifestation und die Truhe mit Verwahrungskästen vom Tisch, hinter Jennea Cannon. Bringt 3 gefüllte Verwahrungskästen zu Jennea im Magiersanktum."}]])
R(1921,"Materialsammlung",[[description="Ihr habt Euren Magierkollegen gut gedient, jetzt wird es Zeit, die Hexerrobe anzuziehen. Wynne Larson kann Eure Robe nähen, aber Ihr müsst ihr die erforderlichen Materialien bringen. $B$BEure Robe wird aus Leinen bestehen, das leicht zu beschaffen ist, aber Ihr müsst auch aufgeladene Rissedelsteine finden, die nur in der Silberbachmine vom Loch Modan zu finden sind, wo die Minenarbeiterliga der Zwerge sie in Kisten zurückgelassen hat.$B$BBeschafft das Leinen und die Edelsteine und bringt sie zu Wynne Larson in das Konfektionsgeschäft Larson im Magierviertel.",objectives={"Bringt 10 Leinentücher und 6 aufgeladene Rissedelsteine zu Wynne Larson in Stormwind."}]])
R(1938,"Urs Abhandlung über Schattenmagie",[[description="Vor langer Zeit studierten drei Magier in diesem Turm, bis einer den dunklen Künsten verfiel. Man bedrängte ihn, von dieser bösen Magie zu lassen, aber er konnte nicht widerstehen. Und so wurde er verbannt.$B$BDas neue Domizil des gefallenen Magiers ist der Turm von Ilgalar im Rotkammgebirge. Er hat ein mächtiges Buch dorthin mitgenommen -'Urs Abhandlung über Schattenmagie'.$B$BWir, die Magier von Stormwind, möchten dieses Buch zurück. Begebt Euch in den Turm von Ilgalar, sucht den Folianten in seiner Bibliothek und bringt ihn mir.",objectives={"Bringt 'Urs Abhandlung über Schattenmagie' zu Zaubermeister Andromath in Stormwind."}]])
R(1939,"Zaubermeister Andromath",[[description="Der Zaubermeister Andromath wünscht Euch zu sprechen, $N. Er ist oben im Magiersanktum im Magierviertel von Stormwind.$B$BEs wäre klug, mit ihm zu sprechen, denn Andromath ist einer der mächtigsten Magier, die nicht in Dalaran eingesperrt sind. Ein Rat von ihm ist in jedem Fall ein guter Rat.",objectives={"Sprecht mit Zaubermeister Andromath."}]])
R(1940,"Makellose Spinnenseide",[[description="Eure Treue ist unerschütterlich, $n. Ich glaube, es ist an der Zeit, dass Ihr ein besseres Kleidungsstück bekommt, das einem geschickten Magier von Eurem Rang angemessener ist. Wenn Ihr die erforderlichen Materialien sammeln könnt, werde ich veranlassen, dass die Robe angefertigt wird.$B$BIhr müsst in den Dämmerwald und Aaskrabblerspinnen jagen. Extrahiert ihre Seide, aber nur die feinste und makelloseste. Wenn Ihr genug davon habt, bringt sie zu Wynne Larson ins Konfektionsgeschäft Larson hier im Magierviertel. Sie wird Eure Robe anfertigen.",objectives={"Bringt 8 Rollen makelloser Spinnenseide zu Wynne Larson in Stormwind."}]])
R(1941,"Managewirkte Robe")
R(1942,"Astralknotengewand")
R(1943,"Gespräch mit Deino",[[description="Die Trollmagierin Deino bedarf Eurer Unterstützung, $N. Sie residiert in Orgrimmar im Dunkeldornen-Lodge.",objectives={"Sprecht mit Deino."}]])
R(1944,"Wasser von Xavian",[[description="Die legendäre Stadt Xavian liegt tief im östlichen Ashenvale. Die Geschichten über ihr Wissen aus längst vergangener Zeit sind den Gebildeten wohl bekannt. Man sagt, die Wasser von Xavian bergen enorme magische Kräfte.$B$BBringt mir eine Probe dieses Wassers direkt von der Quelle.$B$BNehmt dieses Fläschchen und reist nach Xavian. Füllt Wasser am höchsten Wasserfall ab und kehrt zu mir zurück. Aber seid vorsichtig in der uralten Stadt - heute hausen Satyrn in den Ruinen, die gar nicht mögen, wenn sich Magier in ihre Angelegenheiten einmischen.",objectives={"Bringt die Probe des Wassers von Xavian zu Deino in Orgrimmar."}]])
R(1945,"Lachende Schwestern",[[description="Als Dank für Eure Dienste habe ich veranlasst, dass Euch neue Roben angefertigt werden, sofern Ihr die erforderlichen Materialien beschaffen könnt...$B$BFür diese Roben müsst Ihr nach Ashenvale zurückkehren und Locken vom Haar der lachenden Schwestern beschaffen - Dryaden, die sich in der Nähe des Raynewoodes tummeln.$B$BWenn Ihr das Haar habt, bringt es zu Kil'hala, einem Trollschneider in Crossroads im Brachland. Er wird Euch erwarten und Eure Roben zuschneiden.",objectives={"Bringt 12 Haarlocken der lachenden Schwestern zu Kil'hala in Crossroads."}]])
R(1946,"Netherspitzengewand")
R(1947,"Reise in die Marschen",[[description="Jetzt ist es an der Zeit, Euch Euren Magierzauberstab zu verdienen. Um diese Aufgabe zu beginnen, solltet Ihr mit der Menschen-Einsiedlerin Tabetha in den Marschen von Dustwallow sprechen. Ihr findet ihre Hütte tief in den Marschen, westlich von Theramore.$B$BSprecht mit ihr, denn sie verfügt über umfangreiches Wissen. Tabethas Hütte befindet sich westlich von Theramore und direkt nördlich der Stonemaul Ruinen.",objectives={"Sprecht mit Tabetha."}]])
R(1948,"Gegenstände der Macht",[[description="Es ist nicht leicht, einen Magierzauberstab anzufertigen. Es sind rare Substanzen erforderlich und ein Gefäß muss gemacht werden, das große Mengen magischer Energie speichern kann. Ihr müsst diese Sachen sammeln und mir bringen.$B$BIch habe auf dieses Pergament geschrieben, was Ihr braucht und wie Ihr es bekommt. Bringt mir exakt das, was auf der Liste steht und folgt meinen schriftlichen Anweisungen auf den Buchstaben genau, denn wenn Ihr das nicht macht, geht bei der Herstellung Eures Zauberstabes vielleicht etwas ... schief.",objectives={"Bringt 1 Stück Jade und den vom Blitz aufgeladenen Dornbusch zu Tabetha in den Marschen von Dustwallow."}]])
R(1949,"Verborgene Geheimnisse",[[description="Um Euren Zauberstab herzustellen, muss ich einige wichtige Stellen in einem bestimmten Buch lesen. Dieses Buch wurde von dem Magus Tirth geschrieben und heißt 'Rituale der Macht'.$B$BIch besitze kein Exemplar dieses Buchs und es ist in keiner der großen Bibliotheken der Welt zu finden. Daher müsst Ihr mit Tirth sprechen und es von ihm bekommen.$B$BViel Glück. Tirth war ein großer Magier und Gelehrter, aber heute verbringt er seine Zeit bei den Gnomen- und Goblinrennen auf der schimmernden Ebene und trinkt und spielt.",objectives={"Sprecht mit Magus Tirth in der Schimmernden Ebene."}]])
R(1950,"Der Knüller schlechthin",[[description="Ich kann Euch mit dem Buch helfen, doch vorher müsst Ihr mir helfen!$B$BDer Foliant, den Ihr sucht, befindet sich in meiner magisch versiegelten Geldkassette. Um sie zu öffnen, muss ein bestimmter Satz gesprochen werden, aber ich kann mich nicht mehr an ihn erinnern! Normalerweise merkt sich mein Assistent so etwas, aber der ist unauffindbar.$B$BWenn Ihr mein Buch möchtet, sucht meinen Lehrling! Fragt auf der Rennbahn - wenn Ihr Glück habt, hat ihn jemand gesehen. Schleppt ihn entweder hierher oder entlockt ihm wenigstens meinen magischen Satz, damit wir die Kassette aufbekommen!",objectives={"Bringt den Satz für Tirths Geldkassette in Erfahrung und kehrt zu Tirth zurück."}]])
R(1951,"Rituale der Macht",[[description="Hm, wenn ich so darüber nachdenke, ich habe mein Buch nicht! Wisst Ihr, ich hatte Spielschulden, und um sie zu bezahlen, verkaufte ich das letzte Exemplar von 'Rituale der Macht' an ein Mitglied der Kleriker...$B$BEin Mitglied der Scharlachroten Bruderschaft. Er muss es zur Bibliothek im Scharlachroten Kloster in Tirisfal gebracht haben!$B$BWenn Ihr das Buch wollt, müsst Ihr in das Kloster gehen und es suchen. Und entschuldigt den ganzen Ärger. Ich bin neuerdings nicht mehr ich selbst...",objectives={"Bringt das Buch 'Rituale der Macht' zu Tabetha in den Marschen von Dustwallow."}]])
R(1952,"Der Zauberstab des Magiers",[[description="Ich werde jetzt die Zauberstäbe machen.",objectives={"Sprecht nach ihrem Ritual mit Tabetha."}]])
R(1953,"Rückkehr in die Marschen",[[description="$N, es wird Zeit, dass Ihr mit Tabetha sprecht... der Einsiedlerin in den Marschen von Dustwallow. Sie wird Euch in der Herstellung einer mächtigen Magiergerätschaft unterweisen.$B$BTabethas Hütte liegt tief in den Marschen von Dustwallow, westlich von Theramore.",objectives={"Sprecht mit Tabetha."}]])
R(1954,"Die Höllenkugel",[[description="Als ersten Schritt müsst Ihr eine Kugel voll Macht beschaffen. Die Hexenmeister der Burning Blade haben hübsche, hochwertige Kugeln... zu dumm, dass sie Dämonen darin eingebunden haben! Aber das können wir ändern, ja.$B$BGeht nach Desolace und nehmt einem Beschwörer der Burning Blade eine Höllenkugel ab. Beschwörer findet Ihr bei Mannorocs Koven.$B$BKommt zu mir zurück, wenn Ihr die Kugel habt.",objectives={"Bringt eine Höllenkugel zu Tabetha in den Marschen von Dustwallow."}]])
R(1955,"Die Austreibung",[[description="Jetzt, da wir eine Beschwörerkugel haben, müssen wir den Dämon darin austreiben. Ich kann es machen. Das ist der einfache Teil.$B$BIhr habt die schwere Aufgabe. Ihr müsst den Dämon töten, wenn er draußen ist.$B$BUnd Ihr müsst Euch beeilen. Wenn Ihr zu lange braucht, springt er in die Kugel zurück und wir müssen von vorn anfangen!$B$BAlso macht Euch bereit. Bereitet Eure stärksten Zauber vor, habt Eure Tränke parat und holt einen Freund, wenn Ihr einen habt. Denn das hier wird nicht angenehm.",objectives={"Tötet den Dämon der Kugel und sprecht dann mit Tabetha."}]])
R(1956,"Macht in Uldaman",[[description="Jetzt, nachdem der Dämon entfernt wurde, müssen wir eine Kraftquelle finden. Leider sind die besten Kraftquellen meistens die ältesten und die, an die man am schwersten rankommt. Ist schon lustig, wie einem das Schicksal manchmal mitspielt, wie?$B$BAlso müsst Ihr nach Uldaman und dort die Obsidianschildwache besiegen. Der Kerl ist groß, er ist zäh und seine Kraftquelle hat ganz schön Pep.$B$BIch wünsche Euch viel Glück, $N. Falls Ihr kein Glück haben solltet, tja... dann war es schön, Euch gekannt zu haben.",objectives={"Beschafft Euch eine Obsidiankraftquelle und bringt sie in die Marschen von Dustwallow zu Tabetha."}]])
R(1957,"Manawogen",[[description="Wir sind fast fertig, aber dieser letzte Schritt ist der gefährlichste, $n.$B$BIch habe die leere Beschwörerkugel und bin bereit, sie zu ermächtigen. Das machen wir, indem wir die Energie eines Manarisses anzapfen. Ich wirke einen Zauber, der vorübergehend einen Riss auftut, aus dem Kreaturen, Manawogen, herauskommen. Ihr müsst die Manawogen vernichten, damit ihre Macht freigesetzt wird, die ich dann einsammle.$B$BZerschlagt genug Manawogen, bevor sich der Riss schließt, und ich versiegle ihre gesammelte Energie in Eurer Kugel.",objectives={"Vernichtet 12 Manawogen innerhalb des Zeitlimits."}]])
R(1958,"Himmlische Macht")
R(1959,"Meldung bei Anastasia",[[description="Die Magier von Undercity haben eine magische Störung in der Stadt bemerkt und die Magier der Horde um Untersuchung gebeten.$B$BAnastasia Hartwell kann Euch mehr sagen. Sprecht mit Ihr im Magieviertel in Undercity.",objectives={"Sprecht mit Anastasia Hartwell."}]])
R(1960,"Untersuchungen im Alchimistenladen",[[description="Algernons Alchimistenladen im Apothekarium ist das Zentrum einer seltsamen Störung. Unsichtbare, aus reiner Magie bestehende Kreaturen halten sich in dem Laden auf - dafür muss es einen Grund geben, und den müssen wir herausfinden!$B$BUntersucht die Störung und fangt diese Kreaturen. Nehmt Euch von dort hinten eine Truhe mit Kästen und eine Rolle. Benutzt im Laden die Rolle, um die Kreaturen sichtbar zu machen, überwältigt sie mit Euren Zaubern und fangt sie dann mit einem Kasten ein. Kommt mit den gefüllten Kästen, den leeren Kästen und der Anrufung zu mir zurück.",objectives={"Besorgt eine Inkantation der Manifestation und eine Truhe mit Verwahrungskästen von Anastasia Hartwell. Bringt 3 gefüllte Verwahrungskästen, die Truhe mit Verwahrungskästen sowie die Inkantation der Manifestation zu Anastasia in Undercity."}]])
R(1961,"Materialsammlung",[[description="Jetzt ist es Zeit, Eure erste Magierrobe anzulegen, $n. Sie ist ein Zeichen Eures Ranges und ein Zeugnis für Euren Wert.$B$BUm die Robe zu bekommen, müsst Ihr Manaedelsteine von den Magiern von Dalaran im Silberwald sammeln. Ihre Überzeugungen ähneln den unseren, daher ist es ein wenig geschmacklos, sie zu töten, aber wenn sie keine Kraft haben, uns Widerstand zu leisten, verdienen sie es nicht, zu leben.$B$BBringt die Edelsteine und das Leinen zu Josef Gregorian in der Schneiderei im Magieviertel.",objectives={"Bringt 10 Leinentücher und 6 Manaedelsteine aus Dalaran zu Josef Gregorian."}]])
R(1962,"Roben des Zauberfeuers")
R(1963,"Die Shattered-Hand",[[description="Die Methoden des Kriegshäuptlings sind zu zimperlich. Er wagt nicht, die Macht der Horde zu entfesseln. Einst waren wir stärker, allesamt mächtige Eroberer. Diesen Stolz müssen wir zurückerlangen, und der Klan der Shattered-Hand wird dies bewerkstelligen.$b$bWir sammeln Kraft aus den Schatten und schlagen im Verborgenen gegen exponierte Feinde zu. Eine Aufgabe müsst Ihr für mich erledigen, um Euren Wert zu beweisen.$b$bDer Troll Tazan treibt Handel mit den Piraten bei Ratchet. Er hat Informationen, die ich haben muss. Tötet ihn und bringt mir seinen Ranzen.",objectives={"Tötet Tazan und bringt seinen Ranzen zu Therzok in der Kluft der Schatten in Orgrimmar."}]])
R(1978,"Die Todespirscher",[[description="Das Syndikat? Darauf wäre ich nie gekommen. Offenbar sind die Lords von Alterac in den Jahren seit ihrem Verrat tief gesunken.$b$bLord Varimathras wird es mit Freuden hören, und da wir diese Entdeckung weitgehend Euch verdanken, ist es nur recht und billig, dass Ihr ihm die Nachricht überbringt.$b$bAh, und wie konnte ich das vergessen?$b$bWillkommen bei den Todespirschern.",objectives={"Bringt Androns Geschäftsbuch zu Varimathras in der Halle der dunklen Fürstin in Undercity."}]])
R(1998,"Fenwick Thatros",[[description="Lord Varimathras hat mir soeben in einer Botschaft über eine Gefahr für die Verlassenen berichtet, die unverzüglich ausgeschaltet werden muss. Sein Name ist Fenwick Thatros. Lord Varimathras glaubt, dass er einer der Anführer der Untoten sei, die sich im Silberwald angesiedelt haben.$b$bMir kam sofort Euer Name in den Sinn, $n. Ich habe Vertrauen in Eure Fähigkeiten und glaube, Ihr werdet diese Mission fehlerfrei abschließen.$b$bDie letzte Meldung von den Todespirschern im Silberwald deutet darauf hin, dass Thatros nahe der verfallenen Fähre am Lordameresee zu finden ist.",objectives={"Tötet Fenwick Thatros und bringt seinen Kopf zu Mennet Carkad im Schurkenviertel von Undercity."}]])
R(1999,"Werkzeuge des Handwerks",[[description="Die Hexer der Kirin Tor bei Ambermill haben wichtige Dokumente eingelagert, die den aktuellen Zustand von Dalaran betreffen. Das wissen wir durch die Aussagen eines unserer Gefangenen. Lord Varimathras hat die Aufgabe, diese zu beschaffen, den Todespirschern übertragen.$b$bDas ist eine Arbeit für Euch, $n. Ihr braucht allerdings etwas Ausrüstung und Kenntnisse im Schlossknacken. Sprecht mit Estelle Gendry, unserer Lageristin, und bittet sie um ein Werkzeugset, bevor Ihr aufbrecht.",objectives={"Sucht den Statusbericht von Dalaran und bringt ihn zu Mennet Carkad im Schurkenviertel von Undercity."}]])
R(2038,"Bingles' verschwundene Werkzeuge",[[description="Als wäre es nicht schlimm genug gewesen, in den Loch zu stürzen, haben mich auch noch Troggs von der nahe gelegenen Insel angegriffen und mir mein Werkzeug und meinen speziellen Sprengstoff \"Superspreng\" aus der Blastenheimer-Sprengstoffstube gestohlen. Ohne Gyrokopter und Sprengstoff hat die Bewegung keine Chance!$B$BBeschafft mir meine Werkzeuge wieder und findet mein Superspreng aus der Sprengstoffstube, $N. Für Gnomeregan!",objectives={"Sucht Bingles' Werkzeuge und bringt sie ihm zurück. Es sind:$B$BBingles' Schraubenschlüssel, Bingles' Schraubendreher, Bingles' Hammer und Bingles' Sprengstofftube."}]])
R(2039,"Sucht Bingles",[[description="Wir haben den Kontakt mit Bingles verloren! Er wurde zu einer Aufklärungsmission über Gnomeregan geschickt und hat sich seit mehr als einer Woche nicht mehr gemeldet. Ich weiß, er hat sich selbst in die Luft gejagt.$B$BZuletzt sah man ihn über dem Loch fliegen. Vielleicht könnt Ihr dies untersuchen, $n?",objectives={"Sucht Bingles Blastenheimer am Loch Modan."}]])
R(2040,"Unterirdischer Angriff",[[description="Gnomeregan ist diesen elendigen Troggs in die Hände gefallen! Die Situation ist ernst, aber vielleicht könnt Ihr helfen, $n.$B$BTief in den Todesminen gibt es einen funktionierenden Goblinschredder. Sucht diesen Schredder und bringt die intakte Energieversorgung mit. Mit der Energieversorgung des Schredders können wir unseren gyrobohrmatischen Exkavationatoren die erforderliche Energie zuführen, um durch die felsigen, unterirdischen Grenzen von Gnomeregan zu brechen und einem Gnomenangriff den Weg zu ebnen!",objectives={"Holt das Gnoam-Sprecklesprocket aus den Todesminen und bringt es Shoni der Schtillen in Stormwind."}]])
R(2041,"Sprecht mit Shoni",[[description="Vielleicht... Vielleicht könnt Ihr uns im Kampf um Gnomeregan unterstützen.$B$BIn Stormwind findet Ihr den Kommandant unserer Untergrund-Kampftruppe, Shoni die Schtille. Shoni braucht Hilfe für ihre gyrobohrmatischen Exkavationatoren.$B$BIhr findet sie wahrscheinlich bei den Zwergen in Stormwind.$B$BViel Glück, $N.",objectives={"Sprecht mit Shoni der Schtillen in Stormwind."}]])
R(2078,"Gyromasts Rache",[[description="Landratte, Ihr müsst meinen Ersten Maat finden.$B$BNehmt diesen Schlüssel, steckt ihn in sein' Gulliver und schafft ihn her, dasser seim Käpt’n dient.$B$BDiese Murlocs und ihr Häuptling werden nich so froh sein, wenn der Erste Maat sie zu fassen kriegt!",objectives={"Sucht Gelkaks Ersten Maat, den Dreschonator 4100, und führt ihn zu Gelkak zurück."}]])
R(2098,"Gyromasts Rettung",[[description="Das Piratenleben ist eines der Schwersten, Landratte. Es dreht sich nicht nur um Plündern und Saufen! Wehe, mein Schiff sank vor der Küste! Schuld daran sind diese dreisten Dreschadons.$B$BIch muss mein' Ersten Maat funktionstüchtig wiederham!$B$BAls ich an Land gespült wurde, zerbrach der Schlüssel für meinen Ersten Maat an den Felsen und wurde von den Biesterchen von Dunkelküste geraubt. Aus den Augenwinkeln sah ich tobende Kriecher, riesige Waldschreiter und Murlocs, die das Wrack durchstöberten...",objectives={"Sucht die drei Stücke von Gelkaks Schlüssel und bringt sie Gelkak Gyromast."}]])
R(2118,"Verseuchtes Land",[[description="Eine Erkrankung breitet sich in Dunkelküste aus und befällt Körper und Geist aller, die damit in Kontakt kommen.$B$BDie Distelbären wurden am schwersten von der Seuche getroffen. Die einst edlen Tiere sind jetzt ein Instrument der Zerstörung - tollwütig und rasend. Ich habe möglicherweise ein Heilmittel für dieses Leiden.$B$BGeht mit dieser Falle in den Wald und legt sie auf den Boden. Jeder tollwütige Distelbär, der das Licht kreuzt, wird für kurze Zeit friedfertig. Wenn der Bär erst einmal friedfertig ist, wird er Euch folgen. Führt ihn hierher, $n.",objectives={"Fangt einen lebenden tollwütigen Distelbären und bringt ihn zu Tharnariun."}]])
R(2138,"Ausrottung der Infizierten",[[description="Wie ich befürchtete, das Heilmittel wirkt nicht.$B$BEs stimmt mich traurig, Geschöpfe der Natur zum Tode zu verurteilen, aber die kranken und besudelten Distelbären müssen ausgerottet werden.$B$BKehrt in den Wald zurück und vernichtet 20 tollwütige Distelbären, $n. Das wird die Seuche sicher nicht stoppen, aber den Schaden, den die Tiere unserem Wald und seinen Bewohnern zufügen, zumindest für kurze Zeit verringern.",objectives={"Befreit den Wald von 20 tollwütigen Distelbären und kehrt dann zu Tharnariun Treetender in Dunkelküste zurück."}]])
R(2139,"Tharnariuns Hoffnung",[[description="Das Überleben unseres Volkes und unserer Länder ist mit bedauerlichen Kosten verbunden, $n.$B$BIhr habt das Blut der Diener der Natur vergossen; viele kranke Tiere habt Ihr erledigt. Das Volk von Auberdine steht in Eurer Schuld, denn die Qualen des Waldes sind gelindert - wenn auch nur vorübergehend.$B$BIch habe eine letzte Aufgabe für Euch, doch seid gewarnt, Ihr werdet wieder töten müssen. Dies wird hoffentlich das letzte Mal sein, dass ich Euch rufen muss, $n.$B$BIn einer Höhle im Nordosten, nahe Bashal'Aran, haust die Höhlenmutter. Tötet sie.",objectives={"Sucht und tötet die Höhlenmutter."}]])
R(2158,"Ruhe und Entspannung",[[description="Jeder Abenteurer sollte ausruhen, wenn ihn die Erschöpfung überkommt - und es gibt keinen besseren Platz für Ruhe und Entspannung als das Gasthaus Zur Höhle des Löwen!$B$BGastwirt Farley, der Inhaber der 'Höhle des Löwen', ist mein bester Freund. Wenn Ihr ihm sagt, dass ich Euch geschickt habe, dann gewährt er Euch vielleicht einen Spezialrabatt auf Essen und Trinken.$B$BDas Gasthaus Zur Höhle des Löwen findet Ihr, wenn Ihr auf der Straße nach Süden reist - Ihr könnt es nicht verfehlen!",objectives={"Sprecht im Gasthaus Zur Höhle des Löwen mit Gastwirt Farley."}]])
R(2159,"Dolanaar-Lieferung",[[description="Seid mir gegrüßt, $C. Könnt Ihr mir helfen? Ich habe ein Päckchen Kräuter, das ich in die Stadt Dolanaar liefern muss. Aber ich habe noch etwas mit den Druiden von Shadowglen zu regeln und kann nicht weg.$B$BKönntet Ihr das Päckchen für mich zustellen? Es muss zu Gastwirt Keldamyr im Gasthaus von Dolanaar. Das liegt an der Straße nach Süden.",objectives={"Bringt die Dolanaar-Lieferung zu Gastwirt Keldamyr."}]])
R(2160,"Vorräte für Tannok",[[description="He! Ihr seht wie ein beherzter Abenteurer aus. Wenn Ihr vorhabt, den Pass zu überqueren, könntet Ihr da wohl ein Päckchen ins Gasthaus von Kharanos bringen?$b$bIhr hattet doch vor, im Gasthaus abzusteigen, nicht? Wenn Ihr den Pass bezwungen habt, werdet Ihr Euch dort ganz bestimmt etwas ausruhen wollen.$b$bWie auch immer, bringt das zu Tannok Frosthammer, dem Gehilfen des Gastwirts. Ich selbst kann nicht über den Pass und es dauert Tage, bis wieder eine Gebirgsjägereskorte vorbeikommt!",objectives={"Bringt die Kiste mit Gasthausvorräten zu Tannok Frosthammer in Kharanos."}]])
R(2161,"Die Bürde eines Peons",[[description="Entschuldigung? Könntet Ihr mir helfen?$B$BIch habe hier eine Ladung Essen. Ich bin die Straße entlanggelaufen und habe Skorpiden und Spinnen und Schlimmerem getrotzt! Ich habe das Essen ins Tal der Prüfungen gebracht, weil ich dachte, sie könnten es brauchen und weil ich gern behilflich bin. Aber sie brauchen kein Essen! Jetzt muss ich es nach Klingenhügel zurückbringen und fürchte mich vor den ganzen Bestien unterwegs...$B$BKönnt Ihr es für mich hinbringen? Ich bin nur ein Peon, Ihr aber seid $gein Held:eine Heldin;. Ihr fürchtet nichts!$B$BBringt es zu Gastwirt Grosk im Gasthaus von Klingenhügel. Danke!",objectives={"Bringt Ukors Bürde zu Gastwirt Grosk in Klingenhügel."}]])
R(2178,"Schreitereintopf",[[description="Riecht Ihr dieses köstliche Aroma? Das ist mein Geheimrezept, $n - frischer Schreitereintopf. Köstlich!$B$BVielleicht möchtet Ihr das Rezept ja wissen?$B$BBevor ich Euch das Rezept verrate, müsst Ihr beweisen, dass Ihr den Wildtieren gewachsen seid.$B$BIch erwarte nicht, dass Ihr loszieht und eines zähmt und darauf zu mir zurückgeritten kommt, aber wenn Ihr einige Wildtiere töten könnt und mir etwas von ihrem saftigen Fleisch bringt, verrate ich Euch vielleicht das Schreiterrezept.",objectives={"Bringt 5 Stücke Schreiterfleisch zu Alanndarian Nightsonng in Auberdine."}]])
R(2198,"Die zerrissene Halskette",[[description="Ihr habt eine befleckte Halskette gefunden, doch unter der Stumpfheit des Metalls lässt sich noch die feine und magische Handarbeit erkennen. Die Halskette ist beschädigt, in ihrer Fassung scheinen drei Edelsteine zu fehlen. Auf der Unterseite der Halskette kann man vage den Stempel des Stadtsiegels von Ironforge erkennen. Unter dem Siegel befinden sich drei winzige eingravierte Buchstaben: \"TdK\".$B$BWenn Ihr etwas über die Halskette in Erfahrung bringen wollt, müsst Ihr herausfinden, woher sie stammt. Vielleicht sind das Siegel und die Initialen ein Anfang ...",objectives={"Sucht nach dem Erschaffer der zerrissenen Halskette, um etwas über ihren möglichen Wert zu erfahren."}]])
R(2199,"Lehren haben ihren Preis",[[description="Ich genieße als Juwelier hier in Ironforge ein hohes Ansehen! Oder sagen wir besser: Ich genoss es einmal. Dank der gemeinen Tricks eines Konkurrenten mache ich gerade eine schwere Zeit durch. In dieser Branche bedeutet ein schlechter Ruf das finanzielle Desaster. Und so muss ich feststellen, dass mein guter, wenn auch momentan leicht beschmutzter Name keinen roten Heller mehr wert ist.$B$BIch möchte, dass Ihr mir fünf Silberbarren beschafft, die ich für einen Auftrag brauche - den ersten seit einer Ewigkeit.$B$BBringt mir die fünf Silberbarren, dann beantworte ich Eure Fragen über die Halskette.",objectives={"Bringt fünf Silberbarren zu Talvash del Kissel in Ironforge."}]])
R(2200,"Rückkehr nach Uldaman",[[description="Einer meiner Konkurrenten brachte das Gerücht in Umlauf, meine Halskette habe den Paladin verflucht. Und natürlich kauft einem Juwelier niemand verfluchte Gegenstände ab.$B$BIch schlag Euch etwas vor, $N: Ihr findet die Edelsteine und ich repariere die Halskette - aber nur, wenn Ihr herumerzählt, dass ich KEINE verfluchten Gegenstände herstelle!$B$BFangt am besten an, in Uldaman nach Hinweisen zu suchen; vielleicht liegt der Paladin dort begraben, von ihm wissen wir, dass er die Kette als Letzter hatte! Wenn Ihr die Edelsteine gefunden habt, solltet Ihr dies hier benutzen; dadurch könnt Ihr mit mir in Ironforge Kontakt aufnehmen.",objectives={"Sucht in Uldaman nach Hinweisen auf den momentanen Zustand von Talvashs Halskette. Der getötete Paladin, den Talvash erwähnte, hatte die Kette zuletzt."}]])
R(2201,"Suche nach den Edelsteinen",[[description="Das Tagebuch des Paladins liefert Euch die vielleicht einzigen Hinweise darauf, wo sich die Edelsteine aus der Halskette befinden könnten. Wenn der Paladin alles korrekt aufgezeichnet hat, dann müsst Ihr Euch um die Zwerge der Schattenschmiede und die Troggs kümmern, die um die Vorherrschaft über die Grabungsstätte konkurrieren.$B$BMit diesem Wissen bewaffnet, könnt Ihr Eure Suche nach den Edelsteinen jetzt ernsthaft beginnen. Sobald Ihr Euch alle Edelsteine angeeignet habt, solltet Ihr gemäß seinen Anweisungen Talvash in Ironforge mit Hilfe der Wahrsagephiole informieren",objectives={"Findet den Rubin, den Saphir und den Topas, die in ganz Uldaman verstreut sind. Wenn Ihr sie habt, wendet Euch aus der Ferne an Talvash del Kissel, indem Ihr die Wahrsagephiole nutzt, die er Euch zuvor gegeben hat.$B$BAus dem Tagebuch, wisst Ihr...$B* Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt.$B* Der Topas steckt in einer Urne in einem der Trogg-Gebiete, in der Nähe einiger Zwerge der Allianz.$B$B* Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen."}]])
R(2202,"Reagenzsuche in Uldaman",[[description="Ich habe von einer neu entdeckten Pflanze gehört, den magenta Funguskappen. Sie wachsen in Büscheln tief drinnen in der Uldaman-Grabungsstätte; vielleicht kann man sie auch anderswo finden, aber bisher ist das der einzige mir bekannte Ort, an dem sie gedeihen. Ich möchte ihren potenziellen Nutzen für die Alchimie erforschen und dafür brauche ich Euch.$B$BFindet die magenta Funguskappen-Büschel und bringt mir ein Dutzend Kappen. Aber seid gewarnt - die Pflanzen stoßen vielleicht Giftsporen aus, wenn man sie anstößt.$B$BWenn Ihr das für mich tut, dann braue ich Euch einen Schwung von meinem berühmten Regenerierungselixier!",objectives={"Bringt 12 magenta Funguskappen nach Kargath zu Jarkal Mossmeld."}]])
R(2203,"Reagenzien-Suche im Ödland II",[[description="Ihr seid mir eine große Hilfe gewesen, $C. Ich würde Euch ja das Rezept des Gebräus geben, das Ihr vorhin gekostet habt... doch zuvor muss ich Euch um einen gefährlichen Gefallen bitten. Hört meine Bitte.$B$BDiese Schließkassette enthält drei leere thaumaturgische Gefäße; sie sind mit einer Aura der Einstimmung magieerfüllt, die einem versengten Behütergroßdrachen das Blut aussaugt. Wenn Ihr sie gegen die Bestie benutzt, wird sie höchst erbost reagieren, also seid gewarnt. Bringt sie mir, wenn Ihr alle drei gefüllt habt.$B$BGelingt Euch das, gehört das Rezept Euch.",objectives={"Benutzt die leeren thaumaturgischen Gefäße bei versengten Wächtergroßdrachen im Ödland. Wenn Ihr sie gefüllt habt, bringt sie zu Jarkal Mossmeld in Kargath."}]])
R(2204,"Restaurierung der Halskette",[[description="Ihr müsst etwas \"Energie\" für die Halskette finden, und wenn ich es mir recht überlege, dann ist Uldaman sogar der beste Ort dafür. Ich vermute mal, da drinnen laufen eine Menge Konstrukte rum, hab ich Recht?Gut, dann sucht Euch das größte und böseste Konstrukt, das Ihr finden könnt, macht es fertig und schnappt Euch seine Kraftquelle! Ich bin mir ziemlich sicher, dass ich die Kraftquelle mit der Halskette verbinden kann.$B$BOhne die Kraftquelle wird es unmöglich sein, die Halskette zu reparieren! Kommt wieder zu mir nach Ironforge zurück, wenn Ihr die Kraftquelle habt, dann repariere ich die Halskette für Euch.",objectives={"Besorgt Euch eine Kraftquelle vom mächtigsten Konstrukt, das Ihr in Uldaman finden könnt, und liefert sie bei Talvash del Kissel in Ironforge ab."}]])
R(2205,"Aufsuchen des SI: 7",[[description="Das Abzeichen? Oh, das ist gar nichts, Dumpfbacke - jedenfalls nichts, mit dem Ihr fertig werden könntet. Wenn ich Euch so ansehe, würde ich sagen, dass Mathias Euch wahrscheinlich statt für einen anständigen Schurken für einen Käselieferanten halten wird. Aber wie dem auch sei, ich habe eine Aufgabe zugewiesen bekommen und ich habe versprochen, sie zu erledigen.$B$BDa wir gerade davon sprechen, bringt Mathias dieses Päckchen, dann gibt er Euch vielleicht eine kleine Aufgabe oder auch zwei.$B$BZischt ab.",objectives={"Liefert Keryn Sylvius' Päckchen an Meister Mathias Shaw in der Kaserne von Stormwind."}]])
R(2206,"Schneller Eingriff",[[description="Unsere Agenten vor Ort melden starke Aktivitäten der Defias südlich von Goldhain. Die Berichte deuten an, dass die Defias Jerods Anlegestelle erobert haben und ihn nun benutzen, um große Mengen Hehlerware vom Rotkammgebirge nach Westfall zu schmuggeln.$B$BIhr müsst das Dockhaus bespitzeln und mir den Lieferzeitplan beschaffen, $N. Ihr findet ihn wahrscheinlich tief in den Taschen des Dockmeisters.$B$B... und, $N, solltet Ihr entdeckt werden, wird der SI:7 strikt leugnen, dass er Euch kennt.",objectives={"Sucht den Dockmeister der Defias und beschafft den Lieferzeitplan für Meister Mathias Shaw."}]])
R(2218,"Straße der Rettung",[[description="Eine weitere verirrte Seele, die nach Führung sucht, hm? Ich nehme an, Ihr wollt ein Ziel finden - Euer Ziel. Das habe ich schon tausend Mal gesehen, ein Held, der Arbeit sucht.$B$BAber heute ist Euer Glückstag. Hogral hat ein Heilmittel für Eure Leiden.$B$BIhr macht Folgendes: Schlagt diesen Weg nach Ironforge ein und begebt Euch zum düsteren Viertel. Wenn Ihr dort seid, sucht die Diebesgilde und sprecht mit Hulfdan Blackbeard. Er wird Euch den Weg zur Rettung weisen.",objectives={"Sprecht mit Hulfdan Blackbeard in Ironforge."}]])
R(2238,"Einfache List",[[description="Ihr seht's ja, der König ist dabei, im Steinbruch nach Erz und Edelsteinen graben zu lassen. Mehr Reichtümer, als ein Zwerg normalerweise in zehn Leben zu sehen bekommen würde.$B$BDer Verborgene Kreis hat auch Werte, $n. Wertsachen! Versteht Ihr, was ich meine?$B$BWir finden, der König sollte uns was von der Beute abgeben, aber der alte Stinkebart soll nicht erfahren, dass er was abgibt - ich hoffe, Ihr könnt mir folgen.$B$BIhr müsst mit Onin MacHammar drüben bei Gnomeregan reden und 'nen Bericht zurückbringen. Der listige Zwerg hat sich bei den Lepragnomen versteckt. Seid vorsichtig.",objectives={"Sucht Onin MacHammar bei Gnomeregan."}]])
R(2239,"Onins Bericht",[[description="Der Steinbruch? Ja, ich sehe fast jeden Tag diese monströsen Dampfpanzer hier vorbeirollen.$B$BMeine Kontakte im Osten sagen mir, dass der Panzer in Ironforge startet, im Gol'Bolar-Steinbruch seine Ladung abholt, zum Auftanken in Kharanos hält und dann aus einem unerfindlichen Grund den langen Weg um Gnomeregan herum fährt, ehe er seine Ladung in Ironforge ablädt.$B$BEs steht alles in dem Bericht, $R. Bringt ihn zu Hulfdan, damit er den nächsten Schritt planen kann.",objectives={"Bringt Onins Bericht zu Hulfdan in Ironforge."}]])
R(2240,"Die geheime Kammer",[[description="Jetzt zur anstehenden Aufgabe:$B$BEs gibt eine geheime Kammer, die Kammer von Khaz'mul, die erforscht werden muss. Das Problem dabei ist, dass die Kammer hinter einer riesigen verschlossenen Tür liegt! Glücklicherweise weiß ich, wie man sie öffnet.$B$BIch habe alles in dem Tagebuch hier auf dem Tisch beschrieben. Meine Leute und ich sitzen hier zurzeit fest ... also müsst Ihr die Kammer von Khaz'mul für uns finden, $N.$B$BLest mein Tagebuch, erforscht die Kammer und meldet Euch dann bei Ausgrabungsleiter Stormpike in der Forscherliga in Ironforge.",objectives={"Lest Baelogs Tagebuch, erforscht die geheime Kammer und erstattet dann Ausgrabungsleiter Stormpike Bericht."}]])
R(2241,"Der Apfel fällt",[[description="Sie sagen, ich bin 'liebeskrank', was immer das heißen mag.$B$BKlar, ich denke ununterbrochen an Syurna. Klar, mein Haus ist voll von Bildern und Zeichnungen von Syurna. Klar, es kommt vor, dass ich tagelang nicht esse, schlafe oder trinke, während ich über die Liebe lamentiere, die uns nicht zuteil wurde. Ist das so falsch?$B$BJetzt will sie mich nicht sehen! MICH! Ich habe versucht, ihr Nachrichten zu schicken, aber sie redet mit keinem, es sei denn, er wäre ein Schurke.$B$BKönntet Ihr diese Blume zu ihr bringen? Und vergesst nicht, ihr zu sagen, dass sie von Jannok ist.",objectives={"Bringt Jannoks Rose zu Syurna in Darnassus."}]])
R(2242,"Das Schicksal ruft",[[description="Wir glauben, dass es ein Wesen gibt, das uns verstehen helfen könnte, was mit den Wäldern von Teldrassil geschieht. Leider hatte es verheerende Folgen, als wir versuchten, dieses Wesen zur Mitarbeit zu überreden.$B$BEr versteckt sich auf einem Ast am Rand der Lichtung des Orakels. Alle, die sich dem Satyr bisher genähert haben, sei es mit Gewalt oder Diplomatie, fanden ein böses Ende. Vielleicht ist Verstohlenheit die Lösung, $n.$B$BFindet heraus, was Sethir der Uralte in seinen Rucksäcken hat und berichtet mir davon.",objectives={"Sucht Sethir den Uralten und bringt alle Hinweise, die Ihr finden könnt, zu Syurna."}]])
R(2258,"Reagenzien-Suche im Ödland",[[description="$N, ich könnte Eure Hilfe gebrauchen, wenn Ihr Euch dazu in der Lage fühlt. Ich bin ein angesehener Alchimist und benötige Eure Unterstützung, um einige Reagenzien zu beschaffen, die im Ödland zu finden sind.$B$BIch brauche folgende Gegenstände, um meine Vorräte aufzufüllen: 5 Bussard-Muskelmägen, 10 Klippenkojotenfangzähne und 5 Felselementarsplitter. Natürlich könnt Ihr diese Reagenzien direkt von den lieben Tieren selbst bekommen; aber wenn Ihr keine Kämpfernatur seid, dann sucht Euch besser Freunde, die kämpfen können.$B$BBringt mir diese Gegenstände, dann springen ein paar Münzen für Euch dabei raus. Was sagt Ihr?",objectives={"Bringt Jarkal Mossmeld in Kargath im Ödland 5 Bussard-Mägen, 10 Klippenkojoten-Fangzähne und 5 Felselementarsplitter."}]])
R(2259,"Erion Shadewhisper",[[description="Keine Bange, $n, ich schicke Euch nicht zu Syurna. Erion verlangt nach Eurer Anwesenheit in der Enklave des Cenarius. Beeilung!",objectives={"Kontaktiert Erion Shadewhisper in Darnassus."}]])
R(2260,"Erions Befehl",[[description="Die Kunde von Euren Taten ist in aller Munde, $N. Ihr seid so berühmt, dass der Geheimdienst von Stormwind nach Euch persönlich gefragt hat.$B$BDie Reise ist anstrengend und nicht ungefährlich, aber die Gelegenheit einer Ausbildung beim SI:7 sollte man nicht in den Wind schlagen.$B$BEine neue Welt erwartet Euch, $N. Begebt Euch in die Altstadt von Stormwind und sprecht mit Renzik \"Das Messer\" im Hauptquartier des SI:7.",objectives={"Reist zur Stadt Stormwind und meldet Euch bei Renzik \"Das Messer\"."}]])
R(2278,"Die Platinscheiben",[[description="Die Kernstücke dieser Schatzkammer sind vier riesige Platinscheiben, von denen jede mit zahlreichen Siegelzeichen unbekannter Herkunft bedeckt ist. Als Ihr sie berührt, beginnt Eure Hand zu kribbeln. Unmittelbar, nachdem Ihr die Scheiben berührt habt, erscheint das Gesicht eines großen Steinbeobachters.$B$B\"Willkommen. Ich bin ein Hüter des Wissens. Die Schöpfungssynthese der Irdenen wurde hier in den Scheiben von Norgannon für diese Welt aufgezeichnet und aufbewahrt.\"$B$BIhr habt eine Fülle an bislang unbekanntem Wissen über die Welt entdeckt!",objectives={"Sprecht mit dem Steinbehüter und findet heraus, welche uralten Lehren er aufbewahrt. Sobald Ihr alles erfahren habt, was er weiß, aktiviert die Scheiben von Norgannon."}]])
R(2279,"Die Platinscheiben",[[description="Als Ihr die Scheiben von Norgannon ein weiteres Mal berührt, kribbelt Eure Hand erneut. Jetzt aber ist aus dem Inneren der Scheiben ein seltsames, knirschendes Geräusch zu hören.$B$BPlötzlich ist Euer Rucksack schwerer als noch eine Sekunde vorher. In seinem Inneren findet Ihr eine Miniaturausgabe der Scheiben!$B$BZweifellos wäre ein solcher Gegenstand von unschätzbarem Wert für jeden, der sich für die Frühgeschichte von Azeroth interessiert. Die Forscherliga in Ironforge beispielsweise ist eine solche Gruppe und sie ist in der ganzen Allianz bekannt - vielleicht können die etwas mit diesem Fund anfangen.",objectives={"Bringt die Miniaturausgabe der Scheiben von Norgannon zur Forscherliga nach Ironforge."}]])
R(2280,"Die Platinscheiben",[[description="Als Ihr die Scheiben von Norgannon ein weiteres Mal berührt, kribbelt Eure Hand erneut. Jetzt aber ist aus dem Inneren der Scheiben ein seltsames, knirschendes Geräusch zu hören.$B$BPlötzlich ist Euer Rucksack schwerer als noch eine Sekunde vorher. In seinem Inneren findet Ihr eine Miniaturausgabe der Scheiben!$B$BZweifellos wäre ein solcher Gegenstand von unschätzbarem Wert für jeden, der sich für die Frühgeschichte von Azeroth interessiert. Die Weisen von Thunder Bluff beispielsweise sind solche Historiker und sie sind in der ganzen Horde wohl bekannt - vielleicht können die etwas mit diesem Fund anfangen.",objectives={"Bringt die Miniaturausgabe der Scheiben von Norgannon zu einem der Weisen von Thunder Bluff."}]])
R(2281,"Rendezvous im Rotkammgebirge",[[description="Euch jetzt in den Einsatz zu schicken wäre Selbstmord. Renzik braucht nicht noch einen toten Schurken. Aber keine Sorge, $n... Renzik wird Euch schon Beine machen.$B$BGeht ins Rotkammgebirge und sprecht mit einem Mitglied des SI:7 namens Lucius. Ihr werdet ihn auf den Docks von Seenhain finden, wo er mit den anderen halbseidenen Taugenichtsen herumhängt.",objectives={"Geht nach Seenhain im Rotkammgebirge und sprecht mit Lucius."}]])
R(2282,"Althers Mühle",[[description="Wir bilden hier schon seit Jahren Diebe aus! Schließlich wird nicht jeder Langfinger mit der Anmut und Finesse des alten Lucius geboren.$B$BOben an der Straße findet Ihr Althers Mühle. Ich habe dort oben eine Truhe mit wichtigem Inhalt. Holt sie für mich! Bringt mir diese Marke und Ihr bekommt Euer Zertifikat der Diebeskunst!",objectives={"Öffnet Lucius' Schließkassette, nehmt die Marke der Diebeskunst heraus und bringt sie zu Lucius nach Seenhain."}]])
R(2283,"Wiederbeschaffung der Halskette",[[description="Wir haben Arbeit für Euch, falls Ihr den Mut habt, Euch daranzuwagen.$B$BTief im Ödland befindet sich Uldaman, eine Grabungsstätte. Wir haben eine Geschichte gehört von so einem dummen Paladin, der kürzlich dort gestorben ist. Das würde uns ja alles nicht interessieren, aber er hatte eine sehr wertvolle Halskette bei sich. Angeblich sind drei große Edelsteine dabei: ein Rubin, ein Saphir und ein Topas.$B$BKurz gesagt: Wir wollen die Kette haben und wir bezahlen GUTES SILBER, um sie zu kriegen. Vielleicht ist sie beschädigt, aber das tut nichts zur Sache. Wir reparieren sie, wenn Kratzer daran sein sollten.",objectives={"Sucht in der Grabungsstätte von Uldaman nach einer wertvollen Halskette und bringt sie nach Orgrimmar zu Dran Droffers. Die Halskette ist vielleicht beschädigt."}]])
R(2284,"Wiederbeschaffung der Halskette, Teil 2",[[description="Genauso sicher, wie Malton ein Idiot ist, sind diese Edelsteine noch irgendwo in Uldaman. Ihr werdet wohl dorthin zurückgehen müssen und nach ihnen suchen.$B$BIch hab's ja schon mal gesagt: Wenn unsere Informationen stimmen, dann gehören zu der Halskette ein Rubin, ein Saphir und ein Topas. Findet sie und fügt sie in die Halskette ein.$B$BAber wo die Edelsteine sind - wer weiß das schon? Vielleicht habt Ihr ja Glück und findet die Leiche dieses Paladins. Wenn er noch nicht völlig ausgeplündert worden ist, dann hat er sie ja vielleicht sogar bei sich.",objectives={"Sucht in den Tiefen von Uldaman nach einem Hinweis auf den Verbleib der Edelsteine."}]])
R(2298,"Königliche Erpressung",[[description="Wir war'n also grade dabei, Phase III zu planen, da platzen 'n paar von Magnis Holzköpfen hier rein, schwafeln was von 'ner Art Razzia und verhaften ein paar vom Verborgenen Kreis.$B$BSo springt keiner mit dem alten Blackbeard um! Die Diskussion wurde immer hitziger und irgendwann fiel Euer Name!$B$BMein Rat? Nehmt den ersten Greif aus Ironforge raus und geht nach Stormwind. Geht in die Altstadt und sprecht dort mit einem alten Freund von mir, der Renzik \"Das Messer\" genannt wird.",objectives={"Reist nach Stormwind und sucht Renzik \"Das Messer\" auf."}]])
R(2299,"Auf Hulfdan!",[[description="Wo seid Ihr gewesen, $N? Hulfdan sucht schon überall nach Euch. Wir dachten schon, der König hätte Euch in Eisen legen lassen.$B$BGeht so schnell wie möglich nach Ironforge und sprecht mit Hulfdan!",objectives={"Reist nach Ironforge und sprecht mit Hulfdan Blackbeard."}]])
R(2300,"Der SI:7",[[description="Renzik hat nach Euch gesucht, Dumpfbacke.$B$BIch an Eurer Stelle würde Mathias' Stellvertreter nicht warten lassen.",objectives={"Reist nach Stormwind und sucht Renzik \"Das Messer\" auf."}]])
R(2318,"Übersetzung des Tagebuchs",[[description="Ihr befindet Euch in einer Art Sackgasse, denn Ihr wisst, dass Ihr das Buch erst in eine Sprache übersetzen lassen müsst, die Ihr versteht. Es gibt etliche Leute auf der Welt, die das machen könnten - der nächste Ort, wo sich vielleicht jemand finden ließe, der dazu in der Lage ist, wäre vermutlich der Kargath-Außenposten im Ödland. Vielleicht wäre das ein guter Ort, um anzufangen.",objectives={"Sucht jemanden, der das Tagebuch des Paladins übersetzen kann. Der nächstgelegene Ort, wo Ihr so jemanden finden könntet, ist Kargath im Ödland."}]])
R(2338,"Übersetzung des Tagebuchs",[[description="Droffers und Sohn Bergungen' sind nicht schlau genug, die Magie der Halskette wiederherzustellen, aber ich kann es. Ich muss nur die Halskette studieren, damit ich lerne, wie ich selbst solche Ketten herstellen kann. Und dazu benötige ich Eure Halskette. Leiht sie mir, und im Gegenzug für die Zeit, in der ich die Kette studieren kann, werde ich das Tagebuch für Euch übersetzen. Ich sollte genug Zeit haben, alles Nötige zu erfahren, während Ihr nach den Edelsteinen sucht.$B$BEs ist ein einfacher Handel und niemand wird etwas davon erfahren. Also, was sagt Ihr?",objectives={"Leiht Jarkal die Halskette. Im Gegenzug wird er das Tagebuch für Euch übersetzen."}]])
R(2339,"Findet die Edelsteine und die Kraftquelle",[[description="Hier ist das Tagebuch, übersetzt, sodass Ihr es lesen könnt. Kurz gesagt steht darin, dass Zwerge den Rubin versteckt haben, Troggs versteckten den Topas und ein Trogg namens Grimlok hat den Saphir.$B$BEs ist so, Ihr braucht eine Kraftquelle, um die Halskette wieder funktionstüchtig zu bekommen. Dran Droffers weiß das nicht. Um eine Kraftquelle zu finden, würde ich Folgendes tun: Begebt Euch so tief wie möglich nach Uldaman hinein und tötet das stärkste Konstrukt, das Ihr finden könnt. Ich zweifle nicht daran, dass das stärkste Konstrukt dort auch dasjenige ist, das die Kraftquelle hat.$B$BWenn Ihr alles zusammenhabt, dann kommt wieder hierher!",objectives={"Beschafft in Uldaman alle drei Edelsteine sowie eine Kraftquelle für die Halskette und bringt sie anschließend zu Jarkal Mossmeld nach Kargath. Jarkal glaubt, dass sich eine Kraftquelle vielleicht im stärksten Konstrukt in Uldaman findet.$B$BAus dem Tagebuch, wisst Ihr...$B* Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt.$B* Der Topas steckt in einer Urne in einem der Trogg-Gebiete, in der Nähe einiger Zwerge der Allianz.$B* Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen."}]])
R(2340,"Ablieferung der Edelsteine",[[description="Jede Halskettenfassung und jeder Edelstein wird funktionieren, solange sie aus demselben Material bestehen. Doch es ist die Kraftquelle, die der Halskette die Magie wieder zurückgeben wird. Hoffe ich zumindest.$B$BIch werde Euch gern die Edelsteine zur Verfügung stellen, die Ihr für Eure Version der Halskette benötigt, wenn die Kraftquelle einwandfrei funktioniert.$B$BBegebt Euch nach Orgrimmar und haltet Euren Teil der Abmachung mit 'Droffers und Sohn Bergungen' ein. Haltet lediglich den Mund über unser Geschäft, und wenn Ihr zurückkommt, habe ich vielleicht schon eine wundervolle Überraschung für Euch.",objectives={"Liefert die Halskette und die geborgenen Edelsteine bei Dran Droffers in Orgrimmar ab."}]])
R(2341,"Wiederbeschaffung der Halskette, Teil 3",[[description="Als Dran und Malton Droffers anfangen, sich um ihr neues Bergegut zu zanken, ist die Hälfte des Geschäftes bereits erledigt. Jetzt steht noch eine Reise ins Ödland an, um dort die Sache zum Abschluss zu bringen, denn Jarkal Mossmeld aus Kargath hat eine besondere Belohnung für Euch in petto - oder vielleicht auch nicht.",objectives={"Besucht Jarkal Mossmeld in Kargath, um festzustellen, ob er Erfolg gehabt hat."}]])
R(2342,"Wiederbeschaffte Schätze",[[description="Die Fledermausgehege mit diesem Besen auszukehren, das ist keine Aufgabe, die eines Garretts würdig wäre! Aber ich habe mit diesem verfluchten Job ein wenig Geld verdient und ich bin bereit, es für Euch auszugeben, wenn ich damit nur meine Situation verbessern kann.$B$BDie Lieblingswaffe der Familie Garrett liegt weggeschlossen in unserer Truhe in der Südlichen Bankenhalle von Uldaman. Das rührt noch von den Zeiten her, da wir Garretts dort als Buddler schufteten. Ohne sie werde ich für alle Zeiten hier festsitzen und im wahrsten Sinne des Wortes diesen höllischen Fledermäusen hinterherkehren.$B$BBeschafft den Schatz meiner Familie wieder und bringt ihn mir! Helft mir dabei, mein Geburtsrecht einzufordern!",objectives={"Holt Patrick Garretts Familienschatz aus der Truhe der Familie in der südlichen Bankenhalle von Uldaman und bringt diesen zu ihm nach Undercity."}]])
R(2358,"Hörner von Nez'ra",[[description="Vor vielen Jahren wurden die Hörner von Nez'ra aus dem Rabenholdtanwesen gestohlen. Über Ozeane und Kontinente hinweg habe ich nach ihnen gesucht, nur um schließlich zu erfahren, dass diese unbedeutenden Bestien sie die ganze Zeit über im Besitz hatten.$B$BErschlagt jeden Schwarzfelsorc, auf den Ihr trefft, bis Ihr die Hörner von Nez'ra wiedererlangt habt. Solltet Ihr die Hörner in Euren Besitz bekommen, dann sucht mich in Seenhain auf.$B$BWenn Ihr dies für mich tut, soll Euer Name in Rabenholdt Bekanntheit erlangen, $n.",objectives={"Bringt die Hörner von Nez'ra zu Arantir nach Seenhain."}]])
R(2359,"Klavens Turm",[[description="Ich überwache diesen Turm jetzt schon seit Wochen, $n. Kürzlich kam eine größere Lieferung aus dem Dämmerwald an und mit dieser Lieferung kamen auch diese Wachen.$B$BWas sie sind? Das weiß ich genauso wenig wie Ihr. Eines kann ich Euch aber sagen: Menschen sind das nicht.$B$BWie dem auch sei, bei der Lieferung war eine Truhe dabei und ich vermute mal, das ist es, was diese Monstrositäten bewachen. Die Kreatur mit den Stacheln hat einen Schlüssel, den wir brauchen.$B$BBeschafft Euch den Schlüssel, dringt in den Turm ein und stellt fest, was in dieser Truhe ist. Berichtet dann Mathias, was Ihr herausgefunden habt.",objectives={"Stehlt den Turmschlüssel der Defias, brecht in den Turm der Defias ein und stellt fest, was sich in der Dämmerwaldtruhe befindet. Bringt Mathias Shaw in Stormwind dann alle Informationen über das, was Ihr herausgefunden habt. Lest Kearnens Tagebuch, um neue Erkenntnisse über den Turm zu erlangen."}]])
R(2360,"Mathias und die Defias",[[description="Keinen Moment zu früh, $n. Spähtrupps des SI:7 berichten von ungewöhnlich intensiven Aktivitäten der Defias in Westfall.$B$BEs sieht so aus, als hätten die Defias einen verlassenen Wachturm der Allianz südlich der Späherkuppe übernommen und verwendeten diesen als Operationsbasis, um Güter von der Lieferroute ins Rotkammgebirge hereinzuschmuggeln.$B$BBegebt Euch nach Westfall und kontaktiert Agentin Kearnen. Sie wird Euch Bericht erstatten. Sie hält sich in der Nähe des Turms versteckt; dort findet Ihr sie.$B$B... und, $n, solltet Ihr entdeckt werden, wird der SI:7 strikt leugnen, dass er Euch kennt.",objectives={"Reist nach Westfall und sucht Agentin Kearnen. Sie wird Euch Bericht erstatten."}]])
R(2361,"Restaurierung der Halskette")
R(2378,"Suche nach der Shattered-Hand",[[description="Ihr habt den Schattenpirschern gut gedient, $N, aber vielleicht ist es an der Zeit, dass Ihr Euch nach draußen wagt. Zwar habt Ihr schon gezeigt, dass Ihr in der Kunst der Verstohlenheit und der Täuschung bewandert seid, doch Eure Ausbildung ist noch lange nicht beendet.$B$BDie Schattenpirscher haben Verbündete bei der Shattered-Hand. Sucht jemanden auf, der nichts dagegen hat, uns zu helfen: Shenthul in Orgrimmar.",objectives={"Reist nach Orgrimmar und sprecht an der Kluft der Schatten mit Shenthul."}]])
R(2379,"Zando'zan",[[description="Entschlossenheit allein reicht nicht aus, um die Hindernisse zu überwinden, die vor uns liegen.$B$BSprecht mit Zando'zan, um Eure Ausbildung als $gAgent:Agentin; der Shattered-Hand zu beginnen.$B$BErst wenn Ihr die Kunst der Verstohlenheit und die Diebeskunst gemeistert habt, könnt Ihr den nächsten Schritt auf Eurem persönlichen Weg des Schicksals gehen.",objectives={"Sprecht an der Kluft der Schatten mit Zando'zan."}]])
R(2380,"Nach Orgrimmar!",[[description="Noch seid Ihr $gkein Meister:keine Meisterin; der Verstohlenheit und der Täuschung, doch das kann und wird sich alles ändern. Ganz offensichtlich habt Ihr die da oben mit Euren dürftigen Fähigkeiten beeindruckt, denn der große Shenthul selbst hat nach Euch gefragt.$B$BReist auf der Straße nördlich von hier nach Orgrimmar und sprecht in der Kluft der Schatten mit Shenthul.",objectives={"Sprecht an der Kluft der Schatten in Orgrimmar mit Shenthul."}]])
R(2381,"Das Ausplündern der Plünderer",[[description="Ich will Euch keine Angst einjagen, $N, aber die letzten fünf Diebe, die ich ausgesandt habe, um den Schatz der Südmeerfreibeuter zu stehlen, sind in Stücken zu mir zurückgekommen.$B$BAn der Küste im Süden findet Ihr die Tide Razor, das Schiff der Südmeerfreibeuter. Unten im Laderaum findet Ihr das Gesuchte: den Schatz der Südmeerfreibeuter. Auf dem zweiten Deck des Schiffes findet Ihr die Piratenhöhle, dort bilden sie ihre Diebe aus.$B$BGeht an Bord dieses Schiffes, stehlt den Schatz und bringt ihn mir. Nutzt die Piratenhöhle, wenn Ihr Eure Diebeskunst üben wollt, aber seid vorsichtig!",objectives={"Bringt den Schatz der Südmeerfreibeuter zu Wrenix dem Jämmerlichen in Ratchet. Vergesst nicht, einen R.C.V.K. und Diebeswerkzeug von Wrennixs Elektrodingsda-Apparat zu bringen. Ihr werdet diese Dinge brauchen, um Eure Mission zu beenden.$B$BWenn Ihr von ungewöhnlich feindlichen Papageien angegriffen werdet, benutzt Euren R.C.V.K.!"}]])
R(2382,"Wrenix aus Ratchet",[[description="Zando'zan hat es gesehen! Ja, der Tag wird kommen! Thralls Tod... der Dolch in seinem Rücken, das Gift, das durch seine Adern fließt... Zando'zan hat schon zu viel gesagt.$B$B$N! Zando'zan hat eine Aufgabe für $N! $N muss nach Ratchet reisen, im Osten von Crossroads, und mit Wrenix dem Jämmerlichen sprechen. Los!",objectives={"Reist nach Ratchet und sprecht mit Wrenix dem Jämmerlichen."}]])
R(2383,"Einfaches Pergament",[[description="Ah, während Ihr fort wart, kam ein Pergament für Euch, $n.$B$BLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es vom Kriegerlehrer Frang. Er würde gern mit Euch sprechen, wenn Ihr bereit seid. Ihr findet ihn außerhalb des Höhlenbaus, wo er sich in den Schatten verbirgt.",objectives={"Lest das einfache Pergament und sprecht mit Frang im Tal der Prüfungen."}]])
R(2398,"Die verschollenen Zwerge",[[description="Die Grabungsstätte von Uldaman war nicht immer so überlaufen. Wir Zwerge von Ironforge kontrollierten früher das Gebiet, aber... das war, bevor die Troggs kamen. Sie kamen so schnell und waren so zahlreich, dass nicht einmal die Macht der Zwerge sie aufhalten konnte.$B$BUm ehrlich zu sein, kam ihr Angriff so plötzlich, dass ich fürchte, dass vielleicht einige unserer Leute hinter den feindlichen Linien festsitzen.$B$BMein Freund Baelog hatte eine kleine Gruppe Zwerge tief hinunter in die Grabungsstätte geführt, kurz bevor die Troggs auftauchten. Wenn er und seine Gefährten noch leben, dann möchte ich, dass Ihr sie findet.",objectives={"Sucht in Uldaman nach Baelog."}]])
R(2399,"Die sprießenden Wedel")
R(2418,"Kraftsteine",[[description="Vor einiger Zeit hatte ich einen kleinen Zwischenfall mit den Zwergen der Schattenschmiede. Sie brachten mich in die Festung Angor, um dort zwei Arten von seltsamen Steinen zu untersuchen, wie sie in Uldaman vorkommen. Ich habe entdeckt, dass die Steine langlebige und stabile Kraftquellen darstellen, wenn sie richtig behandelt werden. Es ist schon erstaunlich, was man alles in dieser alten Grabungsstätte finden kann!$B$BJedenfalls warfen sie mich aus der Festung Angor raus, nachdem ich ihnen das Geheimnis der Steine verraten hatte, und begannen, in Uldaman nach weiteren Steinen zu graben.$B$BIch will diese Steine für mich! Bringt mir beide Arten von Steinen und ich bezahle Euch gut dafür!",objectives={"Bringt Rigglefuzz im Ödland 8 Kraftsteine aus Dentrium und 8 Kraftsteine aus An'Alleum."}]])
R(2438,"Der smaragdgrüne Traumfänger",[[description="Einst erhielt ich von Gaerolas Talvethen, dem Bewacher der Druiden im Grabhügel von Ban’ethil, einen smaragdgrünen Traumfänger. Dieses mächtige Amulett ist in der Lage, Energie aus dem Smaragdgrünen Traum abzuziehen und damit denen, die es tragen, Glück zu bringen.$B$BLeider habe ich den Traumfänger nicht mehr aus meiner Kommode in Starbreeze holen können. Starbreeze war einst ein ruhiger Ort, aber jetzt ist er durch die Furbolgs, die sich dort aufhalten, der Verderbnis anheim gefallen.$B$BWärt Ihr vielleicht bereit, mir meinen Traumfänger wiederzubeschaffen, $C?",objectives={"Bringt den smaragdgrünen Traumfänger zu Tallonkai Swiftroot in Dolanaar."}]])
R(2439,"Die Platinscheiben",[[description="Dieser Gegenstand ist ein unglaublicher Fund. Die alten Titanen oder 'Schöpfer', wie sie auf diesen Scheiben genannt werden, sind die Verbindung zu unserer verzauberten Erschaffung, wenn das hierin gespeicherte Wissen korrekt ist! Wir werden uns so eingehend wie möglich mit diesen Scheiben beschäftigen.$B$BWas Euch betrifft, $C: Bringt diesen Gutschein zu Dinita Stonemantle in dem Gewölbe. Für ihn erhaltet Ihr etwas, das meiner Meinung nach eines solch unglaublichen Fundes würdig ist.$B$BKehrt umgehend zu mir zurück, wenn Ihr fertig seid - es gibt noch viel mehr für die Forscherliga zu tun!",objectives={"Bringt Euren Belohnungsgutschein zu Dinita Stonemantle im Gewölbe von Ironforge."}]])
R(2440,"Die Platinscheiben",[[description="Ich werde all meine Energien auf diese Scheiben fokussieren; wenn die Zeit gekommen ist, werden sie mir ihre Funktionsweise schon verraten.$B$BWas Euch betrifft, $N, nun, Ihr sollt dafür belohnt werden, dass Ihr mir diese Sache kundgetan habt. Bringt den Belohnungsgutschein zu Bena Winterhoof, der Alchimielehrerin in Thunder Bluff. Sie wird Euch einen speziellen Gegenstand geben, der Euch bestimmt gefällt, und außerdem erhaltet Ihr von ihr eine Auswahl an Tränken aus meinem persönlichen Vorrat.$B$BKehrt bald zu mir zurück ... ich spüre, dass wir in Bezug auf diesen Fund noch viel mehr zu tun haben.",objectives={"Bringt den Belohnungsgutschein zu Bena Winterhoof nach Thunder Bluff."}]])
R(2458,"Undercover",[[description="Die Venture Company... Vielleicht habt Ihr von den Leuten schon gehört?$B$BEin Jahr lang haben wir daran gearbeitet, einen Agenten in ihre Reihen einzuschleusen. Endlich hatten wir - dank harter Arbeit und präziser Planung - Erfolg.$B$BVor kurzem haben wir jetzt gehört, dass die Venture Company irgendetwas Großes plant. Begebt Euch zum Turm der Venture Company nördlich des Schlickermoores und kontaktiert dort unseren Undercover-Agenten, Zuchtmeister Fizzule.$B$BSobald Ihr den Turm gefunden habt, verwendet diese Leuchtfeuerwaffe und grüßt ihn mit dem Gruß der Shattered-Hand.",objectives={"Reist zum Turm der Venture Company nördlich des Schlickermoores und kontaktiert dort den Agenten der Shattered-Hand, Zuchtmeister Fizzule.$B$BSobald der Turm in Sichtweite ist, verwendet die Leuchtfeuerwaffe, um Zuchtmeister Fizzule Eure Ankunft anzuzeigen. Feuert ZWEI Leuchtfeuergeschosse ab, nähert Euch dann Zuchtmeister Fizzule und zeigt den Gruß der Shattered-Hand.$B$BEs ist wichtig, dass Ihr diese Aktionen in der richtigen Reihenfolge durchführt, da Fizzule jede Person, die er nicht erkennt, angreift und eliminiert."}]])
R(2459,"Ferocitas der Traumfresser",[[description="Der Smaragd... Er ist weg! Mein Traumfänger ist beschädigt!$B$BEine Gruppe von Knarzklauenmystikern lebt im Norden von Starbreeze. Ich habe gehört, dass ihr Anführer, Ferocitas der Traumfresser, seit einiger Zeit eine Halskette trägt, die des Nachts grün leuchtet. Jetzt, wo ich meinen Traumfänger sehe, bin ich mir sicher, dass er meinen Smaragd gestohlen hat... Er würde nie verstehen, dass dessen Macht völlig nutzlos für ihn ist.$B$BFindet das verlorene Juwel, $N. Und wenn Ihr schon mal dort seid, erledigt auch gleich einige dieser verderbten Mystiker.",objectives={"Tallonkai Swiftroot aus Dolanaar möchte, dass Ihr 7 Mystiker der Knarzklauen tötet und das verlorene Juwel findet."}]])
R(2460,"Der Shattered-Gruß",[[description="Als ein Schurke der Shattered-Hand müsst Ihr unbedingt den Shattered-Gruß erlernen. Dies ist die einzige Methode, mit der man ein anderes Mitglied der Hand zweifelsfrei identifizieren kann.$B$BSchaut zu, lernt, wiederholt.",objectives={"Führt Shenthul gegenüber den Shattered-Gruß aus."}]])
R(2478,"Mission: möglich, aber nicht sehr wahrscheinlich",[[description="Ihr müsst den Turmschlüssel von Großknecht Silixiz stehlen, $n. Sobald sich der Schlüssel in Eurem Besitz befindet, haltet ihn gut fest - ich könnte ihn später brauchen.$B$BVergesst nicht, das Gift hat alles in diesem Turm geschwächt. Wendet Eure Fähigkeiten an, um unter seinen Bewohnern Chaos und Zerstörung zu verbreiten. Erschlagt sie alle - zeigt keine Gnade!$B$BSobald sich dort drinnen nichts mehr rührt, knackt Ihr das Schloss von Gallywix' Schließkassette und stehlt den Vorrat an Zanzils Mixtur, der sich darin befindet. Bringt Shenthul in Orgrimmar sowohl Gallywix' Kopf als auch die Mixtur.",objectives={"Stehlt Silixiz' Turmschlüssel von Großknecht Silixiz. Tötet dann 2 mutierte Drohnen der Venture Co., 2 Patrouillen der Venture Co. und 2 Ausgucker der Venture Co.$B$BEliminiert den obersten Großknecht Gallywix und nehmt seinen Kopf. Knackt dann das Schloss von Gallywix' Schließkassette und stehlt den Vorrat an Zanzils veränderter Mixtur. Bringt den Vorrat und Gallywix' Kopf zu Shentul nach Orgrimmar; er wird Euch weitere Anweisungen geben."}]])
R(2479,"Hinotts Hilfe",[[description="Bringt eine Probe der Mixtur zu Serge Hinott nach Tarrens Mühle.$B$BWenn Euch überhaupt irgendjemand heilen kann, dann ist das Serge. Falls Ihr lange genug lebt, kann Serge Euch in der Kunst der Herstellung und Anwendung von Giften unterweisen.",objectives={"Reist nach Tarrens Mühle im Vorgebirge von Hillsbrad und liefert die Probe von Zanzils Mixtur bei Serge Hinott ab.$B$BUm nach Tarrens Mühle zu kommen, müsst Ihr den Zeppelin nach Undercity nehmen und dann auf der Straße nach Süden durch den Silberwald in Richtung Hillsbrad reisen. Folgt den Schildern!"}]])
R(2480,"Hinotts Hilfe",[[description="Noch nie habe ich gesehen, dass ein Gift so wundervolle Auswirkungen hatte! Zanzil, sagt Ihr? Nie von ihm gehört. Aber ich muss ihm zur Kreation dieses Gebräus gratulieren.$B$BTja, ich soll Euch also hiervon heilen und Euch dann beibringen, wie man das Gift anwendet?$B$BGebt mir einen Moment Zeit, damit ich das Toxin untersuchen kann, $n.",objectives={"Wartet auf Serge Hinott, um das Heilmittel fertig zu stellen."}]])
R(2498,"Rückkehr zu Denalan",[[description="Ich habe gerade erfahren, dass Denalan am Al'Amethsee herausgefunden hat, was der Grund für die Tumore sein könnte, von denen die Bäumlinge befallen sind. Bitte sprecht mit ihm und sagt ihm, dass ich Euch geschickt habe.$B$BSputet Euch, $n; er braucht unsere Hilfe.",objectives={"Rellian Greenspyre möchte, dass Ihr am Al'Amethsee mit Denalan sprecht."}]])
R(2499,"Grimmeiche",[[description="In einer Höhle am Südufer des Sees überträgt ein Bäumling namens Grimmeiche die Verderbnis auf alle Wesen, die am Al'Amethsee leben.$B$BIch habe mich nicht allzu nah herangewagt, aber selbst aus der Entfernung ist eines ganz klar: Grimmeiche wird von dem größten Tumor vergiftet, den ich je gesehen habe. Ich würde sogar sagen, er ist nicht nur groß, er ist riesengroß.$B$BIhr habt schon viel getan, um mir zu helfen, $N, und doch möchte ich Euch um einen weiteren Gefallen bitten. Spürt Grimmeiche auf und holt den Tumor. Entfernt diese Quelle der Verderbnis aus meiner Heimat!",objectives={"Denalan vom Al'Amethsee möchte, dass Ihr den riesengroßen Tumor von Grimmeiche einsammelt."}]])
R(2500,"Reagenzien-Suche im Ödland",[[description="$C, ich möchte Eure Dienste in Anspruch nehmen. Ich bin ein angesehener Alchimist und benötige Eure Unterstützung, um einige Reagenzien zu beschaffen, die im Ödland zu finden sind.$B$BIch brauche folgende Gegenstände, um meine Vorräte aufzufüllen: 5 Bussard-Muskelmägen, 10 Klippenkojotenfangzähne und 5 Felselementarsplitter. Natürlich könnt Ihr Euch diese Reagenzien von den Viechern selbst holen; aber wenn Ihr keine Kämpfernatur seid, dann sucht Euch besser Freunde, die kämpfen können.$B$BBringt mir diese Gegenstände, dann springen ein paar Münzen für Euch dabei heraus.$B$BAlso, was sagt Ihr?",objectives={"Beschafft die Reagenzien, die Ghak Healtouch aus dem Ödland braucht, und bringt sie ihm nach Thelsamar."}]])
R(2501,"Reagenzien-Suche im Ödland II",[[description="Ihr seid mir eine große Hilfe gewesen, $n. Ich würde Euch gern das Rezept des Gebräus geben, das Ihr vorhin gekostet habt... doch zuvor muss ich Euch um einen recht gefährlichen Gefallen bitten.$B$BDiese Schließkassette enthält drei leere thaumaturgische Gefäße; sie sind mit einer Einstellungs-Aura magieerfüllt, die einem versengten Wächtergroßdrachen das Blut aussaugt. Wenn Ihr ein solches Gefäß gegen die Bestie einsetzt, wird sie höchst erbost reagieren, also seid vorsichtig. Bringt sie mir, wenn Ihr alle drei gefüllt habt.$B$BGelingt Euch das, gehört das Rezept Euch.",objectives={"Benutzt die leeren thaumaturgischen Gefäße bei versengten Wächtergroßdrachen im Ödland. Wenn Ihr sie gefüllt habt, bringt sie zu Ghak Healtouch in Thelsamar."}]])
R(2518,"Tränen des Mondes",[[description="Einst wurde Lady Sathrah von Elune geliebt. Grazil und rein spann die Spinne ihre silbernen Fäden im Mondlicht, wo sie den Abendnebel einfingen. Der silbrige Tau hatte starke Heilkräfte und wurde darum hier im Tempel aufbewahrt.$B$BDoch in jüngster Zeit ist Sathrah dem Wahnsinn verfallen. Auch die ihr nachfolgenden Generationen sind nun gefährdet.$B$BFindet Lady Sathrah, $N, und beendet ihr Leiden. Sie hält sich an der nördlichen Grenze von Teldrassil auf, in der Nähe des Wellspringsees. Sammelt ihre silbrigen Spinndrüsen und bringt sie mir.",objectives={"Priesterin A'moora vom Tempel des Mondes in Darnassus möchte, dass Ihr ihr Lady Sathrahs silbrige Spinndrüsen bringt."}]])
R(2519,"Der Tempel des Mondes",[[description="Ein einstmals großes Wesen des Waldes benötigt Hilfe, $R.$B$BEine schwierige Aufgabe muss getan werden.$B$BBitte sucht Priesterin A'moora auf: Sie wird Euch alles erklären. Ihr findet sie südöstlich von hier im Tempel des Mondes.",objectives={"Schwester Aquinne möchte, dass Ihr im Tempel des Mondes mit Priesterin A'moora sprecht."}]])
R(2520,"Sathrahs Opferung",[[description="Jetzt müsst Ihr die Aufgabe vollenden, die Euch auferlegt worden ist. Nehmt die Spinndrüsen und bringt Elune Lady Sathrahs Opfer dar. Verschafft der großen Spinne die ewige Ruhe.$B$BBegebt Euch zum zentralen Brunnen in diesem Tempel. Dort könnt Ihr das Opfer niederlegen. Die heiligen Wasser werden die Verderbnis, durch die Sathrah in den Wahnsinn getrieben wurde, läutern und säubern.$B$BKommt zu mir zurück, sobald Ihr dies erledigt habt.",objectives={"Priesterin A'moora möchte, dass Ihr Lady Sathrahs silbrige Spinndrüsen am Brunnen innerhalb des Tempels ablegt und dann zu ihr zurückkehrt."}]])
R(2521,"Ein Dienst für Kum'isha",[[description="$R, kann Euer winziges Gehirn überhaupt verstehen, wie selten eine völlig fehlerlose Draenethystsphäre ist? Viele Draenei haben ihr ganzes Leben damit verbracht, auch nur einen einzigen solchen Kristall zu finden, und keiner, der es versuchte, konnte sein Vorhaben je ausführen. Alle sind eines schrecklichen Todes gestorben.$B$BUnd nun steht Ihr vor Kum'isha, wissend, was Kum'isha wünscht, und Ihr möchtet dennoch behilflich sein? Nun gut, $R... Solltet Ihr auf Euren Reisen durch die Lande irgendwann auf eine fehlerlose Draenethystsphäre stoßen, dann bringt sie mir, und ich belohne Euch mit Reichtümern, wie Ihr sie Euch niemals erträumen könnt.",objectives={"Falls Ihr auf Euren Reisen durch die Verwüsteten Lande je auf eine fehlerlose Draenethystsphäre stoßen solltet, bringt sie zu Kum'isha dem Sammler.$B$BDoch seid gewarnt. Der Edelstein ist einer der rarsten Kristalle von ganz Azeroth. Jedes Wesen in diesem Land könnte eine fehlerlose Draenethystsphäre bei sich haben.$B$BIhr erhaltet eine Belohnung für jede fehlerlose Draenethystsphäre, die Ihr beschaffen könnt."}]])
R(2522,"Kum'ishas Bemühungen",[[description="Obwohl die Herbeizauberung des Portals fehlgeschlagen ist, hoffe ich doch weiterhin, dass ich mit meinem nächsten Versuch Erfolg haben werde.$B$BDie Hoffnung der Draenei ist ebenso groß wie Eure Gier nach Tand, $R. Begebt Euch wieder hinaus in dieses verfluchte Land und beschafft mir eine weitere fehlerlose Draenethystsphäre.$B$BNatürlich liegt es ganz allein an Euch, ob Ihr diese Aufgabe annehmen wollt oder nicht... <grinst>.",objectives={"Findet eine fehlerlose Draenethystsphäre und bringt sie Kum'isha dem Sammler."}]])
R(2523,"Verderbte Liedblume")
R(2541,"Der schlafende Druide",[[description="Die hier lebenden Schamanen der Knarzklauen haben einen Weg entdeckt, wie man den Geist eines schlafenden Druiden von seinem Körper trennen kann. Die Furbolgs haben meinen physischen Körper reanimiert und lassen ihn jeden angreifen, der versucht, den Grabhügel von Ban'ethil zu erforschen. Ich selbst bin im Smaragdgrünen Traum gefangen und kann diesem Treiben keinen Einhalt gebieten.$B$BIhr müsst mir helfen. Alle Knarzklauenschamanen tragen einen seltsamen Glücksbringer bei sich, mit dem dieses Ritual durchgeführt wird, und ich würde einen solchen Glücksbringer gern untersuchen. Bitte, $N, bringt mir einen.",objectives={"Bringt einen Voodooglücksbringer des Schamanen zu Oben Zornklaue in den Grabhügel von Ban'ethil."}]])
R(2561,"Druide der Klaue",[[description="Nachdem ich den Glücksbringer untersucht habe, weiß ich jetzt, was zu tun ist, $N. Bitte nehmt ihn, und tut das, worum ich Euch bitte.$B$BIhr müsst die tiefsten Tiefen des Grabhügels von Ban'ethil erforschen. Dort findet Ihr meinen seelenlosen Körper. Und obwohl es mich sehr schmerzt, Euch das jetzt zu sagen, sehe ich keine andere Möglichkeit, wie ich mich der Kontrolle der Knarzklauen entziehen kann.$B$BDamit ich mich von ihnen befreien kann, müsst Ihr meinen physischen Körper töten. Sobald das getan ist, wendet den Voodooglücksbringer auf meinen gefallenen Körper an. Und wenn Ihr diese Aufgabe erfüllt habt, kommt zu mir zurück.",objectives={"Oben Zornklaue möchte, dass Ihr seinen seelenlosen Körper tötet und dann den Voodooglücksbringer anwendet."}]])
R(2581,"Kicherfangunterkiefer",[[description="Es ist eine wohl bekannte Tatsache, dass Hyänen unglaubliche Kraft in ihrem Unterkiefer haben, aber drei Zoll Thoriumstahl durchbeißen? Unmöglich, völlig unwahrscheinlich, und dennoch habe ich es mit meinen eigenen Augen gesehen.$B$BWagt Euch hinaus in die Verwüsteten Lande und bringt mir drei Kicherfangunterkiefer. Und während Ihr nach den Kicherfanghyänen sucht, haltet auch nach Ebern und Skorpoks Ausschau, denn für die erste Zubereitung der Inhaltsstoffprobe benötige ich auch zwei feuerverbrannte Eberlungen und eine Skorpokzange.",objectives={"Bringt Blutmagier Drazial 3 Kicherfangunterkiefer, 2 feuerverbrannte Eberlungen und 1 Skorpokzange."}]])
R(2582,"Wut der Zeiten",[[description="Ah, $n, willkommen. Es scheint, als habe es Euch gefallen, so von Kraft erfüllt und handlungsfähig zu sein, wie es durch die Wirkung der Kicherfangdroge möglich wurde. Doch seid gewarnt: Zwar zeigt sich unmittelbar nach der Einnahme des Präparates ein gigantischer Stärkeschub, doch auf lange Sicht gesehen könnte das Mittel nachteilige Auswirkungen auf Euren Geist und Eure Intelligenz haben.$B$BUnd jetzt, wo Ihr dies wisst - braucht Ihr noch mehr? Falls ja, dann bringt mir drei weitere Kicherfangunterkiefer, zwei feuerverbrannte Eberlungen und eine Skorpokzange.",objectives={"Bringt Blutmagier Drazial 3 Kicherfangunterkiefer, 2 feuerverbrannte Eberlungen und 1 Skorpokzange."}]])
R(2583,"Lebenskraft des Ebers",[[description="Hier in den Verwüsteten Landen leben zwei Arten von Ebern: der Aschmähneneber und der Hölleneber.$B$BEs scheint, als mache die Ausdauer dieser Wildtiere sie so gut wie völlig immun gegen Schaden jeglicher Art, da die anderen Tiere zu große Schwierigkeiten haben, sie zu töten, und daher in Ruhe lassen.$B$BWir müssen weitere Analysen durchführen, $n. Wenn Ihr mir drei feuerverbrannte Eberlungen, zwei Skorpokzangen und ein Basiliskengehirn bringt, dann werde ich aus den Überresten der Inhaltsstoffprobe ein himmlisches Elixier kreieren. Und Ihr seid mein erstes Versuchsobjekt!",objectives={"Bringt Blutmagier Drazial 3 feuerverbrannte Eberlungen, 2 Skorpokzangen und 1 Basiliskengehirn."}]])
R(2584,"Geist des Ebers",[[description="Schon als ich das Elixier zum ersten Mal einsetzte, konnte ich sehen, dass eine oder zwei Anwendungen Euer Verlangen danach nicht stillen würden, $N. Selbst jetzt bleibt mir die Gier in Euren Augen nicht verborgen. Das Gebräu hat suchterzeugende Eigenschaften, denen, so scheint es, noch nicht einmal jemand mit äußerst starkem Willen widerstehen kann.$B$BSo sei es denn! Solltet Ihr mehr von dem Lungensaft-Cocktail benötigen, dann wagt Euch wieder hinaus ins Ödland und besorgt mir drei feuerverbrannte Eberlungen, zwei Skorpokzangen und ein Basiliskengehirn.",objectives={"Bringt Blutmagier Drazial 3 feuerverbrannte Eberlungen, 2 Skorpokzangen und 1 Basiliskengehirn."}]])
R(2585,"Der Entscheidungsschlag",[[description="Habt Ihr jemals gesehen, wie sie kämpfen, $n? Die Skorpoks, meine ich. Habt Ihr jemals die Anmut und Gewandtheit ihrer Bewegungen gesehen? Gesehen, wie entschlossen sie zuschlagen?$B$BWenn wir nur irgendwie diese Beweglichkeit einfangen und für uns nutzbar machen könnten, dann würden wir so reich werden, wie... ähem, dann wäre das ein unschätzbarer Segen für die wissenschaftliche Gemeinschaft, meine ich natürlich.$B$BHelft mir, $n, dann lasse ich Euch auch von der fertigen Inhaltsstoffprobe kosten.$B$BUm eine reaktionsstabile Probe herzustellen, benötige ich drei Skorpokzangen, zwei Geiermuskelmägen und eine feuerverbrannte Eberlunge.",objectives={"Bringt Blutmagier Drazial 3 Skorpokzangen, 2 Geiermuskelmägen und 1 feuerverbrannte Eberlunge."}]])
R(2586,"Salz der Skorpok",[[description="Ihr lebt noch! Das sind wahrlich gute Neuigkeiten. Ich vermute mal, Ihr seid wieder da, weil Ihr mehr von der Skorpokinhaltsstoffprobe möchtet?$B$BTja, $n, dann mal ab ins Ödland mit Euch, und kommt erst zurück, wenn Ihr drei Skorpokzangen, zwei Geiermuskelmägen und eine feuerverbrannte Eberlunge eingesammelt habt.",objectives={"Bringt Blutmagier Drazial 3 Skorpokzangen, 2 Geiermuskelmägen und 1 feuerverbrannte Eberlunge."}]])
R(2601,"Der Biss des Basilisken",[[description="In der Einöde wimmelt es nur so von Rotsteinbasilisken, $n. Diese Basilisken haben sich an ihre Umgebung angepasst und sind in ihr gediehen, mehr als jede andere wilde Tierart in diesem Gebiet.$B$BIch habe sie schon oft von weitem beobachtet, wenn sie jagen und ihren täglichen Aktivitäten nachgehen: Diese Wildtiere zeigen Denkprozesse, die komplexer sind als die mancher Humanoiden!$B$BIch muss ihre Gehirne studieren!$B$BBringt mir zehn ihrer Gehirne, $n. Doch für das Präparat benötige ich auch zwei Geiermuskelmägen. Diese bilden die Grundlage der Lösung.",objectives={"Bringt Blutmagierin Lynnore 10 Basiliskengehirne und 2 Geiermuskelmägen."}]])
R(2602,"Unfehlbare Gedanken",[[description="Eure fokussierte Konzentration hat so schnell nachgelassen? Dann muss unbedingt weitergeforscht werden!$B$BAch ja, und der Preis ist noch immer derselbe, $n. Wagt Euch in die Verwüsteten Lande hinaus und kommt mit zehn Rotsteingehirnen und zwei Geiermuskelmägen wieder.",objectives={"Bringt Blutmagierin Lynnore 10 Basiliskengehirne und 2 Geiermuskelmägen."}]])
R(2603,"Lebensenergie des Geiers",[[description="Hier in den Verwüsteten Landen besitzt der Tod tatsächlich Flügel, $R. Ich habe gesehen, wie die schwarzen Töter und die Knochenpflücker sich am Kadaver so manch eines gefallenen Forschers gütlich taten - und manchmal fraßen sie sogar die übelsten, von Seuchen zerfressenen Leichen auf. Da ist es schon ein Wunder, wie ihre inneren Organe die Pestilenz überwinden, die in diesen Landen wütet.$B$BHelft mir bei meinen Studien, $n! Ich brauche Muskelmägen! Aber ich benötige auch zwei Kicherfangunterkiefer. Diese stellen die Grundlage für das Gebräu dar.$B$BFür Eure Anstrengungen erhaltet Ihr eine doppelte Belohnung.",objectives={"Bringt Blutmagierin Lynnore 10 Geiermuskelmägen und 2 Kicherfangunterkiefer."}]])
R(2604,"Geistige Beherrschung",[[description="Wie ich sehe, ist Euer inneres Feuer erloschen. Was meint Ihr, hat das geistige Hochgefühl etwa eine Stunde angedauert?$B$BFalls Ihr mehr von der Muskelmagen-Kaumasse benötigt, dann benötige ich mehr Muskelmägen. Zurück in die Einöde mit Euch, $N. Kommt erst wieder, wenn Ihr zehn Muskelmägen und zwei Unterkiefer beschafft habt.",objectives={"Bringt Blutmagierin Lynnore 10 Geiermuskelmägen und 2 Kicherfangunterkiefer."}]])
R(2605,"Der durstige Goblin",[[description="Ich hab da so eine Idee. Ich habe von einigen seltsamen Kreaturen namens 'Tausammler' gehört, die im Südwesten leben. Angeblich können sie in speziellen Drüsen Wasser speichern.$B$BIch glaube, wenn ich eine von diesen Drüsen bekäme, dann könnte ich ein Getränk kreieren, das meinen schrecklichen Durst löschen würde. Könntet Ihr mir vielleicht helfen, $n?$B$BSucht bei den Kakteen, $n: Dort findet Ihr die Tausammler.",objectives={"Beschafft Euch eine volle Taudrüse und bringt sie nach Gadgetzan zu Marin Noggenfogger."}]])
R(2606,"Dem guten Geschmacke",[[description="Bäh! Igitt! Das Zeug schmeckt ja eklig! So viel dazu...$B$BBitte, was meint Ihr? Ja, ich weiß schon, Ihr findet, ich sollte nicht so schnell die Flinte ins Korn werfen. Na dann.$B$BÄhm, da fällt mir was ein! Das ist genial! Bringt diesen Tau meiner Freundin Sprinkle - sie ist eine tolle Küchenchefin. Sagt ihr, was wir vorhaben, und dass wir das Zeug etwas aufpeppen wollen.$B$BIch meine, wenn es schon so fies schmeckt, dann sollte es wenigstens einen kleinen... Kick haben. Und davon kann ich nichts bemerken...",objectives={"Marin Noggenfogger möchte, dass Ihr in Gadgetzan mit Sprinkle sprecht."}]])
R(2607,"Die Berührung von Zanzil",[[description="Es scheint, als hättet Ihr mehr Informationen bekommen, als selbst ich erwartet hätte. Es ist schon seltsam, wie das Schicksal manchmal spielt, $N.$B$BEin Heilmittel? Hmm... Geht hinunter in den Keller und sprecht mit Doc Mixilpixil: Vielleicht kann er Euch helfen.",objectives={"Sprecht im Keller der Kaserne mit Doc Mixilpixil."}]])
R(2608,"Die Berührung von Zanzil",[[description="Meine Güte, Ihr seht ja aus wie der Tod. Nein, falsch. Ich habe den Tod schon gesehen - Ihr seht schlimmer aus. Ihr seht aus wie das, was der Tod bei seiner letzten Vorsorgeuntersuchung ausgespuckt hat.$B$BHa! Habt Ihr das gehört, Noarm? Schreibt das auf!$B$B<hustet> Ähem, ja, damit ich Euch helfen kann, muss ich Euch Blut abnehmen. Und keine Sorge, es tut nur die ersten... fünfzig Male oder so weh... Wenn Ihr bereit für die Behandlung seid, $n, solltet Ihr Euch bitte /hinlegen.",objectives={"Ihr solltet Euch /hinlegen, damit Doc Mixilpixil Euch untersuchen kann. Denn wie soll er ein Heilmittel finden, wenn er die Ursache nicht finden kann?"}]])
R(2609,"Die Berührung von Zanzil",[[description="Wir sind einstimmig zu folgendem Schluss gekommen, $n... Ihr habt eine 'Itis'.$B$BZum Glück kann ich die 'Itis' heilen.$B$BUnd das brauche ich dafür: ein Bündel einfache Wildblumen, eine verbleite Phiole, eine Bronzeröhre und schließlich und endlich noch eine Rolle blassgelben Seidenfaden. Die alte Emma hat in 'Das feinste Band' eine Rolle davon für mich hinterlassen. Ihr findet den Laden an einem der Kanäle.$B$BBeeilt Euch jetzt, $n, und vermeidet es möglichst, jemanden anzufassen, bis Ihr geheilt seid. Dr. Montgomery meint übrigens, Ihr könntet eine Dusche vertragen - das hat er gesagt, nicht ich.",objectives={"Bringt Doc Mixilpixil 1 Bündel einfache Wildblumen, 1 verbleite Phiole, 1 Bronzeröhre und 1 Rolle blassgelben Seidenfaden. So eine 'Itis' heilt sich nicht von selbst, $gjunger Herr:junge Dame;."}]])
R(2621,"Der Entehrte",[[description="Bedauern. Das ist alles, was mir noch geblieben ist. Eine einzige Fehlentscheidung hatte gleich mehrere schreckliche Konsequenzen. Hätte ich doch nur auf meine Befehle gewartet. Vielleicht hätte darin etwas über die Schrecken gestanden, die uns in jenem verfluchten Land erwarteten! Vielleicht hätten sie uns zu einer anderen Abteilung beordert... Letztendlich war es meine Schuld. Es war alles meine Schuld.$B$BUnd so stehe ich hier und warte auf meine Befehle. Ich muss es wissen. Ich muss diese Befehle haben.$B$BZentralenkommandant Ruag lebt in Stonard. Findet ihn und bringt in Erfahrung, was aus den Befehlen geworden ist.",objectives={"Sprecht in Stonard mit Zentralen-Kommandant Ruag."}]])
R(2622,"Die fehlenden Befehle",[[description="Die Befehle? Jetzt sagt mir doch mal, was Ihr mit diesen Befehlen wollt!$B$BWas wollt Ihr damit andeuten, $n? Natürlich habe ich die Befehle weitergegeben! Die Soldaten, denen ich die Befehle mitgab, wurden von Murlocs überfallen und auf brutalste Weise misshandelt. Nur ein Einziger von ihnen hat überlebt... wenn man das überleben nennen kann. Er kann kaum sprechen, kann nicht mehr laufen und muss durch einen Schlauch ernährt werden. Wenn Ihr wissen wollt, was mit diesen Befehlen passiert ist, dann sprecht mit Bengor. Er treibt sich hier mit Sicherheit irgendwo herum... und, $n, seid vorsichtig, in was Ihr Eure Nase steckt. Nicht, dass sie Euch abgebissen wird!",objectives={"Sprecht mit Bengor."}]])
R(2623,"Der Sumpfredner",[[description="Befehle... vom Zentral-Kommandanten ausgegeben. Haben Befehle... genommen. Auf dem Weg in die Verwüsteten Lande... überfallen...$B$BMurlocs... Viele Murlocs... Einer... hieß Sumpfredner. Nahm mir Befehle ab, als Speer in meinen Schädel fuhr. Osten... Höhle...$B$B<Bengor verliert das Bewusstsein.>",objectives={"Beschafft die Befehle des Kriegshäuptlings wieder und gebt sie dem gefallenen Helden der Horde zurück."}]])
R(2641,"Sprinkles Geheimzutat",[[description="Als ich noch ein kleines Mädchen war, hat meine Schwester immer gekocht. Es war grauenhaft! Manche ihrer 'Gerichte' konnte ich kaum runterwürgen - bis ich irgendwann meine 'Geheimzutat' entdeckt habe! Egal, zu was man sie hinzufügt... im Nu schmeckt alles toll!$B$BUm was es sich dabei handelt, wollt Ihr wissen? Es ist ein Pilz namens violetter Tragan. Wenn Ihr wollt, dass ich dieses fürchterlich schmeckende Gebräu in etwas Genießbares verwandle, dann begebt Euch ins Hinterland und sucht dort nach einem kleinen See.$B$BUnd vergesst nicht: Violette Tragane findet man nur unter Wasser.",objectives={"Sprinkle in Gadgetzan möchte, dass Ihr einen violetten Tragan sucht und ihr bringt."}]])
R(2661,"Lieferung für Marin",[[description="Hier habt Ihr das violette Pulver, $n. Bringt es zu Marin und sagt ihm, er schuldet mir was!",objectives={"Sprinkle möchte, dass Ihr das violette Pulver nach Gadgetzan zu Marin Noggenfogger bringt."}]])
R(2662,"Noggenfogger-Elixier",[[description="So, jetzt mische ich das Pulver unter den Tau.$B$BSprecht mich in einer Minute noch mal an... wenn ich das fabelhafte Noggenfogger-Elixier perfektioniert habe!",objectives={"Marin Noggenfogger möchte, dass Ihr ihn nochmals ansprecht, wenn er sein Elixier fertig gestellt hat."}]])
R(2681,"Die Steine, die uns binden",[[description="Allein wird es Euch nicht gelingen, die Streitmacht von Razelikh und seinen Untergebenen zu überwinden.$B$BSammelt eine Gruppe von geeigneten Abenteurern um Euch und befreit meine Männer aus der ewigen Qual! Achtzehn Steine müsst Ihr zerschmettern.$B$BKämpft hart und sterbt ehrenvoll, $n.",objectives={"Befreit 9 Diener von Razelikh, 3 Diener von Sevine, 3 Diener von Allistarj und 3 Diener von Grol. Kehrt zum gefallenen Helden zurück, sobald Ihr die Aufgabe erfüllt habt. Ihr müsst nahe bei den Steinen bleiben, sonst habt Ihr keinen Erfolg."}]])
R(2701,"Helden der Vergangenheit",[[description="Bitte, nehmt Euch ein Relikt der Vergangenheit. Wir haben für den Gegenstand keine Verwendung mehr.$B$BMöge es Euch in Eurem Kampf gegen die Legion gute Dienste leisten.",objectives={"Öffnet die Truhe und nehmt Euch Eure Belohnung."}]])
R(2702,"Helden der Vergangenheit",[[description="Mit Eurem Edelmut und Eurer Heldenhaftigkeit erweist Ihr mir Ehre, $n.$B$BUnd auch ihnen habt Ihr Ehre erwiesen...",objectives={"Sprecht mit Corporal Thund Splithoof."}]])
R(2721,"Kirith",[[description="Ein Kapitel Eurer Abenteuer mag jetzt beendet sein, doch ein weiteres Kapitel beginnt gerade, $N.$B$BEiner meiner Männer ist noch immer verschollen, irgendwo in den verwüsteten Landen verschwunden. Ich spreche natürlich von Lieutenant Kirith.$B$BWie ich vorhin schon sagte, wurden wir beide von Allistarj gefangen genommen und gefoltert, aber ich fürchte, dass der arme Kirith nicht durchhielt und schwach wurde. Aus meinem Käfig heraus konnte ich die Experimente hören: Die gequälten Schreie hallten in der ganzen Höhle wider. Das war das Letzte, was ich von Kirith gesehen oder gehört habe.",objectives={"Findet heraus, was aus Lieutenant Kirith geworden ist."}]])
R(2741,"Der Super-Ei-O-Mat")
R(2742,"Rin'ji steckt in der Falle!",[[description="He, $R!$B$BBitte, helft Rin'ji flüchten. Ich weiß, Ihr seid $R, mögt Rin'jis Volk nicht, aber Rin'ji bittet und bettelt! Muss hier raus!$B$BHab auch was Schönes für $R, wenn $R nett ist und Rin'ji hier raushilft...$B$BRin'ji hat was Geheimes bei den Aussichtsklippen versteckt.",objectives={"Eskortiert Rin'ji aus der Quel'Danil-Hütte heraus und findet dann das, was er bei den Aussichtsklippen im Osten versteckt hat."}]])
R(2743,"Der Mantel der Dunkelheit",[[description="Lasst uns nicht um den heißen Brei herumreden, $R; ich habe nicht unbegrenzt Zeit.$B$BIhr müsst das Dreigestirn der Macht vernichten, das den Dämonenlord Razelikh beschützt. Doch das wird nicht ganz so einfach werden wie das Befreien einer verdammten Seele.$B$B<Kirith grinst.>$B$BIhr müsst wissen, dass jeder von Razelikhs Untergebenen ein Drittel eines von Razelikh geschaffenen Amuletts um den Hals trägt. Und genau dieses Amulett braucht Ihr, um den Erzdämon zu beschwören.$B$BGeht zu Trebor und sagt ihm, was benötigt wird, um Razelikh zu beschwören. Er kann Euch weitere Anweisungen geben.",objectives={"Kehrt mit Euren neuen Erkenntnissen zum gefallenen Helden der Horde zurück."}]])
R(2744,"Der Dämonenjäger",[[description="Das Dreigestirn wird von Razelikh beschützt.$B$BAls Lohn für ihre Dienste hat Razelikh jeden von ihnen mit schier unbegrenzter Macht in den Verwüsteten Landen ausgestattet. Die Teile des Amuletts sind auf die Lebenskraft ihrer jeweiligen Besitzer eingestellt und verleihen diesen Unsterblichkeit. Solange die sich in den Verwüsteten Landen aufhalten, können sie nicht getötet werden, und auch ihre Lebensspanne ist bis zum Ende aller Tage ausgedehnt.$B$BDoch einen gibt es, der Euch vielleicht weiterhelfen kann, $n. Reist nach Azshara und sucht dort nach dem Dämonenjäger Loramus Thalipedes. Ihr findet ihn vermutlich auf den Inseln.",objectives={"Sprecht mit Loramus Thalipedes in Azshara."}]])
R(2745,"Eindringen ins Schloss",[[description="Hmm, eine interessante Geschichte und eine, die man nicht auf die leichte Schulter nehmen sollte. Ja, ich kann Euch helfen, aber wenn Ihr das wirklich bis zum Ende durchziehen wollt, dann müsst Ihr andere Saiten aufziehen, die... nicht ganz legal sind.$B$BLescovar und Marzon müssen erledigt werden, und zwar schnell. Glaubt Ihr, Ihr seid zu so was fähig?$B$BDie Entscheidung liegt bei Euch. Falls ja, dann geht so schnell wie möglich ins Schloss und redet dort mit einem Freund von mir, einem Gnom namens Tyrion. Er beobachtet Lescovar jetzt schon seit ein paar Wochen. Er sollte Euch dabei helfen können, die Sache zu Ende zu bringen.",objectives={"Sprecht in Schloss Stormwind mit Tyrion."}]])
R(2746,"Nicht unwichtige Gegenstände",[[description="Trias will also alles ein bisschen beschleunigen, wie? Na gut, können wir zwar machen, aber ich bin noch nicht bereit. Und damit eines mal klar ist: Ich hab den anstrengenderen Job, aber Ihr seid $gderjenige, der:diejenige, die; sich die Hände schmutzig macht, verstanden? Gut.$B$BAlso, Ihr müsst mir ein paar Sachen besorgen, bevor ich meinen Plan in die Tat umsetzen kann. Ich hab schon die perfekte Verkleidung, um den Spionagebot an den Wachen vorbeizubekommen.$B$BBringt mir etwas Seide und ein paar Äpfel. Wo Ihr die Seide herkriegt, ist Eure Sache, aber auf Claras kleinem Hof draußen vor der Stadt gibt es Äpfel in genau der richtigen Größe.",objectives={"Bringt 3 Stück Seidenstoff und 2 frische Äpfel von Clara nach Stormwind zu Tyrion."}]])
R(2747,"Ein außergewöhnliches Ei")
R(2748,"Ein gutes Ei")
R(2749,"Ein gewöhnliches Ei")
R(2750,"Ein schlechtes Ei")
R(2751,"Barbarische Waffenschmiedekunst",[[description="Zwanzig Generationen von Omoshs haben diesen Hammer bereits in Händen gehalten, $n. Hunderttausend Tonnen Metall haben wir geformt. Doch leider, leider endet alles mit Orokk, dem Fehlschlag der Omosh: ohne Verwandte und nicht in der Lage, sich fortzupflanzen.$B$BIch kann nicht zulassen, dass die geheimen Rezepturen der Omosh mit mir sterben! Jemand muss das Werk fortführen, ganz gleich, ob derjenige ein Omosh ist oder nicht!$B$BBeweist Orokk, dass Ihr fähig seid, $n. Bringt Orokk die folgenden Dinge: zwei gemusterte bronzene Armschienen, zwei bronzene Großschwerter und zwei scharfe Klauen. Bringt sie Orokk, dann machen wir weiter.",objectives={"Bringt 2 gemusterte bronzene Armschienen, 2 bronzene Großschwerter und 2 scharfe Klauen zu Orokk Omosh in Orgrimmar."}]])
R(2752,"Über Eisenschulterstücke",[[description="Orokk sieht den Eifer in Euren Augen, $n. Wie ein Schwamm saugt Ihr das Wissen der Omoshs auf.$B$BDrei Lektionen werde ich Euch lehren.$B$BKehrt zum Amboss zurück, schwitzt in der Hitze der Schmiede und stellt für Orokk vier bronzene Streitäxte und vier bronzene Kriegshämmer her. Erst dann könnt Ihr etwas über Eisenschulterstücke lernen.",objectives={"Bringt 4 bronzene Streitäxte und 4 bronzene Kriegshämmer zu Orokk Omosh in Orgrimmar."}]])
R(2753,"In den Boden getrampelt",[[description="Nur zwei Lektionen noch hat Orokk für Euch, $n. Eure Muskeln schmerzen, ich weiß, doch macht weiter - für die Omoshs!$B$BBringt Orokk vier grüne Eisenhelme, vier grüne Eisenarmschienen und zwei grüne Eisengamaschen - zur Belohnung werdet Ihr lernen und Eure Feinde werden leiden!",objectives={"Bringt 4 grüne Eisenhelme, 4 grüne Eisenarmschienen und 2 grüne Eisengamaschen zu Orokk Omosh in Orgrimmar."}]])
R(2754,"Hörner der Raserei",[[description="Jetzt lehrt Orokk Euch die letzte Lektion, $n. Zurück zum heiligen Amboss und der heiligen Schmiede mit Euch! Bringt Orokk zwei robuste Eisenschlägel, zwei bronzene Stiefel mit Versilberung und zwei bronzene Stulpen mit Versilberung.$B$BSeht die Furcht in den Augen der Feinde, wenn Ihr Euch nähert!",objectives={"Bringt 2 robuste Eisenschlägel, 2 bronzene Stiefel mit Versilberung und 2 bronzene Stulpen mit Versilberung zu Orokk Omosh in Orgrimmar."}]])
R(2755,"Freude der Omoshs",[[description="Orokk weint nicht, $n. Orokk hat Ruß ins Auge bekommen.$B$B<Orokk wischt eine Träne weg.>$B$BNoch ein letztes Familiengeheimnis der Omosh wird Orokk Euch beibringen. Dank $n wird Orokk glücklich sterben.$B$BLernt den Freudentanz der Omoshs... und dann lernt Ihr Eisenfaust!",objectives={"Seht zu und lernt den Freudentanz der Omoshs."}]])
R(2756,"Die alten Traditionen",[[description="Früher, zur Zeit der Legenden, zerquetschte Aturk die Schädel seiner Feinde und zermahlte die Knochen zu einem feinen Pulver, das er zu Fasern verarbeitete. Diese Tage sind lange vergangen, $R. Der Kriegshäuptling verlangt Frieden unter den Klans. Alte Feinde werden nur noch misstrauisch beäugt!$B$BEs ist unglaublich, ich weiß, doch es ist nun einmal Thralls Wille.$B$BAber genug gejammert! Ihr seid zum Lernen hier, und Ihr werdet etwas lernen! Bringt mir vier Stahlbrustplatten und vier Stahlhelme, dann bekommt Ihr den Geschmack des Krieges zu kosten!",objectives={"Bringt 4 Stahlbrustplatten und 4 Stahlplattenhelme zu Aturk dem Amboss in Orgrimmar."}]])
R(2757,"Auf nach Booty Bay!",[[description="Hört mal, wenn Ihr hier herumhängt, lernt Ihr nix.$B$BIch kenn da so 'n Typen, der 'n Typen kennt. Der treibt sich bei der Schmiede in Booty Bay rum. Wenn Ihr ihm die Insignie hier zeigt, dann erzählt er Euch alles über Mithril.$B$BAlso, was sagt Ihr? Überlasst diesen Babykram den Kleinkindern, $N - für Euch ist es Zeit weiterzuziehen.$B$BFalls Ihr Interesse haben solltet, der Typ heißt McGavan. Zeigt ihm das hier, dann wird er sehen, dass es Euch ernst ist.",objectives={"Sprecht mit McGavan in Booty Bay."}]])
R(2758,"Die Herkunft der Schmiedekunst",[[description="Als ich etwa so alt war wie Ihr, nahm mich ein Zwerg namens Galvan unter seine Fittiche und bildete mich in der Kunst des Rüstungsschmiedens aus. Bevor er sich nach Booty Bay aufmachte, nahm er mir das Versprechen ab, dass ich all denjenigen ein Lehrer sein würde, die den Wunsch hätten und entschlossen genug wären, selbst eine Schmiedelaufbahn einschlagen zu wollen. Und hier bin ich nun - all die Jahre später.$B$BAlso, es ist jetzt Zeit für Euch, ein bisschen was zu lernen. Stellt mir sechs goldene Schuppenarmschienen her, dann zeige ich Euch, was echte Schmiedekunst ist, $N.",objectives={"Bringt 6 goldene Schuppenarmschienen zu Hank dem Hammer in Stormwind."}]])
R(2759,"Auf der Suche nach Galvan",[[description="Obwohl Galvan Booty Bay schon vor vielen Jahren verlassen hat, leben noch immer Mitglieder des Ordens in der Stadt und hoffen, dass sie eines Tages jemanden finden werden, der der Lehre von Galvan würdig ist.$B$BNehmt diese Insignie und zeigt sie McGavan in Booty Bay.$B$BSolltet Ihr es tatsächlich bis dorthin schaffen, dann weiß er, dass Ihr würdig seid. Ich glaube an Euch, $N!",objectives={"Sprecht in Booty Bay mit McGavan."}]])
R(2760,"Der Mithrilorden",[[description="Die meisten unserer Rekruten schaffen es nicht bis Booty Bay, $N. Der Glanz der Insignie reicht normalerweise aus, um selbst im zuverlässigsten Schmied die Beutegier ausbrechen zu lassen. Narren, alle zusammen, denn die Insignie ist nichts als Talmi im Vergleich zum Wert der Gegenstände, die Ihr zu sehen bekommen werdet!$B$BFindet Galvan den Alten und zeigt ihm diese Anstecknadel. Er lebt weit im Norden, zwischen Zul'Gurub und dem Ogerhügel der Mosh'Ogg.",objectives={"Sprecht mit Galvan dem Alten im Schlingendorntal."}]])
R(2761,"Hier verhütten, da verhütten",[[description="Viele Schmiede glauben, der Bergbau und die Schmiedekunst seien zwei völlig getrennte, voneinander unabhängige Dinge, aber wie kann es Schmiedekunst geben ohne Bergbau? Genau, das ist völlig unmöglich! Und daher muss der vollendete Schmied auch ein tüchtiger Minenarbeiter sein.$B$BZeigt Galvan, dass Ihr fähig seid, $n. Bringt mir vierzig Barren Eisen und vierzig Barren Mithril. Dafür sagt Galvan Euch dann alles über verschnörkelte Mithrilhosen!",objectives={"Bringt Galvan dem Alten im Schlingendorntal 40 Mithrilbarren und 40 Eisenbarren."}]])
R(2762,"Der große silberne Betrüger",[[description="Es heißt, dass Echtsilber noch stärker und haltbarer sei als Mithril. Galvan widerspricht dieser Einschätzung der Mineralien zwar nicht, aber Echtsilber trägt seinen Namen zu Unrecht. Echtsilber ist nicht echt! Mithril ist ein wesentlich edleres Mineral! HA! Aber wie dem auch sei ... für diese Lektion müsst Ihr den silbernen Betrüger finden, $N.$B$BBringt mir vierzig Barren Mithril und fünf Barren Echtsilber. Im Gegenzug werdet Ihr in das Geheimnis der verschnörkelten Mithrilhandschuhe eingeführt, und, was noch wichtiger ist, Ihr werdet lernen, dass Echtsilber lügt!",objectives={"Bringt Galvan dem Alten im Schlingendorntal 40 Mithrilbarren und 5 Echtsilberbarren."}]])
R(2763,"Die Kunst der Magieerfüllung",[[description="Der Abbau von wertvollen Edelsteinen ist für unsere Zunft von äußerster Wichtigkeit, $n. Und nur wenige Edelsteine sind wertvoller als der Citrin. Die magischen Eigenschaften, mit denen wir unsere Waren ausstatten, werden deutlich verstärkt, wenn Citrine im Spiel sind.$B$BIn dieser Lektion verstärken wir vierzig Barren Mithril mit vier Citrinen. So bekommt Ihr ein besseres Verständnis für die magische Edelsteinkunde und lernt außerdem, wie man verschnörkelte Mithrilschultern herstellt.",objectives={"Bringt Galvan dem Alten im Schlingendorntal 40 Mithrilbarren und 4 Citrine."}]])
R(2764,"Galvans bester Schüler",[[description="Wenn Ihr bereit seid, Eure Ausbildung bei Galvan abzuschließen, dann solltet Ihr nach Gadgetzan reisen.$B$BDort findet Ihr meinen besten Schüler, Trenton Lighthammer. Er kann Euch viel über verschnörkeltes Mithril beibringen. Ansonsten bleibt hier und lernt weiter!$B$BAch ja, Gadetzan liegt natürlich in Tanaris!",objectives={"Sprecht in Gadgetzan mit Trenton Lighthammer."}]])
R(2765,"Schmiedkunstexperte!",[[description="Schon als Ihr das erste Mal zu mir kamt, wusste ich, dass Ihr Euch als einer meiner besten Schüler herausstellen würdet! Ohne zu zögern trenntet Ihr Euch von einem nicht recht mächtigen Gegenstand und gabt ihn McGavan. Ihr tatet dies, nur damit Ihr mich treffen konntet. Solch blindes Vertrauen und Hingabe an unser Handwerk soll nicht unbelohnt bleiben.$B$BIhr seid zu einem wahren Experten der Schmiedekunst geworden, $n. Nun erntet den Lohn dafür!",objectives={"Fordert Eure Belohnung von Galvan dem Alten ein!"}]])
R(2766,"Findet OOX-22/FE!",[[description="Ihr habt ein merkwürdiges Gerät aus Metall entdeckt, das die Form eines Eis hat. Als Ihr einen der Knöpfe berührt, erwacht das Ei zu Leben und verwandelt sich in eine Art Gnom-Roboter-Apparat! Aus dem Inneren des Roboteis erklingt eine rasselnde Stimme.$B$B\"Mein Name ist Oglethorpe Obnoticus und mein Leitroboter ist abgestürzt! Ich werde Euch belohnen, wenn Ihr ihn aufspürt. Bringt dem Roboter bitte diesen Signalgeber!\"$B$B\"Ich habe jetzt die Koordinaten des Roboters für Euch berechnet. Er ist in der Nähe des Wildschrammtals abgestürzt!\"",objectives={"Bringt das Notrufsignal zu Oglethorpes Leitroboter in einer Höhle in der Nähe des Wildschrammtals."}]])
R(2767,"Die Rettung von OOX-22/FE",[[description="Aus dem Roboter ertönt erneut die blecherne Stimme des Gnoms:$B$B\"Ich muss OOX-22/FE an einen offenen, sicheren Ort schaffen, wo er die langwierige Startprozedur beginnen kann. Er hat eine eingebaute Tarnvorrichtung, aber ich brauche etwas Zeit, um sie von hier aus wieder zum Funktionieren zu bringen. Eskortiert den Roboter von seinem momentanen Standort zu, ach, sagen wir mal, dem Dock an der Vergessenen Küste. Das sollte der perfekte Ort für mein Vorhaben sein, und bis Ihr dort seid, sollte ich auch alles vorbereitet haben und online gehen können.\"$B$B\"Eskortiert ihn sicher bis zum Dock und kommt dann zu mir nach Booty Bay! Oglethorpe Obnoticus - Ende!\"",objectives={"Eskortiert OOX-22/FE zum Dock an der Vergessenen Küste und meldet Euch dann bei Oglethorpe Obnoticus in Booty Bay."}]])
R(2768,"Wünschel-mato-Rute",[[description="Sergeant Bly hat mich bestohlen! Er sagte, er wolle sie sich nur ausleihen, aber er hat meine geliebte Wünschel-mato-Rute gestohlen! Wo soll ich denn bitte ohne diese Rute wissen, wo ich neue Wasserlöcher graben muss?$B$BFindet Bly und bringt mir meine Rute! Ich habe gehört, er hätte seine Bande von zwielichtigen Abenteurern auf eine Schatzsuche nach Zul'Farrak im Westen geführt. Ich möchte wetten, dort findet Ihr ihn.$B$BHoffen wir, dass die Trolle ihn schon erledigt haben, denn falls Ihr Euch wegen der Rute mit ihm anlegen müsst, dann steht Euch ein schwerer Kampf bevor.",objectives={"Bringt die Wünschel-mato-Rute nach Gadgetzan zu Chefingenieur Bilgewhizzle."}]])
R(2769,"Die Brüder Brassbolt",[[description="Seid Ihr den Gebrüdern Brassbolt schon mal begegnet? Sie sind drüben in der schimmernden Ebene, in Kalimdor, um genau zu sein, und treten dort in Raketenwagenrennen gegen die Goblins an. Normalerweise gewinnen sie, aber das ist keine große Überraschung - der Wagen der Goblins fliegt so oft in die Luft, dass er es kaum jemals über die Ziellinie schafft!$B$BAber trotzdem suchen die Brassbolt-Brüder ständig nach neuen Möglichkeiten, ihren Wagen noch schneller zu machen, und Wizzle hat mir gesagt, dass er für sein nächstes Experiment noch eine sehr seltene Komponente benötigt.$B$BWahrscheinlich kommt er an dieses Ersatzteil nicht allein ran. Sprecht mit ihm, dann erfahrt Ihr mehr darüber.",objectives={"Sprecht mit Wizzle Brassbolts in der schimmernden Ebene."}]])
R(2770,"Gahz'rilla",[[description="Tief im Inneren von Zul'Farrak, der Stadt der Sandtrolle in Tanaris, liegt ein hochheiliger Teich. An diesem Teich beschwören die Trolle eine gewaltige Bestie, Gahz'rilla! Der ist so wild, dass sogar seine Schuppen vor Energie knistern. Und genau diese Energie will ich in meinem Wagen einsetzen.$B$BBringt mir die energiegeladene Schuppe von Gahz'rilla!$B$BWie man Gahz'rilla allerdings beschwört, das verraten die Trolle niemandem. Wenn Ihr ihm begegnen wollt, müsst Ihr daher erst den Trollen das Geheimnis entreißen.",objectives={"Bringt Wizzle Brassbolts in der schimmernden Ebene Gahz'rillas energiegeladene Schuppe."}]])
R(2771,"Ein schlauer Kopf auf den Schultern",[[description="Es scheint, als habe der Meister dies von Anfang an geplant. Ich habe nicht gelernt, solche Gegenstände herzustellen, wie Ihr es könnt, und Ihr habt nicht gelernt, solche Gegenstände herzustellen, wie ich es kann.$B$BDer Meister ist klug, $n. Wir werden uns gegenseitig etwas beibringen!$B$BZeigt mir, wie man eine Mithrilhelmkappe und verschnörkelte Mithrilschultern herstellt, dann zeige ich Euch, wie man einen verschnörkelten Mithrilhelm macht.",objectives={"Bringt Trenton Lighthammer 2 Mithrilhelmkappen und 1 verschnörkelte Mithrilschulter."}]])
R(2772,"Die Welt zu Euren Füßen",[[description="Bei der Talmeisterschaft der Schmiedekunst letztes Jahr mussten alle, die zusahen, erleben, wie mir so ein feiger Hund von der Gießerei der Venture Company die Beine unter dem Körper wegzog. Aber den Grund, warum ich weitermachen und die Meisterschaft am Ende gewinnen konnte, den wusste niemand. Genau, verschnörkelte Mithrilstiefel!$B$BAber für die Meisterschaft dieses Jahr muss ich lernen, wie man verschnörkelte Mithrilhosen fertigt, denn ich muss gegen einen Schredder der Venture Co. antreten! Bringt mir bei, wie man die Hosen anfertigt, und lernt, was es mit den Stiefeln auf sich hat!",objectives={"Bringt Trenton Lighthammer 2 schwere Mithrilstiefel und 1 verschnörkelte Mithrilhose."}]])
R(2773,"Mithril-Kid",[[description="Hier in der Gegend bin ich als Mithril-Kid bekannt. Ich beliefere Abenteurer aus aller Welt mit verschnörkeltem Mithril.$B$B<Trenton flüstert.>$B$BDie wissen aber nicht, dass ich bisher noch keine verschnörkelten Mithrilhandschuhe herstellen kann. Psst! Das bleibt unser kleines Geheimnis, ja?$B$BBringt mir bei, wie man verschnörkelte Mithrilhandschuhe fertigt, $n, dann zeige ich Euch im Gegenzug den Höhepunkt meiner Ausbildung unter Galvan: die verschnörkelte Mithrilbrustplatte.",objectives={"Bringt Trenton Lighthammer 2 schwere Mithrilbrustplatten und 1 verschnörkelten Mithrilhandschuh."}]])
R(2781,"GESUCHT: Kalif Skorpidstich",[[description="GESUCHT: Kalif Skorpidstich!$B$BDie Gadgetzan Water Company aus Gadgetzan in Tanaris ist bereit, eine hohe Belohnung für den Kopf von Kalif Skorpidstich, dem Anführer der Wüstenläufernomaden, zu zahlen. Seine Verbrechen belaufen sich auf:$B$B1. Ermordung von Angestellten der Gadgetzan Water Company!$B2. Stehlen von Rohstoffen der Gadgetzan Water Company!$B3. Besetzen von Eigentum der Gadgetzan Water Company!$B$BBringt Beweise für Kalif Skorpidstichs Untergang zu Chefingenieur Bilgewhizzle und Ihr werdet umgehend belohnt!",objectives={"Bringt Chefingenieur Bilgewhizzle in Gadgetzan den Kopf von Kalif Skorpidstich."}]])
R(2782,"Rin'jis Geheimnis",[[description="Die Tafel ist mit Schriftzeichen der Witherbarktrolle bedeckt. Rin’jis Geheimnis ist wirklich ein Mysterium... $B$BGut möglich, dass Ihr hier etwas ziemlich Wertvolles in Händen haltet. Andererseits könnte ebenso gut das Gegenteil der Fall sein. Ein Troll der Witherbark in Not würde wahrscheinlich alles tun, um einen Ausweg aus seinen Problemen zu finden...",objectives={"Oran Snakewrithe, eine bekannte Gelehrte auf dem Gebiet der Witherbarktrolle, könnte die Tafel vielleicht übersetzen. Normalerweise hält sie sich im Magierviertel von Undercity auf."}]])
R(2783,"Kleinliches Gezänk",[[description="Wir bekämpfen den falschen Feind, $n.$B$BDie wahre Macht in diesem Land wird zahlen- und kräftemäßig immer stärker, während wir uns mit den Orcs über verbrannte Erde zanken.$B$BSollen wir wirklich in diesem Land einen Krieg gegen die Horde führen, nur um eines Tages von den Armeen der Brennenden Legion hinweggefegt zu werden? Es ist sinnlos.$B$BBegrabt Eure Streitigkeiten, $n, und sprecht mit dem gefallenen Helden der Horde. Er kennt die Wahrheit über die Verwüsteten Lande.",objectives={"Sprecht mit dem gefallenen Helden der Horde im Grenzgebiet zwischen den Verwüsteten Landen und dem Sumpf."}]])
R(2784,"In Ungnade fallen",[[description="Hört meine Geschichte, $R.",objectives={"Lauscht der Geschichte des gefallenen Helden der Horde."}]])
R(2801,"Eine Geschichte voller Leid",[[description="Bevor wir fortfahren können, müsst Ihr meine Geschichte hören.",objectives={"Lauscht der Geschichte des gefallenen Helden der Horde."}]])
R(2821,"Das Zeichen der Qualität",[[description="Meine Einstellung zur Lederverarbeitung verlangt, dass die Arbeit von bestmöglicher Qualität zu sein hat - ohne Kompromisse. Jeder, der behauptet, Qualität sei unwichtig, wird auch versuchen, Euch ein Küstengrundstück in Dun Morogh zu verkaufen!$B$BAuf meiner jüngsten Suche nach hochwertigem Material fand ich dicke Yetibälge. Die Yeti sind in Feralas zuhause und viele findet man im Wildschrammtal. Ich hätte gern welche, und wenn Ihr mir zehn davon bringt, dürft Ihr Euch ein beliebiges Stück meiner Lederwaren aussuchen. Haltet Ihr das für angemessen? Dann sind wir im Geschäft.",objectives={"Bringt Pratt McGrubben in der Festung Feathermoon 10 dicke Yetibälge."}]])
R(2822,"Das Zeichen der Qualität",[[description="Ich bin stolz auf meine Lederarbeiten und ich glaube, das sieht man ihnen an; Qualität sollte niemals zweitrangig sein. Jeder, der behauptet, Qualität sei unwichtig, wird Euch wahrscheinlich auch glauben machen wollen, dass die Erde keine Geheimnisse enthält!$B$BAuf meiner jüngsten Suche nach hochwertigem Material habe ich dicke Yetibälge entdeckt. Die Yetis sind in Feralas beheimatet und man findet sie häufig westlich des Wildschrammtals. Ihr dürft Euch ein beliebiges Stück meiner Lederwaren aussuchen für einen Zehnerstapel Yetibälge. Wenn das für Euch akzeptabel ist, dann sind wir im Geschäft!",objectives={"Bringt Jangdor Swiftstrider im Camp Mojache 10 dicke Yetibälge."}]])
R(2841,"Maschinenkriege",[[description="Vor zwei Jahren noch hat man sich jedesmal darüber lustig gemacht, wenn die Rede auf Gnomentechnologie kam. Diese Zeiten haben sich definitiv geändert. Jetzt haben sie eine neue Maschine gebaut, die besser ist als all unsere Schreddermodelle zusammen. Ich brauche die Blaupausen dafür, $N!$B$BDummerweise sind die Pläne in einem Safe bei Robogenieur Thermaplugg sicher verwahrt. Was die Sache noch erschwert: Nur Robogenieur Thermaplugg kennt die Kombination zu diesem Safe.$B$BTut, was Ihr tun müsst, um diese Kombination zu erlangen, $N. Dann öffnet den Safe und bringt mir diese Blaupausen!",objectives={"Besorgt die Maschinenblaupausen und Thermapluggs Safekombination aus Gnomeregan und bringt sie zu Nogg nach Orgrimmar."}]])
R(2842,"Chefingenieur Scooty",[[description="In dem Moment, als wir durch Kernobee von der neuen Gnomen-Maschine hörten, haben Scooty und ich mit der Arbeit am Transpolyporter 6000 begonnen: dem schnellsten und verlässlichsten Weg nach Gnomeregan.$B$BEndlich ist er bereit, Passagiere aufzunehmen, $N. Wenn Ihr es einmal versuchen wollt, geht nach Booty Bay und redet mit Scooty am Windreiterhorst. Um nach Booty Bay zu gelangen, nehmt das Boot von Ratchet aus.$B$BNatürlich könnt Ihr auch versuchen, Euch durch die von Zwergen verseuchten Berge von Dun Morogh nach Gnomeregan durchzuschlagen!",objectives={"Sprecht mit Scooty in Booty Bay."}]])
R(2843,"Gnomer-weeeeg!",[[description="Solange Ihr den Transponder bei Euch habt, müsst Ihr lediglich auf diese Plattform hier treten und Ihr werdet nach Gnomeregan teleportiert.$B$BIhr werdet vielleicht ein paar ungewöhnliche Nebenwirkungen erleben, aber keine davon sollte dauerhaft sein... zumindest nicht mehr.$B$BIch hätte fast den wichtigsten Teil vergessen - die Rückkehr. Wenn Ihr wieder zurückkommen wollt, tretet einfach auf die Transpolyporter-Plattform in Gnomeregan!$B$BJetzt lasst uns diesen Transponder auf Euer Gewicht und Eure Größe einstellen.",objectives={"Wartet, bis Scooty den Goblin-Transponder kalibriert hat."}]])
R(2844,"Der Riesenwächter",[[description="Ich bin so unfähig, $N. Ich sollt' auf meine kleine Freundin, Shay, aufpassen, aber irgendwie ist sie mir verlor'n gegangen. Ich kann nicht genau sagen, was passiert ist, ehrlich, aber als ich sie das letzte Mal gesehen habe, lief’n wir durch die Ruinen direkt nördlich von hier.$B$BAlles war wunderbar, aber dann hab ich mich umgedreht, un’ ... sie war weg.$B$BUnd jetz' hab ich keine Ahnung, was ich tun soll. Habt Ihr 'ne Idee, $N? Ich mache mir furchtbare Sorgen.$B$BHey, wie wär’s, wenn Ihr nach Shay suchen würdet? Eure Beine sind viel schneller als meine.",objectives={"Findet das verlorene Nachtelfen-Mädchen."}]])
R(2845,"Streunende Shay",[[description="Glaubt Ihr, Ihr könnt mir helfen, meinen Weg zurück zu meinem Freund, Felsbeißer, zu finden? Er sollte auf mich aufpassen... Aber ich neige dazu, gelegentlich davonzuschlendern. Es gibt immer so viele Dinge zu sehen und ich lasse mich dann ablenken.$B$BEs gibt allerdings etwas, was immer meine Aufmerksamkeit erregt.$B$BIn dieser Truhe findet Ihr eine Glocke, die mir sehr teuer ist. Ich liebe einfach ihren Ton. Ihr habt mein Wort: Wenn ich davonschlendere, müsst Ihr lediglich damit klingeln und ich komme angelaufen.",objectives={"Nehmt Shays Glocke aus der Truhe.$B$BBegleitet Shay Leafrunner zu Felsbeißers Lager."}]])
R(2846,"Tiara der Tiefen",[[description="Vor langer Zeit besaß ich ein wunderschönes Schmuckstück, die Tiara der Tiefen. Diese war nicht nur schön, sondern enthielt auch große Macht für diejenigen, die damit umzugehen wussten.$B$BAls nun die Kunde von der Tiara die Wasserbeschwörerin Velratha erreichte, musste sie sie haben. Sie schickte Handlanger in mein Haus und die stahlen sie, während ich weg war. Diese Diebe!$B$BIch will meine Tiara wiederhaben! Geht nach Zul'Farrak, der Trollstadt in Tanaris, findet Velratha und ringt ihr die Tiara ab. Bringt sie mir zurück und Ihr steht in meiner Gunst.",objectives={"Bringt die Tiara der Tiefen zu Tabetha in den Marschen von Dustwallow."}]])
R(2847,"Wildlederrüstung",[[description="$n, Ihr werdet ziemlich gut als Lederer! Ich kenne da einige Muster, an denen Ihr vielleicht interessiert seid... Wildlederrüstung! Wildleder zieht Kraft aus den mächtigen und chaotischen Eigenschaften von Wildranken, die man in Gegenden mit üppiger Vegetation auf einigen der Kreaturen dort findet. Die daraus gefertigte Rüstung ist garantiert das Beste, was jemand Eures Geschicks herstellen kann.$B$BIch werde es Euch beibringen, aber Ihr werdet dafür eine Weile für mich arbeiten. Das Lehrgeld beträgt nur 10 Stücke dickes Leder. Danach reden wir über Details.",objectives={"Bringt Pratt McGrubben in der Festung Feathermoon 10 Stücke dickes Leder."}]])
R(2848,"Wildlederschultern",[[description="Wildlederschultern verstärken den Körper des Trägers unglaublich gut und bieten dabei erstklassigen Schutz für die Oberarme und die Schultern. Wie bei allen Wildlederrüstungen wird auch hier eine mächtige, allerdings zufällige Verbesserung erzeugt, wenn die Wildranke eingearbeitet wird.$B$BFür dieses Muster werde ich 6 dicke Rüstungssets und eine Wildranke benötigen. Das sollte für Euch kein allzu schwer zu erfüllender Auftrag sein.",objectives={"Bringt Pratt McGrubben in der Festung Feathermoon 6 dicke Rüstungssets und eine Wildranke."}]])
R(2849,"Wildlederweste",[[description="Wildlederwesten sind die Grundlage aller Wildlederrüstungssets. Das Gerüst der Weste verbindet sich mit der Wildranke, um ein Produkt zu erzeugen, das sowohl maximalen Schutz für den Torso bietet als auch der mächtigen Magie erlaubt, sich in dem Gewand auszubreiten.$B$BFür dieses Muster werde ich 2 Schildkrötenschuppenbrustplatten, 2 Paar Schildkrötenschuppenhandschuhe und eine Wildranke benötigen. Das ist ein großer Auftrag, aber sicher keiner, bei dessen Erfüllung Ihr Schwierigkeiten haben werdet.",objectives={"Bringt Pratt McGrubben in der Festung Feathermoon 2 Schildkrötenschuppenbrustplatten, 2 Paar Schildkrötenschuppenhandschuhe und eine Wildranke."}]])
R(2850,"Wildlederhelm",[[description="Ein Wildlederhelm bietet dem Träger verbesserten Kopfschutz, ohne dabei an der Bequemlichkeit zu sparen. Wie bei allen Wildlederrüstungen erzeugt die eingearbeitete Wildranke eine mächtige, aber zufällige Verbesserung der Struktur des Helms. Lederträger werden dieses Stück auf jeden Fall haben wollen!$B$BFür dieses Muster brauche ich 2 Tuniken des Nachtschleichers, 2 Stirnbänder des Nachtschleichers und eine Wildranke. Erfüllt diesen Auftrag und das Muster gehört Euch!",objectives={"Bringt Pratt McGrubben in der Festung Feathermoon 2 Tuniken des Nachtschleichers, 2 Stirnbänder des Nachtschleichers und eine Wildranke."}]])
R(2851,"Wildlederstiefel",[[description="Ihr habt schon eine ganze Menge gelernt, $n; dennoch gibt es noch mehr für Euch zu lernen. Als Nächstes sind Wildlederstiefel an der Reihe, der Grundstein eines jeden Sets.$B$BDiese Stiefel werden so gefertigt, dass sie den Fuß in Bequemlichkeit hüllen, während sie ihn gleichzeitig gegen die Gefahren des Abenteuerlebens wappnen. Die weichen Sohlen sind ein Segen für diejenigen, die bei ihrer Fußbekleidung auf leise Bewegung Wert legen.$B$BFür dieses Muster müsst Ihr mir 2 Hosen des Nachtschleichers und 2 Stiefel des Nachtschleichers besorgen. Ich werde außerdem zwei Wildranken benötigen, nicht nur eine. Wenn Ihr all das beisammen habt, gebt mir Bescheid.",objectives={"Bringt Pratt McGrubben in der Festung Feathermoon 2 Hosen des Nachtschleichers, 2 Stiefel des Nachtschleichers und 2 Wildranken."}]])
R(2852,"Wildledergamaschen",[[description="Jetzt, nachdem Ihr die Grundlagen beherrscht, seid Ihr bereit, Euch komplexeren Dingen zuzuwenden, $n. Wildledergamaschen gehören zur robustesten und stärksten Lederausrüstung überhaupt. Bauch, Hüften, Schenkel und Solarplexus werden ungeheuer gut geschützt. Und wenn dann noch die Verstärkung hinzukommt, die die Wildranke bewirkt, werden Euch die Abenteurer, die diese Rüstung besitzen, jedes Mal danken, wenn sie Euch sehen.$B$BFür dieses Muster müsst Ihr mir 2 Schildkrötenschuppenhelme, 2 Schildkrötenschuppenarmschienen und 2 Wildranken besorgen.",objectives={"Bringt Pratt McGrubben in der Festung Feathermoon 2 Schildkrötenschuppenhelme, 2 Schildkrötenschuppenarmschienen und 2 Wildranken."}]])
R(2853,"Meister des Wildleders",[[description="Nun, $n, Ihr gebt dem Wort Sorgfalt eine neue Bedeutung. Es steht nur noch ein Wildlederrüstungsmuster aus, denn Ihr habt alle anderen gemeistert. Ich werde nicht von Euch verlangen, Euch unnötig für dieses Muster abzuplagen. Ihr habt es Euch bereits mehr als verdient... Aber ich kann es Euch nicht selbst geben. Mein Lehrer, derjenige, der mich in dieses Handwerk einführte, muss Euch belohnen.$B$BBringt diesen Brief zu Telonis. Er lehrt Lederverarbeitung in Darnassus. Zeigt ihm den Brief und lasst Euch von ihm als Gleichgestellten anerkennen, so wie ich das auch tue.",objectives={"Gebt Telonis, dem Lederverarbeitungsmeister von Darnassus, Pratts Brief."}]])
R(2854,"Wildlederrüstung",[[description="$n, Euer Ruf als Lederer eilt Euch voraus. Ich besitze Wissen über die Lederverarbeitung, das zu erwerben weise von Euch wäre... Wildlederrüstung! Wildleder zieht Kraft aus den mächtigen und chaotischen Eigenschaften von Wildranken, die man in Gegenden mit üppiger Vegetation auf einigen der Kreaturen dort findet. Die daraus gefertigte Rüstung ist garantiert das Beste, was ein Handwerker Eures Geschicks herstellen kann.$B$BIch werde es Euch beibringen, aber Ihr werdet dafür eine Weile für mich arbeiten. Das Lehrgeld beträgt nur 10 Stücke dickes Leder. Danach reden wir über Details.",objectives={"Bringt Jangdor Swiftstrider im Camp Mojache 10 Stücke dickes Leder."}]])
R(2855,"Wildlederschultern",[[description="Wildlederschultern verstärken den Körper des Trägers unglaublich gut und bieten dabei besten Schutz für Oberarme und Schultern. Wie bei allen Wildlederrüstungen wird auch hier eine zufällige, aber magieerfüllte Verbesserung erzeugt, wenn die Wildranke eingearbeitet wird.$B$BFür dieses Muster werde ich 6 dicke Rüstungssets und eine Wildranke benötigen. Das sollte für Euch kein allzu schwer zu erfüllender Auftrag sein.",objectives={"Bringt Jangdor Swiftstrider im Camp Mojache 6 dicke Rüstungssets und eine Wildranke."}]])
R(2856,"Wildlederweste",[[description="Wildlederwesten sind die Grundlage jeglicher Wildlederrüstungssets. Die Struktur der Weste und das Wildrankengeflecht darin erzeugen ein Produkt, das sowohl maximalen Schutz für den Torso bietet, als auch der mächtigen Magie erlaubt, sich in dem Gewand auszubreiten.$B$BFür dieses Muster werde ich 2 Schildkrötenschuppenbrustplatten, 2 Paar Schildkrötenschuppenhandschuhe und eine Wildranke benötigen. Dies ist keine einfache Lektion, aber eine, für die Ihr sicherlich das nötige Geschick habt.",objectives={"Bringt Jangdor Swiftstrider im Camp Mojache 2 Schildkrötenschuppenbrustplatten, 2 Schildkrötenschuppenhandschuhe und eine Wildranke."}]])
R(2857,"Wildlederhelm",[[description="Ein Wildlederhelm bietet dem Träger verbesserten Kopfschutz, ohne dabei an der Bequemlichkeit zu sparen. Wie bei allen Wildlederrüstungen erzeugt die eingearbeitete Wildranke eine mächtige, aber zufällige magische Verstärkung der Struktur des Helms. Lederträger werden dieses Stück auf jeden Fall haben wollen!$B$BFür dieses Muster brauche ich 2 Tuniken des Nachtschleichers, 2 Stirnbänder des Nachtschleichers und eine Wildranke. Schließt diese Lektion erfolgreich ab und das Muster gehört Euch!",objectives={"Bringt Jangdor Swiftstrider im Camp Mojache 2 Tuniken des Nachtschleichers, 2 Stirnbänder des Nachtschleichers und eine Wildranke."}]])
R(2858,"Wildlederstiefel",[[description="Euer Wissen über die Herstellung von Wildlederrüstungen wächst, $n, aber trotzdem habt Ihr noch einiges zu lernen.$B$BWildlederstiefel sind die Grundlage eines jeden Sets. Diese Stiefel werden so gefertigt, dass sie den Fuß in Bequemlichkeit hüllen, während sie ihn gleichzeitig gegen die Gefahren des Abenteurerlebens wappnen. Die weichen Sohlen sind ein Segen für diejenigen, die bei ihrer Fußbekleidung auf leise Bewegung Wert legen.$B$BFür dieses Muster müsst Ihr mir 2 Hosen des Nachtschleichers und 2 Stiefel des Nachtschleichers herstellen. Ich werde außerdem zwei Wildranken benötigen, nicht nur eine. Wenn Ihr diese Dinge habt, werden wir weitermachen.",objectives={"Bringt Jangdor Swiftstrider im Camp Mojache 2 Hosen des Nachtschleichers, 2 Stiefel des Nachtschleichers und 2 Wildranken."}]])
R(2859,"Wildledergamaschen",[[description="Ihr seid so weit, komplexere Lektionen zu meistern, $n. Wildledergamaschen gehören zur robustesten und stärksten Lederausrüstung überhaupt. Bauch, Hüften, Schenkel und Solarplexus werden ungeheuer gut geschützt. Und wenn dann noch die Verstärkung hinzukommt, die die Wildranke bewirkt, werden Euch die Abenteurer, die diese Rüstung besitzen, jedes Mal danken, wenn sie Euch sehen.$B$BUm Euch dieses Muster zu geben, benötige ich 2 Schildkrötenschuppenhelme, 2 Schildkrötenschuppenarmschienen und 2 Wildranken.",objectives={"Bringt Jangdor Swiftstrider im Camp Mojache 2 Schildkrötenschuppenhelme, 2 Schildkrötenschuppenarmschienen und 2 Wildranken."}]])
R(2860,"Meister des Wildleders",[[description="$n, Ihr habt alles erlernt, was ich Euch lehren kann. Es gibt allerdings noch ein letztes Wildlederrüstungsmuster. Ich werde nicht von Euch verlangen, Euch unnötig dafür abzuplagen. Ihr habt es Euch bereits mehr als verdient. Jedoch kann ich dieses Muster nicht einfach mit Euch teilen.$B$BMein Lehrer, derjenige, der mich in dieses Handwerk einführte, muss Euch belohnen. Bringt diese Notiz zu Una. Sie lehrt Lederverarbeitung in Thunder Bluff. Zeigt ihr den Brief und lasst Euch von ihr als Gleichgestellten anerkennen, so wie ich das auch tue.",objectives={"Gebt Una, der Lederverarbeitungsmeisterin von Thunder Bluff, Jangdors Schreiben."}]])
R(2861,"Tabethas Aufgabe",[[description="Gerüchte besagen, dass Tabetha, eine Magierkollegin, die tief in den Marschen von Dustwallow lebt, ein Hühnchen mit einem gewissen Sandtroll in Zul’Farrak zu rupfen hat. Wenn Ihr mit Tabetha sprecht, kann sie Euch sicher mehr dazu sagen.$B$BUnd nehmt ein paar Freunde mit, $N. Falls Tabetha Euch nach Zul’Farrak schickt, wollt Ihr sicher nicht allein hingehen.$B$BIhr findet Tabethas Hütte westlich von Theramore und direkt nördlich der Stonemaul Ruinen.",objectives={"Sprecht mit Tabetha in den Marschen von Dustwallow."}]])
R(2862,"Krieg gegen die Waldpfoten",[[description="Die Gnolle... sie sind mehr als nur ein Ärgernis. Sie sind eine konstante Bedrohung für die Existenz dieses gesamten Lagers! Es ist unwichtig, ob sie Eingeborene des Feralas sind oder nicht. Wenn wir uns nicht gegen sie wappnen, werden wir uns eines Tages aus dem gesamten Gebiet vertrieben sehen.$B$BDie Gnoll-Angriffe auf das Lager wurden in letzter Zeit heftiger. Wir brauchen Eure Hilfe dabei, ihre Anzahl zu reduzieren. Bringt mir zehn ihrer Mähnen und ich werde Euch stattlich für Eure Mühe entlohnen.$B$BLos!",objectives={"Bringt Hadoken Swiftstrider im Camp Mojache 10 Mähnen eines Waldpfotengnolls."}]])
R(2863,"Schlag gegen die Alphas",[[description="Der Plan besteht darin, verschiedene Anführer der Gnolle - Alphas, wie sie sich selbst nennen - in schneller Folge auszuschalten. Wenn wir einen solch schnellen und präzisen Schlag gegen sie erzielen können, würde es in ihren Rängen zu Chaos führen. Vielleicht würde es dann endlich auch in ihren dicken, von Flöhen zerbissenen Köpfen klar, dass wir sie vernichten können und werden!$B$BIch möchte, dass Ihr der Ausführende meines Willens seid. Eliminiert innerhalb einer Stunde fünf Alphas, wenn das klappen soll, $n, sonst bleiben wir in dieser Pattsituation!",objectives={"Tötet 5 Alphas der Waldpfoten und kehrt innerhalb einer Stunde zu Hadoken Swiftstrider zurück."}]])
R(2864,"Tran'rek",[[description="Mein Vetter Tran’rek ist in Schwierigkeiten. Er versprach mir vor einer Woche eine Fuhre Skarabäuspanzerschalen und hat bisher nicht geliefert. Er ist mein Vetter, also würde ich es wirklich hassen, wenn ich jemanden nach Gadgetzan schicken müsste, um ihm etwas zu brechen.$B$BKönnt Ihr für mich mit Tran'rek sprechen? Lasst ihn wissen, dass er diese Lieferung zusammenbekommen muss, bevor ich irgendetwas Unüberlegtes mache.$B$BGadgetzan liegt im nördlichen Tanaris, in Kalimdor.",objectives={"Sprecht mit Tran’rek in Gadgetzan."}]])
R(2865,"Skarabäuspanzerschalen",[[description="Die Skarabäen von Tanaris haben sehr harte Panzerschalen! Hart genug, um sie als Baumaterial für eine Menge Dinge zu verwenden. So viele Dinge!$B$BTatsächlich sind diese Panzer so nützlich... dass die Skarabäen beinahe bis zur Ausrottung gejagt wurden.$B$BIch weiß, wo es noch mehr Skarabäen gibt, und wenn Ihr mir versprecht, mir Ihre Panzerschalen zu bringen, sage ich Euch, wo sie sind. Versprochen?$B$BO.k., die Skarabäen haben eine Kolonie in Zul’Farrak. Ich schätze, die Trolle jagen sie nicht wegen ihrer Panzerschalen.$B$BAber Ihr könnt das tun! Geht nach Zul’Farrak und besorgt mir unbeschädigte Skarabäuspanzerschalen!",objectives={"Bringt Tran’rek in Gadgetzan 5 unbeschädigte Skarabäuspanzerschalen."}]])
R(2866,"Die Ruinen von Solarsal",[[description="Südlich von uns befinden sich die Ruinen von Solarsal. Dies ist eine Gegend aus längst vergangener Zeit. Wir haben die Ruinen ursprünglich erforscht und nichts Besonderes darin gefunden. Daher sind wir friedlich wieder abgezogen.$B$BVor Kurzem haben die Hasskammnaga die Ruinen in alarmierender Anzahl besetzt. Zuerst hielten wir das für die Vorbereitungen auf einen Angriff. Obwohl diese Bedrohung immer noch gegeben ist, glauben wir, dass dort etwas anderes vorgeht.$B$BGeht dorthin, erforscht die Ruinen und achtet auf alles, was Euch ungewöhnlich vorkommt. Viel Glück, $n.",objectives={"Erforscht die Ruinen von Solarsal und findet etwas über die Anwesenheit der Naga dort heraus."}]])
R(2867,"Kehrt zur Festung Feathermoon zurück",[[description="Mit der Entdeckung des seltsamen Pavillons im Herzen der Ruinen von Solarsal ist es an der Zeit, zur Festung Feathermoon zurückzukehren und General Shandris Feathermoon zu berichten, was hier entdeckt wurde.",objectives={"Kehrt zu Shandris Feathermoon in der Festung Feathermoon zurück und berichtet von Euren Entdeckungen."}]])
R(2868,"<TXT> The Shriveled Heart",[[description="Turn this badboy into some troll tomb in the Sunken Temple, and get something cool!"]])
R(2869,"Gegen die Hasskämme",[[description="Es ist derzeit die beste Handlungsweise, davon auszugehen, dass die Naga, was auch immer sie vorhaben, langfristig versuchen werden, die Insel für sich zu beanspruchen. Wir müssen aktive Schritte unternehmen, um diese Bedrohung auszuschalten, bevor es zu spät ist.$B$BBringt mir 10 Schuppen der Hasskämme in gutem Zustand. Es dürfte offensichtlich sein, wie man an diese herankommt. Ihr werdet Euch an den Naga das erste Mal Eure Sporen verdienen und wir haben dann eine geschwächte Nagapräsenz auf der Sardor-Insel - beides sind Aussichten, die uns zum Vorteil gereichen.",objectives={"Bringt Latronicus Moonspear in der Festung Feathermoon 10 Nagaschuppen der Hasskämme."}]])
R(2870,"Gegen Lord Shalzaru",[[description="$n, unsere neuesten Spähberichte haben uns einen guten Einblick in die Kommandokette der Naga erlaubt. In ihren Truppen gibt es viele Adlige und die sind es, die den Ton angeben.$B$BUm genau zu sein, wir haben einen der grausameren Adligen als Lord Shalzaru identifiziert. Späher berichten, dass er höchstpersönlich bei einer kürzlich durchgeführten Nagaausgrabung in einer Höhle südlich der eigentlichen Ruinen, jenseits des Wassers, auf der Insel des Schreckens, ein seltsames Relikt gefunden hat.$B$BMacht dem ein Ende, indem Ihr ihm ein Ende macht, und bringt mir dieses Relikt, damit wir es untersuchen können.",objectives={"Vernichtet Lord Shalzaru und bringt dann Latronicus Moonspear in der Festung Feathermoon das geheimnisvolle Relikt, das er entdeckt hat."}]])
R(2871,"Überbringung des Relikts",[[description="Wenn Ihr so nett wärt, das Relikt zu meiner Frau Vestia zu bringen, wüsste ich das zu schätzen. Sie ist nicht nur eine gute Priesterin für unsere Gemeinde, sondern auch eine der versiertesten Gelehrten, die es gibt. Ich könnte wahrscheinlich nicht einmal dann herausfinden, wo an diesem Ding oben oder unten ist, wenn mein Leben davon abhinge. Meine Frau wiederum ... Also wenn irgendwer herausfinden kann, was das ist, dann sie ... Und wir müssen es wissen!$B$BSie befindet sich gleich um die Ecke, ohne Zweifel am Studieren. Danke, $n.",objectives={"Bringt das geheimnisvolle Relikt zu Vestia Moonspear in der Festung Feathermoon."}]])
R(2872,"Stoleys Schuld",[[description="Mein alter Kumpel Stoley schuldet mir eine ganz bestimmte Flasche Rum. Er schmeißt die Bar in Steamwheedle in Tanaris, Kalimdor, und er versprach mir, dass der Rum dort stärker ist als alles, was man in Booty Bay finden kann. Er ist so davon überzeugt, dass er sagt, wenn ich diesen Rum probiere und ihm nicht zustimme, würde er das Geld, das er mir schuldet, verdoppeln!$B$BNun, ich glaube, er ist nicht mehr so zuversichtlich wie damals, als wir zuletzt miteinander geredet haben, und hat jetzt wohl Angst, mir diesen Rum zu geben. Ich lasse eine Wette aber nicht auf sich beruhen, also wie wäre es, wenn Ihr für mich mit ihm redet?",objectives={"Sprecht mit Stoley in Steamwheedle."}]])
R(2873,"Stoleys Lieferung",[[description="Ich schulde \"Seewolf” MacKinley in Booty Bay etwas Rum, um eine Wette zu begleichen, aber mir ist der Rum ausgegangen! Kapitän Cuergo hat meine letzte Lieferung gestohlen und lagert sie in dieser ummauerten Piratenstadt im Süden.$B$BWenn Ihr meine Rumlieferung finden und zurückbringen könnt, dann kann ich MacKinley beweisen, dass Kalimdors Drinks die aus Booty Bay um Längen schlagen.",objectives={"Bringt Stoleys Lieferung zu Stoley nach Steamwheedle."}]])
R(2874,"Lieferung für MacKinley",[[description="Danke nochmals für Eure Hilfe, $N. Hier habt Ihr eine Flasche Steamwheedle-Bilge-Rum. Bringt sie zu MacKinley und er wird endlich seine verrückten Ansichten über Drinks aus Booty Bay über Bord werfen können.",objectives={"Bringt Stoleys Flasche zu \"Seewolf” MacKinley in Booty Bay."}]])
R(2875,"GESUCHT: Andre Feuerbart",[[description="Der niederträchtige Pirat Andre Feuerbart wird aufgrund seiner gegen Steamwheedle und Gadgetzan gerichteten Verbrechen gesucht.$B$BDurch Erlass der Ratsregierung ist hiermit jeder, der dies liest, zu tödlicher Gewaltanwendung bei der Festnahme von Andre und seinen Spießgesellen autorisiert.$B$BDes Weiteren gilt durch zusätzlichen Erlass, dass, sollte Andre verstorben oder anderweitig während seiner Anhörung unpässlich sein, sein Kopf als Ersatz gilt und die Aushändigung dieses Kopfes an Sicherheitschef Bilgewhizzle als vertragsbindend angesehen wird.",objectives={"Bringt Sicherheitschef Bilgewhizzle in Steamwheedle Andres Kopf."}]])
R(2876,"Schiffzeitpläne",[[description="Auf dieser Schriftrolle sind die Zeitpläne für Lieferungen zwischen Steamwheedle und Booty Bay verzeichnet. Sowohl vergangene als auch zukünftige Lieferungen sind aufgeführt sowie Schiffsnamen. Große rote Kreuze befinden sich neben einigen der Schiffsreisen und Anmerkungen wie \"Große Beute\" oder \"Harter Kampf\" neben anderen.$B$BJemand in Steamwheedle wird dieses Dokument sicher sehen wollen.",objectives={"Berichtet den Behörden in Steamwheedle von den Schiffzeitplänen."}]])
R(2877,"Skulk Rock-Aufräumen",[[description="Wir Wildhammers haben die Vergangenheit besser in Erinnerung als unsere Brüder in Ironforge. Wenn Ihr Euch hier beliebt machen wollt, dann müsst Ihr Euch schon Eure Hände für uns schmutzig machen!$B$BDie Horde hat ihre Stellungen im Hinterland bei Skulk Rock aufgegeben. Jetzt wimmelt es dort von üblen Schlämmen und Brühschlammern. Wir haben Pläne für dieses Gebiet, aber zuerst muss uns eine Aufräummannschaft dort eine Bresche hineinschlagen.$B$BUnd hier kommt Ihr ins Spiel, Sonnenschein! Geht da runter und erledigt 10 grüne Schlämme und 10 jadegrüne Brühschlammer und meldet Euch dann wieder bei mir. Zieht los!",objectives={"Tötet 10 grüne Schlämme sowie 10 jadegrüne Brühschlammer und meldet Euch dann wieder bei Fraggar Thundermantle in Aerie Peak."}]])
R(2878,"Verderbte Liedblume")
R(2879,"Der Stock von Equinex",[[description="Es sieht so aus, als könnte dieser Stock der Stock von Equinex sein. Der Stock von Equinex ist in Wirklichkeit ein Schlüssel. Mit ihm kann man den Equinex-Monolithen öffnen, der immer noch in den nördlichen Ruinen von Rabenwind steht.$B$BFindet die vier Feuer, die noch immer in den Ruinen brennen: Samha, Imbel, Byltan und Lahassa. Beschafft Euch deren Essenz. Und dann benutzt diese Essenz, während Ihr vor dem Equinex-Monolithen steht, um den Stock zu aktivieren. Wenn dies wirklich der Stock von Equinex ist, dann könnt Ihr den Monolithen öffnen und ein hochheiliges Artefakt daraus bergen.",objectives={"Aktiviert Troyas Stock und findet den Equinex-Monolithen."}]])
R(2880,"Kopfgeld für Trollhalsketten",[[description="Seid Euch darüber im Klaren, $R - wir sind NICHT Teil der Allianz! Die Wildhämmer sind unabhängig. Um den Wert einer Person zu beweisen, verlassen sie sich lieber auf Taten und hören nicht auf das Geschwätz derer, die mit ihrem Gequassel versuchen, ihre Untätigkeit zu überspielen.$B$BWenn Ihr hier Freunde sucht, beweist uns erst Euren Wert! Die üblen Trolle, die die Hänge des Hinterlands überrennen, tragen manchmal Stammeshalsketten. Bringt mir 5 davon und wir werden das als einen Schritt in die richtige Richtung für Euch verbuchen.",objectives={"Bringt Fraggar Thundermantle in Aerie Peak 5 Troll-Stammeshalsketten."}]])
R(2881,"Kopfgeld für Trollhalsketten")
R(2882,"Cuergos Gold",[[description="Diese Karte zeigt ein Stück Strand an einer Südküste. Unter der Karte stehen elegant geschriebene Worte:$B$B$BSüdlich von Wheedle$BDürft Ihr drauf hoffen$BFindet Flagge, Mast und Knochen$BGrabt dort, wenn Ihr tapfer sein wollt$BGrabt und erbt Cuergos Gold!$BEinen Schlüssel werdet Ihr brauchen, einen Schlüssel werdet Ihr sehen$BDie Mannen dort woll'n als Bezahlung Euer Blut Euch nehm'n.",objectives={"Findet Cuergos Gold!"}]])
R(2902,"Waldpfotennachforschung",[[description="Gnolle sind zwar nicht die Hellsten, aber sie werden bestimmt die Strategie ihrer jüngsten Aktivitäten irgendwo dokumentiert haben. Wenn wir diese Pläne finden würden, hätten wir eine bessere Vorstellung davon, was sie so aufbringt.$B$BIch möchte, dass Ihr zu den Waldpfoten zurückgeht und nach allem sucht, was Ähnlichkeit mit ihren Schlachtplänen haben könnte. Irgendwas muss es geben, ihre Angriffe waren einfach zu gut koordiniert. Findet diese Schlachtpläne und kommt zu mir zurück, sobald Ihr sie habt.",objectives={"Findet die Gnoll-Schlachtpläne irgendwo in den Gnoll-Lagern südlich vom Camp Mojache."}]])
R(2903,"Die Schlachtpläne",[[description="Jetzt, nachdem die Schlachtpläne der Gnolle entdeckt wurden, bleibt nur noch, die Pläne zu Hadoken Swiftstrider ins Camp Mojache zurückzubringen. Vielleicht kann er oder irgendjemand dort besser darauf schließen, was die Gnolle vorhaben.",objectives={"Bringt die Schlachtpläne der Waldpfoten zu Hadoken Swiftstrider ins Camp Mojache."}]])
R(2904,"Eine schöne Bescherung",[[description="<Kernobee stöhn.t> Was... Was ist passiert?$B$BDas Letzte, an das ich mich erinnere, ist, wie ich von einer Gruppe Dunkeleisenzwerge gefangen, halb tot geprügelt und dann hier zu diesen schmutzigen Troggs geworfen wurde.$B$BHolt mich hier raus, $N!$B$BSo ist der Plan: Bringt mich zum Ausgang; Wenn wir es lebend hier herausschaffen, geht nach Booty Bay und lasst Scooty wissen, dass ich nach Ratchet gegangen bin, um Tinkerwiz zu warnen, dass die Dunkeleisenzwerge in die Herstellung dieser Supermaschine verwickelt sind.$B$BGehen wir!",objectives={"Begleitet Kernobee zur Uhrwerkgasse und meldet Euch dann wieder bei Scooty in Booty Bay."}]])
R(2922,"Rettet Techbots Hirn!",[[description="Als unsere geliebte Stadt Gnomeregan fiel, muss ein verirrter Funke mein armes Geschöpf, Techbot, völlig durcheinander gebracht haben. Früher half er mir und meinen Kollegen mit seinen zahllosen Dingsdas und seiner endlosen Speicherkapazität, aber sein positronisches Gehirn wurde polarisiert. Es ist jetzt negatronisch... und Techbots Verhalten wurde umgekehrt. Er wütet jetzt in ganz Gnomeregan!$B$BDoch vielleicht kann man ihn noch retten. Wenn Ihr seinen Speicherkern auffinden und zu mir bringen könnt, kann ich die Ursache der Polarisierung möglicherweise finden und meinen armen Techbot reparieren.$B$B",objectives={"Bringt Techbots Speicherkern zu Tüftlermeister Overspark nach Ironforge."}]])
R(2923,"Tüftlermeister Overspark",[[description="Tüftlermeister Overspark ist ob des Schicksals seiner mechanischen Schöpfung, Techbot, ziemlich bestürzt. Ich erinnere mich an Techbot als ein freundliches und hilfsbereites Werkzeug der Gnome, aber Overspark erzählte mir, er hätte eine Fehlfunktion.$B$BWirklich traurig. Aber mit etwas Glück kann er vielleicht repariert werden!$B$BSprecht mit Tüftlermeister Overspark in Tüftlerstadt, Ironforge. Er würde sich über Eure Hilfe freuen.",objectives={"Sprecht mit Tüftlermeister Overspark in Ironforge."}]])
R(2924,"Grundlegende Artifixe",[[description="Ein beinahe universell einsetzbares mechanisches Bauteil - das grundlegende Artifix - war den Tüftlern und Schmieden von Gnomeregan von großem Nutzen. Doch während der panischen Flucht aus unserer Stadt hat niemand daran gedacht, einige von diesen Geräten mitzunehmen! Und ich brauche eine ganze Menge davon für eine Arbeit, die ich in Kürze in Angriff nehmen werde.$B$BBitte, geht nach Gnomeregan und bringt mir einige grundlegende Artifixe. Ihr werdet sie in den tieferen Bereichen unserer Stadt finden, in \"Künstliche Extrapolatoren\" genannten Behältern.$B$BDanke, $N, und bitte beeilt Euch!",objectives={"Bringt Klockmort Spannerspan in Ironforge 12 grundlegende Artifixe."}]])
R(2925,"Klockmorts Grundlagen",[[description="Ein Gnomen-Freund, Klockmort Spannerspan, hat mich aus Ironforge kontaktiert. Er teilt mir mit, dass er Hilfe bei einer gefährlichen, aber unverzichtbaren Mission nach Gnomeregan braucht, der einst so großen Gnomen-Stadt, die jetzt verseucht und voller verrückter Gnome und ihrer Gerätschaften ist.$B$BIch muss hier bleiben, aber mir blutet das Herz, wenn ich meinem Freund nicht helfen kann. Wenn Ihr an meiner Stelle gehen könnt, dann stünde ich tief in Eurer Schuld.$B$BIhr könnt Klockmort in Tüftlerstadt in Ironforge finden.",objectives={"Sprecht mit Klockmort Spannerspan in Ironforge."}]])
R(2926,"Gnogaine",[[description="Seit dem Unfall redet Gnoarn nur noch davon, Gnomeregan vom Troggbefall zu befreien und ein Heilmittel für die Erkrankung, die die Stadt verseucht, zu finden, $n.$B$BZum Glück sind Razzle und ich gerade dabei, ein solches Heilmittel zu entwickeln... oder vielleicht auch ein Rezept für wirklich starken Rum. Genau wissen wir das aber erst, wenn wir es ausprobiert haben! Logischerweise benötigen wir zum Test unserer Theorie ein paar Dinge, vor allem Ablagerungen von den bestrahlten Troggs in Gnomeregan. Füllt diese Phiole mit dem grünen Leuchten und bringt sie zurück!",objectives={"Sammelt mit der leeren bleiernen Sammelphiole radioaktive Ablagerungen bestrahlter Eindringlinge oder Plünderer. Sobald sie voll ist, bringt Ihr sie zu Ozzie Togglevolt nach Kharanos zurück."}]])
R(2927,"Der Tag danach",[[description="Ihr glaubt doch wohl nicht, dass ich schon immer so kahlköpfig war, oder? Nein, $gwerter Herr:holde Dame;! Das Strahlungsleck in Gnomeregan rief diesen tragischen Haarverlust hervor. Vor jenem Tag hatte ich den einzigen Gnomen-Afro in ganz Azeroth.$B$B<Gnoarn schüttelt drohend die Faust.>$B$BVerdammt seien diese verdammten dreckigen Troggs, verdammt seien sie alle!$B$BVielleicht ist es noch nicht zu spät, $N. Wir können sie vielleicht immer noch retten - die Stadt, meine ich! Sprecht mit Ozzie Togglevolt in Kharanos. Er und sein Partner Razzle arbeiten an einer Lösung.",objectives={"Sprecht mit Ozzie Togglevolt in Kharanos."}]])
R(2928,"Gyrobohrmatische Exkavation",[[description="Es ist schrecklich, $n. Wir werden nicht genug Teile haben, um unsere Flotte aus gyrobohrmatischen Exkavationatoren nach Dun Morogh zu bringen.$B$BWir brauchen Ersatzteile, $n. Und welch besseren Ort als Gnomeregan könnte es geben, um Ersatzteile für unsere Fahrzeuge zu besorgen? Es heißt, dass Bots und Mechs dort herumlaufen wie Vieh auf der Weide.$B$BIhr müsst für mich nach Gnomeregan gehen und diese Roboter auseinander nehmen. Bringt mir ihre Innereien. Zwei Dutzend sollten ausreichen.",objectives={"Bringt 24 robomechanische Innereien zu Shoni nach Stormwind."}]])
R(2929,"Der große Verrat",[[description="Ich habe Thermaplugg vertraut, $R. Ich hätte nie vermutet, dass er mich und das ganze Gnomen-Volk verraten würde. Und wofür? Macht? Reichtum? Alles Dinge, die er mit der Zeit auch so erlangt hätte. Jetzt sind wir aus unserer Heimat verdrängt worden und dieser Wahnsinnige ist dafür verantwortlich. Der König des Nichts ...$B$BWir werden Gnomeregan zurückerobern, $N. Wir werden nicht ruhen, bis die Stadt wieder unter unserer Kontrolle steht. Wenn Ihr Euch unserem Kampf anschließen wollt, habe ich eine einfach Bitte an Euch: Tötet den Verräter. Vernichtet Robogenieur Thermaplugg.",objectives={"Reist nach Gnomeregan und tötet Robogenieur Thermaplugg. Kehrt zu Hochtüftler Mekkatorque zurück, wenn der Auftrag ausgeführt ist."}]])
R(2930,"Datenrettung",[[description="Als wir aus Gnomeregan flohen, haben wir so viele Daten zurückgelassen! Lebenswichtige Informationen!$B$BIch brauche die Daten auf einer Prismalochkarte aus einem Matrix-Prägographen 3005-D, einem Hochsicherheitsterminal, tief in Gnomeregan. Ihr müsst auf dieses Terminal zugreifen, aber dafür braucht Ihr die Zugangsberechtigung ... und um die zu erhalten, müsst Ihr erst Zugang zu den Terminals niedrigerer Sicherheitsstufen - Modelle A, B und C - haben. DAFÜR wiederum braucht Ihr Sicherheitslochkarten, angefangen mit einer weißen ... Und wir haben alle Lochkarten in der Stadt vergessen.$B$BDas ist eine Katastrophe! Könnt Ihr helfen?",objectives={"Bringt Mechanikermeister Castpipe in Ironforge eine Prismalochkarte."}]])
R(2931,"Castpipes Auftrag",[[description="Mechanikermeister Castpipe in Ironforge sucht Abenteurer! Er organisiert Teams, um Gnomeregan auf einer Datensicherungsmission höchster Sicherheitsstufe und Wichtigkeit zu betreten.$B$BCastpipe mag zwar nicht wie ich ein Mitglied der Erleuchteten Vereinigung für Arkanologie, Alchimie und Ingenieurwissenschaften sein, aber er ist dennoch ein kluger Gnom, und wenn er es für wichtig hält, dann besteht nach meinen Berechnungen eine vierundachtzigprozentige Wahrscheinlichkeit, dass es wirklich wichtig ist.$B$BDas ist eine gute Chance!",objectives={"Sprecht mit Mechanikermeister Castpipe in Ironforge."}]])
R(2932,"Grausige Botschaft",[[description="Die Trolle der Witherbark waren einst Verbündete der Horde, aber sie haben Thrall hintergangen... und das muss bestraft werden!$B$BHier, nehmt meine Pike und geht weit gen Norden ins Hinterland. Ihr werdet es nordöstlich von Tarrens Mühle vorfinden, einem Dorf, das von unseren Verbündeten, den Verlassenen, kontrolliert wird.$B$BWenn Ihr ins Hinterland kommt, jagt Trolle der Witherbark. Sammelt ihre Schädel und rammt meine Pike in einem ihrer kleineren Dörfer in den Boden: in Hiri'watha oder Zun'watha.$B$BZeigt ihnen, dass ihre heimtückischen Taten Konsequenzen nach sich ziehen!",objectives={"Sammelt Schädel der Witherbark und hängt sie an Nimboyas Pike. Platziert Nimboyas behängte Pike in einem der Witherbarkdörfer im Hinterland und kehrt dann zu Nimboya ins Schlingendorntal zurück."}]])
R(2933,"Giftflaschen",[[description="Diese Flaschen enthalten ein übles grünes Gift.$B$BWenn man die Anzahl der Flaschen in diesem Dorf bedenkt, müssen die Witherbarks ihn für sehr wichtig halten. Vielleicht will einer der Apotheker im nahe gelegenen Tarrens Mühle eine Probe davon.",objectives={"Bringt eine Giftflasche zu einem Apotheker nach Tarrens Mühle."}]])
R(2934,"Unbeschädigter Giftbeutel",[[description="Ich benötige eine frische Probe von dem Gift, den Ihr mir gebracht habt. Die Spinnen, von denen er gesammelt wurde, dürften im Hinterland leben. Jagt sie, bis Ihr einen unbeschädigten Giftbeutel findet, und bringt ihn mir. Ihr findet viele Spinnen nahe der Trollstadt Shadra'Alor.$B$BUnd trödelt nicht rum, $N, denn der Giftbeutel muss frisch sein, wenn Ihr ihn abliefert.",objectives={"Bringt Apotheker Lydon in Tarrens Mühle einen unbeschädigten Giftbeutel."}]])
R(2935,"Konsultiert Meister Gadrin",[[description="Das Gift der Brutwachen war nicht so potent wie das Gift, den Ihr mir ursprünglich gebracht habt. Er muss von einer anderen Spinne gewesen sein.$B$BIch will eine frische Probe dieses Gifts. Um herauszufinden, woher er kam, müsst Ihr Euch mit einem Troll unterhalten, der die Witherbark gut kennt - Meister Gadrin im Dorf Sen’jin. Reist nach Durotar und sprecht mit Gadrin. Wenn wir Glück haben, weiß er, woher die Witherbarks ihr Gift bekommen.",objectives={"Sprecht mit Meister Gadrin in Sen'jin."}]])
R(2936,"Der Spinnengott",[[description="Die Witherbarks verehren einen Spinnengott und von ihm bekommen sie ihr wirkungsvolles Gift. Wenn Ihr also ihr Gift wollt, müsst Ihr ihren Gott beschwören!$B$BUm das zu tun, müsst Ihr seinen wahren Namen wissen und dieser Name steht auf einer Tafel, die in Tanaris, in der Trollstadt von Zul’Farrak, in einer Gruft vergraben ist, die von Theka dem Märtyrer bewacht wird.$B$BBesiegt Theka und findet und lest diese Tafel, um den Namen des Spinnengottes herauszufinden. Wenn Ihr ihn kennt, kehrt zu mir zurück.",objectives={"Lest von der Schrifttafel des Theka, um den Namen des Spinnengottes der Witherbark zu erfahren, und kehrt dann zu Meister Gadrin zurück."}]])
R(2937,"Die Beschwörung von Shadra",[[description="Nehmt dieses Pergament und verlest es am Altar von Shadra'Alor tief in der Welt der Witherbark im Hinterland. Dies wird Shadra, den Spinnengott, beschwören.",objectives={"Besiegt Shadra am Altar von Shadra’Alor und bringt sein Gift zu Apotheker Lydon nach Tarrens Mühle."}]])
R(2938,"Gift für Undercity",[[description="Das Gift, das Ihr vom Spinnengott der Witherbarks beschafft habt, ist ein großer Fund! Ich konnte mit nur einem Tropfen von dem Zeug fast zwei Dutzend Hasen töten! Na gut, einige dieser Hasen waren sehr jung und klein genug, um auf eine Handfläche zu passen, und daher war ihre Widerstandskraft gegen Toxine bestimmt niedrig, aber man kann nicht leugnen, dass dieses Gift mächtig ist!$B$BIch würde gern eine Probe zu meinem Vorgesetzten, Apotheker Faranell, in das Apothekarium von Undercity entsenden. Ich bin sicher, er würde es gern selbst testen.",objectives={"Bringt Faranells Päckchen zu Apothekermeister Faranell nach Undercity."}]])
R(2939,"Auf der Suche nach Wissen",[[description="Auch wenn die Ruinen von Feralas ziemlich gefährlich sein können, so erzählen sie doch viel darüber, was hier passiert ist...$B$BAls ich vor einigen Tagen das Geröll südlich von hier durchstöberte, fand ich etwas, das wie ein gewöhnlicher Stock aussah. Allerdings werde ich das Gefühl nicht los, dass es mehr damit auf sich hat. Angelas und ich haben über unseren Büchern hier gebrütet, aber wir konnten nichts darüber herausfinden.$B$BIch habe aber eine Kollegin in Darnassus, die uns vielleicht erzählen kann, was das ist, $n. Warum sprecht Ihr nicht mit ihr und seht, ob sie uns helfen kann?",objectives={"Sprecht mit Daryn Lightwind im Dorf Rut'theran."}]])
R(2940,"Feralas: Ein historischer Abriss",[[description="Es sieht so aus, als sei dieses Buch seit langer Zeit von niemandem mehr geöffnet worden. Sein Einband ist ziemlich abgenutzt und seine Seiten sind vergilbt, aber nach einer kurzen Untersuchung stellt Ihr fest, dass es genau das sein könnte, was Troyas sucht.$B$BIhr steckt es ein, aber dann fällt Euch ein, dass Ihr vielleicht vorher fragen solltet, bevor Ihr es ausleiht.",objectives={"Fragt Daryn Lightwind, ob Ihr Euch ihr Buch ausleihen dürft."}]])
R(2941,"Der Borger",[[description="Ich habe in meinem Leben viele Dinge studiert und meine jüngste Leidenschaft sind die Schnappkiefer, die den Strand im Hinterland bevölkern. Es gibt einen bestimmten, den ich gern sehen würde, einen Riesenschnappkiefer namens Gammerita. Ich würde gern selbst hingehen, aber meine Forschungen halten mich hier. Ein Bild von Gammerita wäre wohl die nächstbessere Lösung.$B$BBringt diesen Brief zu Curgle Cranklehop nach Tanaris. Sie hat etwas für mich erfunden, das Bilder einfangen kann. Ich glaube, sie nannte es \"Schnappschuss\" ...",objectives={"Bringt den Brief zu Curgle Cranklehop nach Tanaris."}]])
R(2942,"Der Morgenstein",[[description="In dem Moment, in dem das Artefakt vom Monolithen getrennt wird, fühlt Ihr, wie die Energie im Stock von Equinex sich zu verflüchtigen beginnt.",objectives={"Bringt den funkelnden Stein und den Stock von Equinex zu Troyas Moonbreeze in die Festung Feathermoon."}]])
R(2943,"Rückkehr zu Troyas",[[description="Hier, $n. Bitte, passt auf mein Buch auf.$B$BNun aber schnell. Troyas wartet bestimmt schon ganz ungeduldig auf Eure Rückkehr.",objectives={"Liefert das Buch bei Troyas Moonbreeze in der Festung Feathermoon ab."}]])
R(2944,"Der Superschnapper FX",[[description="Werft erst mal einen Blick auf meine neue Erfindung, $n. Visiert einfach an, wovon Ihr ein Bild haben möchtet, und drückt dann auf den Knopf.$B$BWas war das für eine Kreatur aus dem Hinterland, die Ihr erwähnt habt? Gammerita? Tja, viel Erfolg bei der Suche nach ihr. Ich bin sicher, Daryn wird mit dem Schnappschuss, den Ihr ihr zurückbringt, sehr zufrieden sein.$B$BWie auch immer, hier habt Ihr den Superschnapper. Viel Spaß!",objectives={"Benutzt den Superschnapper FX, um einen Schnappschuss von Gammerita zu machen, und kehrt dann zu Daryn Lightwind nach Rut'theran zurück."}]])
R(2945,"Schmutzverkrusteter Ring",[[description="Ihr habt bei einer der Leichen der Dunkeleisenzwerge etwas entdeckt, das wie ein Ring aussieht. Es ist jedoch schwer zu sagen, was für ein Ring das ist. Das Ding ist derart mit Dreck und Verkrustungen überzogen, dass man es unmöglich an einen Finger stecken kann. Ihr glaubt, unter den Verkrustungen Edelmetall schimmern und vielleicht sogar einen Edelstein glitzern zu sehen.$B$BWenn Ihr diesen Ring verwenden wollt, müsst Ihr nach etwas suchen, das die Verkrustungen entfernt.",objectives={"Findet einen Weg, den schmutzverkrusteten Ring zu säubern."}]])
R(2946,"Mal sehen, was passiert...",[[description="Wir möchten, dass Ihr die Mininaturscheiben, die Ihr gefunden habt, zu den versiegelten Toren von Uldum bringt. Wir... wir sind uns nicht ganz sicher, was dann passieren wird.$B$BEs klingt ein bisschen riskant, sicher, das geben wir auch zu. Es könnte allerdings auch sein, dass überhaupt nichts passiert. Vielleicht müsst Ihr mit den Scheiben irgendetwas anstellen. Vielleicht öffnen sich die Türen, wenn Ihr die Scheiben bei Euch habt. Versucht alles Mögliche und seid offen für alles, was passieren könnte.$B$BWenn Ihr herausgefunden habt, was die Scheiben bewirken, kehrt nach Ironforge zurück. Es wird einiges zu untersuchen geben, wenn Ihr das erledigt habt!",objectives={"Bringt die Miniaturplatinscheiben zu den Toren von Uldum in Tanaris und sucht nach Hinweisen auf die Verbindung zwischen beidem."}]])
R(2947,"Die Rückkehr des Rings",[[description="Ihr öffnet die Schachtel, die der Funkelmat 5200 ausgegeben hat, und entdeckt, was Ihr vermutet hattet - einen glänzenden Ring! Beim Anstecken des Rings fühlt Ihr magische Macht durch Euren Körper fließen.$B$BAuf der Innenseite des Rings befindet sich eine kleine, aber dennoch klar erkennbare Gravur des Siegels von Ironforge. Daneben sind drei kleine Initialen eingraviert: \"TdK\". Dies könnten entweder die Initialen des ursprünglichen Besitzers oder die des Herstellers des Rings sein. Den Ring behalten ... oder ihn dieser Person zurückgeben? Entscheidungen über Entscheidungen ...",objectives={"Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist."}]])
R(2948,"Gnomen-Verbesserungen",[[description="Hört mir zu, $n. Dieser Ring gehört Euch, das ist schon richtig... aber ich kann Euch einen besseren machen! Das Design ist, wie ich bereits sagte, wirklich einfach. Ich bin heutzutage wesentlich geschickter und für die läppische Summe von dreißig Silbermünzen werde ich ihn für Euch aufpeppen! Na ja, eigentlich etwas mehr als dreißig...$B$BIch bin derzeit in einer misslichen Lage. Mein ganzer Materialvorrat ist aufgebraucht. Wenn Ihr mir einen Barren Silber und einen Moosachat bringt, verziere ich Euch den Ring damit und peppe ihn richtig schön auf!!$B$BVertraut mir!",objectives={"Bringt Talvash del Kissel in Ironforge den glänzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen."}]])
R(2949,"Die Rückkehr des Rings",[[description="Ihr öffnet die Schachtel, die der Funkelmat 5200 ausgegeben hat, und entdeckt einen glänzenden Ring! Beim Anstecken des Rings fühlt Ihr magische Macht durch Euren Körper fließen.$B$BAuf der Innenseite des Rings befindet sich eine kleine, aber dennoch klar erkennbare Gravur des Siegels von Orgrimmar. Daneben sind Buchstaben eingraviert, aber selbst nach der Säuberung sind nur die ersten drei zu erkennen: 'NOG...'$B$BDies könnten entweder die Initialen des ursprünglichen Besitzers oder die des Herstellers des Rings sein. Den Ring behalten ... oder 'NOG' suchen - Entscheidungen, Entscheidungen ...",objectives={"Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist."}]])
R(2950,"Noggs Ringerneuerung",[[description="Nein, nein, nein - ich behaupte nicht plötzlich, der Ring sei meiner. Normalerweise mache ich so etwas nicht, aber Eure Information über die Dunkeleisenzwerge war sehr nützlich. Ich werde diesen Ring für Euch so verbessern, dass selbst der, der dieses einfache kleine Ding hergestellt hat, es nicht hätte besser machen können. Wahrscheinlich war es irgendein Gnom ...$B$BWenn Ihr mir einen Barren Silber, einen Moosachat und dreißig Silbermünzen bringt, verziere ich den Ring damit derart, dass seine Magie noch verstärkt wird. Interessiert?",objectives={"Bringt Nogg in Orgrimmar den glänzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen."}]])
R(2951,"Der Funkelmat 5200!",[[description="Dieser Apparat ist etwas ganz Besonderes unter den Gnomen, er bietet dem Wahnsinn außerhalb dieses Raums tapfer die Stirn. Eine kleine Plakette auf dem Gerät besagt: \"Der Funkelmat 5200\", gefolgt von einem kurzen Text:$B$B\"Schmutz und Verkrustungen ruinieren Euer Funkelzeug? Der Funkelmat 5200 definiert das Wort Glanz neu! Gebt den Gegenstand hinein, den Ihr gesäubert haben wollt, und werft drei Silbermünzen in den Münzschlitz. Lasst den Funkelmat 5200 einen Moment arbeiten - und voilà! Eure Wertgegenstände werden sauber und glänzend herauskommen!\"",objectives={"Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren."}]])
R(2952,"Der Funkelmat 5200!")
R(2953,"Mehr Spaß mit dem Funkelmaten")
R(2954,"Der Steinbehüter",[[description="Willkommen - Ich bin der Wächter des Eingangs. Ich werde Euch den Zugang zum Areal von Uldum nur gewähren, wenn Ihr die Platten von Uldum in Euren Scheibensatz integriert habt.$B$BDas Erscheinen des Steinbehüters von Norgannon muss die Reaktion sein, die man sich davon erhoffte, als man Euch mit den Platinscheiben in die Tanariswüste schickte. Wie Euch aufgetragen, werdet Ihr die Geschichte, die hinter dem Steinbehüter steckt, herausfinden müssen, bevor Ihr weitermachen könnt.",objectives={"Findet den Zweck des Steinbehüters von Norgannon heraus und interagiert dann mit dem Uldum-Sockel in der Tanariswüste."}]])
R(2962,"Das einzige Heilmittel ist mehr grünes Leuchten",[[description="Eure Probe war nicht nur von unzureichender Menge, sondern auch noch verunreinigt.$B$BWas wir brauchen, ist mehr von dem grünen Leuchten. Die Troggs sind offensichtlich nicht stark genug verstrahlt, um unseren Ansprüchen zu genügen. Ihr werdet nach Gnomeregan gehen und etwas der radioaktiven Ablagerung direkt von der Quelle besorgen müssen. Ich spreche von den bestrahlten Brühschleimern, Lauerern und Schrecken. Seid gewarnt, diese Art von Ablagerung ist schwer abzufüllen. Es könnte Euch mehrere Versuche mit der Phiole kosten, bis Ihr eine geeignete Probe bergen könnt.",objectives={"Reist nach Gnomeregan und bringt etwas von der hoch konzentrierten radioaktiven Ablagerung zurück. Seid gewarnt, die Ablagerung ist instabil und wird ziemlich schnell zerfallen.$B$BOzzie wird außerdem Eure schwere bleierne Phiole benötigen, nachdem die Aufgabe erledigt ist."}]])
R(2963,"Omen von Uldum",[[description="Seid mir erneut gegrüßt, $n! Seit Eurer Entdeckung in Uldaman ist die Forscherliga voller Aufregung. Die Liga hat daran gearbeitet, die Geheimnisse der Miniaturplatinscheiben zu enträtseln, die Ihr gefunden habt. Euer treffliches Erscheinen hier in der Halle erlaubt es mir, Euch mitzuteilen, dass wir ziemlich wahrscheinlich eine Spur haben!$B$BHistoriker Karnik hat einige wichtige Hinweise auf den wahren Ursprung des Tals der Behüter in der Tanariswüste gefunden. Er möchte so schnell wie möglich mit Euch sprechen!",objectives={"Sprecht mit Historiker Karnik in der Halle der Forscher in Ironforge."}]])
R(2964,"Eine zukünftige Aufgabe",[[description="Nun, $n... Wir scheinen derzeit in einer temporären Sackgasse zu stecken. Wir wissen, was wir brauchen - die Platten von Uldum -, aber wir haben keinen Schimmer, wo diese sein könnten. Wir müssen eine Menge Nachforschungen anstellen, um einen guten Einsatzplan zusammenzustellen. Ich habe ein paar Ideen, wo man mit der Suche anfangen könnte. Ich hege große Hoffnungen, dass wir Euch bald bitten werden, loszuziehen und sie zu bergen.$B$BDer Hochforscher muss hiervon in Kenntnis gesetzt werden, $n. Zweifellos wird er Euch ebenfalls persönlich dafür danken wollen, dass Ihr der Liga wieder einmal geholfen habt.",objectives={"Sprecht mit Hochforscher Magellas in Ironforge."}]])
R(2965,"Omen von Uldum",[[description="Ah, $n, es ist vortrefflich, dass Ihr erneut zu mir gekommen seid. Eure Funde auf der Uldaman-Grabungsstätte haben uns Gelehrten sicherlich einigen Gesprächsstoff geliefert. Ich unterhielt mich also gerade mit einer der Druiden, Nara Wildmane, als mir dämmerte, dass ihre früheren Erfahrungen als Abenteurer von großer Wichtigkeit für unseren nächsten Schritt sein könnten.$B$BIch möchte, dass Ihr mit ihr über ihre Reisen ins Tal der Behüter in der Tanariswüste sprecht. Sie erwartet Euch auf der Anhöhe der Ältesten.",objectives={"Sprecht mit Nara Wildmane auf der Anhöhe der Ältesten in Thunder Bluff."}]])
R(2966,"Mal sehen, was passiert...",[[description="Sage Truthseeker und ich würden Euch bitten, die Miniaturscheiben, die Ihr gefunden habt, zu den versiegelten Toren von Uldum zu bringen. Wir... wir sind uns nicht ganz sicher, was dann passieren wird.$B$BDas klingt ein wenig riskant, sicher, das geben wir auch zu. Es könnte allerdings auch gar nichts passieren. Vielleicht müsst Ihr die Scheiben mit etwas benutzen. Vielleicht öffnen sich die Türen, wenn Ihr die Scheiben bei Euch habt. Versucht alles Mögliche und seid bereit für alles, was passieren könnte.$B$BFindet alles heraus, was Ihr könnt, und kehrt dann zu mir zurück. Wir werden dann viel zu bereden haben.",objectives={"Bringt die Miniaturplatinscheiben zu den Toren von Uldum in Tanaris und sucht nach Hinweisen auf die Verbindung zwischen beidem."}]])
R(2967,"Rückkehr nach Thunder Bluff",[[description="Ihr greift erneut auf den Sockel zu und die Platinscheiben erscheinen plötzlich wieder in Eurem Rucksack.$B$BNachdem Ihr das Wissen des Steinbehüters verinnerlicht habt und die Scheiben wieder in Eurem Besitz sind, ist es jetzt an der Zeit, nach Thunder Bluff zurückzukehren und Nara Wildmane von Eurer Entdeckung in Kenntnis zu setzen.",objectives={"Sprecht mit Nara Wildmane in Thunder Bluff."}]])
R(2968,"Eine zukünftige Aufgabe",[[description="Nun, $N... Wir scheinen unglücklicherweise in einer Sackgasse zu stecken. Wir wissen, was wir brauchen - die Platten von Uldum -, aber wir haben keinen Schimmer, wo diese sein könnten. Wir werden Nachforschungen darüber anstellen und dann einen soliden Einsatzplan entwickeln. Ich habe ein paar Ideen, wo man mit der Suche anfangen könnte; Ich hege große Hoffnungen, dass wir Euch bald bitten werden, Euch wieder unseren Bemühungen um die Entdeckung der Wahrheit anzuschließen.$B$BSage Truthseeker muss hiervon in Kenntnis gesetzt werden, $N; zweifellos wird er Euch ebenfalls persönlich dafür danken wollen, dass Ihr noch einmal dem Ruf gefolgt seid.",objectives={"Sprecht mit Sage Truthseeker in Thunder Bluff."}]])
R(2969,"Freiheit für alle Kreaturen",[[description="Der dreckige Grimmtotemklan fängt Feendrachen ein, $N. Jer’kai und ich haben keine Ahnung, was sie mit ihnen vorhaben, aber es ist bestimmt nichts Gutes.$B$BWir sind nicht stark genug, um uns durch das Lager zu kämpfen und die gefangenen Drachen zu befreien, aber mit Eurer Hilfe...$B$BWenn Ihr willens seid und ein paar starke Freunde habt, dann befreit mit diesem Schlüssel die Kreaturen aus ihrem Käfig und stellt sicher, dass sie mit ihrem Leben davonkommen. Ich werde die ganze Zeit an Eurer Seite sein. Jer'kai wird hier bleiben.",objectives={"Befreit mit dem Bambuskäfigschlüssel die Grimmlingflitzer aus dem Pferch im Grimmtotemlager. Kindal Moonweaver sowie mindestens 6 Grimmlingflitzer müssen überleben.$B$BIhr habt 6 Minuten, bis Kindal beschließt, dass es Zeit zum Rückzug und Eure Aufgabe gescheitert ist."}]])
R(2970,"Gerechtigkeit üben",[[description="Wie sie Euch ja schon mitgeteilt hat, tragen Kindal und ich den Kampf jetzt zu den Grimmtotem. Gemeinsam sollten wir in der Lage sein, einige der Tauren ohne große Gefahr für uns selbst auszuschalten, aber wir würden etwas Hilfe sehr begrüßen, wenn Ihr dazu bereit wärt.$B$BIhr habt das Lager unterhalb von uns ja schon gesehen, aber es gibt mehr davon im Osten. Verwendet Eure eigenen Taktiken, um den Tauren so viel Schaden wie möglich zuzufügen. Wir können uns alle wieder hier treffen, nachdem sie Kindals Pfeile und Eure Waffen geschmeckt haben!",objectives={"Tötet 12 Naturalisten der Grimmtotem, 10 Räuber der Grimmtotem sowie 6 Schamanen der Grimmtotem und kehrt dann zu Jer’kai Moonweaver nach Feralas zurück."}]])
R(2971,"<UNUSED>",[[description="[PH] Description",objectives={"[PH] Log Description"}]])
R(2972,"Gerechtigkeit üben",[[description="Hier draußen in der Wildnis haben Kindal und ich nur geringe Mittel, um Euch für Eure Hilfe zu entlohnen, aber wir wollen nicht, dass Ihr Euch nicht wertgeschätzt fühlt. Nehmt meinen Siegelring.  Solltet Ihr Euch jemals in Teldrassil wiederfinden, geht zum Tempel des Mondes im Herzen von Darnassus. Dort werdet Ihr meine Hohepriesterin vorfinden, Tyrande Whisperwind. Der Ring wird sie wissen lassen, dass es uns gut geht, und Eure Geschichte untermauern.$B$BWir beide danken Euch, $N.",objectives={"Bringt Jer’kais Siegelring zu Hohepriesterin Tyrande Whisperwind nach Darnassus."}]])
R(2973,"Schimmer für einen neuen Umhang",[[description="Grüße, $C. Ich bin mit meinen Gefährten auf einer Mission für unsere Meister aus Orgrimmar hinunter nach Feralas gereist.$B$BMeine Lebensgefährtin Korrin liebt neue Kleider und daher habe ich vor, ihr einen neuen Umhang zu fertigen, der mit den hauchzarten Flügeln von Feendrachen geschmückt ist. Seid Ihr vielleicht in der Lage, mir zu helfen? Grimmlingflitzer mit prachtvollen Flügeln, wie ich sie will, gibt es westlich vom Camp Mojache.",objectives={"Bringt 10 regenbogenfarbene Grimmlingflitzerflügel zu Krueg Skullsplitter nach Camp Mojache."}]])
R(2974,"Eine grausige Entdeckung",[[description="Was!? Ihr seid in dieser Gegend auf Tauren getroffen? Ihr macht Witze! Wie sahen sie aus?$B$BDer Grimmtotemklan! Ihr habt einige von denen gefunden? Belgrom, einer unserer Meister, interessiert sich für diese Sippe... Er hat sogar ein Kopfgeld auf sie ausgesetzt.$B$BIhr müsst wieder zurückgehen, $C. Geht zurück und bringt mir ihre Hörner... haufenweise, wenn Ihr könnt. Mit den Grimmtotem ist nicht zu spaßen und man sollte sie nicht unterschätzen. Geht zurück und erschlagt sie; lasst die Flüsse in Feralas rot werden von ihrem dunklen Blut.",objectives={"Bringt 20 Grimmtotemhörner zu Krueg Skullsplitter nach Camp Mojache."}]])
R(2975,"Die Oger von Feralas",[[description="Der Einfluss des Ogerstamms der Gordunni sind in diesem Gebiet kaum zu übersehen. Schaut Euch mal um, $N. Seine bloße Anwesenheit zeichnet das Land. Wir müssen die Gordunni zurückdrängen, bevor sie sich weiter nach Feralas hinein ausbreiten können.$B$BFolgt dem Fluss nach Norden und Ihr werdet ihren Außenposten finden. Verringert ihre Zahl, $N. Wir müssen ihnen klar machen, dass ihre Art hier nicht willkommen ist.",objectives={"Rok Orhan im Camp Mojache will, dass Ihr 10 Oger der Gordunni, 10 Magier der Gordunni und 5 Schläger der Gordunni tötet."}]])
R(2976,"Eine grausige Entdeckung",[[description="Was?!$B$BHm, ich hab wohl wirklich ein Kopfgeld erwähnt, nicht wahr? Gut, das wird mich lehren, meinen Mund nicht zu weit aufzureißen, oder?$B$BIhr habt die Arbeit gemacht, also ist es wohl nur fair, wenn Ihr den größten Lohn einheimst. Nehmt die Hörner, ich lasse sie für Euch in eine Kiste packen. Findet Belgrom Rockmaul im Tal der Ehre. Er wird wissen wollen, was Ihr gesehen habt, und Euch für Eure harte Arbeit belohnen.$B$BMacht es gut, $C, und danke noch einmal für alles, was Ihr getan habt.",objectives={"Bringt die Kiste mit Grimmtotemhörnern zu Belgrom Rockmaul nach Orgrimmar."}]])
R(2977,"Rückkehr nach Ironforge",[[description="Ihr greift erneut auf den Sockel zu und die Platinscheiben erscheinen plötzlich wieder in Eurem Rucksack.$B$BNachdem Ihr das Wissen des Steinbehüters verinnerlicht habt und die Scheiben wieder in Eurem Besitz sind, ist es jetzt an der Zeit, nach Ironforge zurückzukehren und die Forscherliga von Eurer Entdeckung in Kenntnis zu setzen.",objectives={"Sprecht mit Historiker Karnik in Ironforge."}]])
R(2978,"Die Gordunnischriftrolle",[[description="Ihr hebt die verschmutzte Schriftrolle auf und bemerkt, dass sie eine Art Versammlung oder Zermonie darstellt. Rok Orhan wird sich für diese Schriftrolle, und was sie für die Gordunni bedeutet, interessieren.",objectives={"Bringt die Gordunnischriftrolle zu Rok Orhan ins Camp Mojache."}]])
R(2979,"Dunkle Zeremonie",[[description="Dies scheinen Pläne für eine Art dunkle Zeremonie zu sein, $n. Soweit ich das erkennen kann, wird dieses Ritual von den Magierlords der Gordunni ausgeführt.$B$BFindet einen dieser Magierlords und sammelt eine Kugel von ihm.$B$BDie Kugel eines Magiers enthält große Macht und wird uns dabei helfen, mehr über diese Zeremonie und die Magie, die die Gordunni beherrschen, herauszufinden.",objectives={"Rok Orhan im Camp Mojache will, dass Ihr eine Gordunnikugel findet."}]])
R(2980,"Die Oger von Feralas",[[description="Jetzt, da Ihr bewiesen habt, dass Ihr ein wahrer Kämpfer seid, vertraue ich darauf, dass Ihr den Mut besitzt, mit der vorliegenden Aufgabe weiterzumachen.$B$BReist in die Obere Wildnis südwestlich von hier. Dort gibt es einige verlassene und zerstörte Gebäude auf dem Land, das einst den Nachtelfen gehörte. Sucht nach diesen Ruinen, und wenn Ihr verwelkte Bäume und entweihtes Gelände seht, dann werdet Ihr die Gordunni finden. Drängt sie zurück.$B$BDiese Oger sind viel stärker als diejenigen, denen Ihr bisher entgegengetreten seid, $n. Seht Euch vor.",objectives={"Rok Orhan im Camp Mojache will, dass Ihr 10 Schamanen der Gordunni, 10 Hexenmeister der Gordunni und 5 Raufer der Gordunni tötet."}]])
R(2981,"Eine Bedrohung in Feralas",[[description="Feralas ist der ideale Ort für jemanden mit Eurer Erfahrung, $C, der sich selbst beweisen will. Ein Stamm von Ogern, die sich Gordunni nennen, ist die vorherrschende Militärmacht dort, und ihre Zahl wächst. Sie müssen aufgehalten werden, bevor sie unsere Anwesenheit in Feralas bedrohen.$B$BEine mir bekannte Kriegerin mit Namen Rok Orhan lebt im Camp Mojache in Feralas; geht zu ihr. Sie wird Euch mehr über die Situation erzählen, wenn Ihr dort ankommt.",objectives={"Belgrom Rockmaul will, dass Ihr mit Rok Orhan im Camp Mojache sprecht."}]])
R(2982,"Die obere Wildnis",[[description="Obwohl es gefährlich ist, haben Troyas und ich die Ruinen erforscht, die in den Wäldern von Feralas zu finden sind.$B$BIn jüngster Zeit ist Troyas jedoch oft allein in die Obere Wildnis gegangen und ich mache mir Sorgen um ihn. Die Oger der Gordunni haben dieses Gebiet besetzt und sie reagieren nicht sehr freundlich auf jemanden, der ihr Territorium betritt.$B$BIch hoffte, dass Ihr vielleicht zu den Ruinen im Südosten reisen und einige der Oger beseitigen würdet. Macht es ein wenig sicherer für meinen Troyas und ich werde Euch sehr dankbar sein.",objectives={"Angelas Moonbreeze will, dass Ihr 8 Hexenmeister der Gordunni, 8 Schamanen der Gordunni und 8 Schläger der Gordunni tötet."}]])
R(2983,"Ruf des Feuers",[[description="Es ist eine Weile her, seit Ihr zuletzt geprüft wurdet, $N. Ihr wart in Euren Studien bisher sehr geduldig, doch es ist an der Zeit, dass Ihr etwas über größere Mächte erlernt... Es ist an der Zeit, dass Ihr wahre Macht erfahrt. Das Element des Feuers ist Euer, wenn Ihr bereit seid, dafür zu bezahlen.$B$BSucht nach Kranal Fiss im Brachland. Er lebt in einer kleinen Siedlung nördlich von Crossroads, aber gebt Acht... wenn Ihr das Land der Nachtelfen erreicht, seid Ihr zu weit gegangen.",objectives={"Sucht Kranal Fiss im Brachland."}]])
R(2984,"Ruf des Feuers",[[description="Es ist lange her, seit Ihr zuletzt geprüft wurdet, $N. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über Zerstörung zu lernen... und über Chaos. Ihr könnt das Element des Feuers verstehen lernen, wenn Ihr bereit seid, dafür zu bezahlen.$B$BSucht nach Kranal Fiss im Brachland. Er lebt in einer kleinen Siedlung nördlich von Crossroads, aber gebt Acht, wenn Ihr das Land der Nachtelfen erreicht, seid Ihr zu weit gegangen.",objectives={"Sucht Kranal Fiss im Brachland."}]])
R(2985,"Ruf des Wassers",[[description="Ihr seht aus, als wäret Ihr bereit für die nächste Prüfung, $N. Ihr wart bislang geduldig in Euren Studien, doch die Zeit ist gekommen, da Ihr mehr erlernen müsst. Die Zeit ist gekommen, mehr über die Reinheit des Wassers zu erlernen.$B$BSucht nach Islen Waterseer im Brachland. Sie befindet sich an der Ostküste, südlich von Ratchet und dem Südstrom. Ihr findet sie in ihrer Angelhütte. Viel Glück, $N.",objectives={"Sucht Islen Waterseer im Brachland."}]])
R(2986,"Ruf des Wassers",[[description="Es ist lange her, seit Ihr zuletzt geprüft wurdet, $N. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über die Reinheit des Wassers zu lernen.$B$BSucht nach Islen Waterseer im Brachland. Sie befindet sich an der Ostküste, südlich von Ratchet und dem Südstrom. Ihr findet sie in ihrer Fischerhütte. Viel Glück, $N.",objectives={"Sucht Islen Waterseer im Brachland."}]])
R(2987,"Gordunnikobalt",[[description="Ich bin gerade erst hier in Feralas angekommen und habe gehört, dass die Oger der Gordunni, die die Wildnis hier bewohnen, einige interessante Mineralien besitzen. Keiner weiß, was die so vorhaben, aber sie passen höllisch gut auf dieses Zeug auf! Sie lassen es nicht einfach herumliegen. Oh nein, sie vergraben es, damit Leute wie ich es nicht in die Finger bekommen.$B$BWenn Ihr wollt, gebe ich Euch meine Schaufel. Geht zum Außenposten der Gordunni nördlich von hier und grabt mir etwas Gordunnikobalt aus. Haltet nach blauem Glühen Ausschau und fangt dann dort an zu graben!",objectives={"Orwin Gizzmick im Camp Mojache will 12 Proben Gordunnikobalt."}]])
R(2988,"Käfige der Witherbark",[[description="Der Sohn unseres mächtigsten Greifen ist verschwunden! Sturmschwinges Erbe, Scharfschnabel, ging vor ein paar Tagen bei der Jagd mit seinen Eltern verloren und wir glauben, dass die Trolle ihn geschnappt haben.$B$BIhr müsst uns helfen! Durchsucht die Käfige in den beiden Dörfern der Witherbarktrolle, um herauszufinden, ob Scharfschnabel dort ist.",objectives={"Durchsucht die Käfige in den beiden Dörfern der Witherbark und kehrt dann zu Greifenmeister Talonaxe zurück."}]])
R(2989,"Der Altar von Zul",[[description="Scharfschnabel war nicht bei den Witherbarktrollen. Vielleicht haben ihn die Vilebranchtrolle geholt. Geht zum Altar von Zul am Westrand des Territoriums der Vilebranch und sucht nach dem Greifenjungen.",objectives={"Überprüft die Oberfläche des Altars von Zul und kehrt dann zu Greifenmeister Talonaxe zurück."}]])
R(2990,"Thadius Grimshade",[[description="Bringt diese Feder zum Rutengänger Thadius Grimshade. Er verließ vor Jahren Aerie Peak, um sich dunklerem Wissen zuzuwenden, aber in seinem Herzen ist er immer noch ein Wildhammer!$B$BUnd vielleicht können uns seine Talente dabei helfen, Scharfschnabel zu finden.$B$BDiese Feder stammt aus dem Nest, in dem das Greifenjunge schläft. Wenn Ihr sie Thadius gebt, kann er mit etwas Glück seine Rutengangmagie verwenden, um Scharfschnabel zu finden.$B$BViel Glück, $N. Ihr werdet Thadius in den verwüsteten Landen finden, im Magierturm der Burg Nethergarde.",objectives={"Bringt Scharfschnabels Feder zu Thadius Grimshade in die verwüsteten Lande."}]])
R(2991,"Nekrums Medaillon",[[description="Ich werde herausfinden, wo Euer Greif ist, aber erst müsst Ihr etwas für mich tun. Es gibt da einen Troll in Zul'Farrak, Nekrum der Ausweider, der ein Medaillon besitzt, das ich wirklich gern studieren würde. Bringt mir das Medaillon und ich werde meine Kräfte dafür verwenden, Scharfschnabel zu finden.$B$BZul’Farrak ist jenseits des Ozeans, im Westen, in der Wüste von Tanaris.",objectives={"Bringt Thadius Grimshade in den verwüsteten Landen Nekrums Medaillon."}]])
R(2992,"Der Rutengang",[[description="Lasst mir etwas Platz, während ich ein Rutengangritual durchführe. Ich werde die Verbindung zwischen der Feder, die Ihr mir gebracht habt, und ihrem Besitzer herstellen und dann selbst dieser Verbindung zu Scharfschnabel folgen.$B$BZumindest... wenn alles nach Plan verläuft. Wenn nicht, nun... dann schließt Ihr besser die Augen.",objectives={"Wartet, bis Grimshade das Rutengangritual durchgeführt hat."}]])
R(2993,"Rückkehr ins Hinterland",[[description="Scharfschnabel wird in einem Käfig hoch oben auf einer Klippe am Gipfel des Jintha’Alor im Hinterland gefangen gehalten. Der Schlüssel zu diesem Käfig ist im Besitz der Hohepriesterin der Vilebranchtrolle, der üblen Priesterin Hexx.$B$BDa. Ich habe meinen Teil erfüllt. Ich wünsche Euch Glück, $N.",objectives={"Sprecht mit Greifenmeister Talonaxe."}]])
R(2994,"Scharfschnabels Rettung",[[description="Wir müssen Scharfschnabel retten!$B$BKämpft Euch bis zum Gipfel von Jintha’Alor im Herzen des Vilebranchterritoriums vor, holt Euch den Schlüssel zu Scharfschnabels Käfig von der üblen Priesterin Hexx und dann sucht und befreit Scharfschnabel.",objectives={"Kämpft Euch bis zum Gipfel von Jintha’Alor durch, tötet die üble Priesterin Hexx, um an den Schlüssel zu Scharfschnabels Käfig zu kommen, und rettet Scharfschnabel."}]])
R(2995,"Nachrichtenwege",[[description="Die Quel'Danil-Hütte ist ein Zentrum der Kommunikation für die Hochelfen des Hinterlands. Ihre Botschafter sind damit beschäftigt, Beziehungen zu anderen Völkern zu knüpfen, mit denen sie ihr Wissen über die Trolle der Witherbark teilen, die das Gebiet im südlichen Hinterland bewohnen. Alle Aufzeichnungen betreffs dieses Nachrichtenaustauschs werden in der Hütte aufbewahrt.$B$BWir können es nicht brauchen, wenn die Hochtalelfen Allianzen mit anderen schließen, $N.$B$BVernichtet die Hochtaldokumente. Wir müssen ihre Nachrichtenwege niederbrennen... im wahrsten Sinne des Wortes.",objectives={"Oran Snakewrithe in Undercity will, dass Ihr ins Hinterland reist und die Hochtalaufzeichnungen, Hochtalberichte und Hochtalnotizen verbrennt."}]])
R(2996,"Die Suche nach Strahad",[[description="Ich habe Euch in der Vergangenheit viele Fertigkeiten beigebracht, aber es ist an der Zeit, dass Euch ein anderer lehrt. Er lebt in Ratchet und sein Name ist Strahad. Er ist ein Mensch, aber lasst Euch deswegen nicht dazu hinreißen, ihn für schwach zu halten. Er mag klein sein, aber er ist auch mächtig. Er kann Euch mächtigere Beschwörungen lehren - ich fühle, dass Ihr dazu bereit seid. Geht nun zu ihm. Er ist in Ratchet... Über der Hafenstadt gleich bei seinem Turm.",objectives={"Sprecht mit Strahad Farsan in Ratchet."}]])
R(2997,"Foliant der Offenbarung",[[description="Hallo, $N. Ich weiß, Ihr seid damit beschäftigt, den Leuten von Dun Morogh zu helfen, aber wenn Ihr etwas Zeit habt, könntet Ihr Euch auf den Weg nach Ironforge hinauf machen, um mit einer unserer am meisten Respektierten zu reden: Tiza Battleforge. Zu ihr kommen die jüngeren Paladine, wenn es an der Zeit für sie ist, mehr über das Licht und darüber zu erfahren, was von einem erwartet wird.$B$BIhr könnt sie oben in der Halle der Mysterien finden. Falls Ihr noch nie dort wart, das ist im Mystikerviertel. Viel Glück, $N.",objectives={"Sprecht mit Tiza Battleforge in Ironforge."}]])
R(2998,"Foliant der Offenbarung",[[description="Seid gegrüßt, $GBruder:Schwester;. Duthorian Rall, einer unserer einflussreichsten Paladine, hat kürzlich von Euch gesprochen. Ich habe mitbekommen, wie er darüber sprach, dass es an der Zeit sei, dass Ihr ein wenig getestet würdet... Dabei fielen auch einige Komplimente darüber, wie gut Ihr bisher abgeschnitten habt.$B$BWenn ich Ihr wäre, würde ich nach Stormwind gehen und mit ihm sprechen, sobald Ihr Zeit habt. Ich bin sicher, er ist in der Kathedrale des Lichts - dort verbringt er einen Großteil seiner Zeit.",objectives={"Sprecht mit Duthorian Rall in Stormwind."}]])
R(2999,"Foliant der Offenbarung",[[description="Hallo, $N. Ich weiß, Ihr seid damit beschäftigt, den Leuten von Dun Morogh zu helfen, aber wenn Ihr etwas Zeit habt, könntet Ihr nach oben gehen, um mit einer unserer am meisten Respektierten zu reden: Tiza Battleforge. Zu ihr kommen die jüngeren Paladine, wenn es an der Zeit für sie ist, mehr über das Licht und darüber zu erfahren, was von einem erwartet wird.",objectives={"Sprecht mit Tiza Battleforge in Ironforge."}]])
R(3000,"Foliant der Offenbarung",[[description="Hallo, $N. Ich weiß, Ihr seid damit beschäftigt, den Völkern Azeroths zu helfen, aber wenn Ihr etwas Zeit habt, solltet Ihr nach Ironforge zurückkehren, um mit einem der am meisten respektierten Paladine Eurer Heimat zu reden: Tiza Battleforge. Zu ihr kommen die jüngeren Zwergen-Paladine, wenn es an der Zeit für sie ist, mehr über das Licht und darüber zu erfahren, was von uns allen erwartet wird.$B$BIhr findet sie im Obergeschoss der Halle der Mysterien, die sich im Mystikerviertel befindet.",objectives={"Sprecht mit Tiza Battleforge in Ironforge."}]])
R(3001,"Die Suche nach Strahad",[[description="Ich habe Euch in der Vergangenheit viele Fertigkeiten beigebracht, aber es ist an der Zeit, dass Euch ein anderer lehrt. Er lebt in Ratchet und sein Name ist Strahad. Er ist ein Mensch, aber lasst Euch deswegen nicht dazu hinreißen, ihn für schwach zu halten oder als Euren Feind anzusehen - zumindest vorerst. Er ist mächtig und sollte respektiert werden. Er kann Euch große Beschwörungen lehren, Beschwörungen, für die Ihr, glaube ich, bereit seid. Geht nun zu ihm.$B$BEr ist in Ratchet... Über der Hafenstadt, gleich bei dem Turm dort.",objectives={"Findet Strahad Farsan in Ratchet."}]])
R(3002,"Die Gordunnikugel",[[description="Obwohl ich meinen Feind genau kenne, bin ich ein Krieger, $n. Ich kann Euch nicht sagen, über welche Fähigkeiten diese Kugel verfügt.$B$BIch kenne einen Magier in Orgrimmar, der uns mehr über die Kugel sagen können wird. Bringt sie zu ihm.",objectives={"Bringt die Gordunnikugel zu Uthel’nay in die Dunkeldornen-Lodge in Orgrimmar."}]])
R(3022,"Vorsichtig behandeln",[[description="$N, ich sehe deutlich, dass Ihr Euch liebend gern meiner noblen Sache zuwenden möchtet. Ja, natürlich könnt Ihr etwas für mich tun!$B$BBringt diese Kiste mit Eiern zu Erelas Ambersky. Das ist ein Druide, der sich um diese Eier kümmert. Er bebrütet sie und bildet dann die jungen Hippogryphe aus. Ihr findet ihn in Teldrassil, in einem kleinen Dorf im Süden namens Rut'theran.",objectives={"Bringt die sorgfältig verpackte Kiste zu Erelas Ambersky in das Dorf Rut'theran."}]])
R(3042,"Trollaushärter",[[description="Die Trolle der Sandfury von Zul'Farrak stellen ein Aushärtungsmittel aus Sandstein her, und ich kann dies verwenden, um die von mir hergestellten Waren auszuhärten, ja, so ist es! Von Kennern wird es hoch gepriesen; wenn Ihr mir also einen guten Vorrat dieses Härters bringt, werde ich Euch reich belohnen.$B$BZul'Farrak liegt nordwestlich von Gadgetzan. Viel Glück.",objectives={"Bringt 20 Phiolen Trollaushärter zu Trenton Lighthammer in Gadgetzan."}]])
R(3062,"Dunkles Herz",[[description="Edana Hasskralle ist die Königin der Nordschwingen, die in den Ruinen im Westen zu Hause sind. Sie ist das vollkommen Böse; ich habe gehört, dass sie ein Herz aus Kristall hat. Sie ist bar jeglicher Emotionen außer dem Hass, den sie für alle anderen fühlt. Ihr müsst Euch Edana stellen und mir ihr dunkles Herz zurückbringen.$B$BIch habe von einem Horn gehört, das die Harpyien tragen - wenn es bei den Hasskrallensteinen, im nördlichen Teil der Ruinen, geblasen wird, wird die Königin beschworen.$B$BStellt Euch ihre Überraschung vor, wenn es nicht die ihren sind, die auf sie warten, sondern ihr Tod.",objectives={"Talo Thornhoof im Camp Mojache will das dunkle Herz von Edana Hasskralle."}]])
R(3063,"Rache an den Nordschwingen",[[description="Zu meiner Zeit war ich ein erfahrener Jäger. Es gab keine Kreatur, die ich fürchtete. Bis...$B$BIch war draußen im Wald, um nach einem heftigen Kampf meine Klinge zu schärfen, als ich in einen Hinterhalt geriet. Harpyien umzingelten mich, und ich schaffte es kaum, mich in Sicherheit zu bringen.$B$BSelbst heute noch kann ich das Echo ihrer Schreie vernehmen...$B$BDanach war ich nicht mehr derselbe. Aber der Hass kocht in meinem Inneren - ich will Rache, auch noch nach all diesen Jahren.$B$BDie Harpyien der Nordschwingen leben westlich von hier. $n, rächt mich.",objectives={"Talo Thornhoof möchte, dass Ihr 4 Harpyien der Nordschwingen, 4 Wildfedern der Nordschwingen, 4 Windruferinnen der Nordschwingen und 4 Töter der Nordschwingen erschlagt."}]])
R(3064,"<NYI> <TXT> Pirate Hats",[[description="I need pirate hats for my shop.  Get me lots!",objectives={"Bring 20 Untorn Pirate Hats to Yorba Screwspigot."}]])
R(3065,"Einfache Schrifttafel",[[description="Ah, während Ihr fort wart, kam ein Pergament für Euch, $n.$B$BLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es vom Kriegerlehrer Frang. Er würde gern mit Euch sprechen, wenn Ihr bereit seid. Ihr findet ihn außerhalb des Höhlenbaus, wo er sich in den Schatten verbirgt.",objectives={"Lest die einfache Schrifttafel und sprecht mit Frang im Tal der Prüfungen."}]])
R(3082,"Geätzte Schrifttafel",[[description="Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, $n.$B$BLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie von der Jägerlehrerin Jen'shan. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.",objectives={"Sprecht mit Jen'shan im Tal der Prüfungen."}]])
R(3083,"Verschlüsselte Schrifttafel",[[description="Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, $n.$B$BLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie vom Schurkenlehrer Rwag. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.",objectives={"Lest die verschlüsselte Schrifttafel und sprecht mit Rwag im Tal der Prüfungen."}]])
R(3084,"Mit Runen beschriftete Schrifttafel",[[description="Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, $n.$B$BLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie von der Schamanenlehrerin Shikrik. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.",objectives={"Sprecht mit Shikrik im Tal der Prüfungen."}]])
R(3085,"Geheiligte Schrifttafel",[[description="Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, $n.$B$BLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie vom Priesterlehrer Ken'jai. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.",objectives={"Lest die geheiligte Schrifttafel und sprecht mit Ken'jai außerhalb des Höhlenbaus im Tal der Prüfungen."}]])
R(3086,"Glyphen-Schrifttafel",[[description="Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, $n.$B$BLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie von der Magierlehrerin Mai'ah. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.",objectives={"Lest die mit Glyphen versehene Schrifttafel und sprecht mit Mai'ah beim Eingang zum Höhlenbau im Tal der Prüfungen."}]])
R(3087,"Geätztes Pergament",[[description="Ah, während Ihr fort wart, kam ein Pergament für Euch, $N.$B$BLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von der Jägerlehrerin Jen'shan. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.",objectives={"Lest das geätzte Pergament und sprecht mit Jen'shan im Tal der Prüfungen."}]])
R(3088,"Verschlüsseltes Pergament",[[description="Ah, während Ihr fort wart, kam ein Pergament für Euch, $n.$B$BLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es vom Schurkenlehrer Rwag. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.",objectives={"Lest das verschlüsselte Pergament und sprecht mit Rwag im Tal der Prüfungen."}]])
R(3089,"Mit Runen beschriftetes Pergament",[[description="Ah, während Ihr fort wart, kam ein Pergament für Euch, $n.$B$BLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von der Schamanenlehrerin Shikrik. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.",objectives={"Lest das mit Runen beschriebene Pergament und sprecht mit Shikrik im Tal der Prüfungen."}]])
R(3090,"Besudeltes Pergament",[[description="Ah, während Ihr fort wart, kam ein Pergament für Euch, $n.$B$BIch versuche normalerweise, jedweden Kontakt mit Hexenmeistern zu vermeiden, aber ich glaube, Ihr solltet es lesen, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von Eurem neuen Lehrer Nartok. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.",objectives={"Lest das besudelte Pergament und sprecht mit Nartok im Höhlenbau im Tal der Prüfungen."}]])
R(3091,"Einfache Notiz",[[description="Gerade eben fragte eine Botin nach Euch, $n. Ich glaube, sie wurde vom Kriegerlehrer Harutt geschickt. Wenn diese Nachricht von Harutt ist, würde ich sie schnellstens lesen.",objectives={"Lest die einfache Nachricht und sprecht mit Harutt Thunderhorn im Camp Narache."}]])
R(3092,"Geätzte Notiz",[[description="Gerade eben fragte eine Botin nach Euch, $n. Ich glaube, sie wurde vom Jägerlehrer Lanka geschickt. Wenn diese Nachricht von Lanka ist, würde ich sie schnellstens lesen.",objectives={"Lest die geätzte Nachricht und sprecht mit Lanka Farshot in Red Cloud Mesa."}]])
R(3093,"Mit Runen beschriftete Notiz",[[description="Gerade eben fragte eine Botin nach Euch, $n. Ich glaube, sie wurde von der Schamanenlehrerin Meela geschickt. Wenn diese Nachricht von Meela ist, würde ich sie schnellstens lesen.",objectives={"Lest die mit Runen beschriftete Nachricht und sprecht mit Meela Dawnstrider im Camp Narache."}]])
R(3094,"Tiefgrüne Notiz",[[description="Gerade eben fragte eine Botin nach Euch, $n. Ich glaube, sie wurde vom Druidenlehrer Gart geschickt. Wenn diese Nachricht von Gart ist, würde ich sie schnellstens lesen.",objectives={"Lest die tiefgrüne Notiz und sprecht mit Gart Mistrunner im Camp Narache."}]])
R(3095,"Einfache Rolle",[[description="Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Kriegerlehrers Dannal zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.",objectives={"Lest die einfache Schriftrolle und sprecht mit Dannal Stern in Deathknell."}]])
R(3096,"Verschlüsselte Rolle",[[description="Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Schurkenlehrers David Trias zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.",objectives={"Lest die verschlüsselte Schriftrolle und sprecht mit David Trias in Deathknell."}]])
R(3097,"Geheiligte Rolle",[[description="Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Priesterlehrers Duesten zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.",objectives={"Lest die geheiligte Schriftrolle und sprecht mit dem dunklen Kleriker Duesten in der Kirche von Deathknell."}]])
R(3098,"Glyphen-Rolle",[[description="Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel der Magielehrerin Isabella zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.",objectives={"Lest die mit Glyphen versehene Schriftrolle und sprecht mit Isabella in der Kirche von Deathknell."}]])
R(3099,"Besudelte Rolle",[[description="Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Hexenmeisterlehrers Maximillion zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.",objectives={"Lest die besudelte Schriftrolle und sprecht mit Maximillion in Deathknell."}]])
R(3100,"Einfacher Brief",[[description="Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, $N. Es scheint sich um einen versiegelten Brief mit den Insignien von Llane, unserem örtlichen Kriegerlehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.",objectives={"Lest den einfachen Brief und sprecht mit Llane Beshere in der Abtei von Nordhain."}]])
R(3101,"Geweihter Brief",[[description="Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, $N. Es scheint sich um einen versiegelten Brief mit den Insignien von Bruder Sammuel, unserem örtlichen Paladinlehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.",objectives={"Lest den geweihten Brief und sprecht mit Bruder Sammuel in der Abtei von Nordhain."}]])
R(3102,"Verschlüsselter Brief",[[description="Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, $N. Es scheint sich um einen versiegelten Brief mit den Insignien von Jorik, einem unserer örtlichen Lehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.",objectives={"Lest den verschlüsselten Brief und sprecht mit Jorik Kerridan im Stall hinter der Abtei von Nordhain."}]])
R(3103,"Geheiligter Brief",[[description="Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, $N. Es scheint sich um einen versiegelten Brief mit den Insignien der Priesterin Anetta, unserer örtlichen Priesterlehrerin, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.",objectives={"Lest den geheiligten Brief und sprecht mit Priesterin Anetta in der Abtei von Nordhain."}]])
R(3104,"Glyphen-Brief",[[description="Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, $N. Es scheint sich um einen versiegelten Brief mit den Insignien von Kheldon, unserem örtlichen Magierlehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.",objectives={"Lest den mit Glyphen versehenen Brief und sprecht mit Kheldon Bremen in der Abtei von Nordhain."}]])
R(3105,"Besudelter Brief",[[description="Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, $N. Es scheint sich um einen versiegelten Brief mit den Insignien von Drusilla, einer unserer örtlichen Lehrerinnen, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.",objectives={"Lest den besudelten Brief und sprecht mit Drusilla La Salle nahe der Abtei von Nordhain."}]])
R(3106,"Einfache Rune",[[description="Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Kriegerlehrer Thran. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.",objectives={"Lest die einfache Rune und sprecht mit Thran Khorman im Coldridgetal."}]])
R(3107,"Geweihte Rune",[[description="Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Paladinlehrer Bromos. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.",objectives={"Lest die geweihte Rune und sprecht mit Bromos Grummner im Coldridgetal."}]])
R(3108,"Geätzte Rune",[[description="Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Jägerlehrer Thorgas. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.",objectives={"Lest die geätzte Rune und sprecht mit Thorgas Grimson im Coldridgetal."}]])
R(3109,"Verschlüsselte Rune",[[description="Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Schurkenlehrer Solm. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.",objectives={"Lest die verschlüsselte Rune und sprecht mit Solm Hargrin im Coldridgetal."}]])
R(3110,"Geheiligte Rune",[[description="Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Priesterlehrer Branstock. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.",objectives={"Lest die geheiligte Rune und sprecht mit Branstock Khalder in Anvilmar."}]])
R(3111,"Glyphic Rune",[[description="Long ago high elves taught us the secrets of magic along with our human allies. They preached to us about rules and how magic can make ya go mad! But don't believe it. We're not like the elves; we don't have the same weaknesses. Just keep yourself on the right path and you'll find magic is as powerful a tool as it is a weapon.$B$BWhen you're ready, come find me inside Anvilmar. I'll be waiting for ya!",objectives={"Speak to Marryk Nurribit inside Anvilmar."}]])
R(3112,"Einfaches Memorandum",[[description="Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Kriegerlehrer Thran. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.",objectives={"Lest das einfache Memorandum und sprecht mit Thran Khorman im Coldridgetal."}]])
R(3113,"Verschlüsseltes Memorandum",[[description="Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Schurkenlehrer Solm. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.",objectives={"Lest das verschlüsselte Memorandum und sprecht mit Solm Hargrin im Coldridgetal."}]])
R(3114,"Glyphen-Memorandum",[[description="Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Magielehrer Marryk. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.",objectives={"Lest das mit Glyphen versehene Memorandum und sprecht mit Marryk Nurribit in Anvilmar oberhalb des Coldridgetals."}]])
R(3115,"Besudeltes Memorandum",[[description="Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Hexenmeisterlehrer Alamar. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.$B$BUnd passt auf Euch auf, $N, man traut Leuten wie Euch hierzulande nicht gerade.",objectives={"Lest das besudelte Memorandum und sprecht mit Alamar Grimm in Anvilmar oberhalb des Coldridgetals."}]])
R(3116,"Einfaches Siegelzeichen",[[description="Dieses Siegelzeichen wurde mir durch einen Boten von unserer Kriegerlehrerin Alyissia überreicht. Es sieht so aus, als wollte Alyissia ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.",objectives={"Lest das einfache Siegelzeichen und sprecht mit Alyissia in Shadowglen."}]])
R(3117,"Geätztes Siegelzeichen",[[description="Dieses Siegelzeichen  wurde mir durch einen Boten von unserer Jägerlehrerin Ayanna überreicht. Es sieht so aus, als wollte Ayanna ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.",objectives={"Lest das geätzte Siegelzeichen und sprecht mit Ayanna Everstride oben auf Aldrassil in Shadowglen."}]])
R(3118,"Verschlüsselte Siegelzeichen",[[description="Dieses Siegelzeichen wurde mir durch einen Boten von unserer Schurkenlehrerin Frahun überreicht. Es sieht so aus, als wollte Frahun ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.",objectives={"Lest das verschlüsselte Siegelzeichen und sprecht mit Frahun Shadwhisper in Shadowglen."}]])
R(3119,"Geheiligtes Siegelzeichen",[[description="Dieses Siegelzeichen wurde mir durch einen Boten von unserer Priesterlehrerin Shanda überreicht. Es sieht so aus, als wollte Shanda ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.",objectives={"Lest das geheiligte Siegel und sprecht mit Shanda in Aldrassil."}]])
R(3120,"Tiefgrünes Siegelzeichen",[[description="Dieses Siegelzeichen wurde mir durch einen Boten von unserem Druidenlehrer Mardant überreicht. Es sieht so aus, als wollte Mardant ein paar Worte mit Euch wechseln, wenn Ihr einen Moment Zeit habt. Lest es und bringt es dann zu ihm.",objectives={"Lest das tiefgrüne Siegel und sprecht mit Mardant Strongoak im großen Baum Aldrassil in Shadowglen."}]])
R(3121,"Eine seltsame Anforderung",[[description="Neeru Fireblade in Orgrimmar hat, was ich brauche, um hier beginnen zu können! Er hat ein Gebräu zusammengemischt, das ich für mein... na, Ihr werdet es schon sehen.$B$BAb mit Euch... nach Orgrimmar. Hier, nehmt das mit. Es ist ein Schrumpfkopf, den ich Neeru im Tausch für die Kräuter versprochen habe. Es ist der Kopf eines armen Zwergs, der mir im Wald über den Weg gelaufen ist. Ich bin sicher, dass Neeru sehr erfreut sein wird.$B$BIhr werdet Neeru in der Kluft der Schatten finden.",objectives={"Bringt den Schrumpfkopf zu Neeru Fireblade in Orgrimmar."}]])
R(3122,"Kehrt zu Hexendoktor Uzer'i zurück",[[description="Hier sind die Kräuter, $n. Bringt sie zu Hexendoktor Uzer'i.$B$BUnd sagt ihm, dass ich mit dem Schrumpfkopf sehr zufrieden bin.",objectives={"Bringt Neerus Kräuterbeutel zu Hexendoktor Uzer'i in Feralas."}]])
R(3123,"Das Gefäß wird getestet",[[description="Dies ist ein Test, sowohl für das Ritual, das ich durchgeführt habe, als auch für Eure Fähigkeiten. Nehmt dieses Gefäß, $N. Damit habt Ihr die Macht, eine Kreatur zu schrumpfen und sie darin gefangen zu nehmen.$B$BReist ins Hinterland und sucht nach Kreaturen, die als Wildekin bekannt sind. Sie waren einst die Tiere der Nachtelfengöttin Elune. Die heimtückischen, primitiven oder wilden Eulenbestien sollen Euer Ziel sein, $N. Vernichtet 10 und benutzt dann das Muisekgefäß, um sie zu schrumpfen und einzufangen, bevor ihr Geist flüchten kann.",objectives={"Reist ins Hinterland und spürt die Wildekin auf. Schaltet 10 davon aus und benutzt dann das Muisekgefäß, um die gefallenen Wildekin zu schrumpfen und einzufangen.$B$BBringt anschließend 10 Einheiten Muisek von Wildekins und das Muisekgefäß zu Hexendoktor Uzer'i in Feralas."}]])
R(3124,"Muisek von Hippogryphen",[[description="Da Ihr bewiesen habt, dass Ihr vertrauenswürdig und auch in der Lage seid, das Muisekgefäß zu benutzen, möchte ich, dass Ihr eine weitere Kreatur einfangt.$B$BHippogryphen sind seit vielen Jahren die treuen Gefährten der Nachtelfen. Ihre Geister sind loyal und unerschütterlich.$B$BEure Aufgabe besteht darin, 10 Fransenfederhippogryphen auszuschalten, sie schnell zu schrumpfen und mit dem Gefäß einzufangen, sodass ihr Muisek erhalten bleibt. Ihr findet die Hippogryphen in der Oberen Wildnis, südlich von hier.",objectives={"Schaltet 10 Fransenfederhippogryphen eines beliebigen Typs aus und benutzt dann das Muisekgefäß, um sie zu schrumpfen und einzufangen."}]])
R(3125,"Muisek von Feendrachen",[[description="$n, als Nächstes müsst Ihr für mich eine Kreatur fangen, die vom Aussehen her sehr zerbrechlich scheint, aber ihr mächtiger Geist ist das, was wir eigentlich besitzen wollen. Die Feendrachen, von denen ich spreche, dienen den Nachtelfen als Verbündete. Wir müssen einen von ihnen einfangen, damit auch die Horde von seiner Geisteskraft profitieren kann.$B$BHier ist das Muisekgefäß, $n. Schaltet 8 Grimmlingflitzer oder Grimmlingdrachen aus und fangt ihr Muisek ein. Ihr könnt sie westlich von hier finden.",objectives={"Schaltet 8 Grimmlingflitzer oder Grimmlingdrachen aus. Benutzt das Muisekgefäß, um die gefallenen Feendrachen zu schrumpfen und einzufangen."}]])
R(3126,"Muisek von Treants",[[description="Die umherwandernden Waldgänger, die überall im Wald zu finden sind, sind unser nächstes Ziel, $n. Nachtelfen haben Treants als Verbündete rekrutiert, um gegen die Horde zu kämpfen. Sie mögen zwar langsam sein, aber als Beschützer sind sie nicht zu unterschätzen.$B$BBald werden wir diese Macht für unsere eigenen Zwecke nutzen können.$B$BFindet 3 umherwandernde Waldgänger, schaltet sie aus und benutzt das Muisekgefäß, um sie zu schrumpfen und einzufangen.",objectives={"Schaltet 3 umherwandernde Waldgänger aus. Benutzt das Muisekgefäß, um die gefallenen Treants zu schrumpfen und einzufangen."}]])
R(3127,"Muisek von Bergriesen",[[description="Bei der letzten Aufgabe, die ich Euch stelle, sollt Ihr nach Nordwesten reisen und den letzten Feind finden.$B$BAls die Brennende Legion in der Welt erschien, haben die Bergriesen ihre Berge verlassen, um den Nachtelfen zu helfen. Ihr erkennt sie an ihrer enormen Größe und daran, wie der Boden erzittert, wenn Ihr durch ihr felsiges Gelände reist.$B$BIch kann es kaum erwarten, eine Macht von dieser Größe zu zähmen. Schaltet 7 Bergriesen aus und benutzt dann das Muisekgefäß, um ihr mächtiges Muisek einzufangen.",objectives={"Schaltet 7 Landgänger oder Klippenriesen aus. Benutzt das Muisekgefäß, um die gefallenen Bergriesen zu schrumpfen und einzufangen."}]])
R(3128,"Natürliche Materialien",[[description="Ich benötige bestimmte Materialien, um mein Vorhaben zu vervollständigen... Ihr könnt das für mich erledigen, zusammen mit den anderen Aufgaben, die ich Euch stellen werde.$B$BIch brauche einen abgesplitterten Stamm eines Treants aus Feralas. Verkrustete Mineralien könnt Ihr an den Bergriesen und Feendrachen im Westen finden. Sucht mir einige widerstandsfähige Sehnen von den Eulenbestien im Hinterland oder den Hippogryphs von Feralas. Als Letztes benötige ich eine große Menge metallischer Fragmente von einer der Bestien, die ich erwähnt habe.",objectives={"Bringt 2 abgesplitterte Baumstämme, 6 verkrustete Mineralien, 20 Stücke widerstandsfähige Sehne und 40 metallische Fragmente zu Hexendoktor Uzer'i ins Camp Mojache."}]])
R(3129,"Waffen des Geistes",[[description="Es ist ein äußerst komplizierter Vorgang, die Waffen mit dem Muisek zu erfüllen. Aber da ich jetzt sowohl über alle erforderlichen Materialien als auch über das Muisek der von Euch eingefangenen Kreaturen verfüge, kann ich endlich beginnen. Bitte wartet hier, ich werde gleich zurück sein.",objectives={"Hexendoktor Uzer'i will, dass Ihr einen Moment wartet, während er die Waffen vorbereitet."}]])
R(3130,"Gegen die Hasskämme",[[description="Ich werde Euch jetzt zu meinem Stellvertreter Lactronicus schicken. Er hat bisher ein wachsames Auge auf die Nagastreitkräfte gehabt. Ich werde die allgemeine Lage hier in Bezug auf die Naga bewerten. Liebend gern würde ich eine ganze Armee gegen sie aussenden, aber es ist nicht unbedingt ratsam, die Festung einem direkten Angriff der Horde - oder Schlimmerem - schutzlos auszusetzen.$B$BWie dem auch sei, Latronicus erwartet Euch. Gute Arbeit bisher, $n. Nur weiter so.$B$BIhr könnt wegtreten.",objectives={"Meldet Euch bei Latronicus Moonspear in der Festung Feathermoon."}]])
R(3141,"Loramus",[[description="Ihr wollt also gegen Dämonen kämpfen? Dann tätet Ihr gut daran, Euch meine Geschichte anzuhören.",objectives={"Lasst Loramus Thalipedes seine Geschichte erzählen."}]])
R(3161,"Gahz'ridian",[[description="$N, ich bin zwar Wissenschaftler, aber im Grunde meines Herzens bin ich auch Schatzsucher!$B$BVor langer Zeit, als Trolle dieses Land besetzt hielten, schufen sie eine große Anzahl von Ornamenten nach dem Vorbild der Gahz'rilla, einer Hydra, die sie als Göttin verehrten. Diese Ornamente werden aus einem Element herausgeschnitzt, das ich nach der Hydragöttin \"Gahz'ridian\" nenne.$B$BIch selbst habe schon einige dieser Ornamente gefunden, aber ich hätte gern noch mehr, um sie zu untersuchen - vielleicht findet Ihr ja noch welche ...$B$BIch habe sogar einen Detektor erfunden, der es zu einem Kinderspiel macht, Gahz'ridian zu finden! Legt ihn einfach an und die Suche kann beginnen!",objectives={"Marvon Rivetseeker in Tanaris möchte, dass Ihr 30 Gahz'ridian-Ornamente sammelt."}]])
R(3181,"Das Horn der Bestie",[[description="Das gigantische Horn hat viele Kratzer und Risse. Ein ungewöhnliches Metallobjekt klemmt in der rauen Oberfläche fest.$B$BBeim näheren Hinschauen entdeckt Ihr, dass das Metall in Wirklichkeit ein zerbrochener Axtkopf ist. In das Metall wurden diese Wörter eingeätzt:$B$BEigentum von Gebirgsjägerin Pebblebitty.$B$BAls Ihr versucht, den zerbrochenen Axtkopf herauszuziehen, zerfällt er in unzählige Teile.$B$BUps!",objectives={"Bringt Margols gigantisches Horn zu Gebirgsjägerin Pebblebitty."}]])
R(3182,"Besitznachweis",[[description="Ihr erwartet wirklich, dass ich eine solche Geschichte glaube? Wenn es das echte Horn wäre, dann würde meine zerbrochene Axt ja immer noch drinstecken.$B$BHört zu, bringt diese dreiste Fälschung zu Kurator Thorius in Ironforge. Falls er Eure Behauptung bestätigt, werdet Ihr eine Beweisurkunde für Eure Tat erhalten. Bringt mir diesen Beweis und ich werde Euch den Schlüssel für die sengende Schlucht geben.$B$BGeht schon!",objectives={"Bringt Margols gigantisches Horn zu Kurator Thorius in Ironforge."}]])
R(3201,"Endlich!",[[description="Ich kann kaum glauben, dass Pebblebitty die Echtheit des Horns angezweifelt hat. Unter uns, ich denke, sie ist einfach nur eifersüchtig. Ich weiß, dass sie diese Bestie gern selbst getötet hätte, nach dem, was bei dem 'Ereignis' so vorgefallen ist.$B$BIhr braucht also eine Urkunde für Eure Tat? Nachdem Ihr nun gerade dem Museum ein solches Geschenk gemacht habt, sollte das kein Problem sein.$B$B<Kurator Thorius fängt an, ein großes Dokument auszufüllen.>$B$BHier bitte! Das könnt Ihr Pebblebitty zurückbringen.",objectives={"Bringt die Urkunde für die Tat zurück zu Gebirgsjägerin Pebblebitty."}]])
R(3221,"Sprecht mit Renferrel",[[description="Während Ihr fort wart, um unseren Todespirschern zu helfen, hat Apotheker Renferrel Euch eine Einladung geschickt. Er hat mir keinerlei Einzelheiten mitgeteilt, aber er wollte mit Euch über die Wolfherzen sprechen, die Ihr ihm gegeben habt.",objectives={"Sprecht mit Apotheker Renferrel in dem Grabmal."}]])
R(3241,"<NYI> <TXT><redux> Dreadmist Peak",[[description="Collect the totems from Dreadmist Peak, because it's icky there now and no place for shiny clean totems.",objectives={"Bring them to Tonga Runetotem."}]])
R(3261,"Jorn Skyseer",[[description="Eure Zeit bei mir ist vorbei, $N. Wenn Ihr mehr lernen wollt, müsst Ihr ins Camp Taurajo gehen und mit Jorn Skyseer sprechen. Er wird Eure Weiterbildung übernehmen.",objectives={"Sprecht im Camp Taurajo mit Jorn Skyseer."}]])
R(3281,"Gestohlenes Silber",[[description="Ihr habt zwar die Raptoren getötet, aber das Silber, das sie gestohlen haben, muss wiederbeschafft werden! Ich habe Berichte darüber, dass die Raptoren eine große Ansammlung von Nestern südlich von Ratchet haben, Raptorgründe genannt. Es ist sehr wahrscheinlich, dass sie unser gestohlenes Silber dorthin gebracht haben.$B$BGeht zu dieser Raptorzuflucht und haltet nach dem gestohlenen Silber Ausschau. Wenn Ihr es gefunden habt, kommt damit zu mir zurück.",objectives={"Bringt das gestohlene Silber zu Gazrog in Crossroads."}]])
R(3301,"Mura Runetotem",[[description="Meine Klangefährtin, Mura Runetotem, ist nach Silberwald gereist, um unseren untoten Verbündeten zu helfen. Der Silberwald ist ein kranker Wald, ein sterbender Wald, und Muras Hoffnung war, ihm neues Leben zu bringen. Vielleicht kann dieses seltsame Leben, das wir im Brachland gefunden haben, ihr bei ihrer Arbeit im Silberwald helfen.$B$BBringt eine Probe der von Euch gesammelten Schalen zu Mura nach Silberwald. Sie hält sich in dem Grabmal auf. Mit etwas Glück vermittelt ihr das Studium der Schalen den Einblick, den sie benötigt, um diesen sterbenden Ort zu heilen.",objectives={"Sprecht mit Mura Runetotem in dem Grabmal."}]])
R(3321,"Habt Ihr das verloren?",[[description="Ihr habt viel für den Orden getan, $n. Allein die Hingabe, derer es bedarf, um hierher zu gelangen, hätte jede normale Person abgehalten. Galvan und auch ich haben keinerlei Zweifel, dass Ihr einer von uns seid.$B$BAus diesem Grund denke ich, dass Ihr Euch eine kleine Belohnung verdient habt. Es ist nichts Besonderes, nur eine Kleinigkeit. Vielleicht sind Euch seine Eigenschaften vertraut, denn ich glaube, dass es der Grund war, warum Ihr überhaupt zu uns gekommen seid.",objectives={"Wartet, bis Trenton seine Arbeit erledigt hat."}]])
R(3341,"Das Ende bringen",[[description="Im Brachland liegt ein schreckliches Dickicht aus ineinander verschlungenen Ranken, Hügel von Razorfen genannt. Unsere ersten Beobachtungen haben zwar auf keine große Bedrohung schließen lassen, aber die neuesten Funde geben doch allen Grund zur Sorge...$B$BDie Stacheleber der Hügel von Razorfen haben sich mit der Geißel zusammengetan. Ein Lich namens Amnennar der Kältebringer beherrscht sie jetzt und nutzt die Macht seines riesigen Bewusstseins, um jede ihrer Bewegungen zu kontrollieren.$B$BAmnennar verfügt über eine direkte telepathische Verbindung zu Ner'zhul. Diese Bindung müssen wir durchtrennen, $N. Dem Kältebringer muss ein Ende gemacht werden.",objectives={"Andrew Brownell will, dass Ihr Amnennar den Kältebringer tötet und ihm dessen Schädel bringt."}]])
R(3361,"Dilemma eines Flüchtlings",[[description="Wir haben die Troggs aus Gnomeregan vertrieben, aber dann ist alles schrecklich schief gegangen! Jetzt ist unsere Heimat völlig von Strahlen verseucht und wir Gnome sind überall in Dun Morogh zerstreut.$B$BIn meiner Hast, der Strahlung zu entkommen, habe ich all mein ganzes Hab und Gut und auch meine Werkzeuge verloren. Die Trolle haben sie geholt. Sie haben meine Truhe, meine Kiste, und meinen Bolzeneimer gestohlen! Alles das haben sie in ihre Lager südwestlich von Anvilmar mitgenommen.$B$BIch bin nur leider kein Abenteurer - könntet Ihr bitte meine Sachen suchen und sie mir herbringen?",objectives={"Bringt Felix Whindlebolt in Anvilmar den Kasten, die Truhe und den Bolzeneimer von Felix."}]])
R(3362,"Disteltal",[[description="Habt Ihr jemals das Disteltal gesehen? Es ist ein sehr gefährlicher Ort, $n.$B$BDiesen merkwürdigen Bestien dort traue ich nicht für eine Minute! Ich glaube, man nennt sie knorrige Distelwandler und Distelwurzelformer...$B$BIch möchte in das Tal hinein, aber solange es dort von Distelwandlern wimmelt, kehre ich auf keinen Fall dorthin zurück. Und an dieser Stelle kommt Ihr ins Spiel - wenn Ihr einige von ihnen erledigt, würde ich vielleicht doch dorthin zurückkehren. Was meint Ihr, $n? Helft Ihr mir?",objectives={"Tran'rek in Gadgetzan möchte, dass Ihr 8 knorrige Distelwandler und 8 Distelwurzelformer erledigt."}]])
R(3363,"Verderbte Liedblume",[[description="Nehmt mich auf.",objectives={"Blah."}]])
R(3364,"Lieferung des kochend heißen Morgengebräus",[[description="Bah! Ich sollte dieses köstliche, kochend heiße Morgengebräu schon vor einer ganzen Weile zu Durnan Furcutter im Anvilmar bringen, aber ich musste erst eine Ladung zu Grelin hier bringen. Ich werde es niemals bis nach Anvilmar schaffen, bevor das Gebräu kalt wird!$B$BIhr seht hurtig aus. Vielleicht könnt Ihr es schaffen. Diese Tasse wird nur noch fünf Minuten lang heiß bleiben, und Durnan bestellte kein \"eisiges\" Morgengebräu, also beeilt Euch. Anvilmar liegt im Nordosten. Es ist eine Siedlung, die in den Berg gebaut wurde.$B$BDanke, $N, und vergesst nicht, mir meinen Becher zurückzubringen!",objectives={"Bringt ein kochend heißes Morgengebräu zu Durnan Furcutter ins Anvilmar hinein, bevor es innerhalb von fünf Minuten kalt wird!"}]])
R(3365,"Den Becher zurückbringen",[[description="Das kam genau zur rechten Zeit! Es geht doch nichts über ein heißes - neee, KOCHEND HEISSES Morgengebräu an einem kalten Wintertag, um einem das Herz zu wärmen.$B$BHier, bitte $n... seid so nett und bringt für mich den leeren Becher zurück zu Nori, ja?",objectives={"Bringt Nori Pridedrift den Becher zurück."}]])
R(3366,"Der leuchtende Splitter",[[description="Der Splitter ist von einem glänzenden Grün und obwohl er fest ist, scheint etwas wie Rauch genau unterhalb der Oberfläche herumzuwirbeln. Ihr möchtet am liebsten in die Tiefen des Kristalls schauen, aber gleichzeitig wisst Ihr, dass es etwas sehr Beunruhigendes damit auf sich hat.$B$BVielleicht solltet Ihr in Ratchet nach jemandem suchen, der Euch mehr über diesen seltsamen Splitter erzählen kann.",objectives={"Reist nach Ratchet, um die Bedeutung des Alptraum-Splitters herauszufinden."}]])
R(3367,"Suntara-Steine",[[description="<Dorius stöhnt.>$B$BIch bin schwer verletzt, $R. Fühle mich... benommen... Alles dreht sich... Innere... Blutungen.$B$BIch muss zurück nach Ironforge. Helft mir, $N.",objectives={"Helft Dorius, zurück nach Ironforge zu kommen."}]])
R(3368,"Suntara-Steine",[[description="Bruder,$B$Bwenn Du diesen Brief liest, bin ich nicht mehr. Wie er zu dir gelangt, weiß ich nicht, aber danke und belohne denjenigen, der ihn dir bringt.$B$BZu den Steinen: Es gibt sie wirklich und sie befinden sich im Besitz der Dunkeleisenzwerge. Ihr Anführer, Lathoric der Schwarze, benutzt die Kraft der Steine, um mein Ausgrabungsteam zu versklaven. Sie wurden zum Kessel gebracht. Ihre Gedanken wurden verdreht, sie arbeiten Tag und Nacht, um etwas, das Obsidion heißt, zu vollenden.$B$BHilf ihnen, Bruder. Das ist der letzte Wunsch eines toten Mannes.$B$B- Dorius",objectives={"Bringt den angesengten Brief zu Thorius in Ironforge. Er befindet sich in der Halle der Forscher."}]])
R(3369,"Alptraum",[[description="Dieser Splitter enthält große Geheimnisse; er ist die pure Essenz des Smaragdgrünen Traums. Was ich jedoch in diesem Splitter sehe, ist kein Traum, diese Art der Vision ist eher ein Alptraum.$B$BIch möchte Euch nicht beunruhigen, $N, aber ich denke, es ist am besten, wenn Ihr diesen Splitter so schnell wie möglich in die Hände eines weisen Druiden gebt.$B$BIhr müsst Hamuul Runetotem auf der Anhöhe der Ältesten finden. Geht nach Thunder Bluff. Mehr vermag ich Euch nicht zu sagen.",objectives={"Bringt den Alptraum-Splitter zu Hamuul Runtetotem auf der Anhöhe der Ältesten."}]])
R(3370,"Alptraum",[[description="Dieser Splitter trägt große Geheimnisse in sich; es ist die pure Essenz des Smaragdgrünen Traums. Was ich jedoch in diesem Splitter sehe ist kein Traum, diese Art der Vision ist eher ein Alptraum.$B$BIch möchte Euch nicht beunruhigen, $N, aber ich denke, es ist am besten, wenn Ihr diesen Splitter in die Hände eines weisen Druiden gebt, sobald Ihr könnt ... $B$BIhr müsst Mathrengyl Bearwalker im Zirkel des Cenarius finden. Geht nach Darnassus. Mehr vermag ich Euch nicht zu sagen.",objectives={"Bringt den Alptraum-Splitter zu Mathrengyl Bearwalker in Darnassus."}]])
R(3371,"Zwergengerechtigkeit",[[description="Wo mein Herz einst schlug, ist jetzt ein leeres Loch, $N. Über den Verlust von Dorius werde ich so schnell nicht hinwegkommen. Ich muss seinen letzten Wunsch erfüllt sehen - diejenigen, die diesen kaltblütigen Mord durchführten, müssen der Gerechtigkeit zugeführt werden.$B$BKehrt zur sengenden Schlucht zurück und erfüllt seine letzte Bitte. Befreit seine Männer.",objectives={"Kehrt zur Sengenden Schlucht zurück und sucht Dorius' Archäologenteam."}]])
R(3372,"Erlöst sie",[[description="Befreit sie, $R. Selbst nachdem ihre Körper aufgegeben haben, zwingt die Macht der Suntara sie, ihre Aufgaben weiter zu erfüllen.$B$BDer Altar von Suntara ist der Schlüssel. Geht nach Norden, in die Hügel oberhalb der Höhle... Die Twilight-Hammer bewachen dort ein Relikt. Bringt es herbei und stellt es auf den Altar von Suntara.$B$B<Der sterbende Archäologe bricht zusammen.>",objectives={"Sucht das mysteriöse Artefakt, das im Norden von den Twilight-Hammer bewacht wird."}]])
R(3373,"Die Essenz des Eranikus",[[description="Als Ihr den Edelstein berührt, ertönt eine tiefe Stimme in Eurem Geist.$B$B\"Sterbliches Wesen, hört diese Bitte. Ich bin Eranikus vom grünen Drachenschwarm, der Hüter dieses verfluchten Tempels. Meine Aufgabe, sicherzustellen, dass die Trolle nie wieder ihre Monstrosität von einem Gott in diese Welt bringen, ist nun fehlgeschlagen. Während ich diesen Edelstein mit einem Teil meiner magischen Essenz fülle, fühle ich, wie mein Traum sich zum Chaos hinbewegt. Ich bitte Euch... legt diesen Edelstein in den Essenzborn in meinem Unterschlupf und lasst unsere Magie dort den Makel von meiner Psyche nehmen, sodass ich endlich ruhen kann.\"",objectives={"Legt die Essenz von Eranikus in den Essenzborn, der sich in dem Versunkenen Tempel in seinem Unterschlupf befindet."}]])
R(3374,"Die Essenz des Eranikus",[[description="Ihr aktiviert den Schwurstein und Itharius spricht Euren Geist direkt durch den Stein an.$B$B\"Indem Ihr die Ladung dieses Schwursteins angenommen habt, erklärt Ihr Euch einverstanden, meiner Sache und der Sache von Yseras Drachenschwarm behilflich zu sein, und die verderbte Seele von Eranikus zu erlösen. Das erste Opfer, eines von vielen, die Ihr ohne Zweifel bringen müsst, ist, mir den Edelstein zu übergeben, der den Teil von Eranikus' Psyche gefesselt hat, der noch über einen freien Willen verfügt.\"$B$B\"Tut dies, $n, und wir werden zusammen an der Erlösung einer Seele arbeiten, die es verdient hat, erlöst zu werden.\"",objectives={"Bringt den Schwurstein von Yseras Drachenschwarm sowie die gekettete Essenz von Eranikus zu Itharius in die Sümpfe des Elends. Dort werdet Ihr Eure Entscheidung treffen, ob Ihr Yseras Drachenschwarm helfen wollt oder nicht."}]])
R(3375,"Ersatzphiole",[[description="Ähm... Ihr braucht eine weitere Wahrsagephiole? Das soll wohl ein Witz sein! Was habt Ihr denn mit der Ersten angestellt?! Wir haben eine Menge Arbeit vor uns, $R. Diese Phiolen wachsen nun mal nicht auf Bäumen! Eigentlich wünschte ich, es wäre so, dann könnte ich nämlich einfach eine pflücken gehen. Ich habe nämlich keine mehr!$B$BUm Euch eine zu machen, brauch ich Folgendes: Einen Manatrank, ein Stück Kohle und etwas süßen Nektar. Fragt mich ja nicht, warum, bringt mir einfach, was ich brauche, und ich werde Euch eine neue Phiole machen.",objectives={"Bringt einen Manatrank, Kohle und Süßen Nektar zu Talvash del Kissel in Ironforge, um einen Ersatz für Talvashs Wahrsagephiole zu bekommen."}]])
R(3376,"Tötet Spitzhauer!",[[description="$n... Ihr seid ein Neuling, ich habe von Euch gehört. Vielleicht könnt Ihr uns ja helfen, wo andere bereits versagt haben.$B$BWir Tauren haben in diesem Land unsere Heimstatt geschaffen, aber nicht, ohne teuer dafür zu bezahlen. Die Stacheleber des Borstennackenstamms aus der Dornrankenklamm, mit Häuptling Spitzhauer Dornenmantel als Anführer, machen uns mit ihrem ständigen Krieg das Leben schwer. Ich beauftrage Euch, mir den Kopf des Häuptlings zu bringen!$B$BIhr könnt ihn in der Klamm östlich von hier in dem heruntergekommenen Dorf finden.",objectives={"Bringt den Kopf von Häuptling Spitzhauer Dornenmantel zu Kriegerheld Windfeather nach Red Cloud Mesa."}]])
R(3377,"Gebet an Elune",[[description="Werdet Ihr mir helfen, sterbliches Wesen? Hört meine Geschichte.",objectives={"Hört Zamaels Geschichte."}]])
R(3378,"Gebet an Elune",[[description="Werdet Ihr mir helfen, sterbliches Wesen? Werdet Ihr das Gebet an Elune finden?$B$BWie ich bereits sagte, wurde das Gebet auf eine goldene Schrifttafel geätzt. Einer dieser Götzenanbeter muss sie bei sich tragen.$B$BWenn Ihr mein Gebet wiederfindet, bringt es zu Astarii Starseeker in Darnassus. Dass mein Glauben nach den zahllosen widerwärtigen Aktionen, die ich gegen diese Welt und seine Einwohner begangen habe, wiederbelebt wurde, ist vollkommen unwichtig, aber mein Gebet muss gehört werden. Absolution ist das Letzte, was ich erwarte.",objectives={"Findet das Gebet an Elune und bringt es zu Astarii Starseeker in Darnassus."}]])
R(3379,"Schattenweber",[[description="Die Spinnen der Sengenden Schlucht sind eine unschätzbare Quelle für Schattenseide. Wie Ihr wisst, ist Schattenseide bei den Fachleuten unseres Gewerbes heiß begehrt.$B$BSeit Kurzem hat sich eine Gruppe von Wilderern in diesem Land eingenistet, die achtlos massenhaft Spinnen töten, ohne darüber nachzudenken, welche Auswirkungen ihre Taten auf Dauer haben können. Die erste Aufgabe, die ich von Euch verlange, ist recht einfach: Findet sie... und macht ihnen ein Ende.$B$BBeginnt Eure Suche im Norden.$B$BWenn Ihr Hilfe benötigt, sprecht mit Schleifer.",objectives={"Tötet die Gruppe der Schattenseidewilderer, die in der Sengenden Schlucht umherstreifen. Nilith hat Grund zu der Annahme, dass es fünf von ihnen gibt, die ausgeschaltet werden müssen."}]])
R(3380,"Der versunkene Tempel",[[description="Es gibt rastlose Geister in dieser Welt, $N. Es sind Geister, die durch ihre Einsamkeit besudelt wurden und an ein altes Übel gebunden sind...$B$BIch habe von einem Ort gehört, der tief unter der Erdoberfläche liegt... größere Mächte als ich jemals gesehen habe, haben ihn dorthin verbannt.$B$BWenn Ihr mehr über diesen Ort, den Versunkenen Tempel, erfahren wollt, sucht einen Goblin namens Marvon Rivetseeker auf. Er hat viele alte Gebiete der Welt erforscht. Zuletzt hieß es, dass er sein Heim in Ratchet verlassen habe, um die Trollruinen von Tanaris zu erforschen.",objectives={"Sucht Marvon Rivetseeker in Tanaris."}]])
R(3381,"Ein Treffen mit dem Meister",[[description="Ah, ein $R, noch dazu jung, der mit Sanath sprechen möchte. Was für ein wundervoller Tag! Ich fühle mich so geehrt, dass Ihr mich mit Eurer Anwesenheit beehrt. Danke!$B$BBitte... seid nicht so arrogant anzunehmen, dass mein Sarkasmus ein Kompliment war. Lasst uns eine Sache klarstellen: Ich mag Euch nicht. Aber diese kleine Unterhaltung hat nichts mit uns zu tun... es geht um meinen Meister.$B$BBringt mir ein Paar Hippogryphenfedern für meine Pfeile und ich werde Euch zu ihm führen. Er bat darum, dass ich ihm Abenteurer schicke, sofern sie sich würdig erweisen.",objectives={"Bringt 2 unbeschädigte Hippogryphenfedern zu Sanath Lim-yo in Azshara, wenn Ihr mit seinem Meister sprechen wollt."}]])
R(3382,"Eine Mannschaft in Bedrängnis",[[description="Wir waren kurz vor der Küste und suchten nach einem sicheren Hafen, um vor Anker zu gehen. Die Sonne war noch keine Stunde untergegangen, als sie angriffen... diese verdammten Naga!$B$BIch weiß nicht genau, wonach sie gesucht haben, aber sie haben es offensichtlich nicht gefunden - sie sind bereits schon einmal wiedergekommen. Einige meiner Späher stehen am Eingang zum Tal Wache, um uns zu warnen, wenn der nächste Angriff kommt.$B$BEs tut mir Leid, dass Ihr gerade jetzt vorbeikommt, $N, aber das liegt nicht in meiner Macht.$B$BSeid Ihr bereit für den Kampf Eures Lebens?",objectives={"Verteidigt Kapitän Vanessa Beltis, ihre Mannschaft und die Passagiere der HERRIN DES HORIZONTS gegen den Angriff der Naga. Captain Vanessa Beltis muss überleben."}]])
R(3383,"<UNUSED>")
R(3384,"<UNUSED>")
R(3385,"Der Untermarkt",[[description="Sie bezeichnen sich selbst als den Untermarkt: Halsabschneider von Händlern, die verkaufen, verschieben, handeln und zu fast allem bereit sind, vorausgesetzt, der Preis stimmt.$B$BEs kommt noch schlimmer, $n. Sie haben einen Stützpunkt für ihre Operationen hier in der Sengenden Schlucht errichtet. Handelsmeister Kovic führt diese Operationen an und hat enge Verbindungen zu den Dunkeleisenzwergen des Gebietes.$B$BWir müssen hart zuschlagen und den Anführern ein Zeichen setzen. Erschlagt Handelsmeister Kovic und seinen Diener Clunk. Bringt seinen Händlerranzen zurück, sobald die Tat ausgeführt ist.$B$BZum Kessel!",objectives={"Erschlagt Handelsmeister Kovic und seinen Diener Clunk. Nehmt den Händlerranzen von seinem Leichnam und bringt ihn zu Nilith."}]])
R(3401,"<UNUSED>")
R(3402,"Der Untermarkt",[[description="Ich will, dass Ihr Vizzklick in Gadgetzan persönlich die Nachricht von Kovics Niederlage überbringt. Ich bin ziemlich sicher, Kovics Tod wird ihn so erfreuen, dass er Euch eine großartige Belohnung geben wird.",objectives={"Sprecht mit Vizzklick in Gadgetzan."}]])
R(3403,"<UNUSED>")
R(3404,"<UNUSED>")
R(3405,"<UNUSED>")
R(3421,"Rückreise")
R(3422,"<UNUSED>")
R(3423,"<UNUSED>")
R(3424,"<UNUSED>")
R(3425,"<UNUSED>")
R(3441,"Göttliche Vergeltung",[[description="Hört meine Geschichte, Abenteurer.",objectives={"Lasst Kalaran Windblade seine Geschichte erzählen."}]])
R(3442,"Die fehlerlose Flamme",[[description="Ihr habt die richtige Entscheidung getroffen, $n.$B$BWir müssen dort zuschlagen, wo wir den größten Schaden anrichten: an den vier Wachpostentürmen.$B$BWenn die vier Wachpostentürme in Flammen stehen, starten wir eine Offensive, bevor sie reagieren können.$B$BIhr benötigt das passende Werkzeug, um die Türme in Brand zu setzen. Für die Herstellung des Werkzeugs wird einiges an Materialien benötigt.$B$BBringt mir vier Herzen der Flamme und vier Kugeln Golemöl, und ich werde die Fackel der fehlerlosen Flamme herstellen können.$B$BIhr solltet Euch also zuerst die Golems und Elementare dieses Landes vornehmen.",objectives={"Sammelt 4 Herzen der Flamme und 4 Kugeln Golemöl und bringt die Gegenstände zu Kalaran Windblade."}]])
R(3443,"Das Schmieden des Schafts",[[description="Um die fehlerlose Flamme halten zu können, brauchen wir noch einen Schaft und eine Ummantelung. Ihr müsst zunächst einen geeigneten Schaft finden.$B$BDie Zuchtmeister und Sklavenhändler der Dunkeleisenzwerge des Kessels benutzen Waffen aus verzaubertem Thorium, eine besonders stabile Legierung. Wenn Ihr mir acht mit Thorium beschichtete Dolche bringen könnt, kann ich die Legierung aufbrechen und einen Schaft schmieden.",objectives={"Bringt 8 mit Thorium beschichtete Dolche zu Kalaran Windblade."}]])
R(3444,"Der runde Stein",[[description="Ich habe einst die furchteinflößenden Kammern des Versunkenen Tempels betreten. Das Böse an jenem Ort durchdringt alle, die eintreten. Mit Mühe und Not habe ich es geschafft, irgendwie meinen Weg wieder nach draußen zu finden, indem ich durch den Brühschlamm watete, der jetzt den Boden bedeckt. Ich kann mich nur daran erinnern, dass ich durch einen großen, kreisrunden Raum gestolpert bin, der angefüllt war mit Schlangenstatuen ...$B$BKürzlich habe ich einen runden Stein entdeckt, der anscheinend das gleiche Schlangensymbol trägt. Ich habe ihn verpackt und in meine Werkstatt nach Ratchet geschickt. Bringt ihn her und ich kann Euch vielleicht mehr erzählen.",objectives={"Holt den runden Stein aus Marvon Rivetseekers Werkstatt in Ratchet."}]])
R(3445,"Der versunkene Tempel",[[description="Ich habe von einem Ort gehört, der tief unter der Oberfläche der Erde liegt - dorthin verbannt durch größere Mächte, als ich jemals gesehen habe.$B$BWenn Ihr mehr über diesen Ort, den Versunkenen Tempel, erfahren wollt sucht einen Goblin namens Marvon Rivetseeker auf. Genau wie Troyas und ich hat er viele alte Gebiete der Welt erforscht. Zuletzt hieß es, dass er seine Heimstatt in Ratchet verlassen habe, um die Trollruinen von Tanaris zu erforschen.$B$BViel Glück bei Eurer Suche, man hat schon seit längerem nichts mehr von ihm gehört.",objectives={"Sucht Marvon Rivetseeker in Tanaris."}]])
R(3446,"In die Tiefen",[[description="Im Tempel fand ich einen kreisrunden Raum mit sechs Altaren, und am Rand eines jeden stand eine Schlangenstatue. Neugierig drückte ich gegen eine von ihnen, um zu sehen, was passieren würde. Es war eine Falle! Durch die Explosion wurde ich fast getötet. Als ich da auf einem Vorsprung lag, sah ich nach unten und bemerkte, dass eine weitere Statue unten im Raum stand; es war ein Altar der Art ... Hakkar, ich glaube, so wurde er genannt.$B$BIch denke, dass dieser Altar das Geheimnis ist ... Ihr müsst dieses Zeichen zum Altar in den Versunkenen Tempel bringen.",objectives={"Sucht den Altar von Hakkar im Versunkenen Tempel in den Sümpfen des Elends."}]])
R(3447,"Das Geheimnis des Kreises",[[description="Meine Erinnerungen sind verworren, aber ich werde Euch alles sagen, was ich weiß. Der Kreis der Statuen im Versunkenen Tempel mag ja gefährlich sein, ich glaube dennoch, dass sie das Geheimnis eines noch größeren Schatzes in sich bergen.$B$BVom Hauptaltar aus konnte ich eine Reihe von Lichtern aktivieren. Ich glaube, dass Ihr, wenn Ihr die Bedeutung dieser Lichter herausfindet, auch die weiteren Geheimnisse lüften könnt, die sich in diesem Raum verstecken.$B$BAber ich warne Euch, $n. In dem Tempel ist etwas unermesslich Böses. Es ist anzunehmen, dass alles Wertvolle äußerst streng bewacht wird.",objectives={"Reist zum Versunkenen Tempel und enthüllt das Geheimnis, das sich in dem Kreis der Statuen verbirgt."}]])
R(3448,"Die Bürde weitergeben",[[description="Kürzlich erhielt ich den Auftrag, Azshara zu untersuchen, einen einst wunderschönen Landstrich, den die Elfen ihr Zuhause nannten. Das war damals, als sie noch Magie praktizierten. Jetzt ist es dort eher gefährlich als schön, aber das hält uns nicht davon ab, jeden Stein umzudrehen, um Hinweise auf unsere Vergangenheit zu erhalten.$B$BEin Gefährte von mir namens Tymor bot mir seine Hilfe bei der Untersuchung dieses Gebietes an, da er ein besonderes Interesse an solchen Dingen hat.$B$BEr besitzt ein kleines Anwesen rechts neben der Halle der Mysterien hier in der Stadt.",objectives={"Sprecht mit Magier Tymor in Ironforge."}]])
R(3449,"Arkane Runen",[[description="Einstmals wurde Magie von einigen Elfen genauso verehrt wie Elune selbst. Einige ihrer mächtigsten Magier erstellten Runen und Schrifttafeln, die die Regeln des Arkanen zitierten und Einsichten in ihre Funde gaben. Sie ließen sie an öffentlichen Plätzen aufstellen, damit jeder darüber nachdenken konnte.$B$BIch hätte sehr gern Abpausbilder dieser Runen aus den Ruinen von Eldarath. Ich habe ein Set für Euch, mit dem Ihr Abpausbilder herstellen könnt, aber Ihr müsst sie selbst finden. Seid aber vorsichtig, die Forscherliga ist nicht die Einzige, die sich dafür interessiert.",objectives={"Verwendet das Zeichenset, um Abpausbilder von der Rune von Beth'Amara, der Rune von Jin'yael, der Rune von Markri und der Rune von Sael'hai herzustellen, bevor Ihr Euch zu der kleinen Insel vor der südlichen Halbinsel von Azshara aufmacht und dem Piloten Xiggs Fuselighter signalisiert, dass er sie abholen kann."}]])
R(3450,"Eine einfache Ladung",[[description="Ich will diese Abpausbilder sofort in meinen Turm geliefert haben, aber Ihr müsst nicht den ganzen Weg selbst gehen. Ich werde sie einfach per Luftfracht aus Azshara bringen lassen.$B$BXiggs Fuselighter schuldet mir noch einen oder zwei Gefallen und wird sich bald in der Nähe aufhalten - er wurde zur Küstenpatrouille abkommandiert. Sprecht mit ihm, bevor Ihr weggeht. Er kann Euch eine Leuchtfeuerwaffe geben, damit Ihr ihm signalisieren könnt. Sobald Ihr die Abpausbilder zusammen habt, begebt Euch an den Ort, den er Euch nennt und übergebt sie ihm dann, damit er sie sicher zu meinem Turm bringen kann. Er sollte sich im Hangar im Militärviertel aufhalten.",objectives={"Sprecht mit Xiggs Fuselighter in Ironforge."}]])
R(3451,"Signal zum Abholen",[[description="Ah, Tymor hat Euch also geschickt, hm? Ja, dem schulde ich noch einen oder zwei Gefallen. Wie war das? Nein, der kleine Teufel. Ja, da kann ich ihm helfen. Ihr braucht also eine Leuchtfeuerwaffe und einen Ort... nichts leichter als das.$B$BKurz vor der südlichen Halbinsel von Azshara liegt eine kleine Insel, auf der wir eine Landungsplattform gebaut haben. Ihr nehmt diese Leuchtfeuerwaffe und schießt sie dort ab. Ich sehe dann Euer Signal und werde vorbeikommen, um diese... was auch immer er da haben will, mitzunehmen.",objectives={"Sprecht mit Xiggs Fuselighter in Ironforge und erhaltet von ihm eine Standardausrüstung-Leuchtfeuerwaffe."}]])
R(3452,"Die Ummantelung der Flamme",[[description="Wir brauchen noch ein letztes Teil, um die Fackel zu formen.$B$BIn den Bergen nordwestlich von hier könnt Ihr ein großes Lager der Twilight-Hammer finden. Es heißt, dass sie Symbole und Götzenbilder zur Verehrung ihres Gottes mit sich herumtragen. Diese Symbole und Götzenbilder besitzen vielleicht genügend Verzauberung, um daraus eine magische Ummantelung herzustellen. Bringt mir ein einziges Symbol von Ragnaros und ich werde versuchen, die Magie aus dem Gegenstand zu extrahieren, um die Ummantelung zu erschaffen.",objectives={"Bringt ein Symbol von Ragnaros zu Kalaran Windblade."}]])
R(3453,"Die Fackel der Vergeltung",[[description="Gebt mir einen Augenblick, um die Teile zusammenzufügen und die notwendigen Verzauberungen anzuwenden.",objectives={"Wartet bis Kalaran Windblade die Fackel der Vergeltung vollendet hat."}]])
R(3454,"Die Fackel der Vergeltung",[[description="Die Fackel muss jetzt an ihren Besitzer gebunden werden. Nehmt die Fackel auf, $n.",objectives={"Nehmt die Fackel der Vergeltung."}]])
R(3461,"Rückkehr zu Magier Tymor",[[description="Tymor hat mir nichts gegeben, um Euch zu bezahlen, also schlage ich vor, dass Ihr das mit ihm besprecht, wenn Ihr zurück in Ironforge seid. Ich bin mir sicher, er wird dann immer noch an seiner Wohnung im Mystikerviertel sein. Klopft einfach bei ihm an, und er soll Euch ja gut bezahlen. Das hier ist nicht gerade ein Spaziergang... das ist schon mal sicher.$B$BDanke nochmals für Eure Hilfe und viel Glück.$B$BOh, das Zeichenset brauche ich nicht. Warum bringt Ihr es nicht selbst Tymor zurück, wenn Ihr ihn besucht?",objectives={"Bringt Magier Tymors Zeichenset zu ihm zurück nach Ironforge."}]])
R(3462,"Knappe Maltrake",[[description="Sprecht mit meinem Gesandten, dem Knappen Maltrake. Er wird Euch weiter unterweisen, wie die Fackel der Vergeltung zu benutzen ist.",objectives={"Sprecht mit dem Knappen Maltrake."}]])
R(3463,"Setzt sie in Brand!",[[description="Hört gut zu, $N. Obgleich die vier Türme niemals zerstört werden können, könnt Ihr dennoch die Fackel der Vergeltung benutzen, um sie für lange Zeit in Brand zu setzen. Ein Feuer, das kein Element und keine Macht löschen kann.$B$BWährend sie in Flammen stehen, kann keine Wache oder Wachposteneinheit die Posten besetzen, und so ist ihre erste Verteidigungslinie außer Kraft gesetzt.$B$BIhr müsst in jeden Turm eindringen und die Fackel der Vergeltung innerhalb ihrer Befestigung verwenden. Nehmt Euch in Acht vor den Elitewachposteneinheiten der Dunkeleisenzwerge, $N.",objectives={"Steckt die Wachpostentürme im Norden, Süden, Osten und Westen in Brand, indem Ihr die Fackel der Vergeltung innerhalb der einzelnen Gebäude benutzt."}]])
R(3481,"Plunder...",[[description="Die Truhe scheint verschlossen zu sein.",objectives={"Öffnet die Truhe."}]])
R(3482,"<NYI> <TXT> The Pocked Black Box",[[description="This is the horde version of the black box quest.",objectives={"Take this box to Kravel."}]])
R(3483,"Signal zum Abholen")
R(3501,"Im Dutzend besser",[[description="Obgleich Ihr wohl niemals eine fehlerlose Draenethystsphäre finden werdet, könnt Ihr zweifelsohne auf Euren Reisen durch dieses Land einige unvollständige Draenethystfragmente entdecken.$B$BEs ist zwar unwahrscheinlich, dass Kum'isha die fehlerhaften Fragmente benutzen kann, um nach Hause zurückzukehren, dennoch können diese Stücke für andere nützliche Zwecke der Draenei dienen.$B$BBringt mir alle fehlerhaften Draenethystfragmente, die Ihr finden könnt, und ich werde Euch belohnen.",objectives={"Bringt Kum'isha unvollständige Draenethystfragmente und Ihr werdet für jedes, das Ihr bringt, belohnt."}]])
R(3502,"Des einen Draeneis Plunder...",[[description="Nach einer solchen Zurschaustellung von ekelhafter Gier ist mir richtig übel.$B$BWie dem auch sei, ich werde mich nicht allzu lange mit Eurer materiellen Abhängigkeit beschäftigen.$B$BFür jedes unvollständige Draenethystfragment, das Ihr mir bringt, werde ich Euch mit weiterem Plunder belohnen. Mein Haufen Plunder wird kleiner werden, und der Eurige dafür anwachsen. Auf Draeneor nennen wir das eine Situation, bei der alle nur gewinnen können.",objectives={"Bringt Kum'isha unvollständige Draenethystfragmente. Jede Art von Monster in den Verwüsteten Landen könnte ein Fragment bei sich tragen."}]])
R(3503,"Treffen mit dem Meister")
R(3504,"Verraten",[[description="Verräterisches, diebisches Weib! So nenne ich sie... und genau das wird sie immer sein!$B$BIch habe wahrscheinlich einen großen Fehler gemacht, $n. Ich habe einem Blutelfen vertraut. Was schlimmer ist, ich habe einer Frau vertraut!$B$BSie behauptete, in Azshara lägen große Reichtümer... mächtige Gegenstände. Ich sollte ihr nur ein paar Krieger zu ihrem Schutz schicken und dafür würde ich belohnt. Und wer ist jetzt wohl der Dumme - sie hat sie alle umgebracht.$B$BIch will Rache, $n, aber ich kann es mir nicht leisten, noch jemanden zu schicken. Sucht Ag'tor bei Valormok auf, nördlich des Lagers der Haldarr. Er kann Euch mehr berichten.",objectives={"Bringt den versiegelten Brief zu Ag'tor Bloodfist nach Azshara."}]])
R(3505,"Verraten",[[description="Das hatte ich mir gedacht.$B$BWir werden unseren Kreuzzug gegen ihre Tagelöhner entlang der westlichen Steilhänge an der nördlichen Halbinsel von Azshara beginnen. Tötet sie mit blutiger Wut - lasst sie wissen, dass sie die falschen Verbündeten verraten haben.$B$BUm sie selbst müsst Ihr Euch jetzt noch nicht kümmern - sie verbringt die meiste Zeit zusammen mit ihren Leibwachen auf der Suche nach Azshara. Es ist wahrscheinlich am klügsten, erst ihre Tagelöhner zu erschlagen und dann ihr persönliches Lager zu suchen. Es wäre weise auszukundschaften, wo wir sie angreifen können. Vielleicht gibt es ja etwas, womit wir sie provozieren können.",objectives={"Tötet 10 Blutelf-Wiederbeschaffer und 10 Blutelf-Feldmesser, bevor Ihr Magus Rimtoris Lager sucht. Sobald Ihr es gefunden habt, sucht nach etwas, das für sie von Bedeutung ist und das wir nehmen können, um sie in einen Kampf zu locken."}]])
R(3506,"Verraten",[[description="Nach einigen Momenten des Nachdenkens kommt Ihr auf ein paar Ideen, eine davon bringt Euch zum Lächeln: Vielleicht würde die Zerstörung der Kristalle die Blutelfin ärgern, die für das Abschlachten so vieler Orcs und den Verrat an Belgrom verantwortlich ist?$B$BIhr fahrt fort, mehr vom Manuskript und den Bildern zu entschlüsseln und erkennt, dass einer der Kristalle an den Schöpfer des Kreises gebunden ist - die anderen sind an etwas weitaus Finstereres gebunden.$B$BIhr schließt das Buch und beginnt Euch zu entscheiden, welchen Kristall Ihr zerstören wollt.",objectives={"Zerstört den arkanen Fokussierkristall, der an Magus Rimtori gebunden ist, und tötet sie danach. Bringt dann den Kopf von Magus Rimtori zu Ag'tor Bloodfist nach Azshara."}]])
R(3507,"Verraten",[[description="Kehrt zu Belgrom nach Orgrimmar zurück. Er wird ihren Kopf höchstpersönlich sehen wollen. Wir werden in Kürze dorthin zurückkehren.$B$BAh, dies ist heute wahrlich ein Freudentag. Danke für Eure Hilfe, $n.",objectives={"Sprecht mit Belgrom Rockmaul in Orgrimmar."}]])
R(3508,"Den Zauberschutz brechen",[[description="Ihr seid tollkühn, $n. Es ist eine bewundernswerte Eigenschaft Eurer Art, sich blind in die Schlacht zu stürzen, auch wenn nur wenig oder gar keine Aussicht auf Erfolg besteht. Ich werde Euch behilflich sein, sei es auch nur, um einen einzigen von Razelikhs Dienern fallen zu sehen.$B$BDen Zauberschutz, der auf Razelikhs Untergebenen liegt, zu brechen, kostet Zeit und macht es nötig, rare Artefakte zu erwerben.$B$BSeid still, ich muss erst das Erleuchtungsritual durchführen. Die Information, die ich dabei erhalte, wird mir helfen, Waffen von großer Macht zu schmieden.",objectives={"Wartet, bis Loramus den Erleuchtungszauber vollendet hat."}]])
R(3509,"Der Name der Bestie",[[description="Es gibt nur eine Möglichkeit, den Dämonenlord und seine Diener zu verletzen. Eine Waffe der Macht muss geschmiedet werden, die seinen wahren Namen trägt.$B$BWird eine solche Waffe geschmiedet, sind der Dämon und alle, die unter seinem Kommando stehen, verwundbar.$B$BIn Azshara residiert eine geringe Gottheit: Lord Arkkoroc. Ihn müsst Ihr aufsuchen. Aber seid gewarnt - wenn man Euch entdeckt, werden seine Diener alles tun, um Euch zu vernichten.$B$BZweifelsohne müsst Ihr einen Preis für solche Informationen bezahlen.",objectives={"Sprecht mit Lord Arkkoroc in Azshara. Beginnt Eure Suche am Rand des Wassers, um den Tempel von Arkkoran zu finden."}]])
R(3510,"Der Name der Bestie",[[description="Sie tötet meine Kinder, sterbliches Wesen. Sie nennt sich selbst die Herrscherin dieser Meere. Eine falsche Göttin, nichts weiter. Zermalmt sie und bringt mir all ihre Köpfe.$B$BDafür erhaltet Ihr den Namen, den Ihr sucht, und etwas anderes von gleicher Bedeutsamkeit.$B$BSie weilt im Gelege... Genannt wird sie Hetäre.$B$B<Lord Arkkoroc zeigt in Richtung Südwesten.>$B$BGeht!",objectives={"Erschlagt Hetäre und bringt den blutigen Hetärenkopf, den geschlagenen Hetärenkopf und den verwundeten Hetärenkopf zu Lord Arkkoroc."}]])
R(3511,"Der Name der Bestie",[[description="Wie versprochen, werde ich den Namen des Dämonenlords enthüllen: Es ist Razelikh der Entweiher. Zuerst muss ich jedoch etwas vorbereiten, das für Eure Reise von äußerster Wichtigkeit ist.$B$BDie Waffe, die Ihr herstellen wollt, benötigt einen Härter. Gebt mir einen Moment Zeit, um das Blut aus diesen Köpfen herauszupressen.$B$B<Lord Arkkoroc drückt die Köpfe mit seinen gigantischen Fäusten zusammen, sodass das Blut aus ihnen herausfließt.>$B$BBringt diesen Härter zurück zu Loramus, zusammen mit dem Namen der Bestie: Rakh'likh.",objectives={"Bringt den Härter zurück zu Loramus Thalipedes."}]])
R(3512,"Mit Eranikus' eigenen Worten",[[description="$N, als Erstes werden wir eine Methode ersinnen, um durch den Edelstein mit Eranikus zu sprechen. Zurzeit befindet er sich in einem gefährlichen Zustand zwischen Schlaf und Tod, verstrickt in ein Gewebe aus Alpträumen. Zwar ist die Essenz, die Ihr mir gegeben habt, stark besudelt, aber es gibt dennoch Hoffnung, dass wir zu ihm durchdringen.$B$BReist weit hinaus in das eisige Land des östlichen Winterspring und sucht einen unserer sterblichen Verbündeten, Umbranse den Geistsprecher. Er ist ein menschliches Medium, der für die Toten spricht. Zwar ist Eranikus noch nicht wirklich tot, trotzdem könnte er uns eine Hilfe sein.",objectives={"Reist in den östlichen Teil von Winterspring und sprecht mit Umbranse, dem Geistsprecher."}]])
R(3513,"Die runenverzierte Rolle",[[description="Die offiziell aussehende Rolle wurde mit einem silbrigen Band eng verschnürt. Ihr seid Euch sicher, dass jemand das hier sehen möchte, aber wer?$B$BEs gibt einen Außenposten im Norden in der Nähe der Grenze von Ashenvale, und wenn die Informationen auf dieser Rolle die Nachtelfen betreffen, dann sollte die Rolle dorthin gebracht werden.",objectives={"Bringt die runenverzierte Rolle zum nördlichen Wachturm des Brachlandes."}]])
R(3514,"Hordenpräsenz",[[description="Diese Rolle ist von der Ränke schmiedenden Dryade Rynthariel, Schlüsselmeisterin des Krallenbaus auf dem Steinkrallengipfel.$B$BMit dem Boten, von dem Ihr diese Rolle erbeutet habt, hat sie jetzt ja wohl keinen Kontakt mehr, aber nachgeben dürfen wir trotzdem nicht. Die Horde wird ihre Kundschafter hier nicht tolerieren.$B$B$n, reist zum Krallenbau. Tötet Rynthariel und stellt ein Symbol auf, das alle sehen können. Nehmt diese Hordenflagge mit Euch, $n. Hisst sie im Krallenbau, damit sie es sich zweimal überlegen, bevor sie einen weiteren Boten durch unser Gebiet schicken.",objectives={"Tötet die Anführerin des Krallenbaus, Rynthariel die Schlüsselmeisterin."}]])
R(3515,"<UNUSED>")
R(3516,"<UNUSED>")
R(3517,"Wissen stehlen",[[description="Ich muss zugeben, $n, ich habe das Beste aus meiner Situation in Azshara gemacht. Belgroms Bestrafung hatte schon seine Vorteile.$B$BBevor ich wegging, habe ich einige Nachforschungen angestellt. Ihr wärt überrascht darüber, wie viele wertvolle Gegenstände hier einfach so herumliegen.$B$BIch erzähle Euch noch mehr von meinen Geschäften und gebe Euch sogar einen Anteil an meinen Gewinnen, wenn Ihr mir helft, ein paar von den Sachen einzusammeln.$B$BIn den östlichen Ruinen von Eldarath gibt es Schrifttafeln, die ich benötige. Alle vier wurden nach Hochgeborenenhexern benannt. Bringt sie mir und wir können weiterreden.",objectives={"Sucht die Schrifttafel von Beth'Amara, die Schrifttafel von Jin'yael, die Schrifttafel von Markri und die Schrifttafel von Sael'hai, bevor Ihr zu Jediga in Azshara zurückkehrt."}]])
R(3518,"Lieferung an Magatha",[[description="Die erste Schrifttafel geht an einen weiblichen Tauren... mit Namen Magatha. Sie gehört zu den Ältesten in Thunder Bluff und zu den Befürwortern der Allianz zwischen den Tauren und den Verlassenen. Sie ist mehr als jeder andere der Ältesten der Meinung, dass die Tauren und ihre Lebensart den Verlassenen helfen können, einen Weg zurück zum Menschsein zu finden.$B$BBringt Ihr die Schrifttafel von Beth'Amara. Die Schrifttafel kann das fehlende Glied sein, das sie benötigt, um den Verlassenen zu helfen... das behauptet sie jedenfalls.",objectives={"Bringt die Schrifttafel von Beth'Amara zu Magatha in Thunder Bluff."}]])
R(3519,"Ein Freund in Not",[[description="Aghhh... Ich wurde ziemlich schlimm von einer Spinne namens Githyiss die Üble gebissen, während ich die Spinnenhöhle ganz in ihrer Nähe erforschte. Ich bin sicher, dass ich ernsthaft vergiftet bin; Ihr müsst mir helfen.$B$BSagt es bitte Dirania Silvershine. Sie wird mir helfen können.$B$BBeeilt Euch... Mir ist so schwindelig...",objectives={"Sprecht mit Dirania Silvershine in Shadowglen."}]])
R(3520,"Kreischergeister",[[description="Ich suche die Geister der Talkreischer von Feralas. Sie sind die Cousins eines alten, alten Gottes und ihre Geister sind mit ihm verbunden.$B$BNehmt diesen Dornbuschzauberstab und reist nach Feralas. Sucht und besiegt die Talkreischer in Süd- und Mittel-Feralas, und schwingt meinen Dornbuschzauberstab dann über ihre gefallenen Körper. Dadurch wird ihr Geist dazu gebracht, sich zu zeigen. Berührt den Geist und sammelt seine Essenz.$B$BKommt mit meinem Dornbuschzauberstab und der gesammelten Essenz zu mir zurück, und ich werde Euch mehr von dem alten Gott erzählen, von dem ich sprach.",objectives={"Fangt die Geister von 3 Kreischern in Feralas ein und kehrt dann zu Yeh'kinya in Steamwheedle zurück."}]])
R(3521,"Iverrons Gegengift",[[description="Wir dürften in der Lage sein, Iverron zu helfen, denn ich kenne ein Gegengift, das gegen das Gift wirkt. Bevor ich es herstellen kann, benötige ich allerdings einige Zutaten.$B$BIch brauche Hyazinth-Pilze. Sie wachsen unter Bäumen. Ihr könnt sie aber auch von den Grell südlich von hier sammeln; sie scheinen sie sehr zu mögen. Außerdem brauche ich noch Mondblütenlilien, die nur an Wasserteichen wachsen.$B$BDie letzte Zutat könnte die Schwierigste sein. Sammelt Waldwebersekret von genau den Spinnen, die Iverron vergiftet haben.",objectives={"Sammelt 7 Hyazinth-Pilze, 4 Mondblütenlilien und 1 Waldwebersekret für Dirania Silvershine in Shadowglen."}]])
R(3522,"Iverrons Gegengift",[[description="Das Gegengift ist fertig, $n. Bitte achtet darauf, dass Iverron es auch trinkt.$B$BEs gibt jedoch etwas, das Ihr wissen sollt: Das Gegengift ist nur 5 Minuten wirksam. Ihr müsst es ihm rechtzeitig bringen.$B$BMögen Eure Füße beflügelt sein, $n.",objectives={"Bringt Iverrons Gegengift zu Iverron, bevor die Zeit um ist. Ihr findet Iverron bei der Höhle im Norden."}]])
R(3523,"Geißel der Niederungen",[[description="Phantastisch! Mein Name ist Belnistrasz und ich danke Euch für meine Rettung. Ich hatte mich schon tot gewähnt... oder schlimmer, als Mahlzeit für dieses von der Geißel befallene Gezücht. Ja, richtig gehört, ich sagte Geißel; sie haben anscheinend mit den Stachelebern hier eine Art Vereinbarung getroffen, und dieser Alptraum ist das Ergebnis.$B$BHört mir zu... anstatt einfach wegzulaufen, möchte ich doch uns allen zuliebe versuchen, etwas zu ändern. Könntet Ihr mir dabei helfen? Es ist wahrscheinlich gefährlich, aber Ihr scheint ein Typ zu sein, dem das nicht viel ausmacht.",objectives={"Wenn Ihr Belnistrasz helfen wollt, sprecht noch einmal mit ihm und übergebt ihm den Schwurstein, den er Euch gab."}]])
R(3524,"An Land gespült",[[description="Majestätische Meereskreaturen begeben sich häufig an die Ufer von Dunkelküste, und liegen dort gestrandet, bis sie sterben. Vor Kurzem wurden diese Kreaturen in immer größerer Zahl an Land gespült. Ich wurde vom Tempel des Mondes zur Untersuchung dorthin geschickt, aber die Anwesenheit der Murlocs entlang des Wassers hat meine Forschungen schwierig gemacht.$B$BEs gibt eine riesige Kreatur, die unmittelbar südlich von Auberdine an Land gespült wurde und die von den widerlichen Grauflossenmurlocs umringt ist. Könntet Ihr Euch dorthin begeben und Knochen von dieser Kreatur für unsere Studien sammeln?",objectives={"Sammelt Meereskreaturknochen von der gestrandeten Meereskreatur unmittelbar südlich von Auberdine und kehrt dann mit ihnen zu Gwennyth Bly'Leggonde nach Auberdine zurück."}]])
R(3525,"Ausschalten des Götzen",[[description="In der Nähe des Eingangs befindet sich ein Götze, der als makabrer Ofen für die Stacheleber fungiert; die Bestien... verzehren die aus dem Brachland Entführten. Ich kann den Götzen außer Funktion setzen und verhindern, dass sie ihn erneut nutzen, aber ich benötige dabei Eure Hilfe. Mein Plan: Begleitet mich zum Götzen. Wenn wir dort angekommen sind, werde ich das Ritual einleiten. Ich werde kaum in der Lage sein, mit Euch zu kommunizieren, geschweige denn, mich zu verteidigen. Schützt mich, während ich den Götzen außer Funktion setze. Wenn sie mich erschlagen, dann ist alles aus.$B$BSteht Ihr mir bei?",objectives={"Begleitet Belnistrasz zum Götzen der Stacheleber in den Hügeln von Razorfen.$B$BBeschützt Belnistrasz, während er das Ritual durchführt, um den Götzen auszuschalten."}]])
R(3526,"Goblin-Ingenieurskunst",[[description="Bei der Experteningenieurskunst gibt es zwei unterschiedliche Disziplinen: Gnom und Goblin. Natürlich ist die Goblin-Ingenieurskunst die Wahl aller brillanten Ingenieure. Durch den klugen Einsatz von hochempfindlichen Sprengstoffen und phantastischen Ausrüstungsgegenständen lernt Ihr, die Welt zu meistern!$B$B$N, lest diese Anleitung. Wenn Ihr etwas über Goblin-Ingenieurskunst wissen wollt, dann bringt sie zu Nixx Sprocketspring nach Gadgetzan. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.",objectives={"Wenn Ihr etwas über die Goblin-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan."}]])
R(3527,"Die Prophezeiung von Mosh'aru",[[description="Die alte Prophezeiung von Mosh'aru berichtet von einer Methode, die Essenz des Gottes Hakkar zu bewahren. Sie wurde auf zwei Schrifttafeln niedergeschrieben und zu der Troll-Stadt Zul'Farrak gebracht, westlich von Gadgetzan.$B$BBringt mir die Mosh'aru-Schrifttafeln!$B$BDie erste Schrifttafel hat der Troll Theka der Märtyrer, der schon lange tot ist. Man sagt, dass seine Verfolger zu Skarabäen verflucht wurden und nun an seinem Schrein herumhuschen.$B$BDie zweite Schrifttafel hat die Wasserbeschwörerin Velratha, in der Nähe des hochheiligen Teiches von Gahz'rilla.$B$BWenn Ihr die Schrifttafeln habt, bringt sie zu mir.",objectives={"Bringt die erste und die zweite Mosh'aru-Schrifttafel zu Yeh'kinya nach Tanaris."}]])
R(3528,"Der Gott Hakkar",[[description="Jetzt wird es Zeit, die Essenz des Avatars von Hakkar einzufangen.$B$BBringt das Ei von Hakkar in das Sanktum des Gefallenen Gottes im Versunkenen Tempel in Azeroth. Ruft die Macht des Eies an, um den toten Gott aufzuwecken.$B$BEr wird seine Diener gegen Euch ausschicken. Besiegt seine Bluttrinker und nehmt ihr Hakkari-Blut an Euch; dann benutzt das Blut, um die ewigen Flammen auszulöschen, die Hakkars Geist halten. Erst wenn alle Flammen gelöscht sind, wird der Avatar von Hakkar unsere Welt betreten.$B$BBesiegt ihn und gebt seine Essenz in das Ei von Hakkar.",objectives={"Bringt das gefüllte Ei von Hakkar zu Yeh'kinya nach Tanaris."}]])
R(3529,"<UNUSED>")
R(3541,"Lieferung an Jes'rimon",[[description="Ich kenne einen Hehler in Orgrimmar. Er wohnt in der Gasse. Er ist ziemlich schwer zu finden, wenn Ihr nicht wisst, wo Ihr suchen sollt. Wenn Ihr Euch dort in einem der höchsten Gebäude umschaut, solltet Ihr ihn jedoch ohne Probleme finden können.$B$BTut mir aber bitte einen Gefallen und posaunt nicht in ganz Kalimdor herum, dass er dort ist und was er so tut, das wäre schlecht für uns beide.$B$BEr wird uns einen mehr als fairen Preis für die Schrifttafel von Jin'yael geben. Ich weiß zwar nicht genau warum, aber Ihr hättet mal sehen sollen, wie aufgeregt er war, als er von ihrem Aufenthaltsort erfahren hat.",objectives={"Bringt die Schrifttafel von Jin'yael zu Jes'rimon nach Orgrimmar."}]])
R(3542,"Lieferung an Andron Gant",[[description="Andron Gant ist mein nächster Kontakt. Normalerweise hält er sich in Undercity auf... ganz in der Nähe des Apothekariums.$B$BEr war ein bisschen redselig, als das Gespräch darauf kam, warum er die Schrifttafel haben wollte. Anscheinend wollen einige der Magier von Undercity die Arkanzauber studieren, die die Hochgeborenen benutzt haben. Sie glauben, dass ihnen diese Schrifttafel dabei helfen würde. Markri war sehr bewandert im Beschwören von Kreaturen, besonders von Elementaren.$B$BNehmt die Schrifttafel von Markri und kommt zu mir zurück, um Euch Euren Teil der Belohnung abzuholen.",objectives={"Bringt die Schrifttafel von Markri zu Andron Gant nach Undercity."}]])
R(3561,"Lieferung für Erzmagier Xylem",[[description="Die letzte Schrifttafel geht an eine sehr gefährliche Person, $N. Hört auf mich, wenn ich Euch sage, dass ich dieser Person viel weniger traue als irgendeiner der anderen, die Ihr in meinem Namen getroffen habt.$B$BErzmagier Xylem hat einen Turm in den Hügeln mit Ausblick auf ganz Azshara. Er ist zwar ein Mensch, aber er benimmt sich wie kein Mensch, den ich jemals getroffen ... oder getötet habe. Er strahlt Macht aus, und ich wage nicht, ihn zu fragen, was er mit der Schrifttafel vorhat.$B$BEr kam zu mir, aber er teilte mir mit, dass seine Leibwache Sanath mir helfen würde, zum Turm zu kommen, wenn ich bereit sei, ihn zu treffen. Sucht nach Sanath im Norden.",objectives={"Bringt die Schrifttafel von Sael'hai zu Erzmagier Xylem in Azshara."}]])
R(3562,"Magathas Bezahlung für Jediga",[[description="Bringt diese Notiz zu Jediga. Sagt ihr, dass ihre Bezahlung hier auf sie wartet, wenn sie zurückkommt. Und sagt ihr, dass ich mit ihrer Arbeit zufrieden bin.$B$BBeeilt Euch, $n. Sagt Eurer Meisterin, dass ich hier auf sie warten werde.",objectives={"Bringt Magathas Notiz zu Jediga in Azshara."}]])
end f(R) end
do local function f(R)
R(3563,"Jes'rimons Bezahlung für Jediga",[[description="Bringt diesen Brief zu Jediga. Lasst sie wissen, dass unser Handel vorteilhaft ist und ich mit ihrer Arbeit zufrieden bin.$B$BSagt ihr, sie soll schnell nach Orgrimmar zurückkommen, und Jes'rimon würde gut für sie sorgen.$B$BSagt ihr das! Und, vielleicht benötige ich in Zukunft noch einmal Eure Dienste, $N.",objectives={"Bringt Jes'rimons Notiz zu Jediga in Azshara."}]])
R(3564,"Androns Bezahlung für Jediga",[[description="Hier... bringt... <hick> das zu Jediga. Viel Glück!",objectives={"Bringt Androns Notiz zu Jediga in Azshara."}]])
R(3565,"Xylems Bezahlung für Jediga",[[description="Was ist? Oh, ja, Eure Bezahlung. Natürlich.$B$BNehmt das und fort mit Euch. Jediga wartet bestimmt schon voller Geduld auf Eure Rückkehr.",objectives={"Bringt Xylems Notiz zu Jediga in Azshara."}]])
R(3566,"Erhebt Euch, Obsidion!",[[description="Es... Es... Es war alles eine Falle.$B$BVergebt... mir.$B$BTötet den Bastard... Tötet ihn für uns... für Thorius.",objectives={"Tötet Lathoric den Schwarzen und Obsidion. Kehrt zurück zu Thorius nach Ironforge mit dem Kopf von Lathoric dem Schwarzen und dem Herzen von Obsidion."}]])
R(3567,"An die Spitze")
R(3568,"Verbreitete Verderbnis",[[description="Seht Ihr die Tauren hinter mir - diejenige, die aussieht, als müsste sie sich jeden Moment übergeben? Sie war erst vor kurzem in Azshara. Sie behauptet, dass sie von einigen Naga verwundet wurde, als sie sich den Weg durch die Ruinen von Eldarath bahnte.$B$BNachdem sie einige von ihnen zurückschlagen konnte, machte sie eine Pause am Strand und trank aus einem der Gezeitenteiche. Jetzt ist ihr ein wenig übel ... unter anderem.$B$BIch würde gern herausfinden, was sie getrunken hat. Nehmt diesen Kasten, darin befinden sich einige leere Phiolen, die ich mit Etiketten versehen habe. Füllt jede an einem anderen Teich und kehrt dann zurück.",objectives={"Füllt alle 4 leeren Phiolen an den Gezeitenteichen entlang der Küste der Ruinen von Eldarath in Azshara und kehrt dann zu Chemiker Cuely zurück."}]])
R(3569,"Verbreitete Verderbnis",[[description="Gebt das Thersa. Vielleicht wird das hier sie heilen... vielleicht aber auch nicht. Wir werden es nicht wissen, solange sie es nicht getrunken hat.",objectives={"Gebt Cuelys Elixier Thersa Windsong in Undercity."}]])
R(3570,"Verbreitete Verderbnis")
R(3581,"Plainsrunning",[[description="Imagine yourself racing across the plains, through forests and over mountains, the wind in your face... Traveling over unseen territory",objectives={"Speak to Saern Priderunner again to learn the Plainsrunning skill."}]])
R(3601,"Kim'jael, fürwahr!",[[description="Kim'jael, fürwahr! Wisst Ihr, was Kim'jael für die Blutelfen bedeutet, $N? Kleine Ratte... oder so etwas in der Art. Diese großen Angeber!$B$BSie haben mich angeworben, damit ich ihnen helfe, das Gebiet auszukundschaften und nach einer Art verlorenen Schatz zu suchen. Natürlich habe ich sofort zugegriffen, als sie das Wort 'Schatz' erwähnten und die Summe, die sie mir bezahlen wollten. Aber dann haben sie sich gegen mich gewandt und versucht, mich zu töten... MICH!$B$BDas zeigt einmal mehr, dass einem Blutelfen nicht zu trauen ist.$B$BMein Problem ist: Sie haben immer noch meine Ausrüstung, und ich kann sie nicht wiederbekommen. Helft Ihr mir?",objectives={"Durchsucht den Thalassian-Stützpunkt nach Kim'jaels Kompass, Zielfernrohr, ausgestopftem Huhn und Wizzlegoober und bringt ihm dann alles nach Azshara zurück."}]])
R(3602,"Azsharit",[[description="Die uralten Klippenriesen aus dem südlichen Azshara ernähren sich von Felsen und Gebäuden des Landes. Ihre Ausscheidung ist, bedingt durch die Ernährung, ein höchst formbarer und extrem starker Kristall, der als Azsharit bekannt ist.$B$BDer südliche Bogen ist übersät mit diesen Gebilden, aber es konnten nur wenige geborgen werden, da die Riesen über ein extrem angriffslustiges Naturell verfügen.$B$BIhr sollt nach Süden vorstoßen und genügend Azsharit einsammeln, um den Waffenkörper herzustellen. Meine Teufelshunde werden Euch beim Einsammeln der Kristalle behilflich sein.",objectives={"Sammelt 20 kristallisierte Azsharite im südlichen Azshara. Ihr könnt den Teufelshund benutzen, damit er Euch beim 'Erschnüffeln' der gut versteckten Ablagerungen behilflich ist.$B$BKehrt zu Loramus zurück, sobald Ihr die Aufgabe erfüllt habt."}]])
R(3621,"Die Herstellung von Teufelsbann",[[description="Die Waffen können jetzt geschmiedet werden. Ihr müsst den ausgehärteten Azsharit zu jemandem bringen, der die Fähigkeit besitzt, Teufelsenergie zu bändigen.$B$BIm Schlingendorntal gibt es einen solchen Schmied. Galvan der Alte, Anführer des Mithrilordens, wird die Waffen nach Euren Angaben fertigen. Ihr könnt sein Lager zwischen Zul'Gurub und dem Ogerhügel der Mosh'Ogg finden.$B$BMögen Eure Entschlossenheit und Euer Glaube Euch durch diese Tortur leiten. Solltet Ihr versagen, wisset, dass Euer Gott auf Euch herablächelt, sterbliches Wesen.",objectives={"Bringt die Lieferung zu Galvan dem Alten im Schlingendorntal."}]])
R(3622,"<UNUSED>")
R(3625,"Verzauberte Azsharit-Teufelswaffe",[[description="$n, die Herstellung jeder einzelnen Waffe wird einige Zeit in Anspruch nehmen.$B$BAußerdem dürft Ihr die Macht des Teufelsfluchs nur einmal alle drei Minuten verwenden. Seine schwächenden Eigenschaften gegen Razelikh den Entweiher und seine Diener können unterschiedlich lang dauern. Aus diesem Grund dürft Ihr den Teufelsfluch erst dann freigeben, wenn der richtige Zeitpunkt gekommen ist!$B$BGebt mir jetzt einen Moment, damit ich Eure Waffen fertigen kann, $n.",objectives={"Wartet, bis Galvan die Waffen fertig geschmiedet hat."}]])
R(3626,"Rückkehr in die verwüsteten Lande",[[description="Die Stunde der Erlösung rückt näher, $n. Ihr müsst mit Eurer neuen Waffe in die Verwüsteten Lande zurückkehren und mit dem Gefallenen Helden der Horde sprechen, um Eure letzte Aufgabe zu erhalten.",objectives={"Kehrt zum Gefallenen Helden der Horde zurück."}]])
R(3627,"Das zerbrochene Amulett vereinen",[[description="Um den Entweiher zu erreichen, müsst Ihr zunächst das Dreigestirn der Macht zerstören und die Teile des Amuletts beschaffen. Wenn Ihr alle drei Teile beschafft habt, kommt zu mir zurück, und ich werde Euch weitere Anweisungen geben.$B$BGeht, $n! Auf in die Verwüsteten Lande! Sevine, Allistarj und Grol müssen fallen!",objectives={"Tötet Grol den Zerstörer, Lady Sevine und Erzmagier Allistarj. Nehmt das Amulett von Grol, das Amulett von Sevine und das Amulett von Allistarj von ihren Leichen.$B$BDenkt daran, Eure Verzauberte Azsharit-Teufelswaffe zu BENUTZEN, um die Triade zu schwächen. Auf eine andere Weise können sie nicht getötet werden - aber verwendet sie weise ..."}]])
R(3628,"Ihr seid Rakh'likh, Dämon",[[description="Razelikhs Unterschlupf befindet sich auf dem Gipfel des höchsten Berges in den Verwüsteten Landen. Einzig durch Einsatz der Teleport-Runen in der Nähe des Berges kann man zu diesem Unterschlupf gelangen. Solange Ihr das Amulett habt, könnt Ihr den Unterschlupf erreichen. Nachdem Ihr erst den Unterschlupf erreicht habt, müsst Ihr die Bestie herbeizaubern. Das Amulett ist Euer Schlüssel, $n. Benutzt es auf dem Altar des Entweihers.$B$BFalls Ihr den Entweiher besiegen könnt, bringt sein Horn zurück. Es wird ein Symbol der Hoffnung für alle sein, die es sehen, ein Beweis dafür, dass es tatsächlich Helden in dieser vom Krieg zerrissenen Welt gibt.",objectives={"Vernichtet Razelikh den Entweiher und bringt das abgespaltene Horn des Entweihers zum Gefallenen Helden der Horde. Ihr müsst außerdem den Zauberschutz des Entweihers mit zurückbringen, damit der Gefallene Held ihn zerstören und somit verhindern kann, dass er jemals in die falschen Hände fällt."}]])
R(3629,"Goblin-Ingenieurskunst",[[description="Experten-Ingenieurskunst beinhaltet zwei unterschiedliche Disziplinen: für Gnome und für Goblins. Ich erwähne Goblin-Ingenieurskunst nur, weil ich ein fairer Lehrer bin. Sie machen gern Dinge, die in die Luft gehen und es ist ihnen dabei meistens egal, ob was im Weg herumsteht - auch wenn sie es selbst sind.$B$B$N, lest diese Anleitung. Wenn Ihr lernen wollt, Euch selbst in die Luft zu jagen, dann bringt sie zu Nixx Sprocketspring nach Gadgetzan. Denkt daran - das ist eine dauerhafte Mitgliedschaft, es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.",objectives={"Wenn Ihr etwas über die Goblin-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan."}]])
R(3630,"Gnomen-Ingenieurskunst",[[description="Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen auf: für Gnome und für Goblins. Gnomen-Ingenieurskunst ist die weit Überlegenere der beiden! Es geht um die Konstruktion von wunderbaren Apparaten und Geräten, die das Leben schöner machen.$B$B$N, lest diese Anleitung. Wenn Ihr mehr über Gnomen-Ingenieurskunst lernen wollt, dann bringt sie zu Tüftlermeister Overspark in Ironforge. Denkt daran - das ist eine dauerhafte Mitgliedschaft und es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr Euch absolut sicher sein, dass Ihr Euch sicher seid, bevor Ihr seine Aufgabe ausführt.",objectives={"Wenn Ihr etwas über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Tüftlermeister Overspark nach Ironforge."}]])
R(3631,"Teufelsross beschwören",[[description="Hmpf. Ich sage, Ihr seid nicht vorbereitet, aber das ist nicht meine Entscheidung. Strahad empfindet das anders und es ist seine Entscheidung... dieses Mal.$B$BEr wünscht mit Euch zu sprechen, und das schnell. Ihr werdet ihn immer noch über Ratchet im Brachland finden, in seinem kleinen Turm dort, mit seinen Akolyten.$B$BTrödelt nicht herum.",objectives={"Sprecht mit Strahad Farsan im Brachland."}]])
R(3632,"Gnomen-Ingenieurskunst",[[description="Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen auf: Gnom und Goblin. Gnomen-Ingenieurskunst ist die weit Überlegenere der beiden! Es geht um die Konstruktion von wunderbaren Apparaten und Geräten, die das Leben schöner machen.$B$B$N, lest diese Anleitung. Wenn Ihr mehr über Gnomen-Ingenieurskunst lernen wollt, dann bringt sie zu Tüftlermeister Overspark hier in Ironforge. Denkt daran - das ist eine dauerhafte Mitgliedschaft und es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr Euch absolut sicher sein, dass Ihr Euch sicher seid, bevor Ihr seine Aufgabe ausführt.",objectives={"Wenn Ihr etwas über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Tüftlermeister Overspark nach Ironforge."}]])
R(3633,"Goblin-Ingenieurskunst",[[description="Bei der Experteningenieurskunst gibt es zwei unterschiedliche Disziplinen: Gnom und Goblin. Natürlich ist die Goblin-Ingenieurskunst die Wahl aller brillanten Ingenieure. Durch den klugen Einsatz von hochempfindlichen Sprengstoffen und phantastischen Ausrüstungsgegenständen lernt Ihr, die Welt zu meistern!$B$B$N, lest diese Anleitung. Wenn Ihr etwas über Goblin-Ingenieurskunst wissen wollt, dann bringt sie zu Nixx Sprocketspring nach Gadgetzan. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.",objectives={"Wenn Ihr etwas über die Goblin-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan."}]])
R(3634,"Gnomen-Ingenieurskunst",[[description="Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen auf: für Gnome und für Goblins. Ich bin zwar der Meinung, dass es Verschwendung ist, aber Ihr solltet doch etwas über die Gnomen-Spezialisierung wissen. Sie machen Geräte und Apparate, die angeblich die Welt verändern, aber meistens gar nicht funktionieren.$B$B$N, lest diese Anleitung. Wenn Ihr lernen wollt, wie man Briefbeschwerer aus Metall herstellt, dann bringt sie zu Tüftlermeister Overspark in Ironforge. Denkt daran - das ist eine dauerhafte Mitgliedschaft und es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr Euch absolut sicher sein, dass Ihr Euch sicher seid, bevor Ihr seine Aufgabe ausführt.",objectives={"Wenn Ihr etwas über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Tüftlermeister Overspark nach Ironforge."}]])
R(3635,"Gnomen-Ingenieurskunst",[[description="Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen: Gnom und Goblin. Ich bin zwar der Meinung, dass es reine Verschwendung ist, aber Ihr solltet doch etwas über die Spezialisierung der Gnome wissen. Sie machen Gegenstände und Apparate, die angeblich die Welt verändern, aber meistens gar nicht funktionieren.$B$B$N, lest diese Anleitung. Wenn Ihr lernen wollt, wie man Briefbeschwerer aus Metall herstellt, dann bringt sie zu Oglethorpe Obnoticus in Booty Bay. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.",objectives={"Wenn Ihr mehr über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Oglethorpe Obnoticus nach Booty Bay."}]])
R(3636,"Das Licht bringen",[[description="Die Geißel ist eine dauerhafte Bedrohung für die Allianz. Ich bin sicher, Euch ist diese Tatsache vertraut. Kürzlich erst stießen wir auf einige sehr seltsame Funde, $N.$B$BIm Brachland gibt es ein fürchterliches Dickicht von Dornsträuchern, das Hügel von Razorfen heißt. Früher war es die Heimat von einfachen Stachelebern, aber nun ist offensichtlich, dass ein Pakt mit der Geißel geschlossen wurde, die viel schlimmere Kreaturen hervorbrachte... Sie werden jetzt von dem Lich, Amnennar dem Kältebringer, beherrscht.$B$BStellt Euch auf die Seite des Lichts, $N, und macht diesem bösen Verbund ein Ende.",objectives={"Erzbischof Benedictus will, dass Ihr Amnennar den Kältebringer in den Hügeln von Razorfen tötet."}]])
R(3637,"Gnomen-Ingenieurskunst",[[description="Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen: Gnom und Goblin. Ich bin zwar der Meinung, dass es reine Verschwendung ist, aber Ihr solltet doch etwas über die Spezialisierung der Gnomen wissen. Sie machen Gegenstände und Apparate, die angeblich die Welt verändern, aber meistens gar nicht funktionieren.$B$B$N, lest diese Anleitung. Wenn Ihr lernen wollt, wie man Briefbeschwerer aus Metall herstellt, dann bringt sie zu Oglethorpe Obnoticus in Booty Bay. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.",objectives={"Wenn Ihr mehr über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Oglethorpe Obnoticus nach Booty Bay."}]])
R(3638,"Der Schwur der Geheimhaltung",[[description="Bei der Goblin-Ingenieurskunst geht es um praktische Anwendungen mit hohem Profit und noch höherer Explosionskraft! Unsere Baupläne ermöglichen uns, mächtige Bomben und gewaltige Waffen hervorzubringen. Die Anleitung, die Ihr gelesen habt, berichtet darüber.$B$BDie Anleitung erwähnt auch unser uraltes Gelöbnis der Geheimhaltung unserer Baupläne. Sobald Ihr ein Goblin-Ingenieur geworden seid, war's das. Es gibt keinerlei Zugang zur Gnomen-Ingenieurskunst.$B$BWenn Ihr immer noch ein Goblin-Ingenieur werden wollt, dann unterzeichnet dieses Dokument, mit dem Ihr eine lebenslange Geheimhaltung gelobt, und sprecht dann wieder mit mir. Denkt gut darüber nach, $N.",objectives={"Wenn Ihr ein Goblin-Ingenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Nixx Sprocketspring in Gadgetzan sprechen."}]])
R(3639,"Zeigt Eure Arbeit",[[description="Als Euer Mentor will ich Proben Eurer Arbeit sehen. Ihr seid ein geschickter Ingenieur, das steht ganz außer Frage, $N. Ich möchte sie gern analysieren, um Möglichkeiten zu erarbeiten, Goblin-orientierte Techniken in Euren zukünftigen Bemühungen noch weiter zu unterstreichen. Ich brauche Folgendes: Zwanzig große Eisenbomben, zwanzig Stäbe robustes Dynamit und fünf explosive Schafe - und achtet darauf, dass sie gesichert sind!$B$BBringt mir diese Gegenstände und ich werde Euch Eure eigene Goblin-Ingenieur-Mitgliedskarte ausstellen, die notwendig ist, um Zugang zu allen Goblin-Ingenieurskunstlehrern zu erhalten!",objectives={"Bringt 20 große Eisenbomben, 20 robuste Dynamitstangen und 5 explosive Schafe zu Nixx Sprocketspring nach Gadgetzan."}]])
R(3640,"Der Schwur der Geheimhaltung",[[description="Die Gnomen-Ingenieurskunst beruht auf der Ingenieurskunsttheorie, die besagt, dass sie unseren Bedürfnissen zu dienen hat! Unsere Baupläne ermöglichen uns, Geräte hervorzubringen, die die Welt um uns kontrollieren. Die Anleitung, die Ihr gelesen habt, berichtet darüber.$B$BDie Anleitung erwähnt auch unser uraltes Gelöbnis der Geheimhaltung unserer Baupläne. Sobald Ihr ein Gnomen-Ingenieur geworden seid, war's das. Es gibt keinerlei Zugang zur Goblin-Ingenieurskunst.$B$BWenn Ihr immer noch ein Gnomen-Ingenieur werden wollt, dann unterzeichnet dieses Dokument, mit dem Ihr eine lebenslange Geheimhaltung gelobt, und sprecht dann wieder mit mir. Denkt gut darüber nach, $N.",objectives={"Wenn Ihr ein Gnomen-Ingenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Tüftlermeister Overspark in Ironforge sprechen."}]])
R(3641,"Zeigt Eure Arbeit",[[description="Als Euer Mentor will ich einige Proben Eurer Arbeit sehen. Ihr seid ein geschickter Ingenieur, das steht ganz außer Frage, $N. Ich möchte Eure Arbeit daher analysieren, um Möglichkeiten zu erarbeiten, Gnomen-orientierte Techniken in Euren zukünftigen Bemühungen noch weiter zu fördern. Ich brauche folgende Proben: 6 Mithrilröhren, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen.$B$BBringt mir diese Gegenstände und ich werde Euch Eure höchsteigene Gnomen-Ingenieur-Mitgliedskarte ausstellen, die notwendig ist, um Zugang zu allen Gnomen-Ingenieurskunstlehrern zu erhalten!",objectives={"Bringt 6 Mithrilröhren, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen zu Tüftlermeister Overspark in Ironforge."}]])
R(3642,"Der Schwur der Geheimhaltung",[[description="Die Gnomen-Ingenieurskunst beruht auf der Ingenieurskunsttheorie, die besagt, dass sie unseren Bedürfnissen zu dienen hat! Unsere Baupläne ermöglichen uns, Geräte hervorzubringen, die die Welt um uns kontrollieren. Die Anleitung, die Ihr gelesen habt, berichtet darüber.$B$BDie Anleitung erwähnt auch unser uraltes Gelöbnis der Geheimhaltung unserer Baupläne. Sobald Ihr ein Gnomen-Ingenieur geworden seid, war's das. Es gibt keinerlei Zugang zur Goblin-Ingenieurskunst.$B$BWenn Ihr immer noch ein Gnomen-Ingenieur werden wollt, dann unterzeichnet dieses Dokument, mit dem Ihr eine lebenslange Geheimhaltung gelobt, und sprecht dann wieder mit mir. Denkt gut darüber nach, $N.",objectives={"Wenn Ihr ein Gnomen-Ingenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Oglethorpe in Booty Bay sprechen."}]])
R(3643,"Zeigt Eure Arbeit",[[description="Als Euer Mentor will ich einige Proben Eurer Arbeit sehen. Ihr seid ein geschickter Ingenieur, das steht ganz außer Frage, $N. Ich möchte Eure Arbeit daher analysieren, um Möglichkeiten zu erarbeiten, Gnomen-orientierte Techniken in Euren zukünftigen Bemühungen noch weiter zu fördern. Ich brauche folgende Proben: 6 Mithrilröhren, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen.$B$BBringt mir diese Gegenstände und ich werde Euch Eure höchsteigene Gnomen-Ingenieur-Mitgliedskarte ausstellen, die notwendig ist, um Zugang zu allen Gnomen-Ingenieurskunstlehrern zu erhalten!",objectives={"Bringt 6 Mithrilröhren, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen zu Oglethorpe Obnoticus in Booty Bay."}]])
R(3644,"Mitgliedskarten-Erneuerung")
R(3645,"Mitgliedskarten-Erneuerung")
R(3646,"Mitgliedskarten-Erneuerung",[[description="wird beim Anblick eines sterbenden Jungtiers wütend!"]])
R(3647,"Mitgliedskarten-Erneuerung")
R(3661,"Elunes Lieblinge?",[[description="Wildekins sind unberechenbare Kreaturen, $N. Sie sind zu einer außerordentlichen Zärtlichkeit fähig, aber diese Kreaturen können auch eine enorme Wildheit an den Tag legen, wenn etwas für sie sehr Wichtiges bedroht wird.$B$BDiese Kreaturen wurden angeblich von Elune geschaffen und ich bin daran interessiert herauszufinden, ob dies wirklich der Wahrheit entspricht.$B$BVor kurzem habe ich etwas von einer Population von Wildekins gehört, die im Hinterland leben - heimtückische, primitive und wilde Eulenbestien. Man findet sie unter den wild lebenden Tieren dort. Würdet Ihr einige Wildekin-Federn für mich sammeln?",objectives={"Sammelt 15 Wildekinfedern aus dem Hinterland für Erelas Ambersky in Rut'theran."}]])
R(3681,"Foliant der Offenbarung",[[description="Verzeiht, dass wir Eure Reise unterbrechen, $R, aber ich dachte, Ihr solltet wissen, dass uns vor kurzem eine Meldung aus Stormwind erreicht hat, dass sich Paladine zum Training dort melden sollen.$B$BWenn ich es nicht besser wüsste, würde ich sagen, dass bald etwas Besonderes geschehen wird und es für Euch an der Zeit ist, die Folianten zu studieren.$B$BSucht Duthorian Rall in Stormwind auf. Er trainiert für gewöhnlich Paladine in der Kathedrale des Lichts.",objectives={"Sprecht mit Duthorian Rall in Stormwind."}]])
R(3701,"Die glimmenden Ruinen von Thaurissan",[[description="Begebt Euch zu den glimmenden Ruinen von Thaurissan in der brennenden Steppe und sammelt so viele Informationen wie möglich.$B$BEs heißt, dass geheimnisvolle Relikte in den Ruinen verstreut seien. Vielleicht solltet Ihr Eure Suche dort beginnen, $N. Nehmt Euch vor den Thaurissan-Wächtern in Acht: Es sind Auftragsmörder, die die Ruinen bewachen und die dort möglicherweise noch immer begrabenen Geheimnisse beschützen, wie auch immer sie aussehen mögen.",objectives={"Begebt Euch zu den Ruinen von Thaurissan in der brennenden Steppe und sammelt Informationen über die Thaurissan-Relikte. Kehrt zur königlichen Historikerin Archesonus zurück, wenn Ihr die Informationen besorgt habt."}]])
R(3702,"Die glimmenden Ruinen von Thaurissan",[[description="Würdet Ihr gern einen Überblick über die Geschichte der Dunkeleisenzwerge erhalten?",objectives={"Hört die Erzählung der königlichen Historikerin Archesonus über die Geschichte von Thaurissan."}]])
R(3721,"Ein eigener OOX")
R(3741,"Hilarys Halskette",[[description="Meine Freundin Hilary hat ihre Halskette verloren und wir können sie einfach nicht finden. Den ganzen Tag lang fischen wir schon hier und haben auch schon rundum überall gesucht. Ich kann mir nur vorstellen, dass sie in den See gefallen ist. Unsere Eltern möchten nicht, dass wir im See schwimmen... meine Mama sagt, dass es unter Wasser ein paar garstige Dinge gibt, aber Ihr seht aus, als ob Ihr keine Angst vor garstigen Dingen hättet.$B$BKönnt Ihr die Kette bitte für uns suchen?",objectives={"Sucht Hilarys Halskette und bringt sie Hilary in Seenhain zurück."}]])
R(3761,"Un'Goro-Erde",[[description="Die Erde des Un'Goro Kraters ist angeblich reich an starken magischen Eigenschaften. Der Zirkel des Cenarius möchte diese Erde in großen Mengen untersuchen; zieht daher in die Wildnis von Un'Goro und sammelt genug davon für unsere ständig laufenden Forschungen.$B$BDie angereicherte Erde ist manchmal zu Haufen aufgeworfen und einige der Wildtiere könnten vielleicht nützliche Proben bei sich haben. Bringt sie raus zu Ghede; sucht einfach nach den Erdhaufen und dem Tauren, der Befehle brüllt. Er ist kein schlechter Kerl, aber verärgert ihn lieber nicht!",objectives={"Bringt 20 Un'Goro-Erdproben zu Ghede in Thunder Bluff."}]])
R(3762,"Erzdruide Runetotem helfen",[[description="Entschuldigung, $C, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?$B$BDer Zirkel des Cenarius in Thunder Bluff ist sehr an erfahrenen Abenteurern wie Euch interessiert, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein Geringerer als Hamuul Runetotem an der Spitze dieses Projektes steht.$B$BBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm auf der Anhöhe der Ältesten in Thunder Bluff.",objectives={"Sprecht in Thunder Bluff mit Erzdruide Hamuul Runetotem."}]])
R(3763,"Erzdruide Staghelm helfen",[[description="Entschuldigung, $C, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?$B$BDer Zirkel des Cenarius in Darnassus sucht nach erfahrenen Abenteurern wie Euch, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein geringerer als Erzdruide Fandral Staghelm an der Spitze dieses Projektes steht.$B$BBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm in der Enklave des Cenarius in Darnassus.",objectives={"Sprecht mit Erzdruide Fandral Staghelm in Darnassus."}]])
R(3764,"Un'Goro-Erde",[[description="Die Erde des Un'Goro Kraters ist angeblich reich an starken magischen Eigenschaften. Ich möchte Wahrheit von Unwahrheit unterscheiden; begebt Euch daher in die Wildnis von Un'Goro und sammelt ausreichend hochwertige Erdproben für unsere ständig laufenden Studien.$B$BIhr glaubt möglicherweise, dass die Aufgabe, etwas zu sammeln, unter Eurer Würde sei; doch mit solch einer Einstellung macht Ihr Euch weder bei mir noch beim Zirkel des Cenarius beliebt. Bringt die Proben zu Jenal, der zweifellos draußen hinter diesem Baum müßig herumlungert; sucht einfach nach den Erdhaufen. Er wird sich um die Logistik kümmern, nicht ich.",objectives={"Bringt 20 Un'Goro-Erdproben zu Jenal in Darnassus."}]])
R(3765,"Verderbnis in der Fremde",[[description="Stormwind - geschäftiger Dreh- und Angelpunkt der Aktivität.$b$bIch bin weit gereist, um Hilfe zu suchen. Man hört häufig, dass mutige Abenteurer durch die Straßen dieser Stadt ziehen.$b$bMein Bruder Gershala benötigt Hilfe in Dunkelküste. Er lebt in der Küstenstadt Auberdine.$b$bDie Reise ist lang und abenteuerlich. Daher suche ich nach Hilfe. Es sollte ein erfahrener $C sein, so wie Ihr.",objectives={"Reist zu Gershala Nightwhisper in Auberdine."}]])
R(3781,"Morgenkornforschung",[[description="Mit dem, was wir einen Immergrünbeutel nennen, haben wir Tharlendrissamenkörner in der Erde vom Un'Goro Krater kultiviert. Diese Samenkörner sind zu einer Ansammlung wirksamer Kräuter erblüht. Ein Ergebnis ist das Morgenkorn, ein rätselhaftes Kraut, von dem wir wenig wissen; ich habe vor, dieses Geheimnis zu enthüllen.$B$BBringt das nach unten zu Mathrengyl, und er wird Euch einige Samenkörner geben, mit denen Ihr beginnen könnt. Wenn Ihr diese verbraucht habt, müsst Ihr weitere von ihm kaufen.",objectives={"Bringt den Samenkorngutschein des Erzdruiden zu Mathrengyl Bearwalker in der Enklave des Cenarius von Darnassus."}]])
R(3782,"Morgenkornforschung",[[description="Mit dem, was wir einen Immergrünbeutel nennen, haben wir Tharlendrissamenkörner in der Erde vom Un'Goro Krater kultiviert. Diese Samenkörner sind zu einer Ansammlung wirksamer Kräuter erblüht. Ein Ergebnis ist das Morgenkorn, ein rätselhaftes Kraut, von dem wir wenig wissen; ich hoffe, dieses Geheimnis für den Zirkel zu enthüllen.$B$BBringt diesen Gutschein zu meiner Tochter Bashana, und sie wird Euch einige Samenkörner geben, damit Ihr uns helfen könnt. Wenn Ihr diese verbraucht habt, müsst Ihr weitere von ihr kaufen.",objectives={"Bringt den Samenkorngutschein zu Bashana Runetotem in Thunder Bluff."}]])
R(3783,"Sind wir endlich da, Yeti?",[[description="Meine Freunde hatten immerzu tolle Ideen. Ich hatte nie das Gefühl mit ihnen mithalten zu können... bis heute! Gerade habe ich die Pläne für etwas Großes angefertigt! Wenn Ihr versprecht, es nicht zu erzählen, weihe ich Euch in das Geheimnis ein... $B$BIch werde einen mechanischen Yeti herstellen! Meine Freunde werden ganz bestimmt durchdrehen, wenn sie ihn sehen, aber wenn sie darüber hinweg sind, bin ich mir sicher, dass sie beeindruckt sein werden!$B$BFür den Anfang benötige ich dickes Yetifell von Eisdistelyetis. Werdet Ihr helfen? Ihr könnt sie im Südosten finden.",objectives={"Sammelt 10 dicke Yetifelle für Umi Rumplesnicker in Everlook."}]])
R(3784,"Erzdruide Runetotem helfen",[[description="Entschuldigung, $C, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?$B$BDer Zirkel des Cenarius in Thunder Bluff ist sehr an erfahrenen Abenteurern wie Euch interessiert, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein Geringerer als Hamuul Runetotem an der Spitze dieses Projektes steht.$B$BBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm auf der Anhöhe der Ältesten in Thunder Bluff.",objectives={"Sprecht in Thunder Bluff mit Erzdruide Hamuul Runetotem."}]])
R(3785,"Morgenkornforschung",[[description="Hier ist Euer Immergrünbeutel, den Ihr für die Nutzung der Tharlendrissamenkörner benötigen werdet. Ihr benötigt außerdem noch Un'Goro-Erdproben als Dünger für die Samenkörner. Verwendet einfach den Beutel, wenn Ihr alles habt; der Beutel wird den Rest erledigen.$B$BWenn Ihr genug Einheiten Morgenkorn habt, bringt sie mir hierher in die Enklave. Und belästigt bitte nicht den Erzdruiden; er ist ein sehr beschäftigter Mann und muss nicht jedes Mal gestört werden, wenn jemand mit einer Ladung Morgenkorn zurückkehrt!",objectives={"Benutzt einen Immergrünbeutel mit einem Paket Tharlendrissamenkörner sowie zwei Un'Goro-Erdproben, um Morgenkorn zu kultivieren.$B$BBringt 10 Einheiten Morgenkorn zu Mathrengyl Bearwalker in Darnassus."}]])
R(3786,"Morgenkornforschung",[[description="Hier ist Euer Immergrünbeutel, den Ihr für die Nutzung der Tharlendrissamenkörner benötigen werdet. Ihr benötigt außerdem noch Un'Goro-Erdproben als Dünger für die Samenkörner. Verwendet einfach den Beutel, wenn Ihr alles habt; der Beutel wird den Rest erledigen.$B$BWenn Ihr genug Einheiten Morgenkorn habt, bringt sie zu mir hierher auf die Anhöhe der Ältesten. Belästigt bitte nicht den Erzdruiden; er wird sehr mit den Forschungsarbeiten beschäftigt sein sowie mit den tausend anderen Sorgen, die er hat!",objectives={"Benutzt einen Immergrünbeutel mit einem Paket Tharlendrissamenkörner sowie zwei Un'Goro-Erdproben, um Morgenkorn zu kultivieren.$B$BBringt 10 Einheiten Morgenkorn zu Bashana Runetotem in Thunder Bluff."}]])
R(3787,"Jonespyres Bitte",[[description="Entschuldigung...$B$BEin Kollege von mir würde gern mit Euch über die Forschungsarbeiten sprechen, die Ihr zusammen mit dem Zirkel des Cenarius durchführt. Er ist ein Druide namens Quintis Jonespyre und lebt in der Festung Feathermoon in Feralas. Er würde gern mit Euch über Morgenkorn reden... und er würde es vorziehen, wenn unser Gespräch dem Erzdruiden nicht zu Ohren kommt.$B$BFalls Ihr interessiert seid, dann sprecht mit ihm; zweifellos wird alles klargelegt, wenn Ihr es tut.",objectives={"Sprecht mit Quintis Jonespyre in der Festung Feathermoon."}]])
R(3788,"Jonespyres Bitte",[[description="Entschuldigung...$B$BEin Kollege von mir würde gern mit Euch über die Forschungsarbeiten sprechen, die Ihr zusammen mit dem Zirkel des Cenarius durchführt. Er ist ein Druide namens Quintis Jonespyre und lebt hier in der Festung Feathermoon. Er würde gern mit Euch über Morgenkorn reden... und er würde es vorziehen, wenn unser Gespräch dem Erzdruiden nicht zu Ohren kommt.$B$BFalls Ihr interessiert seid, dann sprecht mit ihm; zweifellos wird alles klargelegt, wenn Ihr es tut.",objectives={"Sprecht mit Quintis Jonespyre in der Festung Feathermoon."}]])
R(3789,"Erzdruide Staghelm helfen",[[description="Entschuldigung, $C, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?$B$BDer Zirkel des Cenarius in Darnassus sucht nach erfahrenen Abenteurern wie Euch, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein geringerer als Erzdruide Fandral Staghelm an der Spitze dieses Projektes steht.$B$BBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm in der Enklave des Cenarius in Darnassus.",objectives={"Sprecht mit Erzdruide Fandral Staghelm in Darnassus."}]])
R(3790,"Erzdruide Staghelm helfen",[[description="Entschuldigung, $C, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?$B$BDer Zirkel des Cenarius in Darnassus sucht nach erfahrenen Abenteurern wie Euch, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein geringerer als Erzdruide Fandral Staghelm an der Spitze dieses Projektes steht.$B$BBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm in der Enklave des Cenarius in Darnassus.",objectives={"Sprecht mit Erzdruide Fandral Staghelm in Darnassus."}]])
R(3791,"Das Geheimnis des Morgenkorns",[[description="Lasst mich offen mit Euch sein, $n. Ich bin interessiert zu wissen - nein, ich muss es unbedingt wissen, warum der Erzdruide in Darnassus den Namen des Zirkels des Cenarius sowie dessen Mittel benutzt, um große Mengen Morgenkorn zu beschaffen. Ich bin ein Forscher - Flüche sind meine Spezialität. Ich habe gehört, dass Morgenkorn unter den richtigen Bedingungen Fähigkeiten verströmt wie andere Kräuter, die in primitiven Flüchen eingesetzt werden.$B$BIch möchte mehr darüber wissen und bitte Euch um Eure Hilfe. Bringt mir 10 Einheiten Morgenkorn und ich werde mich um Euch kümmern.",objectives={"Bringt 10 Einheiten Morgenkorn zu Quintis Jonespyre in der Festung Feathermoon."}]])
R(3792,"Morgenkorn für die Festung Feathermoon")
R(3801,"Dunkeleisenerbe",[[description="Seid gegrüßt, $N. Ich bin Franclorn Forgewright. Ja, der Franclorn Forgewright, der für die Stonewrought-Methode der Architektur verantwortlich ist. Ihr habt zweifellos während Eurer Abenteuer in unserer vom Krieg zerrissenen Welt eines meiner Werke durchquert oder habt auf einem gestanden.$B$BIhr fragt Euch wahrscheinlich, warum ich hier bin und was ich von Euch möchte - beides berechtigte Fragen.$B$BIch brauche natürlich Eure Hilfe. Im Austausch für Eure Hilfe gewähre ich Euch den Schlüssel zu den Tiefen meiner verfluchten Stadt.",objectives={"Sprecht mit Franclorn Forgewright, wenn Ihr daran interessiert seid, einen Schlüssel für die Hauptstadt zu erhalten."}]])
R(3802,"Dunkeleisenerbe",[[description="Ihr findet Fineous Darkvire jenseits des Rings des Gesetzes in der Halle des Handwerks. Tötet den elenden Wicht und nehmt Ironfel an Euch.$B$BBringt Ironfel zum Schrein von Thaurissan und legt den Hammer an seinen rechtmäßigen Ort: in die Hände der Statue, die mir zu Ehren aufgestellt wurde.$B$BSobald dieses getan ist, öffnet sich das Fach, in dem ich den Hauptschlüssel verborgen habe. Wichtiger jedoch ist: Ironfel wird für alle Zeiten in meinen Händen bleiben. Sollte jemand versuchen, den Hammer zu entfernen, werden Statue und Hammer bersten und für immer verloren sein.",objectives={"Erschlagt Fineous Darkvire und bergt den großen Hammer Ironfel. Bringt Ironfel zum Schrein von Thaurissan und legt ihn auf die Statue von Franclorn Forgewright."}]])
R(3803,"Morgenkorn nach Darnassus")
R(3804,"Morgenkorn nach Thunder Bluff")
R(3821,"Schreckensfels",[[description="Sha'ni wurde ausgeschickt, um Berichte über merkwürdige rituelle Aktivitäten zu untersuchen, die vor mehr als drei Wochen von den Feuermagenogern der brennenden Steppe kamen.$B$BGoretooth sagt mir, dass er noch nichts wieder von dieser Gruppe gehört hätte und dass es am besten sei, wenn ich einfach weitermache und mich auf meine Aufgabe konzentriere. Könnt Ihr Euch das vorstellen? Das ist doch meine Frau!$B$BIch kann meinen Posten nicht verlassen, $N, aber ich muss wissen, was aus Sha'ni geworden ist. Reist in die brennende Steppe und sucht nach ihr.",objectives={"Begebt Euch in die brennende Steppe und findet heraus, was aus Sha'ni Proudtusk geworden ist."}]])
R(3822,"Krom'Grul",[[description="Meine ganze Gruppe wurde gefangen genommen, $N. Alle wurden getötet - alle, außer mir.$B$BIhr Anführer Krom'Grul wollte mich für irgendein Ritual aufsparen.$B$BIch wurde von dem Biest an diesen Altar gekettet und brutal misshandelt. Mein körperliches Sein gab nach einer Stunde dieser Folter auf. Die Bestie riss mir dann meinen Ehenasenring aus dem Gesicht und steckte ihn an seinen Finger. Noch niemals habe ich solch eine Rohheit gesehen!$B$BFindet Krom'Grul und erledigt ihn! Bringt meinen Ring zurück zu Thal'trak.$B$BUnd, $N, sagt ihm, dass wir uns wiedersehen werden ... in einem anderen Leben.",objectives={"Holt Sha'nis Nasenring von Krom'Grul zurück und bringt ihn zu Thal'trak in Kargath. Durchsucht die verschiedenen Höhlen und Minen im Schreckensfels."}]])
R(3823,"Die Feuermagenoger auslöschen",[[description="Wir müssen unsere Feinde schlagen, bevor sie uns schlagen!$B$BIch werde es kurz machen, Soldat.$B$BDie Feuermagenoger der brennenden Steppe sind Verbündete der Orcs des Blackrockklans. Sie arbeiten eng mit diesen üblen Orcs zusammen, bewachen den mineralreichen Schreckensfels und halten die Nachschublinien ständig offen.$B$BHinterlasst Euer Zeichen, $N. Legt ihre Streitkräfte lahm und kehrt zu mir zurück, wenn der Auftrag erledigt ist.$B$B<Oralius greift in die Luft und macht eine erwürgende Bewegung.>$B$BICH BRING DICH UM, WINKY!",objectives={"Tötet 15 Ogermagier der Feuermägen, 7 Oger der Feuermägen sowie 7 Schläger der Feuermägen und kehrt zu Oralius zurück, wenn Ihr fertig seid."}]])
R(3824,"Gor'tesh der Schläger-Lord",[[description="Sie sind gelähmt, ich sag's Euch! Unser nächster Schlag muss entscheidend sein.$B$BDer Lord dieser Bestien, Gor'tesh, muss eliminiert werden. Wichtiger noch, sein Kopf muss zu mir zurückgebracht werden, damit ich die dritte Phase unseres Angriffs auf die Feuermagenoger vorbereiten kann.$B$BSeid gewarnt, Soldat, Gor'tesh regiert nicht vom Schreckensfelsen aus. Stattdessen befindet er sich in einem Gebäude der Blackrockorcs westlich vom Schreckensfelsen.$B$BEure Befehle sind daher einfach. Sucht Gor'tesh und hackt ihm seinen fetten Kopf ab. Kommt zurück, wenn Eure Aufgabe erledigt ist.$B$BKLAPPE HALTEN, WINKY!",objectives={"Sucht Gor'tesh irgendwo im Westen des Schreckensfelsens. Tötet Gor'tesh und bringt dann seinen abgehackten Kopf zu Oralius in der brennenden Steppe zurück."}]])
R(3825,"Ogerkopf auf einem Pfahl = Party",[[description="Jetzt müsst Ihr nur noch eine Sache erledigen, Soldat.$B$BIch habe mir die Freiheit genommen, Gor'teshs Kopf auf einen Pfahl zu stecken. Ihr sollt jetzt einfach diesen Kopf zur Spitze des Schreckensfelsens bringen und ihn in den Boden rammen. Wenn Ihr das getan habt, seht zu, wie diese feigen Oger um ihr Leben rennen! Nachdem Ihr Euren Spaß hattet, kommt zu mir zurück und ich werde Euch für all Eure harte Arbeit belohnen.$B$B<Oralius scheint seinen Bezug zur Realität zu verlieren.>",objectives={"Nehmt Gor'teshs abgehackten Kopf und platziert ihn auf dem Gipfel des Schreckensfelsens. Sucht nach einem weichen Erdhügel, um den Pfahl aufzustellen."}]])
R(3841,"Waise sucht Zuhause",[[description="Ach, hallo, $n. Ich freue mich sehr, Euch wiederzusehen. Wie war Eure Reise nach Darnassus?$B$BNa, Ihr seid bestimmt froh darüber, dass wir während Eurer Abwesenheit ziemliche Fortschritte gemacht haben. Wir haben sogar ein ganzes Nest voller Eier gerettet. Leider ist die Mutter gestorben, ehe wir sie gefunden haben.$B$BSagt mal, wollt Ihr nicht vielleicht so ein Tierchen haben? Es sieht aus, als würden sie bald schlüpfen, und dann brauchen sie $Geinen guten Vater:eine gute Mutter;. Was meint Ihr?$B$BWenn Ihr wirklich Interesse habt, dann bringt eines der Eier zu Quentin. Ihr findet ihn an der Rennbahn in der Schimmernden Ebene. Er kann Euch mehr darüber sagen.",objectives={"Sprecht mit Quentin in Tausend Nadeln."}]])
R(3842,"Kurz vor dem Schlüpfen",[[description="Die Moonweavers, wie? Überaus interessant. Schade, dass die Grimmlingflitzer nicht schätzen können, was es bedeutet, wenn diese beiden sich um sie kümmern. Beide sind überaus fähig und gut.$B$BSoso, sie haben Euch das Ei also geschenkt. Tja, dann solltet Ihr auch so lange dafür verantwortlich sein, wie Ihr dies wünscht. Das Junge scheint wohl schon bald zu schlüpfen, aber wir sollten trotzdem sichergehen, dass es gesund ist und keinen Schaden genommen hat.$B$BIch brauche lediglich zwei Elixiere der Seelenstärke für einen kleinen Zauber, der das Ei beschützen wird. Die übrigen Komponenten habe ich bereits hier.",objectives={"Bringt 2 Elixiere der Seelenstärke zu Quentin in Tausend Nadeln."}]])
R(3843,"Das neueste Mitglied der Familie",[[description="Ein prachtvolles Exemplar, $N. Wenn dieses Geschöpf das Heranreifen übersteht, dann wird es ein wahrhaft gesundes Tier sein!$B$BAber eines würde ich Euch noch vorschlagen, wenn Ihr es damit wirklich ernst meint - geht zum Aerie Peak im Hinterland. Sprecht dort mit einem Zwerg namens Agnar Beastamer. Er ist ein Tierführermeister und kann Euch bestimmt bei den letzten Stadien der Brutzeit behilflich sein.$B$BAber eilt Euch, $N, das Ei ist empfindlich und wird sich ohne die richtige Pflege nicht lange halten.",objectives={"Bringt Euer empfindliches Grimmlingflitzerei ins Hinterland und sprecht mit Agnar Beastamer, aber beeilt Euch. Ihr habt nur eine Stunde Zeit, ihn zu finden. Dann stirbt das Jungtier in dem Ei."}]])
R(3844,"Es ist für jeden ein Geheimnis",[[description="In Ufernähe liegt ein zerstörtes Floß. Das hier ist nur ein kleiner Tümpel, deswegen ist Euch nicht so ganz klar, wie das Floß hier landen konnte. Aber ein Blick auf die Bäume verrät Euch, dass der Wasserstand im Teich nicht unbedingt immer derselbe sein muss.$B$BVielleicht findet Ihr ja mehr heraus, wenn Ihr Euch ein bisschen in der Gegend umschaut ...",objectives={"Sucht in dem Tümpel nach einem Hinweis darauf, wem dieses havarierte Floß gehören könnte."}]])
R(3845,"Es ist für jeden ein Geheimnis",[[description=" Ihr greift nach dem Bündel und zieht es an Land. Vielleicht findet Ihr heraus, wem es gehört, wenn Ihr die Gegenstände darin untersucht.$B$BIn Marshals Zuflucht halten sich ein paar vereinzelte Reisende auf. Vielleicht lässt sich dort ja mehr herausfinden.",objectives={"Untersucht die Gegenstände in dem Bündel und bringt sie zu ihrem Besitzer."}]])
R(3861,"GLUCK!",[[description="Gack... gack... gack... GAGGACK!$B$BGack... gack... gack.$B$BDas Huhn sieht zu Euch hinauf und beginnt dann, mit seinen Krallen am Boden zu scharren. Ihr glaubt, dass es ein Wort schreibt, aber Ihr seid Euch nicht sicher, was es ist. Könnte es das sein... S-A-L-D-E-A-N? Bevor Ihr fragen könnt, dreht sich das Huhn weg und kümmert sich um seine Angelegenheiten.",objectives={"Beschafft Euch etwas Spezial-Hühnerfutter und kehrt zu dem Huhn zurück, das sich mit Euch angefreundet hat. Wenn Ihr es gefunden habt, dann benutzt erst /cheer, ehe Ihr dem Huhn das Spezial-Hühnerfutter gebt."}]])
R(3881,"Rettungsexpedition",[[description="Ich weiß zwar nicht, wie Ihr es bis hierher geschafft habt, aber Ihr seid Balsam für meine Augen! Ich heiße Williden Marshal und bin der Leiter eines neutralen Expeditionstrupps. Unsere jüngste und größte Unternehmung wurde von zahllosen Katastrophen begleitet. Die schlimmste davon war, dass wir die Wildheit des Un'Goro Kraters unterschätzt hatten.$B$BAls wir aus unseren Stützpunkten im südwestlichen und nordöstlichen Teil des Kraters flohen, ließen wir lebenswichtige Vorräte zurück. Ihr seht aus, als wärt Ihr recht stark und geschickt ... Könnt Ihr uns vielleicht dabei helfen, sie zurückzubekommen?",objectives={"Bringt eine Kiste mit Nahrungsmitteln und Forscherausrüstung zu Williden Marshal im Un'Goro Krater."}]])
R(3882,"Knochenklappern",[[description="Man sollte meinen, dass ich gern grabe, nur weil ich der Oberbuddler von Marshals Expeditionen bin. Es könnte schlimmere Dinge in der Welt geben... auch wenn mir gerade keines einfällt.$B$BJedenfalls sollten wir eigentlich in der Terrorflucht - PHANTASTISCHER Name übrigens - nach toten Stegodons und Dimetrodons graben. Na ja, es treiben sich von der Sorte auch noch eine Menge lebende Viecher dort herum! Wil und Hol beschäftigen sich immer mit dieser Todesfalle, daher benötigen wir diese Dinosaurierknochen. Obwohl, unter uns gesagt, wenn Ihr mir welche von einem lebenden Exemplar bringt, dann ist das genauso gut.",objectives={"Bringt 8 Dinosaurierknochen zu Spark Nilminer im Un'Goro Krater."}]])
R(3883,"Eine fremdartige Ökologie",[[description="Nur weil wir einen Rückschlag erlitten haben, heißt das noch lange nicht, dass unsere Forschungen ein Ende finden müssen! Bevor wir hier gelandet sind, untersuchten wir die Schwarmbauten der Gorishiinsekten im südlichen Teil des Kraters. Sie sind fremdartig und passen nicht zur ursprünglichen Ökologie des Un'Goro und wir wollen herausfinden, warum das so ist.$B$BIn ihrem Schwarmbauverbund muss es Larvenbrutstätten geben. Ihr könnt diesen Ort an der hängenden Raupenbrut erkennen. Hier, nehmt mit dieser Phiole eine Probe von der Schwarmbauwand in der Nähe der Brutstätten. Bringt sie dann zu mir zurück, damit ich sie untersuchen kann, aber seid vorsichtig!",objectives={"Verwendet die Kratzphiole, um damit eine Schwarmbauwandprobe von einer der Schwarmbrutstätten der Gorishi im Un'Goro Krater zu holen. Sucht nach den Kammern mit der hängenden Larvenbrut.$B$BBringt die Schwarmbauwandprobe zu Hol'anyee Marshal im Un'Goro Krater."}]])
R(3884,"Willidens Tagebuch",[[description="Ihr habt ein zerfleddertes Tagebuch zu Tage gefördert. Ein Teil davon ist noch lesbar; es scheint von einem gewissen Williden Marshal verfasst worden zu sein. Wenn das Tagebuch stimmt, dann muss Williden irgendwo im nördlichen Teil des Kraters zu finden sein. Dem Tagebuch zufolge haben er und seine Gefährten in den höheren Lagen des Kraters Schutz gesucht, nachdem ihre tiefer gelegenen Stützpunkte von den wilden Bestien überrannt wurden.",objectives={"Bringt das Tagebuch zu Williden Marshal zurück. Er befindet sich irgendwo im Un'Goro Krater."}]])
R(3885,"<NYI> <TXT> The Gadgetzan Run",[[description="Escort Me and Dadanga!",objectives={"Escort Petra and Dadanga!"}]])
R(3901,"Klappernde Skelette",[[description="Ihr habt den Verlassenen Euer Potenzial unter normalen Umständen gezeigt, $N. Jetzt wollen wir mal sehen, wie es damit bestellt ist, wenn Ihr unter Druck steht.$B$BDie klappernden Skelette, weitere hirnlose Diener des Lichkönigs, sind zähere Feinde als die Zombies, mit denen Ihr es bisher zu tun hattet. Auch hier heißt es wieder: Dünnt ihre Reihen aus und beweist den Verlassenen, dass Ihr der Aufgabe gewachsen seid. Frisch ans Werk ... und redet wieder mit mir, wenn Ihr fertig seid.",objectives={"Tötet 12 klappernde Skelette und kehrt zu Schattenpriester Sarvis in Deathknell zurück, wenn Ihr fertig seid."}]])
R(3902,"Beutesuche in Deathknell",[[description="Ihr da! Wenn Ihr Euch irgendwie nützlich machen wollt, dann hört zu!$B$BWir benötigen frisch erweckte Rekruten, die sich nach Deathknell begeben und dort nach allem suchen, was wir irgendwie gebrauchen können. Die Dinge werden sich höchstwahrscheinlich in gestapelten Kästen befinden. Wir rechnen damit, dass sich in Kürze weitere Rekruten erheben werden, und wenn wir nicht wollen, dass die nackt herumtappen, dann müssen wir wohl oder übel was für sie suchen.$B$BAlso, macht Euch an die Arbeit, elendes Knochengestell! Und ohne ein bisschen Eile gibt es auch keine Belohnung.",objectives={"Durchsucht Deathknell und Umgebung nach 6 Stücken aufgestöberter Ware und bringt sie zu Todeswache Saltain zurück."}]])
R(3903,"Milly Osworth",[[description="Ihr habt Euch als verlässlich erwiesen, $N. Verlässlich und ohne Angst, Euch auch mal die Hände schmutzig zu machen, wie?$B$BTja, eine Freundin von mir, Milly Osworth, hat ein paar Probleme. Sie ist mit ihrem Wagen auf der anderen Seite der Abtei, in der Nähe des Stalls. Ich bin mir sicher, sie könnte Eure Hilfe gut gebrauchen.",objectives={"Sprecht mit Milly Osworth."}]])
R(3904,"Millys Ernte",[[description="Eine Bande von Briganten, die Defias, sind in die Weinberge von Nordhain eingedrungen, als ich gerade bei der Weinlese war! Ich habe es den Wachen von Nordhain gemeldet und sie haben mir auch versprochen, dass sie sich darum kümmern würden, aber... Ich habe Angst um meine Traubenernte! Selbst wenn die Defias sie nicht stehlen, befürchte ich, dass unsere Wachen beim Vertreiben der Rohlinge alles zertrampeln.$B$BBitte, Ihr müsst mir helfen! Die meisten Trauben sind schon in Eimern gesammelt, aber ich habe sie in den Weinbergen im Südosten zurückgelassen.$B$BBringt mir diese Kisten! Rettet meine Ernte!",objectives={"Bringt 8 Kisten mit Millys Ernte zu Milly Osworth in der Nähe der Abtei von Nordhain."}]])
R(3905,"Traubenliste",[[description="Jetzt, wo meine Ernte in Sicherheit ist, bringt diese Traubenliste zu Bruder Neals. Er ist verantwortlich für die Essens- und Getränkevorräte von Nordhain und ich bin mir sicher, er wird hoch erfreut sein zu hören, dass er frische Trauben bekommt.$B$BIhr findet Bruder Neals im Glockenturm der Abtei... wo er gern seinen Wein probiert.",objectives={"Bringt die Traubenliste zu Bruder Neals in der Abtei von Nordhain."}]])
R(3906,"Disharmonie der Flamme",[[description="Die Ältesten haben eine Störung der Elemente gespürt. Die Dunkeleisenzwerge haben einen üblen Geist in unsere Welt beschworen, durch den unser Land von einer ewigen Dürre heimgesucht werden könnte. Die Disharmonie der Flamme muss untersucht werden.$B$BBegebt Euch zum Blackrock und dann durch die Flammenschlucht in den Steinbruch. Dort werdet Ihr diesen Herrn des Feuers finden: Übermeister Pyron.$B$BMacht der Störung ein Ende und kehrt dann zu mir zurück.",objectives={"Reist zum Steinbruch am Blackrock und tötet Übermeister Pyron. Kehrt zu Thunderheart zurück, sobald Ihr den Auftrag erledigt habt."}]])
R(3907,"Disharmonie des Feuers",[[description="Ich kann die Verderbtheit in der Luft, die Euch umgibt, riechen, $N. Es gibt einen anderen, versteckt in den Tiefen von Blackrock, der diese Verderbtheit kontrolliert.$B$BDer Wind und die Erde schreien seinen Namen hinaus: Lord Incendius. Doch irgendjemand ... irgendetwas ... gebietet über dieses Wesen. Er ist nichts weiter als ein Abgesandter.$B$BSucht ihn und findet heraus, wo sich sein Meister versteckt hält. Kehrt zu mir zurück, sobald Ihr diese Information gesammelt habt.",objectives={"Betretet die Blackrocktiefen und spürt Lord Incendius auf. Tötet ihn und bringt jegliche Informationsquelle, die Ihr finden könnt, zu Thunderheart."}]])
R(3908,"Es ist für jeden ein Geheimnis",[[description="Seht, ich habe keine Ahnung, wie ich hierher kam. Niemand weiß das - niemand versteht es! Ich kann mich einfach an nichts erinnern...$B$BAber diese Gegenstände, die Ihr mir gebracht habt... Ich erinnere mich an etwas.$B$BMein Schwert. Ich soll es irgendwie stärken, aber ich weiß beim besten Willen nicht, warum. Es tut mir Leid, dass ich Euch nicht mehr sagen kann, aber ich kann mich einfach nicht erinnern!$B$BNa, egal, ich weiß aber, wo Ihr es hinbringen könnt: zu Donova Snowden in Winterspring. Ihr findet sie bei den Thermalquellen. Sie kann das Schwert an den Teichen dort aushärten.",objectives={"Bringt Linkens Schwert zu Donova Snowden in Winterspring."}]])
R(3909,"Das Videre-Elixier",[[description="Was sagt Ihr da? Linken... HAT ES VERGESSEN?$B$BAh, verstehe... Hat sein Gedächtnis verloren...$B$BNa gut, hier ist sein Schwert. Es ist aber noch nicht fertig. Ich habe von jemandem gehört, der es fertig stellen kann, aber... tja, es könnte etwas schwierig werden, mit ihm zu reden.$B$BHört mal, ich weiß jemanden, der Euch bestimmt helfen kann. Ich kann Euch jetzt nicht alles erklären, das würde zu lange dauern, aber Ihr müsst Euch irgendwie ein Videre-Elixier beschaffen. Der Einzige, von dem ich weiß, dass er Euch dabei helfen kann, ist Gregan Brewspewer. Er ist ziemlich schwer aufzuspüren, aber zuletzt hatte er ein Lager in der Wildnis von Feralas.",objectives={"Sucht nach Gregan Brewspewer im nördlichen Feralas. Lasst Euch von ihm erklären, wie Ihr Euch das Videre-Elixier beschaffen könnt, und kehrt dann zu Donova Snowden nach Winterspring zurück."}]])
R(3911,"The Last Element",[[description="There is work to be had for those venturing into the depths, $N.$B$BThe Dark Irons have mastered creation of extremely powerful golems.$B$BInitial reports from our spies indicate that the dwarves use a unique power source to give their creations incomparable killing power.$B$BJust imagine what we could do with our abominations if we could get our hands on this essence of the elements! Turn that city upside down if you must, but do not return until you have found the essence! Payment will be worth the risk.",objectives={"Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals."}]])
R(3912,"Treffen am Grab",[[description="Durch dieses Elixier könnt Ihr mit jemandem sprechen, den Ihr normalerweise nicht einmal sehen würdet...$B$BBringt das Videre-Elixier und Linkens Schwert mit zum Friedhof kurz vor Gadgetzan in Tanaris. Wenn Ihr dort seid, nehmt den Trank zu Euch. Ihr werdet möglicherweise von der Wirkung sehr überrascht sein, aber erschreckt nicht.$B$BGeht in Eurer 'anderen Form' nach Norden, bis Ihr die Berge erreicht. Dort findet Ihr den, mit dem Ihr sprechen müsst, in einer der Felsspalten. Sein Name ist Gaeriyan.$B$BAber vergesst nicht: Nur in dieser Form wird er mit Euch sprechen...",objectives={"Geht zum Friedhof außerhalb von Gadgetzan und benutzt dort das Videre-Elixier. Befolgt Donovas übrige Anweisungen, um Gaeriyan zu finden."}]])
R(3913,"Grabesstille",[[description="Wenn Ihr zum Friedhof zurückkehrt, $n, findet Ihr dort einen Grabstein... Nicht einfach nur irgendeinen Grabstein... Dieser hebt sich von all den anderen ab. Geheimnisse liegen darin verborgen.$B$BDrückt gegen den Stein, dann erfahrt Ihr von diesen Geheimnissen...",objectives={"Wenn Ihr auferstanden seid, sucht nach dem Grabstein, von dem Gaeriyan Euch erzählt hat."}]])
R(3914,"Linkens Schwert",[[description="Ein greller Lichtblitz blendet Euch, dann könnt Ihr das Schwert wieder aufheben. Es hat sich verwandelt!",objectives={"Liefert Linkens überragendes Schwert bei Linken im Un'Goro Krater ab."}]])
R(3921,"Wenikee Boltbucket",[[description="Ich glaube, ich habe das Samophlang zerbrochen. Das ist schlecht, denn ich habe schon einigen Kollegen aus Undermine davon erzählt, und die waren äußerst fasziniert. Wir müssen einen Weg finden, es zu reparieren!$B$BBringt das zerbrochene Samophlang zu Wenikee Boltbucket beim Außenposten der Horde, zwischen dem Brachland und Ashenvale. Sie ist sehr schlau und wissbegierig. Wenn Ihr ihr das Samophlang zeigt, dann, wette ich, stürzt sie sich sofort darauf und will es reparieren.",objectives={"Bringt das zerbrochene Samophlang zu Wenikee Boltbucket."}]])
R(3922,"Nugget-Patronen",[[description="Ich möchte das Samophlang reparieren, aber dazu brauche ich ein paar Dinge. Ich habe keine 17,5er Nugget-Patronen mehr, und davon werde ich für meine Arbeit hier eine ganze Menge brauchen.$B$BDer nächstgelegene Ort, an dem man sie bekommen kann, ist das Schlickermoor im Osten. Die Leute von der Venture Company bewahren sie normalerweise in ihren Werkzeugkisten auf. Geht ins Schlickermoor und schaut in den Werkzeugkisten nach, die Ihr dort findet. Kommt zu mir zurück, sobald Ihr genug Nugget-Patronen gesammelt habt.",objectives={"Bringt 15 Nugget-Patronen zu Wenikee Boltbucket im Brachland."}]])
R(3923,"Rilli Greasygob",[[description="Tja, das hat schon mal nicht funktioniert. Ich habe an dem Samophlang ein paar zusätzliche Messgeräte angebracht, um seine strukturelle Integrität zu messen, und laut der Anzeige war die Integrität am absoluten Tiefpunkt. Ich könnte natürlich noch ein paar Skalen und vielleicht auch den einen oder anderen Hebel anbringen, aber ... ich glaube, das würde alles nur noch schlimmer machen.$B$BIhr solltet das Samophlang zu Rilli Greasygob bringen. Er hat mal für die Venture Company gearbeitet. Wenn irgendjemand weiß, wie man das Ding reparieren kann, dann Rilli.$B$BIhr findet ihn bei 'Noggs Meistermaschinen' in Orgrimmar, im Tal der Ehre.",objectives={"Bringt das zerbrochene Samophlang nach Orgrimmar zu Rilli Greasygob."}]])
R(3924,"Samophlang-Handbuch",[[description="Ich glaube, ich kann das Samophlang reparieren, aber dazu brauche ich erst einmal das Handbuch. Als ich noch für die Venture Company arbeitete, hatte ich einen Konkurrenten, Boss Copperplug. Der hat das Geheimnis des Samophlangs gehütet wie seinen Augapfel und immer nur kleine Fitzelchen an Informationen an diejenigen verteilt, denen er traute. Zu dieser kleinen, ausgewählten Gruppe habe ich leider nicht gehört...$B$BBoss Copperplug war früher immer in der Felsadermine im Nordosten des Brachlandes. Beschafft Euch das Handbuch von ihm, und falls er irgendjemandem einzelne Seiten davon gegeben hat, dann müsst Ihr diese ebenfalls einsammeln.",objectives={"Bringt das Samophlang-Handbuch nach Orgrimmar zu Rilli Greasygob."}]])
R(3941,"Die Hilfe des Gnoms",[[description="Ich denke... Ich denke... Ich weiß, dass ich aus irgendeinem wichtigen Grund hergekommen bin...$B$BIch hab da eine Idee, $n. In der Höhle dort drüben wohnt eine Gnomin namens J.D. Sie war sehr freundlich zu mir, als ich hier ankam. Vielleicht habe ich in meiner Verwirrung ihr gegenüber irgendwas erwähnt.$B$BWarum fragt Ihr sie nicht, ob sie etwas weiß? Oh, aber seid vorsichtig: Sie spielt immer mit diesen verrückten, leuchtenden Kristallen herum, die ich im Krater gesehen habe. Ich habe keine Ahnung, was sie da drinnen treibt.",objectives={"Sucht J.D. Collie in der Höhle in Marshals Zuflucht auf."}]])
R(3942,"Linkens Andenken",[[description="Oh... Linken? Jaaa, der ist echt witzig. Als er hier ankam, murmelte er ständig irgendwelche seltsamen Dinge. Hat wahrscheinlich einen ziemlich heftigen Schlag auf den Kopf bekommen, würde ich mal sagen.$B$BAber etwas, das er gesagt hat, ist bei mir irgendwie hängen geblieben - dass er dabei war, eine Art Totem herzustellen; er sagte, er müsse mit jemandem namens Eridan Bluewind sprechen... an einem Ort namens Teufelswald, glaube ich.$B$BAber ich bezweifle, dass Linken Euch jetzt noch viel darüber sagen kann. Wenn Ihr mehr wissen wollt, solltet Ihr diesen Eridan vielleicht selbst suchen gehen...",objectives={"Sucht Eridan Bluewind im südlichen Teil des Teufelswalds."}]])
R(3961,"Linkens Abenteuer",[[description="Wenn man sich überlegt, dass Linken nur hergekommen ist, um uns von Sturmflamme zu befreien... Er scheint so gar nichts Außergewöhnliches an sich zu haben, aber mir ist aufgefallen, dass er sich überhaupt nicht für meine Experimente oder Geräte interessiert hat, wie das bei den meisten Gnomen sonst der Fall ist. Er muss im Herzen ein echter Krieger sein.$B$BBringt ihm das Totem. Vielleicht hilft ihm das, sich zu erinnern, warum er hergekommen ist.",objectives={"Bringt das Silbertotem von Aquementas zu Linken in Marshals Zuflucht."}]])
R(3962,"Allein ist es gefährlich",[[description="$n, ich fange endlich an, mich zu erinnern! Ich bin hergekommen, um gegen Sturmflamme zu kämpfen. Ich war auf einer Reise und das hätte der letzte Schritt sein sollen.$B$BAber ich bin kein Held mehr... sondern Ihr. Alles, was Ihr getan habt... Ihr müsst dies jetzt zu Ende bringen, nicht ich.$B$BFindet Sturmflamme und besiegt ihn. Er bewacht ein Artefakt, das die Goldene Flamme genannt wird. Es verleiht mehr Macht als alles, was ich je zuvor gesehen habe, und in den Händen von jemandem, dessen Herz böse ist, ist es äußerst gefährlich.$B$BIhr solltet aber unbedingt Verstärkung mitnehmen - es ist gefährlich, allein zu gehen.",objectives={"Begebt Euch zum Feuerfedergrat südlich von Marshals Zuflucht.$B$BSucht Sturmflamme und verwendet das Totem, um die schützende Aura, die ihn umgibt, zu entfernen. Sobald er besiegt ist, holt die Goldene Flamme aus der Höhle."}]])
R(3981,"Kommandant Gor'shak",[[description="Der arme Gargal... er wurde davon völlig überrascht. BUMM! Der tödliche Pfeil traf ihn genau oben an seinem Kopf. Er war vorher schon kein Genie, aber jetzt...$B$B<Galamav zieht eine Grimasse.>$B$BAls wir den Pfeil herauszogen, sahen wir, dass eine zusammengerollte Notiz an seinem Schaft befestigt war. Die Notiz war ein primitiv gezeichnetes Bild eines Orcs hinter Gittern mit der Unterschrift von Commander Gor'shak.$B$BFalls er noch am Leben sein sollte, dort unten in den Tiefen, dann müsst Ihr ihn finden.$B$BEine Falle, sagt Ihr? Ach nee, Dumpfhuf! Deswegen geht ja auch Ihr und nicht wir!",objectives={"Sucht Kommandant Gor'shak in den Blackrocktiefen.$B$BIhr erinnert Euch, dass auf dem primitiv gezeichneten Bild des Orcs auch Gitter vor dem Gesicht zu sehen waren. Vielleicht solltet Ihr nach einer Art Gefängnis suchen."}]])
R(3982,"Was ist los?",[[description="Ich wurde unter der Schirmherrschaft von Thrall hierher geschickt. Glaubt Ihr wirklich, diese Clowns könnten mich fangen? Ich habe mich fangen lassen, um so Informationen sammeln zu können.$B$B<Gor'shak flüstert.>$B$BDie Prinzessin von Ironforge wurde von Imperator Thaurissan entführt. Prinzessin Bronzebeard befindet sich in dieser Stadt! Ich wette, dem alten Magni ist fast das Herz stehen geblieben, als er diese Neuigkeiten gehört hat.$B$B<Gor'shak lacht.>$B$BPssst! Hört Ihr das? Es kommen Wachen! VERTEIDIGT EUCH!",objectives={"Verteidigt Gor'shak."}]])
R(4001,"Was ist los?",[[description="Bisher war meine Kommunikation mit dem Zwerg Kharan in der Zelle auf der anderen Seite der Halle nur sehr eingeschränkt möglich. Doch ich konnte ihn immerhin davon überzeugen, dass ich - oder besser - dass wir ihm nichts Böses wollen.$B$BGeht und redet mit ihm und erfahrt so viel über die Prinzessin und ihre Entführer wie nur möglich. Bringt diese Informationen dann dem Kriegshäuptling.$B$BThrall will nicht, dass der Prinzessin ein Leid geschieht. Er hat irgendeinen großen Plan, und der umfasst auch, dass sie wieder sicher nach Ironforge zurückgebracht wird. Kharan weiß das alles schon ... Geht!",objectives={"Sprecht mit Kharan Mighthammer und sammelt Informationen über die Entführung von Prinzessin Moira Bronzebeard. Bringt diese Informationen dann zu Thrall nach Orgrimmar.$B$BIhr erinnert Euch, dass Gor'shak gesagt hat, Kharan werde in einer Zelle in seiner Nähe festgehalten."}]])
R(4002,"Das östliche Königreich",[[description="Ihr bringt ganz ausgezeichnete Nachrichten, $N.$B$BAls Kriegshäuptling ist es meine Aufgabe, das zu tun, was das Beste für die Horde ist. Zu garantieren, dass die nachfolgenden Generationen nicht in einer hoffnungslosen Existenz gefangen sein werden.$B$BJetzt ist uns die einzigartige Chance, die Allianzen der Zukunft zu formen, in den Schoß gefallen. Wenn wir jetzt den Zwergen helfen, könnte dies unsere Beziehungen zum östlichen Königreich enorm verbessern. Und aus genau diesem Grund dürft Ihr nicht versagen!$B$BSeid Ihr bereit?",objectives={"Sprecht mit Thrall, wenn Ihr bereit seid, die von ihm geplante Mission zu übernehmen."}]])
R(4003,"Die königliche Rettung",[[description="Der Schlag gegen die Dunkeleisenzwerge wird, wenn er denn erfolgreich verläuft, eine Schockwelle durch ihr ganzes Königreich jagen.$B$BPrinzessin Bronzebeard ist unter der Kontrolle von Imperator Thaurissan. Um sie zu befreien, müsst Ihr den Imperator töten. Doch seid gewarnt, denn Eure Aufgabe ist doppelt gefährlich. Zweifellos wird Euch Prinzessin Bronzebeard angreifen, solange sie noch der Kontrolle des Imperators unterliegt.$B$BIHR DÜRFT IHR KEIN LEID ZUFÜGEN!",objectives={"Tötet Imperator Dagran Thaurissan und befreit Prinzessin Moira Bronzebeard von seinem bösen Zauber."}]])
R(4004,"Ist die Prinzessin gerettet?",[[description="Ihr habt meinen Ehemann erschlagen, $R! Mein Kind wird ohne Vater in diese Welt geboren werden.$B$B<Prinzessin Moira zeigt direkt auf Euch.>$B$BIch versichere Euch, dieses Kind wird der nächste Herrscher des Königreichs von Ironforge sein. Ihr und Eure Art solltet für diese ungerechte Tat bis ans Ende aller Tage gejagt werden.$B$B<Ihr denkt, dass Prinzessin Moira vielleicht unter den Nachwirkungen von Thaurissans Zauber leidet.>$B$BLasst mich in Ruhe, $R. Ich bin sicher, Euer Kriegshäuptling ist erpicht darauf, vom Ergebnis seiner Einmischung zu erfahren.",objectives={"Kehrt zu Thrall zurück!"}]])
R(4005,"Aquementas",[[description="Nehmt diese Tasche mit Vorräten mit Euch nach Tanaris. Begebt Euch zur Lost Rigger-Bucht und sucht dort einen Kreis aus Steinen.$B$BIn der östlichsten Halbinsel liegt das Geheimnis...$B$BLest aus dem Buch von Aquor vor - aber nur innerhalb dieses Kreises - und beschwört das einzige Wesen, das die Gegenstände, die Ihr gesammelt habt, in ein Totem verwandeln kann, mit dem Ihr Sturmflamme bekämpfen könnt.$B$BEs wird Aquementas nicht gefallen, dass Ihr ihn aufweckt, doch vergesst nicht: Ihr müsst unbedingt in dem Kreis bleiben, damit er die Gegenstände transformieren kann.",objectives={"Bringt das Buch von Aquor, die silbrigen Klauen und das Eisenstammherz nach Tanaris.$B$BBenutzt das Buch von Aquor, um Aquementas zu beschwören.$B$BWenn Ihr das vollständige Totem habt, bringt es zu J.D. Collie in Marshals Zuflucht zurück."}]])
R(4021,"Gegenangriff!",[[description="Die Horde lobt Euch für Eure Erfolge gegen die Kolkar, doch die Kolkar kochen vor Wut. Ich habe Berichte erhalten, denen zufolge ein Kontingent Kolkar ihr Zuhause in Desolace verlassen hat und ins Brachland gezogen ist, um dort Rache zu üben. Den letzten Berichten nach, rücken Sie in diesem Moment von Westen her gegen diese Bunker vor!$B$BStellt Euch den Eindringlingen der Kolkar und bereitet der Bedrohung, die sie für das Brachland darstellen, ein Ende. Tötet sie, bis ihr Anführer, Kriegsherr Krom'zar, erscheint. Besiegt ihn und bringt mir ein Teil seiner Flagge als Beweis.$B$BWir zählen auf Euch, $n.",objectives={"Bringt ein Teil von Krom'zars Flagge zu Regthar Deathgate, westlich von Crossroads."}]])
R(4022,"Eine Kostprobe der Flamme",[[description="Der Klan ist sich Eurer Arbeit in der sengenden Schlucht bewusst.$B$BZeigt sie mir, $R. Die abgestreifte Drachenhaut, Schwachkopf!",objectives={"Zeigt Cyrus Therepentous die abgestreifte Haut des schwarzen Drachenschwarms, die Ihr von Kalaran Windblade erhalten habt."}]])
R(4023,"Eine Kostprobe der Flamme",[[description="Ihr sucht nach dem Klan? Zeigt mir einen Beweis für Eure Nützlichkeit, sterbliches Wesen.",objectives={"Zeigt Cyrus Therepentous einen Beweis für Eure Nützlichkeit.$B$BIhr habt so ein Gefühl, dass Cyrus bereits weiß, dass Ihr unwürdig seid."}]])
R(4024,"Eine Kostprobe der Flamme",[[description="Ich möchte die sengenden Flammen des Feuerberges schmecken. Die flüssigen Feuer des Blackrock über mich strömen lassen. Diese Essenz, diese sengende Hitze ist es, nach der ich mich sehne.$B$BIn den Tiefen des Blackrock haust Bael'Gar: ein Wesen aus reinstem Feuer, geboren aus den Flammen des Ragnaros. Tötet Bael'Gar und bringt mir aus seinen glimmenden Überresten einen Teil seines inneren Feuers.$B$BVerwendet die Drachenhaut für seine Überreste, um die innere Flamme sicher entnehmen zu können.$B$BSeid erfolgreich und Ihr werdet belohnt.",objectives={"Begebt Euch in die Blackrocktiefen und tötet Bael'Gar.$B$BIhr wisst lediglich, dass der Riese irgendwo in den Blackrocktiefen haust. Vergesst nicht, die veränderte Haut des schwarzen Drachenschwarms mit Bael'Gars Überresten zu benutzen und damit die feurige Essenz einzufangen.$B$BBringt die eingeschlossene feurige Essenz zu Cyrus Therepentous zurück."}]])
R(4041,"Das Videre-Elixier")
R(4061,"Aufstieg der Maschinen",[[description="Wir stießen bereits bei unseren ersten Streifzügen in der sengenden Schlucht auf die Maschinen. Weitere Nachforschungen ergaben, dass sie aus der brennenden Steppe, eventuell auch aus den Blackrocktiefen, stammen. Und dafür brauchen wir Euch, $N.$B$BEure erste Aufgabe besteht darin, Euch in die brennende Steppe zu begeben und dort einige Elementarsplitter von den Felsautomatons und den geringen Felsgeschöpfen der Gegend zu beschaffen. Sobald Ihr eine ausreichende Menge gesammelt habt, kehrt zu mir zurück, dann werde ich herausfinden, woher sie wirklich stammen.",objectives={"Begebt Euch in die Brennende Steppe und beschafft für Theodora Mulvadania 10 gerissene Elementarsplitter.$B$BEuch fällt ein, dass Theodora gesagt hat, die Golems und Elementare in der Gegend seien eine gute Quelle für solche Splitter."}]])
R(4062,"Aufstieg der Maschinen",[[description="G.L.A.$B$BDas sind die Buchstaben, die in die Elementarsplitter eingeprägt sind. Unter den Initialen findet sich eine Markierung für einen Rang oder etwas in der Art. Die Maschinen, die Ihr in der Brennenden Steppe zerstört habt, hatten den 'Rang IV'. Ich nehme an, das ist ein eher niedriger Rang.$B$BBringt diese Splitterprobe in das Lager im Osten zu Lotwil Veriatus. Er ist ein Gelehrter und vor allem für seine Arbeit auf dem Gebiet der Elementarforschung bekannt. Vielleicht kann er uns bei unserer Suche helfen.",objectives={"Bringt die Elementarsplitterprobe zu Lotwil Veriatus.$B$BIhr erinnert Euch, dass Theodora sagte, Lotwil sei in einem Lager im Osten stationiert."}]])
R(4063,"Aufstieg der Maschinen",[[description="Das kann doch nicht Argelmach sein... Argelmach wurde vor zehn Jahren getötet. Warum ich das so genau weiß? Weil ich derjenige war, der ihn getötet hat.$B$BEr war ein abscheulicher Zwerg und wild entschlossen, mein Lebenswerk zu verderben und es für seine teuflischen Zwecke zu benutzen. Wie es scheint, finden die Tückischen immer einen Weg, ihrer gerechten Strafe zu entgehen.$B$BWenn dies Argelmachs Werk ist, dann muss er zerstört werden. Ich brauche Proben seiner jüngsten Schöpfungen. Mit den richtigen Proben kann ich vielleicht diesem Aufstand ein Ende machen. Die Schöpfungen bewachen Argelmach in den Blackrocktiefen.",objectives={"Sucht und tötet Golemlord Argelmach. Bringt Lotwil seinen Kopf. Außerdem müsst Ihr 10 intakte Elementarkerne von den Wuthäschergolems und Kriegshetzerkonstrukten, die Argelmach beschützen, beschaffen. Das wisst Ihr, weil Ihr übernatürliche Fähigkeiten habt."}]])
R(4081,"SOFORT TÖTEN: Dunkeleisenzwerge",[[description="Auf Befehl von Kriegsherr Goretooth, Kommandant des Expeditionskorps von Kargath:$B$BAlle Streitkräfte, über die General Zornesschmied in den Blackrocktiefen verfügt, müssen ausgelöscht werden.$B$BZornesschmieds Männer sind rücksichtslose Killer und verantwortlich für den Massenmord an der 109. Division des Expeditionskorps von Kargath. Alle Helden, die diesen gefühllosen Bestien gegenübertreten wollen, werden aufgefordert, extreme Vorsicht walten zu lassen.$B$BJede Person, die die erste Kampfreihe von General Zornesschmieds Streitkräften in den Blackrocktiefen vernichtet, wird einen Tribut erhalten.",objectives={"Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren!$B$BKriegsherr Goretooth möchte, dass Ihr 15 Gardisten der Zorneshämmer, 10 Aufseher der Zorneshämmer und 5 Fußsoldaten der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt."}]])
R(4082,"SOFORT TÖTEN: Hochrangige Führungskräfte der Dunkeleisenzwerge",[[description="Auf Befehl von Kriegsherr Goretooth, Kommandant des Expeditionskorps von Kargath:$B$BDer Leiter der Aufklärungseinheit des KEK, Großmeister Lexlort, kam mit Neuigkeiten über den Verbleib einiger hochrangiger Führungskräfte der Dunkeleisenzwerge zurück. Hinter dem verschlossenen Tor, nahe dem Herzen der Stadt, bilden sie ihre Streitkräfte darin aus, unsere Männer auszulöschen. Geht in die Blackrocktiefen und vernichtet sie!$B$BWer diese Mission erfüllt, erhält einen Tribut.",objectives={"Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren!$B$BKriegsherr Goretooth möchte, dass Ihr 10 Sanitäter der Zorneshämmer, 10 Soldaten der Zorneshämmer und 10 Offiziere der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt."}]])
R(4083,"Der spektrale Kelch")
R(4084,"Silberherz",[[description="Ich kenne denjenigen nicht, von dem Ihr sprecht, $N.$B$BDoch keine Sorge, wenn Euer Freund auf der Suche nach mir war, dann weiß ich, was er von mir wollte.$B$BIm Herzen des Un'Goro Kraters lebt das Böse in seiner reinsten Form. Dort manifestiert es sich in der Gestalt eines Elementars namens Sturmflamme. Er wird wird von einer Aura beschützt, die niemand durchdringen kann.$B$BNiemand... außer denen, die über genügend Macht verfügen. Diese Macht kann ich Euch lehren, $N.$B$BDoch zunächst müsst Ihr mir eine Bitte erfüllen. Beschafft 11 silbrige Klauen und 1 Eisenstammherz von den Kreaturen im Teufelswald und kommt dann zu mir zurück.",objectives={"Beschafft 11 silbrige Klauen und 1 Eisenstammherz für Eridan Bluewind im Teufelswald."}]])
R(4101,"Den Teufelswald säubern",[[description="Die Pflanzen schenken dem Teufelswald Leben, doch sogar sie leiden unter der Besudelung der Verderbnis. Ich kenne Wege, um sie zu säubern, doch dieses Wissen kann ich an niemanden weitergeben, den ich nicht kenne oder dem ich nicht vertraue. Beweist mir, dass Ihr der Sache des Zirkels des Cenarius wirklich helfen wollt!$B$BNördlich von hier liegen die Eisenstammhöhlen. Für die Wucherborkenelementare, die sich dort aufhalten, gibt es keine Hoffnung mehr auf Säuberung. Ich bitte Euch, bringt mir ihren Saft, er wird Blutharz genannt, damit ich ihn studieren kann. Vielleicht gelingt es mir so, die anderen Lebensformen hier zu retten.",objectives={"Bringt 15 Einheiten Blutharz zu Arathandris Silversky im Teufelswald."}]])
R(4102,"Den Teufelswald säubern",[[description="Die Pflanzen schenken dem Teufelswald Leben, doch sogar sie leiden unter der Besudelung der Verderbnis. Ich kenne Wege, um sie zu säubern, doch dieses Wissen kann ich an niemanden weitergeben, den ich nicht kenne oder dem ich nicht vertraue. Beweist mir, dass Ihr der Sache des Zirkels des Cenarius wirklich helfen wollt!$B$BNördlich von hier liegen die Eisenstammhöhlen. Für die Wucherborkenelementare, die sich dort aufhalten, gibt es keine Hoffnung mehr auf Säuberung. Ich bitte Euch, bringt mir ihren Saft, er wird Blutharz genannt, damit ich ihn studieren kann. Vielleicht gelingt es mir so, die anderen Lebensformen hier zu retten.",objectives={"Bringt 15 Einheiten Blutharz zu Maybess Riverbreeze im Teufelswald."}]])
R(4103,"Salbe durch Jagd")
R(4104,"Salbe durch Bergbau")
R(4105,"Salbe durch Sammlung")
R(4106,"Salbe durch Kürschnerei")
R(4107,"Salbe durch Entzauberung")
R(4108,"Salbe durch Jagd")
R(4109,"Salbe durch Bergbau")
R(4110,"Salbe durch Sammlung")
R(4111,"Salbe durch Kürschnerei")
R(4112,"Salbe durch Entzauberung")
R(4113,"Verderbte Liedblume")
R(4114,"Verderbte Liedblume")
R(4115,"Verderbte Windblüte")
R(4116,"Verderbte Liedblume")
R(4117,"Verderbte Peitscherwurzel")
R(4118,"Verderbte Liedblume")
R(4119,"Verderbter Nachtdrache")
R(4120,"Die Kraft der Verderbnis",[[description="Als Jäger strebe ich danach, die Stärken nachzuahmen, die ich bei meinen Gegnern sehe. Man kann den Kampf zu seinen Gunsten wenden, indem man einfach seinen Feind gut kennt, $N.$B$BAn einem Ort namens Teufelswald, nördlich von Ashenvale, wurden die Kreaturen durch eine Substanz, das so genannte Fel, verderbt. Die Bären und Wölfe wurden von ihr verrückt, allerdings glaube ich, dass sie dadurch auch noch stärker geworden sind.$B$BGeht, $N. Reist zum Teufelswald und tretet den Bestien gegenüber. Erfahrt selbst, ob sie wirklich so stark sind, wie ich glaube.",objectives={"Talo Thornhoff im Camp Mojache in Feralas möchte, dass Ihr 12 Wutklauengrizzlys und 12 Teufelspfotenverheerer im Teufelswald erledigt."}]])
R(4121,"Gefährliche Zwickmühle",[[description="Glaubt Ihr wirklich, dass Ihr es mit mir als Gefangenem zum vereinbarten Treffpunkt schafft? Habt Ihr wirklich gedacht, Ihr könntet in eine schwer bewachte Festung der Blackrock eindringen und völlig unbemerkt ihren wertvollsten Besitz entführen?$B$BMan wird Euch vernichten!",objectives={"Eskortiert Euren Gefangenen, Grark Lorkrub, durch die brennende Steppe und durch den Blackrock in die sengende Schlucht.$B$BEuch fällt ein, dass Lexlort gesagt hat, seine Männer würden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen.$B$BIhr werdet außerdem Eure Thoriumfesseln an Lexlort übergeben müssen."}]])
R(4122,"Grark Lorkrub",[[description="Ich habe ihn durch die ganze sengende Schlucht, durch den Berg und in die brennende Steppe hinein verfolgt. Der Verräter wurde auf frischer Tat dabei ertappt, wie er den Blackrockorcs wichtige Informationen über die tagtäglichen Vorgänge bei uns lieferte. Ich spreche von Grark Lorkrub.$B$BEr sitzt jetzt in der brennenden Steppe, sicher unter deren Schutz - glaubt er jedenfalls.$B$BNehmt diese Fesseln, $N. Findet Grark, legt ihm die Fesseln an und führt ihn durch den Blackrock. Wenn Ihr das tut, ist ein Tribut Euer.",objectives={"Begebt Euch in die brennende Steppe und sucht Grark Lorkrub. Ihr erinnert Euch, dass Lexlort gesagt hat, er sei zuletzt in einer großen Festung der Blackrock gesehen worden.$B$BWenn Ihr Grark Lorkrub gefunden habt, verwendet die Thoriumfesseln, um ihn zu binden, und bringt ihn dann über den Blackrock in die sengende Schlucht zurück. Lexlorts Männer werden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen."}]])
R(4123,"Das Herz des Berges",[[description="Schon seit Jahren suche ich einen ganz bestimmten Edelstein. Er wird das 'Herz des Berges' genannt und ist so groß wie Eure Faust! Die Dunkeleisenzwerge haben den Stein in ihrem Gewölbe weggeschlossen und ich kann machen, was ich will, sie wollen ihn mir einfach nicht verkaufen!$B$BAlso muss ich Gewalt anwenden.$B$BKämpft Euch zum unteren Gewölbe der Blackrocktiefen durch, brecht in den geheimen Safe dort ein und holt Euch das Herz. Dazu müsst Ihr den Wachmann Stahlgriff besiegen, aber der taucht erst auf, wenn Ihr jeden Reliktkasten im Gewölbe geöffnet habt!$B$BViel Glück.",objectives={"Bringt das 'Herz des Berges' zu Maxwort Uberglint in der brennenden Steppe."}]])
R(4124,"Der vermisste Kurier",[[description="Einer meiner Kollegen, Ginro Hearthkindle, braucht Hilfe und Informationen über den Aufenthaltsort eines Kuriers und der Pakete, die er bei sich hatte. Es ist etwa eine Woche her, dass der Kurier verschwunden ist; unsere eigene Suche hat nichts ergeben und wir wissen nicht, was wir noch tun sollen. Leider musste ich den Kurier für vermisst erklären.$B$BWenn Ihr freie Zeit und Kapazitäten habt, dann sprecht doch bitte mit Ginro. Er sollte irgendwo hier in der Festung sein, vielleicht in seinem Quartier.",objectives={"Sprecht mit Ginro Hearthkindle in der Festung Feathermoon."}]])
R(4125,"Der vermisste Kurier",[[description="Es ist etwa eine Woche her, seit der Kurier Raschal sich nach Thalanaar aufgemacht hat. Er kennt Feralas gut; er ist schon bei uns, seit General Feathermoon das Exeditionskorps hergeführt hat. Ich weiß, dass er vorhatte, mit einem Ruderboot die Küste entlangzufahren und Feralas im Süden zu durchqueren, um das Lager der Horde zu umgehen.$B$BIch konnte sein Boot nicht finden, aber vielleicht findet Ihr es ja. Vielleicht liegt es irgendwo versteckt ... oder vielleicht wurde es auch versenkt. Wie dem auch sei, möglicherweise enthält es einen Hinweis darauf, wo Raschal ist. Wenn Ihr irgendetwas entdeckt, lasst es mich bitte wissen.",objectives={"Sucht das Boot des Kuriers irgendwo entlang der Küste von Feralas."}]])
R(4126,"Hurley Pestatem",[[description="Die Dunkeleisenzwerge, angeführt von dem Bösewicht Hurley Pestatem, haben eines der besten Rezepte der Donnerbräus gestohlen, jenes für das Donnerbräu Lagerbier. Diese Schurken! Sie verdienen ein solch edles Gebräu nicht!$B$B$N, ich habe eine schwierige Aufgabe für Euch. Geht zu den Blackrocktiefen in der brennenden Steppe, zerstört alle Fässer mit Donnerbräu Lagerbier, die Ihr finden könnt, und bringt unser Donnerbräurezept zurück!$B$BBitte, bringt das Rezept unbedingt zurück, und wenn Ihr dafür die ganzen Blackrocktiefen umkrempeln müsstet!",objectives={"Bringt Ragnar Donnerbräu in Kharanos das gestohlene Donnerbräurezept."}]])
R(4127,"Havarie",[[description="Als Ihr mit der Hand durch den Matsch fahrt, fühlt Ihr plötzlich den Griff eines Messers unter Euren Fingern. Es sieht gut gepflegt aus und dürfte mit Sicherheit jemandem gehört haben, der auf dem Boot gewesen ist. Vielleicht hat das große Stück des verschwundenen Bootes irgendetwas mit seinem Verschwinden zu tun.$B$BIhr nehmt das Messer an Euch, denn Ginro Hearthkindle in der Festung Feathermoon hatte Euch angewiesen, ihm jegliche Hinweise sofort zu bringen. Allerdings werdet Ihr das ungute Gefühl nicht los, dass Ihr in diesem Gewässer nicht allein seid ...",objectives={"Kehrt zur Festung Feathermoon zurück und zeigt Ginro Hearthkindle das gefundene Messer."}]])
R(4128,"Ragnar Donnerbräu",[[description="Hallo, $n. Wie ich hörte, soll Ragnar Donnerbräu außer sich vor Wut sein, dass jemand sein Bier gestohlen hat. Er sucht nach wackeren Abenteurern und ist gewillt, sie reichlich zu entlohnen.$B$BSprecht mit Ragnar, wenn Ihr Interesse habt. Ihr findet ihn in der Brauerei Donnerbräu in Kharanos in Dun Morogh.",objectives={"Sprecht mit Ragnar Donnerbräu."}]])
R(4129,"Das wieder aufgetauchte Messer",[[description="Der Hausdruide der Festung, Quintis Jonespyre, verfügt über ein paar... ungewöhnliche Fertigkeiten. Eine davon ist die Psychometrie - die Fähigkeit, durch Berührung eines Objekts etwas über seine Geschichte zu erfahren. Fragt mich nicht, wie er das bewerkstelligt. Es muss etwas mit Magie zu tun haben, wovon ich nichts verstehe und womit ich auch nichts zu tun haben will. Zwei Dinge weiß ich jedoch: Erstens, ich habe gesehen, dass es funktioniert, und zweitens, der Gauner schuldet mir etwas.$B$BQuint lebt in einem kleinen Baumhaus. Bringt ihm das Messer und richtet ihm von mir aus, dass seine Kalimdor-Poker-Schulden bei mir beglichen sind, wenn er seinen Hokuspokus bei dem Messer wirkt.",objectives={"Bringt Quintis Jonespyre in der Festung Feathermoon das gefundene Messer."}]])
R(4130,"Psychometrie-Sitzung",[[description="Entschuldigt bitte, mir ist immer noch ein bisschen schwummrig. Wie dem auch sei, ich hatte ein paar nützliche Visionen.$B$BRaschal nimmt zwei lederne Rucksäcke aus seinem Boot und geht landeinwärts. Dann jedoch kehrt er zu seinem Boot zurück. Ich sehe Gnollskalps ... er ist auf ein paar Gnolle gestoßen - Waldpfoten nennt man sie, glaube ich. Er ist sehr besorgt - fast schon panisch - wegen etwas. Und das so sehr, dass er nicht bemerkt, wie sich Wasserelementare hinter seinem Rücken manifestieren. Hier enden die Visionen.$B$BIch muss mich ausruhen, tut mir Leid, $N. Erzählt Gin, was ich gesehen habe. Er muss das wissen.",objectives={"Sprecht mit Ginro Hearthkindle in der Festung Feathermoon."}]])
R(4131,"Die Waldpfotengnolle",[[description="Unsere 'Freunde', die Waldpfoten, mögen Raschal am Ende vielleicht zwar erwischt haben, aber irgendwie habe ich das Gefühl, als hätte sich da etwas anderes ereignet. Wie dem auch sei, es dürfte allerdings der beste Anhaltspunkt sein, um mit der Suche zu beginnen.$B$BIch wünschte nur, ich wüsste genauer, was zu tun ist, aber momentan kann ich lediglich sagen: 'Durchsucht die Lager der Waldpfoten. Macht Euch auf den Weg.' Ich weiß, dass Gnolle Gegenstände, die sie ergattern, behalten und um sie zanken. Vielleicht haben sie ja auch die Rucksäcke gefunden, die Quint erwähnte. Ohne Quints Visionen hätte ich bei früheren Suchaktionen niemals eine direkte Konfrontation mit ihnen gesucht, aber jetzt würde ich sagen: Auf sie mit Gebrüll!",objectives={"Durchsucht die Lager der Waldpfotengnolle im Süden Feralas nach Hinweisen auf den Verbleib des Kuriers oder seiner Habseligkeiten."}]])
R(4132,"Operation: Tod dem Zornesschmied",[[description="Ihr habt bemerkenswerte Arbeit geleistet, $n. Jetzt ist es an der Zeit, Euch auf Eure letzte Mission zu schicken.$B$BGeneral Zornesschmied, der für die Koordination der Angriffe auf die 109. Division des KEK und die massive Dezimierung unserer Truppen verantwortliche Dunkeleisenzwerg, muss zur Rechenschaft gezogen werden.$B$BDies wird zweifellos Eure schwerste Mission werden, aber solltet Ihr erfolgreich sein, wird man Euch reich entlohnen.",objectives={"Begebt Euch zu den Blackrocktiefen und eliminiert General Zornesschmied! Kehrt zum Kriegsherrn Goretooth zurück, sobald Ihr diese Aufgabe erledigt habt."}]])
R(4133,"Vivian Lagrave",[[description="Schattenmeisterin Vivian Lagrave benötigt Eure Dienste. Sie lebt im Ödland, im Orc-Außenposten Kargath, wo sie dem Gerücht nachgeht, nach dem die Dunkeleisenzwerge der Blackrocktiefen angeblich ein bestimmtes Gebräu herstellen.$B$BSprecht mit Vivian. Sie erwartet Euch.",objectives={"Sprecht mit Schattenmeisterin Vivian Lagrave in Kargath."}]])
R(4134,"Verlorenes Donnerbräurezept",[[description="Es geht das Gerücht umher, dass der Dunkeleisenzwerg Hurley Pestatem ein Rezept zum Brauen von Bier gestohlen habe. Dieses Bier, das Donnerbräu Lagerbier, soll angeblich jeden, der es trinkt, mit großer Kraft und Mut erfüllen. Wir möchten dieses Getränk gern untersuchen. Vielleicht finden wir ja noch andere Anwendungsgebiete für seine Vorzüge... Anwendungsgebiete, die eher im Einklang mit den Zielen der Verlassenen sind.$B$BDurchforstet die Blackrocktiefen, findet Hurley, nehmt das Donnerbräurezept von ihm und bringt es mir.$B$BUnd um ihn zu finden, müsst Ihr ihn möglicherweise locken, indem Ihr sein wertvolles Bier bedroht.",objectives={"Bringt Vivian Lagrave in Kargath das gestohlene Donnerbräurezept."}]])
R(4135,"Die verwundene Tiefe",[[description="In den Rucksäcken befinden sich zwei Gegenstände: Der erste ist ein für Thalanaar bestimmtes Paket mit Waren, der zweite eine hastig hingekritzelte Notiz, die an einen unbekannten Empfänger gerichtet ist.$B$BDie Notiz spricht von der Entdeckung heimtückischer käferartiger Kreaturen südlich des Gnoll-Lagers an einem Ort der verwundene Tiefe genannt wird. Der Verfasser wollte die Sache persönlich untersuchen, da er dies als ernsthafte Bedrohung für ganz Feralas befand. Die Notiz ist mit 'Raschal aus Feathermoon' unterzeichnet.$B$BOffenbar habt Ihr jetzt herausgefunden, wohin Raschal letztlich verschwunden ist.",objectives={"Da Ihr jetzt Raschals letzten bekannten Aufenthaltsort in Erfahrung gebracht habt, setzt Ihr die Suche nach ihm oder seinen sterblichen Überresten in der verwundenen Tiefe fort. Laut Notiz soll dieser Ort südlich der Lager der Waldpfotengnolle liegen."}]])
R(4136,"Ribbly Screwspigot",[[description="Mein Bruder Ribbly hat unserer Familie schon immer auf der Tasche gelegen, unser Geld genommen und es für eine Dummheit nach der anderen ausgegeben.$B$BTja, seine letzte Dummheit muss wohl seine bislang schlimmste gewesen sein, denn Baron Revilgaz von Booty Bay hat ein Kopfgeld auf den armen Ribbly ausgesetzt. Ich kann Euch gar nicht sagen, wie glücklich das die Screwspigots macht! Endlich ist unser kleiner Ribbly mal etwas wert!$B$BEr versteckt sich jetzt allerdings ganz weit unten in den Blackrocktiefen. Sucht ihn doch bitte und bringt ihn zu mir!$B$BUnd falls er nicht mitkommen will, ist das auch kein Problem ... bringt mir einfach seinen Kopf.",objectives={"Bringt Yuka Screwspigot in der brennenden Steppe Ribblys Kopf."}]])
R(4141,"Muigin und Larion",[[description="Seht Ihr Larion da drüben? Es ist SEINE Schuld, dass wir hier sind!$B$BIch hab ihm noch gesagt, dass wir in die falsche Richtung gehen, aber hat er auf mich gehört? Und stellt Euch vor, jetzt spricht er nicht mehr mit mir. Na ja, erlauben wir uns doch ein kleines Späßchen mit ihm, bis er es sich anders überlegt.$B$BSind Euch die seltsamen pflanzenartigen Kreaturen in dieser Gegend hier aufgefallen? Die machen nichts als Ärger, wirklich, aber ich glaube, wenn man sie ordentlich abrichten würde, könnte man sie dazu bringen, Befehlen zu gehorchen.$B$BAls Erstes bräuchte ich allerdings ein paar davon, um sie zu studieren. Meint Ihr, Ihr könntet mir ein paar bringen?",objectives={"Sammelt 15 Blutblüten und kehrt zu Muigin zurück."}]])
R(4142,"Ein Besuch bei Gregan",[[description="Ich weiß nicht so recht, was ich davon halten soll, $N. Die Pflanzen... sie scheinen ein gewisses Maß an Intelligenz zu besitzen.$B$BAllerdings bin ich auf diesem Gebiet kein Experte. Aber ich kenne einen!$B$BGeht nach Nord-Feralas und sucht einen Freund von mir auf, er heißt Gregan Brewspewer. Er kennt sich mit solchen Dingen bestens aus.$B$BGregan kann uns bestimmt weiterhelfen. Ihr findet ihn draußen in der Wildnis, denn für das Großstadtleben hat er nicht viel übrig.",objectives={"Bringt Gregan Brewspewer in Feralas eine Blutblüte."}]])
R(4143,"Der Dunst des Bösen",[[description="Um ehrlich zu sein, $N, solche Pflanzen habe ich auf meinen Reisen noch nie gesehen. Vielleicht sollte ich mal einen Ausflug zu diesem Krater machen...$B$BEgal, ich weiß vermutlich, was Muigin benötigt - Dunst der Atal'ai. Das ist ein abscheuliches Zeug, sehr schwer zu sammeln, aber es ist genau das, was er benötigt, um diese kleinen Monster unter Kontrolle zu bringen.$B$BIhr müsst zum Tempel von Atal'Hakkar in den Sümpfen des Elends gehen. Den Dunst der Atal'ai bekommt Ihr von Tieflauerern, Düsterwürmern oder Brühschlammern, die man dort findet. Viel Glück, $N!",objectives={"Sammelt 5 Proben Dunst der Atal'ai und bringt sie Muigin im Un'Goro Krater."}]])
R(4144,"Blutblütensprösslinge")
R(4145,"Larion und Muigin",[[description="Seht Ihr Muigin da drüben? Es ist SEINE Schuld, dass wir uns verirrt haben!$B$BIch kannte den richtigen Weg, aber er bestand darauf, eine Abkürzung zu nehmen, und so sind wir hier gelandet!$B$BUnd um die Lage noch zu verschlimmern, schickt er mir jetzt auch noch seine verrückten Pflanzen, um mich zu ärgern. Ich bin so wütend, dass ich bis auf weiteres kein Wort mehr mit ihm reden werde, aber diese Quälgeister sind wirklich unerträglich.$B$BWarum versuchen wir nicht als Erstes, seinen Bestand ein bisschen zu dezimieren? Geht hinaus und jagt einige Blutblüten und kehrt dann zu mir zurück.",objectives={"Jagt 5 Blutblütenpeitscher, 5 Blutblütendrescher, 5 Blutblütenschinder und 5 Blutblütenfallen für Larion in Marshals Zuflucht."}]])
R(4146,"Schrumpf-Treibstoff",[[description="Ihr habt Glück, $N! Während Marvon fort war, habe ich an einigen meiner eigenen Experimente gearbeitet, eines davon ist ein Käferschrumpfer mit kurzer Reichweite. Nur noch ein paar kleine Änderungen, dann ist er perfekt, um damit diese Blutblütenplagen zu beseitigen.$B$BIhr könnt gern einen meiner Schrumpfer-Prototypen haben, aber Ihr benötigt noch etwas Treibstoff dafür. Den für den Schrumpfer benötigten Dunst der Atal'ai findet Ihr im Tempel von Atal'Hakkar. Ihr bekommt ihn von Tieflauerern, Düsterwürmern oder Brühschlammern.",objectives={"Bringt Larion in Marshals Zuflucht den ungeladenen Schrumpfer und 5 Proben Dunst der Atal'ai."}]])
R(4147,"Marvons Werkstatt",[[description="Ich habe herausgefunden, was Muigin so treibt. Er züchtet da drüben doch tatsächlich diese verdammten Dinger!$B$BIch glaube, die einzige Lösung des Problems besteht darin, mit... nein, nicht mit ihm zu sprechen... Was für ein Blödsinn! Die Lösung ist zurückzuschlagen!$B$BWir brauchen die Hilfe meines Freundes Marvon, der in Ratchet eine Werkstatt hat. Er kann bestimmt irgendein Gerät zusammenbasteln, das uns helfen wird.",objectives={"Reist zu Marvon Rivetseekers Werkstatt in Ratchet."}]])
R(4148,"Blutblütenschrumpfer")
R(4161,"Rezept der Kaldorei",[[description="Vor langer Zeit nannte man die Nachtelfen 'Kaldorei', was übersetzt 'Kinder der Sterne' bedeutet. Für Euch als $C ist es besonders wichtig etwas über die Vergangenheit zu erfahren, also hört gut zu, was ich Euch zu sagen habe, $N.$B$BDie Kaldorei waren schon immer stolz auf ihre harmonische Beziehung zur Natur. Das bedeutet, dass wir von der Natur nur nehmen, was notwendig ist, und es in gleichem Maße vergelten. Dieses Gleichgewicht bedeutet uns viel, $N.$B$BGeht und sammelt sieben kleine Spinnenbeine - und nicht mehr, und kommt dann zu mir zurück.",objectives={"Sammelt 7 kleine Spinnenbeine für Zarrin in Dolanaar."}]])
R(4181,"Goblin-Ingenieurskunst",[[description="Bei der Experteningenieurskunst gibt es zwei unterschiedliche Disziplinen: Gnom und Goblin. Ich erwähne die Ingenieurskunst der Goblins nur, weil ich ein fairer und unvoreingenommener Lehrer bin. Sie machen gern Dinge, die in die Luft gehen, und es ist ihnen dabei meistens egal, ob dabei was im Weg herumsteht - auch wenn sie es selbst sind.$B$BLest dieses Handbuch, $N. Wenn Ihr lernen wollt, wie Ihr Euch selbst in die Luft jagt, dann bringt es zu Nixx Sprocketspring nach Gadgetzan. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.",objectives={"Wenn Ihr mehr über die Goblin-Ingenieurskunst wissen wollt, dann bringt das Handbuch der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan."}]])
R(4182,"Drachkin-Bedrohung",[[description="Das Leben in der Brennenden Steppe ist voller Konflikte.$B$BSeht Euch nur mal diesen Ort an! Wir wissen nur sehr wenig darüber, was mit diesen Gebäuden geschehen ist, aber wir wissen, dass all das hier irgendwann vor der großen Explosion einmal Teil der Rotkammbergkette war.$B$BAber genug gejammert! Wir haben ein Problem, $n. Vielleicht sind Euch die Drachkin am Fuß dieses Bergkamms aufgefallen. Wir brauchen Hilfe, um sie zurückzuschlagen. Tötet so viele, wie Ihr könnt, und kommt dann zu mir zurück. Wenn Ihr erfolgreich seid, können wir uns vielleicht noch über andere Dinge unterhalten.",objectives={"Erschlagt 15 schwarze Brutlinge, 10 Exemplare der schwarzen Großdrachenbrut, 4 schwarze Wyrmkin und 1 Schwarzdrachen. Kehrt zu Helendis Riverhorn zurück, sobald die Aufgabe erledigt ist."}]])
R(4183,"Die wahren Meister",[[description="Bislang nahmen wir an, dass die Blackrockorcs das Ergebnis ihrer primitiven Erziehung seien. Was wir jedoch hier, in ihrem Heimatland, entdeckt haben, erzählt uns eine ganz andere Geschichte.$B$BAngetrieben werden sie zwar tatsächlich von Kampfrausch und Streitlust, aber der schwarze Drachenschwarm ist es, der die Orcs von Blackrock beherrscht. Wir vermuten, dass es auch der schwarze Drachenschwarm ist, der ihre Wut und Feindseligkeit schürt.$B$BBringt diesen Brief zu Magistrat Solomon. Er wird wissen, was zu tun ist.$B$B<Helendis gibt Euch einen versiegelten Brief.>",objectives={"Reist nach Seenhain und händigt Magistrat Solomon Helendis Riverhorns Brief aus."}]])
R(4184,"Die wahren Meister",[[description="Das sind schlimme Neuigkeiten, $N. Zu entdecken, dass unsere Todfeinde nicht mehr als Marionetten einer viel größeren Bedrohung sind, ist wahrlich entmutigend. Es ist unmöglich, dass Seenhain einen Angriff durch die Blackrockorcs UND den schwarzen Drachenschwarm überleben könnte. Wenn Seenhain dieser Gefahr anheim fällt, dann fällt bald auch Dunkelhain, und was dann? Goldhain? Auch Stormwind?$B$BIhr müsst diese Information unbedingt sofort Hochlord Bolvar Fordragon in Stormwind überbringen! Wenn dies nicht die Unterstützung Stormwinds rechtfertigt, dann ist alles verloren.",objectives={"Reist nach Stormwind und tragt Solomons Hilfegesuch dem Hochlord Bolvar Fordragon vor.$B$BBolvar residiert in der Burg Stormwind."}]])
R(4185,"Die wahren Meister",[[description="Solomon malt da ein recht düsteres Bild aus. Aber wir können es uns leider nicht leisten, unsere dünn gesäten Truppen aufgrund von reinen Vermutungen nach Seenhain zu schicken. Ich brauche einen Beweis für diese Behauptungen, bevor ich handeln kann.$B$BSprecht mit Lady Prestor, $n. Sie ist eine kluge Frau und weiß viel über Großdrachen und Drachkin. Vielleicht kann sie ein bisschen Licht in die Sache bringen.",objectives={"Sprecht zuerst mit Lady Katrana Prestor, dann mit Hochlord Bolvar Fordragon."}]])
R(4186,"Die wahren Meister",[[description="Ich ernenne Euch hiermit zum kommissarischen Deputy von Stormwind, $N.$B$BKehrt zu Magistrat Solomon in Seenhain zurück und übergebt ihm diesen Erlass.",objectives={"Händigt Bolvars Erlass an Magistrat Solomon in Seenhain aus."}]])
R(4201,"Der Liebestrank",[[description="Oh, wie schmerzhaft doch die Liebe ist! Mein geliebter Gefreiter Rocknot ist immun gegen meinen Charme. Er verschmäht mich! Es ist zum Verrücktwerden!$B$BIhr müsst mir helfen! Wir Sukkubi wissen viel über die Liebe und ich kann einen Trank herstellen, der den eisernen Panzer um Rocknots Herz erweichen könnte. Dazu benötige ich folgende Dinge: das Kraut Gromsblut, Riesensilbervenen von den Klippenriesen Azsharas sowie Wasser aus dem Golakka-Quellen-Krater in Un'Goro. Ihr könnt das Wasser in diese Phiole füllen.$B$BBitte, $N, verhelft einer armen Seele zum Glück!",objectives={"Bringt 4 Gromsblut-Kräuter, 10 Riesensilbervenen und Nagmaras gefüllte Phiole zu Herrin Nagmara in den Blackrocktiefen."}]])
R(4221,"Verderbte Windblüte")
R(4222,"Verderbte Windblüte")
R(4223,"Die wahren Meister",[[description="<Magistrat Solomon seufzt.>$B$BIhr müsst in die brennende Steppe zurückkehren, $N. Als Deputy von Stormwind erwartet man von Euch, dass Ihr Euch bei Marshal Maxwell meldet. Viel Glück.",objectives={"Sprecht mit Marshal Maxwell in der brennenden Steppe."}]])
R(4224,"Die wahren Meister",[[description="Was? Ihr dachtet, Ihr wärt der Erste? Wie viele Soldaten müssen wir noch verlieren, bevor Stormwind handelt?$B$BWir hatten riesige Mengen an Informationen über die Blackrockbedrohung zusammengetragen, doch dann verloren wir unseren befehlshabenden Offizier, Marshal Windsor. Zusammen mit Marshal Windsor gingen auch all unsere wertvollen Informationen verloren.$B$BWas wir brauchen, ist diese Dokumentation. Sprecht mit dem struppigen John, $N. Er war mit Windsor zusammen, als sie von einem Stoßtrupp der Blackrock überfallen wurden. Er wurde zuletzt in einer Höhle im Norden gesehen.",objectives={"Sprecht mit dem struppigen John, um etwas über Marshal Windsors Schicksal zu erfahren, und kehrt dann zu Marshal Maxwell zurück, wenn Ihr diese Aufgabe erledigt habt.$B$BIhr erinnert Euch daran, dass Marshal Maxwell Euch geraten hat, ihn in einer Höhle im Norden zu suchen."}]])
R(4241,"Marshal Windsor",[[description="Dieser nichtsnutzige Feigling behauptet also, Windsor sei noch am Leben, was?$B$BMacht Euch bereit, Deputy, Ihr werdet ausziehen, um ihn zu suchen. Falls Windsor noch am Leben ist, müsst Ihr ihn zurückholen. Sollte er tot sein, brauche ich einen Beweis dafür.$B$B<Maxwell lacht.>$B$BIch wette, das könnt Ihr langsam schon nicht mehr hören, was?",objectives={"Reist zum Blackrock im Nordwesten und dann weiter zu den Blackrocktiefen. Findet heraus, was aus Marshal Windsor geworden ist.$B$BIhr erinnert Euch daran, dass der struppige John sagte, man hätte Windsor in ein Gefängnis verschleppt."}]])
R(4242,"Verlorene Hoffnung",[[description="Bolvar ist ein Dummkopf. Ich war gerade dabei, ihm seinen kostbaren 'Beweis' zu beschaffen, um ihm diesen in den Hals stopfen zu können.$B$BEr ist ein blinder Blödmann. Selbst wenn der Beweis ihn in die Nase beißt, würde er ihn nicht sehen.$B$BWas meine Informationen angeht, die sind verloren. Unwiderbringlich.$B$BSollte ich Ironfoe jemals finden und es aus diesem Labyrinth herausschaffen, wird mein erster Halt Stormwind sein, damit ich diesem Reptil meinen Hammer über den Schädel ziehen kann.$B$BGeht jetzt, $N.",objectives={"Überbringt Marshal Maxwell die schlechten Neuigkeiten."}]])
R(4243,"Chasing A-Me 01",[[description="Irgendetwas muss meiner bislang besten Erfindung zugestoßen sein. Ihr habt doch schon mal mechanische Eichhörnchen gesehen, richtig? Tja, um näher an die Affen des Un'Goro Kraters heranzukommen, habe ich eine mechanische Äffin geschaffen, die sich unbemerkt unter sie mischen kann - ich nenne sie A-Me 01.$B$BSie hat Wahrsagesteine als Augen, so konnte ich alles sehen, was auch sie sah. Den Fungal Rock hat sie wohlbehalten erreicht - das ist das Versteck der Affen, gleich nördlich von hier. Und dort habe ich dann den Kontakt zu ihr verloren. Das Letzte, was ich sah, war eines der Alphamännchen, das auf sie zugestürmt kam, um sie zu begrüßen!$B$BKönntet Ihr mir wohl helfen, sie zu finden?",objectives={"Sucht im Un'Goro Krater nach A-Me 01."}]])
R(4244,"Chasing A-Me 01",[[description="Ihr setzt Eure Untersuchungen fort und findet eine Abdeckung, die sich aufschieben lässt. Oberhalb der Verkabelung steht in gut lesbarer Schrift geschrieben: 'Mithrilgehäuse ersetzen und Strom erst ausschalten, dann einschalten.'$B$BEs dauert einen Moment, bis Ihr die Abdeckung wieder angebracht habt, und Ihr fragt Euch, ob es wirklich so einfach ist, A-Me 01 zu reparieren und zurück zu Karna Remtravel in der Nähe von Marshals Zuflucht zu bringen.$B$BTja, probieren geht über studieren ...",objectives={"Sucht ein Mithrilgehäuse und bringt es zu A-Me 01 im Un'Goro Krater."}]])
R(4245,"Chasing A-Me 01",[[description="Nachdem Ihr Euch vergewissert habt, dass Ihr bereit seid, A-Me 01 zu Karna Remtravel zurückzubringen, knipst Ihr den Schalter auf 'Aus'. Ihr seht Euch nochmals um, um sicherzugehen, dass sich keine Gorillas nähern, und fragt Euch, was wohl geschieht, wenn Ihr den Schalter wieder auf die 'Ein'-Position stellt.$B$BDas ist Eure letzte Chance ... wollt Ihr das wirklich tun?",objectives={"Begleitet A-Me 01 zu Karna Remtravel im Un'Goro Krater."}]])
R(4261,"Alter Geist",[[description="Der Teufelswald war einst ein friedliches und ruhiges Land... bis die Legion hier eingefallen ist. Die Höllenbestien, Zerstörung, Chaos...$B$BDer Schädel des Gul'dan hat dafür gesorgt, dass hier niemand ungeschoren davonkam. Alles fiel der Verderbnis zum Opfer.$B$BSogar jetzt, da ich ein Geist bin, bin ich immer noch gefangen und muss die Leiden dieses Landes ertragen. Helft mir, den Weg nach Hause zu finden. Bitte, $N, sagt mir, dass Ihr einen alten Geist weg von hier führen werdet, dorthin, wo ich endlich ruhen kann.$B$BSobald ich frei sein werde, solltet Ihr Kayneth Stillwind aufsuchen, einen Druiden, der in Forest Song im Osten lebt.",objectives={"Bringt Arei in Sicherheit und sprecht dann mit Kayneth Stillwind in Forest Song, im Osten von Ashenvale."}]])
R(4262,"Übermeister Pyron",[[description="Die letzten fünf meiner Magier, die ausgezogen waren, um sich auf dem Blackrock umzusehen, kamen knusprig geröstet zurück, mit einem dauerhaften orangefarbenen Gnomen-Afro - oder noch schlimmer.$B$B<Jalinda nimmt etwas Asche vom Boden auf und lässt sie vom Wind davontragen.>$B$BEin besonders mieses Individuum, Übermeister Pyron, scheint hier eine Menge Ärger zu verursachen. Dieser Elementar muss vernichtet werden, damit unser Expeditionsteam in die Blackrocktiefen reisen kann!$B$BEr bewacht den Eingang am Blackrocksteinbruch.",objectives={"Erschlagt Übermeister Pyron und kehrt dann zu Jalinda Sprig zurück.$B$BIhr erinnert Euch an Jalindas Worte, dass Pyron den Steinbruch bewachen würde. Vielleicht solltet Ihr dort nachsehen?"}]])
R(4263,"Incendius!",[[description="Seid Ihr sicher, dass Pyron 'Incendius' sagte, als er starb?$B$B<Jalinda schluckt schwer.>$B$BLord Incendius soll angeblich einer von Ragnaros Dienern sein! Oje, oje... was sollen wir jetzt nur tun?$B$BMeint Ihr, Ihr könntet noch eine weitere Mission bewältigen? Ich habe niemand anderen, den ich schicken könnte, $n!$B$BWir werden niemals eine Gruppe hineinbringen, solange Incendius Pyron aus der Asche immer wieder neu erstehen lässt.$B$BIhr müsst Lord Incendius suchen und vernichten!",objectives={"Sucht Lord Incendius in den Blackrocktiefen und vernichtet ihn!"}]])
R(4264,"Eine zusammengeknüllte Notiz",[[description="Die Notiz ist mit Flecken übersät. Der Text ist kaum noch lesbar, aber Ihr könnt Folgendes erkennen:$B$B... süße Ironie...$B$B... der Sturz der zerbrochenen Allianz...$B$B... ohne General Angerfords Sorgfalt hätten wir das Schema der Verschlüsselung niemals herausgefunden...$B$B... Argelmach hat Windsors Notizen fast entschlüsselt.$B$BUnser Lord wird sich aus den Tiefen erheben und alle zerschmettern, die noch übrig sind...$B$BImperator Dagran Thaurissan",objectives={"Soeben seid Ihr auf etwas gestoßen, das Marshal Windsor mit Sicherheit sehr interessiert. Vielleicht besteht ja doch noch Hoffnung."}]])
R(4265,"Flucht aus dem Schwarmbau",[[description="Die Kapsel platzt auf, als Ihr sie berührt, und zum Vorschein kommt ein Nachtelf, der überraschenderweise noch am Leben ist. Er scheint bei guter Gesundheit zu sein, ist jedoch sehr benommen. Als Ihr ihm aus der Kapsel heraushelft, regt sich Leben in ihm.$B$B\"Elune sei Dank! Ihr habt mich gerettet! Ich... Mein Name ist Raschal. Ich erwachte völlig gelähmt in dieser Kapsel, nachdem mich diese Käfer überwältigt hatten. Wurdet Ihr von der Festung geschickt?\"$B$BAnscheinend habt Ihr den vermissten Kurier gefunden!",objectives={"Begleitet Raschal sicher aus dem Schwarmbau der Zukk'ash hinaus.$B$BKehrt zu Ginro Hearthkindle in der Festung Feathermoon zurück und lasst ihn wissen, dass Raschal am Leben ist und dass es ihm gut geht."}]])
R(4266,"Der Empfang eines Helden",[[description="$N, General Shandris Feathermoon möchte unter vier Augen mit Euch sprechen. Sie möchte Euch bestimmt für Eure Dienste zum Wohle der Festung danken, aber ich weiß auch, dass sie außerdem mit Euch über diese Insektenwesen sprechen will, auf die Ihr und Raschal im Süden von Feralas gestoßen seid. Die Berichte, die diese Insekten der Zukk'ash betreffen, sind ... mehr als beängstigend.$B$BGeneral Feathermoon wartet im Haupttruppenlager auf Euch.",objectives={"Sprecht mit Shandris Feathermoon in der Festung Feathermoon."}]])
R(4267,"Aufstieg der Silithid",[[description="Ich vertraue Euch eine Kopie des Berichts an, den Raschal über die Plage im Südosten Feralas angefertigt hat. Der eigentliche Bericht befindet sich in den Akten in Darnassus, aber ich möchte, dass Ihr diese Kopie an eine Vertraute des Protektorats überbringt. Ihr Name lautet Gracina Spiritmight. Sie ist eine Priesterin, die im Tempel des Mondes in Darnassus lebt. Sie verfügt über großes Wissen, solche Kreaturen betreffend, und wenn sie diesen Bericht erhalten würde, käme es uns allen sehr zugute.$B$BMacht Euch auf den Weg, und viel Glück, $N. Möge Elune über uns alle wachen.",objectives={"Bringt Raschals Bericht zu Gracina Spiritmight in Darnassus."}]])
R(4281,"Thalanaar-Lieferung",[[description="Dieses Paket mit Waren, das Ihr in den Lagern der Waldpfotengnolle gefunden habt, war für den kleinen Streckenposten Thalanaar im Südosten Feralas' bestimmt. Das Paket, ungeachtet des Schicksals des vermissten Kuriers, harrt immer noch der Auslieferung.$B$BIhr untersucht das Paket genauer und entdeckt den Namen 'Falfindel Waywarder' handschriftlich auf der Verpackung vermerkt. Vielleicht ist er der eigentliche Empfänger des Pakets.",objectives={"Bringt das nicht ausgelieferte Paket zu Falfindel Waywarder in Thalanaar."}]])
R(4282,"Ein Funken Hoffnung",[[description="<Marshal Windsor wedelt aufgeregt mit der Notiz herum.>$B$BWisst Ihr, was das bedeutet, $N?$B$BVielleicht ist doch noch nicht alles verloren! Soweit ich das erkennen kann, wird die Information von zwei Dunkeleisenzwergen verwahrt: General Zornesschmied und dem Golemlord Argelmach. Ich habe das Gefühl, als würden sie die Information nicht einfach so herausrücken, wenn wir sie freundlich darum bitten.$B$BAlso hoffe ich, dass Ihr auf einen Kampf vorbereitet seid.$B$BZieht aus und findet die beiden Bösewichte! Vernichtet sie und bringt mir meine verloren gegangenen Informationen zurück.",objectives={"Holt Marshal Windsors verloren gegangene Informationen zurück.$B$BMarshal Windsor glaubt, dass sich die Informationen in den Händen des Golemlords Argelmach und des Generals Zornesschmied befinden."}]])
R(4283,"FÜNFZIG! Jawoll!",[[description="Ich werde Euch ein kleines Geheimnis verraten, Soldat: Kommt näher.$B$BICH BIN HIER DER EINZIGE, DER NOCH BEI VERSTAND IST!$B$BSeht Euch nur all diese Leute an! Ist es zu fassen, dass sie alle irre sind!? Oh ja, das sind sie! DURCHGEDREHT! WAHNSINNIG!$B$B<Oralius senkt die Stimme.>$B$BDas bleibt aber unter uns: mir, Euch und meinem Kumpel Käpt'n Winky.$B$B<Oralius greift in die Luft und drückt zu.>$B$BWie auch immer ... Ich sammle Abzeichen, die gut zu meiner Sammlung Ogerohren passen. Orcs sind der letzte Schrei. Fünfzig. LOS!$B$B<Oralius stößt in ein Horn.>$B$BAB DAMIT!",objectives={"Oralius will 50 Medaillons der Blackrock haben. Die Chancen stehen gut, dass man die Medaillons bei den Orcs in der brennenden Steppe findet."}]])
R(4284,"Machtkristalle",[[description="Ich bin sicher, Ihr habt sie bemerkt, $n. Sie sind überall!$B$BWovon ich rede? Na, von den Kristallen natürlich!$B$BDie Kristalle... Sie liegen überall im Krater herum. Die meisten Leute ignorieren sie, aber ich habe das seltsame Gefühl, als besäßen sie eine gewisse Macht. Ich habe eine Weile mit ihnen herumexperimentiert, aber ich habe noch nichts herausgefunden. Tja, bis jetzt jedenfalls.$B$BAber hört mal, mir gehen langsam die Kristalle aus - meint Ihr, Ihr könntet noch ein paar für mich sammeln?",objectives={"Sammelt 7 Machtkristalle von jeder Farbe: rot, blau, gelb und grün. Bringt sie zu J. D. Collie in Marshals Zuflucht."}]])
R(4285,"Der Nordpylon",[[description="Wofür die wohl gut sind? Ich muss ständig daran denken!$B$BEs macht mich verrückt, dass all die Gerüchte über die Kristallpylonen wahr sind. Nennt mich leichtgläubig, aber ich glaube gewöhnlich, was mir die Leute erzählen.$B$BWie dem auch sei, ich habe gehört, dass sich einer dieser Kristallpylonen hier ganz in der Nähe befinden soll. Irgendwo im Norden ... Sucht ihn doch bitte, $N. Ich weiß genau, dass es die Dinger gibt.",objectives={"Findet den Standort des nördlichen Kristallpylonen im Un'Goro Krater."}]])
R(4286,"Feine Sachen",[[description="Käpt'n Winky sagt mir, dass die Dunkeleisenzwerge in den Tiefen das ganze gute Zeug haben. Stimmt's nicht, Winky?$B$B<Oralius versucht, so gut es geht, einen Piraten zu imitieren.>$B$BHARRR, KUMPEL! DAS STIMMT!$B$BDa hört Ihr's. Ihr müsst Euch dorthin begeben und mir etwas von dem guten Zeug besorgen.$B$BGeht da rein und holt es Euch!",objectives={"Reist in die Blackrocktiefen und holt 20 Dunkeleisengürteltaschen. Kehrt zu Oralius zurück, sobald die Aufgabe erledigt ist. Ihr nehmt an, dass die Dunkeleisenzwerge in den Blackrocktiefen diese 'Gürteltaschen'-Dinger tragen."}]])
R(4287,"Der Ostpylon",[[description="Während meines Aufenthaltes hier sind mir seltsame Gerüchte über rätselhafte Pylonen zu Ohren gekommen, die es angeblich draußen in der Wildnis des Kraters geben soll, $n. Ich nehme an, sie sind ziemlich groß, mit Kristallen an den Innenseiten.$B$BIch habe zwar noch nie welche gesehen, aber ich komme nicht umhin zu glauben, dass die Gerüchte wahr sind - und dass die Pylonen irgendetwas mit all den Kristallen zu tun haben, die wir gefunden haben.$B$BAlso, warum helft Ihr mir nicht, meine Neugier zu stillen? Angeblich soll es einen im östlichen Teil des Kraters geben. Meint Ihr, Ihr könntet ihn finden?",objectives={"Findet den Standort des östlichen Kristallpylonen im Un'Goro Krater."}]])
R(4288,"Der Westpylon",[[description="Meine Experimente haben bis jetzt noch keine positiven Ergebnisse erzielt, $N. Ich kann nur hoffen, dass Ihr eine Lösung findet, indem Ihr einen der Pylonen entdeckt, von denen ich gehört habe.$B$BWas, wenn wir bestimmte Farben mit ihnen kombinieren würden ... ach, eines nach dem anderen. Zuerst müssen wir sie finden!$B$B$N, sucht im westlichen Teil des Kraters. In diesem Gebiet soll sich irgendwo ein Pylon befinden.",objectives={"Findet den Standort des westlichen Kristallpylonen."}]])
R(4289,"Die Affen von Un'Goro",[[description="In diesem Krater gibt es viele seltsame Kreaturen - sie scheinen edler zu sein als ihre Verwandten, die man überall in meinem Heimatland und jenseits davon findet. Ich habe keine Erklärung dafür, aber dieser Ort trägt die Handschrift der Erdenmutter. Immer, wenn ich auf eines ihrer wundervollen Geschöpfe in diesem Krater stoße, erweise ich ihr meine Ehrerbietung.$B$BWenn auch Ihr diese Erleuchtung spüren möchtet, die eine solche Tat begleitet, dann geht nach Norden. Dort findet Ihr große Affen, die die Kraft eines jeden Sterblichen auf eine harte Probe stellen. Bringt mir ihre Pelze ... beweist mir Eure Kraft.",objectives={"Bringt Torwa Pathfinder am Eingang zum Un'Goro Krater 2 Un'Goro-Gorillapelze, 2 Un'Goro-Stampferpelze und 2 Un'Goro-Donnererpelze."}]])
R(4290,"Lar'korwis Mahl",[[description="Einst, vor sehr langer Zeit, stahl einer meiner Brüder ein Stück Fleisch aus Lar'korwis Jagdbeute. Damals wusste er es nicht, aber Lar'korwi hat ihn vom Wald aus beobachtet. Lar'korwi folgte meinem Bruder tagelang und vernichtete alles, was er berührte. Mein Bruder, von Angst erfüllt, entschloss sich schließlich, aus dem Krater zu fliehen, um Lar'korwi zu entkommen.$B$BLar'korwi tötete ihn, nicht weit von dieser Stelle entfernt.$B$BWenn Ihr Lar'korwi provozieren wollt, sucht nach seiner letzten Jagdbeute und stehlt ihm etwas Fleisch.$B$BKommt dann zu mir zurück.",objectives={"Sucht das Gerippe von Lar'korwis letzter Jagdbeute und stehlt einen Teil eines Dreschadongerippes; kehrt dann zu Torwa Pathfinder im Un'Goro Krater zurück."}]])
R(4291,"Lar'korwis Fährte",[[description="Ich bin wirklich erstaunt, dass er noch nicht hinter Euch her ist, $N. Alles läuft jedoch gut, denn ich habe einen letzten Plan, mit dem wir das Monster zu uns locken können.$B$BAls dominantem Männchen steht es Lar'korwi zu, sich mit jedem Weibchen zu paaren, das ihm gefällt - und ihm gefallen viele. Westlich von hier werdet Ihr eine Menge Ravasaurus-Eier finden. Tretet dicht an sie heran, um damit einen Angriff seiner Artgenossen zu provozieren. Die Weibchen produzieren in einer Drüse an ihrem Kopf einen abscheulichen Gestank, der die Männchen wissen lässt, dass sie paarungsbereit sind. Bringt mir zwei dieser Drüsen.",objectives={"Bringt Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater 2 Ravasaurus-Pheromondrüsen."}]])
R(4292,"Ein Köder für Lar'korwi",[[description="Das hier wird der schwierigste Teil werden, denn der Plan ist etwas kompliziert. Nördlich von hier findet Ihr einen kleinen Pfad, der in die Berge hinaufführt. Dort habe ich Lar'korwi zuletzt gesehen. Ihr werdet wissen, dass Ihr im richtigen Gebiet seid, wenn Ihr all die Knochen der großen Kreaturen findet, die es dort einst gab. Nehmt das Fleisch, das Ihr Euch besorgt habt, und legt es dort ab. Reibt das Fleisch dann mit der Drüse ein. Wenn es mit beiden Lockmitteln zusammen nicht gelingt, Lar'korwi zu Euch zu locken, dann weiß ich auch nicht weiter.",objectives={"Beschwört Lar'korwi mit dem Inhalt von Torwas Beutel und besiegt ihn. Bringt dann Lar'korwis Kopf zu Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater."}]])
R(4293,"Eine Brühschleimerprobe...",[[description="Der Teufelswald ist ein Wald weit im Norden des Brachlandes, sogar noch weiter weg als Ashenvale. Dort kann man an durch die Berührung von Fel gesegneten Teichen überall Brühschlammer finden. Die Geißel hat mit den Angriffen von Höllenbestien und anderer Dämonenmagie die Gegend stark verwüstet - die Brühschlammer sind angeblich während dieser Angriffe aus der Erde an die Oberfläche gekrochen.$B$BSammelt einige Proben von Teufelswaldbrühschlammern, dann verwenden wir die Testausrüstung hier neben mir, um eine Kontrollgruppe zusammenzustellen, mit der wir die anderen Proben, die Ihr einsammelt habt, vergleichen können.",objectives={"Sammelt Teufelswaldschleimproben von den Brühschlammern im Teufelswald. Verwendet dann die Testausrüstung neben Chemiker Fuely in Undercity, um zu sehen, welche Eurer Proben am verderbtesten sind. Bringt 5 der verderbten Teufelswaldproben, die Ihr findet, zu Chemiker Fuely."}]])
R(4294,"...und eine Menge Brühschlammer",[[description="Habt Ihr schon einmal vom Un'Goro Krater gehört, $N? Er liegt in der Nähe der Tanariswüste und es ist ein großartiger Ort: üppig, von Leben sprühend, voller Kreaturen und Pflanzen.$B$BDorthin müsst Ihr Euch begeben. Ich habe mir sagen lassen, dass der Krater noch völlig unbesudelt und frei von Einflüssen von außen sei. Erst jetzt beginnen Forscher, seine Geheimnisse zu entdecken.$B$BIch würde die dortigen Brühschleimer und Brühschlammer gern testen. Wenn es stimmt, dass sie nicht verderbt sind, dann würde ich gern wissen, wie sich solche Kreaturen entwickelt haben.",objectives={"Sammelt Un'Goro-Brühschleimerproben von jedem der Brühschleimer im Un'Goro Krater. Verwendet dann die Testausrüstung neben Chemiker Fuely in Undercity, um zu sehen, welche Eurer Proben am reinsten sind. Bringt 5 der reinen Un'Goro-Proben, die Ihr findet, zu Chemiker Fuely."}]])
R(4295,"Rocknots Bier")
R(4296,"Schrifttafel der Sieben",[[description="Die Legenden der Sieben führten mich in die Brennende Steppe. Sie waren hoch gebildete und mächtige Zwerge, und wenn man über Wissen und Macht verfügt, so ist das der Schlüssel zum Reichtum.$B$BUnd genau das ist es, was ich will. Reichtum!$B$BWenn wir mehr über die Sieben in Erfahrung bringen könnten, würde das uns beide vielleicht reich machen. In den Ruinen von Thaurissan soll sich angeblich die Schrifttafel der Sieben befinden, auf der das Wissen über die alten Zwerge geschrieben steht. Sucht diese Schrifttafel, kopiert den Text und bringt ihn mir. Lasst uns deren Geheimnisse gemeinsam entschlüsseln!",objectives={"Bringt Maxwort Uberglint in der brennenden Steppe die Abschrift der Schrifttafel."}]])
R(4297,"Essen für das Baby",[[description="Grimmlingflitzer sind Allesfresser - das bedeutet, dass sie sowohl Fleisch als auch Grünzeug fressen. Wenn dieses Junge hier schlüpft, sollten wir vorbereitet sein. Es ist kaum zu glauben, aber diese kleinen Kerlchen ernährt man am besten mit Fleischstücken, roh und saftig. Ich habe nie herausgefunden, warum das so ist, aber es muss wohl etwas mit Elunes Plan für die Elfen zu tun haben ... vielleicht waren sie als Beschützer oder so etwas vorgesehen, ich weiß es nicht.$B$BIch kümmere mich vorerst um das Ei. Warum besorgt Ihr nicht ein paar Silbermähnenpirscherflanken, mit denen wir das Junge füttern können, sobald es geschlüpft ist?",objectives={"Bringt Agnar Beastamer im Hinterland 5 Silbermähnenpirscherflanken."}]])
R(4298,"Elternfreuden",[[description="He, es war wohl schon weiter, als ich dachte...",objectives={"Sprecht mit Agnar Beastamer im Hinterland."}]])
R(4299,"<NYI> <TXT>The Tomb of the Seven",[[description="Find the Tomb of the Seven, and place this PX83-Enigmatron there.  ",objectives={"Place the PX83-Enigmatron in the Tomb of the Seven, then return to Maxwort Uberglint."}]])
R(4300,"Knochenklingenwaffen",[[description="Hmm, jetzt, wo ich darüber nachdenke, könnte es doch etwas geben, das Ihr für die Hand erledigen könntet. Ja, Jes'rimon könnte bestimmt Eure Hilfe brauchen.$B$BIm Un'Goro Krater gibt es Raptoren mit tödlichen Klauen. Manche dieser Raptoren haben weiße Klauen statt schwarze wie der Tod. Die Mitglieder der Hand haben ... Kunden ..., denen aus diesen Klauen gefertigte Waffen gefallen. Bringt mir reichlich von diesen weißen Klauen, dann werde ich Euch gut entlohnen. Wenn Ihr das schnell genug tut, dann kann ich Euch vielleicht noch auf andere Weise helfen.",objectives={"Bringt Jes'rimon in Orgrimmar 8 weiße Ravasaurusklauen."}]])
R(4301,"Der mächtige U'cha",[[description="Während Ihr Un'Goro erkundet habt, sind mir ein paar andere Dinge aufgefallen, die einem mächtigen Jäger wie Euch sicher gefallen würden. Zum Beispiel gibt es da einen gewaltigen Affen unter den Gorillas im Norden. Ihr seid schon einmal in dieser Höhle gewesen, aber dieses Mal frage ich mich doch, ob Ihr die Begegnung mit ihm wohl überleben würdet, solltet Ihr meine Aufgabe annehmen.$B$BIch nenne ihn U'cha und er ist einer der größten Söhne der Erdenmutter, da könnt Ihr sicher sein. Besiegt U'cha und bringt mir seinen Pelz. Wenn Euch das gelingt, habt Ihr das Recht darauf, ein großer Jäger genannt zu werden.",objectives={"Bringt U'chas Pelz zu Torwa Pathfinder am Eingang des Un'Goro Kraters."}]])
R(4321,"Die Sache verstehen",[[description="Die Information über die Pylonen, die Ihr mir gabt, ist sehr interessant...$B$BGebt mir einen Moment Zeit, um ein paar Berechnungen anzustellen, $n. Sprecht mich demnächst noch einmal an, dann sollte ich Euch die Antwort geben können, nach der wir gesucht haben.",objectives={"Sprecht demnächst mit J. D. Collie."}]])
R(4322,"Gefängnisausbruch!",[[description="Wir müssen hier weg, $N. Helft mir, meine Ausrüstung aus dem Vorratsbereich zu holen und meine Freunde zu befreien. Falls wir hier rauskommen, dann müsst Ihr Euch weiter nach Morgans Wacht durchschlagen und mit Marshal Maxwell sprechen. Er wird Euch weitere Anweisungen geben.",objectives={"Helft Marshal Windsor, seine Ausrüstung zurückzuholen und seine Freunde zu befreien. Kehrt zu Marshal Windsor zurück, wenn Ihr Erfolg hattet."}]])
R(4323,"<NYI> <TXT> Get those Hyenas!!!",[[description="I want some Hyena Pelts, and only the best will do!  Get me spotted Hyena pelts and I'll give you phat lewtz, yo.",objectives={"Bring 7 Spotted Hyena Pelts to TESTTAUREN at Freewind Post."}]])
R(4324,"Yuka Screwspigot",[[description="Mein Bruder Ribbly war sein ganzes Leben lang zu nichts nütze; aber jetzt, glaube ich, hat er endlich einen gewissen Wert! Aber... wir werden Eure Hilfe brauchen, um aus Ribblys Wert Kapital zu schlagen.$B$BMeine Schwester Yuka hat ihn wochenlang gesucht und endlich in der Brennenden Steppe gefunden. Sie hat mich wissen lassen, dass sie ein paar Helfer brauchen könnte.$B$BAlso, was meint Ihr? Wollt Ihr uns helfen? Falls ja, sprecht mit meiner Schwester. Ihr findet sie im Flammenkamm versteckt, in einer Höhle nordwestlich des Schreckensfelsens.",objectives={"Sprecht mit Yuka Screwspigot in der brennenden Steppe."}]])
R(4341,"Kharan Mighthammer",[[description="Seid Ihr in den rauchenden Ruinen von Thaurissan gewesen? Seid Ihr dort zufällig einem erbärmlichen Tölpel namens Kharan Mighthammer begegnet? Dem Zwerg, der eigentlich über mein kleines Mädchen wachen sollte?$B$B<Der König schluchzt.>$B$BUnd jetzt ist sie verschwunden, $N!$B$BIch habe meine Leute die gesamte Steppe durchkämmen lassen. Doch der einzige Hinweis, den sie über den Verbleib meiner Tochter finden konnten, war, dass sie vielleicht in den Tiefen ist. Möglicherweise ist sie sogar schon tot!$B$BAngeblich wird Kharan dort als Gefangener festgehalten ... findet ihn! Ich will Antworten!",objectives={"Begebt Euch in die Blackrocktiefen und findet Kharan Mighthammer.$B$BDer König erwähnte, dass Kharan dort gefangen sei - vielleicht solltet Ihr nach einem Gefängnis Ausschau halten."}]])
R(4342,"Kharans Geschichte",[[description="Bitte hört mich an, ehe Ihr ein Urteil fällt!",objectives={"Lasst Kharan Mighthammer seine Geschichte erzählen."}]])
R(4343,"Verderbte Windblüte")
R(4361,"Der Überbringer schlechter Botschaften...",[[description="Ihr müsst König Magni diese Informationen bringen, $n. Er wird wissen, was zu tun ist!",objectives={"Kehrt nach Ironforge zurück und überbringt König Magni Bronzebeard die schlechten Nachrichten."}]])
R(4362,"Das Schicksal des Königreichs",[[description="Es scheint, als habe mein alter Widersacher, Dagran Thaurissan, mich und das ganze Königreich Ironforge in seiner Gewalt.$B$BVielleicht seid Ihr meine letzte Hoffnung, $N. Ihr müsst meine Tochter Moira retten!$B$BEs gibt nur einen Weg, wie der Zauber, mit dem Thaurissan Moira belegt hat, wirklich zuverlässig gebrochen werden kann: Ihr müsst ihn töten.$B$BAber, $N, meiner Tochter dürft Ihr kein Leid zufügen! Vergesst nicht, dass sie Thaurissans Kontrolle unterliegt! Alles, was sie vielleicht sagt oder tut, geschieht aufgrund von Thaurissans bösem Zauber!",objectives={"Kehrt in die Blackrocktiefen zurück und rettet Prinzessin Moira Bronzebeard aus den Fängen des bösen Imperators Dagran Thaurissan."}]])
R(4363,"Die Überraschung der Prinzessin",[[description="Thaurissan war ein großer und ehrenhafter Zwerg. Ihr habt mein Leben zerstört - meines und das meines ungeborenen Kindes!$B$B<Ihr habt den Eindruck, als leide Prinzessin Bronzebeard noch immer unter den letzten Auswirkungen des vom Imperator gewirkten Zaubers.>$B$BKehrt nach Ironforge zurück und sagt meinem Vater, dass der Erbe des Königreichs Ironforge ein Dunkeleisenzwerg sein wird.$B$BOb er dies billigt oder nicht, so wird es sein.",objectives={"Kehrt nach Ironforge zurück und sprecht mit König Magni Bronzebeard."}]])
R(4381,"Kristallflicker")
R(4382,"Kristallkraft")
R(4383,"Kristallbarriere")
R(4384,"Kristallschwächer")
R(4385,"Kristallsprengladung")
R(4386,"Kristallspitze")
R(4401,"Verderbte Liedblume")
R(4402,"Galgars Kaktusapfel Surprise",[[description="Hier im Tal der Prüfungen wird es ganz schön heiß.$B$B<Galgar wischt sich den Schweíß von der Stirn.>$B$BWenn ich doch nur ein paar Kaktusäpfel hätte, dann könnte ich meinen berühmten Kaktusapfel Surprise machen! Nichts kühlt einen schneller ab als ein Stück dieser leckeren Spezialität.$B$BIch sag Euch was, $N. Wenn Ihr mir 10 Kaktusäpfel bringt, dann mache ich Euch ein paar Portionen Kaktusapfel Surprise, die Ihr mit auf Eure Abenteuer nehmen könnt. Falls Ihr daran interessiert seid, findet Ihr Kaktusäpfel bei den Kaktuspflanzen, die hier in der Gegend wachsen.",objectives={"Bringt Galgar 10 Kaktusäpfel. Ihr erinnert Euch, dass er gesagt hat, man fände sie in der Nähe von Kakteen."}]])
R(4403,"Verderbte Windblüte")
R(4421,"Die Verderbnis der Jadefeuer",[[description="Nicht viele kommen hierher und suchen das Abenteuer... Die Verderbnis hat sich im Teufelswald überall ausgebreitet und macht vor nichts Halt.$B$BAls Mitglied des Smaragdkreises trachte ich danach, dieses Land zu heilen. Doch es gibt andere, die wünschen, dass es weiter schwärt.$B$BIch spreche von den Jadefeuersatyrn, die sich südwestlich von hier aufhalten, bei den Ruinen von Constellas. Ihr Anführer ist ein besonders grausamer Satyr namens Xavathras und unter seiner Führung übertragen sie die Krankheit auf alle Wesen, denen sie begegnen.$B$BWir müssen dieses Land, das einst das unsrige war, verteidigen. Besiegt Xavathras und vernichtet seine Diener.",objectives={"Tötet Xavathras sowie 11 Jadefeuerteufelsanbeter, 9 Jadefeuerschattenpirscher und 9 Jadefeuerschurken. Kehrt zu Eridan Bluewind im Teufelswald zurück, sobald die Aufgabe erledigt ist."}]])
R(4441,"Gebundene Urtume",[[description="Die Flöte, die Ihr gefunden habt, wurde aus einem Urtumbeschützer geschnitzt, den Treantverbündeten, die schon immer treu über die Nachtelfen gewacht haben.$B$BEs ist den Satyrn gelungen, alles zu verderben, mit dem sie in Kontakt kommen, einschließlich der Urtume, die im Teufelswald lebten. Mit Hilfe der teuflischen Verderbnis wurde der Geist des Urtums gefangen und gefoltert und nie wieder völlig freigegeben. Der Teufelsbinder, den Ihr gefunden habt, hängt ganz ohne Zweifel damit zusammen.$B$BWir müssen versuchen, die Flöte zu läutern, $N. Bringt mir gesegnetes Wasser vom Tempel des Mondes in Darnassus.",objectives={"Begebt Euch nach Darnassus und verwendet Eridans Phiole, um Euch im Tempel des Mondes eine Phiole mit gesegnetem Wasser zu holen. Kehrt mit der gefüllten Phiole zu Eridan zurück."}]])
R(4442,"Geläutert!",[[description="Ich werde jetzt versuchen, die Flöte mit dem Wasser von Elune zu läutern. Wir müssen diesem Leiden ein Ende machen...$B$BMöge Elune meine Hände und mein Herz leiten.$B$BSprecht mich gleich noch einmal an.",objectives={"Sprecht Eridan gleich noch einmal an."}]])
