R(8409,"Verdorbenes Bier",[[description="Die faulen Eier wurden wie geplant in den Braukessel geworfen. Zukünftige Ladungen Bier des Gasthauses von Süderstade sind somit erfolgreich verdorben worden!$B$BIhr solltet jetzt zurück zu Ruferin der Dunkelheit Yanka beim Fest des Weidenmanns in Tirisfal gehen und ihr von Eurem Erfolg berichten.",objectives={"Kehrt zur Ruferin der Dunkelheit Yanka beim Fest des Weidenmanns in Tirisfal zurück."}]])
R(8410,"Elementarbeherrschung",[[description="Bath'rah der Windbehüter sucht nach einem Schamanen von Eurer Weisheit. Als Zeichen Eurer Bereitschaft bittet er Euch, ihm Proben eines jeden Elements zu bringen.$B$BUm Bath'rah zu finden, begebt Euch zu dem Fluss östlich von Tarrens Mühle. Folgt seinem Verlauf Richtung Norden, irgendwann trefft Ihr auf die Ruinen, in denen sich Bath'rah niedergelassen hat.",objectives={"Bath'rah der Windbehüter möchte, dass Ihr jeweils eine Probe Luft, Feuer, Erde und Wasser für ihn sammelt."}]])
R(8411,"Die Beherrschung der Elemente",[[description="Willkommen, $C. Bringt mir zuerst die Elemente und dann unterhalten wir uns.$B$BIch brauche erst das Feuer, die Luft, das Wasser und die Erde, bevor ich Euch vertraue, Mann. Ich muss wissen, ob Ihr gut unterrichtet seid.",objectives={"Bringt Bath'rah dem Windbehüter die Elemente Erde, Luft, Feuer und Wasser."}]])
R(8412,"Geistertotem",[[description="Die Elementare an diesem Ort haben sich gegen mich gewendet.$B$BIhr kennt Euch mit den Mächten der Totems besser als jeder andere aus und ich brauche jetzt ein Geistertotem zu meinem Schutz. Wir haben bereits die Elemente, jetzt brauchen wir etwas mit noch mehr Natur. Etwas noch Wilderes.$B$BIn den Westlichen Pestländern könnt Ihr Bären für Klauen und Spinnen für Augen töten. Mit etwas Glück, könnt Ihr beides auch bei den dort lebenden Aasgeiern finden, sie fressen alles.",objectives={"Bringt Bath'rah dem Windbehüter die Komponenten für das Geistertotem."}]])
R(8413,"Die Macht des Voodoos",[[description="Das Geistertotem alleine ist nicht stark genug. Um erfolgreich zu sein, benötigen wir noch etwas Voodoomagie.$B$BDie Trolle im Versunkenen Tempel besitzen Federn, die von mächtiger Voodoomagie erfüllt sind. Begebt Euch dorthin und besiegt Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Mit ihren Federn haben wir genug Macht, um ein starkes Geistertotem zu formen.",objectives={"Bringt Bath'rah dem Windbehüter die Voodoofedern."}]])
R(8414,"Austreibung des Bösen",[[description="Seid gegrüßt, $C. Kreuzfahrer wie Ihr werden in solch abgeschiedenen Gegenden gerne gesehen.$b$bEure heilige Stärke wird gebraucht, um uns bei der Vernichtung der unzähligen Untoten hier zu helfen. Genau genommen bräuchten wir Euch, um eine große Anzahl von Geißelsteinen zu sammeln und sie anschließend zu Hohepriester Thel'danis zu bringen. Der Hohepriester bewacht Uthers Grabmal in Trauerhügel, nicht weit von hier.$b$bNur jemand mit einer Anstecknadel der Argentumdämmerung kann darauf hoffen Geißelsteine zu finden, sprecht also mit Offizier Reinherz, wenn Ihr noch keine besitzt.",objectives={"Sammelt 20 Geißelsteine des Dieners und bringt sie zu Hohepriester Thel'danis in den Westlichen Pestländern."}]])
R(8415,"Chillwindspitze",[[description="Kommandant Ashlam Ehrenschlag sucht nach einem Paladin Eurer Reinheit und Euren Mutes, $n. Ihr könnt ihn im Zugwindlager im Süden der Westlichen Pestländer finden. Sucht nach ihm und helft ihm im Namen des Lichts!",objectives={"Sprecht mit Kommandanten Ashlam Ehrenschlag im Zugwindlager."}]])
R(8416,"Gereinigte Geißelsteine",[[description="Das Böse wurde aus diesen Steinen getrieben, $n.$b$bIch weiß über Kommandant Ashlams Pläne Bescheid, er wird nur nach einem einzigen, gereinigten Geißelstein verlangen. Bringt ihn zu ihm, damit wir die Geißel ins Feuer der Gerechtigkeit tauchen können.",objectives={"Bringt den gereinigten Geißelstein zu Kommandant Ashlan Ehrenschlag an der Zugwindspitze."}]])
R(8417,"Ein geplagter Geist",[[description="In den Verwüsteten Landen gibt es einen geplagten Geist, der einst ein großer Held der Horde war. Die Ehre eines Kriegers stirbt nicht mit seinem Körper und es würde für Euch von Wert sein mit ihm zu sprechen.",objectives={"Sprecht mit dem gefallenen Helden der Horde am Eingang zu den Verwüsteten Landen."}]])
R(8418,"Erschaffung des Steins der Macht",[[description="Jetzt müssen wir die gereinigten Geißelsteine kombinieren und eine Waffe herstellen, die die Reihen der Untoten erschüttert. Das ist keine einfache Aufgabe, $n. Nur die Trolle des Versunkenen Tempels besitzen diese Art seltener Magie, die fähig ist, das Böse von etwas gegen sich selbst zu richten.$b$bIm Tempel sind die Trolle bekannt als Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Verspürt keine Reue für ihre verderbten Seelen... sie sind nicht frei von Bösem.",objectives={"Beschafft Euch gelbe, blaue und grüne Voodoofedern von den Trollen im Versunkenen Tempel."}]])
R(8419,"Die Bitte eines Wichtels",[[description="$n, ein Wichtel im Teufelswald namens Impsy hat nach Euch verlangt. Seine Bitte ist etwas merkwürdig, da er möchte, dass Ihr ihm ein Stück Teufelsstoff als Zeichen des guten Willens bringt. Bedenkt man die Macht, die Ihr bereits als Hexenmeister besitzt, kann ich nur vermuten, dass Ihr wisst, dass die Satyrn des Teufelswalds diesen Teufelsstoff bei sich tragen.$b$bIhr findet Impsy nördlich der Blutgiftfälle, von denen ich hörte, dass sie um diese Jahreszeit recht schön sein sollen.",objectives={"Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald."}]])
R(8420,"Heiß und brennend",[[description="Vielleicht klingt es ja etwas komisch bei einem Wichtel, aber ich würde gerne meinen eigenen Begleiter haben. Das hätte ich wirklich gerne. Es ist nicht gerecht, dass Niby mich hat und ich niemanden!$b$bEs braucht ja gar nicht lebendig zu sein. Ich bräuchte etwas, um mit der Anfertigung beginnen zu können, zum Beispiel etwas Teufelsstoff. Die Satyrn hier im Teufelswald haben manchmal Teufelsstoff, Ihr müsstet also nur genug von ihnen töten, um welchen zu finden. Das hört sich doch gut an, oder?",objectives={"Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald."}]])
R(8421,"Das richtige Zeug",[[description="Jetzt, da ich meinen Teufelsstoff habe, kann ich wirklich mit der Anfertigung *meines* Begleiters beginnen.$b$bIch werde etwas für die Augen brauchen. Vielleicht könnt Ihr mir etwas faules Holz vom Stamm der Eisenstämme besorgen, damit ich daraus ein Paar wunderschöne Augen schnitzen kann. Ihr findet sie im Norden, im Eisenwald.$b$bIch brauche auch etwas Blutgiftessenz, um meinem Begleiter diesen neuen dämonischen Duft zu verleihen. Die besudelten Schlamme haben diese Essenz und Ihr könnt sie gleich hier in der Nähe von Niby und mir finden.",objectives={"Bringt 10 Stück faules Holz und 4 Blutgiftessenzen zu Impsy im Teufelswald."}]])
R(8422,"Federn von Trollen",[[description="Mein Begleiter ist fast fertig. Jetzt brauche ich nur noch etwas als Füllmaterial.$b$bNur die Voodoofedern von den Trollen aus dem Versunkenen Tempel sind dafür geeignet. Sie heißen Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Tötet sie. Tötet sie alle.$b$bDies ist keine gewöhnliche Aufgabe $n, also werde ich Eure Bemühungen belohnen, indem ich Euch etwas von Niby gebe - er wird es sowieso nicht mehr brauchen.",objectives={"Bringt 6 Voodoofedern von den Trollen aus dem Versunkenen Tempel."}]])
R(8423,"Kriegerverwandtschaft",[[description="<Der Held betrachtet Euch.>$b$bIhr seid ein $C, ohne Zweifel. Ich würde Euch um eine ehrenhafte Aufgabe bitten, aber zuerst muss ich Eure Stärke testen.$b$bMan sagt, dass Rexxar die Schärfe seiner Klingen misst, indem er einen Hölleneber mit nur einem einzigen, schnellen Schlag erlegt. Jetzt werde ich Eure Stärke auf die gleiche Art messen.",objectives={"Tötet 7 Hölleneber in den Verwüsteten Landen und kehrt zu dem gefallenen Helden der Horde zurück."}]])
R(8424,"Krieg den Schattenanbetern",[[description="Die weiterhin bestehende Gegenwart der Schattenanbeter in den Verwüsteten Landen ist schmerzhaft für mich. Ihre dunklen Rituale und Zauber bereiten mir heute mehr Qualen als es zu meinen Lebzeiten je etwas hätte tun können.$b$bIch kann ihnen mit Eurer Hilfe eine schmerzhafte Botschaft überbringen. Zieht hinfort und lasst meinen Zorn sprechen.",objectives={"Merzt die Schattenanbeter in den Verwüsteten Landen aus und kehrt zum gefallenen Helden der Horde zurück."}]])
R(8425,"Voodoofedern",[[description="Eure Ehre hat mir zu ein wenig Frieden verholfen. Es ist mehr als gerecht, dass ich Euch etwas im Gegenzug dafür gebe.$b$bMeine Waffen und meine Rüstung waren zu meinen Lebzeiten prächtig, aber jetzt habe ich keine Verwendung mehr dafür. In Euren Händen würden sie einem besseren Zweck dienen.$b$bReist zu dem Versunkenen Tempel und tötet die Trollwächter Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Sie tragen magische Federn, die meinen physikalischen Körper lange genug neu bilden können, damit ich Euch belohnen kann.",objectives={"Bringt die Voodoofedern der Trolle im Versunkenen Tempel zu dem gefallenen Helden der Horde."}]])
R(8426,"Schlacht der Warsongschlucht",[[description="Der Kampf gegen die Schildwachen der Silberschwingen in der Kriegshymnenschlucht ist von großer Bedeutung. Unter dem Vorwand einen Wald zu beschützen, der ihnen nicht gehört, versucht die Allianz der Horde eines unserer größten Holzvorkommen streitig zu machen.$B$BLasst dies nicht zu, $n! Kommt zu mir mit einem Beweis für ehrvolle Taten im Namen der Horde zurück!",objectives={"Bringt 3 Ehrenabzeichen der Kriegshymnenschlucht zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder."}]])
R(8427,"Schlacht der Warsongschlucht",[[description="Der Kampf gegen die Schildwachen der Silberschwingen in der Kriegshymnenschlucht ist von großer Bedeutung. Unter dem Vorwand einen Wald zu beschützen, der ihnen nicht gehört, versucht die Allianz der Horde eines unserer größten Holzvorkommen streitig zu machen.$B$BLasst dies nicht zu, $n! Kommt zu mir mit einem Beweis für ehrvolle Taten im Namen der Horde zurück!",objectives={"Bringt 3 Ehrenabzeichen der Kriegshymnenschlucht zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder."}]])
R(8428,"Schlacht der Warsongschlucht",[[description="Der Kampf gegen die Schildwachen der Silberschwingen in der Kriegshymnenschlucht ist von großer Bedeutung. Unter dem Vorwand einen Wald zu beschützen, der ihnen nicht gehört, versucht die Allianz der Horde eines unserer größten Holzvorkommen streitig zu machen.$B$BLasst dies nicht zu, $n! Kommt zu mir mit einem Beweis für ehrvolle Taten im Namen der Horde zurück!",objectives={"Bringt 3 Ehrenabzeichen der Kriegshymnenschlucht zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder."}]])
