R(8765,"Den Pfad wechseln - Kein Herbeirufer mehr")
R(8766,"Den Pfad wechseln - Kein Eroberer mehr")
R(8767,"Ein leicht geschütteltes Geschenk")
R(8768,"Ein fröhlich verpacktes Geschenk")
R(8769,"Ein tickendes Geschenk")
R(8770,"Ziel: Verteidiger des Ashischwarms",[[description="Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Ashischwarms teilzunehmen. Eure Hauptziele sind die Verteidiger des Ashischwarms.$B$BErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.",objectives={"Tötet 30 Verteidiger des Ashischwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz I, um diese Aufgabe abschließen zu können."}]])
R(8771,"Ziel: Sandpirscher des Ashischwarms",[[description="Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Ashischwarms teilzunehmen. Eure Hauptziele sind die Sandpirscher des Ashischwarms.$B$BErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.",objectives={"Tötet 30 Sandpirscher des Ashischwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz II, um diese Aufgabe abschließen zu können."}]])
R(8772,"Ziel: Wegbehüter des Zoraschwarms",[[description="Es wurde Verstärkung für den Angriff auf den Bau des Zoraschwarms angefordert. Man hat Euch ausgewählt, um die Wegbehüter des Zoraschwarms anzugreifen. Erstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.",objectives={"Tötet 30 Wegbehüter des Zoraschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz VI, um diese Aufgabe abschließen zu können."}]])
R(8773,"Ziel: Häscher des Zoraschwarms",[[description="Es wurde Verstärkung für den Angriff auf den Bau des Zoraschwarms angefordert. Man hat Euch ausgewählt, um die Häscher des Zoraschwarms anzugreifen. Erstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.",objectives={"Tötet 30 Häscher des Zoraschwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz IV, um diese Aufgabe abschließen zu können."}]])
R(8774,"Ziel: Wegelagerer des Regalschwarms",[[description="Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Regalschwarms teilzunehmen. Eure Hauptziele sind die Wegelagerer des Regalschwarms.$B$BErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.",objectives={"Tötet 30 Wegelagerer des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz VIII, um diese Aufgabe abschließen zu können."}]])
R(8775,"Ziel: Feuerspucker des Regalschwarms",[[description="Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Regalschwarms teilzunehmen. Eure Hauptziele sind die Feuerspucker des Regalschwarms.$B$BErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.",objectives={"Tötet 30 Feuerspucker des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz IX, um diese Aufgabe abschließen zu können."}]])
R(8776,"Ziel: Sklavenjäger des Regalschwarms",[[description="Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Regalschwarms teilzunehmen. Eure Hauptziele sind die Sklavenjäger des Regalschwarms.$B$BErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.",objectives={"Tötet 30 Sklavenjäger des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz X, um diese Aufgabe abschließen zu können."}]])
R(8777,"Ziel: Einbuddler des Regalschwarms",[[description="Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Regalschwarms teilzunehmen. Eure Hauptziele sind die Einbuddler des Regalschwarms.$B$BErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.",objectives={"Tötet 30 Einbuddler des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz XI, um diese Aufgabe abschließen zu können."}]])
R(8778,"Die Ironforgebrigade braucht Sprengstoff!",[[description="Uns liegt eine Anforderung der Eisenschmiedebrigade vor, die eine Menge… na sagen wir, recht explosive Komponenten umfasst. Beschafft diese Komponenten und bringt sie zu einem Kerl namens Sprinkelstaub, einem Mitglied der Eisenschmiedebrigade.",objectives={"Bringt Arkanist Sprinkelstaub nahe des Zoraschwarmbaus in Silithus 6 Öle des Feuerbrandes, 5 Einheiten Goblinraketentreibstoff und 10 Einheiten dichtes Sprengpulver. Ihr benötigt auch Logistikeinsatz IV, um diese Aufgabe abschließen zu können."}]])
R(8779,"Magische Materialien",[[description="Geologin Lerchenbanns Studien haben sich für unsere Operationen in Silithus als sehr wertvoll erwiesen. Vor Kurzem hat sie eine Ladung magischer Materialien angefordert, die sie für ihre weiteren Forschungen dringend benötigt.$B$BBeschafft die notwendigen Materialien und liefert sie direkt an sie aus, damit Geologin Lerchenbann ihre Forschungen ungestört fortsetzen kann.",objectives={"Bringt 1 großen glänzenden Splitter, 1 großen strahlenden Splitter und 1 gewaltigen Smaragd zu Geologin Lerchenbann auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz V, um diese Aufgabe abschließen zu können."}]])
R(8780,"Rüstungssets für den Feldeinsatz",[[description="Der Eisenschmiedebrigade gehen im Feld die Rüstungssets aus. Schnappt Euch eine Ladung und bringt sie zu Janela Starkhammer am Posten der Eisenschmiedebrigade beim Zoraschwarmbau.",objectives={"Bringt 8 unverwüstliche Rüstungssets und 8 schwere Rüstungsset zu Janela Starkhammer am Posten der Eisenschmiedebrigade beim Zoraschwarmbau in Silithus. Ihr benötigt auch Logistikeinsatz VII, um diese Aufgabe abschließen zu können."}]])
R(8781,"Waffen für den Feldeinsatz",[[description="Die Eisenschmiedebrigade hat sich in den Kämpfen von Silithus als ein würdiger Verbündeter erwiesen. Unglücklicherweise hat sie auf dem Weg hierher die meisten ihrer Vorräte eingebüßt. Beschafft eine Ladung Waffen und bringt sie zu Janela Starkhammer nahe des Baus des Zoraschwarms.",objectives={"Bringt 2 Mondstahlbreitschwerter zu Janela Starkhammer am Posten der Eisenschmiedebrigade beim Zoraschwarmbau. Ihr benötigt auch Logistikeinsatz VI, um diese Aufgabe abschließen zu können."}]])
R(8782,"Uniformnachschub",[[description="Die letzte Ladung neuer Rekruten hat uns einen Engpass an Uniformen beschert. Beschafft uns eine Ladung Schneiderwaren, damit wir mehr Uniformen herstellen können. Bringt alles zur Windruferin Prachthorn.",objectives={"Bringt 1 Einheit Mondstoff, 2 Runenstoffballen und 1 Einheit Eisenweberseide zu Windruferin Prachthorn auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz VIII, um diese Aufgabe abschließen zu können."}]])
R(8783,"Besondere Materialien",[[description="Vargus, der Schmied von Burg Cenarius, hat verzauberte Materialien zur Herstellung von stärkeren Waffen angefordert. Beschafft die benötigten Materialien und bringt sie direkt zu Vargus, um den hohen Ausrüstungsstand unserer Truppen auf Burg Cenarius aufrechtzuerhalten.",objectives={"Bringt Vargus auf Burg Cenarius in Silithus 2 verzauberte Thoriumbarren und 2 Einheiten verzaubertes Leder. Ihr benötigt auch Logistikeinsatz IX, um diese Aufgabe abschließen zu können."}]])
R(8784,"Geheimnisse der Qiraji",[[description="Ihr habt ein uraltes Artefakt der Qiraji entdeckt! Vielleicht interessiert sich einer der Drachen am Eingang des Tempels für dieses Relikt.",objectives={"Bringt das uralte Qirajiartefakt zu den Drachen, die sich nahe des Tempeleingangs versteckt halten."}]])
R(8785,"Die Orgrimmarlegion braucht Mojo!",[[description="Uns liegt eine Anforderung der Orgrimmarlegion vor, die eine Menge recht ungewöhnliche Materialien umfasst. Aber in Anbetracht ihrer jüngsten Leistungen in Silithus, möchten wir dieser Anfrage so schnell wie möglich nachkommen. Beschafft die notwendigen Materialien und bringt sie einer Trollfrau namens Shai.",objectives={"Bringt Schattenpriesterin Shai nahe des Regalschwarmbaus in Silithus 6 Einheiten mächtiges Mojo, 6 Fläschchen großes Mojo und 8 Öle des Feuerbrandes. Ihr benötigt auch Logistikeinsatz IV, um diese Aufgabe abschließen zu können."}]])
R(8786,"Waffen für den Feldeinsatz",[[description="Die Orgrimmarlegion hatte bereits vor einiger Zeit zusätzliche Waffen angefordert, die wir bisher noch nicht liefern konnten. Beschafft die notwendigen Waffen und bringt sie zu Merok Langschreiter außerhalb des Regalschwarmbaus.",objectives={"Bring 3 massive Eisenäxte zu Merok Langschreiter im Lager der Orgrimmarlegion außerhalb des Regalschwarmbaus. Ihr benötigt auch Logistikeinsatz VI, um diese Aufgabe abschließen zu können."}]])
R(8787,"Rüstungssets für den Feldeinsatz",[[description="Die Orgrimmarlegion ist zu unserer Unterstützung in Silithus eingetroffen. Unglücklicherweise hat sie auf dem Weg hierher die meisten ihrer Rüsstungssets eingebüßt. Beschafft eine Ladung und bringt sie zu Merok Langschreiter im Lager der Orgrimmarlegion.",objectives={"Bringt 8 unverwüstliche Rüstungssets und 8 schwere Rüstungsset zu Merok Langschreiter nahe des Regalschwarmbaus. Ihr benötigt auch Logistikeinsatz VII, um diese Aufgabe abschließen zu können."}]])
R(8788,"Ein leicht geschütteltes Geschenk")
R(8789,"Imperiale Qirajiwaffen",[[description="Wir haben hier nicht ein Jahrtausend in völliger Untätigkeit verbracht, $n. Wir sahen mit eigenen Augen, wie sich diese Biester an ihren eigenen Artgenossen gütlich taten, nachdem diese ihre Nützlichkeit für den Schwarm verloren hatten. Wir lauschten, als sie ihre Pläne schmiedeten, diese Welt in Schutt und Asche zu legen. Und wir lernten, wie sich Verrat und Missgunst in ihren Reihen ausbreiten.$B$BSie haben Schwächen und wir wissen nun, wie wir diese zu unserem Vorteil nutzen können.$B$BFindet und bringt mir ihre Zeremonienwaffen. Zusammen, mit dem durch ihren Gott erschaffenen Element, werden wir daraus mächtige Instrumente der Zerstörung erschaffen.",objectives={"Arygos im Tempel von Ahn'Qiraj wird Euch mit Elementium erfüllte Ausrüstung herstellen, wenn Ihr ihm imperiale Qirajiwaffen und 3 Elementiumblöcke bringt."}]])
R(8790,"Imperiale Qirajiinsignien",[[description="Arygos hat die Theorie aufgestellt, dass das Element, welches während des Konflikts zwischen den Alten Göttern und ihren Anhängern entstanden ist, unter den richtigen Bedingungen für sie tödlich ist. Ich spreche vom Elementium, $G Sterblicher : Sterbliche;.$B$BFindet und bringt mir imperiale Qirajiinsignien sowie das giftige Element, dann werde ich Euch Waffen von größter Macht erschaffen!",objectives={"Merithra des Traums im Tempel von Ahn'Qiraj wird Euch mit Elementium erfüllte Ausrüstung herstellen. Bringt ihr dazu imperiale Qirajiinsignien und 3 Elementiumblöcke."}]])
R(8791,"Der Untergang von Ossirian",[[description="Eine schreckliche Bedrohung hat ihr Ende gefunden. Der grausame Ossirian existiert nicht mehr.$B$BDie Bewohner Kalimdors werden aufatmen, wenn sie von diesem glorreichen Sieg erfahren. Nehmt Ossirians Kopf und bringt ihn zu Kommandant Mar'alith auf Burg Cenarius.",objectives={"Bringt den Kopf von Ossirian dem Narbenlosen zu Kommandant Mar'alith auf Burg Cenarius in Silithus."}]])
R(8792,"Die Horde braucht Euch!",[[description="Hallo, schön das Ihr Euch entschieden habt, mir zuzuhören, was ich zu sagen habe. Die Horde braucht jede Hilfe, die sie kriegen kann, um sich auf den Krieg in Ahn'Qiraj vorzubereiten. Die Horde braucht Euch! Während wir uns unterhalten, haben die offiziellen Sammler bereits damit begonnen, kriegstaugliche Materialien aller Art zu sammeln. Doch ohne Eure Mithilfe sind all diese Mühen vergebens, $N! Wir brauchen Eure Unterstützung!$B$BAm besten unterhaltet Ihr Euch mit dem verantwortlichen Offizier, Kriegsherr Gorchuk. Können wir auf Euch zählen, $C? Werdet Ihr uns bei den Kriegsvorbereitungen zur Seite stehen?",objectives={"Sprecht mit Kriegsherr Gorchuk im Tal der Geister in Orgrimmar."}]])
