R(9412,"<UNUSED>Crystal Flake Throat Lozenge")
R(9413,"<UNUSED>Crystal Flake Throat Lozenge")
R(9414,"<UNUSED>Infused Bandages")
R(9415,"Meldung bei Marschall Bluewall",[[description="Gehört Ihr zu Marschall Bluewalls neuen Rekruten? Natürlich.$b$bAuf was wartet Ihr noch? Gute Soldaten verlieren ihr Leben in der Wüste. Freut es Euch nicht, bald dazuzugehören?$b$bLos jetzt, macht Euch auf den Weg... und trocknet dabei nicht aus.",objectives={"Sprecht mit Marschall Bluewall beim Lager der Allianz in der Nähe des Zoraschwarmbaus."}]])
R(9416,"Meldung bei General Kirika",[[description="Ihr müsst zu General Kirikas neuen Rekruten gehören. Es wurde Zeit, dass Ihr kommt. Der Truppenverschleiß in der Wüste ist hoch.$b$bDie Zwerge haben tagtäglich Verstärkung bekommen, wir können es uns nicht leisten in unserem Kampf um Ressourcen in Silithus an Boden zu verlieren.$b$bLasst Euch vom General weitere Anweisungen geben. Ich muss Euch Rekruten lediglich finden, nicht ausbilden.",objectives={"Sprecht mit General Kirika beim Lager der Horde in der Nähe des Regalschwarmbaus."}]])
R(9419,"Durchkämmen der Wüste",[[description="Wir hatten vor Kurzem herausgefunden, dass die Horde die Wüste von Silithus nach Ressourcen abgesucht hat, schenkten dem Ganzen aber keine besondere Beachtung. Wir dachten, es wäre die Sache nicht wert, eine größere Anzahl von Soldaten in dieser Bruthitze zu stationieren.$b$bWie dem auch sei, wir haben die Wichtigkeit dieser Ressourcen erkannt und versuchen nun, um jeden Preis aufzuholen.$b$bWenn Ihr uns unterstützen wollt, müsst Ihr in die Wüste gehen, dort nach Silithyst suchen und diesen anschließend hierher bringen.",objectives={"Findet Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit Marschall Bluewall beim Lager der Allianz in der Nähe des Zoraschwarmbaus."}]])
R(9422,"Durchkämmen der Wüste",[[description="Wir haben die Wüste von Silithus bereits seit einiger Zeit nach Kristallressourcen durchkämmt. Die einzigen Gefahren, die sich uns dabei in den Weg gestellt haben, waren die Kreaturen, die dort heimisch sind, sowie Sand, Staub und Hitze.$b$bDie Allianz scheint nun aber Wind von unserem Unterfangen bekommen zu haben. Ein Rennen hat begonnen. Ein Rennen um die natürlichen Ressourcen und um deren Verteidigung.$b$bWir brauchen jede helfende Hand, die wir bekommen können. Ich hoffe Ihr werdet uns unterstützen.",objectives={"Findet Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit General Kirika beim Lager der Horde in der Nähe des Regalschwarmbaus."}]])
